class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases: numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // All other even numbers are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For polynomials with even number of coefficients (odd degree),
        // there's guaranteed to be at least one real root

        // First, handle edge case: constant polynomial (degree 0)
        if (xs.size() <= 1) {
            return 0.0; // or throw exception, but examples suggest non-constant
        }

        // Find appropriate search bounds by checking sign changes
        double left = -100.0;
        double right = 100.0;

        // Expand bounds until we find a sign change
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 2;
            right *= 2;
            // Safety limit to prevent infinite loops
            if (Math.abs(left) > 1e6) {
                // Fallback: try to find any sign change in smaller increments
                left = -10.0;
                right = 10.0;
                break;
            }
        }

        // Binary search for root
        for (int iteration = 0; iteration < 100; iteration++) {
            double mid = (left + right) / 2.0;
            double valueAtMid = poly(xs, mid);

            if (Math.abs(valueAtMid) < 1e-12) {
                return mid;
            }

            double valueAtLeft = poly(xs, left);
            if (valueAtLeft * valueAtMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Return midpoint of final interval
        return (left + right) / 2.0;
    }
}

