class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Check F(0) = 0 - not prime
        // Check F(1) = 1 - not prime
        // Start with F(2) = 1 - not prime

        while (true) {
            long next = a + b;
            a = b;
            b = next;

            // Skip 1 as it's not prime
            if (next == 1) {
                continue;
            }

            if (isPrime((int)next)) {
                count++;
                if (count == n) {
                    return (int)next;
                }
            }

            // Safety check for overflow (though problem constraints likely limit n)
            if (next > Integer.MAX_VALUE) {
                break;
            }
        }

        throw new RuntimeException("Failed to find " + n + "-th Fibonacci prime");
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

