class Solution {
    public double findZero(List<Double> xs) {
        // Newton-Raphson method
        double x = 1.0; // initial guess

        // Newton's method iterations
        for (int iter = 0; iter < 100; iter++) {
            double fx = poly(xs, x);

            // Compute derivative: f'(x) = sum(i * xs[i] * x^(i-1))
            double fpx = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fpx += i * xs.get(i) * Math.pow(x, i - 1);
            }

            // If derivative is too small, avoid division by zero
            if (Math.abs(fpx) < 1e-10) {
                // Try perturbing x slightly
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check convergence
            if (Math.abs(xNext - x) < 1e-10) {
                return xNext;
            }

            x = xNext;
        }

        return x;
    }
}

