class Solution {
    public List<Integer> parseMusic(String string) {
        List<Integer> result = new ArrayList<>();
        if (string == null || string.isEmpty()) {
            return result;
        }

        String[] tokens = string.trim().split("\\s+");

        for (String token : tokens) {
            switch (token) {
                case "o":
                    result.add(4);
                    break;
                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // According to the problem, input should only contain these tokens.
                    // But to be safe, skip or throw? The problem doesn't specify error handling.
                    // Since it's a coding challenge, assume valid input.
                    break;
            }
        }

        return result;
    }
}

