class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For odd-degree polynomials (even number of coefficients), there's always at least one real root
        // Use bisection method with expanding search bounds

        // Check basic conditions
        if (xs == null || xs.size() == 0) {
            throw new IllegalArgumentException("Polynomial must have at least one coefficient");
        }
        if (xs.size() % 2 == 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Ensure the polynomial is actually of odd degree (leading coefficient non-zero)
        // Find the highest non-zero coefficient
        int n = xs.size();
        int leadingIndex = -1;
        for (int i = n - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-15) {
                leadingIndex = i;
                break;
            }
        }

        if (leadingIndex == -1) {
            throw new IllegalArgumentException("All coefficients are zero");
        }

        // If degree is even, there might not be a real root, but problem states even number of coefficients
        // guarantees solution - note: even number of coefficients means degree = n-1 is odd
        // So we should check that leadingIndex is odd (degree is odd)
        if (leadingIndex % 2 == 0) {
            // This shouldn't happen given the problem constraints, but handle it
            throw new IllegalArgumentException("Polynomial must have odd degree for guaranteed solution");
        }

        // Bisection method with expanding interval
        double left = -1.0;
        double right = 1.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand interval until we find opposite signs
        int expansionCount = 0;
        while (fLeft * fRight > 0 && expansionCount < 50) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            expansionCount++;
        }

        // If still same sign, use a fallback: just search for sign change in a wider range
        if (fLeft * fRight > 0) {
            // Try searching for sign changes
            left = -100.0;
            right = 100.0;
            double step = 1.0;

            // Find two points with opposite signs
            double prevX = left;
            double prevF = poly(xs, left);

            for (double x = left + step; x <= right; x += step) {
                double currF = poly(xs, x);
                if (prevF * currF <= 0) {
                    left = prevX;
                    right = x;
                    break;
                }
                prevX = x;
                prevF = currF;
            }

            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives precision ~1e-30
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-15) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

import java.util.*;
