class Solution {
    /**
    This function takes a list l and returns a list l' such that
    l' is identical to l in the indices that are not divisible by three, while its values at the indices that are divisible by three are equal
    to the values of the corresponding indices of l, but sorted.
    >>> sortThird(Arrays.asList(1, 2, 3))
    [1, 2, 3]
    >>> sortThird(Arrays.asList(5, 6, 3, 4, 8, 9, 2))
    [2, 6, 3, 4, 8, 9, 5]
     */
    public List<Integer> sortThird(List<Integer> l) {
        // Create a copy of the original list to avoid modifying input
        List<Integer> result = new ArrayList<>(l);

        // Collect elements at indices divisible by 3
        List<Integer> elementsToSort = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 3) {
            elementsToSort.add(l.get(i));
        }

        // Sort these elements
        Collections.sort(elementsToSort);

        // Place sorted elements back at their respective positions
        int sortedIndex = 0;
        for (int i = 0; i < result.size(); i += 3) {
            result.set(i, elementsToSort.get(sortedIndex++));
        }

        return result;
    }
}

