     */
    public List<Integer> sortEven(List<Integer> l) {
        if (l == null || l.size() <= 1) {
            return l;
        }

        // Extract values at even indices (0, 2, 4, ...)
        List<Integer> evenValues = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 2) {
            evenValues.add(l.get(i));
        }

        // Sort the even-indexed values
        Collections.sort(evenValues);

        // Create result list and place sorted even values back at even indices
        List<Integer> result = new ArrayList<>(l);
        int evenIndex = 0;
        for (int i = 0; i < result.size(); i += 2) {
            result.set(i, evenValues.get(evenIndex++));
        }

        return result;
    }
}

