class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Start generating Fibonacci numbers from F(3) = 2 onwards
        // We'll track: prev = F(k-1), curr = F(k)
        int prev = 1;  // F(2) = 1
        int curr = 2;  // F(3) = 2

        // Count how many prime Fibonacci numbers we've found
        int count = 0;

        // Check if 2 is prime (it is)
        if (isPrime(curr)) {
            count++;
            if (count == n) {
                return curr;
            }
        }

        // Continue generating Fibonacci numbers
        while (true) {
            int next = prev + curr;
            prev = curr;
            curr = next;

            if (isPrime(curr)) {
                count++;
                if (count == n) {
                    return curr;
                }
            }
        }
    }

    // Helper method to check if a number is prime
    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

