class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Edge case: empty substring should return 0
        if (substring.isEmpty()) {
            return 0;
        }

        int count = 0;
        // We can only start checking up to string.length() - substring.length()
        // But if substring is longer than string, the loop won't execute anyway
        for (int i = 0; i <= string.length() - substring.length(); i++) {
            if (string.startsWith(substring, i)) {
                count++;
            }
        }
        return count;
    }
}

