class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Ensure even number of coefficients
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Find the largest non-zero coefficient for scaling/initial guess
        double maxCoeff = 0;
        for (double coeff : xs) {
            if (Math.abs(coeff) > maxCoeff) {
                maxCoeff = Math.abs(coeff);
            }
        }

        // Newton-Raphson method
        double x = maxCoeff > 0 ? maxCoeff / 2.0 : 1.0; // Initial guess

        for (int i = 0; i < 100; i++) { // Max iterations
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative
            double fpx = polyDerivative(xs, x);

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-12) {
                // Try a different starting point if derivative is too small
                x = (i % 2 == 0) ? x + 1.0 : x - 1.0;
                continue;
            }

            double newX = x - fx / fpx;

            // Check convergence
            if (Math.abs(newX - x) < 1e-10) {
                return newX;
            }

            x = newX;
        }

        // Fallback: if Newton-Raphson didn't converge, try bisection
        // For odd-degree polynomials, we know there's a root somewhere
        double left = -maxCoeff - 1;
        double right = maxCoeff + 1;

        // Expand bounds until we find sign change
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 2;
            right *= 2;
            // Safety check to prevent infinite loop
            if (Math.abs(left) > 1e9) {
                break;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fmid = poly(xs, mid);

            if (Math.abs(fmid) < 1e-10 || (right - left) < 1e-10) {
                return mid;
            }

            if (poly(xs, left) * fmid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2;
    }

    // Helper method to compute polynomial derivative
    private double polyDerivative(List<Double> xs, double x) {
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += xs.get(i) * i * Math.pow(x, i - 1);
        }
        return result;
    }
}

