class Solution {
    /**
     * Check if in given list of numbers, are any two numbers closer to each other than given threshold.
     *
     * @param numbers the list of numbers to check
     * @param threshold the minimum distance threshold (must be non-negative)
     * @return true if any two numbers are closer than the threshold, false otherwise
     * @throws IllegalArgumentException if threshold is negative
     * @throws NullPointerException if numbers is null
     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        // Item 49: Check parameters for validity
        if (numbers == null) {
            throw new NullPointerException("numbers cannot be null");
        }

        if (threshold < 0) {
            throw new IllegalArgumentException("threshold must be non-negative, got " + threshold);
        }

        // If fewer than 2 elements, no pair exists
        if (numbers.size() < 2) {
            return false;
        }

        // Create a copy to avoid modifying the original list (Item 50: defensive copy)
        List<Double> sortedNumbers = new ArrayList<>(numbers);
        Collections.sort(sortedNumbers);

        // Check adjacent pairs - after sorting, closest elements are adjacent
        for (int i = 0; i < sortedNumbers.size() - 1; i++) {
            double diff = Math.abs(sortedNumbers.get(i + 1) - sortedNumbers.get(i));
            if (diff < threshold) {
                return true;
            }
        }

        return false;
    }
}

