     * Insert a number {@code delimiter} between every two consecutive elements of input list {@code numbers}.
     *
     * @param numbers the list of integers to intersperse; must not be null
     * @param delimiter the integer value to insert between elements
     * @return a new list with the delimiter inserted between each pair of consecutive elements;
     *         returns an empty list if input is empty or has only one element
     * @throws NullPointerException if {@code numbers} is null
     *
     * <p>Examples:
     * <pre>{@code
     * intersperse(List.of(), 4)        // returns []
     * intersperse(Arrays.asList(1, 2, 3), 4)  // returns [1, 4, 2, 4, 3]
     * }</pre>
     */
    public List<Integer> intersperse(List<Integer> numbers, int delimiter) {
        // Item 49: Check parameters for validity - validate that numbers is not null
        Objects.requireNonNull(numbers, "numbers must not be null");

        // If the list has 0 or 1 elements, no insertion needed
        if (numbers.size() <= 1) {
            return new ArrayList<>(numbers);
        }

        // Create result list with appropriate capacity to avoid resizing
        // For n elements, we'll have n + (n-1) = 2n-1 elements total
        List<Integer> result = new ArrayList<>(2 * numbers.size() - 1);

        // Item 54: Return empty collections, not null - always return a valid list
        // Iterate through the original list and insert delimiter between elements
        for (int i = 0; i < numbers.size(); i++) {
            result.add(numbers.get(i));
            // Add delimiter after each element except the last one
            if (i < numbers.size() - 1) {
                result.add(delimiter);
            }
        }

        return result;
    }
}

