class Solution {
    /**
     * Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
     * For each of the group, output the deepest level of nesting of parentheses.
     * E.g. (()()) has maximum two levels of nesting while ((())) has three.
     *
     * @param paren_string string containing space-separated groups of parentheses
     * @return list of integers representing the maximum nesting depth for each group
     * @throws IllegalArgumentException if paren_string is null
     */
    public List<Integer> parseNestedParens(String paren_string) {
        // Check parameter for validity (Item 49)
        if (paren_string == null) {
            throw new IllegalArgumentException("Input string cannot be null");
        }

        // Handle empty string case - return empty list (Item 54)
        if (paren_string.trim().isEmpty()) {
            return Collections.emptyList();
        }

        // Split by spaces to get individual groups
        String[] groups = paren_string.trim().split("\\s+");
        List<Integer> result = new ArrayList<>(groups.length);

        for (String group : groups) {
            int depth = 0;
            int maxDepth = 0;

            for (int i = 0; i < group.length(); i++) {
                char c = group.charAt(i);
                if (c == '(') {
                    depth++;
                    maxDepth = Math.max(maxDepth, depth);
                } else if (c == ')') {
                    depth--;
                }
            }

            result.add(maxDepth);
        }

        return result;
    }
}

