     * 
     * @param a first binary string (must contain only '0' and '1')
     * @param b second binary string (must contain only '0' and '1')
     * @return XOR result as a binary string
     * @throws IllegalArgumentException if inputs are null, have different lengths, 
     *         or contain characters other than '0' and '1'
     */
    public String stringXor(String a, String b) {
        // Validate inputs (Item 49: Check parameters for validity)
        if (a == null || b == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        if (a.length() != b.length()) {
            throw new IllegalArgumentException("Input strings must have the same length");
        }

        // Validate that strings contain only '0' and '1'
        for (int i = 0; i < a.length(); i++) {
            char ca = a.charAt(i);
            char cb = b.charAt(i);
            if ((ca != '0' && ca != '1') || (cb != '0' && cb != '1')) {
                throw new IllegalArgumentException("Strings must contain only '0' and '1'");
            }
        }

        // If both strings are empty, return empty string
        if (a.length() == 0) {
            return "";
        }

        // Perform XOR operation using StringBuilder for efficiency (Item 64)
        StringBuilder result = new StringBuilder(a.length());
        for (int i = 0; i < a.length(); i++) {
            char ca = a.charAt(i);
            char cb = b.charAt(i);
            // XOR: same bits give 0, different bits give 1
            if (ca == cb) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

