class Solution {
    /**
    Out of list of strings, return the longest one. Return the first one in case of multiple
    strings of the same length. Return None in case the input list is empty.
    >>> longest(List.of())
    Optional.empty
    >>> longest(Arrays.asList("a", "b", "c"))
    Optional[a]
    >>> longest(Arrays.asList("a", "bb", "ccc"))
    Optional[ccc]
     */
    public Optional<String> longest(List<String> strings) {
        // Check for null input (Item 49: Check parameters for validity)
        if (strings == null) {
            return Optional.empty();
        }

        // If the list is empty, return empty Optional (Item 54)
        if (strings.isEmpty()) {
            return Optional.empty();
        }

        String longest = strings.get(0);

        // Iterate through the list to find the longest string
        // In case of tie, keep the first one (so we don't replace equal-length strings)
        for (int i = 1; i < strings.size(); i++) {
            String current = strings.get(i);
            if (current.length() > longest.length()) {
                longest = current;
            }
        }

        return Optional.of(longest);
    }
}

