     * @param string the string to search in
     * @param substring the substring to search for
     * @return the number of occurrences of substring in string, including overlapping matches
     */
    public int howManyTimes(String string, String substring) {
        // Handle edge cases as per Item 49: check parameters for validity
        if (string == null || substring == null) {
            return 0;
        }

        // If substring is empty, return 0 (no meaningful match)
        if (substring.isEmpty()) {
