class Solution {
    /**
     * Input is a space-delimited string of numerals from 'zero' to 'nine'.
     * Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
     * Return the string with numbers sorted from smallest to largest.
     * 
     * @param numbers space-delimited string of number words
     * @return space-delimited string with numbers sorted ascending, or empty string if input is null/empty
     * @throws IllegalArgumentException if any token is not a valid number word
     */
    public String sortNumbers(String numbers) {
        // Item 49: Check parameters for validity
        if (numbers == null) {
            return "";
        }

        // Trim and split - handle empty string case
        String[] tokens = numbers.trim().split("\\s+");
        if (tokens.length == 0 || (tokens.length == 1 && tokens[0].isEmpty())) {
            return "";
        }

        // Create mapping from word to numeric value
        Map<String, Integer> wordToNum = new HashMap<>();
        wordToNum.put("zero", 0);
        wordToNum.put("one", 1);
        wordToNum.put("two", 2);
        wordToNum.put("three", 3);
        wordToNum.put("four", 4);
        wordToNum.put("five", 5);
        wordToNum.put("six", 6);
        wordToNum.put("seven", 7);
        wordToNum.put("eight", 8);
        wordToNum.put("nine", 9);

        // Create reverse mapping for conversion back to words
        String[] numWords = {"zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"};

        // Validate and collect values
        List<Integer> values = new ArrayList<>();
        for (String token : tokens) {
            if (!wordToNum.containsKey(token)) {
                throw new IllegalArgumentException("Invalid number word: '" + token + "'");
            }
            values.add(wordToNum.get(token));
        }

        // Sort the values
        Collections.sort(values);

        // Convert back to words and join
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < values.size(); i++) {
            if (i > 0) {
                result.append(" ");
            }
            result.append(numWords[values.get(i)]);
        }

        return result.toString();
    }
}

