class Solution {
    public List<Double> findClosestElements(List<Double> numbers) {
        // Check parameters for validity (Item 49)
        if (numbers == null) {
            throw new IllegalArgumentException("Input list cannot be null");
        }

        if (numbers.size() < 2) {
            throw new IllegalArgumentException("List must contain at least two elements");
        }

        // Create a copy to avoid modifying the original list (Item 50)
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        double minDiff = Double.MAX_VALUE;
        int index1 = 0;
        int index2 = 1;

        // Find the pair with minimum difference (only need to check adjacent pairs after sorting)
        for (int i = 0; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < minDiff) {
                minDiff = diff;
                index1 = i;
                index2 = i + 1;
            }
        }

        // Return in order: smaller number first, larger number second
        double num1 = sorted.get(index1);
        double num2 = sorted.get(index2);

        if (num1 <= num2) {
            return Arrays.asList(num1, num2);
        } else {
            return Arrays.asList(num2, num1);
        }
    }
}

