class Solution {
    /**
     * Given list of numbers (of at least two elements), apply a linear transform to that list,
     * such that the smallest number will become 0 and the largest will become 1.
     * 
     * @param numbers list of Double values (must contain at least 2 elements)
     * @return a new list with normalized values between 0 and 1
     * @throws IllegalArgumentException if input list is null, empty, or has fewer than 2 elements
     * @throws ArithmeticException if all values are the same (division by zero)
     */
    public List<Double> rescaleToUnit(List<Double> numbers) {
        // Check for null input
        if (numbers == null) {
            throw new IllegalArgumentException("Input list cannot be null");
        }

        // Check for sufficient size
        if (numbers.size() < 2) {
            throw new IllegalArgumentException("Input list must contain at least 2 elements");
        }

        // Find min and max values
        double min = Double.MAX_VALUE;
        double max = Double.MIN_VALUE;

        for (Double num : numbers) {
            // Handle null elements in the list
            if (num == null) {
                throw new IllegalArgumentException("List cannot contain null elements");
            }

            if (num < min) {
                min = num;
            }
            if (num > max) {
                max = num;
            }
        }

        // Handle case where all values are the same (min == max)
        if (min == max) {
            throw new ArithmeticException("Cannot rescale: all values are identical");
        }

        // Create result list
        List<Double> result = new ArrayList<>(numbers.size());

        // Apply normalization
        double range = max - min;
        for (Double num : numbers) {
            result.add((num - min) / range);
        }

        return result;
    }
}

