class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Check parameters for validity (Item 49)
        if (n <= 1) {
            throw new IllegalArgumentException("n must be greater than 1");
        }

        // Start checking from n/2 downwards - the largest proper divisor cannot exceed n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // This should never be reached for n > 1, as 1 always divides n
        return 1;
    }
}

