class Solution {
    /**
     * Return list of prime factors of given integer in the order from smallest to largest.
     * Each of the factors should be listed number of times corresponding to how many times it appears in factorization.
     * Input number should be equal to the product of all factors.
     *
     * @param n the integer to factorize (must be >= 2)
     * @return list of prime factors in ascending order; empty list for n < 2
     * @see <a href="https://en.wikipedia.org/wiki/Integer_factorization">Integer factorization</a>
     */
    public List<Integer> factorize(int n) {
        List<Integer> factors = new ArrayList<>();

        // Handle edge cases: numbers less than 2 have no prime factors
        if (n < 2) {
            return factors;
        }

        // Check for factor 2 separately to optimize the loop below
        while (n % 2 == 0) {
            factors.add(2);
            n /= 2;
        }

        // Now check odd factors starting from 3
        for (int i = 3; i * i <= n; i += 2) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }

        // If n is still greater than 1, then it's a prime factor itself
        if (n > 1) {
            factors.add(n);
        }

        return factors;
    }
}

