class Solution {
    public double findZero(List<Double> xs) {
            // Validate input: must have even number of coefficients
            if (xs == null || xs.size() < 2 || xs.size() % 2 != 0) {
                throw new IllegalArgumentException("List must have even number of coefficients");
            }

            // For linear case (2 coefficients): a + bx = 0 -> x = -a/b
            if (xs.size() == 2) {
                double a = xs.get(0);
                double b = xs.get(1);
                if (Math.abs(b) < 1e-15) {
                    throw new IllegalArgumentException("Coefficient of x cannot be zero for linear equation");
                }
                return -a / b;
            }

            // Newton-Raphson method
            double x = 1.0; // initial guess
            double tolerance = 1e-10;
            int maxIterations = 1000;

            for (int i = 0; i < maxIterations; i++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < tolerance) {
                    return x;
                }

                // Compute derivative: f'(x)
                double fpx = 0.0;
                for (int j = 1; j < xs.size(); j++) {
                    fpx += xs.get(j) * j * Math.pow(x, j - 1);
                }

                // Avoid division by zero
                if (Math.abs(fpx) < 1e-15) {
                    // Try a different starting point or use bisection fallback
                    x = x + 0.1;
                    continue;
                }

                double xNext = x - fx / fpx;

                // Check for convergence
                if (Math.abs(xNext - x) < tolerance) {
                    // Verify it's actually a root
                    if (Math.abs(poly(xs, xNext)) < tolerance) {
                        return xNext;
                    }
                }

                x = xNext;
            }

            // If we get here, try bisection as fallback
            // Find an interval [a, b] where f(a)*f(b) < 0
            double a = -100.0, b = 100.0;
            double fa = poly(xs, a);
            double fb = poly(xs, b);

            // Expand interval if needed
            int expandAttempts = 0;
            while (fa * fb > 0 && expandAttempts < 20) {
                a *= 2;
                b *= 2;
                fa = poly(xs, a);
                fb = poly(xs, b);
                expandAttempts++;
            }

            if (fa * fb <= 0) {
                // Bisection method
                for (int i = 0; i < 100; i++) {
                    double mid = (a + b) / 2;
                    double fmid = poly(xs, mid);
                    if (Math.abs(fmid) < 1e-10) {
                        return mid;
                    }
                    if (fa * fmid <= 0) {
                        b = mid;
                        fb = fmid;
                    } else {
                        a = mid;
                        fa = fmid;
                    }
                }
                return (a + b) / 2;
            }

            // Last resort: return the best approximation from Newton
            return x;
        }
}

