class Solution {
    /**
     * Returns the n-th number that is both a Fibonacci number and prime.
     * 
     * @param n the position (1-indexed) of the Fibonacci prime to return
     * @return the n-th Fibonacci prime
     * @throws IllegalArgumentException if n is less than 1
     */
    public int primeFib(int n) {
        // Item 49: Check parameters for validity
        if (n < 1) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0;  // F(0)
        long b = 1;  // F(1)

        // Handle special case: 2 is the first Fibonacci prime
        if (n == 1) {
            return 2;
        }

        // Generate Fibonacci numbers and check for primality
        while (true) {
            long next = a + b;
            a = b;
            b = next;

            // Skip 0 and 1 as they're not prime
            if (next < 2) {
                continue;
            }

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return (int) next;
                }
            }
        }
    }

    // Helper method to check if a number is prime
    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

