class Solution {
    public String makePalindrome(String string) {
        // Handle null or empty string
        if (string == null || string.length() <= 1) {
            return string != null ? string : "";
        }

        // Find the longest palindromic suffix
        for (int i = 0; i < string.length(); i++) {
            // Check if substring from i to end is a palindrome
            if (isPalindrome(string.substring(i))) {
                // If yes, append the reverse of the prefix (substring from 0 to i)
                String prefix = string.substring(0, i);
                StringBuilder sb = new StringBuilder(string);
                sb.append(new StringBuilder(prefix).reverse());
                return sb.toString();
            }
        }

        // This should never be reached since at least the last character is always a palindrome
        return string;
    }
}

