class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: constant polynomial (shouldn't happen with even coefficients >= 2)
        if (xs.size() < 2) {
            throw new IllegalArgumentException("Polynomial must have at least 2 coefficients");
        }

        // Find the leading coefficient (largest index with non-zero value)
        int n = xs.size() - 1;
        int leadIndex = -1;
        for (int i = n; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) {
                leadIndex = i;
                break;
            }
        }

        if (leadIndex == -1) {
            throw new IllegalArgumentException("All coefficients are zero");
        }

        // For odd degree polynomials (even number of coefficients), there's always at least one real root
        // We'll use bisection method on a sufficiently large interval
        double left = -10000.0;
        double right = 10000.0;

        // Adjust interval to ensure sign change
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If no sign change, expand interval
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 20) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // enough iterations for precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

