            if (isPalindrome(string.substring(i))) {
                // If yes, take the prefix before i and append its reverse
                String prefix = string.substring(0, i);
                return string + new StringBuilder(prefix).reverse().toString();
            }
        }

        // This should never be reached since single char is always palindrome
        return string + string.charAt(0);
    }
}

