                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // For invalid notes, could throw exception or skip
                    // Based on problem statement, we assume valid input
                    break;
            }
        }

        return result;
    }
}

