class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true; // 2 and 3 are prime
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check for divisors from 5 to sqrt(n), skipping even numbers
        // Use the optimization that all primes > 3 are of form 6k ± 1
        int i = 5;
        while (i * i <= n) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
            i += 6;
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // For linear case: a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (b != 0) {
                return -a / b;
            }
        }

        // Newton-Raphson method
        double x = 1.0; // initial guess
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            // Calculate f(x) and f'(x)
            double fx = poly(xs, x);

            // If we found a root within tolerance, return it
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Calculate derivative numerically or analytically
            // Let's calculate derivative analytically
            double fPrimeX = 0;
            for (int j = 1; j < xs.size(); j++) {
                fPrimeX += j * xs.get(j) * Math.pow(x, j - 1);
            }

            // Avoid division by zero
            if (Math.abs(fPrimeX) < 1e-15) {
                // Try a different initial guess or use bisection
                x += 0.5; // shift slightly
                continue;
            }

            double xNew = x - fx / fPrimeX;

            // Check for convergence
            if (Math.abs(xNew - x) < tolerance) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNew)) < tolerance) {
                    return xNew;
                }
            }

            x = xNew;
        }

        // Fallback: if Newton-Raphson fails, try bisection with a wide range
        // Try to find an interval [a, b] where f(a)*f(b) < 0
        double a = -1000.0;
        double b = 1000.0;
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Expand search range until we find sign change
        while (fa * fb > 0 && (b - a) < 1000000) {
            a *= 2;
            b *= 2;
            fa = poly(xs, a);
            fb = poly(xs, b);
        }

        // Bisection method
        if (fa * fb <= 0) {
            for (int i = 0; i < 100; i++) {
                double mid = (a + b) / 2;
                double fm = poly(xs, mid);
                if (Math.abs(fm) < tolerance || (b - a) / 2 < tolerance) {
                    return mid;
                }
                if (fa * fm <= 0) {
                    b = mid;
                    fb = fm;
                } else {
                    a = mid;
                    fa = fm;
                }
            }
        }

        // Last resort: return the last x from Newton-Raphson
        return x;
    }
}

