class Solution {
    public double findZero(List<Double> xs) {
        // Create a lambda for the polynomial evaluation
        java.util.function.DoubleUnaryOperator polyFunc = x -> poly(xs, x);

        // For odd-degree polynomials, we know lim_{x->-inf} = -inf and lim_{x->+inf} = +inf
        // (or vice versa depending on leading coefficient sign)
        // So we can find an interval [a, b] where f(a) * f(b) < 0

        double a = -1000.0;
        double b = 1000.0;

        // Adjust bounds if needed - expand until we find sign change
        double fa = polyFunc.applyAsDouble(a);
        double fb = polyFunc.applyAsDouble(b);

        int iterations = 0;
        while (fa * fb > 0 && iterations < 10) {
            a *= 10;
            b *= 10;
            fa = polyFunc.applyAsDouble(a);
            fb = polyFunc.applyAsDouble(b);
            iterations++;
        }

        // If still no sign change, fallback to starting at origin
        if (fa * fb > 0) {
            a = -10.0;
            b = 10.0;
            fa = polyFunc.applyAsDouble(a);
            fb = polyFunc.applyAsDouble(b);
            if (fa * fb > 0) {
                a = -1.0;
                b = 1.0;
                fa = polyFunc.applyAsDouble(a);
                fb = polyFunc.applyAsDouble(b);
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations for precision
            double mid = (a + b) / 2.0;
            double fmid = polyFunc.applyAsDouble(mid);

            if (Math.abs(fmid) < 1e-12) {
                return mid;
            }

            if (fa * fmid <= 0) {
                b = mid;
                fb = fmid;
            } else {
                a = mid;
                fa = fmid;
            }
        }

        return (a + b) / 2.0;
    }
}

