        List<Integer> result = new ArrayList<>(l);

        // Collect elements at indices divisible by 3
        List<Integer> elementsToSort = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 3) {
            elementsToSort.add(l.get(i));
        }

        // Sort the collected elements
        Collections.sort(elementsToSort);

        // Put the sorted elements back at their respective positions
        int sortedIndex = 0;
        for (int i = 0; i < result.size(); i += 3) {
            result.set(i, elementsToSort.get(sortedIndex++));
        }

        return result;
    }
}

