class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Ensure both strings have the same length by padding the shorter one with leading zeros
        // Based on the example, we assume they have the same length, but let's handle edge cases

        int lenA = a.length();
        int lenB = b.length();

        // Pad the shorter string with leading zeros to match lengths
        while (lenA < lenB) {
            a = "0" + a;
            lenA++;
        }
        while (lenB < lenA) {
            b = "0" + b;
            lenB++;
        }

        StringBuilder result = new StringBuilder();

        // XOR each corresponding bit
        for (int i = 0; i < a.length(); i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

