        // The largest proper divisor of n is n divided by its smallest prime factor
        // Check if n is divisible by 2
        if (n % 2 == 0) {
            return n / 2;
        }

        // For odd numbers, check odd divisors from 3 upward
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return n / i;
            }
        }

        // If no divisor found, n is prime, so largest proper divisor is 1
        return 1;
    }
}

import java.util.*;
