class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("Input must be positive");
        }

        int count = 0;
        int a = 0; // F(0)
        int b = 1; // F(1)

        // Handle special case: F(3) = 2 is the first Fibonacci prime
        if (n == 1) {
            return 2;
        }

        // Start generating Fibonacci numbers from F(3) = 2
        // We already know F(0)=0, F(1)=1, F(2)=1 are not prime
        int fib = 2; // F(3)
        int index = 3;

        while (true) {
            if (isPrime(fib)) {
                count++;
                if (count == n) {
                    return fib;
                }
            }

            // Generate next Fibonacci number
            int next = a + b;
            a = b;
            b = fib;
            fib = next;
            index++;
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

