class Solution {
    public double findZero(List<Double> xs) {
            // Create a lambda for evaluating polynomial
            java.util.function.DoubleFunction<Double> polyFunc = (Double x) -> poly(xs, x);

            // For polynomials with odd degree (even number of coefficients),
            // we know there's at least one real root
            // Start with a reasonable search interval
            double left = -1000.0;
            double right = 1000.0;

            // Expand interval until we find sign change
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            int attempts = 0;
            while (fLeft * fRight > 0 && attempts < 30) {
                left *= 10;
                right *= 10;
                fLeft = poly(xs, left);
                fRight = poly(xs, right);
                attempts++;
            }

            // Bisection method
            double tolerance = 1e-9;
            int maxIterations = 100;

            for (int i = 0; i < maxIterations; i++) {
                double mid = (left + right) / 2.0;
                double fMid = poly(xs, mid);

                if (Math.abs(fMid) < tolerance) {
                    return mid;
                }

                if (fLeft * fMid < 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }

            // Return midpoint of final interval
            return (left + right) / 2.0;
        }
}

