class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 0; // F(0)
        int b = 1; // F(1)

        // Check F(3) = 2 first since we start from small Fibonacci numbers
        // We'll iterate through Fibonacci sequence and check for primality

        // Handle the special case: F(3) = 2
        if (n == 1) {
            return 2;
        }

        // Start generating Fibonacci numbers from F(3) onwards
        // We already know F(0)=0, F(1)=1, F(2)=1, F(3)=2
        // Let's start from F(4) = 3

        int fib = 0;
        count = 1; // We've found F(3) = 2 as the first Fibonacci prime

        // Generate Fibonacci numbers starting from F(4) = 3
        int prevFib = 2; // F(3)
        int currFib = 3; // F(4)

        while (true) {
            // Check if current Fibonacci number is prime
            if (isPrime(currFib)) {
                count++;
                if (count == n) {
                    return currFib;
                }
            }

            // Generate next Fibonacci number
            fib = prevFib + currFib;
            prevFib = currFib;
            currFib = fib;
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

