class Solution {
    public double findZero(List<Double> xs) {
            // Find the leading coefficient (last non-zero coefficient)
            int n = xs.size();
            double leadingCoeff = 0.0;
            for (int i = n - 1; i >= 0; i--) {
                if (Math.abs(xs.get(i)) > 1e-12) {
                    leadingCoeff = xs.get(i);
                    break;
                }
            }

            // For polynomials with odd degree, we can find bounds where the sign changes
            // Start with a reasonable range and expand until we get opposite signs
            double left = -1.0;
            double right = 1.0;
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            // Expand bounds until we have opposite signs or reach max iterations
            int expansions = 0;
            int maxExpansions = 100;
            while (fLeft * fRight > 0 && expansions < maxExpansions) {
                if (leadingCoeff > 0) {
                    // As x->+inf, f->+inf; as x->-inf, f->-inf
                    left *= 10;
                    fLeft = poly(xs, left);
                } else {
                    // As x->+inf, f->-inf; as x->-inf, f->+inf
                    right *= 10;
                    fRight = poly(xs, right);
                }
                expansions++;
            }

            // If still same sign, try larger bounds
            if (fLeft * fRight > 0) {
                left = -1e6;
                right = 1e6;
                fLeft = poly(xs, left);
                fRight = poly(xs, right);
            }

            // Use bisection method
            double mid = 0;
            for (int i = 0; i < 100; i++) { // enough iterations for double precision
                mid = (left + right) / 2;
                double fMid = poly(xs, mid);

                if (Math.abs(fMid) < 1e-12) {
                    break;
                }

                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }

            return mid;
        }
}

