class Solution {
    public int fizzBuzz(int n) {
        int count = 0;

        // Check all numbers less than n
        for (int i = 1; i < n; i++) {
            // Check if divisible by 11 or 13
            if (i % 11 == 0 || i % 13 == 0) {
                // Count occurrences of digit 7 in this number
                int num = i;
                while (num > 0) {
                    if (num % 10 == 7) {
                        count++;
                    }
                    num /= 10;
                }
            }
        }

        return count;
    }
}

