class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method to find a root
        // Start with initial guess and iterate until convergence

        // Handle edge case: constant polynomial (degree 0)
        if (xs.size() == 1) {
            // xs[0] = 0? If not, no solution, but problem says solution guaranteed
            return 0.0;
        }

        // Newton-Raphson parameters
        double x = 1.0; // initial guess
        double epsilon = 1e-10;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative: f'(x) = sum(i * xs[i] * x^(i-1))
            double fpx = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fpx += i * xs.get(i) * Math.pow(x, i - 1);
            }

            // Avoid division by zero
            if (Math.abs(fpx) < epsilon) {
                // Try a different initial guess
                x += 1.0;
                continue;
            }

            // Newton-Raphson update: x_new = x - f(x)/f'(x)
            double xNew = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNew - x) < epsilon) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNew)) < epsilon) {
                    return xNew;
                }
            }

            x = xNew;
        }

        // Fallback: if we didn't converge, return the best guess
        return x;
    }
}

