        String[] wordArray = numbers.trim().split("\\s+");

        // Create a list of pairs (word, numeric value) or just sort using custom comparator
        List<String> wordList = new ArrayList<>(Arrays.asList(wordArray));

        // Sort using a custom comparator based on numeric values
        Collections.sort(wordList, (a, b) -> {
            Integer numA = wordToNumber.get(a);
            Integer numB = wordToNumber.get(b);
            return numA.compareTo(numB);
        });

