class Solution {
    public double findZero(List<Double> xs) {
        // For linear case (2 coefficients), solve directly
        if (xs.size() == 2) {
            return -xs.get(0) / xs.get(1);
        }

        // For higher degrees, use Newton-Raphson method
        double x = 0.0; // initial guess

        for (int iter = 0; iter < 100; iter++) {
            double fx = poly(xs, x);

            // If we're close enough to zero, return
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative
            double fpx = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fpx += i * xs.get(i) * Math.pow(x, i - 1);
            }

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-10) {
                // Try a different initial guess if derivative is too small
                x += 0.1;
                continue;
            }

            double xNew = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNew - x) < 1e-10) {
                return xNew;
            }

            x = xNew;
        }

        return x; // return last approximation
    }
}

