        Arrays.sort(words, (a, b) -> {
            Integer valA = wordToDigit.get(a);
            Integer valB = wordToDigit.get(b);
            return valA.compareTo(valB);
        });

        // Join the sorted words back into a string
        return String.join(" ", words);
    }
}

