class Solution {
    public double findZero(List<Double> xs) {
            // Create a function to evaluate polynomial
            double left = -1000.0;
            double right = 1000.0;

            // Expand interval until we find opposite signs
            while (poly(xs, left) * poly(xs, right) > 0) {
                left *= 2;
                right *= 2;
                // Safety check to prevent infinite loops
                if (Math.abs(left) > 1e9) {
                    break;
                }
            }

            // Bisection method
            double mid;
            int iterations = 100; // enough for double precision
            for (int i = 0; i < iterations; i++) {
                mid = (left + right) / 2;
                double fMid = poly(xs, mid);

                if (Math.abs(fMid) < 1e-9) {
                    return mid;
                }

                if (poly(xs, left) * fMid < 0) {
                    right = mid;
                } else {
                    left = mid;
                }
            }

            return (left + right) / 2;
        }
}

