class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Start with first two Fibonacci numbers
        int a = 1;  // F1
        int b = 2;  // F2

        // We'll check starting from 2 (which is already prime)
        if (n == 1) {
            return 2;
        }

        int count = 1;  // We've found 2 already

        // Generate Fibonacci numbers and check for primality
        while (count < n) {
            int next = a + b;
            a = b;
            b = next;

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }
        }

        // Should not reach here if n is valid
        return -1;
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

