class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method to find a root
        // Start with initial guess x = 1.0
        double x = 1.0;

        // Newton-Raphson iteration: x_{n+1} = x_n - f(x_n)/f'(x_n)
        for (int i = 0; i < 100; i++) { // max iterations
            double fx = poly(xs, x);

            // If we're close enough to zero, return
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative at x
            double fpx = derivative(xs, x);

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-10) {
                // Perturb x slightly and try again
                x += 0.1;
                continue;
            }

            double xNew = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNew - x) < 1e-10) {
                return xNew;
            }

            x = xNew;
        }

        // Fallback: return last computed value
        return x;
    }

    // Helper method to compute derivative
    private double derivative(List<Double> coeffs, double x) {
        if (coeffs.size() <= 1) {
            return 0;
        }

        double result = 0;
        for (int i = 1; i < coeffs.size(); i++) {
            result += i * coeffs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

