class Solution {
    public double findZero(List<Double> xs) {
        // Find the highest non-zero coefficient to determine the actual degree
        int n = xs.size() - 1;
        int degree = n;
        while (degree >= 0 && Math.abs(xs.get(degree)) < 1e-12) {
            degree--;
        }

        // Since problem guarantees odd degree (even number of coefficients with leading non-zero)
        // We know degree is odd

        // Evaluate polynomial at large positive and negative values
        double posVal = poly(xs, 1000.0);
        double negVal = poly(xs, -1000.0);

        double left, right;

        // Determine interval where sign changes
        if (posVal > 0 && negVal < 0) {
            left = -1000.0;
            right = 1000.0;
        } else if (posVal < 0 && negVal > 0) {
            left = -1000.0;
            right = 1000.0;
        } else {
            // Expand search range if needed
            double range = 1000.0;
            while ((posVal > 0 && negVal > 0) || (posVal < 0 && negVal < 0)) {
                range *= 2;
                posVal = poly(xs, range);
                negVal = poly(xs, -range);
                left = -range;
                right = range;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives good precision
            double mid = (left + right) / 2;
            double val = poly(xs, mid);

            if (Math.abs(val) < 1e-12) {
                return mid;
            }

            if (poly(xs, left) * val < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2;
    }
}

