class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Edge case: numbers <= 1 have no proper divisors
        if (n <= 1) {
            return -1; // or could throw exception, but returning -1 is common for such cases
        }

        // The largest proper divisor of n is at most n/2
        // Check from n/2 downwards
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // Fallback (shouldn't be reached for n > 1)
    }
}

