        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Find the degree (n-1 for n coefficients)
        int n = xs.size();

        // Find leading coefficient (last non-zero)
        double leading = 0.0;
        for (int i = n - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) {
                leading = xs.get(i);
                break;
            }
        }

        // If constant term only and non-zero, no root, but problem guarantees solution exists
        if (Math.abs(leading) < 1e-12) {
            // All coefficients zero? Then any x works
            return 0.0;
        }

        // Bisection parameters
        double left = -1000.0;
        double right = 1000.0;
        double tolerance = 1e-9;

        // Expand search range until we bracket a root
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 10;
            right *= 10;
            // Safety limit to prevent infinite loop
            if (Math.abs(left) > 1e9) {
                // Fallback: try Newton's method starting from 0
                return newtonMethod(xs, 0.0);
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations should be enough for precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance) {
                return mid;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2.0;
    }

    // Helper method for Newton's method fallback
    private double newtonMethod(List<Double> xs, double x0) {
        double x = x0;
        double tolerance = 1e-9;

        for (int i = 0; i < 50; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative
            double fpx = 0.0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(fpx) < 1e-12) {
                // Derivative too small, fall back to small step
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for divergence
            if (Double.isInfinite(xNext) || Double.isNaN(xNext)) {
                x += 0.1;
            } else {
                x = xNext;
            }
        }

        return x;
    }
}

