        String[] notes = string.trim().split("\\s+");

        for (String note : notes) {
            switch (note) {
                case "o":
                    result.add(4);
                    break;
                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // Handle unexpected notes - could throw exception or skip
                    // For robustness, we'll just skip or could add error handling
                    break;
            }
        }

        return result;
    }
}

