class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        // We only need to check up to sqrt(n) because if n = a * b and a <= b,
        // then a * a <= n, so a <= sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Newton-Raphson method
        // Start with an initial guess
        double x = 1.0;

        // Derivative coefficients: if original is [a0, a1, a2, ..., an],
        // derivative is [a1, 2*a2, 3*a3, ..., n*an]
        List<Double> derivativeCoeffs = new ArrayList<>();
        for (int i = 1; i < xs.size(); i++) {
            derivativeCoeffs.add((double) i * xs.get(i));
        }

        // Newton-Raphson iteration
        for (int iteration = 0; iteration < 100; iteration++) {
            double fx = poly(xs, x);

            // If we're close enough to zero, return
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            double fpx = poly(derivativeCoeffs, x);

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-10) {
                // Try a different starting point or use bisection fallback
                x += 0.1;
                continue;
            }

            double nextX = x - fx / fpx;

            // Check for convergence
            if (Math.abs(nextX - x) < 1e-10) {
                return nextX;
            }

            x = nextX;
        }

        // Fallback: if still not converged, return current approximation
        return x;
    }
}

