class Solution {
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For Newton-Raphson, we need the derivative polynomial
        List<Double> derivativeCoeffs = new ArrayList<>();
        for (int i = 1; i < xs.size(); i++) {
            derivativeCoeffs.add(xs.get(i) * i);
        }

        // Initial guess - try some common values
        double x = 1.0;
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            double fpx = poly(derivativeCoeffs, x);
            if (Math.abs(fpx) < 1e-15) {
                // Derivative too small, try perturbing
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < tolerance) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNext)) < tolerance) {
                    return xNext;
                }
            }

            x = xNext;
        }

        // Fallback: if Newton-Raphson fails, try bisection around origin
        // Since odd-degree polynomials go to +/- infinity at extremes
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Ensure we have opposite signs (should be true for odd degree)
        if (fLeft * fRight > 0) {
            // Try wider range
            left = -10000.0;
            right = 10000.0;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Last resort: return midpoint
        return (left + right) / 2.0;
    }
}

