class Solution {
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return 0; // or -1, depending on requirements, but n >= 2 usually makes sense here
        }

        // Check for smallest divisor from 2 to sqrt(n)
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                return n / i;
            }
        }

        // If n is prime, the largest proper divisor is 1
        return 1;
    }
}

