                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Convert to array for faster access
        double[] coeffs = new double[xs.size()];
        for (int i = 0; i < xs.size(); i++) {
            coeffs[i] = xs.get(i);
        }

        // Find the degree (highest non-zero coefficient index)
        int degree = coeffs.length - 1;

        // Find leading coefficient (largest non-zero coefficient)
        double leadingCoeff = coeffs[degree];
        while (leadingCoeff == 0 && degree > 0) {
            degree--;
            leadingCoeff = coeffs[degree];
        }

        // For odd degree polynomials, there's guaranteed to be at least one real root
        // We'll use bisection method with a sufficiently large search interval

        // First, find an interval [a, b] where f(a) * f(b) < 0
        double a = -1.0;
        double b = 1.0;
        double fa = poly(coeffs, a);
        double fb = poly(coeffs, b);

        // Expand the interval until we find a sign change
        int attempts = 0;
        while (fa * fb > 0 && attempts < 50) {
            a *= 2;
            b *= 2;
            fa = poly(coeffs, a);
            fb = poly(coeffs, b);
            attempts++;
        }

        // If still no sign change, try asymmetric expansion
        if (fa * fb > 0) {
            a = -1000.0;
            b = 1000.0;
            fa = poly(coeffs, a);
            fb = poly(coeffs, b);
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~30 decimal places precision
            double mid = (a + b) / 2.0;
            double fm = poly(coeffs, mid);

            if (Math.abs(fm) < 1e-12) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2.0;
    }

    // Helper method to evaluate polynomial (inline the original poly method)
    private double poly(double[] coeffs, double x) {
        double result = 0;
        double xPower = 1;
        for (int i = 0; i < coeffs.length; i++) {
            result += coeffs[i] * xPower;
            xPower *= x;
        }
        return result;
    }
}

