class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    Evaluates derivative of polynomial with coefficients xs at point x.
    return xs[1] + 2*xs[2] * x + 3*xs[3] * x^2 + .... n*xs[n] * x^(n-1)
     */
    private double polyDerivative(List<Double> xs, double x) {
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += xs.get(i) * i * Math.pow(x, i - 1);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For linear case (degree 1): a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            return -a / b;
        }

        // Newton-Raphson method for higher degree polynomials
        double x = 0.0; // Initial guess

        // Try several starting points to handle cases where Newton might diverge
        double[] initialGuesses = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

        for (double startX : initialGuesses) {
            double currentX = startX;

            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, currentX);

                // Check if we're close enough to a root
                if (Math.abs(fx) < 1e-10) {
                    return currentX;
                }

                double fPrimeX = polyDerivative(xs, currentX);

                // Avoid division by zero or near-zero derivative
                if (Math.abs(fPrimeX) < 1e-12) {
                    currentX += 0.1; // perturb slightly and try again
                    continue;
                }

                double nextX = currentX - fx / fPrimeX;

                // Check for convergence
                if (Math.abs(nextX - currentX) < 1e-12) {
                    return currentX;
                }

                // Handle overflow
                if (Double.isInfinite(nextX) || Double.isNaN(nextX)) {
                    break; // try next initial guess
                }

                currentX = nextX;
            }
        }

        // Fallback: binary search on interval [-1000, 1000] if Newton fails
        double left = -1000.0;
        double right = 1000.0;

        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Since odd-degree polynomials go from -∞ to +∞ or vice versa,
        // we should have opposite signs at extremes
        if (fLeft * fRight > 0) {
            // Expand search range
            left = -10000.0;
            right = 10000.0;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        // Binary search / bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

