class Solution {
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: linear polynomial (2 coefficients)
        if (xs.size() == 2) {
            // f(x) = xs.get(0) + xs.get(1)*x = 0 => x = -xs.get(0)/xs.get(1)
            return -xs.get(0) / xs.get(1);
        }

        // For higher degree polynomials, use Newton-Raphson method
        // Start with initial guess
        double x = 1.0;
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);

            // If we found a root (within tolerance)
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative
            double fpx = 0.0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-15) {
                // Try a small perturbation if derivative is too small
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < tolerance) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNext)) < tolerance) {
                    return xNext;
                }
            }

            x = xNext;
        }

        // If we didn't converge, return best guess
        return x;
    }
}

