        int count = 0;
        int a = 0; // F(0)
        int b = 1; // F(1)

        // Handle special cases for small Fibonacci numbers
        // F(3) = 2, F(4) = 3, F(5) = 5, etc.

        // Check F(3) = 2
        if (n == 1) {
            return 2;
        }

        // Start generating from F(3) onwards
        int prev = 2; // F(3)
        int curr = 3; // F(4)

        count = 2; // We've found 2 and 3

        if (n == 2) {
            return 3;
        }

        while (true) {
            // Check if prev is prime (we already handled 2, so start with 3)
            if (isPrime(prev)) {
                count++;
                if (count == n) {
                    return prev;
                }
            }

            if (isPrime(curr)) {
                count++;
                if (count == n) {
                    return curr;
                }
            }

            // Generate next Fibonacci number
            int next = prev + curr;
            prev = curr;
            curr = next;
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

