    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method to find a root
        double x = 0.0; // initial guess

        // Maximum iterations to prevent infinite loops
        int maxIterations = 100;
        double tolerance = 1e-10;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // If we're close enough to zero, return
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative at x
            double fpx = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fpx += i * xs.get(i) * Math.pow(x, i - 1);
            }

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-15) {
                // If derivative is too small, try a different approach
                // Slightly perturb x to avoid getting stuck
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < tolerance) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNext)) < 10 * tolerance) {
                    return xNext;
                }
            }

            x = xNext;
        }

        // Fallback: try bisection if Newton-Raphson didn't converge well
        // Find an interval [a, b] where f(a)*f(b) < 0
        double a = -1000.0;
        double b = 1000.0;

        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Expand search range if needed
        int expandCount = 0;
        while (fa * fb > 0 && expandCount < 10) {
            a *= 10;
            b *= 10;
            fa = poly(xs, a);
            fb = poly(xs, b);
            expandCount++;
        }

        // Bisection method
        if (fa * fb <= 0) {
            for (int i = 0; i < 100; i++) {
                double mid = (a + b) / 2;
                double fmid = poly(xs, mid);

                if (Math.abs(fmid) < 1e-10 || (b - a) < 1e-10) {
                    return mid;
                }

                if (fa * fmid <= 0) {
                    b = mid;
                    fb = fmid;
                } else {
                    a = mid;
                    fa = fmid;
                }
            }
        }

        // Last resort: return the best approximation from Newton
        return x;
    }
}

