class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) return -1;

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special cases - Fibonacci sequence starts with 0, 1, 1, 2, 3, 5...
        // We need to check each Fibonacci number for primality

        // Check F(0) = 0 - not prime
        // Check F(1) = 1 - not prime
        // Check F(2) = 1 - not prime
        // Check F(3) = 2 - prime (1st)
        // Check F(4) = 3 - prime (2nd)
        // Check F(5) = 5 - prime (3rd)
        // Check F(6) = 8 - not prime
        // Check F(7) = 13 - prime (4th)
        // Check F(8) = 21 - not prime
        // Check F(9) = 34 - not prime
        // Check F(10) = 55 - not prime
        // Check F(11) = 89 - prime (5th)

        while (true) {
            long next = a + b;
            a = b;
            b = next;

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return (int) next;
                }
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

