class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Get the degree (number of coefficients - 1)
        int n = xs.size() - 1;

        // Since xs has even number of coefficients, n is odd (degree is odd)
        // For odd degree polynomials, lim_{x->+inf} p(x) = sign(lc) * inf
        // and lim_{x->-inf} p(x) = -sign(lc) * inf, so there must be a real root

        // Find the leading coefficient (last non-zero coefficient)
        double leadingCoeff = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) {
                leadingCoeff = xs.get(i);
                break;
            }
        }

        // Determine the sign behavior at infinity
        boolean positiveAtInfinity = (leadingCoeff > 0);

        // Find an interval [a, b] where p(a) and p(b) have opposite signs
        double a = -1.0;
        double b = 1.0;
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Expand interval until we find opposite signs
        int attempts = 0;
        while (fa * fb > 0 && attempts < 50) {
            if (positiveAtInfinity) {
                b *= 2;
                fb = poly(xs, b);
                a = -b;
                fa = poly(xs, a);
            } else {
                a *= 2;
                fa = poly(xs, a);
                b = -a;
                fb = poly(xs, b);
            }
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations for precision
            double mid = (a + b) / 2;
            double fmid = poly(xs, mid);

            if (Math.abs(fmid) < 1e-12 || (b - a) < 1e-12) {
                return mid;
            }

            if (fa * fmid <= 0) {
                b = mid;
                fb = fmid;
            } else {
                a = mid;
                fa = fmid;
            }
        }

        return (a + b) / 2;
    }
}

