class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Use Newton-Raphson method
        double x = 1.0; // initial guess

        // Newton-Raphson iterations
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative: f'(x)
            double dfx = 0.0;
            for (int j = 1; j < xs.size(); j++) {
                dfx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            // Avoid division by zero
            if (Math.abs(dfx) < 1e-10) {
                x += 0.1; // perturb and try again
                continue;
            }

            double xNew = x - fx / dfx;

            // Check for convergence
            if (Math.abs(xNew - x) < 1e-10) {
                return xNew;
            }

            x = xNew;
        }

        return x;
    }
}

