class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle linear case directly: a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            return -a / b;
        }

        // Use Newton-Raphson method with multiple starting points
        double[] startingPoints = {-100, -10, -1, 0, 1, 10, 100};

        for (double start : startingPoints) {
            double root = newtonRaphson(xs, start);
            if (Math.abs(poly(xs, root)) < 1e-9) {
                return root;
            }
        }

        // Fallback: try bisection method on intervals
        for (int i = -100; i <= 100; i++) {
            double left = i;
            double right = i + 1;
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            if (fLeft * fRight <= 0) {
                // Root exists in [left, right]
                double mid = (left + right) / 2;
                while (right - left > 1e-9) {
                    fLeft = poly(xs, left);
                    fRight = poly(xs, right);
                    mid = (left + right) / 2;
                    double fMid = poly(xs, mid);

                    if (Math.abs(fMid) < 1e-12) {
                        break;
                    }

                    if (fLeft * fMid <= 0) {
                        right = mid;
                    } else {
                        left = mid;
                    }
                }
                return mid;
            }
        }

        // Should not reach here due to problem guarantee, but return NaN as fallback
        return Double.NaN;
    }

    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 100; i++) {  // Max iterations
            double fx = poly(xs, x);

            // Derivative evaluation using finite difference for simplicity
            double h = 1e-9;
            double fPrime = (poly(xs, x + h) - poly(xs, x - h)) / (2 * h);

            if (Math.abs(fPrime) < 1e-12) {
                continue;  // Skip if derivative too small
            }

            double xNext = x - fx / fPrime;

            if (Math.abs(xNext - x) < 1e-12 || Math.abs(fx) < 1e-12) {
                return xNext;
            }

            x = xNext;
        }
        return x;
    }
}

