class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true; // 2 and 3 are prime
        }

        // Eliminate multiples of 2 and 3
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check for factors from 5 up to sqrt(n), skipping even numbers
        // Use the pattern: check i and i+2 where i = 5, 11, 17, 23, ...
        // This checks numbers of form 6k±1
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Try Newton-Raphson with multiple starting points
        double[] starts = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0, 0.5, -0.5};

        for (double start : starts) {
            double result = newtonRaphson(xs, start);
            if (Math.abs(poly(xs, result)) < 1e-9) {
                return result;
            }
        }

        // If Newton-Raphson fails, try bisection on a reasonable interval
        // Since odd-degree polynomials go to ±infinity at ends, there must be a sign change
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Ensure we have a sign change
        while (fLeft * fRight > 0 && (left > -1e6 || right < 1e6)) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        if (fLeft * fRight <= 0) {
            // Bisection method
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);
                if (Math.abs(fMid) < 1e-9) {
                    return mid;
                }
                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
            return (left + right) / 2;
        }

        // Fallback: return 0 if all else fails (shouldn't happen per problem constraints)
        return 0.0;
    }

    private double newtonRaphson(List<Double> xs, double start) {
        double x = start;
        for (int i = 0; i < 50; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative: f'(x) = sum_{i=1}^{n} i * xs[i] * x^(i-1)
            double dfx = 0;
            for (int j = 1; j < xs.size(); j++) {
                dfx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(dfx) < 1e-12) {
                // Derivative too small, try a different approach
                return x + 0.1; // small step
            }

            x = x - fx / dfx;

            // Check for divergence
            if (Double.isNaN(x) || Double.isInfinite(x) || Math.abs(x) > 1e6) {
                return start; // give up and return start
            }
        }
        return x;
    }
}

