class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 0; // F(0)
        int b = 1; // F(1)

        // Handle special cases for small Fibonacci numbers
        if (a == 2) count++;
        if (b == 2 || b == 3) {
            if (b == 2) count++;
            if (count == n) return b;
            if (b == 3) count++;
            if (count == n) return b;
        }

        // Start from F(3) = 2, but we've already handled base cases above
        // Let's generate Fibonacci numbers starting from index 2
        int index = 2;

        while (true) {
            int next = a + b;

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }

            a = b;
            b = next;
            index++;
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }

        return true;
    }
}

