class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Ensure both strings have the same length by padding the shorter one with leading zeros
        int lenA = a.length();
        int lenB = b.length();
        int maxLen = Math.max(lenA, lenB);

        // Pad strings with leading zeros to make them equal length
        StringBuilder sbA = new StringBuilder();
        for (int i = lenA; i < maxLen; i++) {
            sbA.append('0');
        }
        sbA.append(a);

        StringBuilder sbB = new StringBuilder();
        for (int i = lenB; i < maxLen; i++) {
            sbB.append('0');
        }
        sbB.append(b);

        // Perform XOR operation bit by bit
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < maxLen; i++) {
            char bitA = sbA.charAt(i);
            char bitB = sbB.charAt(i);

            // XOR: same bits give 0, different bits give 1
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

