    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Edge cases: empty substring or string longer than substring
        if (substring == null || substring.isEmpty() || string == null || string.length() < substring.length()) {
            return 0;
        }

        int count = 0;
        int stringLen = string.length();
        int subLen = substring.length();

        // Check each possible starting position
        for (int i = 0; i <= stringLen - subLen; i++) {
            if (string.substring(i, i + subLen).equals(substring)) {
                count++;
            }
        }

        return count;
    }
}

