class Solution {
    public List<Integer> factorize(int n) {
        List<Integer> factors = new ArrayList<>();

        // Handle edge case: numbers <= 1 have no prime factors
        if (n <= 1) {
            return factors;
        }

        // Check for factor 2 separately to optimize (then we can check only odd numbers)
        while (n % 2 == 0) {
            factors.add(2);
            n /= 2;
        }

        // Check for odd factors starting from 3
        for (int i = 3; i * i <= n; i += 2) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }

        // If n is still greater than 1, then it's a prime factor
        if (n > 1) {
            factors.add(n);
        }

        return factors;
    }
}

