class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For linear case (degree 1), solve directly
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (b != 0) {
                return -a / b;
            }
        }

        // Use Newton-Raphson method
        double x = 0.0; // initial guess

        // Try different starting points to increase chances of finding a root
        double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

        for (double startX : startingPoints) {
            double currentX = startX;
            for (int i = 0; i < 100; i++) { // max iterations
                double fx = poly(xs, currentX);

                // Check if we're close enough to zero
                if (Math.abs(fx) < 1e-9) {
                    return currentX;
                }

                // Compute derivative
                double fPrimeX = polyDerivative(xs, currentX);

                // If derivative is too small, avoid division by zero
                if (Math.abs(fPrimeX) < 1e-12) {
                    break; // try next starting point
                }

                double nextX = currentX - fx / fPrimeX;

                // Check for convergence
                if (Math.abs(nextX - currentX) < 1e-9) {
                    return nextX;
                }

                currentX = nextX;
            }
        }

        // Fallback: try bisection method between -1000 and 1000
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Find interval where sign changes
        while (fLeft * fRight > 0 && (right - left) < 2000) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        // Bisection method
        if (fLeft * fRight <= 0) {
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);

                if (Math.abs(fMid) < 1e-9 || (right - left) < 1e-9) {
                    return mid;
                }

                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
        }

        // Last resort: return midpoint of search range
        return (left + right) / 2;
    }

    private double polyDerivative(List<Double> xs, double x) {
        // Derivative of a_0 + a_1*x + a_2*x^2 + ... + a_n*x^n
        // is a_1 + 2*a_2*x + 3*a_3*x^2 + ... + n*a_n*x^(n-1)
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

