            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        double xPower = 1;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * xPower;
            xPower *= x;
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Optimized polynomial evaluation using Horner's method
        // But for clarity, we'll use the direct method in poly, but optimize here

        // Since polynomial has even number of coefficients, degree is odd (n = xs.size()-1)
        // and odd-degree polynomials always have at least one real root

        // Try Newton-Raphson with multiple starting points
        double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0, 100.0, -100.0};

        for (double start : startingPoints) {
            double result = newtonRaphson(xs, start);
            if (Math.abs(poly(xs, result)) < 1e-9) {
                return result;
            }
        }

        // Fallback to bisection method over a wide range
        double left = -1000.0;
        double right = 1000.0;

        // Find interval where function changes sign
        while (left < right) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            double fLeft = poly(xs, left);
            if (fLeft * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }

            // Prevent infinite loop
            if (right - left < 1e-9) {
                break;
            }
        }

        return (left + right) / 2;
    }

    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 100; i++) { // max iterations
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative using Horner's method
            double fPrime = derivative(xs, x);
            if (Math.abs(fPrime) < 1e-12) {
                // Derivative too small, try small perturbation
                x += 0.001;
                continue;
            }

            double xNew = x - fx / fPrime;
            if (Double.isNaN(xNew) || Double.isInfinite(xNew)) {
                return x0; // fallback
            }

            if (Math.abs(xNew - x) < 1e-12) {
                return xNew;
            }
            x = xNew;
        }
        return x;
    }

    private double derivative(List<Double> xs, double x) {
        // Evaluate derivative: if f(x) = a0 + a1*x + a2*x^2 + ... + an*x^n
        // then f'(x) = a1 + 2*a2*x + 3*a3*x^2 + ... + n*an*x^(n-1)
        double result = 0;
        double xPower = 1;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * xPower;
            xPower *= x;
        }
        return result;
    }
}

