class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 0;  // F(0)
        int b = 1;  // F(1)

        // Handle special case for F(3) = 2
        if (n == 1) {
            return 2;
        }

        // Start from F(3) = 2
        int index = 3;

        while (true) {
            int fib = a + b;

            if (isPrime(fib)) {
                count++;
                if (count == n) {
                    return fib;
                }
            }

            // Update Fibonacci sequence
            a = b;
            b = fib;
            index++;
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

