class Solution {
    /**
     * Utility class - prevent instantiation
     */
    private Solution() {
        throw new AssertionError();
    }

    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Check the first few Fibonacci numbers manually
        // F(0) = 0 (not prime)
        // F(1) = 1 (not prime)
        // F(2) = 1 (not prime)
        // F(3) = 2 (prime)
        // F(4) = 3 (prime)
        // F(5) = 5 (prime)
        // F(6) = 8 (not prime)
        // F(7) = 13 (prime)
        // F(8) = 21 (not prime)
        // F(9) = 34 (not prime)
        // F(10) = 55 (not prime)
        // F(11) = 89 (prime)

        // Start generating from F(3) = 2
        if (n == 1) return 2;
        if (n == 2) return 3;
        if (n == 3) return 5;

        count = 3; // We already counted 2, 3, 5

        // Continue from F(6) = 8 onwards
        long prev2 = 3; // F(4) = 3
        long prev1 = 5; // F(5) = 5
        long current = 8; // F(6) = 8

        while (true) {
            if (isPrime(current)) {
                count++;
                if (count == n) {
                    return (int) current;
                }
            }

            prev2 = prev1;
            prev1 = current;
            current = prev2 + prev1;

            // Safety check for overflow
            if (current < 0) {
                throw new ArithmeticException("Fibonacci number overflow");
            }
        }
    }

    /**
     * Check if a number is prime
     */
    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

