class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge case: linear polynomial
        if (xs.size() == 2) {
            // xs[0] + xs[1]*x = 0 => x = -xs[0]/xs[1]
            return -xs.get(0) / xs.get(1);
        }

        // Find the degree (highest non-zero coefficient index)
        int degree = xs.size() - 1;
        while (degree > 0 && Math.abs(xs.get(degree)) < 1e-12) {
            degree--;
        }

        // We know degree is odd (since even number of coefficients means odd degree)
        // Use bisection method with a large enough range

        // First, find bounds where function changes sign
        double left = -1000.0;
        double right = 1000.0;

        // Expand the range if needed to ensure we bracket a root
        while (poly(xs, left) > 0) {
            left *= 2;
            if (left < -1e10) break; // Safety limit
        }
        while (poly(xs, right) < 0) {
            right *= 2;
            if (right > 1e10) break; // Safety limit
        }

        // Ensure we have opposite signs at the ends
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If both same sign, expand further
        if (fLeft * fRight > 0) {
            left = -10000.0;
            right = 10000.0;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations should be enough for double precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint as fallback
        return (left + right) / 2.0;
    }
}

