    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        String[] words = numbers.trim().split("\\s+");

        // Create a list of pairs (word, numeric value) for sorting
        List<Map.Entry<String, Integer>> wordValuePairs = new ArrayList<>();
        for (String word : words) {
            wordValuePairs.add(new AbstractMap.SimpleEntry<>(word, NUMBER_MAP.get(word)));
        }

        // Sort by numeric value
        Collections.sort(wordValuePairs, Map.Entry.comparingByValue());

        // Extract just the words in sorted order
        List<String> sortedWords = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : wordValuePairs) {
            sortedWords.add(entry.getKey());
        }

        return String.join(" ", sortedWords);
    }
