class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Edge case: n <= 1 has no proper divisors
        if (n <= 1) {
            return -1; // or throw exception, but problem implies n >= 2
        }

        // Check for smallest divisor starting from 2
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                // i is the smallest divisor, so n/i is the largest proper divisor
                return n / i;
            }
        }

        // If we reach here, n is prime, so the largest proper divisor is 1
        return 1;
    }
}

