class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Use bisection method with increasing search intervals
        // Since polynomial has odd degree, it must have at least one real root

        // First, evaluate the polynomial at some points to find sign change
        double left = -1000.0;
        double right = 1000.0;

        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If we're lucky and get exact zero
        if (Math.abs(fLeft) < 1e-9) return left;
        if (Math.abs(fRight) < 1e-9) return right;

        // Expand search range until we find sign change
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 20) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // If still no sign change, use Newton-Raphson with multiple starting points
        if (fLeft * fRight > 0) {
            // Try Newton-Raphson with several initial guesses
            double[] guesses = {0.0, 1.0, -1.0, 10.0, -10.0, 0.5, -0.5};
            for (double guess : guesses) {
                double root = newtonRaphson(xs, guess);
                if (Math.abs(poly(xs, root)) < 1e-7) {
                    return root;
                }
            }
            // Fallback: return midpoint
            return (left + right) / 2;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }

    // Helper method for Newton-Raphson
    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 50; i++) {
            double fx = poly(xs, x);
            // Calculate derivative: if f(x) = a0 + a1*x + a2*x^2 + ..., then f'(x) = a1 + 2*a2*x + 3*a3*x^2 + ...
            double fxPrime = 0;
            for (int j = 1; j < xs.size(); j++) {
                fxPrime += j * xs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(fxPrime) < 1e-12) {
                // Derivative too small, try perturbation
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fxPrime;

            if (Math.abs(xNext - x) < 1e-9) {
                break;
            }

            x = xNext;
        }
        return x;
    }
}

