    [1, 4, 2, 4, 3]
     */
    public List<Integer> intersperse(List<Integer> numbers, int delimiter) {
        // Handle null or empty list
        if (numbers == null || numbers.isEmpty()) {
            return new ArrayList<>();
        }

        // Handle single element list - just return a copy
        if (numbers.size() == 1) {
            return new ArrayList<>(numbers);
        }

        // Create result list with estimated capacity
        // Original size + (size-1) delimiters
        List<Integer> result = new ArrayList<>(numbers.size() * 2 - 1);

        // Add first element
        result.add(numbers.get(0));

        // Add remaining elements with delimiter before each
        for (int i = 1; i < numbers.size(); i++) {
            result.add(delimiter);
            result.add(numbers.get(i));
        }

        return result;
    }
}

