                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // According to the problem, we can assume valid input,
                    // but in production code we might throw an exception or skip
                    break;
            }
        }

        return result;
    }
}

