class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.isEmpty()) {
            return numbers;
        }

        // Use a single Map instance for lookup (immutable, so safe to reuse)
        final Map<String, Integer> wordToNum = new HashMap<>();
        wordToNum.put("zero", 0);
        wordToNum.put("one", 1);
        wordToNum.put("two", 2);
        wordToNum.put("three", 3);
        wordToNum.put("four", 4);
        wordToNum.put("five", 5);
        wordToNum.put("six", 6);
        wordToNum.put("seven", 7);
        wordToNum.put("eight", 8);
        wordToNum.put("nine", 9);

        // Split into words - avoid creating unnecessary String objects
        String[] words = numbers.split(" ");

        // Create list for sorting
        List<String> wordList = new ArrayList<>(words.length);
        for (String word : words) {
            wordList.add(word); // Reuse existing String objects from split
        }

        // Sort using custom comparator based on numeric value
        Collections.sort(wordList, (a, b) -> {
            return wordToNum.get(a) - wordToNum.get(b);
        });

        // Join back with spaces - avoid creating unnecessary StringBuilder/Strings in loop
        return String.join(" ", wordList);
    }
}

