class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[2] * x^2 + .... xs[n] * x^n
    Using Horner's method for efficiency
     */
    public double poly(List<Double> xs, double x) {
        double result = 0.0;
        // Horner's method: start from highest degree coefficient
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero finds x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Assumes list xs has even number of coefficients and largest non-zero coefficient
    guarantees a solution exists.
     */
    public double findZero(List<Double> xs) {
        // Handle edge case: linear polynomial (2 coefficients)
        if (xs.size() == 2) {
            // f(x) = a + bx, root at x = -a/b
            double a = xs.get(0);
            double b = xs.get(1);
            if (b == 0) return 0.0; // shouldn't happen per problem constraints
            return -a / b;
        }

        // For higher degree polynomials, use Newton-Raphson method
        // First, compute derivative coefficients
        List<Double> derivative = new ArrayList<>();
        for (int i = 1; i < xs.size(); i++) {
            derivative.add(xs.get(i) * i);
        }

        // Newton-Raphson method
        double x = 1.0; // initial guess
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            double fpx = poly(derivative, x);

            // Avoid division by zero
            if (Math.abs(fpx) < tolerance) {
                // Perturb x slightly to avoid flat region
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < tolerance) {
                return xNext;
            }

            x = xNext;
        }

        // Fallback: return best approximation found
        return x;
    }
}

