class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        double xPower = 1.0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * xPower;
            xPower *= x;
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Ensure we have even number of coefficients (odd degree polynomial)
        int n = xs.size();
        if (n % 2 != 0 || n == 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Find the leading coefficient (highest degree term)
        double leadingCoeff = 0.0;
        for (int i = n - 1; i >= 0; i--) {
            if (!Double.equals(xs.get(i), 0.0)) {
                leadingCoeff = xs.get(i);
                break;
            }
        }

        if (leadingCoeff == 0.0) {
            throw new IllegalArgumentException("Polynomial must have non-zero leading coefficient");
        }

        // For odd-degree polynomials, we know there's at least one real root
        // Use bisection method with a sufficiently large search interval

        // First, find an interval [a, b] where f(a) * f(b) < 0
        double a = -1.0;
        double b = 1.0;
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Expand interval until we find sign change
        int expansionCount = 0;
        while (fa * fb > 0 && expansionCount < 100) {
            a *= 2;
            b *= 2;
            fa = poly(xs, a);
            fb = poly(xs, b);
            expansionCount++;
        }

        // If still no sign change, use the fact that odd-degree polynomials 
        // go to opposite infinities, so pick very large values
        if (fa * fb > 0) {
            a = leadingCoeff > 0 ? -1e6 : 1e6;
            b = leadingCoeff > 0 ? 1e6 : -1e6;
            fa = poly(xs, a);
            fb = poly(xs, b);
        }

        // Bisection method
        double tolerance = 1e-10;
        int maxIterations = 100;

        for (int i = 0; i < maxIterations; i++) {
            double mid = (a + b) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance || (b - a) / 2.0 < tolerance) {
                return mid;
            }

            if (fa * fMid <= 0) {
                b = mid;
                fb = fMid;
            } else {
                a = mid;
                fa = fMid;
            }
        }

        return (a + b) / 2.0;
    }
}

