class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0;  // F(0)
        long b = 1;  // F(1)

        // Handle special cases - Fibonacci sequence starts with 0, 1, 1, 2, ...
        if (isPrime(2)) {
            count++;
            if (count == n) return 2;
        }

        if (isPrime(3)) {
            count++;
            if (count == n) return 3;
        }

        if (isPrime(5)) {
            count++;
            if (count == n) return 5;
        }

        // Start generating from F(7) = 13 onwards
        long prev = 5; // F(5)
        long curr = 8; // F(6)

        while (true) {
            long next = prev + curr;
            prev = curr;
            curr = next;

            if (curr > Integer.MAX_VALUE) {
                break; // Safety check, though Fibonacci primes beyond 89 are large
            }

            if (isPrime((int)curr)) {
                count++;
                if (count == n) {
                    return (int)curr;
                }
            }
        }

        // Alternative approach: generate all Fibonacci numbers and check
        // Let's rewrite with cleaner logic
        return findNthFibonacciPrime(n);
    }

    // Better implementation
    private int findNthFibonacciPrime(int n) {
        if (n <= 0) throw new IllegalArgumentException("n must be positive");

        int count = 0;
        int fib1 = 1;
        int fib2 = 1;

        // Check small Fibonacci numbers first
        if (isPrime(2)) {
            count++;
            if (count == n) return 2;
        }

        if (isPrime(3)) {
            count++;
            if (count == n) return 3;
        }

        if (isPrime(5)) {
            count++;
            if (count == n) return 5;
        }

        // Continue with larger Fibonacci numbers
        int a = 5;
        int b = 8;

        while (true) {
            if (isPrime(b)) {
                count++;
                if (count == n) {
                    return b;
                }
            }

            int next = a + b;
            a = b;
            b = next;

            // Prevent overflow
            if (b < 0 || b > Integer.MAX_VALUE) {
                break;
            }
        }

        throw new RuntimeException("Failed to find nth Fibonacci prime");
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        int sqrt = (int)Math.sqrt(num);
        for (int i = 3; i <= sqrt; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

