class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return -1; // or throw exception, but problem doesn't specify
        }

        // The largest proper divisor of n is n divided by its smallest prime factor
        // If n is prime, the answer is 1

        // Check if n is even
        if (n % 2 == 0) {
            return n / 2;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return n / i;
            }
        }

        // If no divisor found, n is prime, so return 1
        return 1;
    }
}

