class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For polynomials with odd degree (even # of coefficients), 
        // as x -> ±∞, f(x) -> ±∞ (opposite signs), so there's always a root

        // Evaluate leading coefficient to determine end behavior
        double leadCoeff = xs.get(xs.size() - 1);

        // Find initial bounds [a, b] where f(a) * f(b) < 0
        double a = -1.0;
        double b = 1.0;

        // Expand bounds until we find opposite signs
        while (true) {
            double fa = poly(xs, a);
            double fb = poly(xs, b);

            if (fa * fb <= 0) {
                // We found a bracket (might be exactly zero at one end)
                if (Math.abs(fa) < 1e-12) return a;
                if (Math.abs(fb) < 1e-12) return b;
                break;
            }

            // Expand bounds exponentially
            a *= 2;
            b *= 2;

            // Safety limit to avoid infinite loops
            if (Math.abs(a) > 1e10) {
                // Fallback: just return 0 if we can't find bounds
                return 0.0;
            }
        }

        // Binary search (bisection method) for root
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~1e-30 precision
            double mid = (a + b) / 2;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < 1e-12) {
                return mid;
            }

            double fa = poly(xs, a);
            if (fa * fm <= 0) {
                b = mid;
            } else {
                a = mid;
            }
        }

        return (a + b) / 2;
    }
}

