        // Create result list and place sorted even values back at even indices
        List<Integer> result = new ArrayList<>(l);
        int evenIndex = 0;
        for (int i = 0; i < result.size(); i += 2) {
            result.set(i, evenValues.get(evenIndex++));
        }

        return result;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    returns encoded string by cycling groups of three characters.
     */
    public String encodeCyclic(String s) {
        // split string to groups. Each of length 3.
        List<String> groups = new ArrayList<>();
        for (int i = 0; i < s.length(); i += 3) {
            groups.add(s.substring(i, Math.min(i + 3, s.length())));
        }
        // cycle elements in each group. Unless group has fewer elements than 3.
        for (int i = 0; i < groups.size(); i++) {
            if (groups.get(i).length() == 3) {
                groups.set(i, groups.get(i).substring(1) + groups.get(i).charAt(0));
            }
        }
        return String.join("", groups);
    }

    /**
    takes as input string encoded with encodeCyclic function. Returns decoded string.
     */
    public String decodeCyclic(String s) {
        // split string to groups. Each of length 3.
        List<String> groups = new ArrayList<>();
        for (int i = 0; i < s.length(); i += 3) {
            groups.add(s.substring(i, Math.min(i + 3, s.length())));
        }
        // reverse cycle elements in each group (undo the encoding)
        // for 3-char groups: move last char to front (right rotation)
        for (int i = 0; i < groups.size(); i++) {
            if (groups.get(i).length() == 3) {
                String group = groups.get(i);
                groups.set(i, group.charAt(2) + group.substring(0, 2));
            }
        }
        return String.join("", groups);
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special case for small Fibonacci numbers
        if (n == 1) return 2;

        while (true) {
            long next = a + b;
            a = b;
            b = next;

            // Skip 0 and 1 as they are not prime
            if (next < 2) continue;

            if (isPrime((int) next)) {
                count++;
                if (count == n) {
                    return (int) next;
                }
            }
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Check if in given list of numbers, are any two numbers closer to each other than given threshold.
    >>> hasCloseElements(Arrays.asList(1.0, 2.0, 3.0), 0.5)
    false
    >>> hasCloseElements(Arrays.asList(1.0, 2.8, 3.0, 4.0, 5.0, 2.0), 0.3)
    true
     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        // Handle edge cases
        if (numbers == null || numbers.size() < 2) {
            return false;
        }

        // If threshold is negative, no pair can be closer than a negative distance
        if (threshold < 0) {
            return false;
        }

        // Convert to array for efficient sorting and access
        Double[] arr = numbers.toArray(new Double[0]);
        Arrays.sort(arr);

        // Check adjacent elements only
        for (int i = 0; i < arr.length - 1; i++) {
            double diff = Math.abs(arr[i] - arr[i + 1]);
            if (diff < threshold) {
                return true;
            }
        }

        return false;
    }
}

