    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method
        double x = 0.0; // initial guess

        // Try multiple starting points if needed
        for (int attempt = 0; attempt < 20; attempt++) {
            // Try different starting points
            double start = attempt == 0 ? 0.0 : 
                          (attempt % 2 == 1 ? attempt / 2.0 : -attempt / 2.0);

            double current = start;
            for (int i = 0; i < 50; i++) { // max iterations
                double fx = poly(xs, current);

                // Check if we found a root
                if (Math.abs(fx) < 1e-9) {
                    return current;
                }

                // Numerical derivative
                double h = 1e-7;
                double fpx = (poly(xs, current + h) - poly(xs, current - h)) / (2 * h);

                // Avoid division by zero
                if (Math.abs(fpx) < 1e-12) {
                    break;
                }

                double next = current - fx / fpx;

                // Check for convergence
                if (Math.abs(next - current) < 1e-9) {
                    if (Math.abs(poly(xs, next)) < 1e-9) {
                        return next;
                    }
                    break;
                }

                current = next;
            }
        }

        // Fallback: try bisection between -1000 and 1000
        double left = -1000.0;
        double right = 1000.0;

        // Find interval where sign changes
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If no sign change, expand range
        int expandCount = 0;
        while (fLeft * fRight > 0 && expandCount < 10) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            expandCount++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-9 || (right - left) < 1e-9) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint as last resort
        return (left + right) / 2;
    }
}

