class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Handle null inputs
        if (a == null || b == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        // Ensure both strings have the same length
        if (a.length() != b.length()) {
            throw new IllegalArgumentException("Input strings must have the same length");
        }

        StringBuilder result = new StringBuilder(a.length());

        for (int i = 0; i < a.length(); i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            // XOR operation: if bits are different, result is '1', otherwise '0'
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

