class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Handle edge cases
        if (substring.isEmpty()) {
            return 0;
        }
        if (string.isEmpty()) {
            return 0;
        }

        int count = 0;
        int index = 0;

        // Keep searching until we can't find any more matches
        while (index <= string.length() - substring.length()) {
            int foundIndex = string.indexOf(substring, index);
            if (foundIndex == -1) {
                break;
            }
            count++;
            // Move to the next position to allow overlapping matches
            index = foundIndex + 1;
        }

        return count;
    }
}

