class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method with multiple starting points
        // Since a solution is guaranteed, we'll try several initial guesses

        // Handle edge case: constant polynomial (degree 0) - but problem says even number of coefficients
        // and largest non-zero coefficient guarantees solution, so degree >= 1

        // Try Newton-Raphson from multiple starting points
        double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0, 0.5, -0.5};

        for (double start : startingPoints) {
            double result = newtonRaphson(xs, start);
            if (!Double.isNaN(result) && !Double.isInfinite(result)) {
                // Verify it's actually a root (within reasonable tolerance)
                double value = poly(xs, result);
                if (Math.abs(value) < 1e-8) {
                    return result;
                }
            }
        }

        // Fallback: try bisection method on a large interval
        // Find interval where function changes sign
        double left = -1000.0;
        double right = 1000.0;

        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If same sign, expand interval
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 10) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // Bisection method
        if (fLeft * fRight <= 0) {
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);

                if (Math.abs(fMid) < 1e-8) {
                    return mid;
                }

                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }

            // Return midpoint as best guess
            return (left + right) / 2;
        }

        // Last resort: return 0.0 (shouldn't happen given problem constraints)
        return 0.0;
    }

    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;

        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);

            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative using numerical differentiation
            // Or we could compute analytically, but numerical is simpler
            double h = 1e-8;
            double fPrime = (poly(xs, x + h) - poly(xs, x - h)) / (2 * h);

            if (Math.abs(fPrime) < 1e-12) {
                // Derivative too small, try different approach
                return Double.NaN;
            }

            double xNext = x - fx / fPrime;

            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                return Double.NaN;
            }

            if (Math.abs(xNext - x) < 1e-12) {
                return xNext;
            }

            x = xNext;
        }

        return x;
    }
}

