class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Special cases: the first few Fibonacci numbers are 0, 1, 1, 2, 3, 5...
        // We need to handle the sequence properly

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Check the first few Fibonacci numbers manually since 0 and 1 aren't prime
        // Start from F(2) = 1, F(3) = 2, etc.

        // Handle F(0) = 0 (not prime), F(1) = 1 (not prime), F(2) = 1 (not prime)
        // Start checking from F(3) = 2

        // First, check F(3) = 2
        if (isPrime((int)a)) count++;
        if (count == n) return (int)a;

        if (isPrime((int)b)) count++;
        if (count == n) return (int)b;

        // Now iterate through remaining Fibonacci numbers
        while (true) {
            long c = a + b;
            a = b;
            b = c;

            if (c > Integer.MAX_VALUE) {
                throw new ArithmeticException("Result exceeds integer range");
            }

            if (isPrime((int)c)) {
                count++;
                if (count == n) {
                    return (int)c;
                }
            }
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

