class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Handle edge cases
        if (a == null || b == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        // Make sure both strings have the same length by padding the shorter one with leading zeros
        int lenA = a.length();
        int lenB = b.length();
        int maxLen = Math.max(lenA, lenB);

        // Pad with leading zeros to make equal length
        StringBuilder sbA = new StringBuilder(a);
        StringBuilder sbB = new StringBuilder(b);

        while (sbA.length() < maxLen) {
            sbA.insert(0, '0');
        }
        while (sbB.length() < maxLen) {
            sbB.insert(0, '0');
        }

        StringBuilder result = new StringBuilder(maxLen);

        // Perform XOR character by character
        for (int i = 0; i < maxLen; i++) {
            char bitA = sbA.charAt(i);
            char bitB = sbB.charAt(i);

            if (bitA == bitB) {
                result.append('0');  // Same bits XOR to 0
            } else {
                result.append('1');  // Different bits XOR to 1
            }
        }

        return result.toString();
    }
}

