class Solution {
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true;
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check for divisors from 5 up to sqrt(n), skipping even numbers
        // Use the pattern: check i and i+2, then increment by 6
        // This checks numbers of form 6k±1 (which covers all primes > 3)
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle special case: linear polynomial (degree 1, 2 coefficients)
        if (xs.size() == 2) {
            double a0 = xs.get(0);
            double a1 = xs.get(1);
            if (Math.abs(a1) < 1e-15) {
                throw new IllegalArgumentException("Linear coefficient is zero");
            }
            return -a0 / a1;
        }

        // Newton-Raphson method
        double x = 1.0; // initial guess

        for (int iter = 0; iter < 100; iter++) {
            double fx = poly(xs, x);

            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Calculate derivative
            double fpx = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fpx += i * xs.get(i) * Math.pow(x, i - 1);
            }

            // Avoid division by zero or very small numbers
            if (Math.abs(fpx) < 1e-15) {
                // Try a different initial guess or perturb
                x += 0.1;
                continue;
            }

            double x_new = x - fx / fpx;

            // Check for convergence
            if (Math.abs(x_new - x) < 1e-12) {
                return x_new;
            }

            // Limit the step size to prevent overflow
            if (Math.abs(x_new) > 1e10) {
                x = x + (Math.random() - 0.5); // random perturbation
            } else {
                x = x_new;
            }
        }

        // Return best approximation after max iterations
        return x;
    }
}

