class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // For n <= 1, there's no proper divisor
        if (n <= 1) {
            return -1; // or throw exception, but based on examples, n >= 2 likely
        }

        // Start from n/2 and go down, since the largest proper divisor is at most n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // fallback (every number is divisible by 1)
    }
}

