class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Define the polynomial function
        java.util.function.DoubleUnaryOperator polyFunc = (double x) -> {
            double result = 0;
            for (int i = 0; i < xs.size(); i++) {
                result += xs.get(i) * Math.pow(x, i);
            }
            return result;
        };

        double f = polyFunc.applyAsDouble(0.0);

        // If 0 is already a root
        if (Math.abs(f) < 1e-9) {
            return 0.0;
        }

        // Find an interval [a, b] where f(a) * f(b) < 0
        // Start with a reasonable range and expand if needed
        double a = -1.0;
        double b = 1.0;
        double fa = polyFunc.applyAsDouble(a);
        double fb = polyFunc.applyAsDouble(b);

        // Expand interval until we find opposite signs
        int maxExpansions = 100;
        int expansions = 0;
        while (fa * fb >= 0 && expansions < maxExpansions) {
            a *= 2;
            b *= 2;
            fa = polyFunc.applyAsDouble(a);
            fb = polyFunc.applyAsDouble(b);
            expansions++;
        }

        // If still same sign, try larger bounds
        if (fa * fb >= 0) {
            a = -1000.0;
            b = 1000.0;
            fa = polyFunc.applyAsDouble(a);
            fb = polyFunc.applyAsDouble(b);
            // Fallback: if still same sign, just return midpoint as approximation
            if (fa * fb >= 0) {
                return 0.0;
            }
        }

        // Bisection method
        double left = a;
        double right = b;
        double mid;
        double fmid;

        for (int i = 0; i < 100; i++) { // 100 iterations gives ~1e-30 precision
            mid = (left + right) / 2.0;
            fmid = polyFunc.applyAsDouble(mid);

            if (Math.abs(fmid) < 1e-9) {
                return mid;
            }

            if (fa * fmid < 0) {
                right = mid;
                fb = fmid;
            } else {
                left = mid;
                fa = fmid;
            }
        }

        return (left + right) / 2.0;
    }
}

