class Solution {
    public double findZero(List<Double> xs) {
        // Use bisection method to find a root
        double left = -1000.0;
        double right = 1000.0;

        // Expand the interval until we find a sign change
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 2;
            right *= 2;
            // Safety check to prevent infinite loop
            if (Math.abs(left) > 1e10) {
                break;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations for precision
            double mid = (left + right) / 2;
            double value = poly(xs, mid);

            if (Math.abs(value) < 1e-9) {
                return mid;
            }

            if (poly(xs, left) * value < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2;
    }
}

