class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle the first few Fibonacci numbers manually since we start from index 0
        // But we need to check for primes starting from the actual values

        // Check F(0) = 0 - not prime, skip
        // Check F(1) = 1 - not prime, skip

        while (true) {
            long next = a + b;
            a = b;
            b = next;

            // Check if current Fibonacci number (a) is prime and positive
            if (a > 1 && isPrime(a)) {
                count++;
                if (count == n) {
                    return (int) a;
                }
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0 || num % 3 == 0) {
            return false;
        }

        // Check divisors up to sqrt(num)
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

