class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge case: if n <= 1, return -1 or throw exception
        // But based on the example, n is expected to be > 1

        // The largest proper divisor of n is n divided by its smallest prime factor
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                return n / i;
            }
        }

        // If no divisor found, n is prime, so largest proper divisor is 1
        return 1;
    }
}

