    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Convert to array for faster access
        double[] coeffs = xs.stream().mapToDouble(Double::doubleValue).toArray();

        // Define the polynomial function
        java.util.function.DoubleUnaryOperator polyFunc = (double x) -> {
            double result = 0;
            double xPower = 1;
            for (double coeff : coeffs) {
                result += coeff * xPower;
                xPower *= x;
            }
            return result;
        };

        // Bisection method: find interval [a, b] where f(a)*f(b) < 0
        double a = -1000.0;
        double b = 1000.0;

        // Expand interval until we find sign change
        while (polyFunc.applyAsDouble(a) * polyFunc.applyAsDouble(b) > 0) {
            a *= 10;
            b *= 10;
            // Safety limit to avoid infinite loop
            if (Math.abs(a) > 1e10) {
                break;
            }
        }

        // Apply bisection
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~30 decimal places precision
            double mid = (a + b) / 2;
            double fMid = polyFunc.applyAsDouble(mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (polyFunc.applyAsDouble(a) * fMid < 0) {
                b = mid;
            } else {
                a = mid;
            }
        }

        return (a + b) / 2;
    }
}

