class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) return -1;

        int count = 0;
        int a = 1, b = 1; // First two Fibonacci numbers

        // Handle special case: 2 is the first Fibonacci prime
        // We need to check Fibonacci numbers starting from 1,1,2,3,5...

        while (true) {
            // Generate next Fibonacci number
            int c = a + b;
            a = b;
            b = c;

            // Check if current Fibonacci number is prime
            if (isPrime(c)) {
                count++;
                if (count == n) {
                    return c;
                }
            }

            // Also check the initial 2 if we haven't started properly
            // But since we start with a=1, b=1, then c=2 on first iteration
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

