class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Helper function to evaluate polynomial at x
        java.util.function.DoubleUnaryOperator polyFunc = x -> {
            double result = 0;
            double xPower = 1;
            for (double coeff : xs) {
                result += coeff * xPower;
                xPower *= x;
            }
            return result;
        };

        double f = polyFunc.applyAsDouble(0);

        // Find an interval [a, b] where f(a) * f(b) < 0
        double a = -1000.0;
        double b = 1000.0;

        double fa = polyFunc.applyAsDouble(a);
        double fb = polyFunc.applyAsDouble(b);

        // Expand interval until we find opposite signs
        int maxAttempts = 50;
        for (int attempt = 0; attempt < maxAttempts && fa * fb >= 0; attempt++) {
            a *= 2;
            b *= 2;
            fa = polyFunc.applyAsDouble(a);
            fb = polyFunc.applyAsDouble(b);
        }

        // Bisection method to find root
        for (int i = 0; i < 100; i++) { // 100 iterations gives precision ~1e-30
            double mid = (a + b) / 2.0;
            double fm = polyFunc.applyAsDouble(mid);

            if (Math.abs(fm) < 1e-15) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        // Return midpoint as best approximation
        return (a + b) / 2.0;
    }
}

