class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 1, b = 1; // Start with F1=1, F2=1

        // Skip the first two 1s since 1 is not prime
        long fib = 2; // Start checking from F3=2

        while (true) {
            // Generate next Fibonacci number
            long next = a + b;
            a = b;
            b = next;
            fib = next;

            // Check if it's prime (skip 1 which is not prime)
            if (fib > 1 && isPrime(fib)) {
                count++;
                if (count == n) {
                    return (int) fib;
                }
            }

            // Prevent overflow for very large numbers (though test cases are small)
            if (fib < 0) {
                break;
            }
        }

        // Should not reach here with valid input
        throw new RuntimeException("Failed to find prime Fibonacci number");
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        long sqrt = (long) Math.sqrt(num);
        for (long i = 3; i <= sqrt; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

