    >>> parseMusic("o o| .| o| o| .| .| .| .| o o")
    [4, 2, 1, 2, 2, 1, 1, 1, 1, 4, 4]
     */
    public List<Integer> parseMusic(String string) {
        List<Integer> result = new ArrayList<>();

        if (string == null || string.trim().isEmpty()) {
            return result;
        }

        String[] notes = string.trim().split("\\s+");

        for (String note : notes) {
            if ("o|".equals(note)) {
                result.add(2);
            } else if (".|".equals(note)) {
                result.add(1);
            } else if ("o".equals(note)) {
                result.add(4);
            }
            // Note: Invalid notes would be ignored based on the problem statement
        }

        return result;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Handle edge cases
        if (substring == null || substring.isEmpty() || string == null) {
            return 0;
        }

        int count = 0;
        int stringLength = string.length();
        int substringLength = substring.length();

        // If substring is longer than string, no matches possible
        if (substringLength > stringLength) {
            return 0;
        }

        // Check every possible starting position
        for (int i = 0; i <= stringLength - substringLength; i++) {
            // Check if substring matches at position i
            boolean matches = true;
            for (int j = 0; j < substringLength; j++) {
                if (string.charAt(i + j) != substring.charAt(j)) {
                    matches = false;
                    break;
                }
            }

            if (matches) {
                count++;
            }
        }

        return count;
    }
}

