            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For linear case (degree 1), solve directly: a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            return -a / b;
        }

        // For higher degrees, use Newton-Raphson method
        double x = 1.0; // starting guess

        for (int i = 0; i < 100; i++) { // max iterations
            double fx = poly(xs, x);

            // Check if we're close enough to zero
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative
            double fpx = polyDerivative(xs, x);

            // If derivative is zero, try different starting point
            if (Math.abs(fpx) < 1e-10) {
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < 1e-10) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNext)) < 1e-8) {
                    return xNext;
                }
            }

            x = xNext;

            // If value becomes too large, restart from different initial point
            if (Double.isInfinite(x) || Double.isNaN(x) || Math.abs(x) > 1e6) {
                x = (i % 2 == 0) ? -1.0 : 2.0;
            }
        }

        // Fallback: return the best approximation found
        return x;
    }

    // Helper method to evaluate derivative of polynomial
    private double polyDerivative(List<Double> xs, double x) {
        double result = 0;
        // derivative of xs[0] + xs[1]*x + xs[2]*x^2 + ... is xs[1] + 2*xs[2]*x + 3*xs[3]*x^2 + ...
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

