        numberMap.put("seven", 7);
        numberMap.put("eight", 8);
        numberMap.put("nine", 9);

        // Split input into individual number words
        String[] numberWords = numbers.split("\\s+");

        // Sort the words based on their numeric values
        Arrays.sort(numberWords, (a, b) -> {
            return numberMap.get(a).compareTo(numberMap.get(b));
        });

        // Join back into a space-delimited string
        return String.join(" ", numberWords);
    }
}

