import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle linear case explicitly: ax + b = 0 => x = -b/a
        if (xs.size() == 2) {
            double a = xs.get(1);
            double b = xs.get(0);
            return -b / a;
        }

        // For higher degrees, use Newton-Raphson with multiple starting points
        // Try several initial guesses to increase chances of finding a root

        // First, find the actual degree (ignore trailing zeros)
        int degree = xs.size() - 1;
        while (degree > 0 && Math.abs(xs.get(degree)) < 1e-12) {
            degree--;
        }

        // For degree 1, already handled above
        // For degree >= 3 (odd degree), there's always at least one real root

        // Newton-Raphson implementation
        double x = 1.0; // starting point
        for (int attempt = 0; attempt < 3; attempt++) {
            // Different starting points
            if (attempt == 1) x = -1.0;
            else if (attempt == 2) x = 2.0;

            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                // Compute derivative
                double fpx = polyDerivative(xs, x);
                if (Math.abs(fpx) < 1e-12) {
                    break; // derivative too small, skip
                }

                double x_new = x - fx / fpx;

                // Check if we're diverging
                if (Double.isNaN(x_new) || Double.isInfinite(x_new) || Math.abs(x_new - x) > 1e10) {
                    break;
                }

                x = x_new;
            }
        }

        // Fallback: try bisection between -1000 and 1000
        double left = -1000.0;
        double right = 1000.0;
        double fl = poly(xs, left);
        double fr = poly(xs, right);

        // Find interval where sign changes
        while (fl * fr > 0 && (left > -1e6 || right < 1e6)) {
            left *= 2;
            right *= 2;
            fl = poly(xs, left);
            fr = poly(xs, right);
        }

        // Bisection method
        if (fl * fr <= 0) {
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fm = poly(xs, mid);
                if (Math.abs(fm) < 1e-10) {
                    return mid;
                }
                if (fl * fm <= 0) {
                    right = mid;
                    fr = fm;
                } else {
                    left = mid;
                    fl = fm;
                }
            }
            return (left + right) / 2;
        }

        // Last resort: return 0
        return 0.0;
    }

    // Helper method to compute polynomial derivative at x
    private double polyDerivative(List<Double> xs, double x) {
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += xs.get(i) * i * Math.pow(x, i - 1);
        }
        return result;
    }
}

