import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Find the highest degree term (last non-zero coefficient)
        int n = xs.size() - 1;
        double leadingCoeff = xs.get(n);

        // For odd degree polynomials, we need to find bounds where f changes sign
        // Try increasing intervals until we find a sign change

        double left = -1.0;
        double right = 1.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand search range until we have opposite signs
        int expansionCount = 0;
        while (fLeft * fRight > 0 && expansionCount < 100) {
            // Expand the interval
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            expansionCount++;
        }

        // If we still don't have sign change, use very large bounds
        if (fLeft * fRight > 0) {
            left = -1e9;
            right = 1e9;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        // Binary search for root
        for (int i = 0; i < 100; i++) { // 100 iterations gives precision ~1e-30
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

