class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 1; // F(1) = 1
        long b = 1; // F(2) = 1
        long c;

        // Check if 2 is needed (it's the first Fibonacci prime)
        // Since 1,1 are not prime, we start generating from F(3)=2

        // Handle the first few cases explicitly since F(3)=2 is the first Fibonacci prime
        if (n == 1) {
            return 2;
        }

        // Start generating Fibonacci numbers from F(3) onwards
        int fibIndex = 3;

        while (true) {
            c = a + b;

            // Check if current Fibonacci number is prime
            if (isPrime(c)) {
                count++;
                if (count == n) {
                    return (int) c;
                }
            }

            // Update for next iteration
            a = b;
            b = c;
            fibIndex++;
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

