class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Handle null inputs
        if (a == null || b == null) {
            throw new IllegalArgumentException("Inputs cannot be null");
        }

        // Pad shorter string with leading zeros to match lengths
        int lenA = a.length();
        int lenB = b.length();
        int maxLen = Math.max(lenA, lenB);

        StringBuilder sbA = new StringBuilder();
        StringBuilder sbB = new StringBuilder();

        // Pad with leading zeros
        for (int i = 0; i < maxLen - lenA; i++) {
            sbA.append('0');
        }
        sbA.append(a);

        for (int i = 0; i < maxLen - lenB; i++) {
            sbB.append('0');
        }
        sbB.append(b);

        StringBuilder result = new StringBuilder();

        // Process each character position
        for (int i = 0; i < maxLen; i++) {
            char bitA = sbA.charAt(i);
            char bitB = sbB.charAt(i);

            // XOR operation: same bits give 0, different bits give 1
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

