class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        // Map number words to their numeric values
        Map<String, Integer> wordToNum = new HashMap<>();
        wordToNum.put("zero", 0);
        wordToNum.put("one", 1);
        wordToNum.put("two", 2);
        wordToNum.put("three", 3);
        wordToNum.put("four", 4);
        wordToNum.put("five", 5);
        wordToNum.put("six", 6);
        wordToNum.put("seven", 7);
        wordToNum.put("eight", 8);
        wordToNum.put("nine", 9);

        // Split input string into individual number words
        String[] words = numbers.split(" ");

        // Create array of pairs (word, numeric value) for sorting
        List<String> resultWords = new ArrayList<>();
        List<Integer> resultValues = new ArrayList<>();

        for (String word : words) {
            if (!word.isEmpty()) {
                resultWords.add(word);
                resultValues.add(wordToNum.get(word));
            }
        }

        // Sort using the numeric values as keys
        for (int i = 0; i < resultWords.size() - 1; i++) {
            int minIndex = i;
            for (int j = i + 1; j < resultWords.size(); j++) {
                if (resultValues.get(j) < resultValues.get(minIndex)) {
                    minIndex = j;
                }
            }
            // Swap both lists
            if (minIndex != i) {
                String tempWord = resultWords.get(i);
                resultWords.set(i, resultWords.get(minIndex));
                resultWords.set(minIndex, tempWord);

                Integer tempValue = resultValues.get(i);
                resultValues.set(i, resultValues.get(minIndex));
                resultValues.set(minIndex, tempValue);
            }
        }

        // Join the sorted words back into a string
        return String.join(" ", resultWords);
    }
}

