                continue; // Ignore spaces
            }

            if (c == '(') {
                currentGroup.append(c);
                depth++;
            } else if (c == ')') {
                currentGroup.append(c);
                depth--;

                // When depth returns to 0, we've completed a balanced group
                if (depth == 0 && currentGroup.length() > 0) {
                    result.add(currentGroup.toString());
                    currentGroup.setLength(0); // Reset for next group
                }
            }
        }

        return result;
    }
}

