public double findZero(List<Double> xs) {
    // Ensure even number of coefficients as required
    if (xs.size() % 2 != 0) {
        throw new IllegalArgumentException("List must have even number of coefficients");
    }

    // Handle edge case: constant polynomial (degree 0)
    if (xs.size() == 1) {
        return 0; // or throw exception, but problem says even coefficients so this shouldn't happen
    }

    // Find the highest degree non-zero coefficient
    int n = xs.size();
    int degree = n - 1;
    int highestNonZeroIndex = -1;
    for (int i = degree; i >= 0; i--) {
        if (Math.abs(xs.get(i)) > 1e-15) {
            highestNonZeroIndex = i;
            break;
        }
    }

    // If all coefficients are zero, any x is a solution
    if (highestNonZeroIndex == -1) {
        return 0.0;
    }

    // For odd-degree polynomials (guaranteed at least one real root)
    // We'll use bisection method after finding an interval with sign change

    // Define a helper function to evaluate polynomial
    class PolyEvaluator {
        public double eval(double x) {
            double result = 0;
            double xPower = 1;
            for (int i = 0; i < xs.size(); i++) {
                result += xs.get(i) * xPower;
                xPower *= x;
            }
            return result;
        }
    }

    PolyEvaluator evaluator = new PolyEvaluator();

    // Find an interval [a, b] where f(a) * f(b) < 0 (sign change)
    double a = -1000.0;
    double b = 1000.0;

    double fa = evaluator.eval(a);
    double fb = evaluator.eval(b);

    // Expand search range if needed
    int attempts = 0;
    while (fa * fb > 0 && attempts < 20) {
        a *= 10;
        b *= 10;
        fa = evaluator.eval(a);
        fb = evaluator.eval(b);
        attempts++;
    }

    // If still no sign change, try Newton-like approach from 0
    if (fa * fb > 0) {
        // Try starting from 0 and search nearby
        for (double start = 0; start < 100; start += 10) {
            double left = start - 10;
            double right = start + 10;
            double fLeft = evaluator.eval(left);
            double fRight = evaluator.eval(right);
            if (fLeft * fRight <= 0) {
                a = left;
                b = right;
                break;
            }
        }
    }

    // Bisection method
    double tolerance = 1e-9;
    int maxIterations = 1000;

    for (int i = 0; i < maxIterations; i++) {
        double mid = (a + b) / 2;
        double fMid = evaluator.eval(mid);

        if (Math.abs(fMid) < tolerance || (b - a) / 2 < tolerance) {
            return mid;
        }

        if (fa * fMid <= 0) {
            b = mid;
            fb = fMid;
        } else {
            a = mid;
            fa = fMid;
        }
    }

    // Return midpoint as best guess
    return (a + b) / 2;
}

