        String[] notes = string.trim().split("\\s+");

        for (String note : notes) {
            if ("o".equals(note)) {
                result.add(4);
            } else if ("o|".equals(note)) {
                result.add(2);
            } else if (".|".equals(note)) {
                result.add(1);
            }
        }

        return result;
    }
}

