class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // If linear polynomial (2 coefficients), solve directly: a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) > 1e-12) {
                return -a / b;
            }
        }

        // For higher degree polynomials, use bisection method
        // Find interval where function changes sign

        // Check values at several points to find sign change
        double left = -1000.0;
        double right = 1000.0;

        // Adjust interval based on leading coefficient to ensure sign change
        double leadingCoeff = 0.0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) {
                leadingCoeff = xs.get(i);
                break;
            }
        }

        // If leading coefficient is positive, as x->∞, f(x)->∞, as x->-∞, f(x)->-∞ (odd degree)
        // If leading coefficient is negative, as x->∞, f(x)->-∞, as x->-∞, f(x)->∞

        // Try to find appropriate bounds
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand interval if needed to find sign change
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 20) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations should give good precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

