class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 0; // F(0)
        int b = 1; // F(1)

        // Handle special case: F(3) = 2 is the first Fibonacci prime
        if (n == 1) {
            return 2;
        }

        // Start generating Fibonacci numbers from F(3) onwards
        // We already know F(0)=0, F(1)=1, F(2)=1, F(3)=2

        // Check F(3) = 2
        if (isPrime(2)) {
            count++;
            if (count == n) {
                return 2;
            }
        }

        // Now generate subsequent Fibonacci numbers
        int prev = 2; // F(3)
        int curr = 3; // F(4)

        while (true) {
            // Check current Fibonacci number
            if (isPrime(curr)) {
                count++;
                if (count == n) {
                    return curr;
                }
            }

            // Generate next Fibonacci number
            int next = prev + curr;
            prev = curr;
            curr = next;
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

