class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Handle null inputs if needed (though problem states they're valid)
        if (a == null || b == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        // Ensure both strings have the same length by padding the shorter one with leading zeros
        // However, based on the example, it seems they should be the same length
        int lenA = a.length();
        int lenB = b.length();

        // Pad shorter string with leading zeros to match lengths
        StringBuilder sbA = new StringBuilder(a);
        StringBuilder sbB = new StringBuilder(b);

        while (sbA.length() < sbB.length()) {
            sbA.insert(0, '0');
        }
        while (sbB.length() < sbA.length()) {
            sbB.insert(0, '0');
        }

        // Perform XOR operation character by character
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < sbA.length(); i++) {
            char bitA = sbA.charAt(i);
            char bitB = sbB.charAt(i);

            // XOR logic: if bits are different, result is '1', else '0'
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

