class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 0;  // F(0)
        int b = 1;  // F(1)

        // Handle special cases for small Fibonacci numbers
        if (n == 1) {
            return 2;  // First prime Fibonacci
        }

        while (true) {
            int next = a + b;
            a = b;
            b = next;

            // Check if current Fibonacci number is prime and > 1
            if (next > 1 && isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }

            // Safety check to prevent overflow - Fibonacci numbers grow exponentially
            if (next < 0) {
                throw new ArithmeticException("Integer overflow occurred");
            }
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

