class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Handle null cases - though problem doesn't specify, good practice
        if (string == null || substring == null) {
            return 0;
        }

        // If substring is empty, return 0 (common convention)
        if (substring.isEmpty()) {
            return 0;
        }

        int count = 0;
        int len = string.length();
        int subLen = substring.length();

        // We can only start checking up to len - subLen
        for (int i = 0; i <= len - subLen; i++) {
            // Check if substring matches starting at position i
            if (string.substring(i, i + subLen).equals(substring)) {
                count++;
            }
        }

        return count;
    }
}

