class Solution {
    public double findZero(List<Double> xs) {
        // For linear case: xs[0] + xs[1]*x = 0 => x = -xs[0]/xs[1]
        if (xs.size() == 2) {
            return -xs.get(0) / xs.get(1);
        }

        // Use bisection method - start with a wide range and narrow down
        double left = -1000.0;
        double right = 1000.0;
        double tolerance = 1e-9;

        // Ensure we have opposite signs at endpoints
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If both same sign, expand the search range
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 10) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // enough iterations for precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint as fallback
        return (left + right) / 2.0;
    }
}

