    public int countDistinctCharacters(String string) {
        if (string == null) {
            return 0;
        }

        Set<Character> distinctChars = new HashSet<>();
        for (char c : string.toLowerCase().toCharArray()) {
            distinctChars.add(c);
        }

        return distinctChars.size();
    }
}

