    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Start from n/2 and go down to find the largest divisor
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }
        // This should never happen for n > 1, but return 1 as fallback
        // For n = 1, there's no positive divisor smaller than 1, but the problem likely assumes n > 1
        return 1;
    }
}

