class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // All other even numbers are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        // Only need to check up to sqrt(n) because if n = a*b and a <= b,
        // then a <= sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        double xPower = 1;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * xPower;
            xPower *= x;
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Use bisection method with a wide search range
        double left = -1000.0;
        double right = 1000.0;
        double eps = 1e-9;

        // Evaluate at endpoints
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If no sign change in the initial range, expand search
        int iterations = 0;
        while (fLeft * fRight > 0 && iterations < 20) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            iterations++;
        }

        // Now apply bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations should be enough for precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < eps) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint if we didn't converge to exact zero
        return (left + right) / 2.0;
    }
}

