class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle the first few Fibonacci numbers
        // F(0) = 0, F(1) = 1, F(2) = 1, F(3) = 2, F(4) = 3, etc.

        // Check F(2) = 1 (not prime), so start from F(3) = 2
        if (n == 1) {
            return 2;
        }

        // Start generating from F(3) onwards
        for (int i = 3; ; i++) {
            long fib = a + b;

            // Check if this Fibonacci number is prime
            if (fib > 1 && isPrime(fib)) {
                count++;
                if (count == n) {
                    return (int) fib;
                }
            }

            // Update Fibonacci sequence
            a = b;
            b = fib;
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

