class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Edge cases
        if (string == null || substring == null) {
            return 0;
        }

        int count = 0;
        int textLength = string.length();
        int patternLength = substring.length();

        // If substring is empty, by convention return 0
        if (patternLength == 0) {
            return 0;
        }

        // If pattern is longer than text, no matches possible
        if (patternLength > textLength) {
            return 0;
        }

        // Check each possible starting position
        for (int i = 0; i <= textLength - patternLength; i++) {
            if (string.substring(i, i + patternLength).equals(substring)) {
                count++;
            }
        }

        return count;
    }
}

