class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 1, b = 1; // First two Fibonacci numbers

        // Skip the first few Fibonacci numbers (0, 1, 1) and start checking from 2
        // We'll generate Fibonacci numbers and check for primality

        // Handle special case: first prime Fibonacci is 2
        if (n == 1) {
            return 2;
        }

        count = 1; // We've found 2 as the first prime Fibonacci

        // Start generating from the next Fibonacci numbers
        int prev = 1, curr = 2; // Fibonacci sequence: 1, 2, 3, 5, 8, 13...

        while (count < n) {
            if (isPrime(curr)) {
                count++;
                if (count == n) {
                    return curr;
                }
            }

            // Generate next Fibonacci number
            int next = prev + curr;
            prev = curr;
            curr = next;
        }

        return curr; // Should not reach here if n >= 1
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

