        List<Integer> result = new ArrayList<>();
        if (numbers == null || numbers.isEmpty()) {
            return result;
        }

        int currentMax = numbers.get(0);
        for (int num : numbers) {
            if (num > currentMax) {
                currentMax = num;
            }
            result.add(currentMax);
        }

        return result;
    }
}

