        for (String note : notes) {
            switch (note) {
                case "o":
                    result.add(4);
                    break;
                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // According to the problem, only these three formats appear,
                    // but if needed, we could handle invalid inputs
                    throw new IllegalArgumentException("Invalid note format: " + note);
            }
        }

        return result;
    }
}

