class Solution {
    public double findZero(List<Double> xs) {
        // Ensure we have even number of coefficients
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("Polynomial must have even number of coefficients");
        }

        // Find the leading coefficient (largest non-zero, which should be the last non-zero)
        int degree = xs.size() - 1;
        int leadIdx = -1;
        for (int i = xs.size() - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-15) {
                leadIdx = i;
                break;
            }
        }

        if (leadIdx == -1) {
            throw new IllegalArgumentException("All coefficients are zero");
        }

        // For odd-degree polynomials (even number of coefficients), 
        // there's always at least one real root

        // Bisection method parameters
        double left = -1000.0;
        double right = 1000.0;
        double tolerance = 1e-10;
        int maxIterations = 1000;

        // Find interval where sign changes
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand search range if needed
        int expandAttempts = 0;
        while (fLeft * fRight > 0 && expandAttempts < 20) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            expandAttempts++;
        }

        // If still no sign change, use Newton-Raphson or just return midpoint
        if (fLeft * fRight > 0) {
            // Fallback: try Newton-Raphson from 0
            double x = 0.0;
            for (int i = 0; i < 100; i++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < tolerance) {
                    return x;
                }
                // Numerical derivative
                double h = 1e-8;
                double fpx = (poly(xs, x + h) - fx) / h;
                if (Math.abs(fpx) < 1e-15) {
                    x += 0.1; // small step if derivative too small
                } else {
                    x -= fx / fpx;
                }
                if (Double.isNaN(x) || Double.isInfinite(x)) {
                    x = (left + right) / 2;
                    break;
                }
            }
            return x;
        }

        // Bisection method
        for (int iter = 0; iter < maxIterations; iter++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

