class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true; // 2 and 3 are prime
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check for divisors from 5 up to sqrt(n), skipping even numbers
        // We can use the optimization that all primes > 3 are of form 6k ± 1
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // For linear case: xs[0] + xs[1]*x = 0 => x = -xs[0]/xs[1]
        if (xs.size() == 2 && Math.abs(xs.get(1)) > 1e-10) {
            return -xs.get(0) / xs.get(1);
        }

        // Use Newton-Raphson method
        double x = 0.0; // initial guess
        double epsilon = 1e-10;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative: f'(x)
            double fPrimeX = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fPrimeX += i * xs.get(i) * Math.pow(x, i - 1);
            }

            // Avoid division by zero
            if (Math.abs(fPrimeX) < epsilon) {
                // Try a different starting point or use small perturbation
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fPrimeX;

            // Check for convergence
            if (Math.abs(xNext - x) < epsilon) {
                return xNext;
            }

            x = xNext;
        }

        // Return best approximation after max iterations
        return x;
    }
}

