class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        int n = xs.size() - 1; // degree of polynomial

        // Helper function to evaluate polynomial and its derivative
        double[] coeffs = xs.stream().mapToDouble(Double::doubleValue).toArray();

        // If degree 1, solve directly
        if (n == 1) {
            return -coeffs[0] / coeffs[1];
        }

        // Newton-Raphson method
        double x = 1.0; // initial guess
        for (int i = 0; i < 50; i++) {
            double fx = 0;
            double fpx = 0;

            // Evaluate polynomial and derivative
            for (int j = 0; j <= n; j++) {
                fx += coeffs[j] * Math.pow(x, j);
            }
            for (int j = 1; j <= n; j++) {
                fpx += j * coeffs[j] * Math.pow(x, j - 1);
            }

            if (Math.abs(fpx) < 1e-10) {
                // Derivative too small, try different starting point
                x = x + 0.1;
                continue;
            }

            double xNext = x - fx / fpx;
            if (Math.abs(xNext - x) < 1e-9) {
                break;
            }
            x = xNext;
        }

        return x;
    }
}

