    >>> filterBySubstring(Arrays.asList("abc", "bacd", "cde", "array"), "a")
    ["abc", "bacd", "array"]
     */
    public List<String> filterBySubstring(List<String> strings, String substring) {
        // Handle null cases - if substring is null, no string can contain it
        if (substring == null) {
            return new ArrayList<>();
        }

        // Create result list
        List<String> result = new ArrayList<>();

        // If input list is null, return empty list
        if (strings == null) {
            return result;
        }

        // Iterate through each string and check if it contains the substring
        for (String str : strings) {
            // Only add if string is not null and contains the substring
            if (str != null && str.contains(substring)) {
                result.add(str);
            }
        }

        return result;
    }
}

