class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Handle null cases using safe pattern (though problem states inputs are valid)
        if (a == null || b == null) {
            return null;
        }

        // Check if lengths are equal
        if (a.length() != b.length()) {
            // According to the problem context, inputs should be same length
            // but we'll handle by using the minimum length or could throw exception
            // For this problem, assuming same length as per example
            return "";
        }

        StringBuilder result = new StringBuilder();

        for (int i = 0; i < a.length(); i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            // XOR operation: same bits produce 0, different bits produce 1
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

