class Solution {
    public int largestDivisor(int n) {
        // Edge cases
        if (n <= 1) {
            return 0; // or handle as needed, but problem likely assumes n > 1
        }

        // For n > 1, the largest proper divisor
        if (n % 2 == 0) {
            return n / 2;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return n / i;
            }
        }

        // If we reach here, n is prime, so largest proper divisor is 1
        return 1;
    }
}

