class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // For linear case (2 coefficients): a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) > 1e-12) {
                return -a / b;
            }
        }

        // For quadratic case (4 coefficients would be cubic, so actually xs.size() == 3 for quadratic)
        // Wait, the problem says even number of coefficients, so 2, 4, 6...
        // So for xs.size() == 2: linear (degree 1)
        // xs.size() == 4: cubic (degree 3)
        // xs.size() == 6: quintic (degree 5)
        // These are all odd-degree polynomials (since degree = n-1, and n is even => degree is odd)
        // Odd-degree polynomials always have at least one real root

        // Use Newton-Raphson method
        double x = 1.0; // Initial guess
        double epsilon = 1e-9;
        int maxIterations = 100;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);

            // If we're close enough to zero, return
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative numerically
            double h = 1e-7;
            double fpx = (poly(xs, x + h) - fx) / h;

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-12) {
                fpx = 1e-12; // Small non-zero value to avoid division by zero
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < epsilon) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNext)) < epsilon) {
                    return xNext;
                }
            }

            x = xNext;
        }

        // Fallback: return the best approximation found
        return x;
    }
}

