        if (l.isEmpty()) {
            throw new IllegalArgumentException("List cannot be empty");
        }

        // Initialize max with the first element
        int max = l.get(0);

        // Iterate through the rest of the list to find maximum
        for (int i = 1; i < l.size(); i++) {
            Integer current = l.get(i);
