class Solution {
    public List<Double> findClosestElements(List<Double> numbers) {
        // Create a copy to avoid modifying the original list
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        double minDiff = Math.abs(sorted.get(1) - sorted.get(0));
        int minIndex = 0;

        // Check all adjacent pairs
        for (int i = 1; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < minDiff) {
                minDiff = diff;
                minIndex = i;
            }
        }

        // Return the pair in ascending order (sorted already, so just return adjacent pair)
        double a = sorted.get(minIndex);
        double b = sorted.get(minIndex + 1);

        // Ensure smaller number comes first (though sorting should guarantee this)
        if (a <= b) {
            return Arrays.asList(a, b);
        } else {
            return Arrays.asList(b, a);
        }
    }
}

