class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Edge case: n <= 1 has no proper divisors
        if (n <= 1) {
            return -1; // or handle as needed, but problem implies n > 1
        }

        // Check if n is even
        if (n % 2 == 0) {
            return n / 2;
        }

        // Find the smallest prime factor (starting from 3)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return n / i;
            }
        }

        // If no factor found, n is prime, so largest proper divisor is 1
        return 1;
    }
}

