class Solution {
    /**
    Filter an input list of strings only for ones that start with a given prefix.
    >>> filterByPrefix(List.of(), "a")
    []
    >>> filterByPrefix(Arrays.asList("abc", "bcd", "cde", "array"), "a")
    ["abc", "array"]
     */
    public List<String> filterByPrefix(List<String> strings, String prefix) {
        if (strings == null) {
            return new ArrayList<>();
        }

        if (prefix == null) {
            // If prefix is null, no strings can start with it (unless they're also null, but strings in a List<String> shouldn't be null based on the type)
            return new ArrayList<>();
        }

        return strings.stream()
                .filter(s -> s != null && s.startsWith(prefix))
                .collect(Collectors.toList());
    }
}

