class Solution {
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
            // Newton-Raphson method
            double x = 1.0; // initial guess

            // Perform 50 iterations of Newton-Raphson
            for (int i = 0; i < 50; i++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                // Compute derivative at x
                double fPrimeX = 0;
                for (int j = 1; j < xs.size(); j++) {
                    fPrimeX += j * xs.get(j) * Math.pow(x, j - 1);
                }

                // Avoid division by zero
                if (Math.abs(fPrimeX) < 1e-10) {
                    // Try a different initial guess
                    x = (x > 0) ? x - 1.0 : x + 1.0;
                    continue;
                }

                double xNext = x - fx / fPrimeX;

                // Check if converged
                if (Math.abs(xNext - x) < 1e-10) {
                    break;
                }

                x = xNext;
            }

            return x;
        }
}

