class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 1, b = 1; // First two Fibonacci numbers

        // Check the first few Fibonacci numbers manually for small n
        if (n == 1) {
            return 2; // Third Fibonacci number (1, 1, 2)
        }

        // Start generating from the third Fibonacci number
        int index = 3;
        while (true) {
            long fib = a + b;
            a = b;
            b = fib;

            if (isPrime(fib)) {
                count++;
                if (count == n) {
                    return (int) fib;
                }
            }

            index++;
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

