class Solution {
    /**
    Check if in given list of numbers, are any two numbers closer to each other than given threshold.
    >>> hasCloseElements(Arrays.asList(1.0, 2.0, 3.0), 0.5)
    false
    >>> hasCloseElements(Arrays.asList(1.0, 2.8, 3.0, 4.0, 5.0, 2.0), 0.3)
    true
     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        // Handle edge cases
        if (numbers == null || numbers.size() < 2) {
            return false;
        }

        // Create a copy to avoid modifying the original list
        List<Double> sortedNumbers = new ArrayList<>(numbers);
        Collections.sort(sortedNumbers);

        // Check adjacent pairs only - if the list is sorted, 
        // the minimum difference for any element will be with one of its neighbors
        for (int i = 0; i < sortedNumbers.size() - 1; i++) {
            double diff = Math.abs(sortedNumbers.get(i + 1) - sortedNumbers.get(i));
            if (diff < threshold) {
                return true;
            }
        }

        return false;
    }
}

