        if (substring == null) {
            // If substring is null, no string can contain it, so return empty list
            return new ArrayList<>();
        }

        List<String> result = new ArrayList<>();

        for (String str : strings) {
            // Skip null strings or check if they contain the substring
            if (str != null && str.contains(substring)) {
                result.add(str);
            }
        }

        return result;
    }
}

