class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Check if number of coefficients is even
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("Number of coefficients must be even");
        }

        // Find the leading coefficient (last non-zero)
        int n = xs.size();
        int leadingIndex = -1;
        for (int i = n - 1; i >= 0; i--) {
            if (!Double.isNaN(xs.get(i)) && !Double.isInfinite(xs.get(i)) && xs.get(i) != 0.0) {
                leadingIndex = i;
                break;
            }
        }

        if (leadingIndex == -1) {
            // All coefficients are zero
            return 0.0;
        }

        // Leading coefficient should be non-zero (guaranteed by problem statement)
        double leadingCoeff = xs.get(leadingIndex);

        // For odd degree polynomials (leadingIndex is even, since index = degree)
        // we know a real root exists

        // Define function as lambda
        final List<Double> coeffs = xs;

        // Helper function to evaluate polynomial
        java.util.function.DoubleUnaryOperator f = (double x) -> {
            double result = 0.0;
            double xPower = 1.0;
            for (int i = 0; i < coeffs.size(); i++) {
                result += coeffs.get(i) * xPower;
                xPower *= x;
            }
            return result;
        };

        // Find bounds where f changes sign
        double left = -1.0;
        double right = 1.0;
        double fLeft = f.applyAsDouble(left);
        double fRight = f.applyAsDouble(right);

        // Expand until we find sign change
        int attempts = 0;
        while (fLeft * fRight >= 0 && attempts < 30) {
            left *= 2.0;
            right *= 2.0;
            fLeft = f.applyAsDouble(left);
            fRight = f.applyAsDouble(right);
            attempts++;
        }

        // If still no sign change, try asymmetric expansion
        if (fLeft * fRight >= 0) {
            left = -1000.0;
            right = 1000.0;
            fLeft = f.applyAsDouble(left);
            fRight = f.applyAsDouble(right);
            attempts = 0;
            while (fLeft * fRight >= 0 && attempts < 50) {
                left *= 2.0;
                right *= 2.0;
                fLeft = f.applyAsDouble(left);
                fRight = f.applyAsDouble(right);
                attempts++;
            }
        }

        // Bisection method
        double tolerance = 1e-9;
        int maxIterations = 100;

        for (int i = 0; i < maxIterations; i++) {
            double mid = (left + right) / 2.0;
            double fMid = f.applyAsDouble(mid);

            if (Math.abs(fMid) < tolerance) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

