class Solution {
    /**
    Out of list of strings, return the longest one. Return the first one in case of multiple
    strings of the same length. Return None in case the input list is empty.
    >>> longest(List.of())
    Optional.empty
    >>> longest(Arrays.asList("a", "b", "c"))
    Optional[a]
    >>> longest(Arrays.asList("a", "bb", "ccc"))
    Optional[ccc]
     */
    public Optional<String> longest(List<String> strings) {
        if (strings == null || strings.isEmpty()) {
            return Optional.empty();
        }

        String longest = null;
        int maxLength = -1;

        for (String s : strings) {
            // Handle null strings - skip them or treat as length 0
            // Based on typical expectations, we should handle null safely
            if (s == null) {
                continue;
            }

            if (s.length() > maxLength) {
                maxLength = s.length();
                longest = s;
            }
            // Note: We use > not >= to keep the first occurrence when lengths are equal
        }

        return Optional.ofNullable(longest);
    }
}

