class Solution {
    public double findZero(List<Double> xs) {
        // Convert to array for faster access
        double[] coeffs = new double[xs.size()];
        for (int i = 0; i < xs.size(); i++) {
            coeffs[i] = xs.get(i);
        }

        // Find the degree (highest non-zero coefficient index)
        int degree = xs.size() - 1;

        // For odd-degree polynomials, we know there's at least one real root
        // Use bisection method with a wide search range

        // First, find an interval [a, b] where f(a) * f(b) < 0
        double a = -1000.0;
        double b = 1000.0;

        // Expand search range if needed
        while (poly(coeffs, a) * poly(coeffs, b) > 0) {
            a *= 2;
            b *= 2;
            // Safety limit to avoid infinite loop
            if (Math.abs(a) > 1e9) {
                // Fallback: try Newton's method or return midpoint
                break;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives good precision
            double mid = (a + b) / 2.0;
            double fMid = poly(coeffs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (poly(coeffs, a) * fMid < 0) {
                b = mid;
            } else {
                a = mid;
            }
        }

        return (a + b) / 2.0;
    }

    // Helper method using array for efficiency
    private double poly(double[] coeffs, double x) {
        double result = 0;
        double xPower = 1;
        for (int i = 0; i < coeffs.length; i++) {
            result += coeffs[i] * xPower;
            xPower *= x;
        }
        return result;
    }
}

