        for (String note : notes) {
            switch (note) {
                case "o":
                    result.add(4);
                    break;
                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // According to the problem, we assume valid input, 
                    // but if needed, could add error handling or skip
                    break;
            }
        }

        return result;
    }
}

