        Arrays.sort(words, (a, b) -> {
            int valA = wordToDigit.get(a);
            int valB = wordToDigit.get(b);
            return Integer.compare(valA, valB);
        });

        // Join sorted words back into a string
        return String.join(" ", words);
    }
}

