class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: constant polynomial (shouldn't happen due to even coefficients requirement)
        if (xs.size() <= 1) {
            return 0.0;
        }

        // Create polynomial function
        java.util.function.DoubleUnaryOperator f = x -> poly(xs, x);

        // Since it's odd-degree (even number of coefficients), it must cross zero
        // Try to find an interval where sign changes
        double left = -1000.0;
        double right = 1000.0;

        double fLeft = f.applyAsDouble(left);
        double fRight = f.applyAsDouble(right);

        // Ensure we have a sign change
        while (fLeft * fRight > 0 && (Math.abs(left) < 1e6 || Math.abs(right) < 1e6)) {
            left *= 2;
            right *= 2;
            fLeft = f.applyAsDouble(left);
            fRight = f.applyAsDouble(right);
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = f.applyAsDouble(mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

