class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Remove trailing zeros (leading coefficients that are zero)
        int n = xs.size();
        int lastNonZero = n - 1;
        while (lastNonZero >= 0 && Math.abs(xs.get(lastNonZero)) < 1e-12) {
            lastNonZero--;
        }

        if (lastNonZero < 0) {
            // All coefficients are zero
            return 0.0;
        }

        // Create a trimmed list without trailing zeros
        List<Double> trimmed = xs.subList(0, lastNonZero + 1);

        // For linear case (degree 1): ax + b = 0 => x = -b/a
        if (trimmed.size() == 2) {
            double a = trimmed.get(1);
            double b = trimmed.get(0);
            if (Math.abs(a) > 1e-12) {
                return -b / a;
            }
        }

        // For higher degrees, use numerical method
        // Use Newton-Raphson with multiple starting points to increase chances of convergence

        double[] startPoints = {-100.0, -10.0, -1.0, 0.0, 1.0, 10.0, 100.0};

        for (double start : startPoints) {
            double root = newtonRaphson(trimmed, start);
            if (!Double.isNaN(root) && !Double.isInfinite(root)) {
                // Verify it's actually a root
                double value = poly(trimmed, root);
                if (Math.abs(value) < 1e-6) {
                    return root;
                }
            }
        }

        // Fallback: try bisection on a wide range
        for (double left = -100.0, right = 100.0; left < right; ) {
            double mid = (left + right) / 2.0;
            double fMid = poly(trimmed, mid);

            if (Math.abs(fMid) < 1e-6) {
                return mid;
            }

            // Try to find interval with sign change
            double fLeft = poly(trimmed, left);
            double fRight = poly(trimmed, right);

            if (fLeft * fMid < 0) {
                right = mid;
            } else if (fRight * fMid < 0) {
                left = mid;
            } else {
                // Expand search range
                left -= 100.0;
                right += 100.0;
                if (left < -1000.0) break; // Give up
            }
        }

        // As last resort, return midpoint of search range
        return 0.0;
    }

    private double newtonRaphson(List<Double> coeffs, double startX) {
        double x = startX;
        for (int i = 0; i < 100; i++) { // Max iterations
            double fx = poly(coeffs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative
            double fPrime = 0;
            for (int j = 1; j < coeffs.size(); j++) {
                fPrime += j * coeffs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(fPrime) < 1e-12) {
                return Double.NaN; // Derivative too small, skip
            }

            double xNext = x - fx / fPrime;

            // Check for divergence
            if (Double.isInfinite(xNext) || Double.isNaN(xNext)) {
                return Double.NaN;
            }

            if (Math.abs(xNext - x) < 1e-12) {
                return xNext;
            }

            x = xNext;
        }

        return x;
    }
}

