import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Define the polynomial function
        java.util.function.DoubleUnaryOperator f = x -> poly(xs, x);

        double left = -1000.0;
        double right = 1000.0;

        // Expand interval until we find a sign change
        double fLeft = f.applyAsDouble(left);
        double fRight = f.applyAsDouble(right);

        // If no sign change, expand interval
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 30) {
            left *= 2;
            right *= 2;
            fLeft = f.applyAsDouble(left);
            fRight = f.applyAsDouble(right);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations for precision
            double mid = (left + right) / 2.0;
            double fMid = f.applyAsDouble(mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

