class Solution {
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 0; // F(0)
        int b = 1; // F(1)

        // Check if 2 is the first prime Fibonacci (we'll handle 2 specially since it's prime)
        // Actually, let's generate Fibonacci numbers and check for primality

        while (true) {
            int next = a + b;
            a = b;
            b = next;

            // Skip 0 and 1 as they are not prime
            if (next < 2) {
                continue;
            }

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

