class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Make both strings the same length by padding with leading zeros
        int maxLen = Math.max(a.length(), b.length());
        StringBuilder sbA = new StringBuilder();
        StringBuilder sbB = new StringBuilder();

        // Pad string a with leading zeros
        for (int i = 0; i < maxLen - a.length(); i++) {
            sbA.append('0');
        }
        sbA.append(a);

        // Pad string b with leading zeros
        for (int i = 0; i < maxLen - b.length(); i++) {
            sbB.append('0');
        }
        sbB.append(b);

        // Perform XOR on each bit
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < maxLen; i++) {
            char bitA = sbA.charAt(i);
            char bitB = sbB.charAt(i);

            // XOR: if bits are different, result is '1', otherwise '0'
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

