class Solution {
    public double findZero(List<Double> xs) {
            // Handle edge case: empty list or all zeros
            if (xs == null || xs.isEmpty()) {
                return 0.0;
            }

            // Find the highest degree non-zero coefficient
            int n = xs.size() - 1; // degree of polynomial
            int leadingIndex = -1;
            for (int i = xs.size() - 1; i >= 0; i--) {
                if (Math.abs(xs.get(i)) > 1e-12) {
                    leadingIndex = i;
                    break;
                }
            }

            // If all coefficients are zero, any x is a solution
            if (leadingIndex == -1) {
                return 0.0;
            }

            // Evaluate polynomial at a point
            java.util.function.DoubleUnaryOperator f = (double x) -> {
                double result = 0.0;
                double xPower = 1.0;
                for (int i = 0; i < xs.size(); i++) {
                    result += xs.get(i) * xPower;
                    xPower *= x;
                }
                return result;
            };

            // For odd-degree polynomials (even number of coefficients), 
            // there's always at least one real root
            // Use bisection method on a sufficiently large interval

            double left = -1000.0;
            double right = 1000.0;

            // Expand interval until we have opposite signs at endpoints
            while (f.applyAsDouble(left) * f.applyAsDouble(right) > 0) {
                left *= 10;
                right *= 10;
                // Safety check to prevent infinite loop
                if (Math.abs(left) > 1e9) {
                    // Fallback: try Newton's method starting from 0
                    double x = 0.0;
                    for (int iter = 0; iter < 100; iter++) {
                        double fx = f.applyAsDouble(x);
                        // Numerical derivative
                        double eps = 1e-9;
                        double fpx = (f.applyAsDouble(x + eps) - fx) / eps;
                        if (Math.abs(fpx) < 1e-12) {
                            x += 0.1; // perturb if derivative too small
                            continue;
                        }
                        double xNext = x - fx / fpx;
                        if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                            x += 0.1;
                            continue;
                        }
                        if (Math.abs(xNext - x) < 1e-12) {
                            return xNext;
                        }
                        x = xNext;
                    }
                    return x;
                }
            }

            // Bisection method
            double mid = 0.0;
            for (int i = 0; i < 100; i++) { // 100 iterations gives ~1e-30 precision
                mid = (left + right) / 2.0;
                double fm = f.applyAsDouble(mid);

                if (Math.abs(fm) < 1e-12) {
                    return mid;
                }

                if (f.applyAsDouble(left) * fm < 0) {
                    right = mid;
                } else {
                    left = mid;
                }
            }

            return mid;
        }
}

