class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method to find a root
        double x = 1.0; // initial guess

        // Maximum iterations to prevent infinite loop
        int maxIterations = 100;
        double tolerance = 1e-10;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);

            // If we're close enough to zero, return
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative: f'(x) = sum_{i=1}^{n-1} i * xs[i] * x^(i-1)
            double fpx = 0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-15) {
                // Slightly perturb x and try again
                x += 0.1;
                continue;
            }

            // Newton's step
            x = x - fx / fpx;
        }

        // Fallback: if we didn't converge, return the best guess
        return x;
    }
}

