class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Handle null inputs
        if (a == null || b == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        // Ensure both strings have the same length by padding with leading zeros
        int maxLen = Math.max(a.length(), b.length());
        StringBuilder sbA = new StringBuilder();
        StringBuilder sbB = new StringBuilder();

        // Pad shorter string with leading zeros
        for (int i = 0; i < maxLen - a.length(); i++) {
            sbA.append('0');
        }
        sbA.append(a);

        for (int i = 0; i < maxLen - b.length(); i++) {
            sbB.append('0');
        }
        sbB.append(b);

        // Perform XOR operation bit by bit
        StringBuilder result = new StringBuilder(maxLen);
        for (int i = 0; i < maxLen; i++) {
            char bitA = sbA.charAt(i);
            char bitB = sbB.charAt(i);

            // XOR: same bits give 0, different bits give 1
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

