class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Ensure even number of coefficients (odd degree polynomial)
        int n = xs.size();
        if (n % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Find the highest non-zero coefficient to determine actual degree
        int degree = n - 1;
        while (degree > 0 && Math.abs(xs.get(degree)) < 1e-15) {
            degree--;
        }

        // If constant polynomial (degree 0), no root unless it's zero
        if (degree == 0) {
            if (Math.abs(xs.get(0)) < 1e-15) {
                return 0.0; // every point is a root, return 0
            } else {
                throw new IllegalArgumentException("Constant polynomial with no roots");
            }
        }

        // Use Newton-Raphson method with multiple starting points
        // Try various initial guesses to find a root
        for (double startX = -10.0; startX <= 10.0; startX += 2.0) {
            double x = startX;
            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                // Compute derivative
                double fpx = 0.0;
                for (int i = 1; i < xs.size(); i++) {
                    fpx += xs.get(i) * i * Math.pow(x, i - 1);
                }

                // Avoid division by zero or very small numbers
                if (Math.abs(fpx) < 1e-10) {
                    break; // try next starting point
                }

                double newX = x - fx / fpx;

                // Check if we've converged or gone too far
                if (Double.isNaN(newX) || Double.isInfinite(newX) || Math.abs(newX - x) < 1e-12) {
                    break;
                }

                x = newX;
            }
        }

        // Fallback: use bisection method between -100 and 100
        double left = -100.0;
        double right = 100.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If signs are different, bisection should work
        if (fLeft * fRight <= 0) {
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2.0;
                double fMid = poly(xs, mid);

                if (Math.abs(fMid) < 1e-10) {
                    return mid;
                }

                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
            return (left + right) / 2.0;
        }

        // If bisection didn't work, try scanning for sign changes
        for (double x = -50.0; x < 50.0; x += 0.5) {
            double fx = poly(xs, x);
            double fNext = poly(xs, x + 0.5);
            if (fx * fNext <= 0) {
                // Root between x and x+0.5, use bisection in this interval
                double leftBound = x;
                double rightBound = x + 0.5;
                for (int i = 0; i < 50; i++) {
                    double mid = (leftBound + rightBound) / 2.0;
                    double fMid = poly(xs, mid);
                    if (Math.abs(fMid) < 1e-10) {
                        return mid;
                    }
                    if (poly(xs, leftBound) * fMid <= 0) {
                        rightBound = mid;
                    } else {
                        leftBound = mid;
                    }
                }
                return (leftBound + rightBound) / 2.0;
            }
        }

        // Last resort: return midpoint of range
        return 0.0;
    }
}

