class Solution {
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Create a function to evaluate polynomial
        // Use bisection method to find a root

        double left = -1000.0;
        double right = 1000.0;

        // First, try to find an interval where the function changes sign
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If we're lucky and already have a root
        if (Math.abs(fLeft) < 1e-9) return left;
        if (Math.abs(fRight) < 1e-9) return right;

        // Expand the search interval until we find sign change
        while (fLeft * fRight > 0) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);

            // Safety check to avoid infinite loop
            if (Math.abs(left) > 1e7) {
                // Fallback: try Newton's method starting from 0
                return newtonRaphson(xs, 0.0);
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // enough iterations for double precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint if we didn't find exact root
        return (left + right) / 2.0;
    }

    // Helper method for Newton-Raphson as fallback
    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 50; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-9) {
                return x;
            }

            // Compute derivative numerically
            double h = 1e-9;
            double fPrime = (poly(xs, x + h) - poly(xs, x)) / h;

            if (Math.abs(fPrime) < 1e-12) {
                x += 1.0; // perturb if derivative is too small
                continue;
            }

            x = x - fx / fPrime;

            // Check bounds
            if (Double.isNaN(x) || Double.isInfinite(x)) {
                x = x0 + (i % 2 == 0 ? 1 : -1) * (i + 1);
            }
        }
        return x;
    }
}

