class Solution {
    public List<Double> findClosestElements(List<Double> numbers) {
        // Create a copy to avoid modifying the original list
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        double minDiff = Math.abs(sorted.get(1) - sorted.get(0));
        int bestIndex = 0;

        // Check all adjacent pairs
        for (int i = 1; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < minDiff) {
                minDiff = diff;
                bestIndex = i;
            }
        }

        // Return the pair with smallest difference in ascending order
        double num1 = sorted.get(bestIndex);
        double num2 = sorted.get(bestIndex + 1);

        // Ensure smaller number comes first
        if (num1 <= num2) {
            return Arrays.asList(num1, num2);
        } else {
            return Arrays.asList(num2, num1);
        }
    }
}

