class Solution {
    public List<Double> rescaleToUnit(List<Double> numbers) {
        if (numbers == null || numbers.isEmpty()) {
            return new ArrayList<>();
        }

        // Find min and max values
        double min = Double.MAX_VALUE;
        double max = Double.MIN_VALUE;

        for (Double num : numbers) {
            if (num != null) {
                min = Math.min(min, num);
                max = Math.max(max, num);
            }
        }

        // Create result list
        List<Double> result = new ArrayList<>(numbers.size());

        // Handle edge case where all values are the same
        if (min == max) {
            // All values are identical, map them all to 0.0 (or could use 0.5)
            for (int i = 0; i < numbers.size(); i++) {
                result.add(0.0);
            }
        } else {
            // Apply the rescaling formula
            double range = max - min;
            for (Double num : numbers) {
                if (num != null) {
                    result.add((num - min) / range);
                } else {
                    result.add(null);
                }
            }
        }

        return result;
    }
}

