class Solution {
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        int sqrtN = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Use Horner's method for better numerical stability and efficiency
        double result = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For linear case: [a, b] -> a + bx = 0 -> x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            return -a / b;
        }

        // Use Newton-Raphson method for higher degrees
        // We need to find a good starting point and handle derivative

        // Try to find initial bracket using the fact that odd-degree polynomials go to ±infinity
        double left = -1000.0;
        double right = 1000.0;

        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Since it's odd degree, we expect f(left) and f(right) to have opposite signs for large enough range
        // But let's ensure we have a bracket by expanding if needed
        int iterations = 0;
        while (fLeft * fRight > 0 && iterations < 10) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            iterations++;
        }

        // Bisection method - guaranteed to converge for continuous function with sign change
        for (int i = 0; i < 100; i++) { // 100 iterations gives precision ~1e-30
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint as fallback
        return (left + right) / 2.0;
    }
}

