class Solution {
    public List<Double> findClosestElements(List<Double> numbers) {
        // Create a copy of the list to avoid modifying the original
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        double minDiff = Double.MAX_VALUE;
        int minIndex = 0;

        // Check adjacent pairs for minimum difference
        for (int i = 0; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < minDiff) {
                minDiff = diff;
                minIndex = i;
            }
        }

        // Return the pair in order (smaller, larger)
        double num1 = sorted.get(minIndex);
        double num2 = sorted.get(minIndex + 1);

        return Arrays.asList(Math.min(num1, num2), Math.max(num1, num2));
    }
}

