class Solution {
    public double findZero(List<Double> xs) {
            // Use bisection method with bracketing
            // First, find an interval [a, b] where f(a) * f(b) < 0

            // Try increasing intervals until we find a sign change
            double a = -1000.0;
            double b = 1000.0;

            // Check if we already have a root at endpoints or nearby
            double fa = poly(xs, a);
            double fb = poly(xs, b);

            // If no sign change, expand search range
            int attempts = 0;
            while (fa * fb > 0 && attempts < 10) {
                a *= 10;
                b *= 10;
                fa = poly(xs, a);
                fb = poly(xs, b);
                attempts++;
            }

            // If still no sign change, try smaller intervals around 0
            if (fa * fb > 0) {
                a = -10.0;
                b = 10.0;
                fa = poly(xs, a);
                fb = poly(xs, b);
                attempts = 0;
                while (fa * fb > 0 && attempts < 20) {
                    a -= 10;
                    b += 10;
                    fa = poly(xs, a);
                    fb = poly(xs, b);
                    attempts++;
                }
            }

            // Bisection method
            for (int i = 0; i < 100; i++) {
                double mid = (a + b) / 2;
                double fm = poly(xs, mid);

                if (Math.abs(fm) < 1e-10 || (b - a) < 1e-10) {
                    return mid;
                }

                if (fa * fm <= 0) {
                    b = mid;
                    fb = fm;
                } else {
                    a = mid;
                    fa = fm;
                }
            }

            return (a + b) / 2;
        }
}

