class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true;
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check for divisors from 5 up to sqrt(n), skipping even numbers
        // Use 6k ± 1 optimization: all primes > 3 are of form 6k±1
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Newton-Raphson method
        // Start with initial guess
        double x = 1.0;
        double epsilon = 1e-10;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // If close enough to zero, return
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative using finite difference or analytically
            double fxDeriv = derivative(xs, x);

            // Avoid division by zero
            if (Math.abs(fxDeriv) < epsilon) {
                // Try perturbing x slightly
                x += 0.01;
                continue;
            }

            double xNew = x - fx / fxDeriv;

            // Check for convergence
            if (Math.abs(xNew - x) < epsilon) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNew)) < epsilon) {
                    return xNew;
                }
            }

            x = xNew;
        }

        // Fallback: if we didn't converge, return current x anyway
        return x;
    }

    // Helper method to compute derivative at point x
    private double derivative(List<Double> xs, double x) {
        if (xs.size() <= 1) {
            return 0;
        }

        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

