     */
    public boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For linear case: [a, b] -> ax + b = 0 -> x = -b/a
        if (xs.size() == 2) {
            double a = xs.get(1);
            double b = xs.get(0);
            return -b / a;
        }

        // For higher degrees, use Newton-Raphson method
        // Start with a reasonable initial guess

        // Find the highest degree term (last non-zero coefficient)
        int n = xs.size() - 1;
        double leadingCoeff = xs.get(n);

        // Initial guess: for large |x|, polynomial behaves like leadingCoeff * x^n
        // So try x = sign(leadingCoeff) * 10 or something similar
        double x = 1.0;

        // Try different starting points if needed, but Newton-Raphson usually converges well
        for (int iter = 0; iter < 100; iter++) {
            double fx = poly(xs, x);

            // If close enough to zero, return
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative numerically
            double h = 1e-8;
            double fpx = (poly(xs, x + h) - poly(xs, x - h)) / (2 * h);

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-12) {
                // Slightly perturb x and try again
                x = x + (Math.random() - 0.5) * 0.1;
                continue;
            }

            double xNew = x - fx / fpx;

            // Check for convergence or divergence
            if (Double.isNaN(xNew) || Double.isInfinite(xNew)) {
                // Try bisection fallback
                return bisect(xs, -10.0, 10.0);
            }

            // Check if we're getting closer
            if (Math.abs(xNew - x) < 1e-12) {
                return xNew;
            }

            x = xNew;
        }

        // Fallback: bisection method over a wide range
        return bisect(xs, -100.0, 100.0);
    }

    // Bisection method helper
    private double bisect(List<Double> xs, double left, double right) {
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Ensure we have opposite signs
        if (fLeft * fRight > 0) {
            // Try expanding the interval
            for (int i = 0; i < 10; i++) {
                left *= 2;
                right *= 2;
                fLeft = poly(xs, left);
                fRight = poly(xs, right);
                if (fLeft * fRight <= 0) break;
            }
            // If still no sign change, give up and return midpoint
            if (fLeft * fRight > 0) {
                return (left + right) / 2;
            }
        }

        for (int iter = 0; iter < 100; iter++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

