class Solution {
    public List<Double> findClosestElements(List<Double> numbers) {
        if (numbers == null || numbers.size() < 2) {
            throw new IllegalArgumentException("List must contain at least two elements");
        }

        // Create a copy and sort it
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        double minDiff = Math.abs(sorted.get(1) - sorted.get(0));
        int minIndex = 0;

        // Find the pair with minimum difference
        for (int i = 1; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < minDiff) {
                minDiff = diff;
                minIndex = i;
            }
        }

        // Return the pair in ascending order (already sorted, so just return consecutive elements)
        double first = sorted.get(minIndex);
        double second = sorted.get(minIndex + 1);

        // Ensure smaller number comes first (though in sorted list first <= second)
        if (first > second) {
            return Arrays.asList(second, first);
        } else {
            return Arrays.asList(first, second);
        }
    }
}

