        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Remove trailing zeros to get actual degree
        int n = xs.size();
        while (n > 0 && Math.abs(xs.get(n-1)) < 1e-15) {
            n--;
        }

        // Even number of coefficients means odd degree (degree = n-1)
        // So polynomial has at least one real root

        // Newton-Raphson method
        double x = 1.0; // Initial guess
        double epsilon = 1e-10;

        for (int iteration = 0; iteration < 1000; iteration++) {
            double fx = poly(xs, x);

            // Check if we've found a root
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative
            double fpx = derivative(xs, x);

            // If derivative is too small, avoid division by zero
            if (Math.abs(fpx) < 1e-15) {
                // Try a different initial guess or use bisection fallback
                x = x + 0.1;
                continue;
            }

            double xNew = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNew - x) < epsilon) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNew)) < epsilon) {
                    return xNew;
                }
            }

            x = xNew;

            // Handle overflow or extreme values
            if (Double.isNaN(x) || Double.isInfinite(x)) {
                x = 1.0; // Reset to initial guess
            }
        }

        // Fallback: return last approximation
        return x;
    }

    private double derivative(List<Double> xs, double x) {
        if (xs.size() <= 1) {
            return 0.0;
        }

        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i-1);
        }
        return result;
    }
}

