class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method to find a root
        double x = 0.0; // initial guess
        double epsilon = 1e-9;

        for (int i = 0; i < 100; i++) { // max iterations
            double fx = poly(xs, x);
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative: f'(x) = sum_{k=1}^{n} k * xs[k] * x^(k-1)
            double fpx = 0.0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(fpx) < 1e-12) {
                // Derivative too small, try a different starting point
                x = x + 1.0;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < epsilon) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNext)) < epsilon) {
                    return xNext;
                }
            }

            x = xNext;
        }

        // Fallback: return last approximation
        return x;
    }
}

