class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Generate Fibonacci numbers until we find n Fibonacci primes
        int count = 0;
        int a = 0; // F(0)
        int b = 1; // F(1)

        // Handle special case: check F(0) and F(1)
        // F(0) = 0, F(1) = 1 - neither is prime

        // Start from F(2) = 1, but we'll generate from F(3) onwards
        while (true) {
            int next = a + b;

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }

            // Update Fibonacci sequence
            a = b;
            b = next;

            // Safety check to prevent infinite loop if something goes wrong
            if (next < 0) {
                throw new ArithmeticException("Integer overflow occurred");
            }
        }
    }

    private boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        if (num <= 3) {
            return true;
        }
        if (num % 2 == 0 || num % 3 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

