class Solution {
    public int howManyTimes(String string, String substring) {
        // Handle null cases (though problem statement suggests inputs are valid)
        if (string == null || substring == null) {
            return 0;
        }

        // If substring is empty, return 0 (as per the example howManyTimes("", "a") = 0,
        // and logically empty substring shouldn't count as occurrences)
        if (substring.isEmpty()) {
            return 0;
        }

        // If string is empty but substring is not, no matches possible
        if (string.isEmpty()) {
            return 0;
        }

        int count = 0;
        int stringLength = string.length();
        int substringLength = substring.length();

        // Check each possible starting position
        for (int i = 0; i <= stringLength - substringLength; i++) {
            // Check if substring matches at position i
            if (string.substring(i, i + substringLength).equals(substring)) {
                count++;
            }
        }

        return count;
    }
}

