class Solution {
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case of empty list or single coefficient
        if (xs.isEmpty()) {
            return 0.0;
        }

        // Create a lambda for the polynomial function
        java.util.function.DoubleUnaryOperator polyFunc = x -> poly(xs, x);

        // Try to find an interval [low, high] where function changes sign
        double low = -1000.0;
        double high = 1000.0;

        // Expand search range if needed
        double fLow = polyFunc.applyAsDouble(low);
        double fHigh = polyFunc.applyAsDouble(high);

        int attempts = 0;
        while (fLow * fHigh > 0 && attempts < 20) {
            low *= 10;
            high *= 10;
            fLow = polyFunc.applyAsDouble(low);
            fHigh = polyFunc.applyAsDouble(high);
            attempts++;
        }

        // If still no sign change, try Newton-like method from 0
        if (fLow * fHigh > 0) {
            // Fallback: try starting from 0 and use gradient descent or simple iteration
            double x = 0.0;
            double step = 0.1;
            for (int i = 0; i < 1000; i++) {
                double fx = polyFunc.applyAsDouble(x);
                if (Math.abs(fx) < 1e-9) {
                    return x;
                }
                // Simple gradient descent approach: move opposite to gradient direction
                double xPlus = x + 0.001;
                double fxPlus = polyFunc.applyAsDouble(xPlus);
                double derivative = (fxPlus - fx) / 0.001;
                if (Math.abs(derivative) > 1e-9) {
                    x = x - fx / derivative; // Newton step
                } else {
                    x = x - fx * Math.signum(derivative) * step;
                }
                // Check for convergence
                if (Math.abs(polyFunc.applyAsDouble(x)) < 1e-9) {
                    return x;
                }
            }
            return x;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~30 decimal digits precision
            double mid = (low + high) / 2;
            double fMid = polyFunc.applyAsDouble(mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLow * fMid <= 0) {
                high = mid;
                fHigh = fMid;
            } else {
                low = mid;
                fLow = fMid;
            }
        }

        return (low + high) / 2;
    }
}

