class Solution {
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Handle special cases for small n
        if (n == 1) return 2;
        if (n == 2) return 3;
        if (n == 3) return 5;

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Generate Fibonacci numbers and check for primality
        while (count < n) {
            long c = a + b;
            a = b;
            b = c;

            // Skip 1 (not prime)
            if (c <= 1) {
                continue;
            }

            if (isPrime(c)) {
                count++;
                if (count == n) {
                    return (int) c;
                }
            }
        }

        return -1; // Should never reach here
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0) return false;
        if (num % 3 == 0) return num == 3;

        // Check for divisors up to sqrt(num)
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

