class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Handle special cases for small n
        if (n == 1) return 2;
        if (n == 2) return 3;
        if (n == 3) return 5;
        if (n == 4) return 13;
        if (n == 5) return 89;

        // For larger n, generate Fibonacci numbers and check for primality
        int count = 5; // We've already handled the first 5

        long a = 8; // F(6) = 8
        long b = 13; // F(7) = 13
        long c;

        while (true) {
            // Generate next Fibonacci number
            c = a + b;
            a = b;
            b = c;

            // Check if it's prime
            if (isPrime(c)) {
                count++;
                if (count == n) {
                    return (int) c;
                }
            }

            // Safety check to prevent overflow for very large numbers
            if (c > Integer.MAX_VALUE) {
                throw new ArithmeticException("Result exceeds integer range");
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;

        // Check divisors up to sqrt(num)
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

