class Solution {
    public double findZero(List<Double> xs) {
        // Define a helper function to evaluate polynomial
        java.util.function.DoubleUnaryOperator polyFunc = (double x) -> {
            double result = 0;
            double xPower = 1;
            for (Double coef : xs) {
                result += coef * xPower;
                xPower *= x;
            }
            return result;
        };

        double f = polyFunc.applyAsDouble(0);

        // Find bounds where function changes sign
        double left = -1.0;
        double right = 1.0;

        // Expand search range until we find sign change
        while (true) {
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            if (fLeft <= 0 && fRight >= 0 || fLeft >= 0 && fRight <= 0) {
                break;
            }

            left *= 2;
            right *= 2;

            // Safety limit to prevent infinite loop
            if (Math.abs(left) > 1e10) {
                left = -1e10;
                right = 1e10;
                break;
            }
        }

        // Binary search for root
        for (int i = 0; i < 100; i++) { // 100 iterations gives very high precision
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fMid * poly(xs, left) <= 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2;
    }
}

