class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Create a helper function to evaluate polynomial
        // We'll use bisection method

        // Find the degree and leading coefficient
        int n = xs.size();
        int degree = n - 1;

        // Find the largest non-zero coefficient index (should be the last one based on problem statement)
        // But problem says "largest non zero coefficient" - maybe they mean the highest degree term?
        // Given the constraint, we assume leading coefficient (xs.get(degree)) is non-zero

        // Bisection method: find an interval where function changes sign
        double left = -1000.0;
        double right = 1000.0;

        // Expand interval until we find sign change
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 10;
            right *= 10;
            // Safety limit to prevent infinite loop
            if (Math.abs(left) > 1e10) {
                // Fallback: try smaller interval or return NaN
                left = -100.0;
                right = 100.0;
                break;
            }
        }

        // Now apply bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~30 decimal digits precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            double fLeft = poly(xs, left);
            if (fLeft * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Return midpoint of final interval
        return (left + right) / 2.0;
    }
}

