    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true;
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check for factors up to sqrt(n), starting from 5
        // Only check numbers of form 6k ± 1 (since all primes > 3 are of this form)
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Newton-Raphson method
        double x = 0.0; // initial guess

        // Try multiple starting points in case of issues
        for (double startX : new double[]{0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0}) {
            x = startX;
            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                // Compute derivative
                double fpx = 0.0;
                for (int i = 1; i < xs.size(); i++) {
                    fpx += i * xs.get(i) * Math.pow(x, i - 1);
                }

                // Avoid division by zero
                if (Math.abs(fpx) < 1e-15) {
                    // perturb slightly and try again
                    x += 0.1;
                    continue;
                }

                double nextX = x - fx / fpx;

                // Check for divergence
                if (Double.isInfinite(nextX) || Double.isNaN(nextX)) {
                    x += 0.1;
                    continue;
                }

                x = nextX;
            }
        }

        // Fallback: bisection method over a reasonable range
        double left = -1000.0;
        double right = 1000.0;

        // Find interval where sign changes
        while (left < right) {
            double fl = poly(xs, left);
            double fr = poly(xs, right);

            if (fl == 0) return left;
            if (fr == 0) return right;
            if (fl * fr < 0) break;

            left *= 2;
            right *= 2;

            if (Math.abs(left) > 1e10) {
                // Give up and return midpoint
                return (left + right) / 2;
            }
        }

        // Bisection
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < 1e-10) {
                return mid;
            }

            if (poly(xs, left) * fm < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2;
    }
}

