    >>> longest(Arrays.asList("a", "b", "c"))
    Optional[a]
    >>> longest(Arrays.asList("a", "bb", "ccc"))
    Optional[ccc]
     */
    public Optional<String> longest(List<String> strings) {
        if (strings == null || strings.isEmpty()) {
            return Optional.empty();
        }

        // Use stream with max comparator comparing by length
        // For ties, the first element encountered with max length is kept (stable behavior)
        return strings.stream()
                .max((s1, s2) -> Integer.compare(s1.length(), s2.length()));
    }
}

