class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method to find a root
        // Start with initial guess
        double x = 1.0;
        double tolerance = 1e-9;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // If we're close enough to zero, return
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative: f'(x)
            double fPrimeX = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fPrimeX += i * xs.get(i) * Math.pow(x, i - 1);
            }

            // Avoid division by zero
            if (Math.abs(fPrimeX) < tolerance) {
                // If derivative is zero, try a different starting point
                x = x + 1.0;
                continue;
            }

            // Newton-Raphson update: x_new = x - f(x)/f'(x)
            double xNew = x - fx / fPrimeX;

            // Check for convergence
            if (Math.abs(xNew - x) < tolerance) {
                // Verify this is actually a root
                if (Math.abs(poly(xs, xNew)) < 10 * tolerance) {
                    return xNew;
                }
            }

            x = xNew;
        }

        // Fallback: return the best approximation found
        return x;
    }
}

