class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method to find a root
        double x = 1.0; // Initial guess

        // Try multiple starting points if needed
        for (int attempt = 0; attempt < 10; attempt++) {
            double xCurrent = x + (attempt % 3 == 0 ? 0 : (attempt % 3 == 1 ? 10 : -10));

            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, xCurrent);

                // Check if we found a root
                if (Math.abs(fx) < 1e-10) {
                    return xCurrent;
                }

                // Compute derivative
                double fPrime = 0.0;
                for (int i = 1; i < xs.size(); i++) {
                    fPrime += xs.get(i) * i * Math.pow(xCurrent, i - 1);
                }

                // Avoid division by zero
                if (Math.abs(fPrime) < 1e-10) {
                    break;
                }

                double xNext = xCurrent - fx / fPrime;

                // Check for convergence
                if (Math.abs(xNext - xCurrent) < 1e-10) {
                    if (Math.abs(poly(xs, xNext)) < 1e-8) {
                        return xNext;
                    }
                    break;
                }

                xCurrent = xNext;
            }
        }

        // Fallback: use bisection method on a reasonable interval
        double left = -1000.0;
        double right = 1000.0;

        // Find interval where function changes sign
        while (poly(xs, left) * poly(xs, right) > 0 && (right - left) < 2000) {
            left *= 2;
            right *= 2;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2;
    }
}

