class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 1; // F(1)
        long b = 1; // F(2)

        // Check the first Fibonacci number (1)
        if (isPrime((int)a)) {
            count++;
            if (count == n) return (int)a;
        }

        // Check the second Fibonacci number (1)
        if (isPrime((int)b)) {
            count++;
            if (count == n) return (int)b;
        }

        // Generate subsequent Fibonacci numbers
        while (true) {
            long c = a + b;
            a = b;
            b = c;

            if (c > Integer.MAX_VALUE) {
                throw new ArithmeticException("Fibonacci number exceeds Integer.MAX_VALUE");
            }

            if (isPrime((int)c)) {
                count++;
                if (count == n) {
                    return (int)c;
                }
            }
        }
    }

    private boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        if (num <= 3) {
            return true;
        }
        if (num % 2 == 0 || num % 3 == 0) {
            return false;
        }

        for (int i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

