class Solution {
    public double findZero(List<Double> xs) {
        // Use bisection method to find a root
        // First, evaluate the polynomial at various points to find a sign change

        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand search range if needed to find sign change
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 20) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // If still no sign change, use midpoint as fallback (shouldn't happen per problem statement)
        if (fLeft * fRight > 0) {
            return 0.0;
        }

        // Bisection method
        double tolerance = 1e-9;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return best approximation
        return (left + right) / 2.0;
    }
}

