class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return -1; // or throw exception, but problem likely assumes n > 1
        }

        // Check for divisors from 2 to sqrt(n)
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                // Found smallest divisor i, so n/i is largest proper divisor
                return n / i;
            }
        }

        // If no divisor found, n is prime, so largest proper divisor is 1
        return 1;
    }
}

