class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrtN = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle linear case: xs[0] + xs[1]*x = 0 -> x = -xs[0]/xs[1]
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) > 1e-12) {
                return -a / b;
            }
        }

        // For higher degree polynomials, use Newton-Raphson method
        // Start with initial guess and iterate until convergence

        // Try several initial guesses to handle different polynomial behaviors
        double[] initialGuesses = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

        for (double initialGuess : initialGuesses) {
            double x = initialGuess;
            for (int iteration = 0; iteration < 100; iteration++) {
                // Evaluate polynomial at x
                double fx = poly(xs, x);

                // Check if we found a root
                if (Math.abs(fx) < 1e-9) {
                    return x;
                }

                // Calculate derivative
                double fPrime = 0;
                for (int i = 1; i < xs.size(); i++) {
                    fPrime += xs.get(i) * i * Math.pow(x, i - 1);
                }

                // Avoid division by zero
                if (Math.abs(fPrime) < 1e-12) {
                    // Try a small perturbation
                    x += 0.1;
                    continue;
                }

                double newX = x - fx / fPrime;

                // Check for convergence
                if (Math.abs(newX - x) < 1e-9) {
                    return newX;
                }

                x = newX;
            }

            // If we got close enough with this initial guess, return
            if (Math.abs(poly(xs, x)) < 1e-6) {
                return x;
            }
        }

        // Fallback: try bisection method between reasonable bounds
        // Since leading coefficient is largest non-zero and degree is odd,
        // polynomial goes to ±∞ as x→±∞, so we can find bounds
        double left = -1000.0;
        double right = 1000.0;

        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Ensure we have opposite signs
        while (fLeft * fRight > 0) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            // Safety check to avoid infinite loop
            if (Math.abs(left) > 1e9) {
                break;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint as last resort
        return (left + right) / 2;
    }
}

