class Solution {
    /**
    This function takes a list l and returns a list l' such that
    l' is identical to l in the odd indicies, while its values at the even indicies are equal
    to the values of the even indicies of l, but sorted.
    >>> sortEven(Arrays.asList(1, 2, 3))
    [1, 2, 3]
    >>> sortEven(Arrays.asList(5, 6, 3, 4))
    [3, 6, 5, 4]
     */
    public List<Integer> sortEven(List<Integer> l) {
        // Handle edge cases
        if (l == null || l.size() <= 1) {
            return l;
        }

        // Create a copy of the original list to avoid modifying input
        List<Integer> result = new ArrayList<>(l);

        // Extract elements at even indices (0, 2, 4, ...)
        List<Integer> evenElements = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 2) {
            evenElements.add(l.get(i));
        }

        // Sort the even-indexed elements
        Collections.sort(evenElements);

        // Put sorted even elements back at even indices
        int evenIndex = 0;
        for (int i = 0; i < result.size(); i += 2) {
            result.set(i, evenElements.get(evenIndex++));
        }

        return result;
    }
}

