class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 1; // F1
        long b = 1; // F2

        // Handle special case: 2 is the first Fibonacci prime
        // But our sequence starts 1,1,2,3,5,8...
        // So we need to check for 2 explicitly or start differently

        // Let's generate Fibonacci numbers starting from 1, 1, 2, 3, 5...
        if (n == 1) {
            return 2; // First Fibonacci prime is 2
        }

        // We'll generate Fibonacci numbers and check for primality
        long fib = 2; // Start with the third Fibonacci number

        // Initialize the sequence: F1=1, F2=1, F3=2
        long prev1 = 1;
        long prev2 = 1;

        // Check the first few Fibonacci numbers manually
        // F1=1 (not prime), F2=1 (not prime), F3=2 (prime), F4=3 (prime), F5=5 (prime), ...

        if (n == 1) return 2;

        // Start checking from F3 onwards
        int found = 0;

        // We already know 2,3,5,13,89 are the first 5
        // Let's implement general solution

        long current = 2; // F3
        long next = 3;    // F4

        // Check F3=2
        if (isPrime(current)) {
            found++;
            if (found == n) return (int)current;
        }

        // Check F4=3
        if (isPrime(next)) {
            found++;
            if (found == n) return (int)next;
        }

        // Now continue with the rest
        while (true) {
            long nextFib = current + next;
            current = next;
            next = nextFib;

            if (isPrime(nextFib)) {
                found++;
                if (found == n) {
                    return (int)nextFib;
                }
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0) return false;

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

