class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    Evaluates the derivative of the polynomial at point x.
    For polynomial a0 + a1*x + a2*x^2 + ... + an*x^n,
    derivative is a1 + 2*a2*x + 3*a3*x^2 + ... + n*an*x^(n-1)
     */
    private double polyDeriv(List<Double> xs, double x) {
        if (xs.size() <= 1) {
            return 0;
        }
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero finds x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge case: linear polynomial (degree 1)
        if (xs.size() == 2) {
            return -xs.get(0) / xs.get(1);
        }

        // Use Newton's method with multiple starting points to increase chances of finding a root
        // Try different initial guesses
        double[] initialGuesses = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

        for (double x0 : initialGuesses) {
            double x = x0;
            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, x);
                double fpx = polyDeriv(xs, x);

                // Check if we've found a root
                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                // Avoid division by zero or near-zero derivative
                if (Math.abs(fpx) < 1e-10) {
                    break; // Try next initial guess
                }

                double xNext = x - fx / fpx;

                // Check for convergence
                if (Math.abs(xNext - x) < 1e-10) {
                    return xNext;
                }

                // Check for divergence or NaN
                if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                    break; // Try next initial guess
                }

                x = xNext;
            }
        }

        // Fallback: use bisection method on a reasonable interval if Newton's method fails
        // Since the problem guarantees a solution exists, try a wider range
        double left = -1000.0, right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Ensure we have opposite signs (Intermediate Value Theorem)
        while (fLeft * fRight > 0 && (right - left) > 100) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        // Bisection method
        for (int i = 0; i < 200; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Last resort: return midpoint of our best attempt
        return (left + right) / 2;
    }
}

