    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For linear case: a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            return -a / b;
        }

        // Use Newton-Raphson with multiple starting points
        double[] startingPoints = {-100.0, -10.0, -1.0, 0.0, 1.0, 10.0, 100.0};

        for (double start : startingPoints) {
            double x = start;
            for (int iter = 0; iter < 100; iter++) {
                // Calculate f(x)
                double fx = 0.0;
                double fpx = 0.0;
                double xPower = 1.0;
                double xPowerPrev = 1.0;

                for (int i = 0; i < xs.size(); i++) {
                    fx += xs.get(i) * xPower;
                    if (i > 0) {
                        fpx += i * xs.get(i) * xPowerPrev;
                    }
                    xPower *= x;
                    if (i > 0) {
                        xPowerPrev *= x;
                    }
                }

                // Avoid division by zero
                if (Math.abs(fpx) < 1e-12) {
                    continue;
                }

                double newX = x - fx / fpx;

                // Check if converged
                if (Math.abs(newX - x) < 1e-9) {
                    // Verify it's actually a root
                    double residual = 0.0;
                    double xPowerCheck = 1.0;
                    for (int i = 0; i < xs.size(); i++) {
                        residual += xs.get(i) * xPowerCheck;
                        xPowerCheck *= newX;
                    }
                    if (Math.abs(residual) < 1e-6) {
                        return newX;
                    }
                }

                x = newX;
            }
        }

        // Fallback: try bisection method over a large range
        double left = -1000.0;
        double right = 1000.0;

        // Find interval where sign changes
        for (int attempts = 0; attempts < 20; attempts++) {
            double mid = (left + right) / 2.0;
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            if (fLeft * fRight > 0) {
                // Expand search range
                left *= 2;
                right *= 2;
            } else {
                // Bisection
                for (int i = 0; i < 100; i++) {
                    double midPoint = (left + right) / 2.0;
                    double fMid = poly(xs, midPoint);

                    if (Math.abs(fMid) < 1e-9 || (right - left) < 1e-9) {
                        return midPoint;
                    }

                    if (fLeft * fMid <= 0) {
                        right = midPoint;
                        fRight = fMid;
                    } else {
                        left = midPoint;
                        fLeft = fMid;
                    }
                }
                return (left + right) / 2.0;
            }
        }

        // Last resort: return midpoint of initial range
        return 0.0;
    }
}

