class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) return -1;

        int count = 0;
        int a = 1, b = 1; // First two Fibonacci numbers

        // Handle the first few Fibonacci numbers specially
        if (isPrime(a)) {
            count++;
            if (count == n) return a;
        }

        while (true) {
            int next = a + b;
            if (isPrime(next)) {
                count++;
                if (count == n) return next;
            }
            a = b;
            b = next;
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

