class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Newton-Raphson method
        double x = 0.0; // initial guess
        int maxIterations = 100;
        double tolerance = 1e-10;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // If we found a root
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative numerically
            double derivative = (poly(xs, x + 1e-7) - fx) / 1e-7;

            // Avoid division by zero
            if (Math.abs(derivative) < 1e-15) {
                // Try small perturbation
                x += 0.1;
                continue;
            }

            double xNew = x - fx / derivative;

            // Check for convergence
            if (Math.abs(xNew - x) < tolerance) {
                return xNew;
            }

            x = xNew;
        }

        // Return best approximation after max iterations
        return x;
    }
}

