import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // For linear case: ax + b = 0 => x = -b/a
        if (xs.size() == 2) {
            double a = xs.get(1); // coefficient of x
            double b = xs.get(0); // constant term
            if (a != 0.0) {
                return -b / a;
            }
        }

        // For cubic case, could use analytical formula, but let's use numerical method
        // Use Newton-Raphson with multiple starting points

        // Find leading coefficient (largest non-zero index)
        int n = xs.size() - 1;
        while (n > 0 && Math.abs(xs.get(n)) < 1e-15) {
            n--;
        }

        // If leading coefficient is zero, it shouldn't happen per problem statement
        if (Math.abs(xs.get(n)) < 1e-15) {
            return 0.0; // fallback
        }

        // Newton-Raphson method
        double x = 0.0; // initial guess
        double epsilon = 1e-10;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative
            double fpx = polyDerivative(xs, x);

            // If derivative is too small, try a different approach
            if (Math.abs(fpx) < epsilon) {
                // Try perturbing x slightly
                x += 0.1;
                continue;
            }

            double xNew = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNew - x) < epsilon) {
                return xNew;
            }

            x = xNew;

            // If we're going off to infinity, reset
            if (Double.isNaN(x) || Double.isInfinite(x)) {
                x = (iter % 2 == 0) ? 1.0 : -1.0;
            }
        }

        // Last resort: return current approximation
        return x;
    }

    // Helper method to compute derivative polynomial
    private double polyDerivative(List<Double> xs, double x) {
        if (xs.size() <= 1) {
            return 0.0;
        }

        List<Double> derivativeCoeffs = new ArrayList<>();
        for (int i = 1; i < xs.size(); i++) {
            derivativeCoeffs.add(xs.get(i) * i);
        }

        return poly(derivativeCoeffs, x);
    }
}

