        // Find all factors of constant term and leading coefficient
        // Since coefficients are Double, we'll look for small integer roots first
        // Given the examples, roots are likely small integers or simple fractions

        // Try integer roots from -100 to 100
        for (int root = -100; root <= 100; root++) {
            if (Math.abs(poly(xs, root)) < 1e-9) {
                return root;
            }
        }

        // Try simple fractions: ±1/2, ±1/3, etc.
        for (int denominator = 2; denominator <= 10; denominator++) {
            for (int numerator = -10; numerator <= 10; numerator++) {
                double candidate = (double) numerator / denominator;
                if (Math.abs(poly(xs, candidate)) < 1e-9) {
                    return candidate;
                }
            }
        }

        // Fallback: use Newton-Raphson method for finding a root
        double x = 0.0;
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);
            // Compute derivative
            double fpx = 0.0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(fpx) < 1e-12) {
                x += 0.1; // avoid division by zero
                continue;
            }

            double nextX = x - fx / fpx;
            if (Math.abs(nextX - x) < 1e-9) {
                break;
            }
            x = nextX;
        }

        return x;
    }
}

