class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return 0; // or -1, but divisors of 1 are just 1, so no proper divisor exists
        }

        // Check for smallest divisor from 2 upwards
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                // i is the smallest divisor > 1, so n/i is the largest proper divisor
                return n / i;
            }
        }

        // If we reach here, n is prime, so its largest proper divisor is 1
        return 1;
    }
}

