class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Convert to array for easier access
        double[] coeffs = xs.toArray(new double[0]);
        int n = coeffs.length;

        // For polynomials with even number of coefficients, degree is odd (n-1 is odd)
        // So there's guaranteed at least one real root

        // Start with initial guess - try simple values first
        double x = 0.0;
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = polyValue(coeffs, x);

            // Check if we found a root
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Calculate derivative
            double fpx = polyDerivative(coeffs, x);

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-15) {
                // Try small perturbation if derivative is zero
                x += 0.001;
                continue;
            }

            // Newton's method: x_new = x - f(x)/f'(x)
            double xNew = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNew - x) < tolerance) {
                // Verify this is actually a root
                if (Math.abs(polyValue(coeffs, xNew)) < tolerance) {
                    return xNew;
                }
            }

            x = xNew;

            // Add safeguard against overflow
            if (Double.isInfinite(x) || Double.isNaN(x)) {
                // Fallback to bisection-like approach with bounds
                double left = -100.0, right = 100.0;
                while (left < right) {
                    double mid = (left + right) / 2;
                    double fm = polyValue(coeffs, mid);
                    if (Math.abs(fm) < 1e-8) return mid;
                    if (polyValue(coeffs, left) * fm < 0) {
                        right = mid;
                    } else {
                        left = mid;
                    }
                }
                return left; // Shouldn't reach here normally
            }
        }

        // If we didn't converge, return best approximation
        return x;
    }

    // Helper method to evaluate polynomial at x
    private double polyValue(double[] coeffs, double x) {
        double result = 0;
        double xPower = 1;
        for (int i = 0; i < coeffs.length; i++) {
            result += coeffs[i] * xPower;
            xPower *= x;
        }
        return result;
    }

    // Helper method to evaluate derivative of polynomial at x
    private double polyDerivative(double[] coeffs, double x) {
        if (coeffs.length <= 1) return 0;

        double result = 0;
        double xPower = 1;
        for (int i = 1; i < coeffs.length; i++) {
            result += i * coeffs[i] * xPower;
            xPower *= x;
        }
        return result;
    }
}

