class Solution {
    public List<Double> rescaleToUnit(List<Double> numbers) {
        if (numbers == null || numbers.isEmpty()) {
            return new ArrayList<>();
        }

        // Find min and max
        double min = Double.MAX_VALUE;
        double max = Double.MIN_VALUE;

        for (double num : numbers) {
            if (num < min) {
                min = num;
            }
            if (num > max) {
                max = num;
            }
        }

        // Create result list
        List<Double> result = new ArrayList<>(numbers.size());

        // Handle the case where all numbers are the same (min == max)
        if (min == max) {
            // All values become 0.0 (or could be 0.5, but 0.0 is more standard for uniform distribution)
            for (int i = 0; i < numbers.size(); i++) {
                result.add(0.0);
            }
            return result;
        }

        // Apply normalization: (x - min) / (max - min)
        double range = max - min;
        for (double num : numbers) {
            result.add((num - min) / range);
        }

        return result;
    }
}

