class Solution {
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        // Only need to check up to √n because if n = a*b and a <= b, then a*a <= n
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
            // For linear polynomials (2 coefficients), direct formula
            if (xs.size() == 2) {
                double a = xs.get(0);
                double b = xs.get(1);
                if (Math.abs(b) < 1e-12) {
                    throw new IllegalArgumentException("Linear coefficient is zero");
                }
                return -a / b;
            }

            // For higher degree polynomials, use Newton-Raphson
            double x = 1.0; // initial guess
            double epsilon = 1e-9;
            int maxIterations = 1000;

            for (int i = 0; i < maxIterations; i++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < epsilon) {
                    return x;
                }

                // Compute derivative numerically
                double h = 1e-8;
                double fpx = (poly(xs, x + h) - poly(xs, x)) / h;

                if (Math.abs(fpx) < 1e-12) {
                    // Derivative too small, perturb x slightly
                    x += 0.1;
                    continue;
                }

                double xNext = x - fx / fpx;

                // Check for divergence
                if (Double.isNaN(xNext) || Double.isInfinite(xNext) || 
                    Math.abs(xNext - x) > 1e10) {
                    // Try bisection fallback
                    return bisection(xs, -1000.0, 1000.0);
                }

                x = xNext;
            }

            // If we get here, return the best approximation
            return x;
        }

        private double bisection(List<Double> xs, double left, double right) {
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            // Expand bounds until we find sign change
            int expansionCount = 0;
            while (fLeft * fRight > 0 && expansionCount < 30) {
                left *= 2;
                right *= 2;
                fLeft = poly(xs, left);
                fRight = poly(xs, right);
                expansionCount++;
            }

            if (fLeft * fRight > 0) {
                return left; // fallback
            }

            double epsilon = 1e-9;
            while (right - left > epsilon) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);

                if (Math.abs(fMid) < epsilon) {
                    return mid;
                }

                if (fLeft * fMid < 0) {
                    right = mid;
                } else {
                    left = mid;
                }
            }

            return (left + right) / 2;
        }
}

