    >>> stringSequence(5)
    "0 1 2 3 4 5"
     */
    public String stringSequence(int n) {
        if (n < 0) {
            return "";
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i <= n; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(i);
        }
        return sb.toString();
    }
}

