class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Validate input: even number of coefficients and leading coefficient non-zero
        if (xs.size() % 2 == 0 && !isNearZero(xs.get(xs.size() - 1))) {
            // Binary search for a root
            double low = -1000.0;
            double high = 1000.0;

            // Ensure we have opposite signs at endpoints
            // Expand search range if needed
            while (poly(xs, low) * poly(xs, high) > 0) {
                low *= 10;
                high *= 10;
                // Safety limit to prevent infinite loops
                if (Math.abs(low) > 1e9) {
                    break;
                }
            }

            // Binary search with sufficient precision
            for (int i = 0; i < 100; i++) {
                double mid = (low + high) / 2;
                double valueAtMid = poly(xs, mid);

                if (Math.abs(valueAtMid) < 1e-9) {
                    return mid;
                }

                if (poly(xs, low) * valueAtMid <= 0) {
                    high = mid;
                } else {
                    low = mid;
                }
            }

            // Return midpoint of final interval
            return (low + high) / 2;
        }

        // Fallback: try linear case specifically
        if (xs.size() == 2) {
            // ax + b = 0 => x = -b/a
            double a = xs.get(1);
            double b = xs.get(0);
            if (!isNearZero(a)) {
                return -b / a;
            }
        }

        // For other cases, return 0 as default
        return 0.0;
    }

    private boolean isNearZero(double value) {
        return Math.abs(value) < 1e-9;
    }
}

