class Solution {
    /**
    This function takes a list l and returns a list l' such that
    l' is identical to l in the odd indices, while its values at the even indices are equal
    to the values of the even indices of l, but sorted.
    >>> sortEven(Arrays.asList(1, 2, 3))
    [1, 2, 3]
    >>> sortEven(Arrays.asList(5, 6, 3, 4))
    [3, 6, 5, 4]
     */
    public List<Integer> sortEven(List<Integer> l) {
        // Handle edge cases: empty or single-element list
        if (l == null || l.size() <= 1) {
            return l;
        }

        // Extract values at even indices
        List<Integer> evenValues = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 2) {
            evenValues.add(l.get(i));
        }

        // Sort the even-indexed values
        Collections.sort(evenValues);

        // Build result list
        List<Integer> result = new ArrayList<>(l.size());
        int evenIndex = 0;

        for (int i = 0; i < l.size(); i++) {
            if (i % 2 == 0) { // even index
                result.add(evenValues.get(evenIndex++));
            } else { // odd index
                result.add(l.get(i));
            }
        }

        return result;
    }
}

import java.util.*;
