class Solution {
    public List<Double> findClosestElements(List<Double> numbers) {
        // Create a copy to avoid modifying the original list
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        double minDiff = Double.MAX_VALUE;
        int[] closestPairIndices = {0, 1};

        // Check all adjacent pairs
        for (int i = 0; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < minDiff) {
                minDiff = diff;
                closestPairIndices[0] = i;
                closestPairIndices[1] = i + 1;
            }
        }

        // Return in order (smaller, larger)
        double first = sorted.get(closestPairIndices[0]);
        double second = sorted.get(closestPairIndices[1]);

        // Ensure we return in ascending order (though sorting already ensures this for adjacent pairs)
        if (first <= second) {
            return Arrays.asList(first, second);
        } else {
            return Arrays.asList(second, first);
        }
    }
}

