     */
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // All other even numbers are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Horner's method for better numerical stability and efficiency
        double result = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle degenerate cases
        if (xs.isEmpty()) {
            throw new IllegalArgumentException("Empty coefficient list");
        }

        // Find the highest non-zero coefficient to determine actual degree
        int n = xs.size() - 1;
        while (n >= 0 && Math.abs(xs.get(n)) < 1e-15) {
            n--;
        }
        if (n < 0) {
            throw new IllegalArgumentException("All coefficients are zero");
        }

        // For linear case (n=1): ax + b = 0 => x = -b/a
        if (n == 1) {
            double a = xs.get(1);
            double b = xs.get(0);
            if (Math.abs(a) < 1e-15) {
                throw new IllegalArgumentException("Linear coefficient is zero");
            }
            return -b / a;
        }

        // For higher degrees, use bisection method with interval expansion
        // Since we're guaranteed a root exists, we'll find an interval [a,b] where f(a)*f(b) < 0

        double left = -10.0;
        double right = 10.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand interval until we find sign change
        int iterations = 0;
        while (fLeft * fRight > 0 && iterations < 30) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            iterations++;
        }

        // If still no sign change, try to find any sign change in smaller steps
        if (fLeft * fRight > 0) {
            // Try scanning from 0 outward
            double step = 1.0;
            double current = 0.0;
            double fCurrent = poly(xs, current);

            for (int i = 0; i < 1000; i++) {
                double next = current + step;
                double fNext = poly(xs, next);
                if (fCurrent * fNext <= 0) {
                    left = current;
                    right = next;
                    fLeft = fCurrent;
                    fRight = fNext;
                    break;
                }

                double prev = current - step;
                double fPrev = poly(xs, prev);
                if (fCurrent * fPrev <= 0) {
                    left = prev;
                    right = current;
                    fLeft = fPrev;
                    fRight = fCurrent;
                    break;
                }

                current = next;
                fCurrent = fNext;
                if (i % 2 == 0) {
                    step *= 2;
                }
            }
        }

        // Bisection method for root finding
        double tolerance = 1e-9;
        int maxIterations = 100;
        for (int i = 0; i < maxIterations; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance || (right - left) / 2 < tolerance) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

