class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // First Fibonacci number F0
        long b = 1; // Second Fibonacci number F1

        // Handle special case: we need to check Fibonacci numbers starting from F0=0, F1=1
        // But 0 and 1 are not prime, so we start checking from F2=1 onwards

        while (count < n) {
            long next = a + b;
            a = b;
            b = next;

            // Skip 1 (not prime) - but note F1=F2=1, so we might get duplicates
            if (next == 1) {
                continue;
            }

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return (int) next;
                }
            }
        }

        return -1; // Should never reach here for valid input
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        long sqrt = (long) Math.sqrt(num);
        for (long i = 3; i <= sqrt; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

