class Solution {
    public List<String> separateParenGroups(String paren_string) {
        List<String> result = new ArrayList<>();

        // Remove all spaces
        String clean = paren_string.replace(" ", "");

        int depth = 0;
        StringBuilder currentGroup = new StringBuilder();

        for (char c : clean.toCharArray()) {
            if (c == '(') {
                if (depth == 0) {
                    // Start a new group
                    currentGroup.setLength(0); // Clear any previous content
                }
                currentGroup.append(c);
                depth++;
            } else if (c == ')') {
                currentGroup.append(c);
                depth--;

                if (depth == 0) {
                    // Finished a balanced group at top level
                    result.add(currentGroup.toString());
                }
            }
        }

        return result;
    }
}

