     */
    public List<Integer> parseMusic(String string) {
        List<Integer> result = new ArrayList<>();

        if (string == null || string.trim().isEmpty()) {
            return result;
        }

        String[] notes = string.trim().split("\\s+");

        for (String note : notes) {
            switch (note) {
                case "o":
                    result.add(4);
                    break;
                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // Handle unexpected input - could throw exception or skip
                    // For robustness, we'll skip invalid notes
                    break;
            }
        }

        return result;
    }
}

