class Solution {
    public double findZero(List<Double> xs) {
        // Find degree and leading coefficient
        int n = xs.size() - 1; // degree of polynomial
        double leadingCoeff = xs.get(n);

        // Calculate Cauchy's bound for root magnitude
        double bound = 0;
        for (int i = 0; i < n; i++) {
            double coeff = xs.get(i);
            if (Math.abs(coeff) > bound) {
                bound = Math.abs(coeff);
            }
        }
        if (leadingCoeff != 0) {
            bound = bound / Math.abs(leadingCoeff) + 1;
        } else {
            bound = 100; // fallback
        }

        double left = -bound;
        double right = bound;

        // Ensure we have a sign change
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand interval until we find sign change
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 20) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations for precision
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

