class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return numbers;
        }

        // Create mapping from word to digit value
        Map<String, Integer> wordToValue = new HashMap<>();
        wordToValue.put("zero", 0);
        wordToValue.put("one", 1);
        wordToValue.put("two", 2);
        wordToValue.put("three", 3);
        wordToValue.put("four", 4);
        wordToValue.put("five", 5);
        wordToValue.put("six", 6);
        wordToValue.put("seven", 7);
        wordToValue.put("eight", 8);
        wordToValue.put("nine", 9);

        // Create reverse mapping from digit value to word
        String[] valueToWord = {"zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"};

        // Split input string into words
        String[] words = numbers.split(" ");

        // Convert words to integers and store with original words for sorting
        List<int[]> pairs = new ArrayList<>();
        for (String word : words) {
            if (!word.isEmpty()) {
                int value = wordToValue.get(word);
                pairs.add(new int[]{value, word.hashCode()}); // store hash as placeholder
            }
        }

        // Sort by numeric value
        Collections.sort(pairs, (a, b) -> Integer.compare(a[0], b[0]));

        // Build result string
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < pairs.size(); i++) {
            if (i > 0) result.append(" ");
            result.append(valueToWord[pairs.get(i)[0]]);
        }

        return result.toString();
    }
}

