class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return -1; // No proper divisors for 1 or less
        }

        // Start from n/2 and go down to 1
        // The largest proper divisor can't be larger than n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // This should never be reached for n > 1, but just in case
        return -1;
    }
}

