class Solution {
    public double findZero(List<Double> xs) {
        // Use bisection method to find a root
        // First, evaluate polynomial at some initial points to find bounds with sign change

        double left = -1000.0;
        double right = 1000.0;

        // Find bounds where sign changes
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If we're lucky and get exact zero, return immediately
        if (Math.abs(fLeft) < 1e-12) return left;
        if (Math.abs(fRight) < 1e-12) return right;

        // Expand search range if needed until we find sign change
        int expansionCount = 0;
        while (fLeft * fRight > 0 && expansionCount < 50) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            expansionCount++;

            if (Math.abs(fLeft) < 1e-12) return left;
            if (Math.abs(fRight) < 1e-12) return right;
        }

        // If still no sign change, try symmetric bounds around 0
        if (fLeft * fRight > 0) {
            left = -10.0;
            right = 10.0;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            expansionCount = 0;
            while (fLeft * fRight > 0 && expansionCount < 100) {
                left -= 10.0;
                right += 10.0;
                fLeft = poly(xs, left);
                fRight = poly(xs, right);
                expansionCount++;

                if (Math.abs(fLeft) < 1e-12) return left;
                if (Math.abs(fRight) < 1e-12) return right;
            }
        }

        // Now apply bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations should give good precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

