class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special cases for small Fibonacci numbers
        if (isPrime(2)) {
            count++;
            if (count == n) return 2;
        }

        // Start generating Fibonacci numbers from F(3) = 2 onwards
        // We'll generate and check each Fibonacci number
        while (true) {
            long next = a + b;

            if (next > Integer.MAX_VALUE) {
                throw new ArithmeticException("Result exceeds Integer.MAX_VALUE");
            }

            if (isPrime((int)next)) {
                count++;
                if (count == n) {
                    return (int)next;
                }
            }

            a = b;
            b = next;
        }
    }

    private boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        if (num <= 3) {
            return true;
        }
        if (num % 2 == 0 || num % 3 == 0) {
            return false;
        }

        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

