class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return 0; // or throw exception, but based on example, n >= 2
        }

        // Start from n/2 and go downwards
        // The largest proper divisor must be <= n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // This should never be reached for n >= 2, but included for safety
    }
}

