class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // All other even numbers are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        // Only need to check up to sqrt(n) because if n = a*b and a <= b,
        // then a <= sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Newton-Raphson method
        double x = 1.0; // initial guess
        double epsilon = 1e-9;

        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative
            double fpx = 0.0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(fpx) < epsilon) {
                // Derivative too small, try perturbation
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check if we're diverging or if xNext is NaN
            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                x += 0.5;
            } else {
                x = xNext;
            }
        }

        // If Newton-Raphson fails, try bisection on a reasonable range
        double left = -1000.0;
        double right = 1000.0;

        // Find interval where sign changes
        while (poly(xs, left) * poly(xs, right) > 0 && (right - left) < 1e6) {
            left *= 2;
            right *= 2;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fmid = poly(xs, mid);

            if (Math.abs(fmid) < epsilon) {
                return mid;
            }

            if (poly(xs, left) * fmid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2;
    }
}

