class Solution {
    // Map to convert number words to integers
    private static final Map<String, Integer> WORD_TO_NUM = new HashMap<>();

    static {
        WORD_TO_NUM.put("zero", 0);
        WORD_TO_NUM.put("one", 1);
        WORD_TO_NUM.put("two", 2);
        WORD_TO_NUM.put("three", 3);
        WORD_TO_NUM.put("four", 4);
        WORD_TO_NUM.put("five", 5);
        WORD_TO_NUM.put("six", 6);
        WORD_TO_NUM.put("seven", 7);
        WORD_TO_NUM.put("eight", 8);
        WORD_TO_NUM.put("nine", 9);
    }

    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        // Handle empty or null input
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        // Split the input string into individual number words
        String[] wordArray = numbers.trim().split("\\s+");

        // Create a list to hold the numeric values for sorting
        List<Integer> numList = new ArrayList<>();

        // Convert each word to its numeric value
        for (String word : wordArray) {
            numList.add(WORD_TO_NUM.get(word));
        }

        // Sort the numeric values
        Collections.sort(numList);

        // Convert back to words and join with spaces
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < numList.size(); i++) {
            // Find the word corresponding to this number
            for (Map.Entry<String, Integer> entry : WORD_TO_NUM.entrySet()) {
                if (entry.getValue() == numList.get(i)) {
                    if (i > 0) {
                        result.append(" ");
                    }
                    result.append(entry.getKey());
                    break;
                }
            }
        }

        return result.toString();
    }
}

