     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        int sqrtN = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Use Horner's method for efficiency and numerical stability
        double result = 0.0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // For linear case: a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) > 1e-12) {
                return -a / b;
            }
        }

        // Use Newton-Raphson method to find a root
        double x = 1.0; // initial guess

        // Newton-Raphson: x_{n+1} = x_n - f(x_n) / f'(x_n)
        for (int i = 0; i < 100; i++) { // max iterations
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative
            double[] coeffsDerivative = new double[xs.size() - 1];
            for (int j = 0; j < coeffsDerivative.length; j++) {
                coeffsDerivative[j] = xs.get(j + 1) * (j + 1);
            }
            List<Double> derList = new ArrayList<>();
            for (double d : coeffsDerivative) {
                derList.add(d);
            }
            double fpx = poly(derList, x);

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-12) {
                // Try a small perturbation or fallback
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < 1e-12) {
                break;
            }

            x = xNext;
        }

        // Return the approximate root found
        return x;
    }
}

