class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle linear case: a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (b != 0) {
                return -a / b;
            }
        }

        // Try rational roots using rational root theorem
        // For polynomial with integer coefficients, rational roots are factors of constant term / factors of leading coefficient
        // Since we have doubles, we'll check small integer candidates

        // Find the degree (number of coefficients - 1)
        int degree = xs.size() - 1;

        // Check small integer values first (the examples suggest integer roots)
        for (int guess = -10; guess <= 10; guess++) {
            if (Math.abs(poly(xs, guess)) < 1e-9) {
                return guess;
            }
        }

        // If no integer root found, use Newton-Raphson method
        double x = 0.0; // starting point
        double tolerance = 1e-9;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Numerical derivative
            double h = 1e-7;
            double fpx = (poly(xs, x + h) - fx) / h;

            if (Math.abs(fpx) < 1e-12) {
                // Derivative too small, perturb x slightly
                x += 0.1;
                continue;
            }

            double xNew = x - fx / fpx;

            if (Double.isNaN(xNew) || Double.isInfinite(xNew)) {
                // Fallback: try bisection-like approach
                x += 0.1;
                continue;
            }

            if (Math.abs(xNew - x) < tolerance) {
                if (Math.abs(poly(xs, xNew)) < tolerance) {
                    return xNew;
                }
            }
            x = xNew;
        }

        // Last resort: return whatever we have
        return x;
    }
}

