class Solution {
    public double findZero(List<Double> xs) {
        // For polynomials with odd degree (even number of coefficients), 
        // we know there's at least one real root

        // Find the degree (highest power) - coefficients are from lowest to highest power
        int degree = xs.size() - 1;

        // Get leading coefficient (for x^degree)
        double leadingCoeff = xs.get(degree);

        // If leading coefficient is 0, find the actual highest non-zero coefficient
        while (leadingCoeff == 0 && degree > 0) {
            degree--;
            leadingCoeff = xs.get(degree);
        }

        // For odd degree polynomial, as x->+inf, f(x)->sign(leadingCoeff)*inf
        // as x->-inf, f(x)->-sign(leadingCoeff)*inf (since degree is odd)
        // So we can find bounds where function changes sign

        // Start with a reasonable range and expand until we get sign change
        double left = -1.0;
        double right = 1.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand the interval until we have a sign change
        int iterations = 0;
        while (fLeft * fRight > 0 && iterations < 100) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            iterations++;
        }

        // If still no sign change, return 0 (fallback, though shouldn't happen for odd degree)
        if (fLeft * fRight > 0) {
            return 0.0;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives good precision
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

