        // If substring is null, no strings can contain it (except maybe empty string case)
        if (substring == null) {
            return new ArrayList<>();
        }

        List<String> result = new ArrayList<>();

        for (String str : strings) {
            // Skip null strings in the list
            if (str != null && str.contains(substring)) {
                result.add(str);
            }
        }

        return result;
    }
}

