class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Handle null cases
        if (a == null || b == null) {
            return null;
        }

        // Get the maximum length of both strings
        int len = Math.max(a.length(), b.length());

        // Pad both strings with leading zeros to make them equal length
        StringBuilder sbA = new StringBuilder();
        StringBuilder sbB = new StringBuilder();

        for (int i = 0; i < len - a.length(); i++) {
            sbA.append('0');
        }
        sbA.append(a);

        for (int i = 0; i < len - b.length(); i++) {
            sbB.append('0');
        }
        sbB.append(b);

        // Perform XOR operation
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < len; i++) {
            char bitA = sbA.charAt(i);
            char bitB = sbB.charAt(i);

            // XOR: if bits are same, result is '0'; if different, result is '1'
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

