class Solution {
    public double findZero(List<Double> xs) {
        // Define the polynomial function
        java.util.function.DoubleUnaryOperator polyFunc = x -> poly(xs, x);

        double left = -1000.0;
        double right = 1000.0;
        double fLeft = polyFunc.applyAsDouble(left);
        double fRight = polyFunc.applyAsDouble(right);

        // Expand interval until we find sign change
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 30) {
            left *= 2;
            right *= 2;
            fLeft = polyFunc.applyAsDouble(left);
            fRight = polyFunc.applyAsDouble(right);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // enough iterations for double precision
            double mid = (left + right) / 2;
            double fMid = polyFunc.applyAsDouble(mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

