class Solution {
    final class Solution {
        /**
         * From a supplied list of numbers (of length at least two) select and return two that are the closest to each
         * other and return them in order (smaller number, larger number).
         * <p>
         * Implementation Requirements: This implementation sorts the input list and then checks all adjacent pairs
         * to find the pair with minimum absolute difference. The original list is not modified.
         *
         * @param numbers list of numbers with at least two elements
         * @return a list containing the two closest numbers in ascending order
         * @throws IllegalArgumentException if the input list has fewer than two elements
         * @throws NullPointerException if the input list or any element is null
         */
        public List<Double> findClosestElements(List<Double> numbers) {
            if (numbers == null) {
                throw new NullPointerException("Input list cannot be null");
            }

            if (numbers.size() < 2) {
                throw new IllegalArgumentException("List must contain at least two elements");
            }

            // Create a copy to avoid modifying the original list
            List<Double> sorted = new ArrayList<>(numbers);
            Collections.sort(sorted);

            double minDiff = Double.MAX_VALUE;
            int minIndex = 0;

            // Check adjacent pairs for minimum difference
            for (int i = 0; i < sorted.size() - 1; i++) {
                double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
                if (diff < minDiff) {
                    minDiff = diff;
                    minIndex = i;
                }
            }

            // Return the pair in ascending order (already sorted, so just return adjacent pair)
            return Arrays.asList(sorted.get(minIndex), sorted.get(minIndex + 1));
        }
    }
}

