class Solution {
    /**
     * Given list of numbers (of at least two elements), apply a linear transform to that list,
     * such that the smallest number will become 0 and the largest will become 1.
     * 
     * <p>The transformation maps the minimum value to 0.0 and the maximum value to 1.0,
     * with all other values scaled linearly between them using the formula:
     * {@code (x - min) / (max - min)}.
     * 
     * <p>If all values in the input list are equal, returns a list of zeros.
     * 
     * @param numbers the list of numbers to rescale (must contain at least two elements)
     * @return a new list containing the rescaled values as doubles
     * @throws IllegalArgumentException if the input list is null or empty
     * @throws NullPointerException if the input list contains null elements
     */
    public List<Double> rescaleToUnit(List<Double> numbers) {
        if (numbers == null || numbers.isEmpty()) {
            throw new IllegalArgumentException("Input list must not be null or empty");
        }

        // Find minimum and maximum values
        double min = Double.POSITIVE_INFINITY;
        double max = Double.NEGATIVE_INFINITY;

        for (Double num : numbers) {
            if (num == null) {
                throw new NullPointerException("List elements must not be null");
            }
            if (num < min) {
                min = num;
            }
            if (num > max) {
                max = num;
            }
        }

        // Create result list
        List<Double> result = new ArrayList<>(numbers.size());

        // Handle edge case where all values are the same
        if (min == max) {
            // All values are identical, map everything to 0.0
            for (int i = 0; i < numbers.size(); i++) {
                result.add(0.0);
            }
        } else {
            // Apply linear transformation: (x - min) / (max - min)
            double range = max - min;
            for (Double num : numbers) {
                result.add((num - min) / range);
            }
        }

        return result;
    }
}

