class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: linear polynomial (2 coefficients)
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) > 1e-15) {
                return -a / b;
            }
            // fallback — shouldn't happen per problem guarantee
            return 0.0;
        }

        // Newton-Raphson with multiple starting points
        for (double startX : new double[]{0.0, 1.0, -1.0, 2.0, -2.0, 0.5, -0.5}) {
            double x = startX;
            for (int i = 0; i < 100; i++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < 1e-9) {
                    return x;
                }
                // Compute derivative numerically
                double h = 1e-6;
                double fpx = (poly(xs, x + h) - poly(xs, x - h)) / (2 * h);
                if (Math.abs(fpx) < 1e-12) {
                    break; // derivative too small — try next start
                }
                double xNext = x - fx / fpx;
                // Check for divergence (NaN, Inf, or too far)
                if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                    break;
                }
                x = xNext;
            }
        }

        // Fallback: try bisection between -100 and 100 (for odd degree, sign changes somewhere)
        double left = -100.0;
        double right = 100.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Since odd degree, signs should differ if interval large enough
        if (fLeft * fRight <= 0) {
            // Bisection
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);
                if (Math.abs(fMid) < 1e-9) {
                    return mid;
                }
                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
        }

        // Last resort: return midpoint of final interval
        return (left + right) / 2;
    }
}

