class Solution {
    /**
     * Return maximum element in the list.
     * 
     * @param l the list to find maximum element in
     * @return the maximum element in the list
     * @throws NoSuchElementException if the list is empty
     * 
     * >>> maxElement(Arrays.asList(1, 2, 3))
     * 3
     * >>> maxElement(Arrays.asList(5, 3, -5, 2, -3, 3, 9, 0, 123, 1, -10))
     * 123
     * 
     * Implementation Requirements: This implementation iterates through all elements
     * in the list using the size() and get(int) methods of the List interface,
     * comparing each element to find the maximum. The iteration proceeds in order
     * from index 0 to size()-1. If the list contains null elements, a NullPointerException
     * will be thrown when attempting to compare elements.
     */
    public int maxElement(List<Integer> l) {
        if (l == null) {
            throw new IllegalArgumentException("List cannot be null");
