class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Validate input: even number of coefficients
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("Polynomial must have even number of coefficients");
        }

        // Check that the largest non-zero coefficient (leading coefficient) is positive
        double leadingCoeff = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) { // non-zero check
                leadingCoeff = xs.get(i);
                break;
            }
        }
        if (leadingCoeff <= 0) {
            throw new IllegalArgumentException("Leading coefficient must be positive");
        }

        // For odd-degree polynomials with positive leading coefficient:
        // lim(x->-inf) p(x) = -inf, lim(x->+inf) p(x) = +inf
        // So there must be at least one real root

        // First, find an interval [a, b] where p(a) < 0 and p(b) > 0
        double a = -1.0;
        double b = 1.0;

        // Expand the interval until we bracket a root
        while (poly(xs, a) >= 0 || poly(xs, b) <= 0) {
            a *= 2;
            b *= 2;

            // Safety check to prevent infinite loops
            if (Math.abs(a) > 1e10) {
                // Fallback: return a reasonable estimate
                return 0.0;
            }
        }

        // Now we have poly(xs, a) < 0 and poly(xs, b) > 0
        // Apply bisection method
        double eps = 1e-9;
        for (int iter = 0; iter < 100; iter++) { // enough iterations for precision
            double mid = (a + b) / 2;
            double val = poly(xs, mid);

            if (Math.abs(val) < eps) {
                return mid;
            }

            if (val < 0) {
                a = mid;
            } else {
                b = mid;
            }
        }

        return (a + b) / 2;
    }
}

