class Solution {
    public double findZero(List<Double> xs) {
        // Set search bounds - based on the problem context, small roots are expected
        double left = -1000.0;
        double right = 1000.0;

        // Ensure we have a sign change - if not, expand search range
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand search range if no sign change
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 20) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~30 decimal digits precision
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

