class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Convert to array for faster access
        double[] coeffs = new double[xs.size()];
        for (int i = 0; i < xs.size(); i++) {
            coeffs[i] = xs.get(i);
        }

        // Find bounds where function changes sign
        // Since odd degree polynomial, we know limits go to +/- infinity
        double left = -1000.0;
        double right = 1000.0;

        // Expand the interval until we find sign change
        while (poly(coeffs, left) * poly(coeffs, right) > 0) {
            left *= 10;
            right *= 10;
            // Safety limit to prevent infinite loop
            if (Math.abs(left) > 1e15) {
                break;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives precision ~1e-30
            double mid = (left + right) / 2.0;
            double fMid = poly(coeffs, mid);

            if (Math.abs(fMid) < 1e-15) {
                return mid;
            }

            if (poly(coeffs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2.0;
    }

    // Helper method using array instead of List for efficiency
    private double poly(double[] coeffs, double x) {
        double result = 0;
        double xPower = 1.0;
        for (int i = 0; i < coeffs.length; i++) {
            result += coeffs[i] * xPower;
            xPower *= x;
        }
        return result;
    }
}

