        String longest = null;
        int maxLength = -1;

        for (String s : strings) {
            // Handle null strings in the list - skip them or treat as length 0
            int currentLength = (s != null) ? s.length() : 0;

            if (currentLength > maxLength) {
                maxLength = currentLength;
                longest = s;
            }
            // If equal length, we keep the first one (don't update)
        }

        return Optional.ofNullable(longest);
    }
}

