class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Check if we have linear polynomial (degree 1)
        if (xs.size() == 2) {
            double a0 = xs.get(0);
            double a1 = xs.get(1);
            if (Math.abs(a1) > 1e-12) {
                return -a0 / a1;
            }
        }

        // Use Newton-Raphson method with multiple starting points
        // Since the problem guarantees a solution exists, we'll find one

        // Try different starting points to increase chances of convergence
        double[] startingPoints = {0.0, 1.0, -1.0, 10.0, -10.0, 0.5, -0.5};

        for (double start : startingPoints) {
            double root = newtonRaphson(xs, start);
            if (Math.abs(poly(xs, root)) < 1e-9) {
                return root;
            }
        }

        // Fallback: try bisection method on a large interval
        // Since polynomial of odd degree goes to ±infinity, there must be sign change
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Ensure we have opposite signs
        if (fLeft * fRight > 0) {
            // Try larger interval
            left = -10000.0;
            right = 10000.0;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        // If still same sign, try binary search on sign change
        if (fLeft * fRight <= 0) {
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);
                if (Math.abs(fMid) < 1e-12) {
                    return mid;
                }
                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
            return (left + right) / 2;
        }

        // Last resort: try derivative-based method on smaller intervals
        for (double start = -10; start <= 10; start += 0.5) {
            double root = newtonRaphson(xs, start);
            if (root != Double.NaN && Math.abs(poly(xs, root)) < 1e-6) {
                return root;
            }
        }

        // Should not reach here given problem constraints
        return 0.0;
    }

    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Calculate derivative
            double fPrime = 0;
            for (int j = 1; j < xs.size(); j++) {
                fPrime += j * xs.get(j) * Math.pow(x, j - 1);
            }

            // Avoid division by zero
            if (Math.abs(fPrime) < 1e-12) {
                return Double.NaN;
            }

            double xNew = x - fx / fPrime;

            // Check for divergence
            if (Double.isNaN(xNew) || Double.isInfinite(xNew) || 
                Math.abs(xNew - x) > 1e10) {
                return Double.NaN;
            }

            x = xNew;
        }

        return x;
    }
}

