class Solution {
    public List<Integer> parseMusic(String string) {
        List<Integer> result = new ArrayList<>();

        for (int i = 0; i < string.length(); i++) {
            // Skip spaces
            if (string.charAt(i) == ' ') {
                continue;
            }

            // Check for 2-character tokens first
            if (i + 1 < string.length()) {
                String twoChar = string.substring(i, i + 2);

                if (twoChar.equals("o|")) {
                    result.add(2);
                    i++; // Skip the next character as we consumed it
                    continue;
                } else if (twoChar.equals(".|")) {
                    result.add(1);
                    i++; // Skip the next character as we consumed it
                    continue;
                }
            }

            // Check for 1-character token
            if (string.charAt(i) == 'o') {
                result.add(4);
            }
        }

        return result;
    }
}

