class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: empty list or all zeros
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Evaluate polynomial at a point using Horner's method for efficiency
        // But for finding root, we'll use bisection method

        // Find the degree (highest power) - it's xs.size() - 1
        int degree = xs.size() - 1;

        // Check if leading coefficient is non-zero (should be guaranteed by problem statement)
        double leadingCoeff = xs.get(degree);
        if (leadingCoeff == 0) {
            // Find the actual highest non-zero coefficient
            for (int i = degree; i >= 0; i--) {
                if (xs.get(i) != 0) {
                    leadingCoeff = xs.get(i);
                    degree = i;
                    break;
                }
            }
        }

        // For odd degree polynomials, as x->±∞, f(x)->±∞ or ∓∞
        // So we can find an interval where function changes sign

        // Start with a reasonable interval
        double left = -1000.0;
        double right = 1000.0;

        // Expand interval until we find sign change
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 10;
            right *= 10;
            // Safety check to avoid infinite loop
            if (Math.abs(left) > 1e10) {
                // Fallback: try to find root near zero
                left = -1.0;
                right = 1.0;
                break;
            }
        }

        // Now use bisection method
        double mid = 0.0;
        int iterations = 100; // enough for double precision

        for (int i = 0; i < iterations; i++) {
            mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                break; // Found exact or very close root
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return mid;
    }
}

