class Solution {
    public double findZero(List<Double> xs) {
        // Use bisection method between bounds where sign changes
        // First, evaluate polynomial at several points to find sign change
        double left = -1000.0;
        double right = 1000.0;

        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Ensure we have a sign change; if not, expand search range
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 10) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations for precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Fallback: return midpoint
        return (left + right) / 2.0;
    }
}

