    >>> intersperse(Arrays.asList(1, 2, 3), 4)
    [1, 4, 2, 4, 3]
     */
    public List<Integer> intersperse(List<Integer> numbers, int delimiter) {
        if (numbers == null) {
            throw new IllegalArgumentException("Input list cannot be null");
        }

        // Handle empty list case
        if (numbers.isEmpty()) {
            return new ArrayList<>();
        }

        // Calculate expected size: original size + (size - 1) delimiters
        int originalSize = numbers.size();
        int newSize = originalSize * 2 - 1;

        // Create a new list with the calculated capacity
        List<Integer> result = new ArrayList<>(newSize);

        // Add first element
        result.add(numbers.get(0));

        // Add remaining elements with delimiter in between
        for (int i = 1; i < originalSize; i++) {
            result.add(delimiter);
            result.add(numbers.get(i));
        }

        return result;
    }
}

