import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            throw new IllegalArgumentException("Polynomial coefficients cannot be null or empty");
        }

        // Newton-Raphson method
        double x = 1.0; // Initial guess
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative numerically
            double h = 1e-8;
            double fpx = (poly(xs, x + h) - fx) / h;

            // Avoid division by zero
            if (Math.abs(fpx) < tolerance) {
                // Try a different initial guess
                x = x + 1.0;
                continue;
            }

            double xNew = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNew - x) < tolerance) {
                return xNew;
            }

            x = xNew;
        }

        // Fallback: if Newton-Raphson fails, try bisection
        // Find bounds where sign changes
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand search range until we find sign change
        int expansionAttempts = 0;
        while (fLeft * fRight > 0 && expansionAttempts < 20) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            expansionAttempts++;
        }

        // Bisection method
        if (fLeft * fRight <= 0) {
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);

                if (Math.abs(fMid) < tolerance) {
                    return mid;
                }

                if (fLeft * fMid < 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
        }

        // Final fallback: return last Newton-Raphson value
        return x;
    }
}

