class Solution {
    /**
    This function takes a list l and returns a list l' such that
    l' is identical to l in the odd indicies, while its values at the even indicies are equal
    to the values of the even indicies of l, but sorted.
    >>> sortEven(Arrays.asList(1, 2, 3))
    [1, 2, 3]
    >>> sortEven(Arrays.asList(5, 6, 3, 4))
    [3, 6, 5, 4]
     */
    public List<Integer> sortEven(List<Integer> l) {
        Objects.requireNonNull(l);

        // Extract values at even indices
        List<Integer> evenValues = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 2) {
            evenValues.add(l.get(i));
        }

        // Sort the even-indexed values
        Collections.sort(evenValues);

        // Create result list using AbstractList skeletal implementation
        return new AbstractList<Integer>() {
            private final List<Integer> original = l;
            private final List<Integer> sortedEven = evenValues;

            @Override
            public Integer get(int index) {
                if (index % 2 == 0) {
                    // Even index: use sorted value
                    return sortedEven.get(index / 2);
                } else {
                    // Odd index: use original value
                    return original.get(index);
                }
            }

            @Override
            public Integer set(int index, Integer element) {
                throw new UnsupportedOperationException();
            }

            @Override
            public int size() {
                return original.size();
            }
        };
    }
}

