class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special case: 2 is the first prime Fibonacci
        if (n == 1) {
            return 2;
        }

        // Start generating Fibonacci numbers
        while (true) {
            long next = a + b;
            a = b;
            b = next;

            // Skip small Fibonacci numbers that aren't prime (0, 1, 1)
            if (next < 2) {
                continue;
            }

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return (int) next;
                }
            }

            // Safety check to prevent overflow - though for reasonable n values it shouldn't happen
            if (next > Integer.MAX_VALUE) {
                throw new ArithmeticException("Fibonacci number exceeds integer range");
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

