    >>> sumProduct(Arrays.asList(1, 2, 3, 4))
    [10, 24]
     */
    public List<Integer> sumProduct(List<Integer> numbers) {
        int sum = 0;
        int product = 1;

        for (Integer num : numbers) {
            sum += num;
            product *= num;
        }

        return Arrays.asList(sum, product);
    }
}

