class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 1, b = 1; // Start with F(1)=1, F(2)=1

        // Skip the initial 1s since 1 is not prime
        // Generate Fibonacci numbers starting from 2
        while (true) {
            long next = a + b;
            a = b;
            b = next;

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return (int) next;
                }
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

