class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true; // 2 and 3 are prime
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check for divisors from 5 up to sqrt(n), skipping even numbers
        // Use the pattern: check 6k ± 1 (i.e., 5, 7, 11, 13, 17, 19, ...)
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge case: empty list or all zeros
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // For linear polynomial (degree 1), direct formula
        if (xs.size() == 2) {
            double a0 = xs.get(0);
            double a1 = xs.get(1);
            if (Math.abs(a1) > 1e-12) {
                return -a0 / a1;
            }
            // If slope is zero, no unique solution - return 0 as fallback
            return 0.0;
        }

        // Newton-Raphson method for higher degree polynomials
        double x = 1.0; // initial guess

        // Evaluate derivative at point x
        for (int iteration = 0; iteration < 100; iteration++) {
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative: f'(x) = sum(i * xs[i] * x^(i-1)) for i >= 1
            double fpx = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fpx += i * xs.get(i) * Math.pow(x, i - 1);
            }

            // Avoid division by zero or very small numbers
            if (Math.abs(fpx) < 1e-12) {
                // Try a different approach if derivative is too small
                x += 0.1;
                continue;
            }

            double x_next = x - fx / fpx;

            // Check for convergence
            if (Math.abs(x_next - x) < 1e-10) {
                return x_next;
            }

            // Limit x to avoid overflow
            if (Double.isInfinite(x_next) || Double.isNaN(x_next)) {
                // If Newton fails, try bisection-like approach
                x = (x + 1) / 2;
            } else {
                x = x_next;
            }
        }

        // Return best approximation after max iterations
        return x;
    }
}

