        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For linear case: a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) > 1e-12) {
                return -a / b;
            }
        }

        // For higher degree polynomials, use Newton-Raphson method
        // Compute derivative coefficients
        List<Double> derivCoeffs = new ArrayList<>();
        for (int i = 1; i < xs.size(); i++) {
            derivCoeffs.add(xs.get(i) * i);
        }

        // Helper functions for evaluation
        java.util.function.DoubleUnaryOperator f = x -> poly(xs, x);
        java.util.function.DoubleUnaryOperator df = x -> poly(derivCoeffs, x);

        // Newton-Raphson with multiple starting points to handle different cases
        double[] startPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

        for (double x0 : startPoints) {
            double x = x0;
            for (int iter = 0; iter < 100; iter++) {
                double fx = f.applyAsDouble(x);
                double dfx = df.applyAsDouble(x);

                // If we're close enough to zero, return
                if (Math.abs(fx) < 1e-9) {
                    return x;
                }

                // Avoid division by zero
                if (Math.abs(dfx) < 1e-12) {
                    // Try a small perturbation
                    x += 0.001;
                    continue;
                }

                double xNew = x - fx / dfx;

                // Check for convergence or divergence
                if (Double.isNaN(xNew) || Double.isInfinite(xNew)) {
                    break;
                }

                // Check if we're getting closer
                if (Math.abs(xNew - x) < 1e-12) {
                    if (Math.abs(f.applyAsDouble(xNew)) < 1e-9) {
                        return xNew;
                    }
                    break;
                }

                x = xNew;
            }
        }

        // Fallback: try bisection method if Newton-Raphson fails
        // Find interval where sign changes
        double left = -100.0, right = 100.0;
        double fLeft = f.applyAsDouble(left);
        double fRight = f.applyAsDouble(right);

        // If signs are same, expand the interval
        while (fLeft * fRight > 0 && Math.abs(left) < 1e6) {
            left *= 10;
            right *= 10;
            fLeft = f.applyAsDouble(left);
            fRight = f.applyAsDouble(right);
        }

        if (fLeft * fRight <= 0) {
            // Bisection method
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = f.applyAsDouble(mid);
                if (Math.abs(fMid) < 1e-9) {
                    return mid;
                }
                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
            return (left + right) / 2;
        }

        // Last resort: return midpoint of range as approximation
        return 0.0;
    }
}

