class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 1, b = 1;

        // Handle special case: check if 2 is the first prime Fibonacci
        // Start generating from the beginning
        while (true) {
            long fib = a;

            // Check if current Fibonacci number is prime and greater than 1
            if (fib > 1 && isPrime(fib)) {
                count++;
                if (count == n) {
                    return (int) fib;
                }
            }

            // Generate next Fibonacci number
            long temp = a + b;
            a = b;
            b = temp;
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

