class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Convert list to array for faster access
        double[] coeffs = new double[xs.size()];
        for (int i = 0; i < xs.size(); i++) {
            coeffs[i] = xs.get(i);
        }

        // Find degree (highest non-zero coefficient index)
        int degree = coeffs.length - 1;
        while (degree > 0 && Math.abs(coeffs[degree]) < 1e-15) {
            degree--;
        }

        // For odd degree polynomials, we know a root exists
        // Use bisection with expanding interval

        // First, try to find an interval [a, b] where f(a)*f(b) < 0
        double a = -1.0;
        double b = 1.0;
        double fa = evaluate(coeffs, a);
        double fb = evaluate(coeffs, b);

        // Expand interval until we find opposite signs
        int expansionCount = 0;
        while (fa * fb > 0 && expansionCount < 100) {
            a *= 2;
            b *= 2;
            fa = evaluate(coeffs, a);
            fb = evaluate(coeffs, b);
            expansionCount++;
        }

        // If still same sign, use large interval as fallback
        if (fa * fb > 0) {
            a = -1e6;
            b = 1e6;
            fa = evaluate(coeffs, a);
            fb = evaluate(coeffs, b);
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // sufficient iterations for double precision
            double mid = (a + b) / 2;
            double fm = evaluate(coeffs, mid);

            if (Math.abs(fm) < 1e-12) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2;
    }

    private double evaluate(double[] coeffs, double x) {
        // Horner's method for efficiency
        double result = 0;
        for (int i = coeffs.length - 1; i >= 0; i--) {
            result = result * x + coeffs[i];
        }
        return result;
    }
}

