class Solution {
    /**
    Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parseNestedParens("(()()) ((())) () ((())()())")
    [2, 3, 1, 3]
     */
    public List<Integer> parseNestedParens(String paren_string) {
        List<Integer> result = new ArrayList<>();

        // Handle empty or null input
        if (paren_string == null || paren_string.trim().isEmpty()) {
            return result;
        }

        // Split by spaces to get individual parenthesis groups
        String[] groups = paren_string.split("\\s+");

        for (String group : groups) {
            int maxDepth = 0;
            int currentDepth = 0;

            // Scan through each character in the group
            for (int i = 0; i < group.length(); i++) {
                char c = group.charAt(i);

                if (c == '(') {
                    currentDepth++;
                    // Update maximum depth
                    maxDepth = Math.max(maxDepth, currentDepth);
                } else if (c == ')') {
                    currentDepth--;
                }
            }

            result.add(maxDepth);
        }

        return result;
    }
}

