class Solution {
    /**
    Return a greatest common divisor of two integers a and b
    >>> greatestCommonDivisor(3, 5)
    1
    >>> greatestCommonDivisor(25, 15)
    5
     */
    public int greatestCommonDivisor(int a, int b) {
        // Handle negative numbers by taking absolute values
        // Also handle edge case where both numbers are 0
        if (a == 0 && b == 0) {
            return 0; // GCD(0,0) is undefined, but conventionally return 0
        }

        // Make sure we work with non-negative values
        a = Math.abs(a);
        b = Math.abs(b);

        // Euclidean algorithm
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }

        return a;
    }
}

