class Solution {
    public double findZero(List<Double> xs) {
        // For odd-degree polynomials (even number of coefficients), 
        // there's always at least one real root

        // Start with a reasonable search range and expand if needed
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand search range until we find opposite signs
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 30) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // If we still don't have opposite signs, try other directions
        if (fLeft * fRight > 0) {
            // Try searching from 0 outward
            left = -1.0;
            right = 1.0;
            double step = 1.0;
            while (fLeft * fRight > 0 && step < 1e6) {
                left = -step;
                right = step;
                fLeft = poly(xs, left);
                fRight = poly(xs, right);
                step *= 10;
            }
        }

        // Now use bisection method
        double tolerance = 1e-9;
        while (right - left > tolerance) {
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

