class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Derivative of polynomial: derivative[i] = (i+1) * xs.get(i+1)
        List<Double> derivative = new ArrayList<>();
        for (int i = 1; i < xs.size(); i++) {
            derivative.add(xs.get(i) * i);
        }

        // Newton-Raphson method
        double x = 1.0; // initial guess

        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            double fpx = poly(derivative, x);
            if (Math.abs(fpx) < 1e-10) {
                // Derivative too small, try different initial guess
                x = x + 1.0;
                continue;
            }

            double xNext = x - fx / fpx;
            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                // Fallback: try bisection method
                return bisectionMethod(xs, -1000, 1000);
            }

            if (Math.abs(xNext - x) < 1e-10) {
                return xNext;
            }

            x = xNext;
        }

        // If we didn't converge, fall back to bisection
        return bisectionMethod(xs, -1000, 1000);
    }

    private double bisectionMethod(List<Double> coeffs, double left, double right) {
        double fLeft = poly(coeffs, left);
        double fRight = poly(coeffs, right);

        // Find an interval where function changes sign
        while (fLeft * fRight > 0) {
            left *= 2;
            right *= 2;
            fLeft = poly(coeffs, left);
            fRight = poly(coeffs, right);
            // Safety check to prevent infinite loop
            if (Math.abs(left) > 1e6) {
                return Double.NaN;
            }
        }

        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(coeffs, mid);

            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

