class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: constant polynomial (shouldn't happen with even coefficients >= 2)
        if (xs.size() < 2) {
            return 0.0;
        }

        // Use Newton-Raphson method with multiple starting points
        // Try several initial guesses to increase chances of finding a root
        double[] initialGuesses = {-100.0, -10.0, -1.0, 0.0, 1.0, 10.0, 100.0};

        for (double guess : initialGuesses) {
            double root = newtonRaphson(xs, guess);
            if (Math.abs(poly(xs, root)) < 1e-9) {
                return root;
            }
        }

        // If Newton-Raphson fails, try bisection method
        // Find an interval [a, b] where f(a) * f(b) < 0
        double a = -1000.0;
        double b = 1000.0;

        while (Math.abs(b - a) > 1e-9) {
            double fa = poly(xs, a);
            double fb = poly(xs, b);

            if (fa * fb <= 0) {
                // Bisection within [a, b]
                while (Math.abs(b - a) > 1e-9) {
                    double mid = (a + b) / 2.0;
                    double fm = poly(xs, mid);

                    if (Math.abs(fm) < 1e-9 || Math.abs(b - a) < 1e-9) {
                        return mid;
                    }

                    if (fa * fm <= 0) {
                        b = mid;
                        fb = fm;
                    } else {
                        a = mid;
                        fa = fm;
                    }
                }
                return (a + b) / 2.0;
            }

            // Expand the interval if no sign change
            a *= 2;
            b *= 2;

            // Prevent infinite loop if interval gets too large
            if (Math.abs(a) > 1e6) {
                break;
            }
        }

        // Fallback: return midpoint of last interval tried
        return 0.0;
    }

    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 100; i++) { // Max iterations
            double fx = poly(xs, x);

            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative: f'(x) = sum_{k=1}^{n-1} k * xs[k] * x^(k-1)
            double fPrime = 0.0;
            for (int k = 1; k < xs.size(); k++) {
                fPrime += k * xs.get(k) * Math.pow(x, k - 1);
            }

            // Avoid division by zero
            if (Math.abs(fPrime) < 1e-12) {
                return x; // Can't continue Newton, return current approximation
            }

            double xNew = x - fx / fPrime;

            // Check for convergence
            if (Math.abs(xNew - x) < 1e-9) {
                return xNew;
            }

            x = xNew;
        }

        return x;
    }
}

