class Solution {
    public String makePalindrome(String string) {
        if (string == null || string.length() <= 1) {
            return string;
        }

        // Try each possible suffix starting from the longest (the whole string)
        // to find the longest palindromic suffix
        for (int i = 0; i < string.length(); i++) {
            // Check if substring from i to end is a palindrome
            if (isPalindrome(string.substring(i))) {
                // If so, append reverse of prefix (from 0 to i-1) to the end
                String prefix = string.substring(0, i);
                return string + new StringBuilder(prefix).reverse().toString();
            }
        }

        // This should never be reached since at minimum the last character is a palindrome
        return string;
    }
}

