class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // All even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        // We only need to check up to sqrt(n) because if n = a*b and a <= b,
        // then a <= sqrt(n)
        int sqrtN = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Newton-Raphson method
        double x = 1.0; // initial guess
        double epsilon = 1e-10;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative: f'(x)
            double fPrimeX = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fPrimeX += xs.get(i) * i * Math.pow(x, i - 1);
            }

            // Avoid division by zero
            if (Math.abs(fPrimeX) < epsilon) {
                // Try a different starting point or use bisection fallback
                x += 1.0;
                continue;
            }

            double newX = x - fx / fPrimeX;

            // Check for convergence
            if (Math.abs(newX - x) < epsilon) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, newX)) < epsilon) {
                    return newX;
                }
            }

            x = newX;
        }

        // Fallback: return current approximation
        return x;
    }
}

