class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 0;  // F(0)
        int b = 1;  // F(1)

        // Handle special case: we need to check 2, which is F(3)
        // Start checking from Fibonacci numbers >= 2

        // Generate Fibonacci numbers and check for primality
        while (count < n) {
            // Move to next Fibonacci number
            int c = a + b;
            a = b;
            b = c;

            // Skip 1 (not prime), but include 2 and above
            if (c >= 2 && isPrime(c)) {
                count++;
                if (count == n) {
                    return c;
                }
            }
        }

        // Should never reach here with valid input
        return -1;
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

