        int depth = 0;

        for (char c : cleanString.toCharArray()) {
            if (c == '(') {
                if (depth == 0) {
                    // Starting a new group
                    currentGroup.setLength(0);
                }
                currentGroup.append(c);
                depth++;
            } else if (c == ')') {
                currentGroup.append(c);
                depth--;
                if (depth == 0) {
                    // Completed a balanced group
                    result.add(currentGroup.toString());
                }
            }
        }

        return result;
    }
}

