class Solution {
    public double findZero(List<Double> xs) {
        // Convert to array for easier access
        double[] coeffs = new double[xs.size()];
        for (int i = 0; i < xs.size(); i++) {
            coeffs[i] = xs.get(i);
        }

        // Evaluate polynomial at point x
        java.util.function.DoubleFunction<Double> polyEval = (double x) -> {
            double result = 0;
            double xPower = 1;
            for (double coeff : coeffs) {
                result += coeff * xPower;
                xPower *= x;
            }
            return result;
        };

        // Find an interval [a, b] where f(a) * f(b) < 0
        double a = -1.0;
        double b = 1.0;
        double fa = polyEval.applyAsDouble(a);
        double fb = polyEval.applyAsDouble(b);

        // Expand interval until we find opposite signs
        int maxExpand = 30;
        for (int i = 0; i < maxExpand && fa * fb >= 0; i++) {
            a *= 2;
            b *= 2;
            fa = polyEval.applyAsDouble(a);
            fb = polyEval.applyAsDouble(b);
        }

        // If still no sign change, try negative direction for a
        if (fa * fb >= 0) {
            a = -1000.0;
            b = 1000.0;
            fa = polyEval.applyAsDouble(a);
            fb = polyEval.applyAsDouble(b);
        }

        // Bisection method
        double epsilon = 1e-10;
        for (int i = 0; i < 100 && (b - a) > epsilon; i++) {
            double mid = (a + b) / 2;
            double fmid = polyEval.applyAsDouble(mid);

            if (Math.abs(fmid) < epsilon) {
                return mid;
            }

            if (fa * fmid < 0) {
                b = mid;
                fb = fmid;
            } else {
                a = mid;
                fa = fmid;
            }
        }

        return (a + b) / 2;
    }
}

