class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0, b = 1; // Fibonacci sequence starts with 0, 1

        while (count < n) {
            long next = a + b;
            a = b;
            b = next;

            // Skip 0 and 1 as they are not prime
            if (a > 1 && isPrime((int)a)) {
                count++;
                if (count == n) {
                    return (int)a;
                }
            }
        }

        // This should never be reached given valid input
        throw new IllegalStateException("Failed to find n-th Fibonacci prime");
    }

    private boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        if (num <= 3) {
            return true;
        }
        if (num % 2 == 0 || num % 3 == 0) {
            return false;
        }

        for (int i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

