class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Edge case: empty substring - according to typical convention, return 0
        // Also handles null safety
        if (substring == null || substring.isEmpty()) {
            return 0;
        }

        // Edge case: empty main string or main string shorter than substring
        if (string == null || string.length() < substring.length()) {
            return 0;
        }

        int count = 0;
        // Check at each position in the string
        for (int i = 0; i <= string.length() - substring.length(); i++) {
            // Use substring method to extract and compare
            if (string.substring(i, i + substring.length()).equals(substring)) {
                count++;
            }
        }

        return count;
    }
}

