class Solution {
    // Static member class - an enum for number words
    public static enum NumberWord {
        ZERO(0), ONE(1), TWO(2), THREE(3), FOUR(4), FIVE(5), 
        SIX(6), SEVEN(7), EIGHT(8), NINE(9);

        private final int value;

        NumberWord(int value) {
            this.value = value;
        }

        public int getValue() {
            return value;
        }

        // Reverse lookup map
        private static final Map<Integer, NumberWord> valueMap = new HashMap<>();

        static {
            for (NumberWord word : values()) {
                valueMap.put(word.value, word);
            }
        }

        public static NumberWord fromValue(int value) {
            return valueMap.get(value);
        }

        public static NumberWord fromString(String word) {
            try {
                return NumberWord.valueOf(word.toUpperCase());
            } catch (IllegalArgumentException e) {
                throw new IllegalArgumentException("Invalid number word: " + word);
            }
        }
    }

    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        String[] words = numbers.trim().split("\\s+");
        List<NumberWord> numberWords = new ArrayList<>();

        for (String word : words) {
            numberWords.add(NumberWord.fromString(word));
        }

        // Sort by numeric value
        Collections.sort(numberWords, Comparator.comparingInt(NumberWord::getValue));

        // Convert back to strings and join
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < numberWords.size(); i++) {
            if (i > 0) {
                result.append(" ");
            }
            result.append(numberWords.get(i).name().toLowerCase());
        }

        return result.toString();
    }
}

