import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
            // For Newton-Raphson, start with initial guess
            double x = 1.0;
            double tolerance = 1e-9;
            int maxIterations = 1000;

            for (int i = 0; i < maxIterations; i++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < tolerance) {
                    return x;
                }

                // Compute derivative at x
                double fPrimeX = polyDerivative(xs, x);

                // Avoid division by zero
                if (Math.abs(fPrimeX) < 1e-15) {
                    // Try a small perturbation or change starting point
                    x += 0.1;
                    continue;
                }

                double xNext = x - fx / fPrimeX;

                // Check for convergence
                if (Math.abs(xNext - x) < tolerance) {
                    // Verify it's actually a root
                    if (Math.abs(poly(xs, xNext)) < tolerance) {
                        return xNext;
                    }
                }

                x = xNext;
            }

            // Fallback: if Newton-Raphson didn't converge, try binary search on an interval
            // Since odd-degree polynomials go to ±infinity, try a large interval
            double left = -1000.0;
            double right = 1000.0;
            double mid = 0.0;

            for (int i = 0; i < 100; i++) {
                mid = (left + right) / 2;
                double fMid = poly(xs, mid);

                if (Math.abs(fMid) < tolerance) {
                    return mid;
                }

                double fLeft = poly(xs, left);
                if (fLeft * fMid < 0) {
                    right = mid;
                } else {
                    left = mid;
                }
            }

            return mid;
        }

        // Helper method to compute derivative of polynomial at x
        private double polyDerivative(List<Double> coeffs, double x) {
            if (coeffs.size() <= 1) {
                return 0.0;
            }

            double result = 0.0;
            for (int i = 1; i < coeffs.size(); i++) {
                result += i * coeffs.get(i) * Math.pow(x, i - 1);
            }
            return result;
        }
}

