class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Start Fibonacci sequence: 1, 2, 3, 5, 8, 13...
        long a = 1;
        long b = 2;
        int count = 0;

        // Handle the first Fibonacci number we need to check
        // We'll check 2 separately since our loop starts with a=1, b=2

        while (true) {
            // Check if current Fibonacci number (b) is prime
            if (isPrime(b)) {
                count++;
                if (count == n) {
                    return (int) b;
                }
            }

            // Generate next Fibonacci number
            long next = a + b;
            a = b;
            b = next;
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

