import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Remove trailing zeros to get actual degree
        List<Double> coeffs = new ArrayList<>(xs);
        while (coeffs.size() > 1 && coeffs.get(coeffs.size() - 1) == 0) {
            coeffs.remove(coeffs.size() - 1);
        }

        // Ensure even number of coefficients (as per requirement)
        // If we removed trailing zeros and now have odd count, add one back or handle error
        // But the problem states input has even number, so we assume valid input

        int n = coeffs.size();

        // Handle linear case: ax + b = 0 => x = -b/a
        if (n == 2) {
            double a = coeffs.get(1);
            double b = coeffs.get(0);
            return -b / a;
        }

        // For higher degrees, use bisection method
        // Since degree is odd (n-1 is odd when n is even), limit exists
        double left = -1000.0;
        double right = 1000.0;

        // Find interval where sign changes
        while (poly(coeffs, left) * poly(coeffs, right) > 0) {
            left *= 2;
            right *= 2;
            if (left < -1e6 || right > 1e6) {
                break; // fallback
            }
        }

        // Bisection method
        double mid = 0;
        for (int i = 0; i < 100; i++) { // sufficient iterations for precision
            mid = (left + right) / 2;
            double fMid = poly(coeffs, mid);

            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }

            if (poly(coeffs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return mid;
    }
}

