class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special case: F(3) = 2 is the first prime Fibonacci
        // We need to generate Fibonacci numbers and check for primality

        while (true) {
            long fib = a;

            // Check if fib is prime (and within int range)
            if (fib > 1 && isPrime((int)fib)) {
                count++;
                if (count == n) {
                    return (int)fib;
                }
            }

            // Generate next Fibonacci number
            long temp = a + b;
            a = b;
            b = temp;

            // Safety check to prevent overflow (since we're returning int)
            if (fib > Integer.MAX_VALUE) {
                throw new ArithmeticException("Fibonacci number exceeds integer range");
            }
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

