class Solution {
    public String makePalindrome(String string) {
        if (string == null || string.length() == 0) {
            return string;
        }

        // Find the longest suffix that is a palindrome
        for (int i = 0; i < string.length(); i++) {
            // Check if substring from i to end is a palindrome
            if (isPalindrome(string.substring(i))) {
                // If yes, append reverse of the prefix (from 0 to i-1)
                String prefix = string.substring(0, i);
                return string + new StringBuilder(prefix).reverse().toString();
            }
        }

        // This should never be reached since at least the last character forms a palindrome
        return string;
    }
}

