class Solution {
    public double findZero(List<Double> xs) {
        // Handle linear case explicitly: ax + b = 0 => x = -b/a
        if (xs.size() == 2) {
            double a = xs.get(1);
            double b = xs.get(0);
            return -b / a;
        }

        // For higher degree polynomials, use Newton-Raphson with multiple starting points
        // Since odd degree polynomials go to ±∞ as x→±∞, we can find an interval
        double left = -100.0;
        double right = 100.0;

        // Find an interval where function changes sign
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 2;
            right *= 2;
            // Safety check to prevent infinite loop
            if (Math.abs(left) > 1e9) {
                break;
            }
        }

        // Bisection method for reliability
        double mid = (left + right) / 2;
        int maxIterations = 1000;
        double tolerance = 1e-9;

        for (int i = 0; i < maxIterations; i++) {
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance) {
                return mid;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }

            mid = (left + right) / 2;

            if ((right - left) < tolerance) {
                return mid;
            }
        }

        return mid;
    }
}

