        if (xs.isEmpty()) return 0.0;

        // Newton-Raphson method
        double x = 0.0; // initial guess
        int maxIterations = 100;
        double epsilon = 1e-9;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative: f'(x)
            // Derivative of sum_{k=0}^n a_k x^k is sum_{k=1}^n k*a_k x^{k-1}
            double fpx = 0.0;
            for (int k = 1; k < xs.size(); k++) {
                fpx += k * xs.get(k) * Math.pow(x, k-1);
            }

            if (Math.abs(fpx) < epsilon) {
                // Derivative too small, perturb x slightly and continue
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;
            if (Math.abs(xNext - x) < epsilon) {
                return xNext;
            }
            x = xNext;
        }

        return x; // Return best approximation after max iterations
    }
}

