class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Assume inputs are valid and of equal length based on the example
        // If lengths differ, we could pad with zeros or throw an exception
        // For this problem, let's assume equal length as shown in example

        StringBuilder result = new StringBuilder();
        int len = Math.min(a.length(), b.length());

        for (int i = 0; i < len; i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            // XOR logic: if bits are different, result is '1', else '0'
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

