class Solution {
    public int largestDivisor(int n) {
        // Handle edge case: if n is 1, there's no positive divisor smaller than 1
        if (n <= 1) {
            return 0;
        }

        // Check for smallest divisor from 2 to sqrt(n)
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                return n / i;
            }
        }

        // If no divisor found, n is prime, so largest proper divisor is 1
        return 1;
    }
}

