class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        int sqrtN = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Ensure even number of coefficients (odd degree)
        int n = xs.size();

        // For linear case: a + bx = 0 -> x = -a/b
        if (n == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) < 1e-12) {
                // Handle degenerate case - should not happen per problem constraints
                return 0.0;
            }
            return -a / b;
        }

        // Use Newton-Raphson method for higher degree polynomials
        double x = 0.0; // Initial guess

        // Newton-Raphson iterations
        for (int iter = 0; iter < 100; iter++) {
            double fx = poly(xs, x);

            // If we found a root, return it
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative: f'(x) = sum_{i=1}^{n-1} i * coeff[i] * x^(i-1)
            double fpx = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fpx += i * xs.get(i) * Math.pow(x, i - 1);
            }

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-12) {
                // Perturb x slightly and try again
                x += 0.1;
                continue;
            }

            double xNew = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNew - x) < 1e-10) {
                return xNew;
            }

            x = xNew;
        }

        // Fallback: return last computed value
        return x;
    }
}

