class Solution {
    public List<Integer> factorize(int n) {
        List<Integer> factors = new ArrayList<>();

        if (n <= 1) {
            return factors;
        }

        // Handle factor 2 separately to optimize odd number checking later
        while (n % 2 == 0) {
            factors.add(2);
            n /= 2;
        }

        // Check odd factors starting from 3
        for (int i = 3; i * i <= n; i += 2) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }

        // If n is still greater than 1, then it's a prime factor
        if (n > 1) {
            factors.add(n);
        }

        return factors;
    }
}

