class Solution {
    public double findZero(List<Double> xs) {
        // Newton-Raphson method to find root of polynomial
        double x = 0.0; // initial guess
        double tolerance = 1e-7;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative numerically
            double h = 1e-8;
            double fpx = (poly(xs, x + h) - fx) / h;

            if (Math.abs(fpx) < 1e-12) {
                // Derivative too small, perturb x slightly and continue
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < tolerance) {
                return xNext;
            }

            x = xNext;
        }

        // Fallback: return best approximation
        return x;
    }
}

