class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        StringBuilder result = new StringBuilder();

        // Ensure both strings have the same length by padding the shorter one with leading zeros
        int lenA = a.length();
        int lenB = b.length();
        int maxLen = Math.max(lenA, lenB);

        // Pad both strings to the same length
        String paddedA = padWithLeadingZeros(a, maxLen);
        String paddedB = padWithLeadingZeros(b, maxLen);

        // Perform XOR character by character
        for (int i = 0; i < maxLen; i++) {
            char bitA = paddedA.charAt(i);
            char bitB = paddedB.charAt(i);

            // XOR: if bits are different, result is '1', otherwise '0'
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }

    private String padWithLeadingZeros(String s, int length) {
        if (s.length() >= length) {
            return s;
        }

        StringBuilder padded = new StringBuilder();
        for (int i = 0; i < length - s.length(); i++) {
            padded.append('0');
        }
        padded.append(s);
        return padded.toString();
    }
}

