        String[] tokens = string.split(" ");

        for (String token : tokens) {
            if ("o".equals(token)) {
                result.add(4);
            } else if ("o|".equals(token)) {
                result.add(2);
            } else if (".|".equals(token)) {
                result.add(1);
            }
        }

        return result;
    }
