import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Ensure even number of coefficients (as per requirement)
        if (xs.size() % 2 == 0 && xs.size() > 0) {
            // Check leading coefficient is non-zero (as per guarantee)
            double leading = xs.get(xs.size() - 1);
            if (leading == 0.0) {
                throw new IllegalArgumentException("Leading coefficient must be non-zero");
            }
        } else {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Define polynomial evaluation using helper
        java.util.function.DoubleUnaryOperator polyEval = x -> {
            double res = 0;
            double xPower = 1;
            for (double coeff : xs) {
                res += coeff * xPower;
                xPower *= x;
            }
            return res;
        };

        double f(double x) {
            return polyEval.applyAsDouble(x);
        }

        // Bisection with interval expansion
        double low = -1000.0;
        double high = 1000.0;
        double fLow = f(low);
        double fHigh = f(high);

        // Expand interval until sign change
        while (fLow * fHigh > 0) {
            low *= 10;
            high *= 10;
            fLow = f(low);
            fHigh = f(high);
            // Safety: avoid infinite loop (e.g., if floating issues)
            if (Math.abs(low) > 1e9) {
                // Fallback: return midpoint or throw
                break;
            }
        }

        // Bisection loop
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~1e-30 precision
            double mid = (low + high) / 2;
            double fMid = f(mid);
            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }
            if (fLow * fMid <= 0) {
                high = mid;
                fHigh = fMid;
            } else {
                low = mid;
                fLow = fMid;
            }
        }

        return (low + high) / 2;
    }
}

