                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // Handle invalid notes - could throw exception or ignore
                    // For robustness, we'll just skip or throw
                    throw new IllegalArgumentException("Unknown note format: " + note);
            }
        }

        return result;
    }
}

