class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Newton-Raphson method
        double x = 0.0; // initial guess
        for (int iter = 0; iter < 100; iter++) {
            double fx = poly(xs, x);
            // Compute derivative: d/dx [sum_{i=0}^{n} a_i x^i] = sum_{i=1}^{n} i*a_i x^{i-1}
            double fpx = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fpx += i * xs.get(i) * Math.pow(x, i - 1);
            }

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-10) {
                x += 0.1; // perturb if derivative too small
                continue;
            }

            double nextX = x - fx / fpx;

            // Check convergence
            if (Math.abs(nextX - x) < 1e-10) {
                break;
            }

            x = nextX;
        }

        // Verify it's actually a root (within tolerance)
        if (Math.abs(poly(xs, x)) > 1e-6) {
            // Fallback: try other starting points
            for (double start = -10.0; start <= 10.0; start += 1.0) {
                double candidate = newtonMethod(xs, start);
                if (Math.abs(poly(xs, candidate)) < 1e-6) {
                    return candidate;
                }
            }
            // Last resort: return 0.0 (shouldn't happen per problem guarantee)
            return 0.0;
        }

        return x;
    }

    private double newtonMethod(List<Double> xs, double startX) {
        double x = startX;
        for (int iter = 0; iter < 50; iter++) {
            double fx = poly(xs, x);
            double fpx = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fpx += i * xs.get(i) * Math.pow(x, i - 1);
            }

            if (Math.abs(fpx) < 1e-12) {
                x += 0.1;
                continue;
            }

            double nextX = x - fx / fpx;
            if (Math.abs(nextX - x) < 1e-12) break;
            x = nextX;
        }
        return x;
    }
}

