    [2.0, 2.0]
     */
    public List<Double> findClosestElements(List<Double> numbers) {
        // Create a copy to avoid modifying the original list
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        double minDiff = Double.MAX_VALUE;
        double[] closestPair = new double[2];

        for (int i = 0; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < minDiff) {
                minDiff = diff;
                closestPair[0] = sorted.get(i);
                closestPair[1] = sorted.get(i + 1);
            }
        }

        // Use SuppressWarnings on the smallest scope possible - local variable
        @SuppressWarnings("unchecked")
        List<Double> result = (List<Double>) Arrays.asList(closestPair[0], closestPair[1]);
        return result;
    }
}

