class Solution {
    /**
    From a list of integers, remove all elements that occur more than once.
    Keep order of elements left the same as in the input.
    >>> removeDuplicates(Array.asList(1, 2, 3, 2, 4))
    [1, 3, 4]
     */
    public List<Integer> removeDuplicates(List<Integer> numbers) {
        // Count frequencies - using LinkedHashMap to maintain insertion order
        Map<Integer, Long> frequencyMap = numbers.stream()
                .collect(Collectors.groupingBy(
                    n -> n,
                    LinkedHashMap::new,
                    Collectors.counting()
                ));

        // Filter to keep only elements that appear exactly once
        List<Integer> result = new ArrayList<>();
        for (Integer num : numbers) {
            // Check frequency using the precomputed map
            if (frequencyMap.get(num) == 1L) {
                result.add(num);
            }
        }

        return result;
    }
}

