class Solution {
    public double findZero(List<Double> xs) {
        // Convert to array for easier access
        double[] coeffs = xs.stream().mapToDouble(Double::doubleValue).toArray();

        // Newton-Raphson method
        double x = 1.0; // initial guess
        double tolerance = 1e-10;

        for (int i = 0; i < 1000; i++) {
            double fx = evaluate(coeffs, x);
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            double fpx = evaluateDerivative(coeffs, x);
            if (Math.abs(fpx) < 1e-15) {
                // Derivative too small, try different starting point
                x += 0.5;
                continue;
            }

            double xNext = x - fx / fpx;
            if (Math.abs(xNext - x) < tolerance) {
                return xNext;
            }
            x = xNext;
        }

        return x; // fallback
    }

    private double evaluate(double[] coeffs, double x) {
        double result = 0;
        for (int i = 0; i < coeffs.length; i++) {
            result += coeffs[i] * Math.pow(x, i);
        }
        return result;
    }

    private double evaluateDerivative(double[] coeffs, double x) {
        double result = 0;
        for (int i = 1; i < coeffs.length; i++) {
            result += i * coeffs[i] * Math.pow(x, i - 1);
        }
        return result;
    }
}

