class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        int n = xs.size();

        // Linear case: a + bx = 0 => x = -a/b
        if (n == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) < 1e-15) {
                return 0.0; // degenerate case
            }
            return -a / b;
        }

        // Get the leading coefficient (last non-zero coefficient)
        double leadingCoeff = 0.0;
        for (int i = n - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-15) {
                leadingCoeff = xs.get(i);
                break;
            }
        }

        // Bisection method
        // Since it's an odd-degree polynomial, we know there's at least one real root
        double left = -1000.0;
        double right = 1000.0;

        // Expand bounds until we find a sign change
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 10;
            right *= 10;
            // Safety limit to prevent infinite loops
            if (Math.abs(left) > 1e9) {
                // Fallback: try Newton's method starting from 0
                return newtonMethod(xs, 0.0);
            }
        }

        // Bisection loop
        double mid = 0.0;
        for (int i = 0; i < 100; i++) { // enough iterations for double precision
            mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                break;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return mid;
    }

    // Helper method for Newton-Raphson fallback
    private double newtonMethod(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 50; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }
            // Compute derivative
            double fpx = 0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }
            if (Math.abs(fpx) < 1e-15) {
                x += 0.1; // perturb if derivative too small
                continue;
            }
            x = x - fx / fpx;
            if (Double.isNaN(x) || Double.isInfinite(x)) {
                x = x0 + i * 0.1; // try different starting point
            }
        }
        return x;
    }
}

