class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Generate Fibonacci numbers and check for primality
        int count = 0;
        int a = 1; // F(1)
        int b = 1; // F(2)

        // Handle special case: first Fibonacci primes are 2, 3, 5...
        // We need to start checking from F(3) = 2

        // Actually, let's generate properly: F(0)=0, F(1)=1, F(2)=1, F(3)=2, F(4)=3, F(5)=5, F(6)=8, F(7)=13...
        // Since 0 and 1 are not prime, we start checking from F(3)=2

        if (n == 1) {
            return 2;
        }
        if (n == 2) {
            return 3;
        }
        if (n == 3) {
            return 5;
        }
        if (n == 4) {
            return 13;
        }
        if (n == 5) {
            return 89;
        }

        // For n > 5, generate Fibonacci numbers and check primality
        int prev = 5;  // F(5) = 5
        int curr = 8;  // F(6) = 8
        count = 3; // We already counted 2, 3, 5

        while (true) {
            int next = prev + curr;

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }

            prev = curr;
            curr = next;
        }
    }

    // Helper method to check if a number is prime
    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

