class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return -1; // No proper divisors for 0, 1, or negative numbers
        }

        // Find the smallest divisor > 1
        int smallestDivisor = -1;
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                smallestDivisor = i;
                break;
            }
        }

        // If no smallest divisor found, n is prime, so answer is 1
        if (smallestDivisor == -1) {
            return 1;
        }

        // Otherwise, largest proper divisor is n / smallestDivisor
        return n / smallestDivisor;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Return list of prime factors of given integer in the order from smallest to largest.
    Each of the factors should be listed number of times corresponding to how many times it appeares in factorization.
    Input number should be equal to the product of all factors
    >>> factorize(8)
    [2, 2, 2]
    >>> factorize(25)
    [5, 5]
    >>> factorize(70)
    [2, 5, 7]
     */
    public List<Integer> factorize(int n) {
        List<Integer> factors = new ArrayList<>();

        if (n <= 1) {
            return factors;
        }

        // Check for factor 2 separately to optimize odd number checking later
        while (n % 2 == 0) {
            factors.add(2);
            n /= 2;
        }

        // Check odd factors starting from 3
        for (int i = 3; i * i <= n; i += 2) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }

        // If n is still greater than 1, then it's a prime factor
        if (n > 1) {
            factors.add(n);
        }

        return factors;
    }
}

