        // Find the longest suffix that is a palindrome
        for (int i = 0; i < string.length(); i++) {
            // Check if substring from i to end is palindrome
            if (isPalindrome(string.substring(i))) {
                // If yes, append reverse of prefix (0 to i-1)
                String prefix = string.substring(0, i);
                StringBuilder sb = new StringBuilder(string);
                sb.append(new StringBuilder(prefix).reverse());
                return sb.toString();
            }
        }

        // Fallback (shouldn't reach here as single char is always palindrome)
        return string;
    }
}

