        String[] notes = string.trim().split("\\s+");

        for (String note : notes) {
            switch (note) {
                case "o":
                    result.add(4);
                    break;
                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // According to the problem statement, only these three formats are expected
                    // If an unknown note appears, we could either skip it or throw an exception
                    // For robustness, let's skip unknown notes
                    break;
            }
        }

        return result;
    }
}

