class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Start from n/2 and go down to 1
        // The first divisor we find will be the largest proper divisor
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }
        // According to the problem constraints, n should be > 1
        // If n <= 1, no proper divisor exists, but the loop above handles n=1 by returning 0
        // However, since divisors are positive, and the problem implies n >= 2,
        // we can return 1 as fallback (1 divides everything)
        return 1;
    }
}

