import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Newton-Raphson method
        double x = 1.0; // initial guess
        double tolerance = 1e-9;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);

            // Check if we're close enough to a root
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative: f'(x) = sum_{k=1}^{n-1} k * xs[k] * x^(k-1)
            double fpx = 0.0;
            for (int k = 1; k < xs.size(); k++) {
                fpx += k * xs.get(k) * Math.pow(x, k - 1);
            }

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-15) {
                // Try a different initial guess if derivative is too small
                x += 0.1;
                continue;
            }

            double nextX = x - fx / fpx;

            // Check for convergence
            if (Math.abs(nextX - x) < tolerance) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, nextX)) < tolerance) {
                    return nextX;
                }
            }

            x = nextX;
        }

        // Fallback: return the last computed value
        return x;
    }
}

