class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Validate inputs - though problem states they consist only of 1s and 0s
        if (a == null || b == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        // Ensure both strings have the same length by padding the shorter one with leading zeros
        // Or we can process up to the minimum length and handle remainder
        int lenA = a.length();
        int lenB = b.length();
        int maxLen = Math.max(lenA, lenB);

        // Pad shorter string with leading zeros
        StringBuilder aPadded = new StringBuilder(a);
        StringBuilder bPadded = new StringBuilder(b);

        while (aPadded.length() < maxLen) {
            aPadded.insert(0, '0');
        }
        while (bPadded.length() < maxLen) {
            bPadded.insert(0, '0');
        }

        StringBuilder result = new StringBuilder(maxLen);

        for (int i = 0; i < maxLen; i++) {
            char bitA = aPadded.charAt(i);
            char bitB = bPadded.charAt(i);

            // XOR operation: same bits give 0, different bits give 1
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

