class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // For n <= 1, there's no proper divisor
        if (n <= 1) {
            return -1; // or throw exception, but problem implies n > 1
        }

        // Check from n/2 down to 1
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // This should never be reached for n > 1, but included for completeness
    }
}

