class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        int sqrtN = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: linear polynomial (2 coefficients)
        if (xs.size() == 2) {
            // f(x) = xs[0] + xs[1]*x, so x = -xs[0]/xs[1]
            return -xs.get(0) / xs.get(1);
        }

        // Newton-Raphson method
        double x = 1.0; // initial guess

        for (int i = 0; i < 100; i++) { // max 100 iterations
            double fx = poly(xs, x);

            // Check if we're close enough to zero
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative
            double fpx = 0.0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-10) {
                // Try a different initial guess
                x = (x > 0) ? -1.0 : 1.0;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < 1e-10) {
                return xNext;
            }

            x = xNext;
        }

        // Fallback: return best approximation found
        return x;
    }
}

