class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Handle null cases
        if (a == null || b == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        // Get the minimum length to process
        int len = Math.min(a.length(), b.length());

        // Build result using StringBuilder for efficiency
        StringBuilder result = new StringBuilder(len);

        // XOR each corresponding character
        for (int i = 0; i < len; i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            // XOR logic: same bits give '0', different bits give '1'
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

