     */
    public int largestDivisor(int n) {
        // Start from n/2 since the largest proper divisor cannot exceed n/2
        // and go downwards to find the first divisor
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }
        return 1; // This line is technically unreachable for n > 1, but included for completeness
    }
}

