class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Ensure leading coefficient (highest degree) is non-zero
        int n = xs.size();
        int lastNonZeroIdx = n - 1;
        while (lastNonZeroIdx >= 0 && Math.abs(xs.get(lastNonZeroIdx)) < 1e-12) {
            lastNonZeroIdx--;
        }

        if (lastNonZeroIdx < 0) {
            // All coefficients zero - any x is a solution
            return 0.0;
        }

        // Use Newton's method with multiple starting points for robustness
        // Try several initial guesses
        double[] initialGuesses = {-100.0, -10.0, -1.0, 0.0, 1.0, 10.0, 100.0};

        double bestRoot = Double.NaN;
        double bestResidual = Double.MAX_VALUE;

        for (double start : initialGuesses) {
            double root = newtonMethod(xs, start);

            // Check if this is actually a root
            double residual = Math.abs(poly(xs, root));

            if (residual < bestResidual) {
                bestResidual = residual;
                bestRoot = root;

                // If we found an exact or very close root, return early
                if (residual < 1e-9) {
                    break;
                }
            }
        }

        // If still no good solution, try bisection-like approach on intervals
        if (Double.isNaN(bestRoot) || bestResidual > 1e-6) {
            // Try scanning for sign changes
            for (double x1 = -50.0; x1 <= 50.0; x1 += 1.0) {
                double y1 = poly(xs, x1);
                double x2 = x1 + 1.0;
                double y2 = poly(xs, x2);

                if (y1 * y2 <= 0) {
                    // Sign change detected, use bisection
                    double root = bisection(xs, x1, x2);
                    double residual = Math.abs(poly(xs, root));
                    if (residual < bestResidual) {
                        bestResidual = residual;
                        bestRoot = root;
                        if (residual < 1e-9) break;
                    }
                }
            }
        }

        return !Double.isNaN(bestRoot) ? bestRoot : 0.0;
    }

    private double newtonMethod(List<Double> xs, double startX) {
        double x = startX;

        for (int i = 0; i < 100; i++) { // Max iterations
            double fx = poly(xs, x);

            // If close to root, return
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative
            double fPrimeX = polyDerivative(xs, x);

            // Avoid division by zero
            if (Math.abs(fPrimeX) < 1e-12) {
                // Try small perturbation
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fPrimeX;

            // Check for convergence
            if (Math.abs(xNext - x) < 1e-12) {
                return xNext;
            }

            // Check for divergence (very large step)
            if (Double.isInfinite(xNext) || Double.isNaN(xNext) || Math.abs(xNext) > 1e6) {
                return Double.NaN; // Signal failure
            }

            x = xNext;
        }

        return x; // Return last approximation
    }

    private double polyDerivative(List<Double> xs, double x) {
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }

    private double bisection(List<Double> xs, double a, double b) {
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Ensure we have a sign change
        if (fa * fb > 0) {
            return Double.NaN;
        }

        for (int i = 0; i < 50; i++) { // Bisection iterations
            double c = (a + b) / 2;
            double fc = poly(xs, c);

            if (Math.abs(fc) < 1e-12 || (b - a) < 1e-12) {
                return c;
            }

            if (fa * fc <= 0) {
                b = c;
                fb = fc;
            } else {
                a = c;
                fa = fc;
            }
        }

        return (a + b) / 2;
    }
}

