            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Create a lambda for polynomial evaluation using the poly method
        java.util.function.DoubleUnaryOperator f = x -> poly(xs, x);

        // For odd-degree polynomials, find an interval where sign changes
        // Start with a reasonable range and expand until we find sign change
        double left = -1000.0;
        double right = 1000.0;

        // Expand interval until we find f(left) * f(right) < 0
        while (f.applyAsDouble(left) * f.applyAsDouble(right) > 0) {
            left *= 2;
            right *= 2;
            // Prevent infinite loop for pathological cases
            if (Math.abs(left) > 1e10) {
                // Fallback: try Newton's method starting from 0
                return newtonRaphson(f, 0.0);
            }
        }

        // Bisection method
        double tolerance = 1e-9;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double mid = (left + right) / 2;
            double fMid = f.applyAsDouble(mid);

            if (Math.abs(fMid) < tolerance || (right - left) / 2 < tolerance) {
                return mid;
            }

            if (f.applyAsDouble(left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Return midpoint if we didn't converge within tolerance
        return (left + right) / 2;
    }

    // Helper method using Newton-Raphson as fallback
    private double newtonRaphson(java.util.function.DoubleUnaryOperator f, double x0) {
        double x = x0;
        double tolerance = 1e-9;
        int maxIterations = 100;

        for (int i = 0; i < maxIterations; i++) {
            double fx = f.applyAsDouble(x);
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Numerical derivative
            double h = 1e-8;
            double dfx = (f.applyAsDouble(x + h) - fx) / h;

            if (Math.abs(dfx) < 1e-15) {
                // Derivative too small, switch to bisection or return current
                return x;
            }

            x = x - fx / dfx;

            // Check for overflow
            if (Double.isNaN(x) || Double.isInfinite(x)) {
                break;
            }
        }

        return x;
    }
}

