class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Handle small cases directly for efficiency
        if (n == 1) return 2;
        if (n == 2) return 3;
        if (n == 3) return 5;
        if (n == 4) return 13;
        if (n == 5) return 89;

        // Start generating Fibonacci numbers from F(7) = 13 onwards
        long a = 8;  // F(6)
        long b = 13; // F(7)
        int count = 4; // We already counted 2,3,5,13

        while (true) {
            // Check if current Fibonacci number (b) is prime
            if (isPrime(b)) {
                count++;
                if (count == n) {
                    return (int) b;
                }
            }

            // Generate next Fibonacci number
            long c = a + b;
            a = b;
            b = c;

            // Safety check for overflow (though for reasonable n this shouldn't happen)
            if (b > Integer.MAX_VALUE) {
                throw new ArithmeticException("Result exceeds Integer.MAX_VALUE");
            }
        }
    }

    // Helper method to check if a number is prime
    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0) return false;
        if (num % 3 == 0) return num == 3;

        // Check for divisors up to sqrt(num)
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

