class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge case: constant polynomial (degree 0)
        if (xs.size() <= 1) {
            if (xs.isEmpty() || xs.get(0) == 0) {
                return 0.0; // identity function or zero polynomial
            }
            throw new IllegalArgumentException("Constant polynomial has no roots");
        }

        // For linear case: a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) < 1e-12) {
                throw new IllegalArgumentException("Linear coefficient is zero");
            }
            return -a / b;
        }

        // Newton-Raphson method with multiple starting points
        double x = 1.0; // initial guess
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative: f'(x) = sum(i * coeff[i] * x^(i-1))
            double fpx = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fpx += i * xs.get(i) * Math.pow(x, i - 1);
            }

            // If derivative is too small, perturb x slightly
            if (Math.abs(fpx) < 1e-12) {
                x += (Math.random() - 0.5) * 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < tolerance) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNext)) < tolerance) {
                    return xNext;
                }
            }

            x = xNext;
        }

        // If Newton-Raphson failed, try bisection with reasonable bounds
        // Since we have odd degree (even number of coefficients), 
        // the polynomial goes to +/- infinity at extremes
        double left = -100.0;
        double right = 100.0;

        // Find bounds where sign changes
        while (poly(xs, left) * poly(xs, right) > 0 && (right - left) < 10000) {
            left *= 2;
            right *= 2;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fmid = poly(xs, mid);

            if (Math.abs(fmid) < tolerance) {
                return mid;
            }

            if (poly(xs, left) * fmid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Return midpoint as last resort
        return (left + right) / 2;
    }
}

