class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For degree 1 polynomial (2 coefficients): a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            return -a / b;
        }

        // For higher degrees, use Newton-Raphson method
        // First, find a good starting point by checking values at integer points
        double x = 0.0;
        double tolerance = 1e-10;
        int maxIterations = 1000;

        // Try Newton-Raphson from several starting points
        for (double startX : new double[]{0.0, 1.0, -1.0, 2.0, -2.0, 0.5, -0.5}) {
            x = startX;
            for (int iter = 0; iter < maxIterations; iter++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < tolerance) {
                    return x;
                }

                // Calculate derivative
                double fPrimeX = 0.0;
                for (int i = 1; i < xs.size(); i++) {
                    fPrimeX += i * xs.get(i) * Math.pow(x, i - 1);
                }

                // Avoid division by zero
                if (Math.abs(fPrimeX) < 1e-15) {
                    break; // Try next starting point
                }

                double newX = x - fx / fPrimeX;

                // Check if we're diverging
                if (Double.isNaN(newX) || Double.isInfinite(newX) || Math.abs(newX - x) > 1e10) {
                    break;
                }

                x = newX;
            }
        }

        // If Newton-Raphson fails, try bisection method
        // Find interval where function changes sign
        double left = -100.0;
        double right = 100.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Extend search range if needed
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 20) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        if (fLeft * fRight <= 0) {
            // Bisection method
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);

                if (Math.abs(fMid) < tolerance || (right - left) < tolerance) {
                    return mid;
                }

                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
        }

        // Fallback: return last computed value from Newton-Raphson
        return x;
    }
}

