class Solution {
    public String stringXor(String a, String b) {
        // Handle edge cases
        if (a == null || b == null) {
            return a == null ? b : a;
        }

        // Determine the maximum length (assuming we XOR up to the length of the shorter string,
        // or pad with zeros if needed - but based on the problem description, likely same length)
        int len = Math.min(a.length(), b.length());

        StringBuilder result = new StringBuilder();

        for (int i = 0; i < len; i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            // XOR logic: if bits are same, result is '0'; if different, result is '1'
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

