        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For linear case: a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) > 1e-12) {
                return -a / b;
            }
            // Fallback for degenerate case
        }

        // Newton-Raphson method with multiple starting points
        int maxIterations = 100;
        double tolerance = 1e-10;

        // Try different starting points
        double[] starts = {0.0, 1.0, -1.0, 2.0, -2.0, 0.5, -0.5, 10.0, -10.0, 100.0, -100.0};

        for (double start : starts) {
            double x = start;
            for (int i = 0; i < maxIterations; i++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < tolerance) {
                    return x;
                }

                // Compute derivative: f'(x) = sum(i * xs[i] * x^(i-1))
                double fpx = 0;
                for (int j = 1; j < xs.size(); j++) {
                    fpx += j * xs.get(j) * Math.pow(x, j - 1);
                }

                if (Math.abs(fpx) < 1e-12) {
                    // Derivative too small, try next starting point
                    break;
                }

                double xNext = x - fx / fpx;

                // Check for divergence
                if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                    break;
                }

                if (Math.abs(xNext - x) < tolerance) {
                    // Check if this is actually a root
                    if (Math.abs(poly(xs, xNext)) < tolerance) {
                        return xNext;
                    }
                }

                x = xNext;
            }
        }

        // If Newton-Raphson fails, try bisection on a reasonable interval
        // For polynomials with even number of coefficients (odd degree), 
        // we know limits go to +/- infinity, so there should be a sign change

        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Find interval with sign change
        while (fLeft * fRight > 0 && (right - left) < 1e10) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        if (fLeft * fRight <= 0) {
            // Bisection method
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);

                if (Math.abs(fMid) < tolerance || (right - left) < tolerance) {
                    return mid;
                }

                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
        }

        // Last resort: return midpoint of search range
        return (left + right) / 2;
    }
}

