class Solution {
    /**
    Insert a number 'delimeter' between every two consecutive elements of input list `numbers'
    >>> intersperse(List.of(), 4)
    []
    >>> intersperse(Arrays.asList(1, 2, 3), 4)
    [1, 4, 2, 4, 3]
     */
    public List<Integer> intersperse(List<Integer> numbers, int delimiter) {
        // Handle null input gracefully
        if (numbers == null) {
            return new ArrayList<>();
        }

        // If the list is empty or has only one element, return a copy
        if (numbers.size() <= 1) {
            return new ArrayList<>(numbers);
        }

        // Calculate the expected size: original size + (size - 1) delimiters
        int expectedSize = numbers.size() + Math.max(0, numbers.size() - 1);
        List<Integer> result = new ArrayList<>(expectedSize);

        // Add first element
        result.add(numbers.get(0));

        // Add remaining elements with delimiter before each one
        for (int i = 1; i < numbers.size(); i++) {
            result.add(delimiter);
            result.add(numbers.get(i));
        }

        return result;
    }
}

