class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return -1; // No proper divisors for 1 or non-positive numbers
        }

        // Start checking from n/2 downwards since the largest proper divisor 
        // cannot be larger than n/2 (except for n=1, which we handled above)
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // This line is theoretically unreachable since 1 always divides n
    }
}

