class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For polynomials with odd degree (even number of coefficients),
        // there's always at least one real root.
        // We'll use Newton-Raphson method with fallback to bisection.

        // First, find the degree (highest non-zero coefficient index)
        int degree = xs.size() - 1;
        while (degree > 0 && Math.abs(xs.get(degree)) < 1e-12) {
            degree--;
        }

        // For linear case: xs[0] + xs[1]*x = 0 => x = -xs[0]/xs[1]
        if (degree == 1) {
            return -xs.get(0) / xs.get(1);
        }

        // For constant case (shouldn't happen per problem statement, but handle safely)
        if (degree == 0) {
            return 0.0; // or throw exception
        }

        // Use Newton-Raphson with multiple starting points to increase chances of finding a root
        double[] startingPoints = {0.0, 1.0, -1.0, 10.0, -10.0, 100.0, -100.0};

        for (double start : startingPoints) {
            double x = start;
            for (int i = 0; i < 100; i++) { // max iterations
                double fx = poly(xs, x);
                if (Math.abs(fx) < 1e-9) {
                    return x;
                }

                // Calculate derivative
                double fpx = 0.0;
                for (int j = 1; j < xs.size(); j++) {
                    fpx += j * xs.get(j) * Math.pow(x, j - 1);
                }

                // Avoid division by zero
                if (Math.abs(fpx) < 1e-12) {
                    break;
                }

                double newX = x - fx / fpx;

                // Check if we've converged or gone too far
                if (Double.isNaN(newX) || Double.isInfinite(newX) || Math.abs(newX - x) < 1e-12) {
                    break;
                }

                x = newX;
            }
        }

        // Fallback to bisection method on a large interval
        // Since odd degree polynomials go from -∞ to +∞ or vice versa
        double left = -1000.0;
        double right = 1000.0;
        double fl = poly(xs, left);
        double fr = poly(xs, right);

        // Ensure we have opposite signs (if not, expand interval)
        int attempts = 0;
        while (fl * fr > 0 && attempts < 5) {
            left *= 10;
            right *= 10;
            fl = poly(xs, left);
            fr = poly(xs, right);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < 1e-9) {
                return mid;
            }

            if (fl * fm < 0) {
                right = mid;
                fr = fm;
            } else {
                left = mid;
                fl = fm;
            }
        }

        // Return midpoint as last resort
        return (left + right) / 2;
    }
}

