class Solution {
    public int fizzBuzz(int n) {
        int count = 0;

        // Check each number from 0 to n-1
        for (int i = 0; i < n; i++) {
            // Check if divisible by 11 or 13
            if (i % 11 == 0 || i % 13 == 0) {
                // Count occurrences of '7' in the number
                int num = i;
                // Handle 0 separately since log10(0) is undefined
                if (num == 0) {
                    // 0 doesn't contain digit 7, so nothing to add
                    continue;
                }

                // Count digits equal to 7
                while (num > 0) {
                    if (num % 10 == 7) {
                        count++;
                    }
                    num /= 10;
                }
            }
        }

        return count;
    }
}

