class Solution {
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Find the highest degree non-zero coefficient (leading term)
        int n = xs.size() - 1;
        int leadingIndex = n;
        while (leadingIndex >= 0 && Math.abs(xs.get(leadingIndex)) < 1e-15) {
            leadingIndex--;
        }

        // If all coefficients are zero, any x is a solution
        if (leadingIndex < 0) {
            return 0.0;
        }

        // The degree of polynomial
        int degree = leadingIndex;

        // We need even number of coefficients (odd degree) as per requirement
        // But let's be defensive and handle any case

        // For bisection, we need to find an interval [a, b] where f(a)*f(b) < 0
        // For odd degree polynomial, as x->+inf, f(x)->sign(a)*inf, as x->-inf, f(x)->-sign(a)*inf
        // So there must be sign change somewhere

        double a = -1000.0;
        double b = 1000.0;

        // Adjust interval to ensure sign change
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Expand interval until we find sign change
        int attempts = 0;
        while (fa * fb > 0 && attempts < 20) {
            a *= 10;
            b *= 10;
            fa = poly(xs, a);
            fb = poly(xs, b);
            attempts++;
        }

        // If still no sign change, try different approach
        if (fa * fb > 0) {
            // Try centered around 0 with symmetric bounds
            a = -1.0;
            b = 1.0;
            fa = poly(xs, a);
            fb = poly(xs, b);

            // Expand until we find sign change
            for (int i = 0; i < 30 && fa * fb > 0; i++) {
                a *= 2;
                b *= 2;
                fa = poly(xs, a);
                fb = poly(xs, b);
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (a + b) / 2;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < 1e-12) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2;
    }
}

