class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        // Map number words to their numeric values
        Map<String, Integer> wordToNum = new HashMap<>();
        wordToNum.put("zero", 0);
        wordToNum.put("one", 1);
        wordToNum.put("two", 2);
        wordToNum.put("three", 3);
        wordToNum.put("four", 4);
        wordToNum.put("five", 5);
        wordToNum.put("six", 6);
        wordToNum.put("seven", 7);
        wordToNum.put("eight", 8);
        wordToNum.put("nine", 9);

        // Split input string into words
        String[] words = numbers.trim().split("\\s+");

        // Convert to list of numeric values with original words for sorting
        List<String> wordList = new ArrayList<>();
        List<Integer> numList = new ArrayList<>();

        for (String word : words) {
            wordList.add(word);
            numList.add(wordToNum.get(word));
        }

        // Create indices array and sort by numeric values
        Integer[] indices = new Integer[words.length];
        for (int i = 0; i < indices.length; i++) {
            indices[i] = i;
        }

        Arrays.sort(indices, (a, b) -> numList.get(a) - numList.get(b));

        // Build result using sorted indices
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < indices.length; i++) {
            if (i > 0) {
                result.append(" ");
            }
            result.append(wordList.get(indices[i]));
        }

        return result.toString();
    }
}

