class Solution {
    public double findZero(List<Double> xs) {
            // Handle edge case: constant polynomial (but problem says even number of coefficients,
            // so minimum is 2 coefficients, meaning degree 1)

            // Find a large enough interval where the function changes sign
            // Since leading coefficient is non-zero and degree is odd, function goes to ±∞
            double leadingCoeff = xs.get(xs.size() - 1);
            double direction = leadingCoeff > 0 ? 1 : -1;

            // Start with a reasonable interval
            double left = -1000.0;
            double right = 1000.0;

            // Expand interval until we find sign change
            while (poly(xs, left) * poly(xs, right) > 0) {
                left *= 10;
                right *= 10;
                // Safety limit to prevent infinite loop
                if (Math.abs(left) > 1e10) {
                    break;
                }
            }

            // Bisection method
            double mid = 0;
            int maxIterations = 100;
            double tolerance = 1e-10;

            for (int i = 0; i < maxIterations; i++) {
                mid = (left + right) / 2.0;
                double fMid = poly(xs, mid);

                if (Math.abs(fMid) < tolerance) {
                    break;
                }

                if (poly(xs, left) * fMid < 0) {
                    right = mid;
                } else {
                    left = mid;
                }
            }

            return mid;
        }
}

