class Solution {
    public int largestDivisor(int n) {
        // Edge cases: n <= 1 has no proper divisors
        if (n <= 1) {
            return 0; // or throw exception, but problem implies valid input
        }

        // Check from n/2 down to 1
        // The largest proper divisor cannot be larger than n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // This line is theoretically unreachable since 1 always divides n
    }
}

