class Solution {
    public double findZero(List<Double> xs) {
        // Ensure we have even number of coefficients as required
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Bisection method parameters
        double left = -1000.0;
        double right = 1000.0;
        double tolerance = 1e-9;

        // Check if we have a sign change in the interval
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If no sign change, expand the search range
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 10) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // If still no sign change, use Newton's method or fallback
        if (fLeft * fRight > 0) {
            // Try to find any root by scanning for sign change
            for (double x = -100; x <= 100; x += 0.1) {
                double fx = poly(xs, x);
                double fxNext = poly(xs, x + 0.1);
                if (fx == 0) return x;
                if (fx * fxNext < 0) {
                    left = x;
                    right = x + 0.1;
                    break;
                }
            }
        }

        // Bisection method
        while (right - left > tolerance) {
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance) {
                return mid;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2.0;
    }
}

