        }

        // Sort the list to make comparison more efficient
        // After sorting, only adjacent elements need to be compared
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        // Check adjacent pairs only - if any pair has difference < threshold, return true
        for (int i = 0; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < threshold) {
                return true;
            }
        }

        return false;
    }
}

