        String[] words = numbers.trim().split("\\s+");

        // Convert words to numbers, sort, then convert back
        List<String> sortedWords = Arrays.stream(words)
            .map(word -> new Integer[]{wordToNum.get(word), word})
            .sorted(Comparator.comparingInt(arr -> arr[0]))
            .map(arr -> arr[1])
            .collect(Collectors.toList());

        return String.join(" ", sortedWords);
    }
}

