import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For small polynomials, we can try analytical solutions or simple iteration
        // Newton-Raphson method

        // Handle edge case: constant polynomial (but problem says even number of coefficients, so minimum 2)
        if (xs.size() == 2) {
            // Linear: a + bx = 0 -> x = -a/b
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) > 1e-12) {
                return -a / b;
            }
        }

        // For higher degrees, use Newton-Raphson
        double x = 1.0; // Initial guess

        for (int iter = 0; iter < 100; iter++) {
            double fx = poly(xs, x);

            // Check if we're close enough to a root
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative numerically or analytically
            double h = 1e-9;
            double fpx = (poly(xs, x + h) - poly(xs, x)) / h;

            if (Math.abs(fpx) < 1e-12) {
                // Derivative too small, try different starting point
                x += 1.0;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < 1e-12) {
                return xNext;
            }

            x = xNext;
        }

        // Fallback: return current approximation
        return x;
    }
}

