    public List<Integer> parseMusic(String string) {
        List<Integer> result = new ArrayList<>();

        if (string == null || string.trim().isEmpty()) {
            return result;
        }

        String[] notes = string.trim().split("\\s+");

        for (String note : notes) {
            switch (note) {
                case "o":
                    result.add(4);
                    break;
                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // Ignore unknown notes or could throw exception
                    break;
            }
        }

        return result;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Handle edge cases
        if (substring == null || substring.isEmpty() || string == null) {
            return 0;
        }

        int count = 0;
        int index = 0;

        // Search for substring starting from each position
        while (index <= string.length() - substring.length()) {
            // Find next occurrence starting from current index
            int foundIndex = string.indexOf(substring, index);

            if (foundIndex == -1) {
                break;
            }

            count++;
            // Move forward by 1 to allow overlapping matches
            index = foundIndex + 1;
        }

        return count;
    }
}

