class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
            // For linear polynomial: a + bx = 0 -> x = -a/b
            if (xs.size() == 2) {
                double a = xs.get(0);
                double b = xs.get(1);
                if (b == 0) {
                    // Degenerate case, but problem guarantees solution exists
                    return 0.0;
                }
                return -a / b;
            }

            // Create a function to evaluate polynomial
            java.util.function.DoubleUnaryOperator f = x -> {
                double result = 0;
                double xPower = 1;
                for (double coeff : xs) {
                    result += coeff * xPower;
                    xPower *= x;
                }
                return result;
            };

            // Derivative function
            java.util.function.DoubleUnaryOperator fPrime = x -> {
                double result = 0;
                double xPower = 1;
                for (int i = 1; i < xs.size(); i++) {
                    result += i * xs.get(i) * xPower;
                    xPower *= x;
                }
                return result;
            };

            // Newton-Raphson with multiple starting points
            double[] startPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 0.5, -0.5, 10.0, -10.0};

            for (double start : startPoints) {
                double x = start;
                for (int iter = 0; iter < 100; iter++) {
                    double fx = f.applyAsDouble(x);
                    if (Math.abs(fx) < 1e-10) {
                        return x;
                    }

                    double fpx = fPrime.applyAsDouble(x);
                    if (Math.abs(fpx) < 1e-10) {
                        break; // Derivative too small, try next start point
                    }

                    double nextX = x - fx / fpx;
                    if (Double.isNaN(nextX) || Double.isInfinite(nextX)) {
                        break;
                    }

                    // Check convergence
                    if (Math.abs(nextX - x) < 1e-10) {
                        if (Math.abs(f.applyAsDouble(nextX)) < 1e-8) {
                            return nextX;
                        }
                        break;
                    }

                    x = nextX;
                }
            }

            // Fallback: try bisection method on reasonable interval
            double left = -100.0, right = 100.0;
            double fl = f.applyAsDouble(left);
            double fr = f.applyAsDouble(right);

            // Find interval where sign changes
            for (int i = 0; i < 50; i++) {
                if (fl * fr <= 0) {
                    break;
                }
                left *= 2;
                right *= 2;
                fl = f.applyAsDouble(left);
                fr = f.applyAsDouble(right);
            }

            // Bisection
            if (fl * fr <= 0) {
                for (int i = 0; i < 100; i++) {
                    double mid = (left + right) / 2;
                    double fm = f.applyAsDouble(mid);
                    if (Math.abs(fm) < 1e-10) {
                        return mid;
                    }
                    if (fl * fm <= 0) {
                        right = mid;
                        fr = fm;
                    } else {
                        left = mid;
                        fl = fm;
                    }
                }
                return (left + right) / 2;
            }

            // Last resort: return average of all roots (for polynomials with known roots)
            // Since problem guarantees solution exists, and examples have integer roots,
            // try simple integer values
            for (int i = -10; i <= 10; i++) {
                double val = 0;
                double xPower = 1;
                for (double coeff : xs) {
                    val += coeff * xPower;
                    xPower *= i;
                }
                if (Math.abs(val) < 1e-9) {
                    return i;
                }
            }

            // Final fallback - return 0.0 (shouldn't happen per problem statement)
            return 0.0;
        }
}

