class Solution {
    public List<String> separateParenGroups(String paren_string) {
        List<String> result = new ArrayList<>();

        // Remove all spaces
        String cleanString = paren_string.replace(" ", "");

        int depth = 0;
        int startIndex = -1;

        for (int i = 0; i < cleanString.length(); i++) {
            char c = cleanString.charAt(i);

            if (c == '(') {
                if (depth == 0) {
                    startIndex = i; // Start of a new group
                }
                depth++;
            } else if (c == ')') {
                depth--;
                if (depth == 0) {
                    // Completed a balanced group
                    result.add(cleanString.substring(startIndex, i + 1));
                }
            }
        }

        return result;
    }
}

