            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Horner's method for efficiency and numerical stability
        double result = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Trim trailing zeros to get the actual degree
        List<Double> coeffs = new ArrayList<>(xs);
        while (coeffs.size() > 1 && coeffs.get(coeffs.size() - 1) == 0) {
            coeffs.remove(coeffs.size() - 1);
        }

        // Check that we have even number of original coefficients (as per problem)
        // and now odd degree (since degree = coeffs.size() - 1)
        if (coeffs.size() % 2 == 0) {
            throw new IllegalArgumentException("Must have even number of coefficients");
        }

        int degree = coeffs.size() - 1;
        if (degree % 2 == 0) {
            throw new IllegalArgumentException("Polynomial degree must be odd for guaranteed root");
        }

        // For linear case (degree 1), solve directly
        if (degree == 1) {
            double a = coeffs.get(1); // coefficient of x
            double b = coeffs.get(0); // constant term
            return -b / a;
        }

        // For higher odd degrees, use bisection method
        // First, find an interval [a, b] where f(a) * f(b) < 0
        double left = -1000.0;
        double right = 1000.0;

        // Expand the search range until we find opposite signs
        while (poly(coeffs, left) * poly(coeffs, right) > 0) {
            left *= 2;
            right *= 2;
            if (Math.abs(left) > 1e9) {
                // Fallback: try smaller range or use Newton's method
                left = -10.0;
                right = 10.0;
                break;
            }
        }

        // Bisection method
        double mid;
        int iterations = 100; // enough for double precision
        for (int i = 0; i < iterations; i++) {
            mid = (left + right) / 2.0;
            double fMid = poly(coeffs, mid);

            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }

            if (poly(coeffs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2.0;
    }
}

