class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special case for small n - check F(3)=2, F(4)=3, F(5)=5, etc.
        // Note: F(0)=0, F(1)=1, F(2)=1, F(3)=2, F(4)=3, F(5)=5, F(6)=8, F(7)=13, ...

        if (n == 1) return 2;
        if (n == 2) return 3;
        if (n == 3) return 5;

        // Start from F(3) = 2
        long fib = 2;
        int index = 3;

        count = 1; // We already know 2 is the first Fibonacci prime

        while (count < n) {
            if (isPrime(fib)) {
                count++;
                if (count == n) {
                    return (int) fib;
                }
            }

            // Generate next Fibonacci number
            long temp = a + b;
            a = b;
            b = fib;
            fib = temp;
            index++;
        }

        return (int) fib;
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;

        // Check for divisors up to sqrt(num)
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

