class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Handle null cases
        if (a == null || b == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        // Ensure both strings have the same length
        // If they have different lengths, we can pad the shorter one with leading zeros
        // or handle based on the problem requirements. Given the example, we'll assume same length
        // but for robustness, let's handle different lengths by padding with leading zeros
        int lenA = a.length();
        int lenB = b.length();
        int maxLen = Math.max(lenA, lenB);

        // Pad both strings to the same length with leading zeros
        StringBuilder paddedA = new StringBuilder(a);
        StringBuilder paddedB = new StringBuilder(b);

        while (paddedA.length() < maxLen) {
            paddedA.insert(0, '0');
        }
        while (paddedB.length() < maxLen) {
            paddedB.insert(0, '0');
        }

        StringBuilder result = new StringBuilder(maxLen);

        for (int i = 0; i < maxLen; i++) {
            char bitA = paddedA.charAt(i);
            char bitB = paddedB.charAt(i);

            // XOR logic: same bits give 0, different bits give 1
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

