class Solution {
    public double findZero(List<Double> xs) {
            // Use Newton-Raphson method to find a root
            // Start with initial guess and iterate
            double x = 0.0;
            double epsilon = 1e-9;
            int maxIterations = 1000;

            for (int iter = 0; iter < maxIterations; iter++) {
                double fx = poly(xs, x);

                // If we're close enough to zero, return
                if (Math.abs(fx) < epsilon) {
                    return x;
                }

                // Compute derivative
                double fPrimeX = 0.0;
                for (int i = 1; i < xs.size(); i++) {
                    fPrimeX += i * xs.get(i) * Math.pow(x, i - 1);
                }

                // Avoid division by zero
                if (Math.abs(fPrimeX) < 1e-15) {
                    // Try a small perturbation
                    x += 0.1;
                    continue;
                }

                double nextX = x - fx / fPrimeX;

                // Check for convergence
                if (Math.abs(nextX - x) < epsilon) {
                    return nextX;
                }

                x = nextX;

                // Handle overflow or extreme values
                if (Double.isNaN(x) || Double.isInfinite(x)) {
                    // Reset to a different starting point
                    x = (iter % 2 == 0) ? 1.0 : -1.0;
                }
            }

            // Fallback: return the best approximation found
            return x;
        }
}

