import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        double xPower = 1.0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * xPower;
            xPower *= x;
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Create a lambda for the polynomial function
        java.util.function.DoubleUnaryOperator f = x -> poly(xs, x);

        // For polynomials of odd degree (even number of coefficients), 
        // we know there's at least one real root

        // Try to find an interval [a, b] where f(a) and f(b) have opposite signs
        double a = -1000.0;
        double b = 1000.0;
        double fa = f.applyAsDouble(a);
        double fb = f.applyAsDouble(b);

        // If we're lucky and find exact root
        if (Math.abs(fa) < 1e-9) return a;
        if (Math.abs(fb) < 1e-9) return b;

        // Expand search range if needed to ensure sign change
        int attempts = 0;
        while (fa * fb > 0 && attempts < 20) {
            a *= 2;
            b *= 2;
            fa = f.applyAsDouble(a);
            fb = f.applyAsDouble(b);
            attempts++;
        }

        // If still no sign change, try symmetric points around 0
        if (fa * fb > 0) {
            a = -10.0;
            b = 10.0;
            fa = f.applyAsDouble(a);
            fb = f.applyAsDouble(b);
            attempts = 0;
            while (fa * fb > 0 && attempts < 30) {
                a -= 10.0;
                b += 10.0;
                fa = f.applyAsDouble(a);
                fb = f.applyAsDouble(b);
                attempts++;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (a + b) / 2.0;
            double fm = f.applyAsDouble(mid);

            if (Math.abs(fm) < 1e-9) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        // Return midpoint as fallback
        return (a + b) / 2.0;
    }
}

