class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        if (n <= 1) {
            return 0; // or -1, depending on specification, but n > 1 for meaningful divisors
        }

        // Check for divisors from 2 to sqrt(n)
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                // i is a divisor, so n/i is also a divisor
                // n/i is larger than i (since i <= sqrt(n)), so it's our answer
                return n / i;
            }
        }

        // If no divisor found, n is prime, so largest proper divisor is 1
        return 1;
    }
}

