import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: constant polynomial (shouldn't happen with even coefficients >=2)
        if (xs.size() < 2) {
            return 0.0;
        }

        // Use Newton-Raphson method with fallback to bisection

        // Try Newton-Raphson starting from several initial guesses
        double[] initialGuesses = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

        for (double guess : initialGuesses) {
            double root = newtonRaphson(xs, guess);
            if (!Double.isNaN(root) && !Double.isInfinite(root)) {
                // Verify it's actually a root (within tolerance)
                double value = poly(xs, root);
                if (Math.abs(value) < 1e-9) {
                    return root;
                }
            }
        }

        // If Newton-Raphson failed, try bisection method
        // For odd-degree polynomial, as x->±∞, p(x)->±∞ or ∓∞
        // Find interval where sign changes
        double left = -100.0;
        double right = 100.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand interval until we find sign change
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 20) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // Now use bisection
        if (fLeft * fRight <= 0) {
            return bisection(xs, left, right);
        }

        // Fallback
        return 0.0;
    }

    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Calculate derivative numerically or analytically
            double fpx = polyDerivative(xs, x);
            if (Math.abs(fpx) < 1e-12) {
                return Double.NaN; // Derivative too small, avoid division by zero
            }

            double xNew = x - fx / fpx;
            if (Double.isNaN(xNew) || Double.isInfinite(xNew)) {
                return Double.NaN;
            }

            if (Math.abs(xNew - x) < 1e-12) {
                return xNew;
            }

            x = xNew;
        }
        return x; // Return last approximation
    }

    private double polyDerivative(List<Double> xs, double x) {
        // derivative of a₀ + a₁x + a₂x² + ... + aₙxⁿ is a₁ + 2a₂x + 3a₃x² + ... + naₙxⁿ⁻¹
        if (xs.size() <= 1) {
            return 0.0;
        }

        double result = 0.0;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }

    private double bisection(List<Double> xs, double left, double right) {
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Ensure f(left) and f(right) have opposite signs
        if (fLeft * fRight > 0) {
            return Double.NaN;
        }

        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12 || (right - left) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }
        return (left + right) / 2;
    }
}

