    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Verify even number of coefficients
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Convert to array for faster access
        double[] coeffs = xs.stream().mapToDouble(Double::doubleValue).toArray();

        // Use Newton-Raphson method with fallback to bisection
        double x = 1.0; // Initial guess

        for (int i = 0; i < 100; i++) {
            double fx = polyValue(coeffs, x);

            // If close enough to zero, return
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative
            double fpx = derivativeValue(coeffs, x);

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-10) {
                // Try different approach: bisection between -100 and 100
                return bisection(coeffs, -100.0, 100.0);
            }

            double xNext = x - fx / fpx;

            // Check for divergence
            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                return bisection(coeffs, -100.0, 100.0);
            }

            // Limit step size to avoid overshooting
            if (Math.abs(xNext - x) > 100) {
                xNext = x + (xNext > x ? 100 : -100);
            }

            x = xNext;
        }

        // Fallback: bisection
        return bisection(coeffs, -100.0, 100.0);
    }

    private double polyValue(double[] coeffs, double x) {
        double result = 0;
        double xPower = 1;
        for (double coeff : coeffs) {
            result += coeff * xPower;
            xPower *= x;
        }
        return result;
    }

    private double derivativeValue(double[] coeffs, double x) {
        // Derivative: if coeffs = [a0, a1, a2, ..., an], then derivative is [a1, 2*a2, ..., n*an]
        double result = 0;
        double xPower = 1;
        for (int i = 1; i < coeffs.length; i++) {
            result += i * coeffs[i] * xPower;
            xPower *= x;
        }
        return result;
    }

    private double bisection(double[] coeffs, double left, double right) {
        double fLeft = polyValue(coeffs, left);
        double fRight = polyValue(coeffs, right);

        // If no sign change, try wider bounds
        if (fLeft * fRight > 0) {
            for (int exp = 1; exp <= 10; exp++) {
                double newLeft = -Math.pow(10, exp);
                double newRight = Math.pow(10, exp);
                fLeft = polyValue(coeffs, newLeft);
                fRight = polyValue(coeffs, newRight);
                if (fLeft * fRight <= 0) {
                    left = newLeft;
                    right = newRight;
                    break;
                }
            }
        }

        // Now do bisection
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = polyValue(coeffs, mid);

            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

