import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle degenerate case: constant polynomial (degree 0)
        if (xs.size() <= 1) {
            return xs.isEmpty() ? 0.0 : -xs.get(0);
        }

        // Newton-Raphson method
        double x = 0.0; // initial guess
        double tolerance = 1e-9;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = polyValue(xs, x);

            // Check if we've found a root
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative numerically
            double h = 1e-8;
            double fpx = (polyValue(xs, x + h) - fx) / h;

            // Avoid division by zero or very small derivative
            if (Math.abs(fpx) < 1e-12) {
                // Try a different starting point or use bisection fallback
                x += 1.0;
                continue;
            }

            double newX = x - fx / fpx;

            // Check for convergence
            if (Math.abs(newX - x) < tolerance) {
                return newX;
            }

            x = newX;
        }

        // Fallback: if Newton-Raphson fails, try bisection over a range
        // Since it's guaranteed to have a root, and it's an odd-degree polynomial
        // we can search for sign changes
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = polyValue(xs, left);
        double fRight = polyValue(xs, right);

        // Ensure we have a sign change
        while (fLeft * fRight > 0 && (left > -10000 || right < 10000)) {
            left *= 10;
            right *= 10;
            fLeft = polyValue(xs, left);
            fRight = polyValue(xs, right);
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = polyValue(xs, mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }

    // Helper method to evaluate polynomial at x
    private double polyValue(List<Double> coeffs, double x) {
        double result = 0;
        double xPower = 1;
        for (double coeff : coeffs) {
            result += coeff * xPower;
            xPower *= x;
        }
        return result;
    }
}

