class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special case: check 2 separately since our sequence starts with 0,1,1,2...
        if (n == 1) {
            return 2;
        }

        // Generate Fibonacci numbers starting from F(0) = 0
        while (true) {
            long fib = a;

            // Skip 0 and 1 as they are not prime
            if (fib > 1 && isPrime(fib)) {
                count++;
                if (count == n) {
                    return (int) fib;
                }
            }

            // Update Fibonacci sequence
            long temp = a;
            a = b;
            b = temp + b;
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

