class Solution {
    public double findZero(List<Double> xs) {
        // Remove trailing zeros to get actual degree
        int n = xs.size() - 1;
        while (n >= 0 && Math.abs(xs.get(n)) < 1e-12) {
            n--;
        }
        if (n < 0) {
            return 0.0; // zero polynomial
        }

        // We need even number of coefficients, meaning odd degree polynomial
        // which guarantees at least one real root

        // Get leading coefficient
        double leadCoeff = xs.get(n);

        // Find Cauchy's bound: 1 + max(|a_i / leadCoeff|) for i < n
        double maxRatio = 0;
        for (int i = 0; i < n; i++) {
            maxRatio = Math.max(maxRatio, Math.abs(xs.get(i) / leadCoeff));
        }
        double bound = 1 + maxRatio;

        // Use bisection method to find a root in [-bound, bound]
        double left = -bound;
        double right = bound;

        // Evaluate polynomial at endpoints
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If signs are same, expand search range
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 10) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

