class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        // Create mapping from number words to their numeric values
        Map<String, Integer> numberMap = new HashMap<>();
        numberMap.put("zero", 0);
        numberMap.put("one", 1);
        numberMap.put("two", 2);
        numberMap.put("three", 3);
        numberMap.put("four", 4);
        numberMap.put("five", 5);
        numberMap.put("six", 6);
        numberMap.put("seven", 7);
        numberMap.put("eight", 8);
        numberMap.put("nine", 9);

        // Split input string into individual number words
        String[] parts = numbers.split("\\s+");

        // Sort the parts based on their numeric values using the map
        Arrays.sort(parts, (a, b) -> {
            int valA = numberMap.getOrDefault(a.toLowerCase(), -1);
            int valB = numberMap.getOrDefault(b.toLowerCase(), -1);
            return Integer.compare(valA, valB);
        });

        // Join the sorted parts back into a space-delimited string
        return String.join(" ", parts);
    }
}

