class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Handle edge cases
        if (substring == null || substring.isEmpty() || string == null || string.isEmpty()) {
            return 0;
        }

        int count = 0;
        int startIndex = 0;

        while (startIndex <= string.length() - substring.length()) {
            int foundIndex = string.indexOf(substring, startIndex);
            if (foundIndex == -1) {
                break;
            }
            count++;
            startIndex = foundIndex + 1; // Move by 1 to allow overlapping matches
        }

        return count;
    }
}

