class Solution {
    public double findZero(List<Double> xs) {
        // Newton-Raphson method
        double x = 1.0; // initial guess

        for (int i = 0; i < 100; i++) { // max iterations
            double fx = poly(xs, x);

            // Check if we're close enough to a root
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative numerically (or analytically)
            double fpx = derivative(xs, x);

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-10) {
                // Try a different starting point
                x += 0.1;
                continue;
            }

            double nextX = x - fx / fpx;

            // Check for convergence
            if (Math.abs(nextX - x) < 1e-10) {
                return x;
            }

            x = nextX;
        }

        // If we didn't converge, return best estimate
        return x;
    }

    // Helper method to compute derivative at point x
    private double derivative(List<Double> coeffs, double x) {
        if (coeffs.size() <= 1) {
            return 0.0;
        }

        double result = 0;
        for (int i = 1; i < coeffs.size(); i++) {
            result += i * coeffs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

