class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Find the highest degree term (last non-zero coefficient)
        int n = xs.size() - 1;
        while (n >= 0 && Math.abs(xs.get(n)) < 1e-12) {
            n--;
        }
        if (n < 0) {
            return 0.0; // zero polynomial
        }

        // Since input has even number of coefficients, degree n is odd (n = size-1, size is even => n is odd)
        // Odd degree polynomials always have at least one real root

        // Try to find an interval [a, b] where f(a)*f(b) < 0 (sign change)
        double a = -1000.0;
        double b = 1000.0;

        // Expand interval until we find sign change
        while (poly(xs, a) * poly(xs, b) > 0) {
            a *= 2;
            b *= 2;
            // Safety check to avoid infinite loop
            if (Math.abs(a) > 1e9) {
                break;
            }
        }

        // Now use bisection method to find root
        for (int i = 0; i < 100; i++) { // 100 iterations for precision
            double mid = (a + b) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (poly(xs, a) * fMid < 0) {
                b = mid;
            } else {
                a = mid;
            }
        }

        return (a + b) / 2;
    }
}

