class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Handle special cases - first few Fibonacci numbers
        int count = 0;
        long a = 0; // F0
        long b = 1; // F1

        // Check F0 = 0 (not prime)
        // Check F1 = 1 (not prime)

        // Start from F2 = 1
        if (n == 1) {
            return 2; // First prime Fibonacci is 2 (F3)
        }

        // We'll generate Fibonacci numbers and check for primality
        while (true) {
            long next = a + b;
            a = b;
            b = next;

            // Skip 0 and 1 as they are not prime
            if (next > 1 && isPrime(next)) {
                count++;
                if (count == n) {
                    return (int) next;
                }
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

