class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs.size() == 0) return 0.0;
        if (xs.size() == 1) return 0.0; // constant polynomial, but problem says even size

        // For linear case: a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) > 1e-12) {
                return -a / b;
            }
            return 0.0;
        }

        // Use bisection method since we know a root exists
        // First, find a range where sign changes
        double left = -1000.0;
        double right = 1000.0;

        // Try to find an interval [a,b] where f(a)*f(b) < 0
        double fa = poly(xs, left);
        double fb = poly(xs, right);

        // If we're lucky and one endpoint is already zero
        if (Math.abs(fa) < 1e-9) return left;
        if (Math.abs(fb) < 1e-9) return right;

        // Expand search range if needed to find sign change
        int attempts = 0;
        while (fa * fb > 0 && attempts < 10) {
            left *= 2;
            right *= 2;
            fa = poly(xs, left);
            fb = poly(xs, right);
            attempts++;
        }

        // If still no sign change, fall back to Newton-like method starting from 0
        if (fa * fb > 0) {
            // Try starting points around 0
            for (double start = 0; start < 10; start++) {
                if (Math.abs(poly(xs, start)) < 1e-9) return start;
                if (Math.abs(poly(xs, -start)) < 1e-9) return -start;
            }
            return 0.0;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations for precision
            double mid = (left + right) / 2.0;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < 1e-9) {
                return mid;
            }

            if (fa * fm <= 0) {
                right = mid;
                fb = fm;
            } else {
                left = mid;
                fa = fm;
            }
        }

        return (left + right) / 2.0;
    }
}

