class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // For n <= 2, there's no proper divisor smaller than n
        // But based on the example, n >= 3 (since largestDivisor(15) = 5)

        // The largest proper divisor cannot be larger than n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // This should never be reached for n > 1, as 1 always divides n
        return 1;
    }
}

