class Solution {
    public double findZero(List<Double> xs) {
        // Bisection method implementation
        double left = -1000.0;
        double right = 1000.0;
        double tolerance = 1e-10;
        int maxIterations = 1000;

        // First, try to find an interval where function changes sign
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If the signs are the same, expand the interval until we find a sign change
        int expansionCount = 0;
        while (fLeft * fRight > 0 && expansionCount < 20) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            expansionCount++;
        }

        // Now apply bisection method
        for (int i = 0; i < maxIterations; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            // Check if we've found a root (within tolerance)
            if (Math.abs(fMid) < tolerance || (right - left) / 2 < tolerance) {
                return mid;
            }

            // Bisection step: choose the subinterval where sign changes
            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint as best approximation if max iterations reached
        return (left + right) / 2;
    }
}

