class Solution {
    public List<Double> rescaleToUnit(List<Double> numbers) {
        if (numbers == null || numbers.isEmpty()) {
            return new ArrayList<>();
        }

        // Find min and max values
        double min = Double.MAX_VALUE;
        double max = Double.MIN_VALUE;

        for (Double num : numbers) {
            if (num != null) {
                min = Math.min(min, num);
                max = Math.max(max, num);
            }
        }

        // Handle case where all values are the same (avoid division by zero)
        if (Math.abs(max - min) < 1e-15) {
            // If all values are the same, map them all to 0.0 (or could be 0.5, but 0.0 is standard)
            List<Double> result = new ArrayList<>(numbers.size());
            for (int i = 0; i < numbers.size(); i++) {
                result.add(0.0);
            }
            return result;
        }

        // Apply linear transformation: (x - min) / (max - min)
        List<Double> result = new ArrayList<>(numbers.size());
        for (Double num : numbers) {
            if (num != null) {
                result.add((num - min) / (max - min));
            } else {
                result.add(null);
            }
        }

        return result;
    }
}

