class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle linear case directly: a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) > 1e-12) {
                return -a / b;
            }
        }

        // For higher degree polynomials, use Newton-Raphson method
        // Start with several initial guesses
        double[] initialGuesses = {-10.0, -1.0, 0.0, 1.0, 10.0};

        for (double guess : initialGuesses) {
            double root = newtonRaphson(xs, guess);
            if (Math.abs(poly(xs, root)) < 1e-9) {
                return root;
            }
        }

        // Fallback: try bisection method on a wider range
        // Check intervals where sign changes
        for (double left = -100; left < 100; left += 1.0) {
            double right = left + 1.0;
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            if (fLeft * fRight <= 0) {
                // Sign change detected, use bisection
                double root = bisection(xs, left, right);
                if (Math.abs(poly(xs, root)) < 1e-9) {
                    return root;
                }
            }
        }

        // Last resort: return any value that minimizes |poly(x)|
        double bestX = 0;
        double bestVal = Math.abs(poly(xs, 0));

        for (double x = -50; x <= 50; x += 0.5) {
            double val = Math.abs(poly(xs, x));
            if (val < bestVal) {
                bestVal = val;
                bestX = x;
            }
        }

        return bestX;
    }

    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative using finite difference or analytically
            double fPrime = polyDerivative(xs, x);

            if (Math.abs(fPrime) < 1e-12) {
                // Derivative too small, try perturbation
                x += 0.01;
                continue;
            }

            double xNext = x - fx / fPrime;

            // Check for divergence
            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                break;
            }

            x = xNext;
        }
        return x;
    }

    private double polyDerivative(List<Double> xs, double x) {
        // Derivative of a + bx + cx^2 + ... is b + 2cx + 3dx^2 + ...
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }

    private double bisection(List<Double> xs, double left, double right) {
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        if (fLeft * fRight > 0) {
            return left; // No sign change
        }

        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

