class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        // Handle empty input
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        // Split the input string into individual number words
        String[] words = numbers.trim().split("\\s+");

        // Create a list to hold the numeric values for sorting
        List<Integer> numericValues = new ArrayList<>();
        for (String word : words) {
            numericValues.add(wordToNumber(word));
        }

        // Sort the numeric values
        Collections.sort(numericValues);

        // Convert back to words
        List<String> resultWords = new ArrayList<>();
        for (Integer num : numericValues) {
            resultWords.add(numberToWord(num));
        }

        // Join with spaces and return
        return String.join(" ", resultWords);
    }

    // Helper method to convert word to number
    private int wordToNumber(String word) {
        switch (word) {
            case "zero": return 0;
            case "one": return 1;
            case "two": return 2;
            case "three": return 3;
            case "four": return 4;
            case "five": return 5;
            case "six": return 6;
            case "seven": return 7;
            case "eight": return 8;
            case "nine": return 9;
            default: throw new IllegalArgumentException("Invalid number word: " + word);
        }
    }

    // Helper method to convert number to word
    private String numberToWord(int num) {
        switch (num) {
            case 0: return "zero";
            case 1: return "one";
            case 2: return "two";
            case 3: return "three";
            case 4: return "four";
            case 5: return "five";
            case 6: return "six";
            case 7: return "seven";
            case 8: return "eight";
            case 9: return "nine";
            default: throw new IllegalArgumentException("Invalid number: " + num);
        }
    }
}

