class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return numbers;
        }

        // Split the input string into individual number words
        String[] numberWords = numbers.trim().split("\\s+");

        // Convert each word to its numeric value and sort
        List<Integer> numericValues = new ArrayList<>();
        for (String word : numberWords) {
            numericValues.add(WordToNumber.valueOf(word.toUpperCase()).getValue());
        }

        // Sort the numeric values
        Collections.sort(numericValues);

        // Convert back to words
        List<String> sortedWords = new ArrayList<>();
        for (Integer value : numericValues) {
            sortedWords.add(NumberToWord.valueOf(value).name().toLowerCase());
        }

        // Join with spaces
        return String.join(" ", sortedWords);
    }

    // Enum for word to number mapping
    enum WordToNumber {
        ZERO(0), ONE(1), TWO(2), THREE(3), FOUR(4), FIVE(5), 
        SIX(6), SEVEN(7), EIGHT(8), NINE(9);

        private final int value;

        WordToNumber(int value) {
            this.value = value;
        }

        public int getValue() {
            return value;
        }
    }

    // Reverse mapping for conversion back to words
    enum NumberToWord {
        0(ZERO), 1(ONE), 2(TWO), 3(THREE), 4(FOUR), 5(FIVE),
        6(SIX), 7(SEVEN), 8(EIGHT), 9(NINE);

        private final WordToNumber word;

        NumberToWord(WordToNumber word) {
            this.word = word;
        }
    }
}

