class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Ensure leading coefficient is positive for proper end behavior
        // (if the last non-zero coefficient is negative, flip signs)
        List<Double> coeffs = new ArrayList<>(xs);
        int n = coeffs.size() - 1;
        while (n >= 0 && Math.abs(coeffs.get(n)) < 1e-12) {
            n--;
        }
        if (n >= 0 && coeffs.get(n) < 0) {
            for (int i = 0; i < coeffs.size(); i++) {
                coeffs.set(i, -coeffs.get(i));
            }
        }

        // Bisection method
        double left = -1000.0;
        double right = 1000.0;

        // Expand search range until we bracket a root
        double fl = poly(coeffs, left);
        double fr = poly(coeffs, right);

        // If still same sign, expand further
        while (fl * fr > 0 && (Math.abs(left) < 1e6 || Math.abs(right) < 1e6)) {
            left *= 2;
            right *= 2;
            fl = poly(coeffs, left);
            fr = poly(coeffs, right);
        }

        // Now we have fl * fr <= 0 (or close enough)
        for (int iter = 0; iter < 100; iter++) {
            double mid = (left + right) / 2;
            double fm = poly(coeffs, mid);

            if (Math.abs(fm) < 1e-12) {
                return mid;
            }

            if (fl * fm <= 0) {
                right = mid;
                fr = fm;
            } else {
                left = mid;
                fl = fm;
            }
        }

        return (left + right) / 2;
    }
}

