class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special cases: F(0)=0, F(1)=1, F(2)=1 are not prime
        // Start from F(3) = 2

        // We'll generate Fibonacci numbers until we find the nth prime Fibonacci
        while (count < n) {
            long next = a + b;
            a = b;
            b = next;

            // Check if 'next' is prime and greater than 1
            if (next > 1 && isPrime((int)next)) {
                count++;
                if (count == n) {
                    return (int)next;
                }
            }
        }

        // Should never reach here if n is positive
        return -1;
    }

    private boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        if (num <= 3) {
            return true;
        }
        if (num % 2 == 0 || num % 3 == 0) {
            return false;
        }

        // Check for divisors up to sqrt(num)
        for (int i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

