class Solution {
    /**
    returns encoded string by cycling groups of three characters.
     */
    public String encodeCyclic(String s) {
        // split string to groups. Each of length 3.
        List<String> groups = new ArrayList<>();
        for (int i = 0; i < s.length(); i += 3) {
            groups.add(s.substring(i, Math.min(i + 3, s.length())));
        }
        // cycle elements in each group. Unless group has fewer elements than 3.
        for (int i = 0; i < groups.size(); i++) {
            if (groups.get(i).length() == 3) {
                groups.set(i, groups.get(i).substring(1) + groups.get(i).charAt(0));
            }
        }
        return String.join("", groups);
    }

    /**
    takes as input string encoded with encodeCyclic function. Returns decoded string.
     */
    public String decodeCyclic(String s) {
        // split string to groups. Each of length 3.
        List<String> groups = new ArrayList<>();
        for (int i = 0; i < s.length(); i += 3) {
            groups.add(s.substring(i, Math.min(i + 3, s.length())));
        }
        // reverse the cycling operation: for groups of length 3, move last char to front
        for (int i = 0; i < groups.size(); i++) {
            if (groups.get(i).length() == 3) {
                groups.set(i, groups.get(i).charAt(2) + groups.get(i).substring(0, 2));
            }
        }
        return String.join("", groups);
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special case for small Fibonacci numbers
        if (n == 1) {
            // Check Fibonacci numbers until we find first prime
            while (true) {
                if (isPrime(a)) {
                    return (int)a;
                }
                long temp = a + b;
                a = b;
                b = temp;
            }
        }

        // We'll iterate through Fibonacci numbers
        // Start from F(0) = 0, F(1) = 1, then generate next
        long fibNum = 0;

        // We need to check 0, 1, then generate more
        // But 0 and 1 are not prime, so skip them
        while (count < n) {
            if (fibNum > 1 && isPrime(fibNum)) {
                count++;
                if (count == n) {
                    return (int)fibNum;
                }
            }

            // Generate next Fibonacci number
            long next = a + b;
            a = b;
            b = next;
            fibNum = next;

            // Safety check for overflow - problem likely assumes reasonable n
            if (fibNum < 0) {
                throw new ArithmeticException("Overflow occurred");
            }
        }

        // This should not be reached if n >= 1
        return -1;
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        long sqrt = (long)Math.sqrt(num);
        for (long i = 3; i <= sqrt; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

