class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Edge case: empty substring - return 0 based on the first test case
        if (substring.isEmpty()) {
            return 0;
        }

        int count = 0;
        int stringLen = string.length();
        int subLen = substring.length();

        // If substring is longer than string, no match possible
        if (subLen > stringLen) {
            return 0;
        }

        // Check every possible starting position
        for (int i = 0; i <= stringLen - subLen; i++) {
            if (string.substring(i, i + subLen).equals(substring)) {
                count++;
            }
        }

        return count;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        // Handle null or empty input
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        // Split the input string into individual number words
        String[] inputWords = numbers.trim().split("\\s+");

        // Convert each word to its corresponding enum value, sort, then convert back
        List<NumberWord> numberWords = new ArrayList<>();
        for (String word : inputWords) {
            numberWords.add(NumberWord.fromString(word));
        }

        // Sort by natural order (which we define by the ordinal in the enum)
        Collections.sort(numberWords);

        // Convert back to strings and join with spaces
        List<String> resultWords = new ArrayList<>();
        for (NumberWord nw : numberWords) {
            resultWords.add(nw.toString());
        }

        return String.join(" ", resultWords);
    }

    // Enum representing the number words from zero to nine
    private enum NumberWord {
        ZERO(0),
        ONE(1),
        TWO(2),
        THREE(3),
        FOUR(4),
        FIVE(5),
        SIX(6),
        SEVEN(7),
        EIGHT(8),
        NINE(9);

        private final int value;

        NumberWord(int value) {
            this.value = value;
        }

        public int getValue() {
            return value;
        }

        // Custom comparison based on numeric value
        @Override
        public int compareTo(NumberWord other) {
            return Integer.compare(this.value, other.value);
        }

        // Factory method to convert string to enum
        public static NumberWord fromString(String word) {
            if (word == null) {
                return null;
            }
            switch (word.toLowerCase()) {
                case "zero": return ZERO;
                case "one": return ONE;
                case "two": return TWO;
                case "three": return THREE;
                case "four": return FOUR;
                case "five": return FIVE;
                case "six": return SIX;
                case "seven": return SEVEN;
                case "eight": return EIGHT;
                case "nine": return NINE;
                default: throw new IllegalArgumentException("Invalid number word: " + word);
            }
        }
    }
}

