class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // All other even numbers are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Find the highest degree coefficient (last non-zero coefficient)
        int degree = xs.size() - 1;
        int actualDegree = degree;
        for (int i = degree; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) {
                actualDegree = i;
                break;
            }
        }

        // If all coefficients are zero, any x is a solution
        if (actualDegree == 0) {
            return 0.0;
        }

        // For bisection, we need to find an interval [a, b] where f(a)*f(b) < 0
        double a = -1000.0;
        double b = 1000.0;

        // Expand search range if needed
        for (int expand = 0; expand < 20; expand++) {
            double fa = poly(xs, a);
            double fb = poly(xs, b);

            if (fa * fb <= 0) {
                // Sign change found or one is zero
                if (Math.abs(fa) < 1e-9) return a;
                if (Math.abs(fb) < 1e-9) return b;

                // Bisection method
                for (int iter = 0; iter < 100; iter++) {
                    double mid = (a + b) / 2;
                    double fm = poly(xs, mid);

                    if (Math.abs(fm) < 1e-9) {
                        return mid;
                    }

                    if (fa * fm <= 0) {
                        b = mid;
                        fb = fm;
                    } else {
                        a = mid;
                        fa = fm;
                    }
                }
                return (a + b) / 2;
            }

            // Expand the search range
            a *= 2;
            b *= 2;
        }

        // Fallback: try Newton's method with various starting points
        for (double start = -10; start <= 10; start += 0.5) {
            double x = start;
            for (int i = 0; i < 50; i++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < 1e-9) {
                    return x;
                }

                // Calculate derivative numerically
                double h = 1e-6;
                double fpx = (poly(xs, x + h) - fx) / h;

                if (Math.abs(fpx) < 1e-9) {
                    break; // Avoid division by zero
                }

                double xNext = x - fx / fpx;
                if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                    break;
                }

                x = xNext;
            }
        }

        // Last resort: return midpoint of default range
        return 0.0;
    }
}

