import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    private double polyDeriv(List<Double> xs, double x) {
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle linear case explicitly for efficiency and precision
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (b != 0) {
                return -a / b;
            }
        }

        // For higher degrees, use Newton-Raphson method
        double x = 1.0; // initial guess

        // Try multiple starting points to increase chances of finding a root
        double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

        for (double startX : startingPoints) {
            double currentX = startX;
            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, currentX);

                // Check if we found a root
                if (Math.abs(fx) < 1e-10) {
                    return currentX;
                }

                double fpx = polyDeriv(xs, currentX);

                // Avoid division by zero
                if (Math.abs(fpx) < 1e-10) {
                    break; // try next starting point
                }

                double nextX = currentX - fx / fpx;

                // Check for convergence
                if (Math.abs(nextX - currentX) < 1e-10) {
                    if (Math.abs(poly(xs, nextX)) < 1e-10) {
                        return nextX;
                    }
                    break;
                }

                currentX = nextX;
            }
        }

        // Fallback: try bisection method on interval [-100, 100]
        double left = -100.0;
        double right = 100.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Find an interval where function changes sign
        while (fLeft * fRight > 0 && (right - left) < 200) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        if (fLeft * fRight <= 0) {
            for (int iter = 0; iter < 100; iter++) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);

                if (Math.abs(fMid) < 1e-10 || (right - left) < 1e-10) {
                    return mid;
                }

                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
            return (left + right) / 2;
        }

        // Last resort: return 0.0 if nothing works (shouldn't happen per problem constraints)
        return 0.0;
    }
}

