        int count = 0;
        long a = 0;  // F(0)
        long b = 1;  // F(1)

        // Handle special cases - Fibonacci sequence starts with 0, 1, 1, 2, 3...
        // We'll check each Fibonacci number

        // Check F(0) = 0
        if (isPrime(a)) {
            count++;
            if (count == n) return (int)a;
        }

        // Check F(1) = 1
        if (isPrime(b)) {
            count++;
            if (count == n) return (int)b;
        }

        // Generate remaining Fibonacci numbers
        while (true) {
            long c = a + b;
            a = b;
            b = c;

            if (isPrime(c)) {
                count++;
                if (count == n) {
                    return (int)c;
                }
            }

            // Safety check for overflow - Fibonacci numbers grow exponentially
            if (c < 0) {
                throw new ArithmeticException("Fibonacci number overflow");
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;

        // Check odd divisors up to sqrt(num)
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

