     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return 0; // or throw exception, but based on examples, n >= 2
        }

        // Start from n/2 since no divisor can be larger than n/2 (except n itself)
        for (int i = n / 2; i >= 1; i--) {
