class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Try Newton-Raphson method
        double x = 0.0; // initial guess
        int maxIterations = 100;
        double tolerance = 1e-9;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative
            double fpx = 0.0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += xs.get(j) * j * Math.pow(x, j - 1);
            }

            // If derivative is zero, try small perturbation
            if (Math.abs(fpx) < tolerance) {
                fpx = (poly(xs, x + tolerance) - fx) / tolerance;
            }

            // Newton step
            double xNext = x - fx / fpx;

            // Check for divergence or NaN
            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                // Fallback to bisection method
                return bisect(xs, -1000.0, 1000.0);
            }

            // Check convergence
            if (Math.abs(xNext - x) < tolerance) {
                return xNext;
            }

            x = xNext;
        }

        // If Newton didn't converge, try bisection
        return bisect(xs, -1000.0, 1000.0);
    }

    // Bisection method as fallback
    private double bisect(List<Double> coeffs, double left, double right) {
        double fLeft = poly(coeffs, left);
        double fRight = poly(coeffs, right);

        // Ensure we have a sign change
        if (fLeft * fRight > 0) {
            // Try larger bounds
            for (double bound = 1000.0; bound <= 10000.0; bound *= 10) {
                fLeft = poly(coeffs, -bound);
                fRight = poly(coeffs, bound);
                if (fLeft * fRight <= 0) {
                    left = -bound;
                    right = bound;
                    break;
                }
            }
        }

        double mid;
        double fMid;
        int iterations = 100;

        for (int i = 0; i < iterations; i++) {
            mid = (left + right) / 2;
            fMid = poly(coeffs, mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            if (poly(coeffs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2;
    }
}

