class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return numbers;
        }

        // Split input string into individual number words
        String[] words = numbers.trim().split("\\s+");

        // Create list of numeric values
        List<Integer> numericValues = new ArrayList<>();
        for (String word : words) {
            numericValues.add(NumberWord.valueOf(word.toUpperCase()).getValue());
        }

        // Sort the numeric values
        Collections.sort(numericValues);

        // Convert back to words
        List<String> resultWords = new ArrayList<>();
        for (Integer value : numericValues) {
            resultWords.add(NumberWord.fromValue(value).orElseThrow().name().toLowerCase());
        }

        // Join with spaces
        return String.join(" ", resultWords);
    }

    // Enum for number words
    enum NumberWord {
        ZERO(0),
        ONE(1),
        TWO(2),
        THREE(3),
        FOUR(4),
        FIVE(5),
        SIX(6),
        SEVEN(7),
        EIGHT(8),
        NINE(9);

        private final int value;

        NumberWord(int value) {
            this.value = value;
        }

        public int getValue() {
            return value;
        }

        // Cache for reverse lookup (value -> enum)
        private static final Map<Integer, NumberWord> valueToEnum;

        static {
            valueToEnum = new HashMap<>();
            for (NumberWord word : values()) {
                valueToEnum.put(word.value, word);
            }
        }

        public static Optional<NumberWord> fromValue(int value) {
            return Optional.ofNullable(valueToEnum.get(value));
        }
    }
}

