class Solution {
    public double findZero(List<Double> xs) {
        int n = xs.size() - 1; // degree of polynomial

        // Helper function to evaluate polynomial
        java.util.function.DoubleUnaryOperator polyEval = x -> {
            double result = 0;
            double xPower = 1;
            for (int i = 0; i < xs.size(); i++) {
                result += xs.get(i) * xPower;
                xPower *= x;
            }
            return result;
        };

        // For odd degree, as x->±∞, p(x)->±∞ or ∓∞ depending on leading coefficient
        double leadingCoeff = xs.get(n);

        // Find an interval where function changes sign
        double low = -1000.0;
        double high = 1000.0;

        // Adjust bounds until we find sign change
        while (polyEval.applyAsDouble(low) * polyEval.applyAsDouble(high) > 0) {
            low *= 10;
            high *= 10;
            // Safety check to avoid infinite loop
            if (Math.abs(low) > 1e9) {
                // Fallback: try smaller range with more iterations
                low = -10.0;
                high = 10.0;
                break;
            }
        }

        // Bisection method
        double eps = 1e-9;
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~1e-30 precision
            double mid = (low + high) / 2;
            double fMid = polyEval.applyAsDouble(mid);

            if (Math.abs(fMid) < eps) {
                return mid;
            }

            if (polyEval.applyAsDouble(low) * fMid < 0) {
                high = mid;
            } else {
                low = mid;
            }
        }

        return (low + high) / 2;
    }
}

