class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Newton-Raphson method with multiple starting points
        double[] startingPoints = {0.0, 1.0, -1.0, 10.0, -10.0, 0.5, -0.5, 2.0, -2.0};

        for (double start : startingPoints) {
            double result = newtonRaphson(xs, start);
            if (result != Double.NaN && Math.abs(poly(xs, result)) < 1e-9) {
                return result;
            }
        }

        // Fallback: try bisection method on reasonable interval
        for (double left = -100; left <= 100; left += 10) {
            double right = left + 10;
            double bisectResult = bisection(xs, left, right);
            if (bisectResult != Double.NaN && Math.abs(poly(xs, bisectResult)) < 1e-9) {
                return bisectResult;
            }
        }

        // Last resort: return 0 if everything else fails
        return 0.0;
    }

    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            double fpx = derivative(xs, x);
            if (Math.abs(fpx) < 1e-12) {
                // Derivative too small, try different approach
                return Double.NaN;
            }

            double xNext = x - fx / fpx;
            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                return Double.NaN;
            }

            if (Math.abs(xNext - x) < 1e-12) {
                return xNext;
            }

            x = xNext;
        }

        // Check if we converged
        if (Math.abs(poly(xs, x)) < 1e-9) {
            return x;
        }

        return Double.NaN;
    }

    private double derivative(List<Double> xs, double x) {
        if (xs.size() <= 1) {
            return 0.0;
        }

        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }

    private double bisection(List<Double> xs, double a, double b) {
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Check if sign changes
        if (fa * fb > 0) {
            return Double.NaN;
        }

        for (int i = 0; i < 100; i++) {
            double c = (a + b) / 2;
            double fc = poly(xs, c);

            if (Math.abs(fc) < 1e-12 || (b - a) / 2 < 1e-12) {
                return c;
            }

            if (fa * fc <= 0) {
                b = c;
                fb = fc;
            } else {
                a = c;
                fa = fc;
            }
        }

        return (a + b) / 2;
    }
}

