class Solution {
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 and 3 are prime
        if (n <= 3) {
            return true;
        }

        // Eliminate multiples of 2 and 3
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check for factors up to sqrt(n)
        // All primes > 3 are of the form 6k ± 1
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

