class Solution {
    public double findZero(List<Double> xs) {
        // For Newton-Raphson, we need the derivative
        List<Double> derivative = new ArrayList<>();
        for (int i = 1; i < xs.size(); i++) {
            derivative.add(xs.get(i) * i);
        }

        // Handle constant polynomial (shouldn't happen per constraints, but safety)
        if (derivative.isEmpty()) {
            throw new IllegalArgumentException("Constant polynomial has no zero");
        }

        // Newton-Raphson with initial guess
        double x = 0.0;
        double epsilon = 1e-10;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative at x
            double fpx = poly(derivative, x);

            // Avoid division by zero
            if (Math.abs(fpx) < epsilon) {
                // Try small perturbation
                x += 0.1;
                continue;
            }

            // Newton step
            double xNext = x - fx / fpx;

            // Check convergence
            if (Math.abs(xNext - x) < epsilon) {
                return xNext;
            }

            x = xNext;
        }

        // Fallback - return last approximation
        return x;
    }
}

