class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        // Split the input string by spaces
        String[] words = numbers.split(" ");

        // Convert each word to its numeric value and store pairs
        List<NumWord> numWords = new ArrayList<>();
        for (String word : words) {
            try {
                NumWord nw = NumWord.fromWord(word);
                numWords.add(nw);
            } catch (IllegalArgumentException e) {
                // Skip invalid words or handle as needed
                continue;
            }
        }

        // Sort by numeric value
        Collections.sort(numWords);

        // Convert back to words and join
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < numWords.size(); i++) {
            if (i > 0) {
                result.append(" ");
            }
            result.append(numWords.get(i).word);
        }

        return result.toString();
    }

    // Enum for number words - provides type safety and constant-specific behavior
    enum NumWord implements Comparable<NumWord> {
        ZERO("zero", 0),
        ONE("one", 1),
        TWO("two", 2),
        THREE("three", 3),
        FOUR("four", 4),
        FIVE("five", 5),
        SIX("six", 6),
        SEVEN("seven", 7),
        EIGHT("eight", 8),
        NINE("nine", 9);

        private final String word;
        private final int value;

        NumWord(String word, int value) {
            this.word = word;
            this.value = value;
        }

        public String getWord() {
            return word;
        }

        public int getValue() {
            return value;
        }

        @Override
        public int compareTo(NumWord other) {
            return Integer.compare(this.value, other.value);
        }

        public static NumWord fromWord(String word) {
            for (NumWord nw : NumWord.values()) {
                if (nw.word.equals(word)) {
                    return nw;
                }
            }
            throw new IllegalArgumentException("Invalid number word: " + word);
        }
    }
}

