            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs.size() == 2) {
            // Linear case: a + bx = 0 => x = -a/b
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) > 1e-10) {
                return -a / b;
            }
        }

        // For higher degree polynomials, use Newton-Raphson method
        double x = 0.0; // Initial guess

        // Try different initial guesses if needed
        for (int attempt = 0; attempt < 5; attempt++) {
            if (attempt == 1) x = 1.0;
            else if (attempt == 2) x = -1.0;
            else if (attempt == 3) x = 2.0;
            else if (attempt == 4) x = -2.0;

            double currentX = x;
            for (int i = 0; i < 100; i++) { // Max iterations
                double fx = poly(xs, currentX);

                // Check if close enough to zero
                if (Math.abs(fx) < 1e-9) {
                    return currentX;
                }

                // Compute derivative numerically
                double h = 1e-8;
                double fxh = poly(xs, currentX + h);
                double derivative = (fxh - fx) / h;

                // Avoid division by zero
                if (Math.abs(derivative) < 1e-10) {
                    break;
                }

                double nextX = currentX - fx / derivative;

                // Check convergence
                if (Math.abs(nextX - currentX) < 1e-9) {
                    if (Math.abs(poly(xs, nextX)) < 1e-9) {
                        return nextX;
                    }
                    break;
                }

                currentX = nextX;
            }
        }

        // Fallback: try bisection method on a reasonable interval
        double left = -100.0;
        double right = 100.0;
        double mid;

        for (int i = 0; i < 100; i++) {
            mid = (left + right) / 2.0;
            double fmid = poly(xs, mid);

            if (Math.abs(fmid) < 1e-9) {
                return mid;
            }

            double fleft = poly(xs, left);
            if (fleft * fmid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2.0;
    }
}

