class Solution {
    public String stringXor(String a, String b) {
        // Make both strings the same length by padding with leading zeros
        int maxLen = Math.max(a.length(), b.length());
        StringBuilder aBuilder = new StringBuilder(a);
        StringBuilder bBuilder = new StringBuilder(b);

        while (aBuilder.length() < maxLen) {
            aBuilder.insert(0, '0');
        }
        while (bBuilder.length() < maxLen) {
            bBuilder.insert(0, '0');
        }

        StringBuilder result = new StringBuilder();
        for (int i = 0; i < maxLen; i++) {
            char bitA = aBuilder.charAt(i);
            char bitB = bBuilder.charAt(i);

            // XOR: if bits are different, result is '1', otherwise '0'
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

