class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        // Handle empty or null input
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        // Split the input string into individual number words
        String[] parts = numbers.trim().split("\\s+");

        // Convert each word to its numeric value using the NumberWord enum
        List<NumberWord> numberWords = new ArrayList<>();
        for (String part : parts) {
            numberWords.add(NumberWord.fromString(part));
        }

        // Sort by the numeric value (instance field, not ordinal)
        Collections.sort(numberWords);

        // Convert back to strings and join with spaces
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < numberWords.size(); i++) {
            if (i > 0) {
                result.append(" ");
            }
            result.append(numberWords.get(i).word);
        }

        return result.toString();
    }

    // Enum for number words with instance field for numeric value
    private enum NumberWord {
        ZERO(0, "zero"),
        ONE(1, "one"),
        TWO(2, "two"),
        THREE(3, "three"),
        FOUR(4, "four"),
        FIVE(5, "five"),
        SIX(6, "six"),
        SEVEN(7, "seven"),
        EIGHT(8, "eight"),
        NINE(9, "nine");

        private final int value;
        private final String word;

        NumberWord(int value, String word) {
            this.value = value;
            this.word = word;
        }

        public int getValue() {
            return value;
        }

        // Get enum from string representation
        public static NumberWord fromString(String word) {
            for (NumberWord nw : NumberWord.values()) {
                if (nw.word.equals(word)) {
                    return nw;
                }
            }
            throw new IllegalArgumentException("Invalid number word: " + word);
        }

        @Override
        public String toString() {
            return word;
        }
    }
}

