class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Convert to array for faster access
        double[] coeffs = new double[xs.size()];
        for (int i = 0; i < xs.size(); i++) {
            coeffs[i] = xs.get(i);
        }

        // Helper function to evaluate polynomial
        java.util.function.DoubleUnaryOperator f = (double x) -> {
            double result = 0;
            double xPower = 1;
            for (int i = 0; i < coeffs.length; i++) {
                result += coeffs[i] * xPower;
                xPower *= x;
            }
            return result;
        };

        // Find an interval [a, b] where f(a) * f(b) < 0 (sign change)
        // Since it's an odd degree polynomial (even # of coeffs), 
        // it goes to +/- infinity as x -> +/- infinity

        double a = -1000.0;
        double b = 1000.0;

        double fa = f.applyAsDouble(a);
        double fb = f.applyAsDouble(b);

        // Expand interval if needed to ensure sign change
        int attempts = 0;
        while (fa * fb > 0 && attempts < 30) {
            a *= 10;
            b *= 10;
            fa = f.applyAsDouble(a);
            fb = f.applyAsDouble(b);
            attempts++;
        }

        // Bisection method
        double epsilon = 1e-9;
        while (b - a > epsilon) {
            double mid = (a + b) / 2.0;
            double fmid = f.applyAsDouble(mid);

            if (Math.abs(fmid) < epsilon) {
                return mid;
            }

            if (fa * fmid <= 0) {
                b = mid;
                fb = fmid;
            } else {
                a = mid;
                fa = fmid;
            }
        }

        return (a + b) / 2.0;
    }
}

