enum NumberWord {
    ZERO(0), ONE(1), TWO(2), THREE(3), FOUR(4), 
    FIVE(5), SIX(6), SEVEN(7), EIGHT(8), NINE(9);

    private final int value;

    NumberWord(int value) {
        this.value = value;
    }

    public int getValue() {
        return value;
    }
}

class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return numbers;
        }

        String[] words = numbers.trim().split("\\s+");

        // Sort by the numeric value of each word
        Arrays.sort(words, (a, b) -> {
            NumberWord wa = NumberWord.valueOf(a.toUpperCase());
            NumberWord wb = NumberWord.valueOf(b.toUpperCase());
            return Integer.compare(wa.getValue(), wb.getValue());
        });

        return String.join(" ", words);
    }
}

