class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method
        double x = 1.0; // initial guess

        for (int i = 0; i < 100; i++) { // max iterations
            double fx = poly(xs, x);
            // Check if close enough to zero
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative
            double fpx = 0.0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-15) {
                // Try a small perturbation
                x += 0.1;
                continue;
            }

            double xNew = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNew - x) < 1e-10) {
                return xNew;
            }

            x = xNew;
        }

        // Return best approximation if didn't converge
        return x;
    }
}

