                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // For invalid notes, we could skip or throw exception
                    // Based on the problem, we assume only valid notes are present
                    break;
            }
        }

        return result;
    }
}

