class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Handle edge cases
        if (substring == null || substring.isEmpty() || string == null) {
            return 0;
        }

        int count = 0;
        int index = 0;

        while (index <= string.length() - substring.length()) {
            // Find next occurrence starting from current index
            index = string.indexOf(substring, index);

            if (index == -1) {
                break;
            }

            count++;
            index++; // Move forward by 1 to allow overlapping matches
        }

        return count;
    }
}

