    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method
        double x = 0.0; // initial guess
        double epsilon = 1e-9;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative: f'(x)
            double fpx = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fpx += i * xs.get(i) * Math.pow(x, i - 1);
            }

            // Avoid division by zero
            if (Math.abs(fpx) < epsilon) {
                // If derivative is zero, try a small perturbation
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < epsilon) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNext)) < epsilon) {
                    return xNext;
                }
            }

            x = xNext;
        }

        // Fallback: return current x if didn't converge
        return x;
    }
}

