            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For linear case (2 coefficients), direct solution
        if (xs.size() == 2) {
            // a + bx = 0 => x = -a/b
            double a = xs.get(0);
            double b = xs.get(1);
            return -a / b;
        }

        // Newton-Raphson method for higher degree polynomials
        double x = 1.0; // initial guess

        // Maximum iterations to prevent infinite loop
        for (int i = 0; i < 1000; i++) {
            double fx = poly(xs, x);

            // If we're close enough to zero, return
            if (Math.abs(fx) < 1e-9) {
                return x;
            }

            // Compute derivative at x
            double fpx = 0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-9) {
                // If derivative is near zero, try a small perturbation
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < 1e-9) {
                return xNext;
            }

            x = xNext;
        }

        // Fallback: if we didn't converge, return the last approximation
        return x;
    }
}

