class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: empty list or all zeros
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Find the highest degree with non-zero coefficient
        int degree = -1;
        for (int i = xs.size() - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) {
                degree = i;
                break;
            }
        }

        // If all coefficients are zero, any x is a solution
        if (degree == -1) {
            return 0.0;
        }

        // For linear case: ax + b = 0 => x = -b/a
        if (degree == 1) {
            double a = xs.get(1);
            double b = xs.get(0);
            if (Math.abs(a) > 1e-12) {
                return -b / a;
            }
            return 0.0;
        }

        // For higher degree polynomials, use Newton-Raphson method
        double x = 1.0; // initial guess

        // Try multiple starting points if needed
        for (int startIdx = 0; startIdx < 5; startIdx++) {
            double startX = startIdx == 0 ? 1.0 : 
                           startIdx == 1 ? -1.0 :
                           startIdx == 2 ? 0.0 :
                           startIdx == 3 ? 2.0 : -2.0;

            x = startX;
            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, x);

                // Check if we're close enough to a root
                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                // Compute derivative
                double fpx = 0.0;
                for (int i = 1; i < xs.size(); i++) {
                    fpx += i * xs.get(i) * Math.pow(x, i - 1);
                }

                // Avoid division by zero
                if (Math.abs(fpx) < 1e-12) {
                    // Try a different starting point or perturb
                    x += 0.1;
                    continue;
                }

                double xNew = x - fx / fpx;

                // Check for convergence
                if (Math.abs(xNew - x) < 1e-10) {
                    // Verify it's actually a root
                    if (Math.abs(poly(xs, xNew)) < 1e-8) {
                        return xNew;
                    }
                }

                x = xNew;

                // Handle overflow/NaN
                if (Double.isNaN(x) || Double.isInfinite(x)) {
                    break;
                }
            }
        }

        // Fallback: try bisection method on a reasonable interval
        // Since leading coefficient is non-zero and degree is odd (even #coeffs means odd degree),
        // there must be a root somewhere
        double left = -100.0;
        double right = 100.0;

        // Find interval where sign changes
        while (left < right) {
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            if (fLeft * fRight <= 0) {
                // Bisection method
                for (int i = 0; i < 100; i++) {
                    double mid = (left + right) / 2;
                    double fMid = poly(xs, mid);

                    if (Math.abs(fMid) < 1e-10 || (right - left) < 1e-10) {
                        return mid;
                    }

                    if (fLeft * fMid <= 0) {
                        right = mid;
                    } else {
                        left = mid;
                        fLeft = fMid;
                    }
                }
                return (left + right) / 2;
            }

            left *= 2;
            right *= 2;

            // Prevent infinite loop
            if (Math.abs(left) > 1e10) {
                break;
            }
        }

        // Last resort: return midpoint of search range
        return 0.0;
    }
}

