                case "o|":
                    beats.add(2);
                    break;
                case ".|":
                    beats.add(1);
                    break;
                default:
                    // Optional: handle invalid notes, but per problem statement
                    // we assume valid input according to the legend
                    break;
            }
        }

        return beats;
    }
}

