class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return numbers;
        }

        // Define enum for number words
        enum NumberWord { zero, one, two, three, four, five, six, seven, eight, nine }

        // Create mapping from number word to its numeric value using EnumMap
        Map<NumberWord, Integer> wordToValue = new EnumMap<>(NumberWord.class);
        for (NumberWord word : NumberWord.values()) {
            wordToValue.put(word, word.ordinal());
        }

        // Split input string into words
        String[] words = numbers.trim().split("\\s+");

        // Sort words based on their numeric values
        Arrays.sort(words, (a, b) -> {
            NumberWord wordA = NumberWord.valueOf(a);
            NumberWord wordB = NumberWord.valueOf(b);
            return wordToValue.get(wordA) - wordToValue.get(wordB);
        });

        // Join the sorted words back into a string
        return String.join(" ", words);
    }
}

