class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Newton-Raphson method
        double x = 0.0; // initial guess
        double tolerance = 1e-9;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative numerically or analytically
            // Let's use analytical derivative for accuracy
            double fprime = 0.0;
            for (int j = 1; j < xs.size(); j++) {
                fprime += j * xs.get(j) * Math.pow(x, j - 1);
            }

            // Avoid division by zero
            if (Math.abs(fprime) < 1e-15) {
                // Slight perturbation if derivative is near zero
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fprime;

            // Check for convergence
            if (Math.abs(xNext - x) < tolerance) {
                return xNext;
            }

            x = xNext;
        }

        // Fallback: return last estimate
        return x;
    }
}

