class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        StringBuilder result = new StringBuilder();

        // Determine the maximum length to process
        int len = Math.max(a.length(), b.length());

        // Process each bit position from right to left (LSB to MSB)
        for (int i = 0; i < len; i++) {
            // Get the bit from each string (from the right side)
            int bitA = (i < a.length()) ? (a.charAt(a.length() - 1 - i) - '0') : 0;
            int bitB = (i < b.length()) ? (b.charAt(b.length() - 1 - i) - '0') : 0;

            // XOR operation
            int xorResult = bitA ^ bitB;

            // Prepend the result (since we're processing from LSB to MSB)
            result.insert(0, xorResult);
        }

        // Handle edge case where result might be empty (both inputs were empty)
        if (result.length() == 0) {
            return "0";
        }

        return result.toString();
    }
}

