class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true;
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check for divisors from 5 up to √n, skipping even numbers
        // Use the pattern: check i and i+2, then increment by 6
        // This checks numbers of form 6k±1
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Remove trailing zeros to get actual degree
        int n = xs.size();
        int lastNonZero = n - 1;
        while (lastNonZero >= 0 && xs.get(lastNonZero) == 0.0) {
            lastNonZero--;
        }

        // If all coefficients are zero, any x is a solution
        if (lastNonZero < 0) {
            return 0.0;
        }

        // Get actual degree
        int degree = lastNonZero;

        // For linear case (degree 1)
        if (degree == 1) {
            double a0 = xs.get(0);
            double a1 = xs.get(1);
            return -a0 / a1;
        }

        // For higher odd degrees, use Newton-Raphson method
        // Start with initial guess based on leading coefficient
        double leadingCoeff = xs.get(lastNonZero);
        double initialGuess = 1.0;
        if (leadingCoeff != 0) {
            // Rough estimate: |x| ≈ |a0/a_n|^(1/n) or simple heuristic
            initialGuess = Math.signum(-xs.get(0) / leadingCoeff) * 
                          (Math.abs(xs.get(0) / leadingCoeff) > 0 ? 
                           Math.pow(Math.abs(xs.get(0) / leadingCoeff), 1.0/degree) : 1.0);
        }

        // Newton-Raphson with multiple starting points to ensure finding a root
        double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

        for (double x0 : startingPoints) {
            double x = x0;
            for (int iteration = 0; iteration < 100; iteration++) {
                double fx = polyValue(xs, x);
                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                double fpx = derivativeValue(xs, x);
                if (Math.abs(fpx) < 1e-15) {
                    // Derivative too small, try perturbation
                    x += 0.1 * (iteration % 2 == 0 ? 1 : -1);
                    continue;
                }

                double xNew = x - fx / fpx;

                // Check if we've converged or escaped to infinity
                if (Double.isNaN(xNew) || Double.isInfinite(xNew)) {
                    break;
                }

                if (Math.abs(xNew - x) < 1e-12) {
                    if (Math.abs(polyValue(xs, xNew)) < 1e-10) {
                        return xNew;
                    }
                    break;
                }

                x = xNew;
            }
        }

        // Fallback: if Newton-Raphson fails, try bisection on a reasonable interval
        double left = -100.0, right = 100.0;
        double fLeft = polyValue(xs, left);
        double fRight = polyValue(xs, right);

        // Try to find an interval where sign changes
        while (fLeft * fRight > 0 && (right - left) < 1e6) {
            left *= 2;
            right *= 2;
            fLeft = polyValue(xs, left);
            fRight = polyValue(xs, right);
        }

        if (fLeft * fRight <= 0) {
            // Bisection method
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = polyValue(xs, mid);
                if (Math.abs(fMid) < 1e-10 || (right - left) < 1e-10) {
                    return mid;
                }
                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
            return (left + right) / 2;
        }

        // Last resort: return 0
        return 0.0;
    }

    // Helper method to evaluate polynomial
    private double polyValue(List<Double> xs, double x) {
        double result = 0;
        double xPower = 1;
        for (double coeff : xs) {
            result += coeff * xPower;
            xPower *= x;
        }
        return result;
    }

    // Helper method to evaluate derivative of polynomial
    private double derivativeValue(List<Double> xs, double x) {
        double result = 0;
        double xPower = 1;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * xPower;
            xPower *= x;
        }
        return result;
    }
}

