import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method to find a root
        double x = 0.0; // Initial guess

        // Try multiple starting points to increase chances of convergence
        double[] guesses = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

        for (double initialGuess : guesses) {
            double xCurrent = initialGuess;
            for (int iteration = 0; iteration < 100; iteration++) {
                double fx = poly(xs, xCurrent);

                // If we're close enough to zero, return
                if (Math.abs(fx) < 1e-10) {
                    return xCurrent;
                }

                // Calculate derivative numerically
                double h = 1e-8;
                double fPrime = (poly(xs, xCurrent + h) - poly(xs, xCurrent - h)) / (2 * h);

                // Avoid division by zero or very small derivative
                if (Math.abs(fPrime) < 1e-10) {
                    break;
                }

                double xNext = xCurrent - fx / fPrime;

                // Check if converged
                if (Math.abs(xNext - xCurrent) < 1e-10) {
                    if (Math.abs(poly(xs, xNext)) < 1e-8) {
                        return xNext;
                    }
                    break;
                }

                xCurrent = xNext;
            }
        }

        // Fallback: use bisection method on a wide range
        // Find interval where sign changes
        for (double left = -1000, right = 1000; left <= 1000; left += 10) {
            double fLeft = poly(xs, left);
            double fRight = poly(xs, left + 10);

            if (fLeft * fRight <= 0) {
                // Bisection in [left, left+10]
                double a = left;
                double b = left + 10;
                for (int i = 0; i < 100; i++) {
                    double mid = (a + b) / 2;
                    double fMid = poly(xs, mid);

                    if (Math.abs(fMid) < 1e-10) {
                        return mid;
                    }

                    if (poly(xs, a) * fMid < 0) {
                        b = mid;
                    } else {
                        a = mid;
                    }
                }
                // Return midpoint of last interval if found
                return (a + b) / 2;
            }
        }

        // Last resort: return 0.0 if all else fails (shouldn't happen per problem statement)
        return 0.0;
    }
}

