class Solution {
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Remove trailing zeros to get actual degree
        List<Double> coeffs = new ArrayList<>(xs);
        while (coeffs.size() > 1 && coeffs.get(coeffs.size() - 1) == 0.0) {
            coeffs.remove(coeffs.size() - 1);
        }

        // If constant polynomial, no solution guaranteed unless it's zero
        if (coeffs.size() <= 1) {
            return 0.0;
        }

        // For linear case: a + bx = 0 => x = -a/b
        if (coeffs.size() == 2) {
            double a = coeffs.get(0);
            double b = coeffs.get(1);
            if (b != 0) {
                return -a / b;
            }
            return 0.0;
        }

        // Newton-Raphson with multiple starting points
        double[] starts = {0.0, 1.0, -1.0, 10.0, -10.0, 0.5, -0.5};

        for (double start : starts) {
            double root = newtonRaphson(coeffs, start);
            if (Math.abs(poly(coeffs, root)) < 1e-9) {
                return root;
            }
        }

        // Fallback: try bisection on a wide range
        for (double left = -100; left <= 100; left += 10) {
            double right = left + 10;
            double fLeft = poly(coeffs, left);
            double fRight = poly(coeffs, right);

            if (fLeft * fRight <= 0) {
                // Bisection
                for (int i = 0; i < 100; i++) {
                    double mid = (left + right) / 2;
                    double fMid = poly(coeffs, mid);
                    if (Math.abs(fMid) < 1e-9) {
                        return mid;
                    }
                    if (fLeft * fMid <= 0) {
                        right = mid;
                    } else {
                        left = mid;
                        fLeft = fMid;
                    }
                }
                return (left + right) / 2;
            }
        }

        return 0.0;
    }

    private double newtonRaphson(List<Double> coeffs, double x0) {
        double x = x0;
        for (int i = 0; i < 100; i++) {
            double fx = poly(coeffs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative
            double fpx = 0;
            for (int j = 1; j < coeffs.size(); j++) {
                fpx += j * coeffs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(fpx) < 1e-12) {
                return x; // Can't continue, return current
            }

            double xNext = x - fx / fpx;
            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                return x;
            }
            x = xNext;
        }
        return x;
    }
}

