class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        int n = xs.size();

        // Handle linear case: c0 + c1*x = 0 => x = -c0/c1
        if (n == 2) {
            double c0 = xs.get(0);
            double c1 = xs.get(1);
            if (Math.abs(c1) < 1e-12) {
                throw new IllegalArgumentException("Linear coefficient is zero");
            }
            return -c0 / c1;
        }

        // Newton-Raphson method for higher degree polynomials
        double x = 0.0; // start at 0

        // Precompute derivative coefficients: [c1, 2*c2, 3*c3, ...]
        List<Double> derivCoeffs = new ArrayList<>();
        for (int i = 1; i < n; i++) {
            derivCoeffs.add(xs.get(i) * i);
        }

        // Newton-Raphson iterations
        for (int iter = 0; iter < 100; iter++) {
            double fx = poly(xs, x);
            double fpx = poly(derivCoeffs, x);

            // If derivative is too small, avoid division by zero
            if (Math.abs(fpx) < 1e-12) {
                // Try a small perturbation or switch to bisection logic
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check convergence
            if (Math.abs(xNext - x) < 1e-10) {
                break;
            }

            x = xNext;

            // Safety: clamp x to avoid overflow
            if (Double.isInfinite(x) || Double.isNaN(x)) {
                x = 0.0;
            }
        }

        return x;
    }
}

