class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: empty list
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Find the highest degree coefficient (last non-zero)
        int n = xs.size() - 1;
        while (n >= 0 && Math.abs(xs.get(n)) < 1e-15) {
            n--;
        }
        if (n < 0) {
            return 0.0; // zero polynomial
        }

        // Use bisection method
        // For odd-degree polynomials, we know there's at least one real root
        double left = -1000.0;
        double right = 1000.0;

        // Ensure we have opposite signs at endpoints
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If both same sign, expand search range
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 20) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

