            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Use bisection method to find a root
        // Since we have odd degree (even number of coefficients), there's guaranteed to be at least one real root

        double left = -1000.0;
        double right = 1000.0;

        // Expand search range until we find opposite signs
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 10;
            right *= 10;
            // Safety limit to prevent infinite loop
            if (Math.abs(left) > 1e10) {
                // Fallback: try Newton-Raphson from 0
                return newtonRaphson(xs, 0.0);
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives precision ~1e-30
            double mid = (left + right) / 2.0;
            double value = poly(xs, mid);

            if (Math.abs(value) < 1e-12) {
                return mid;
            }

            if (poly(xs, left) * value < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2.0;
    }

    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }
            // Compute derivative numerically
            double derivative = (poly(xs, x + 1e-8) - fx) / 1e-8;
            if (Math.abs(derivative) < 1e-12) {
                // Derivative too small, try perturbation
                x += 0.1;
                continue;
            }
            x = x - fx / derivative;
            if (Double.isNaN(x) || Double.isInfinite(x)) {
                // Failed, return something reasonable
                return 0.0;
            }
        }
        return x;
    }
}

