class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special case for first few Fibonacci numbers
        // We'll generate Fibonacci numbers starting from F(3) = 2

        // Check F(3) = 2
        if (isPrime(2)) {
            count++;
            if (count == n) return 2;
        }

        // Check F(4) = 3
        if (isPrime(3)) {
            count++;
            if (count == n) return 3;
        }

        // Start generating from F(5) = 5 onwards
        long fib = 5; // F(5)
        long prev1 = 3; // F(4)
        long prev2 = 2; // F(3)

        while (true) {
            if (isPrime(fib)) {
                count++;
                if (count == n) {
                    return (int) fib;
                }
            }

            // Generate next Fibonacci number
            long next = prev1 + prev2;
            prev2 = prev1;
            prev1 = fib;
            fib = next;
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;

        // Check for divisors up to sqrt(num)
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

