     */
    public List<Double> findClosestElements(List<Double> numbers) {
        // Create a copy and sort it
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        double minDiff = Double.MAX_VALUE;
        int minIndex = 0;

        // Check adjacent pairs
        for (int i = 0; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < minDiff) {
                minDiff = diff;
                minIndex = i;
            }
        }

        // Return the pair in ascending order (already sorted, so just take adjacent pair)
        return Arrays.asList(sorted.get(minIndex), sorted.get(minIndex + 1));
    }
}

