class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Get degree (highest power) - coefficients are in order [a0, a1, ..., an]
        int n = xs.size() - 1;

        // Find the actual degree by skipping trailing zeros
        int actualDegree = n;
        while (actualDegree > 0 && Math.abs(xs.get(actualDegree)) < 1e-12) {
            actualDegree--;
        }

        // Since we have even number of coefficients, actualDegree should be odd
        // For odd degree polynomials, lim(x->+inf) = sign(lc) * inf, lim(x->-inf) = -sign(lc) * inf
        // So there must be at least one real root

        // Use bisection method with interval expansion
        double left = -1000.0;
        double right = 1000.0;

        // Expand interval until we bracket a root
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If we already have opposite signs, proceed to bisection
        // Otherwise expand interval
        int expansionCount = 0;
        while (fLeft * fRight > 0 && expansionCount < 30) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            expansionCount++;
        }

        // Now apply bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations for precision
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint as best approximation
        return (left + right) / 2;
    }
}

