class Solution {
    /**
    Input to this function is a string representing musical notes in a special ASCII format.
    Your task is to parse this string and return list of integers corresponding to how many beats does each
    not last.

    Here is a legend:
    "o" - whole note, lasts four beats
    "o|" - half note, lasts two beats
    ".|" - quater note, lasts one beat

    >>> parseMusic("o o| .| o| o| .| .| .| .| o o")
    [4, 2, 1, 2, 2, 1, 1, 1, 1, 4, 4]
     */
    public List<Integer> parseMusic(String string) {
        List<Integer> result = new ArrayList<>();
        int i = 0;

        while (i < string.length()) {
            // Skip whitespace
            if (Character.isWhitespace(string.charAt(i))) {
                i++;
                continue;
            }

            // Check for 2-character notes first
            if (i + 1 < string.length()) {
                String twoChar = string.substring(i, i + 2);
                if (twoChar.equals("o|")) {
                    result.add(2); // half note
                    i += 2;
                    continue;
                } else if (twoChar.equals(".|")) {
                    result.add(1); // quarter note
                    i += 2;
                    continue;
                }
            }

            // Check for single character note
            if (string.charAt(i) == 'o') {
                result.add(4); // whole note
                i++;
            } else {
                // Shouldn't happen with valid input, but skip unknown char
                i++;
            }
        }

        return result;
    }
}

