class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Handle edge cases
        if (substring == null || substring.isEmpty() || string == null) {
            return 0;
        }

        int count = 0;
        int fromIndex = 0;

        while (true) {
            // Find the substring starting from current index
            int index = string.indexOf(substring, fromIndex);

            if (index == -1) {
                break; // No more occurrences found
            }

            count++;
            // Move forward by 1 to allow for overlapping matches
            fromIndex = index + 1;
        }

        return count;
    }
}

