class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle linear case directly
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (b == 0) {
                return 0; // or throw exception, but problem guarantees solution
            }
            return -a / b;
        }

        // For higher degree polynomials, use numerical method
        // Since we have odd degree (even number of coefficients), there's guaranteed to be a real root

        // Try Newton-Raphson with multiple starting points
        for (double startX = -100.0; startX <= 100.0; startX += 10.0) {
            double root = newtonRaphson(xs, startX);
            if (!Double.isNaN(root) && Math.abs(poly(xs, root)) < 1e-9) {
                return root;
            }
        }

        // Fallback to bisection method on a large interval
        double left = -1000.0;
        double right = 1000.0;

        // Find bracketing interval
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If signs are different, we can use bisection
        if (fLeft * fRight < 0) {
            return bisection(xs, left, right);
        }

        // Try expanding interval
        for (int i = 0; i < 20; i++) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            if (fLeft * fRight < 0) {
                return bisection(xs, left, right);
            }
        }

        // Last resort: return midpoint of large interval
        return 0.0;
    }

    private double newtonRaphson(List<Double> xs, double startX) {
        double x = startX;
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative
            double fpx = polyDerivative(xs, x);
            if (Math.abs(fpx) < 1e-12) {
                return Double.NaN; // Derivative too small
            }

            double xNext = x - fx / fpx;
            if (Double.isInfinite(xNext) || Double.isNaN(xNext)) {
                return Double.NaN;
            }

            if (Math.abs(xNext - x) < 1e-12) {
                return xNext;
            }

            x = xNext;
        }

        // Check if we found a root
        if (Math.abs(poly(xs, x)) < 1e-9) {
            return x;
        }
        return Double.NaN;
    }

    private double polyDerivative(List<Double> xs, double x) {
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += xs.get(i) * i * Math.pow(x, i - 1);
        }
        return result;
    }

    private double bisection(List<Double> xs, double a, double b) {
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        if (fa * fb > 0) {
            return Double.NaN; // No bracket
        }

        for (int i = 0; i < 100; i++) {
            double mid = (a + b) / 2;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < 1e-12 || (b - a) < 1e-12) {
                return mid;
            }

            if (fa * fm < 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2;
    }
}

