class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Edge case: empty substring - return 0 as per convention
        if (substring.isEmpty()) {
            return 0;
        }

        // Edge case: empty string (but non-empty substring)
        if (string.isEmpty()) {
            return 0;
        }

        int count = 0;
        // We only need to check up to string.length() - substring.length()
        // But to include positions where substring might still fit, we go to string.length() - substring.length() + 1
        for (int i = 0; i <= string.length() - substring.length(); i++) {
            // Check if substring matches starting at position i
            if (string.substring(i, i + substring.length()).equals(substring)) {
                count++;
            }
        }

        return count;
    }
}

