        String[] words = numbers.trim().split("\\s+");

        // Sort by numeric value using our mapping
        Arrays.sort(words, (a, b) -> {
            Integer numA = wordToDigit.getOrDefault(a, -1);
            Integer numB = wordToDigit.getOrDefault(b, -1);
            return numA.compareTo(numB);
        });

        // Join back into a string
        return String.join(" ", words);
    }
}

