class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For linear case (degree 1), we can compute directly
        if (xs.size() == 2) {
            double a0 = xs.get(0);
            double a1 = xs.get(1);
            if (Math.abs(a1) > 1e-15) {
                return -a0 / a1;
            }
        }

        // Bisection method for higher odd-degree polynomials
        double left = -1000.0;
        double right = 1000.0;

        // Expand search range until we find a sign change
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 2;
            right *= 2;
            // Safety check to avoid infinite loops
            if (Math.abs(left) > 1e9) {
                // Fallback: try Newton-Raphson starting from 0
                return newtonRaphson(xs, 0.0);
            }
        }

        // Bisection method
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance) {
                return mid;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Return midpoint if we didn't converge exactly
        return (left + right) / 2.0;
    }

    // Helper method for Newton-Raphson fallback
    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        double tolerance = 1e-10;
        int maxIterations = 100;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative
            double dfx = 0;
            for (int j = 1; j < xs.size(); j++) {
                dfx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(dfx) < 1e-15) {
                // Derivative too small, try perturbation
                x += 0.1;
                continue;
            }

            double xNext = x - fx / dfx;

            // Check if we're diverging
            if (Double.isNaN(xNext) || Double.isInfinite(xNext) || Math.abs(xNext - x) > 1e6) {
                return x; // give up and return current value
            }

            x = xNext;
        }

        return x;
    }
}

