class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return -1; // or throw IllegalArgumentException
        }

        // For n = 2, the only proper divisor is 1
        if (n == 2) {
            return 1;
        }

        // Check if n is even
        if (n % 2 == 0) {
            return n / 2;
        }

        // For odd numbers, find the smallest divisor starting from 3
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                // Found the smallest divisor, so n/i is the largest proper divisor
                return n / i;
            }
        }

        // If we reach here, n is prime, so largest proper divisor is 1
        return 1;
    }
}

