        // Find the longest palindromic suffix
        for (int i = 0; i < string.length(); i++) {
            if (isPalindrome(string.substring(i))) {
                // Found the longest palindromic suffix starting at index i
                // Append the reverse of the prefix (string.substring(0, i))
                return string + new StringBuilder(string.substring(0, i)).reverse().toString();
            }
        }

        // This should never happen for non-null strings since at minimum the last character is a palindrome
        return string;
    }
}

