class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check for odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For linear case: xs = [a, b] => a + b*x = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) < 1e-15) {
                // Handle degenerate case, though problem states even # coefficients and largest non-zero guarantees solution
                return 0.0;
            }
            return -a / b;
        }

        // Bisection method for higher degree polynomials
        // Since even number of coefficients means odd degree, there's guaranteed to be at least one real root

        // Define the polynomial function
        java.util.function.DoubleUnaryOperator f = x -> poly(xs, x);

        // Try to find an interval [low, high] where f(low) and f(high) have opposite signs
        double low = -1000.0;
        double high = 1000.0;

        // Expand search range until we find opposite signs
        while (f.applyAsDouble(low) * f.applyAsDouble(high) > 0) {
            low *= 2;
            high *= 2;
            // Safety limit to prevent infinite loops
            if (Math.abs(low) > 1e9) {
                // Fallback: return midpoint as approximation
                return (low + high) / 2;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives precision ~1e-30
            double mid = (low + high) / 2;
            double fMid = f.applyAsDouble(mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (f.applyAsDouble(low) * fMid < 0) {
                high = mid;
            } else {
                low = mid;
            }
        }

        return (low + high) / 2;
    }
}

