class Solution {
    public int fizzBuzz(int n) {
        int count = 0;

        for (int i = 1; i < n; i++) {
            // Check if divisible by 11 or 13
            if (i % 11 == 0 || i % 13 == 0) {
                // Count occurrences of digit 7 in i
                String numStr = String.valueOf(i);
                for (int j = 0; j < numStr.length(); j++) {
                    if (numStr.charAt(j) == '7') {
                        count++;
                    }
                }
            }
        }

        return count;
    }
}

