class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Check constraint: even number of coefficients
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Check if largest non-zero coefficient condition is met (not strictly necessary for implementation,
        // but the problem states we only take such lists)

        // Use Newton-Raphson method
        double x = 1.0; // initial guess

        // Try multiple starting points in case of poor convergence
        double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 0.5, -0.5, 10.0, -10.0};

        for (double start : startingPoints) {
            double currentX = start;
            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, currentX);

                // If we're close enough to zero, return
                if (Math.abs(fx) < 1e-10) {
                    return currentX;
                }

                // Compute derivative
                double fPrime = 0.0;
                for (int i = 1; i < xs.size(); i++) {
                    fPrime += i * xs.get(i) * Math.pow(currentX, i - 1);
                }

                // Avoid division by zero
                if (Math.abs(fPrime) < 1e-10) {
                    break; // try next starting point
                }

                double nextX = currentX - fx / fPrime;

                // Check for divergence or NaN
                if (Double.isNaN(nextX) || Double.isInfinite(nextX)) {
                    break; // try next starting point
                }

                currentX = nextX;
            }
        }

        // If Newton's method fails, try bisection on a reasonable interval
        // Since it's an odd-degree polynomial, it goes to ±∞ as x→±∞
        double left = -100.0;
        double right = 100.0;

        // Find an interval where the function changes sign
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 2;
            right *= 2;
            if (left < -1e6) {
                // Fallback: return 0 if nothing works
                return 0.0;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Return midpoint as best estimate
        return (left + right) / 2;
    }
}

