class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Edge case: empty substring or empty string
        if (substring == null || substring.isEmpty() || string == null) {
            return 0;
        }

        int count = 0;
        int stringLength = string.length();
        int substringLength = substring.length();

        // If substring is longer than string, impossible to match
        if (substringLength > stringLength) {
            return 0;
        }

        // Check at each possible starting position
        for (int i = 0; i <= stringLength - substringLength; i++) {
            if (string.substring(i, i + substringLength).equals(substring)) {
                count++;
            }
        }

        return count;
    }
}

