class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Validate input: even number of coefficients
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("Polynomial must have even number of coefficients");
        }

        // Check if leading coefficient is non-zero
        double leadingCoeff = xs.get(xs.size() - 1);
        if (Math.abs(leadingCoeff) < 1e-15) {
            throw new IllegalArgumentException("Leading coefficient must be non-zero");
        }

        // Handle linear case (degree 1)
        if (xs.size() == 2) {
            // f(x) = a + bx, root is -a/b
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) < 1e-15) {
                throw new IllegalArgumentException("Linear polynomial must have non-zero slope");
            }
            return -a / b;
        }

        // For higher degrees, use bisection method
        // Since it's an odd-degree polynomial (even # of coefficients), 
        // it must have at least one real root

        double left = -1000.0;
        double right = 1000.0;

        // Find an interval where function changes sign
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand search range if needed
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 10) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // If still no sign change, try different approach
        if (fLeft * fRight > 0) {
            // Try centered interval
            left = -10.0;
            right = 10.0;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);

            // Search in smaller increments
            for (double x = -10; x <= 10; x += 0.5) {
                double fX = poly(xs, x);
                if (Math.abs(fX) < 1e-9) {
                    return x;
                }
                if (x > -10) {
                    double fPrev = poly(xs, x - 0.5);
                    if (fPrev * fX < 0) {
                        left = x - 0.5;
                        right = x;
                        break;
                    }
                }
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint as fallback
        return (left + right) / 2;
    }
}

