class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        String[] words = numbers.split(" ");

        // Create array to hold the numeric values
        int[] values = new int[words.length];

        // Map each word to its numeric value
        for (int i = 0; i < words.length; i++) {
            values[i] = wordToNumber(words[i]);
        }

        // Sort the numeric values
        Arrays.sort(values);

        // Convert back to words
        String[] resultWords = new String[words.length];
        for (int i = 0; i < words.length; i++) {
            resultWords[i] = numberToWord(values[i]);
        }

        return String.join(" ", resultWords);
    }

    private int wordToNumber(String word) {
        Map<String, Integer> map = new HashMap<>();
        map.put("zero", 0);
        map.put("one", 1);
        map.put("two", 2);
        map.put("three", 3);
        map.put("four", 4);
        map.put("five", 5);
        map.put("six", 6);
        map.put("seven", 7);
        map.put("eight", 8);
        map.put("nine", 9);

        return map.getOrDefault(word, -1);
    }

