class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        if (n <= 1) {
            return 0; // or throw exception, but based on examples, n >= 2 likely
        }

        // Check from n/2 downwards - the first divisor we find is the largest
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // This handles the case where n is prime (largest proper divisor is 1)
    }
}

