            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For Newton-Raphson method
        double x = 1.0; // initial guess

        // Try multiple starting points if needed
        for (double startX = 0; startX < 10; startX += 1) {
            double currentX = startX;
            for (int i = 0; i < 100; i++) { // max iterations
                double fx = poly(xs, currentX);

                // Check if we found a root
                if (Math.abs(fx) < 1e-9) {
                    return currentX;
                }

                // Compute derivative numerically
                double h = 1e-7;
                double fpx = (poly(xs, currentX + h) - poly(xs, currentX - h)) / (2 * h);

                // Avoid division by zero
                if (Math.abs(fpx) < 1e-9) {
                    break; // try next starting point
                }

                double newX = currentX - fx / fpx;

                // Check for convergence
                if (Math.abs(newX - currentX) < 1e-9) {
                    if (Math.abs(poly(xs, newX)) < 1e-9) {
                        return newX;
                    }
                    break; // try next starting point
                }

                currentX = newX;
            }
        }

        // Fallback: try bisection on a large interval
        // Since leading coefficient is non-zero and degree is odd, limits at ±∞ have opposite signs
        double left = -1000.0;
        double right = 1000.0;

        // Find interval where sign changes
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 2;
            right *= 2;
            if (left < -1e10) break; // safety limit
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fmid = poly(xs, mid);

            if (Math.abs(fmid) < 1e-9) {
                return mid;
            }

            if (poly(xs, left) * fmid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Return midpoint as best guess
        return (left + right) / 2;
    }
}

