                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // According to problem statement, we assume valid input,
                    // but in production code might throw IllegalArgumentException
                    break;
            }
        }

        return result;
    }
}

