class Solution {
    public double findZero(List<Double> xs) {
            // Use Newton-Raphson method to find a root
            // Start with initial guess and iterate
            double x = 1.0; // Initial guess

            // Newton-Raphson: x_{n+1} = x_n - f(x_n) / f'(x_n)
            for (int i = 0; i < 100; i++) {
                double fx = poly(xs, x);

                // If we're close enough to zero, return
                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                // Compute derivative
                double fpx = 0.0;
                for (int j = 1; j < xs.size(); j++) {
                    fpx += xs.get(j) * j * Math.pow(x, j - 1);
                }

                // Avoid division by zero
                if (Math.abs(fpx) < 1e-10) {
                    // Try a different starting point
                    x += 0.5;
                    continue;
                }

                x = x - fx / fpx;

                // Handle overflow or NaN
                if (Double.isNaN(x) || Double.isInfinite(x)) {
                    x = x > 0 ? 1.0 : -1.0;
                }
            }

            // Fallback: return the best approximation found
            return x;
        }
}

