class Solution {
    public double findZero(List<Double> xs) {
        // Check if we have even number of coefficients (odd degree polynomial)
        int n = xs.size();
        if (n % 2 != 0) {
            throw new IllegalArgumentException("Polynomial must have even number of coefficients");
        }

        // Find the leading coefficient (largest non-zero coefficient)
        double leadingCoeff = xs.get(n - 1);
        for (int i = n - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-15) {
                leadingCoeff = xs.get(i);
                break;
            }
        }

        // Ensure we have odd degree (even number of coefficients means degree = n-1, which should be odd)
        int degree = n - 1;
        if (degree % 2 == 0) {
            throw new IllegalArgumentException("Leading coefficient must correspond to odd degree polynomial");
        }

        // Bisection method parameters
        double left = -1000.0;
        double right = 1000.0;
        double tolerance = 1e-10;
        int maxIterations = 1000;

        // Find interval where function changes sign
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand interval if needed to find sign change
        int expansionCount = 0;
        while (fLeft * fRight > 0 && expansionCount < 20) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            expansionCount++;
        }

        // Bisection method
        for (int iter = 0; iter < maxIterations; iter++) {
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance || (right - left) / 2.0 < tolerance) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint if we didn't converge to tolerance
        return (left + right) / 2.0;
    }
}

