class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Start from n/2 and go downwards since the largest proper divisor
        // cannot be larger than n/2 (except for n=1, which has no proper divisors)
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }
        return 1; // This line handles n=1 case, though mathematically 1 has no proper divisors
    }
}

