class Solution {
    public double findZero(List<Double> xs) {
        final double EPS = 1e-9;
        final int MAX_ITER = 1000;

        // Bisection method: find interval [a,b] with sign change
        double a = -100.0;
        double b = 100.0;

        // Expand interval until sign change (for safety, though odd-degree guarantees one)
        double fa = poly(xs, a);
        double fb = poly(xs, b);
        int expansion = 0;
        while (fa * fb > 0 && expansion < 30) {
            a *= 10;
            b *= 10;
            fa = poly(xs, a);
            fb = poly(xs, b);
            expansion++;
        }

        // If still same sign, fallback to midpoint (rare)
        if (fa * fb > 0) {
            // Just return midpoint as fallback
            return (a + b) / 2;
        }

        // Bisection loop
        for (int i = 0; i < MAX_ITER; i++) {
            double mid = (a + b) / 2;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < EPS) {
                return mid;
            }

            if (fa * fm < 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        // After iterations, return best estimate
        return (a + b) / 2;
    }
}

