class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases: numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // All other even numbers are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        // We only need to check up to sqrt(n) because if n = a*b and a <= b,
        // then a ≤ sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For small polynomials, try direct solving first
        if (xs.size() == 2) {
            // Linear: a + bx = 0 => x = -a/b
            return -xs.get(0) / xs.get(1);
        }

        // For higher degrees, use Newton-Raphson
        // Find the leading coefficient (last non-zero coefficient)
        int n = xs.size() - 1; // degree
        double leadingCoeff = xs.get(n);
        while (Math.abs(leadingCoeff) < 1e-12 && n > 0) {
            n--;
            leadingCoeff = xs.get(n);
        }

        // Use Newton-Raphson with multiple starting points
        for (double start : new double[]{-1000.0, -10.0, -1.0, 0.0, 1.0, 10.0, 1000.0}) {
            double x = start;
            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, x);
                // Calculate derivative
                double fpx = 0;
                for (int i = 1; i < xs.size(); i++) {
                    fpx += i * xs.get(i) * Math.pow(x, i - 1);
                }

                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                if (Math.abs(fpx) < 1e-12) {
                    // Derivative too small, try perturbation
                    x += 0.1;
                    continue;
                }

                double xNext = x - fx / fpx;

                // Check if converged
                if (Math.abs(xNext - x) < 1e-10) {
                    if (Math.abs(poly(xs, xNext)) < 1e-8) {
                        return xNext;
                    }
                    break; // diverged, try next start
                }

                x = xNext;
            }
        }

        // Fallback: bisection method on interval [-bound, bound]
        double bound = 1.0;
        for (int i = 0; i < xs.size() - 1; i++) {
            bound += Math.abs(xs.get(i));
        }
        bound /= Math.abs(leadingCoeff);
        bound = Math.max(bound, 10.0);

        double left = -bound;
        double right = bound;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Ensure we have a sign change
        while (fLeft * fRight > 0 && bound < 1e10) {
            bound *= 10;
            left = -bound;
            right = bound;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        // Bisection
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);
            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }
            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

