class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 0, b = 1; // Fibonacci sequence starts with 0, 1

        while (true) {
            int next = a + b;
            a = b;
            b = next;

            // Check if the current Fibonacci number is prime
            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }

            // Safety check to avoid potential overflow issues for very large numbers
            if (next < 0) {
                throw new ArithmeticException("Fibonacci number overflow");
            }
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

