    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Edge case: empty substring cannot be found meaningfully
        if (substring.isEmpty()) {
            return 0;
        }

        // Edge case: empty string, substring can't be found
        if (string.isEmpty()) {
            return 0;
        }

        int count = 0;
        // Check from each possible starting position
        for (int i = 0; i <= string.length() - substring.length(); i++) {
            // Check if substring matches at position i
            if (string.substring(i, i + substring.length()).equals(substring)) {
                count++;
            }
        }

        return count;
    }
}

