class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return numbers;
        }

        // Map number words to their numeric values
        Map<String, Integer> wordToNumber = new HashMap<>();
        wordToNumber.put("zero", 0);
        wordToNumber.put("one", 1);
        wordToNumber.put("two", 2);
        wordToNumber.put("three", 3);
        wordToNumber.put("four", 4);
        wordToNumber.put("five", 5);
        wordToNumber.put("six", 6);
        wordToNumber.put("seven", 7);
        wordToNumber.put("eight", 8);
        wordToNumber.put("nine", 9);

        // Reverse mapping for conversion back to words
        String[] numberToWord = {
            "zero", "one", "two", "three", "four", 
            "five", "six", "seven", "eight", "nine"
        };

        // Split input string into words
        String[] words = numbers.split(" ");

        // Convert to list of Integer values for sorting
        List<Integer> numericValues = new ArrayList<>();
        for (String word : words) {
            numericValues.add(wordToNumber.get(word));
        }

        // Sort the numeric values
        Collections.sort(numericValues);

        // Convert back to words and join with spaces
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < numericValues.size(); i++) {
            if (i > 0) {
                result.append(" ");
            }
            result.append(numberToWord[numericValues.get(i)]);
        }

        return result.toString();
    }
}

