class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases: numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // All other even numbers are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Validate: must have even number of coefficients
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Use bisection method with expanding search range
        double left = -1000.0;
        double right = 1000.0;
        double tolerance = 1e-9;

        // Expand search range if needed to ensure sign change
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 2;
            right *= 2;
            // Safety check to prevent infinite loop
            if (Math.abs(left) > 1e12) {
                // Fallback: try Newton's method starting from 0
                return newtonRaphson(xs, 0.0);
            }
        }

        // Bisection method
        while (right - left > tolerance) {
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance) {
                return mid;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2.0;
    }

    // Helper method for Newton-Raphson fallback
    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        double tolerance = 1e-9;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative: f'(x) = sum(i * xs[i] * x^(i-1))
            double fPrime = 0;
            for (int j = 1; j < xs.size(); j++) {
                fPrime += j * xs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(fPrime) < 1e-15) {
                // Derivative too small, perturb x slightly
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fPrime;
            if (Math.abs(xNext - x) < tolerance) {
                return xNext;
            }
            x = xNext;
        }

        return x;
    }
}

