class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method to find a root
        double x = 0.0; // initial guess
        double epsilon = 1e-10;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative using finite difference or analytical derivative
            // Let's compute derivative analytically for better accuracy
            double fPrime = 0.0;
            for (int j = 1; j < xs.size(); j++) {
                fPrime += j * xs.get(j) * Math.pow(x, j - 1);
            }

            // Avoid division by zero
            if (Math.abs(fPrime) < 1e-15) {
                // If derivative is too small, try a different approach
                // Slightly perturb x to avoid stagnation
                x += 0.01;
                continue;
            }

            double xNext = x - fx / fPrime;

            // Check for convergence
            if (Math.abs(xNext - x) < epsilon) {
                // Verify this is actually a root
                if (Math.abs(poly(xs, xNext)) < epsilon) {
                    return xNext;
                }
            }

            x = xNext;
        }

        // Fallback: if Newton-Raphson didn't converge, try bisection
        // Since we know there's a root, and polynomial goes to ±infinity on ends
        double left = -1000.0;
        double right = 1000.0;

        // Find interval where sign changes
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 2;
            right *= 2;
            if (Math.abs(left) > 1e6) {
                break;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fmid = poly(xs, mid);

            if (Math.abs(fmid) < epsilon) {
                return mid;
            }

            if (poly(xs, left) * fmid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2;
    }
}

