class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 1;
        long b = 1;

        // Handle first few Fibonacci numbers manually since we need to include 2
        // which appears early in the sequence

        // Check the first few Fibonacci numbers
        if (isPrime((int)a)) {
            count++;
            if (count == n) return (int)a;
        }

        if (isPrime((int)b)) {
            count++;
            if (count == n) return (int)b;
        }

        // Now generate remaining Fibonacci numbers starting from 2
        long c;
        while (true) {
            c = a + b;
            if (isPrime((int)c)) {
                count++;
                if (count == n) return (int)c;
            }
            a = b;
            b = c;
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

