import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For linear case (2 coefficients): xs[0] + xs[1]*x = 0 => x = -xs[0]/xs[1]
        if (xs.size() == 2) {
            double a0 = xs.get(0);
            double a1 = xs.get(1);
            if (Math.abs(a1) < 1e-15) {
                // Fallback for degenerate case - should not happen per problem constraints
                return 0.0;
            }
            return -a0 / a1;
        }

        // Newton-Raphson method for higher degree polynomials
        double x = 0.0; // Start with initial guess

        // Try multiple starting points to increase chances of finding a root
        double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0, 0.5, -0.5};

        for (double startX : startingPoints) {
            x = startX;
            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, x);

                // Check if we found a root
                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                // Compute derivative
                double fp = polyDerivative(xs, x);

                // If derivative is too small, avoid division by zero
                if (Math.abs(fp) < 1e-15) {
                    // Slight perturbation to escape flat region
                    x += 0.001;
                    continue;
                }

                double xNew = x - fx / fp;

                // Check for convergence or divergence
                if (Double.isNaN(xNew) || Double.isInfinite(xNew)) {
                    break;
                }

                // Check if we're converging
                if (Math.abs(xNew - x) < 1e-12) {
                    if (Math.abs(poly(xs, xNew)) < 1e-10) {
                        return xNew;
                    }
                    break;
                }

                x = xNew;
            }
        }

        // Fallback: return the best approximation found
        return x;
    }

    // Helper method to evaluate polynomial derivative
    private double polyDerivative(List<Double> coeffs, double x) {
        if (coeffs.size() <= 1) {
            return 0.0;
        }

        double result = 0;
        for (int i = 1; i < coeffs.size(); i++) {
            result += i * coeffs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

