class Solution {
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Precondition: xs has even number of coefficients → degree is odd → guaranteed real root
        int n = xs.size() - 1; // degree of polynomial
        double[] coeffs = xs.toArray(new double[0]);

        // Helper: evaluate polynomial at x
        java.util.function.DoubleUnaryOperator eval = x -> {
            double sum = 0;
            double term = 1;
            for (int i = 0; i <= n; i++) {
                sum += coeffs[i] * term;
                term *= x;
            }
            return sum;
        };

        // Find interval [a, b] where f(a) and f(b) have opposite signs
        double a = -1.0;
        double b = 1.0;
        double fa = eval.applyAsDouble(a);
        double fb = eval.applyAsDouble(b);

        // Expand interval until sign change
        int expansionCount = 0;
        while (fa * fb > 0 && expansionCount < 100) {
            if (Math.abs(fa) < Math.abs(fb)) {
                a *= 2;
                fa = eval.applyAsDouble(a);
            } else {
                b *= 2;
                fb = eval.applyAsDouble(b);
            }
            expansionCount++;
        }

        // Fallback: if still no sign change, try symmetric expansion
        if (fa * fb > 0) {
            // Try large bounds
            a = -1e6;
            b = 1e6;
            fa = eval.applyAsDouble(a);
            fb = eval.applyAsDouble(b);
            // If still same sign, try midpoint and hope for best (unlikely)
            if (fa * fb > 0) {
                // Worst case: assume root near 0
                return 0.0;
            }
        }

        // Bisection method
        double tolerance = 1e-9;
        int maxIterations = 1000;
        for (int i = 0; i < maxIterations; i++) {
            double mid = (a + b) / 2;
            double fm = eval.applyAsDouble(mid);

            if (Math.abs(fm) < tolerance || (b - a) / 2 < tolerance) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2;
    }
}

