            "five", "six", "seven", "eight", "nine"
        };

        // Split, convert to integers, sort, convert back to words, join
        List<String> words = Arrays.asList(numbers.split(" "));

        // Sort by numeric value using method references
        words.sort(Comparator.comparing(word -> wordToDigit.get(word)));

        // Map back to words using method reference
        List<String> sortedWords = words.stream()
            .map(digitToWord[wordToDigit.get(wordToDigit.get(words.get(0))) == 0 ? 
