class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method to find a root
        double x = 1.0; // initial guess
        for (int i = 0; i < 100; i++) { // limit iterations to avoid infinite loops
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative: f'(x) = sum_{j=1}^{n-1} j * xs[j] * x^(j-1)
            double fpx = 0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(fpx) < 1e-10) {
                // Derivative too small, try perturbing x
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;
            if (Double.isInfinite(xNext) || Double.isNaN(xNext)) {
                x += 0.1; // perturb and try again
            } else {
                x = xNext;
            }
        }
        return x;
    }
}

