class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // The largest proper divisor of n is at most n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }
        // This should never happen for n > 1, but return 1 as fallback
        // For n = 1, there is no proper divisor, but problem likely assumes n > 1
        return 1;
    }
}

