import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle linear case directly: a + bx = 0 -> x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            return -a / b;
        }

        // Build derivative coefficients: if original is [a0, a1, a2, ..., an],
        // derivative is [a1, 2*a2, 3*a3, ..., n*an]
        List<Double> deriv = new ArrayList<>();
        for (int i = 1; i < xs.size(); i++) {
            deriv.add((double) i * xs.get(i));
        }

        // Newton-Raphson: x_{n+1} = x_n - f(x_n)/f'(x_n)
        double x = 0.0; // initial guess
        for (int iter = 0; iter < 100; iter++) { // max iterations
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            double fpx = poly(deriv, x);
            if (Math.abs(fpx) < 1e-10) {
                // Derivative too small, try perturbation
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < 1e-10) {
                return xNext;
            }

            x = xNext;
        }

        // Fallback: return best approximation found
        return x;
    }
}

