        }

        String[] tokens = string.trim().split("\\s+");
        List<Integer> result = new ArrayList<>();

        for (String token : tokens) {
            switch (token) {
                case "o":
                    result.add(4);
                    break;
                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // For invalid tokens, could throw exception or skip
                    // Based on problem statement, we assume valid input
                    break;
            }
        }

        return result;
    }
}

