class Solution {
    /**
    For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sumProduct(List.of())
    [0, 1]
    >>> sumProduct(Arrays.asList(1, 2, 3, 4))
    [10, 24]
     */
    public List<Integer> sumProduct(List<Integer> numbers) {
        // Handle null input safely
        if (numbers == null || numbers.isEmpty()) {
            return Arrays.asList(0, 1);
        }

        // Calculate sum using stream
        int sum = numbers.stream()
                        .mapToInt(Integer::intValue)
                        .sum();

        // Calculate product using stream with identity value of 1
        int product = numbers.stream()
                            .mapToInt(Integer::intValue)
                            .reduce(1, (a, b) -> a * b);

        return Arrays.asList(sum, product);
    }
}

