class Solution {
    public String makePalindrome(String string) {
        if (string == null || string.isEmpty()) {
            return string;
        }

        // Find the longest palindromic suffix
        for (int i = 0; i < string.length(); i++) {
            // Check if substring from i to end is a palindrome
            if (isPalindrome(string.substring(i))) {
                // If yes, take the prefix before i, reverse it, and append
                String prefix = string.substring(0, i);
                StringBuilder reversedPrefix = new StringBuilder(prefix).reverse();
                return string + reversedPrefix.toString();
            }
        }

        // Fallback (should not reach here since single char is always palindrome)
        return string;
    }
}

