    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true;  // 2 and 3 are prime
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check for divisors from 5 up to sqrt(n), skipping even numbers
        // Using the 6k ± 1 optimization: all primes > 3 are of form 6k ± 1
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Convert to array for faster access
        double[] coeffs = xs.stream().mapToDouble(Double::doubleValue).toArray();
        int n = coeffs.length;

        // Define a function to evaluate polynomial
        java.util.function.DoubleUnaryOperator f = x -> {
            double result = 0;
            double xPower = 1;
            for (int i = 0; i < n; i++) {
                result += coeffs[i] * xPower;
                xPower *= x;
            }
            return result;
        };

        // Bisection method
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = f.applyAsDouble(left);
        double fRight = f.applyAsDouble(right);

        // If signs are same, expand interval
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 20) {
            left *= 2;
            right *= 2;
            fLeft = f.applyAsDouble(left);
            fRight = f.applyAsDouble(right);
            attempts++;
        }

        // If still same sign, try other intervals
        if (fLeft * fRight > 0) {
            // Fallback: try from 0 to some value
            left = -100.0;
            right = 100.0;
        }

        // Now apply bisection
        for (int i = 0; i < 100; i++) { // 100 iterations for precision
            double mid = (left + right) / 2.0;
            double fMid = f.applyAsDouble(mid);

            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

