    >>> intersperse(Arrays.asList(1, 2, 3), 4)
    [1, 4, 2, 4, 3]
     */
    public List<Integer> intersperse(List<Integer> numbers, int delimiter) {
        if (numbers.isEmpty()) {
            return new ArrayList<>();
        }

        return numbers.stream()
            .flatMap(num -> {
                // For each element, we output the element itself
                // and then the delimiter, except for the last element
                if (num.equals(numbers.get(numbers.size() - 1))) {
                    return Stream.of(num);
                } else {
                    return Stream.of(num, delimiter);
                }
            })
            .toList();
    }
}

