import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Newton-Raphson method
        double x = 1.0; // initial guess
        double tolerance = 1e-9;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative at x
            double dfx = polyDerivative(xs, x);
            if (Math.abs(dfx) < 1e-12) {
                // Derivative too small, try different starting point
                x += 0.1;
                continue;
            }

            double xNew = x - fx / dfx;

            // Check for convergence
            if (Math.abs(xNew - x) < tolerance) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNew)) < tolerance) {
                    return xNew;
                }
            }

            x = xNew;

            // Handle overflow/NaN
            if (Double.isNaN(x) || Double.isInfinite(x)) {
                // Fallback to bisection or try different start
                x = 0.5;
            }
        }

        // If Newton fails, try bisection on reasonable interval
        // Since problem says solution exists, and leading coefficient is largest,
        // there should be at least one real root
        for (double left = -100.0, right = 100.0; left < right; ) {
            double mid = (left + right) / 2;
            double fmid = poly(xs, mid);
            if (Math.abs(fmid) < 1e-8) {
                return mid;
            }

            double fleft = poly(xs, left);
            if (fleft * fmid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Last resort: return 0 if it happens to be a root
        return 0.0;
    }

    private double polyDerivative(List<Double> coeffs, double x) {
        if (coeffs.size() <= 1) {
            return 0;
        }

        List<Double> derivCoeffs = new ArrayList<>();
        for (int i = 1; i < coeffs.size(); i++) {
            derivCoeffs.add(coeffs.get(i) * i);
        }

        return poly(derivCoeffs, x);
    }
}

