    public Optional<String> longest(List<String> strings) {
        if (strings == null || strings.isEmpty()) {
            return Optional.empty();
        }

        return strings.stream()
                .max((s1, s2) -> {
                    int len1 = s1.length();
                    int len2 = s2.length();
                    if (len1 != len2) {
                        return Integer.compare(len1, len2);
                    }
                    // If lengths are equal, we want the first one encountered
                    // max() preserves the first element when comparison returns 0
                    return 0;
                });
    }
}

