import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        double xPower = 1;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * xPower;
            xPower *= x;
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle linear case directly: xs[0] + xs[1]*x = 0 => x = -xs[0]/xs[1]
        if (xs.size() == 2) {
            return -xs.get(0) / xs.get(1);
        }

        // For higher degrees, use Newton-Raphson method
        double x = 1.0; // Start with initial guess

        // Try Newton-Raphson with several iterations
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative: f'(x)
            double dfx = 0;
            double xPower = 1;
            for (int j = 1; j < xs.size(); j++) {
                dfx += j * xs.get(j) * xPower;
                xPower *= x;
            }

            // Avoid division by zero
            if (Math.abs(dfx) < 1e-15) {
                // Try different starting point
                x += 1.0;
                continue;
            }

            double xNext = x - fx / dfx;

            // Check for convergence
            if (Math.abs(xNext - x) < 1e-10) {
                return xNext;
            }

            x = xNext;
        }

        // Fallback: if Newton-Raphson didn't converge well, try bisection
        // Find interval where function changes sign
        double left = -100.0;
        double right = 100.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Ensure we have a sign change
        while (fLeft * fRight > 0) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

