class Solution {
    public double findZero(List<Double> xs) {
        // Define a large enough interval based on polynomial degree
        int n = xs.size() - 1; // degree
        // For safety, use larger bounds for higher degrees
        double left = -Math.pow(10, Math.max(3, n/2 + 1));
        double right = Math.pow(10, Math.max(3, n/2 + 1));

        // Ensure we have opposite signs
        double fl = poly(xs, left);
        double fr = poly(xs, right);

        // If signs are same, expand interval until we find opposite signs
        int iterations = 0;
        while (fl * fr >= 0 && iterations < 20) {
            left *= 10;
            right *= 10;
            fl = poly(xs, left);
            fr = poly(xs, right);
            iterations++;
        }

        // Now apply bisection method
        double mid;
        double eps = 1e-9;

        for (int i = 0; i < 100; i++) { // max iterations
            mid = (left + right) / 2;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < eps) {
                return mid;
            }

            if (fl * fm < 0) {
                right = mid;
                fr = fm;
            } else {
                left = mid;
                fl = fm;
            }
        }

        return mid;
    }
}

