class Solution {
    public List<String> separateParenGroups(String paren_string) {
        List<String> result = new ArrayList<>();
        StringBuilder currentGroup = new StringBuilder();
        int balance = 0;

        // Remove spaces by filtering as we process
        for (int i = 0; i < paren_string.length(); i++) {
            char c = paren_string.charAt(i);

            // Skip spaces
            if (c == ' ') {
                continue;
            }

            // Only process parentheses
            if (c == '(' || c == ')') {
                currentGroup.append(c);

                if (c == '(') {
                    balance++;
                } else { // c == ')'
                    balance--;
                }

                // When balance is 0, we've completed a balanced group
                if (balance == 0 && currentGroup.length() > 0) {
                    result.add(currentGroup.toString());
                    currentGroup.setLength(0); // Reset for next group
                }
            }
        }

        return result;
    }
}

