class Solution {
    public List<Double> rescaleToUnit(List<Double> numbers) {
        if (numbers == null || numbers.isEmpty()) {
            return new ArrayList<>();
        }

        // Find min and max
        Double min = Collections.min(numbers);
        Double max = Collections.max(numbers);

        // Handle edge case where all values are the same
        if (min.equals(max)) {
            // All values are identical, return list of zeros (or could return all 0.5)
            // Based on typical min-max normalization, if range is 0, all values map to 0
            List<Double> result = new ArrayList<>(numbers.size());
            for (int i = 0; i < numbers.size(); i++) {
                result.add(0.0);
            }
            return result;
        }

        // Apply the rescaling transformation
        double range = max - min;
        return numbers.stream()
                      .map(x -> (x - min) / range)
                      .collect(ArrayList::new, ArrayList::add, ArrayList::addAll);
    }
}

