class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method to find a root
        double x = 0.0; // initial guess

        // Try multiple starting points to increase chances of finding a root
        for (double startX = -10.0; startX <= 10.0; startX += 1.0) {
            double currentX = startX;
            for (int i = 0; i < 100; i++) { // max iterations
                double fx = poly(xs, currentX);

                // If we're close enough to zero, return
                if (Math.abs(fx) < 1e-9) {
                    return currentX;
                }

                // Compute derivative
                double fPrimeX = polyDerivative(xs, currentX);

                // Avoid division by zero
                if (Math.abs(fPrimeX) < 1e-12) {
                    break; // try next starting point
                }

                double nextX = currentX - fx / fPrimeX;

                // Check for convergence or overflow
                if (Double.isNaN(nextX) || Double.isInfinite(nextX) || 
                    Math.abs(nextX - currentX) < 1e-12) {
                    break;
                }

                currentX = nextX;
            }
        }

        // Fallback: try bisection between -1000 and 1000
        double left = -1000.0;
        double right = 1000.0;

        // Find interval where sign changes
        while (left < right) {
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            double fLeft = poly(xs, left);
            if (fLeft * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2.0;
    }

    // Helper method to compute polynomial derivative
    private double polyDerivative(List<Double> xs, double x) {
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += xs.get(i) * i * Math.pow(x, i - 1);
        }
        return result;
    }
}

