class Solution {
    public int largestDivisor(int n) {
        // Edge cases: n should be > 1, as 1 has no proper divisors
        if (n <= 1) {
            return -1; // or throw exception, but problem context suggests n >= 2
        }

        // The largest proper divisor cannot exceed n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // This line is technically unreachable for n >= 2, but added for completeness
    }
}

