class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // All other even numbers are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        // Only need to check up to sqrt(n) because if n = a*b and a <= b, then a <= sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Find the highest degree term (non-zero coefficient from the end)
        int degree = xs.size() - 1;
        while (degree > 0 && Math.abs(xs.get(degree)) < 1e-15) {
            degree--;
        }

        // For degree 1: ax + b = 0 => x = -b/a
        if (degree == 1) {
            return -xs.get(0) / xs.get(1);
        }

        // Newton-Raphson method
        double x = 0.0; // initial guess

        // Try multiple starting points if needed
        for (int start = 0; start < 5; start++) {
            double currentX = start - 2.0; // try -2, -1, 0, 1, 2
            for (int iteration = 0; iteration < 100; iteration++) {
                double fx = polyValue(xs, currentX);
                if (Math.abs(fx) < 1e-10) {
                    return currentX;
                }

                double fpx = polyDerivativeValue(xs, currentX);
                if (Math.abs(fpx) < 1e-15) {
                    break; // derivative too small, try another start
                }

                double nextX = currentX - fx / fpx;

                // Check for convergence
                if (Math.abs(nextX - currentX) < 1e-10) {
                    return nextX;
                }

                currentX = nextX;

                // Avoid overflow
                if (Double.isInfinite(currentX) || Double.isNaN(currentX)) {
                    break;
                }
            }
        }

        // Fallback: try bisection method on a reasonable interval
        // Since odd degree polynomials go from -inf to +inf or vice versa
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = polyValue(xs, left);
        double fRight = polyValue(xs, right);

        // Make sure we have opposite signs
        if (fLeft * fRight > 0) {
            // Expand search range
            for (double bound : new double[]{10000, 100000}) {
                left = -bound;
                right = bound;
                fLeft = polyValue(xs, left);
                fRight = polyValue(xs, right);
                if (fLeft * fRight <= 0) break;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = polyValue(xs, mid);

            if (Math.abs(fMid) < 1e-10 || (right - left) < 1e-10) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }

    // Helper methods for clarity (can be inlined if needed)
    private double polyValue(List<Double> xs, double x) {
        double result = 0;
        double xPower = 1;
        for (double coeff : xs) {
            result += coeff * xPower;
            xPower *= x;
        }
        return result;
    }

    private double polyDerivativeValue(List<Double> xs, double x) {
        // derivative of a0 + a1*x + a2*x^2 + ... is a1 + 2*a2*x + 3*a3*x^2 + ...
        double result = 0;
        double xPower = 1;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * xPower;
            xPower *= x;
        }
        return result;
    }
}

