import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Using Horner's method for efficiency and numerical stability
        double result = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge case: linear polynomial (degree 1)
        if (xs.size() == 2) {
            return -xs.get(0) / xs.get(1);
        }

        // Use Newton-Raphson method
        double x = 1.0; // initial guess

        // Derivative coefficients: for [a0, a1, a2, ..., an], derivative is [a1, 2*a2, 3*a3, ...]
        List<Double> derivativeCoeffs = new ArrayList<>();
        for (int i = 1; i < xs.size(); i++) {
            derivativeCoeffs.add(xs.get(i) * i);
        }

        // Newton-Raphson iterations
        for (int i = 0; i < 100; i++) { // max iterations
            double fx = poly(xs, x);
            double fpx = poly(derivativeCoeffs, x);

            // Check if we found a root
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-10) {
                // Try a different starting point
                x += 1.0;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < 1e-10) {
                return xNext;
            }

            x = xNext;
        }

        // Fallback: return last computed value
        return x;
    }
}

