class Solution {
    /**
    From a given list of integers, generate a list of rolling maximum element found until given moment
    in the sequence.
    >>> rollingMax(Arrays.asList(1, 2, 3, 2, 3, 4, 2))
    [1, 2, 3, 3, 3, 4, 4]
     */
    public List<Integer> rollingMax(List<Integer> numbers) {
        if (numbers == null || numbers.isEmpty()) {
            return new ArrayList<>();
        }

        return numbers.stream()
            .collect(() -> {
                List<Integer> result = new ArrayList<>();
                AtomicInteger currentMax = new AtomicInteger(Integer.MIN_VALUE);
                return new Object() {
                    List<Integer> getResult() { return result; }
                    AtomicInteger getCurrentMax() { return currentMax; }
                };
            },
            (acc, num) -> {
                int current = Math.max(acc.getCurrentMax().get(), num);
                acc.getCurrentMax().set(current);
                acc.getResult().add(current);
            },
            (acc1, acc2) -> {
                throw new UnsupportedOperationException("Parallel stream not supported");
            })
            .getResult();
    }
}

