     */
    public List<Double> findClosestElements(List<Double> numbers) {
        // Sort the list first
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        // Use streams to find the pair with minimum difference
        return IntStream.range(1, sorted.size())
            .mapToObj(i -> new double[]{sorted.get(i-1), sorted.get(i)})
            .min(Comparator.<double[]>comparingDouble(pair -> Math.abs(pair[1] - pair[0])))
            .map(pair -> Arrays.asList(pair[0], pair[1]))
            .orElse(null);
    }
}

