        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Horner's method for better numerical stability and efficiency
        double result = 0.0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Binary search approach for finding a root
        double left = -1000.0;
        double right = 1000.0;
        double epsilon = 1e-7;

        // Ensure we have values with opposite signs at the boundaries
        // For odd-degree polynomials, as x->∞, f(x)->sign(a_n)*∞, as x->-∞, f(x)->-sign(a_n)*∞
        // So we should have opposite signs at some finite bounds

        // Expand search range if needed
        while (Math.abs(poly(xs, left)) > 1e10 || Math.abs(poly(xs, right)) > 1e10) {
            left *= 2;
            right *= 2;
        }

        // Make sure poly(left) and poly(right) have opposite signs
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If same sign, expand further
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 30) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // Binary search
        while (right - left > epsilon) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < epsilon) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

