class Solution {
    /**
    Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13.
    >>> fizzBuzz(50)
    0
    >>> fizzBuzz(78)
    2
    >>> fizzBuzz(79)
    3
     */
    public int fizzBuzz(int n) {
        return IntStream.range(0, n)
            .filter(i -> i % 11 == 0 || i % 13 == 0)
            .mapToInt(i -> countDigitSeven(i))
            .sum();
    }

    private int countDigitSeven(int num) {
        int count = 0;
        int n = Math.abs(num);
        while (n > 0) {
            if (n % 10 == 7) {
                count++;
            }
            n /= 10;
        }
        return count;
    }
}

