    >>> hasCloseElements(Arrays.asList(1.0, 2.0, 3.0), 0.5)
    false
    >>> hasCloseElements(Arrays.asList(1.0, 2.8, 3.0, 4.0, 5.0, 2.0), 0.3)
    true
     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        if (numbers == null || numbers.size() < 2) {
            return false;
        }

        // Sort the list to make adjacent elements the closest possible pairs
        List<Double> sorted = numbers.stream()
                                    .sorted()
                                    .toList();

        // Check if any adjacent pair has difference less than threshold
        for (int i = 0; i < sorted.size() - 1; i++) {
            if (Math.abs(sorted.get(i + 1) - sorted.get(i)) < threshold) {
                return true;
            }
        }

        return false;
    }
}

