class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        int sqrtN = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Use bisection method with expanding search range
        double left = -1000.0;
        double right = 1000.0;

        // Expand search range if needed
        while (true) {
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            // If signs are different, we have a bracket
            if (fLeft * fRight <= 0) {
                break;
            }

            // Expand the range
            left *= 2;
            right *= 2;

            // Safety limit to avoid infinite loop
            if (Math.abs(left) > 1e10) {
                // Fallback: try to find any root by checking common values
                for (double test = -10; test <= 10; test += 0.5) {
                    if (Math.abs(poly(xs, test)) < 1e-9) {
                        return test;
                    }
                }
                // If still not found, use midpoint as last resort
                return (left + right) / 2;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // sufficient iterations for double precision
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            double fLeft = poly(xs, left);
            if (fLeft * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Return midpoint if we haven't converged exactly
        return (left + right) / 2;
    }
}

