class Solution {
    public double findZero(List<Double> xs) {
        // Use bisection method
        double left = -1000.0;
        double right = 1000.0;

        // Expand interval until we find sign change
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 10;
            right *= 10;
            // Safety check to avoid infinite loops
            if (Math.abs(left) > 1e10) {
                // Fallback: try derivative-based Newton method or return 0
                return 0.0;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations should give good precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2.0;
    }
}

