class Solution {
    public double findZero(List<Double> xs) {
        // Try multiple starting points to increase chances of finding a root
        double[] startPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0, 0.5, -0.5};

        for (double startX : startPoints) {
            double x = startX;
            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, x);

                // Check if we're close enough to a root
                if (Math.abs(fx) < 1e-9) {
                    return x;
                }

                // Compute derivative
                double fpx = 0.0;
                for (int i = 1; i < xs.size(); i++) {
                    fpx += xs.get(i) * i * Math.pow(x, i - 1);
                }

                // Avoid division by zero or very small derivatives
                if (Math.abs(fpx) < 1e-9) {
                    break; // Try next starting point
                }

                double newX = x - fx / fpx;

                // Check for divergence or NaN
                if (Double.isNaN(newX) || Double.isInfinite(newX)) {
                    break; // Try next starting point
                }

                x = newX;
            }
        }

        // Fallback: try bisection between -1000 and 1000
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Look for sign change
        while (left < right) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Last resort: return midpoint of range
        return (left + right) / 2;
    }
}

