class Solution {
    /**
    Insert a number 'delimeter' between every two consecutive elements of input list `numbers'
    >>> intersperse(List.of(), 4)
    []
    >>> intersperse(Arrays.asList(1, 2, 3), 4)
    [1, 4, 2, 4, 3]
     */
    public List<Integer> intersperse(List<Integer> numbers, int delimiter) {
        if (numbers.isEmpty()) {
            return new ArrayList<>();
        }

        return numbers.stream()
                .flatMap(e -> {
                    // Create a stream with the element and possibly the delimiter
                    if (e == numbers.get(numbers.size() - 1)) {
                        // Last element: just return the element
                        return Stream.of(e);
                    } else {
                        // Not last element: return element followed by delimiter
                        return Stream.of(e, delimiter);
                    }
                })
                .toList();
    }
}

