            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For linear case (2 coefficients): ax + b = 0 => x = -b/a
        if (xs.size() == 2) {
            double b = xs.get(0);
            double a = xs.get(1);
            return -b / a;
        }

        // Newton-Raphson method
        double x = 0.0; // initial guess
        double tolerance = 1e-9;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative: f'(x)
            double dfx = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                dfx += i * xs.get(i) * Math.pow(x, i - 1);
            }

            // Avoid division by zero
            if (Math.abs(dfx) < 1e-12) {
                // Try perturbing x slightly
                x += 0.1;
                continue;
            }

            double xNext = x - fx / dfx;

            // Check for convergence
            if (Math.abs(xNext - x) < tolerance) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNext)) < tolerance) {
                    return xNext;
                }
            }

            x = xNext;
        }

        // Fallback: return current approximation
        return x;
    }
}

