class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: constant polynomial (degree 0)
        if (xs.size() == 1) {
            return 0.0; // or throw exception, but problem says even number of coefficients
        }

        // Find the degree (highest non-zero coefficient index)
        int degree = xs.size() - 1;

        // Check if leading coefficient is zero (shouldn't happen per problem statement, but be safe)
        double leadingCoeff = xs.get(degree);
        while (leadingCoeff == 0 && degree > 0) {
            degree--;
            leadingCoeff = xs.get(degree);
        }

        // For odd degree polynomials (even number of coefficients means odd degree),
        // there must be at least one real root

        // Use bisection method
        // First, find an interval [a, b] where f(a) * f(b) < 0

        double a = -1000.0;
        double b = 1000.0;
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Expand interval until we find sign change
        int attempts = 0;
        while (fa * fb >= 0 && attempts < 20) {
            a *= 10;
            b *= 10;
            fa = poly(xs, a);
            fb = poly(xs, b);
            attempts++;
        }

        // If still no sign change, return midpoint as fallback
        if (fa * fb >= 0) {
            return (a + b) / 2;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~30 decimal digits precision
            double mid = (a + b) / 2;
            double fmid = poly(xs, mid);

            if (Math.abs(fmid) < 1e-12) {
                return mid;
            }

            if (fa * fmid < 0) {
                b = mid;
                fb = fmid;
            } else {
                a = mid;
                fa = fmid;
            }
        }

        return (a + b) / 2;
    }
}

