import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Use bisection method with large bounds since we know a root exists
        double left = -1000.0;
        double right = 1000.0;

        // Expand bounds until we find opposite signs, if needed
        while (poly(xs, left) > 0 && poly(xs, right) > 0) {
            left *= 10;
            right *= 10;
        }
        while (poly(xs, left) < 0 && poly(xs, right) < 0) {
            left *= 10;
            right *= 10;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives very high precision
            double mid = (left + right) / 2.0;
            double valueAtMid = poly(xs, mid);

            if (Math.abs(valueAtMid) < 1e-12) {
                return mid;
            }

            double valueAtLeft = poly(xs, left);
            if (valueAtLeft * valueAtMid <= 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Fallback: return midpoint of final interval
        return (left + right) / 2.0;
    }
}

