class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Ensure both strings have the same length by padding the shorter one with leading zeros
        // According to the problem, we should assume they're the same length, but let's be safe
        int lenA = a.length();
        int lenB = b.length();
        int maxLen = Math.max(lenA, lenB);

        // Pad strings to same length with leading zeros
        StringBuilder sa = new StringBuilder(a);
        StringBuilder sb = new StringBuilder(b);

        while (sa.length() < maxLen) sa.insert(0, '0');
        while (sb.length() < maxLen) sb.insert(0, '0');

        StringBuilder result = new StringBuilder(maxLen);

        for (int i = 0; i < maxLen; i++) {
            char bitA = sa.charAt(i);
            char bitB = sb.charAt(i);

            // XOR: if bits are different, result is '1', otherwise '0'
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

