class Solution {
    public int howManyTimes(String string, String substring) {
        // Edge case: empty substring cannot be found
        if (substring.isEmpty()) {
            return 0;
        }

        int count = 0;
        int stringLen = string.length();
        int substrLen = substring.length();

        // If substring is longer than string, no matches possible
        if (substrLen > stringLen) {
            return 0;
        }

        // Check every possible starting position
        for (int i = 0; i <= stringLen - substrLen; i++) {
            if (string.substring(i, i + substrLen).equals(substring)) {
                count++;
            }
        }

        return count;
    }
}

