class Solution {
    public List<Double> rescaleToUnit(List<Double> numbers) {
        if (numbers == null || numbers.isEmpty()) {
            return new ArrayList<>();
        }

        // Find min and max values
        double min = Collections.min(numbers);
        double max = Collections.max(numbers);

        // Create result list
        List<Double> result = new ArrayList<>(numbers.size());

        // Handle edge case: if all values are the same
        if (min == max) {
            // All values are identical, map them all to 0.0 (or could be 0.5, but 0.0 is standard)
            for (int i = 0; i < numbers.size(); i++) {
                result.add(0.0);
            }
            return result;
        }

        // Apply min-max normalization to each element
        double range = max - min;
        for (Double num : numbers) {
            result.add((num - min) / range);
        }

        return result;
    }
}

