class Solution {
    public double findZero(List<Double> xs) {
        // Check that number of coefficients is even
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Find the highest degree non-zero coefficient to determine behavior
        int n = xs.size() - 1; // degree of polynomial
        int leadingIndex = -1;
        for (int i = n; i >= 0; i--) {
            if (!xs.get(i).equals(0.0)) {
                leadingIndex = i;
                break;
            }
        }

        // If all coefficients are zero, any x is a solution
        if (leadingIndex == -1) {
            return 0.0;
        }

        // Check if leading degree is odd (ensured by even number of coefficients)
        if (leadingIndex % 2 == 0) {
            throw new IllegalArgumentException("Leading degree must be odd to guarantee a solution");
        }

        // Binary search for root
        // For odd-degree polynomial, lim_{x->-inf} f(x) = -sign(a_n)*inf, lim_{x->+inf} f(x) = sign(a_n)*inf
        // So we can find a large enough interval where f changes sign

        double left = -1000.0;
        double right = 1000.0;

        // Expand interval until we find opposite signs
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 10;
            right *= 10;
            // Safety check to prevent infinite loop
            if (Math.abs(left) > 1e9) {
                // Fallback: try Newton's method or return 0
                return 0.0;
            }
        }

        // Binary search for root
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2.0;
    }
}

