class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special case: Fibonacci sequence starts with 0, 1, 1, ...
        // We'll check 2 (which is F(3)) onwards, but we need to check the early terms

        // Check F(3) = 2
        if (n == 1) {
            return 2;
        }

        // Start generating from F(3) = 2
        a = 1; // F(2)
        b = 2; // F(3)

        if (isPrime(b)) {
            count++;
            if (count == n) {
                return b;
            }
        }

        // Continue with rest of Fibonacci sequence
        while (true) {
            long next = a + b;
            a = b;
            b = next;

            if (isPrime(b)) {
                count++;
                if (count == n) {
                    return (int) b;
                }
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;

        // Check for divisibility by numbers of form 6k ± 1
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

