class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return 0; // or throw exception, but problem doesn't specify
        }

        // The largest proper divisor of n is at most n/2
        // We can find it by checking from n/2 downwards
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // This handles the case when n=1, though n<=1 should be handled above
    }
}

