            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    Derivative of polynomial at point x
     */
    private double polyDeriv(List<Double> xs, double x) {
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += xs.get(i) * i * Math.pow(x, i - 1);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Check even number of coefficients
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Find highest-degree non-zero coefficient
        int degree = xs.size() - 1;
        while (degree >= 0 && Math.abs(xs.get(degree)) < 1e-15) {
            degree--;
        }

        // Must have at least degree 1 (since even # of coefficients, minimum is 2 → degree 1)
        if (degree < 1) {
            throw new IllegalArgumentException("Polynomial must have degree at least 1");
        }

        // For odd-degree polynomials, we know there's at least one real root
        // Try Newton-Raphson with multiple starting points
        double[] starts = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0, 0.5, -0.5};

        for (double start : starts) {
            double root = newtonRaphson(xs, start, 100, 1e-12);
            if (!Double.isNaN(root) && !Double.isInfinite(root)) {
                if (Math.abs(poly(xs, root)) < 1e-8) {
                    return root;
                }
            }
        }

        // Fallback to bisection method
        // Find an interval [a, b] where sign changes
        double a = -100.0;
        double b = 100.0;

        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Expand interval if needed
        int attempts = 0;
        while (fa * fb > 0 && attempts < 10) {
            a *= 10;
            b *= 10;
            fa = poly(xs, a);
            fb = poly(xs, b);
            attempts++;
        }

        if (fa * fb <= 0) {
            return bisection(xs, a, b, 1e-12);
        }

        // Last resort: return NaN or throw exception
        throw new RuntimeException("Could not find a root");
    }

    private double newtonRaphson(List<Double> xs, double x0, int maxIter, double tol) {
        double x = x0;
        for (int i = 0; i < maxIter; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < tol) {
                return x;
            }

            double fpx = polyDeriv(xs, x);
            if (Math.abs(fpx) < 1e-15) {
                return Double.NaN; // Derivative too small
            }

            double xNext = x - fx / fpx;
            if (Double.isInfinite(xNext) || Double.isNaN(xNext)) {
                return Double.NaN;
            }

            if (Math.abs(xNext - x) < tol) {
                return xNext;
            }

            x = xNext;
        }
        return x;
    }

    private double bisection(List<Double> xs, double a, double b, double tol) {
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        if (fa * fb > 0) {
            return Double.NaN;
        }

        while ((b - a) > tol) {
            double c = (a + b) / 2;
            double fc = poly(xs, c);

            if (Math.abs(fc) < tol) {
                return c;
            }

            if (fa * fc < 0) {
                b = c;
                fb = fc;
            } else {
                a = c;
                fa = fc;
            }
        }

        return (a + b) / 2;
    }
