class Solution {
    /**
    Out of list of strings, return the longest one. Return the first one in case of multiple
    strings of the same length. Return None in case the input list is empty.
    >>> longest(List.of())
    Optional.empty
    >>> longest(Arrays.asList("a", "b", "c"))
    Optional[a]
    >>> longest(Arrays.asList("a", "bb", "ccc"))
    Optional[ccc]
     */
    public Optional<String> longest(List<String> strings) {
        if (strings.isEmpty()) {
            return Optional.empty();
        }

        return strings.stream()
                .max((s1, s2) -> {
                    int lenDiff = s2.length() - s1.length();
                    if (lenDiff != 0) {
                        return lenDiff;
                    }
                    // If lengths are equal, prefer the first occurrence (lower index)
                    // Since max() processes elements in encounter order and keeps the first
                    // maximum found, we return 0 for equal lengths to maintain stability
                    return 0;
                });
    }
}

