    5
     */
    public int largestDivisor(int n) {
        if (n <= 1) {
            return 0; // or throw exception, but assuming n >= 2 based on example
        }

        // Check for smallest divisor from 2 to sqrt(n)
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                // Found smallest divisor i, so n/i is largest proper divisor
                return n / i;
            }
        }

        // If no divisor found, n is prime, so largest proper divisor is 1
        return 1;
    }
}

