class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For odd degree polynomials (even number of coefficients), 
        // there's always at least one real root

        // Set initial bounds where we expect a sign change
        double left = -1000.0;
        double right = 1000.0;
        double mid;

        // Expand bounds until we find a sign change
        while (poly(xs, left) > 0 || poly(xs, right) < 0) {
            left *= 2;
            right *= 2;
            // Safety limit to avoid infinite loops
            if (Math.abs(left) > 1e9) {
                break;
            }
        }

        // Now apply bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives good precision
            mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2;
    }
}

