    >>> intersperse(List.of(), 4)
    []
    >>> intersperse(Arrays.asList(1, 2, 3), 4)
    [1, 4, 2, 4, 3]
     */
    public List<Integer> intersperse(List<Integer> numbers, int delimiter) {
        // Handle empty list case
        if (numbers.isEmpty()) {
            return new ArrayList<>();
        }

        // Handle single element case - no delimiters needed
        if (numbers.size() == 1) {
            return new ArrayList<>(numbers);
        }

        // Create result list with appropriate capacity
        // For n elements, we'll have n + (n-1) = 2n - 1 elements
        List<Integer> result = new ArrayList<>(2 * numbers.size() - 1);

        // Add first element
        result.add(numbers.get(0));

        // Add remaining elements with delimiter before each
        for (int i = 1; i < numbers.size(); i++) {
            result.add(delimiter);
            result.add(numbers.get(i));
        }

        return result;
    }
}

