class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Validate even number of coefficients
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Find the largest non-zero coefficient to determine scaling
        double maxCoeff = 0;
        for (double coeff : xs) {
            if (Math.abs(coeff) > maxCoeff) {
                maxCoeff = Math.abs(coeff);
            }
        }

        // If all coefficients are zero, any x is a solution
        if (maxCoeff == 0) {
            return 0.0;
        }

        // Derivative coefficients
        List<Double> derivative = new ArrayList<>();
        for (int i = 1; i < xs.size(); i++) {
            derivative.add(xs.get(i) * i);
        }

        // Newton's method with multiple starting points
        double[] initialGuesses = {0.0, 1.0, -1.0, 2.0, -2.0, 0.5, -0.5, 10.0, -10.0};

        for (double x0 : initialGuesses) {
            double x = x0;
            for (int iteration = 0; iteration < 100; iteration++) {
                double fx = poly(xs, x);

                // Check if we found a root
                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                // Compute derivative at x
                double fpx = poly(derivative, x);

                // Avoid division by zero
                if (Math.abs(fpx) < 1e-12) {
                    // Try a small perturbation
                    x += 0.01;
                    continue;
                }

                double xNew = x - fx / fpx;

                // Check for convergence
                if (Math.abs(xNew - x) < 1e-10) {
                    if (Math.abs(poly(xs, xNew)) < 1e-8) {
                        return xNew;
                    }
                }

                // Limit x to reasonable range to avoid overflow
                if (Double.isInfinite(xNew) || Double.isNaN(xNew) || Math.abs(xNew) > 1e6) {
                    break;
                }

                x = xNew;
            }
        }

        // Fallback: try bisection method on intervals
        // Check intervals around the origin and scaled by maxCoeff
        double scale = Math.max(1.0, maxCoeff);
        for (double left = -scale * 10; left < scale * 10; left += scale) {
            double right = left + scale;
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            if (fLeft * fRight <= 0) {
                // Bisection method
                for (int i = 0; i < 50; i++) {
                    double mid = (left + right) / 2;
                    double fMid = poly(xs, mid);

                    if (Math.abs(fMid) < 1e-10) {
                        return mid;
                    }

                    if (fLeft * fMid <= 0) {
                        right = mid;
                    } else {
                        left = mid;
                        fLeft = fMid;
                    }
                }
                return (left + right) / 2;
            }
        }

        // Last resort: return the best approximation found
        double bestX = 0;
        double bestError = Double.MAX_VALUE;
        for (double x = -10; x <= 10; x += 0.1) {
            double error = Math.abs(poly(xs, x));
            if (error < bestError) {
                bestError = error;
                bestX = x;
            }
        }
        return bestX;
    }
}

