class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F0
        long b = 1; // F1

        // Handle special case: if n=1, we need the first prime Fibonacci
        // Start generating Fibonacci numbers from the beginning
        while (count < n) {
            long next = a + b;
            a = b;
            b = next;

            // Check if current Fibonacci number (a) is prime
            // Skip 0 and 1 as they are not prime
            if (a > 1 && isPrime(a)) {
                count++;
                if (count == n) {
                    return (int) a;
                }
            }
        }

        // Should never reach here for valid input
        throw new RuntimeException("Failed to find prime Fibonacci number");
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0) return false;

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

