    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Find the highest degree coefficient (leading coefficient)
        int n = xs.size();
        int leadingIdx = -1;
        for (int i = n - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-15) {
                leadingIdx = i;
                break;
            }
        }

        if (leadingIdx == -1) {
            throw new IllegalArgumentException("All coefficients are zero");
        }

        // For polynomials of odd degree (even number of coefficients means odd degree)
        // There must be at least one real root

        // Try Newton-Raphson first with multiple starting points
        double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

        for (double start : startingPoints) {
            double root = newtonRaphson(xs, start, leadingIdx);
            if (!Double.isNaN(root) && !Double.isInfinite(root) && Math.abs(poly(xs, root)) < 1e-9) {
                return root;
            }
        }

        // If Newton-Raphson fails, use bisection method
        // Find interval [a, b] where f(a)*f(b) < 0
        double a = -100.0;
        double b = 100.0;
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Expand search range if needed
        while (fa * fb > 0 && Math.abs(a) < 1e6) {
            a *= 2;
            b *= 2;
            fa = fb;
            fb = poly(xs, b);
        }

        if (fa * fb > 0) {
            // Last resort: use bisection on a reasonable range
            a = -1000.0;
            b = 1000.0;
        }

        return bisection(xs, a, b);
    }

    private double newtonRaphson(List<Double> xs, double start, int leadingIdx) {
        double x = start;
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative
            double fpx = 0;
            for (int j = 1; j <= leadingIdx; j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(fpx) < 1e-15) {
                return Double.NaN; // Derivative too small
            }

            double xNext = x - fx / fpx;

            // Check for divergence
            if (Double.isNaN(xNext) || Double.isInfinite(xNext) || Math.abs(xNext - x) > 1e6) {
                return Double.NaN;
            }

            x = xNext;
        }

        // Check if we found a root
        if (Math.abs(poly(xs, x)) < 1e-9) {
            return x;
        }
        return Double.NaN;
    }

    private double bisection(List<Double> xs, double a, double b) {
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Ensure fa and fb have opposite signs
        if (fa * fb > 0) {
            // Try to find a better interval
            for (double x = a; x <= b; x += 1.0) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < 1e-12) return x;
                if (fx * fa < 0) {
                    b = x;
                    fb = fx;
                    break;
                }
            }
        }

        for (int i = 0; i < 100; i++) {
            double mid = (a + b) / 2;
            double fmid = poly(xs, mid);

            if (Math.abs(fmid) < 1e-12 || (b - a) < 1e-12) {
                return mid;
            }

            if (fa * fmid < 0) {
                b = mid;
                fb = fmid;
            } else {
                a = mid;
                fa = fmid;
            }
        }

        return (a + b) / 2;
    }
}

