class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 1, b = 1; // First two Fibonacci numbers

        // Handle special case for small numbers
        if (n == 1) return 2;

        while (true) {
            long fib = a;

            // Skip 1 (not prime), start checking from 2
            if (fib > 1 && isPrime(fib)) {
                count++;
                if (count == n) {
                    return (int) fib;
                }
            }

            // Generate next Fibonacci number
            long temp = a + b;
            a = b;
            b = temp;
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0) return false;

        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

