class Solution {
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true; // 2 and 3 are prime
        }

        // Eliminate even numbers and multiples of 3
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        // We only need to check numbers of form 6k±1 (which covers all primes > 3)
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Use Horner's method for better numerical stability and efficiency
        double result = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Use Horner's method helper for derivative
        // For polynomial a0 + a1*x + ... + an*x^n, derivative is a1 + 2*a2*x + ... + n*an*x^(n-1)

        // Find bounds for root search
        double maxRatio = 0;
        double leadingCoeff = xs.get(xs.size() - 1);
        for (int i = 0; i < xs.size() - 1; i++) {
            double coeff = Math.abs(xs.get(i));
            double ratio = coeff / Math.abs(leadingCoeff);
            if (ratio > maxRatio) {
                maxRatio = ratio;
            }
        }
        double bound = 1 + maxRatio;

        // Try Newton-Raphson first with multiple starting points
        for (double startX = -bound; startX <= bound; startX += bound / 5.0) {
            double result = newtonRaphson(xs, startX);
            if (Math.abs(poly(xs, result)) < 1e-9) {
                return result;
            }
        }

        // Fallback to bisection if Newton-Raphson fails
        return bisect(xs, -bound, bound);
    }

    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 100; i++) { // max iterations
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            double fxPrime = polyDerivative(xs, x);
            if (Math.abs(fxPrime) < 1e-12) {
                // Derivative too small, try different approach
                return x; // or break and try bisection
            }

            double xNext = x - fx / fxPrime;

            // Check for divergence
            if (Double.isNaN(xNext) || Double.isInfinite(xNext) || Math.abs(xNext - x) > 1e10) {
                return x0; // give up and return start point
            }

            x = xNext;
        }
        return x;
    }

    private double polyDerivative(List<Double> xs, double x) {
        // derivative of a0 + a1*x + a2*x^2 + ... + an*x^n is a1 + 2*a2*x + 3*a3*x^2 + ... + n*an*x^(n-1)
        if (xs.size() <= 1) {
            return 0;
        }

        // Build derivative coefficients: [a1, 2*a2, 3*a3, ..., n*an]
        List<Double> derivCoeffs = new ArrayList<>();
        for (int i = 1; i < xs.size(); i++) {
            derivCoeffs.add((double)i * xs.get(i));
        }

        return poly(derivCoeffs, x);
    }

    private double bisect(List<Double> xs, double a, double b) {
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Ensure we have opposite signs
        if (fa * fb > 0) {
            // If same sign, try to find an interval with opposite signs
            for (double x = a; x <= b; x += (b - a) / 100.0) {
                double f = poly(xs, x);
                if (f * fa <= 0) {
                    return x; // found a root or close to it
                }
            }
            return a;
        }

        for (int i = 0; i < 100; i++) {
            double mid = (a + b) / 2;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < 1e-12 || (b - a) < 1e-12) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }
        return (a + b) / 2;
    }
}

