            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 1, b = 1; // First two Fibonacci numbers

        // Handle special case: we need to check if 2 is prime (it is)
        // But Fibonacci sequence starts with 1, 1, 2, 3, 5...
        // So we need to generate until we find enough primes

        while (true) {
            // Generate next Fibonacci number
            long next = a + b;
            a = b;
            b = next;

            // Check if this Fibonacci number is prime
            if (isPrime(next)) {
                count++;
                if (count == n) {
