                }
            }

            // Edge case: handle the first few Fibonacci numbers properly
            // When we start, we have a=1, b=1, then next=2
            // We should also check if 2 is included - let's trace through

            // Actually, let's fix the initialization to handle all cases
            // Fibonacci sequence: F1=1, F2=1, F3=2, F4=3, F5=5, F6=8, F7=13, F8=21, F9=34, F10=55, F11=89...

            // Since the examples show primeFib(1)=2, we need to find 2 first
            // Let me adjust the logic to check 2 explicitly or restructure

            // Better approach: use a loop that generates Fibonacci numbers sequentially
            // and checks primality
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
