class Solution {
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return -1; // or throw exception, but problem implies n > 1
        }

        // If n is even, largest proper divisor is n/2
        if (n % 2 == 0) {
            return n / 2;
        }

        // For odd numbers, find the smallest divisor >= 3
        // We only need to check up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return n / i;
            }
        }

        // If we get here, n is prime, so largest proper divisor is 1
        return 1;
    }
}

