class Solution {
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        // Exclude even numbers greater than 2
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For safety, handle degenerate case (all zeros?) — but problem says largest non-zero coefficient exists
        // Use bisection method on a sufficiently large interval
        double low = -1000.0;
        double high = 1000.0;

        // Ensure we have a sign change: expand interval if needed
        double fLow = poly(xs, low);
        double fHigh = poly(xs, high);

        // If same sign, expand interval
        int attempts = 0;
        while (fLow * fHigh > 0 && attempts < 30) {
            low *= 2;
            high *= 2;
            fLow = poly(xs, low);
            fHigh = poly(xs, high);
            attempts++;
        }

        // Now bisection
        for (int i = 0; i < 100; i++) {  // enough iterations for double precision
            double mid = (low + high) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLow * fMid <= 0) {
                high = mid;
                fHigh = fMid;
            } else {
                low = mid;
                fLow = fMid;
            }
        }

        return (low + high) / 2.0;
    }
}

