class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 1, b = 1; // First two Fibonacci numbers

        // Handle special case: check if 2 is needed
        while (true) {
            long next = a + b;
            a = b;
            b = next;

            // Skip 1 (not prime)
            if (b == 1) {
                continue;
            }

            // Check if b is prime
            if (isPrime(b)) {
                count++;
                if (count == n) {
                    return (int) b;
                }
            }

            // Prevent overflow - Fibonacci numbers grow exponentially
            if (b < 0) {
                throw new ArithmeticException("Overflow occurred");
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

