class Solution {
    /**
    Check if in given list of numbers, are any two numbers closer to each other than given threshold.
    >>> hasCloseElements(Arrays.asList(1.0, 2.0, 3.0), 0.5)
    false
    >>> hasCloseElements(Arrays.asList(1.0, 2.8, 3.0, 4.0, 5.0, 2.0), 0.3)
    true
     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        // Check parameters for validity
        if (numbers == null) {
            throw new IllegalArgumentException("List of numbers cannot be null");
        }
        if (threshold < 0) {
            throw new IllegalArgumentException("Threshold cannot be negative");
        }

        // If there are fewer than 2 elements, no pair exists
        if (numbers.size() < 2) {
            return false;
        }

        // Sort the list to efficiently check adjacent elements
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        // Check adjacent pairs only - the minimum distance between any two elements
        // in a sorted list will be between some pair of adjacent elements
        for (int i = 0; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < threshold) {
                return true;
            }
        }

        return false;
    }
}

