class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        // Check for null input
        if (numbers == null) {
            throw new IllegalArgumentException("Input cannot be null");
        }

        // Trim and check for empty string
        String trimmed = numbers.trim();
        if (trimmed.isEmpty()) {
            return "";
        }

        // Split by spaces
        String[] tokens = trimmed.split("\\s+");

        // Map number words to their numeric values
        Map<String, Integer> numberMap = new HashMap<>();
        numberMap.put("zero", 0);
        numberMap.put("one", 1);
        numberMap.put("two", 2);
        numberMap.put("three", 3);
        numberMap.put("four", 4);
        numberMap.put("five", 5);
        numberMap.put("six", 6);
        numberMap.put("seven", 7);
        numberMap.put("eight", 8);
        numberMap.put("nine", 9);

        // Validate each token and collect valid numbers
        List<String> validTokens = new ArrayList<>();
        for (String token : tokens) {
            if (!numberMap.containsKey(token)) {
                throw new IllegalArgumentException("Invalid number word: '" + token + "'");
            }
            validTokens.add(token);
        }

        // Sort based on numeric value
        Collections.sort(validTokens, (a, b) -> {
            return numberMap.get(a) - numberMap.get(b);
        });

        // Join back into a space-delimited string
        return String.join(" ", validTokens);
    }
}

