class Solution {
    public double findZero(List<Double> xs) {
        // Check parameters for validity (Item 49)
        if (xs == null) {
            throw new IllegalArgumentException("Coefficient list cannot be null");
        }
        if (xs.size() < 2 || xs.size() % 2 != 0) {
            throw new IllegalArgumentException("Coefficient list must have even number of elements (at least 2)");
        }

        // Check if all coefficients are zero (would be degenerate case)
        boolean allZero = true;
        for (Double coef : xs) {
            if (coef != null && Math.abs(coef) > 1e-15) {
                allZero = false;
                break;
            }
        }
        if (allZero) {
            return 0.0; // Any x works, but 0 is simplest
        }

        // Use bisection method with expanding search range
        double low = -1000.0;
        double high = 1000.0;

        // Expand search range until we find a sign change
        while (low > -1e6) {
            double fLow = poly(xs, low);
            double fHigh = poly(xs, high);

            if (fLow == 0) return low;
            if (fHigh == 0) return high;
            if (fLow * fHigh < 0) {
                // Sign change found, apply bisection
                return bisection(xs, low, high);
            }

            // Expand search range
            low *= 2;
            high *= 2;
        }

        // Fallback: use Newton-Raphson from 0
        return newtonRaphson(xs, 0.0);
    }

    private double bisection(List<Double> xs, double a, double b) {
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Ensure fa and fb have opposite signs
        if (fa * fb > 0) {
            return Double.NaN; // Shouldn't happen if called correctly
        }

        // Bisection iterations
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~2^-100 precision
            double mid = (a + b) / 2.0;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < 1e-12 || (b - a) < 1e-12) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2.0;
    }

    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative numerically
            double h = 1e-8;
            double fpx = (poly(xs, x + h) - poly(xs, x - h)) / (2 * h);

            if (Math.abs(fpx) < 1e-15) {
                // Derivative too small, try different starting point
                x += 1.0;
                continue;
            }

            double xNew = x - fx / fpx;

            if (Double.isNaN(xNew) || Double.isInfinite(xNew)) {
                x += 1.0;
                continue;
            }

            x = xNew;
        }
        return x;
    }
}

