        // Find maximum element
        Integer max = l.get(0);
        for (Integer num : l) {
            // Skip null elements within the list (optional defensive programming)
            if (num == null) {
                throw new IllegalArgumentException("List contains null elements");
            }
            if (num > max) {
                max = num;
            }
        }

        return max;
    }
}

