class Solution {
    /**
    Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13.
    >>> fizzBuzz(50)
    0
    >>> fizzBuzz(78)
    2
    >>> fizzBuzz(79)
    3
     */
    public int fizzBuzz(int n) {
        // Validate parameter: n should be non-negative
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }

        int count = 0;

        // Check all integers from 1 to n-1 (and possibly 0, but 0 has no digit 7)
        for (int i = 1; i < n; i++) {
            // Check if divisible by 11 or 13
            if (i % 11 == 0 || i % 13 == 0) {
                // Count occurrences of digit 7 in i
                int num = i;
                while (num > 0) {
                    if (num % 10 == 7) {
                        count++;
                    }
                    num /= 10;
                }
            }
        }

        return count;
    }
}

