class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        // Check parameters for validity - n must be positive
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive, got: " + n);
        }

        int count = 0;
        int a = 0;  // First Fibonacci number F0
        int b = 1;  // Second Fibonacci number F1

        // Handle special case: F1 = 1 is not prime, F2 = 1 is not prime, F3 = 2 is prime
        while (true) {
            int next = a + b;
            a = b;
            b = next;

            if (isPrime(b)) {
                count++;
                if (count == n) {
                    return b;
                }
            }
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        int sqrt = (int) Math.sqrt(num);
        for (int i = 3; i <= sqrt; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

