class Solution {
    /**
    Check if in given list of numbers, are any two numbers closer to each other than given threshold.
    >>> hasCloseElements(Arrays.asList(1.0, 2.0, 3.0), 0.5)
    false
    >>> hasCloseElements(Arrays.asList(1.0, 2.8, 3.0, 4.0, 5.0, 2.0), 0.3)
    true
     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        // Check for null parameters using Objects.requireNonNull as per best practices
        numbers = Objects.requireNonNull(numbers, "numbers");

        // If threshold is negative, no pair can be closer than a negative distance
        if (threshold < 0) {
            return false;
        }

        // If list has fewer than 2 elements, no pairs exist
        if (numbers.size() < 2) {
            return false;
        }

        // Check all pairs of numbers
        for (int i = 0; i < numbers.size(); i++) {
            for (int j = i + 1; j < numbers.size(); j++) {
                double diff = Math.abs(numbers.get(i) - numbers.get(j));
                if (diff < threshold) {
                    return true;
                }
            }
        }

        return false;
    }
}

