class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Validate inputs are non-null (using Objects.requireNonNull as per best practices)
        a = Objects.requireNonNull(a, "First string cannot be null");
        b = Objects.requireNonNull(b, "Second string cannot be null");

        // Check that strings have equal length
        if (a.length() != b.length()) {
            throw new IllegalArgumentException("Binary strings must have equal length: " + 
                                             "length1=" + a.length() + ", length2=" + b.length());
        }

        StringBuilder result = new StringBuilder(a.length());

        // Perform XOR operation character by character
        for (int i = 0; i < a.length(); i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            // Validate that characters are only '0' or '1'
            if ((bitA != '0' && bitA != '1') || (bitB != '0' && bitB != '1')) {
                throw new IllegalArgumentException("Strings must contain only '0' and '1' characters");
            }

            // XOR: same bits give 0, different bits give 1
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

