            return "";
        }

        // Split by spaces and filter out empty strings
        String[] words = numbers.trim().split("\\s+");

        // Create mapping from word to digit value
        Map<String, Integer> wordToDigit = new HashMap<>();
        wordToDigit.put("zero", 0);
        wordToDigit.put("one", 1);
        wordToDigit.put("two", 2);
        wordToDigit.put("three", 3);
        wordToDigit.put("four", 4);
        wordToDigit.put("five", 5);
        wordToDigit.put("six", 6);
        wordToDigit.put("seven", 7);
        wordToDigit.put("eight", 8);
        wordToDigit.put("nine", 9);

        // Validate each word and collect valid ones
        List<String> validWords = new ArrayList<>();
        for (String word : words) {
            String lowerWord = word.toLowerCase();
            if (!wordToDigit.containsKey(lowerWord)) {
                throw new IllegalArgumentException("Invalid number word: '" + word + "'. Valid words are: zero, one, two, three, four, five, six, seven, eight, nine.");
            }
            validWords.add(word); // Keep original casing
        }

        // Sort based on numeric value
        validWords.sort(Comparator.comparing(word -> wordToDigit.get(word.toLowerCase())));

        // Join back into string
        return String.join(" ", validWords);
    }
}

