class Solution {
    /**
    Return list of prime factors of given integer in the order from smallest to largest.
    Each of the factors should be listed number of times corresponding to how many times it appeares in factorization.
    Input number should be equal to the product of all factors
    >>> factorize(8)
    [2, 2, 2]
    >>> factorize(25)
    [5, 5]
    >>> factorize(70)
    [2, 5, 7]
     */
    public List<Integer> factorize(int n) {
        // Validate input - prime factorization is typically defined for n >= 2
        if (n < 2) {
            if (n <= 0) {
                throw new IllegalArgumentException("Input must be positive integer greater than or equal to 2");
            }
            // n == 1 has no prime factors, return empty list
            return new ArrayList<>();
        }

        List<Integer> factors = new ArrayList<>();

        // Check for factor 2 separately to optimize odd number checking later
        while (n % 2 == 0) {
            factors.add(2);
            n /= 2;
        }

        // Check for odd factors starting from 3
        for (int i = 3; i * i <= n; i += 2) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }

        // If n is still greater than 1, then it's a prime factor
        if (n > 1) {
            factors.add(n);
        }

        return factors;
    }
}

