class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Validate input
        if (xs == null) {
            throw new IllegalArgumentException("Coefficients list cannot be null");
        }

        double result = 0;
        double xPower = 1;
        for (int i = 0; i < xs.size(); i++) {
            Double coeff = xs.get(i);
            if (coeff != null) {
                result += coeff * xPower;
            }
            xPower *= x;
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Validate inputs
        if (xs == null || xs.size() < 2 || xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients >= 2");
        }

        // Check if all coefficients are zero (edge case)
        boolean allZero = true;
        for (Double coeff : xs) {
            if (coeff != null && Math.abs(coeff) > 1e-15) {
                allZero = false;
                break;
            }
        }
        if (allZero) {
            return 0.0; // Any x works, return 0
        }

        // Use Newton-Raphson method
        double x = 1.0; // Initial guess

        for (int iteration = 0; iteration < 100; iteration++) {
            double fx = poly(xs, x);

            // Check if we're close enough to zero
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative: f'(x) = sum(i * xs[i] * x^(i-1))
            double fpx = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                Double coeff = xs.get(i);
                if (coeff != null && Math.abs(coeff) > 1e-15) {
                    fpx += i * coeff * Math.pow(x, i - 1);
                }
            }

            // Handle case where derivative is zero (avoid division by zero)
            if (Math.abs(fpx) < 1e-15) {
                // Try a different initial guess or perturb x
                x += 0.1;
                continue;
            }

            double xNew = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNew - x) < 1e-12) {
                return xNew;
            }

            x = xNew;
        }

        // Return best approximation after max iterations
        return x;
    }
}

