class Solution {
    /**
    Check if in given list of numbers, are any two numbers closer to each other than given threshold.
    >>> hasCloseElements(Arrays.asList(1.0, 2.0, 3.0), 0.5)
    false
    >>> hasCloseElements(Arrays.asList(1.0, 2.8, 3.0, 4.0, 5.0, 2.0), 0.3)
    true
     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        // Check parameters for validity
        Objects.requireNonNull(numbers, "numbers list cannot be null");

        // Threshold can be negative, zero, or positive - all are valid
        // But if threshold is negative, no two numbers can be "closer" than a negative value
        if (threshold < 0) {
            return false;
        }

        // Need at least 2 elements to form a pair
        if (numbers.size() < 2) {
            return false;
        }

        // Create a copy to avoid modifying the original list
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        // Check adjacent pairs only (since sorted, min distance must be between adjacent elements)
        for (int i = 0; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < threshold) {
                return true;
            }
        }

        return false;
    }
}

