class Solution {
    /**
    Return a greatest common divisor of two integers a and b
    >>> greatestCommonDivisor(3, 5)
    1
    >>> greatestCommonDivisor(25, 15)
    5
     */
    public int greatestCommonDivisor(int a, int b) {
        // Handle negative numbers by taking absolute values
        // GCD is always non-negative
        a = Math.abs(a);
        b = Math.abs(b);

        // Handle edge cases where one or both inputs are 0
        // GCD(a, 0) = |a| and GCD(0, b) = |b|
        if (a == 0) return b;
        if (b == 0) return a;

        // Euclidean algorithm
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }

        return a;
    }
}

