class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Check for invalid inputs: numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // Handle 2 separately (it's the only even prime)
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        // We only need to check up to sqrt(n) because if n = a*b and a <= b,
        // then a <= sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        if (xs == null || xs.isEmpty()) {
            throw new IllegalArgumentException("Coefficient list cannot be null or empty");
        }

        double result = 0;
        double xPower = 1; // x^0 = 1
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * xPower;
            xPower *= x;
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Check parameters for validity
        if (xs == null) {
            throw new IllegalArgumentException("Coefficients cannot be null");
        }
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("Number of coefficients must be even");
        }
        if (xs.size() < 2) {
            throw new IllegalArgumentException("Need at least 2 coefficients");
        }

        // Remove trailing zeros from coefficients (highest degree terms)
        // Find the actual degree
        int degree = xs.size() - 1;
        while (degree > 0 && Math.abs(xs.get(degree)) < 1e-15) {
            degree--;
        }

        // If after removing zeros, we have even degree (odd number of remaining coefficients),
        // this contradicts the guarantee, but handle gracefully
        if (degree == 0) {
            // Constant polynomial: xs[0] = 0, any x is solution, return 0
            return 0.0;
        }

        // Use Newton-Raphson method with multiple starting points
        // Or use bisection with automatic bracketing

        // Try to find an interval [a, b] where f(a)*f(b) < 0
        double a = -1000.0;
        double b = 1000.0;
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // If the signs are the same, expand the interval
        int attempts = 0;
        while (fa * fb > 0 && attempts < 30) {
            a *= 10;
            b *= 10;
            fa = poly(xs, a);
            fb = poly(xs, b);
            attempts++;
        }

        // If still same sign, try different approach - use Newton's method
        if (fa * fb > 0) {
            // Use Newton-Raphson with multiple starting points
            for (double x0 : new double[]{-10, -1, 0, 1, 10}) {
                double root = newtonRaphson(xs, x0);
                if (Math.abs(poly(xs, root)) < 1e-9) {
                    return root;
                }
            }
            // Fallback: try bisection on [0, 1] if possible
            double f0 = poly(xs, 0);
            double f1 = poly(xs, 1);
            if (f0 * f1 <= 0) {
                return bisection(xs, 0, 1);
            }
            // Last resort: return 0
            return 0.0;
        }

        // Use bisection method
        return bisection(xs, a, b);
    }

    // Bisection method
    private double bisection(List<Double> xs, double a, double b) {
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        if (fa * fb > 0) {
            throw new IllegalArgumentException("No root found in interval [" + a + ", " + b + "]");
        }

        for (int i = 0; i < 100; i++) { // 100 iterations gives ~1e-30 precision
            double mid = (a + b) / 2;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < 1e-12) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2;
    }

    // Newton-Raphson method
    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative
            double dfx = derivative(xs, x);
            if (Math.abs(dfx) < 1e-12) {
                // Derivative too small, try small perturbation
                x += 0.001;
                continue;
            }

            double xNew = x - fx / dfx;

            if (Double.isNaN(xNew) || Double.isInfinite(xNew)) {
                return x; // fallback
            }

            x = xNew;
        }
        return x;
    }

    // Evaluate derivative of polynomial at x
    private double derivative(List<Double> xs, double x) {
        if (xs.size() <= 1) {
            return 0;
        }

        double result = 0;
        double xPower = 1; // x^0 = 1
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * xPower;
            xPower *= x;
        }
        return result;
    }
}

