class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        // Check parameters for validity - n must be positive
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive: " + n);
        }

        int count = 0;
        int a = 0; // F(0)
        int b = 1; // F(1)

        // Handle special case for n=1 (first Fibonacci prime is 2)
        if (n == 1) {
            return 2;
        }

        // Generate Fibonacci numbers and check for primality
        while (count < n) {
            int next = a + b;
            a = b;
            b = next;

            // Skip 0 and 1 as they are not prime
            if (next > 1 && isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }
        }

        // Should never reach here if n is valid
        throw new IllegalStateException("Failed to find nth Fibonacci prime");
    }

    // Helper method to check if a number is prime
    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

