class Solution {
    /**
    For a given list of input numbers, calculate Mean Absolute Deviation
    around the mean of this dataset.
    Mean Absolute Deviation is the average absolute difference between each
    element and a centerpoint (mean in this case):
    MAD = average | x - x_mean |
    >>> meanAbsoluteDeviation(Arrays.asList(1.0, 2.0, 3.0, 4.0))
    1.0
     */
    public double meanAbsoluteDeviation(List<Double> numbers) {
        // Explicit validity check: ensure list is not null
        if (numbers == null) {
            throw new IllegalArgumentException("Input list cannot be null");
        }

        // Explicit validity check: ensure list is not empty
        if (numbers.isEmpty()) {
            throw new IllegalArgumentException("Input list cannot be empty");
        }

        // Calculate the mean
        double sum = 0.0;
        for (Double num : numbers) {
            // Check for null elements in the list
            if (num == null) {
                throw new IllegalArgumentException("List cannot contain null elements");
            }
            sum += num;
        }
        double mean = sum / numbers.size();

        // Calculate the sum of absolute deviations from the mean
        double absSum = 0.0;
        for (Double num : numbers) {
            absSum += Math.abs(num - mean);
        }

        // Return the mean absolute deviation
        return absSum / numbers.size();
    }
}

