            throw new IllegalArgumentException("Input strings cannot be null");
        }

        // If substring is empty, return 0 to avoid infinite loop
        if (substring.isEmpty()) {
            return 0;
        }

        // If substring is longer than string, no matches possible
        if (substring.length() > string.length()) {
            return 0;
