class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        // Handle null or empty input
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        // Split the input string by spaces
        String[] words = numbers.trim().split("\\s+");

        // Create mapping from word to numeric value
        Map<String, Integer> numberMap = new HashMap<>();
        numberMap.put("zero", 0);
        numberMap.put("one", 1);
        numberMap.put("two", 2);
        numberMap.put("three", 3);
        numberMap.put("four", 4);
        numberMap.put("five", 5);
        numberMap.put("six", 6);
        numberMap.put("seven", 7);
        numberMap.put("eight", 8);
        numberMap.put("nine", 9);

        // Validate each word and convert to integers
        List<Integer> numericValues = new ArrayList<>();
        for (String word : words) {
            if (!numberMap.containsKey(word)) {
                throw new IllegalArgumentException("Invalid number word: '" + word + "'");
            }
            numericValues.add(numberMap.get(word));
        }

        // Sort the numeric values
        Collections.sort(numericValues);

        // Convert back to words and join with spaces
        List<String> sortedWords = new ArrayList<>();
        for (Integer val : numericValues) {
            for (Map.Entry<String, Integer> entry : numberMap.entrySet()) {
                if (entry.getValue().equals(val)) {
                    sortedWords.add(entry.getKey());
                    break;
                }
            }
        }

        return String.join(" ", sortedWords);
    }
}

