class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Check for invalid input - n must be greater than 1
        if (n <= 1) {
            throw new IllegalArgumentException("n must be greater than 1");
        }

        // The largest proper divisor cannot be larger than n/2
        // Start from n/2 and go downwards to find the first divisor
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // This should never be reached for n > 1, but just in case
        throw new IllegalStateException("No proper divisor found for n = " + n);
    }
}

