class Solution {
    public double findZero(List<Double> xs) {
        // Validate input: must have even number of coefficients
        if (xs == null || xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Find the highest degree non-zero coefficient to determine leading behavior
        int n = xs.size();
        double leadingCoeff = 0.0;
        for (int i = n - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-15) {
                leadingCoeff = xs.get(i);
                break;
            }
        }

        // If all coefficients are zero, any x is a solution
        if (leadingCoeff == 0.0) {
            return 0.0;
        }

        // Use bisection method to find a root
        // For odd degree polynomials, we know there's at least one real root
        double left = -1000.0;
        double right = 1000.0;

        // Expand search range until we find opposite signs
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 2;
            right *= 2;
            // Safety limit to prevent infinite loop
            if (Math.abs(left) > 1e9) {
                // Fallback: try Newton's method starting from 0
                return newtonMethod(xs, 0.0);
            }
        }

        // Bisection method
        double mid = 0.0;
        for (int i = 0; i < 100; i++) { // 100 iterations for precision
            mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (poly(xs, left) * fMid <= 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return mid;
    }

    // Helper method for Newton-Raphson as fallback
    private double newtonMethod(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 50; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }
            // Compute derivative numerically
            double h = 1e-9;
            double fPrime = (poly(xs, x + h) - poly(xs, x - h)) / (2 * h);
            if (Math.abs(fPrime) < 1e-15) {
                // Derivative too small, switch to bisection-like approach
                x += 1.0;
                continue;
            }
            x = x - fx / fPrime;
            if (Double.isNaN(x) || Double.isInfinite(x)) {
                x = (x0 + 1.0) / 2; // Reset if diverged
            }
        }
        return x;
    }
}

