import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Create a copy to avoid modifying original list (defensive copy)
        List<Double> coeffs = new ArrayList<>(xs);

        // Newton-Raphson method
        double x = 1.0; // initial guess
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(coeffs, x);

            // Check if we're close enough to a root
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative: f'(x)
            double fPrimeX = 0.0;
            for (int i = 1; i < coeffs.size(); i++) {
                fPrimeX += coeffs.get(i) * i * Math.pow(x, i - 1);
            }

            // Avoid division by zero
            if (Math.abs(fPrimeX) < 1e-15) {
                // Try a different initial guess or perturb x
                x += 0.1;
                continue;
            }

            double xNew = x - fx / fPrimeX;

            // Check for convergence
            if (Math.abs(xNew - x) < tolerance) {
                // Verify it's actually a root
                if (Math.abs(poly(coeffs, xNew)) < 1e-8) {
                    return xNew;
                }
            }

            x = xNew;
        }

        // Fallback: return last approximation
        return x;
    }
}

