        for (String token : tokens) {
            switch (token) {
                case "o":
                    result.add(4);
                    break;
                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // For robustness, could ignore or throw exception,
                    // but problem statement implies only valid tokens will be present
                    break;
            }
        }

        return result;
    }
}

