import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
            // Use Newton-Raphson method to find a root
            // Start with initial guess and iterate until convergence

            // Handle edge cases
            if (xs == null || xs.isEmpty()) {
                return 0.0;
            }

            // If constant polynomial (degree 0), no root unless it's zero
            if (xs.size() == 1) {
                return 0.0; // arbitrary choice for constant case
            }

            // Find the degree (highest non-zero coefficient)
            int degree = xs.size() - 1;
            while (degree >= 0 && Math.abs(xs.get(degree)) < 1e-12) {
                degree--;
            }
            if (degree < 0) {
                return 0.0; // zero polynomial
            }

            // Newton-Raphson method
            double x = 1.0; // initial guess

            // Try multiple starting points to increase chances of finding a root
            double[] initialGuesses = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

            for (double guess : initialGuesses) {
                x = guess;
                for (int iteration = 0; iteration < 100; iteration++) {
                    double fx = poly(xs, x);

                    // Check if we're close enough to a root
                    if (Math.abs(fx) < 1e-10) {
                        return x;
                    }

                    // Compute derivative
                    double fpx = polyDerivative(xs, x);

                    // Avoid division by zero
                    if (Math.abs(fpx) < 1e-10) {
                        break; // try next initial guess
                    }

                    double xNext = x - fx / fpx;

                    // Check for convergence
                    if (Math.abs(xNext - x) < 1e-10) {
                        // Verify it's actually a root
                        if (Math.abs(poly(xs, xNext)) < 1e-8) {
                            return xNext;
                        }
                        break;
                    }

                    x = xNext;
                }
            }

            // Fallback: try bisection on a large interval since odd-degree polynomials have roots
            // Try to find interval where function changes sign
            double left = -1000.0;
            double right = 1000.0;

            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            // Ensure we have opposite signs
            while (fLeft * fRight > 0 && (left > -10000 || right < 10000)) {
                left *= 2;
                right *= 2;
                fLeft = poly(xs, left);
                fRight = poly(xs, right);
            }

            if (fLeft * fRight <= 0) {
                // Bisection method
                for (int i = 0; i < 100; i++) {
                    double mid = (left + right) / 2.0;
                    double fMid = poly(xs, mid);

                    if (Math.abs(fMid) < 1e-10) {
                        return mid;
                    }

                    if (fLeft * fMid < 0) {
                        right = mid;
                        fRight = fMid;
                    } else {
                        left = mid;
                        fLeft = fMid;
                    }
                }
                return (left + right) / 2.0;
            }

            // Last resort: return 0.0
            return 0.0;
        }

        // Helper method to compute derivative of polynomial
        private double polyDerivative(List<Double> xs, double x) {
            if (xs.size() <= 1) {
                return 0.0;
            }

            double result = 0;
            for (int i = 1; i < xs.size(); i++) {
                result += i * xs.get(i) * Math.pow(x, i - 1);
            }
            return result;
        }
}

