class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Handle null cases
        if (a == null || b == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        // Ensure both strings have the same length
        int lenA = a.length();
        int lenB = b.length();

        // If lengths differ, we'll pad the shorter one with leading zeros
        // or process up to the minimum length. Based on typical XOR behavior,
        // we'll assume they should be the same length, but handle padding.
        int maxLen = Math.max(lenA, lenB);

        // Pad both strings to the same length with leading zeros
        StringBuilder sbA = new StringBuilder(a);
        StringBuilder sbB = new StringBuilder(b);

        while (sbA.length() < maxLen) {
            sbA.insert(0, '0');
        }
        while (sbB.length() < maxLen) {
            sbB.insert(0, '0');
        }

        a = sbA.toString();
        b = sbB.toString();

        StringBuilder result = new StringBuilder();

        for (int i = 0; i < a.length(); i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            // XOR logic: if bits are different, result is '1', otherwise '0'
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

