class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Use Newton-Raphson method to find a root
        // Start with an initial guess
        double x = 1.0;
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);

            // If we're close enough to zero, return
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative
            double fPrimeX = polyDerivative(xs, x);

            // Avoid division by zero
            if (Math.abs(fPrimeX) < 1e-15) {
                // Try a different initial guess
                x += 1.0;
                continue;
            }

            // Newton-Raphson step
            double xNew = x - fx / fPrimeX;

            // Check for convergence
            if (Math.abs(xNew - x) < tolerance) {
                // Verify this is actually a root
                if (Math.abs(poly(xs, xNew)) < tolerance) {
                    return xNew;
                }
            }

            x = xNew;
        }

        // Return best approximation found
        return x;
    }

    // Helper method to compute polynomial derivative
    private double polyDerivative(List<Double> coeffs, double x) {
        if (coeffs.size() <= 1) {
            return 0.0;
        }

        double result = 0.0;
        for (int i = 1; i < coeffs.size(); i++) {
            result += i * coeffs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

