class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n < 2) {
            return false;
        }

        if (n == 2) {
            return true;
        }

        // Exclude even numbers > 2
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: linear polynomial (degree 1)
        if (xs.size() == 2) {
            return -xs.get(0) / xs.get(1);
        }

        // For higher degrees, use Newton-Raphson method
        // First, find the degree (highest non-zero coefficient index)
        int degree = xs.size() - 1;
        while (degree > 0 && Math.abs(xs.get(degree)) < 1e-12) {
            degree--;
        }

        // If it's actually linear, handle separately
        if (degree == 1) {
            return -xs.get(0) / xs.get(1);
        }

        // Newton-Raphson method
        double x = 1.0; // initial guess

        for (int i = 0; i < 100; i++) { // max iterations
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative
            double[] coeffs = new double[degree];
            for (int j = 1; j <= degree; j++) {
                coeffs[j-1] = xs.get(j) * j;
            }

            double fpx = poly(coeffs, x);
            if (Math.abs(fpx) < 1e-12) {
                // Derivative too small, try different initial guess
                x += 0.5;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < 1e-10) {
                return xNext;
            }

            x = xNext;
        }

        // Fallback: return last computed value
        return x;
    }
}

