class Solution {
    /**
    Given a positive floating point number, it can be decomposed into
    and integer part (largest integer smaller than given number) and decimals
    (leftover part always smaller than 1).

    Return the decimal part of the number.
    >>> truncateNumber(3.5)
    0.5
     */
    public double truncateNumber(double number) {
        // For positive numbers, get the integer part using floor
        // Then subtract to get the decimal part
        double integerPart = Math.floor(number);
        double decimalPart = number - integerPart;

        // Ensure the result is in [0, 1) range due to potential floating-point precision issues
        if (decimalPart >= 1.0) {
            decimalPart = 0.0;
        } else if (decimalPart < 0.0) {
            // This shouldn't happen for positive inputs, but handle edge cases
            decimalPart += 1.0;
        }

        return decimalPart;
    }
}

