class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Defensive copy to prevent modification of the list by caller
        List<Double> coeffs = new ArrayList<>(xs);

        // Create a function to evaluate polynomial
        java.util.function.DoubleUnaryOperator polyFunc = (double x) -> {
            double result = 0;
            double xPower = 1;
            for (Double coeff : coeffs) {
                result += coeff * xPower;
                xPower *= x;
            }
            return result;
        };

        double f(double x) {
            double result = 0;
            double xPower = 1;
            for (Double coeff : coeffs) {
                result += coeff * xPower;
                xPower *= x;
            }
            return result;
        }

        // Since we have odd degree polynomial (even number of coefficients),
        // and a root is guaranteed, use bisection method

        // Find an interval where function changes sign
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = f(left);
        double fRight = f(right);

        // If we don't have opposite signs, expand the interval
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 20) {
            left *= 10;
            right *= 10;
            fLeft = f(left);
            fRight = f(right);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // sufficient iterations for precision
            double mid = (left + right) / 2.0;
            double fMid = f(mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

