class Solution {
    public String makePalindrome(String string) {
        // Handle null case (though problem doesn't specify, it's good practice)
        if (string == null) {
            return null;
        }

        // Try each possible starting position for the palindromic suffix
        // Start from index 0 (whole string) and move right to find longest palindrome suffix
        for (int i = 0; i < string.length(); i++) {
            if (isPalindrome(string.substring(i))) {
                // Found the longest palindromic suffix starting at index i
                String prefix = string.substring(0, i);
                String reversePrefix = new StringBuilder(prefix).reverse().toString();
                return string + reversePrefix;
            }
        }

        // This should never happen for valid strings since single characters are palindromes
        return string;
    }
}

