class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return -1; // or throw exception, but problem implies n > 1
        }

        // For even numbers, the largest proper divisor is n/2
        if (n % 2 == 0) {
            return n / 2;
        }

        // For odd numbers, find the smallest divisor d > 1
        // Then n/d is the largest proper divisor
        for (int d = 3; d * d <= n; d += 2) {
            if (n % d == 0) {
                return n / d;
            }
        }

        // If no divisor found, n is prime, so largest proper divisor is 1
        return 1;
    }
}

