        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle special case: linear polynomial (2 coefficients)
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) < 1e-12) {
                // Degenerate case: no x term, either no solution or infinite solutions
                // But problem states guaranteed solution, so assume b != 0
                return -a / b;
            }
            return -a / b;
        }

        // Bisection method with interval expansion
        double left = -1000.0;
        double right = 1000.0;

        // Expand interval until we bracket a root
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 2;
            right *= 2;
            // Safety limit to avoid infinite loops
            if (Math.abs(left) > 1e9) {
                // Fallback: try Newton's method or return NaN
                // But problem guarantees solution exists, so this shouldn't happen
                break;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~1e-30 precision
            double mid = (left + right) / 2;
            double value = poly(xs, mid);

            if (Math.abs(value) < 1e-12) {
                return mid;
            }

            if (poly(xs, left) * value < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2;
    }
}

