class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrtN = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        double xPower = 1;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * xPower;
            xPower *= x;
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Optimized polynomial evaluation using Horner's method
        // f(x) = a0 + a1*x + a2*x^2 + ... = a0 + x*(a1 + x*(a2 + x*(...)))
        java.util.function.DoubleUnaryOperator f = (double x) -> {
            double result = 0.0;
            for (int i = xs.size() - 1; i >= 0; i--) {
                result = result * x + xs.get(i);
            }
            return result;
        };

        // For odd-degree polynomials, we know there's at least one real root
        // We'll use a combination of bisection and Newton-Raphson

        // First, find bounds where the function changes sign
        double left = -1000.0;
        double right = 1000.0;

        // Expand search range if needed
        while (f.applyAsDouble(left) * f.applyAsDouble(right) > 0) {
            left *= 10;
            right *= 10;
            if (Math.abs(left) > 1e9) {
                // Fallback: try Newton's method from multiple starting points
                break;
            }
        }

        // Use bisection method within the bracketed interval
        for (int iteration = 0; iteration < 100; iteration++) {
            double mid = (left + right) / 2.0;
            double fMid = f.applyAsDouble(mid);

            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }

            if (f.applyAsDouble(left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // If bisection didn't converge well enough, try Newton-Raphson from a few starting points
        double[] guesses = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};
        for (double guess : guesses) {
            double result = newtonRaphson(f, guess);
            if (Math.abs(f.applyAsDouble(result)) < 1e-8) {
                return result;
            }
        }

        // Last resort: return midpoint of final bisection interval
        return (left + right) / 2.0;
    }

    private double newtonRaphson(java.util.function.DoubleUnaryOperator f, double x0) {
        double x = x0;
        for (int i = 0; i < 50; i++) {
            double fx = f.applyAsDouble(x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Numerical derivative
            double h = 1e-8;
            double fPrime = (f.applyAsDouble(x + h) - fx) / h;

            if (Math.abs(fPrime) < 1e-12) {
                // Derivative too small, try small perturbation
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fPrime;

            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                return x0; // fallback
            }

            x = xNext;
        }
        return x;
    }
}

