class Solution {
    public String makePalindrome(String string) {
        if (string == null || string.length() <= 1) {
            return string;
        }

        // Find the longest palindromic suffix
        int start = 0; // starting index of the longest palindromic suffix
        for (int i = 0; i < string.length(); i++) {
            if (isPalindrome(string.substring(i))) {
                start = i;
                break;
            }
        }

        // Get the prefix that comes before the palindromic suffix
        String prefix = string.substring(0, start);

        // Append reverse of prefix to the original string
        String reversedPrefix = new StringBuilder(prefix).reverse().toString();
        return string + reversedPrefix;
    }
}

