class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases: n should be > 1 since 1 has no proper divisors
        if (n <= 1) {
            return -1; // or throw exception, but problem likely assumes n > 1
        }

        // Check from n/2 down to 1 for the first divisor
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // This line is theoretically unreachable for n > 1, as 1 always divides n
    }
}

