import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
            // If xs has even number of coefficients, degree is odd (n-1)
            // Find the degree (highest non-zero coefficient)
            int degree = -1;
            for (int i = xs.size() - 1; i >= 0; i--) {
                if (Math.abs(xs.get(i)) > 1e-12) {
                    degree = i;
                    break;
                }
            }

            // If no non-zero coefficients found, return 0
            if (degree == -1) {
                return 0.0;
            }

            // Function to evaluate polynomial
            java.util.function.DoubleUnaryOperator polyFunc = (double x) -> {
                double result = 0;
                double xPower = 1;
                for (int i = 0; i < xs.size(); i++) {
                    result += xs.get(i) * xPower;
                    xPower *= x;
                }
                return result;
            };

            // Since polynomial of odd degree goes to ±infinity, find bounds
            double left = -1000.0;
            double right = 1000.0;

            // Expand bounds until we find sign change
            double fLeft = polyFunc.applyAsDouble(left);
            double fRight = polyFunc.applyAsDouble(right);

            // Try expanding bounds if needed
            int attempts = 0;
            while (fLeft * fRight > 0 && attempts < 30) {
                left *= 2;
                right *= 2;
                fLeft = polyFunc.applyAsDouble(left);
                fRight = polyFunc.applyAsDouble(right);
                attempts++;
            }

            // Bisection method
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = polyFunc.applyAsDouble(mid);

                if (Math.abs(fMid) < 1e-10) {
                    return mid;
                }

                if (fLeft * fMid < 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }

            return (left + right) / 2;
        }
}

