class Solution {
    public double findZero(List<Double> xs) {
        // Newton-Raphson method to find a root
        double x = 1.0; // initial guess

        // Limit iterations to avoid infinite loops
        for (int iter = 0; iter < 100; iter++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-9) {
                return x;
            }

            // Compute derivative: f'(x) = sum(i * xs.get(i) * x^(i-1)) for i>=1
            double fpx = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fpx += i * xs.get(i) * Math.pow(x, i - 1);
            }

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-9) {
                // Try a different initial guess or perturb
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < 1e-9) {
                return xNext;
            }

            x = xNext;
        }

        // Fallback: return current approximation
        return x;
    }
}

