class Solution {
    /**
    Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13.
    >>> fizzBuzz(50)
    0
    >>> fizzBuzz(78)
    2
    >>> fizzBuzz(79)
    3
     */
    public int fizzBuzz(int n) {
        int count = 0;

        // Check all numbers from 1 to n-1
        for (int i = 1; i < n; i++) {
            // Check if divisible by 11 or 13
            if (i % 11 == 0 || i % 13 == 0) {
                // Count occurrences of '7' in this number
                count += countSevens(i);
            }
        }

        return count;
    }

    private int countSevens(int num) {
        int count = 0;
        int temp = num;

        // Handle negative numbers just in case (though our input is positive)
        if (temp < 0) {
            temp = -temp;
        }

        // Special case for 0
        if (temp == 0) {
            return 0;
        }

        while (temp > 0) {
            if (temp % 10 == 7) {
                count++;
            }
            temp /= 10;
        }

        return count;
    }
}

