class Solution {
    public List<Double> findClosestElements(List<Double> numbers) {
        // Create a copy and sort it
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        double minDiff = Math.abs(sorted.get(1) - sorted.get(0));
        double[] closestPair = {sorted.get(0), sorted.get(1)};

        // Check adjacent pairs in sorted list
        for (int i = 1; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < minDiff) {
                minDiff = diff;
                closestPair[0] = sorted.get(i);
                closestPair[1] = sorted.get(i + 1);
            }
        }

        // Ensure smaller number comes first (for case where they might be equal or already ordered)
        if (closestPair[0] <= closestPair[1]) {
            return Arrays.asList(closestPair[0], closestPair[1]);
        } else {
            return Arrays.asList(closestPair[1], closestPair[0]);
        }
    }
}

