    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Get the degree (number of coefficients - 1)
        int n = xs.size() - 1;

        // Find the leading coefficient (last non-zero coefficient from the end)
        double leadingCoeff = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) {
                leadingCoeff = xs.get(i);
                break;
            }
        }

        // Determine search bounds based on leading coefficient
        // For large |x|, the polynomial behaves like leadingCoeff * x^n
        // We need to find bounds where f(a) * f(b) < 0

        double lowerBound = -1000.0;
        double upperBound = 1000.0;

        // Adjust bounds based on leading coefficient to ensure we bracket a root
        // Since we have odd degree (even number of coefficients means degree is odd),
        // there must be a real root

        // First, find reasonable bounds by expanding until we get opposite signs
        double fLower = poly(xs, lowerBound);
        double fUpper = poly(xs, upperBound);

        // If same sign, expand bounds
        int expansionCount = 0;
        while (fLower * fUpper > 0 && expansionCount < 50) {
            lowerBound *= 10;
            upperBound *= 10;
            fLower = poly(xs, lowerBound);
            fUpper = poly(xs, upperBound);
            expansionCount++;
        }

        // Binary search for the root
        double left = lowerBound;
        double right = upperBound;

        // Make sure we have opposite signs at boundaries
        if (poly(xs, left) * poly(xs, right) > 0) {
            // Fallback: just try some common values if bracketing fails
            // Try values from -10 to 10
            for (double test = -10.0; test <= 10.0; test += 0.5) {
                if (Math.abs(poly(xs, test)) < 1e-9) {
                    return test;
                }
            }
            // If still no luck, return midpoint as fallback
            return (left + right) / 2;
        }

        // Binary search with precision
        for (int i = 0; i < 100; i++) { // enough iterations for double precision
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2;
    }
}

