class Solution {
    public double findZero(List<Double> xs) {
        // Handle degenerate cases: empty list or all zeros
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Find the highest non-zero coefficient to determine actual degree
        int n = xs.size() - 1;
        while (n >= 0 && Math.abs(xs.get(n)) < 1e-12) {
            n--;
        }

        // If all coefficients are zero, any x is a solution
        if (n < 0) {
            return 0.0;
        }

        // For odd degree polynomials (even number of coefficients in original list)
        // but after trimming leading zeros, degree might be even - but problem states
        // "even number of coefficients", so assume original list has even size

        // Check if degree is odd (n % 2 == 1)
        // If not, but problem guarantees solution exists, proceed anyway

        // Use bisection method
        double left = -1000.0;
        double right = 1000.0;

        // Expand interval until we find sign change
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 2;
            right *= 2;
            // Safety limit to prevent infinite loop
            if (Math.abs(left) > 1e9) {
                break;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations for double precision
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2;
    }
}

