class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Handle small cases directly for efficiency
        if (n == 1) return 2;
        if (n == 2) return 3;
        if (n == 3) return 5;
        if (n == 4) return 13;
        if (n == 5) return 89;

        // Count of Fibonacci primes found
        int count = 5;

        // Start generating from the next Fibonacci numbers after 89
        // Previous two Fibonacci numbers before 89 are 34 and 55
        long prev2 = 34; // F(9) = 34
        long prev1 = 55; // F(10) = 55
        long current = 89; // F(11) = 89

        while (true) {
            // Generate next Fibonacci number
            long next = prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
            current = next;

            // Check if current is prime
            if (isPrime(current)) {
                count++;
                if (count == n) {
                    return (int) current;
                }
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;

        // Check for factors up to sqrt(num)
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

