    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check for odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For linear case: ax + b = 0 => x = -b/a
        if (xs.size() == 2) {
            double a = xs.get(1);
            double b = xs.get(0);
            if (Math.abs(a) > 1e-12) {
                return -b / a;
            }
        }

        // For higher degrees, use Newton-Raphson with multiple starting points
        int maxIterations = 1000;
        double tolerance = 1e-12;

        // Try different starting points
        double[] starts = {-1000, -100, -10, -1, 0, 1, 10, 100, 1000};

        for (double start : starts) {
            double x = start;
            for (int i = 0; i < maxIterations; i++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < tolerance) {
                    return x;
                }

                // Compute derivative
                double fpx = polyDerivative(xs, x);
                if (Math.abs(fpx) < 1e-15) {
                    break; // Derivative too small, Newton fails
                }

                double xNext = x - fx / fpx;

                // Check if we're diverging or going out of bounds
                if (Double.isNaN(xNext) || Double.isInfinite(xNext) || Math.abs(xNext - x) > 1e6) {
                    break;
                }

                x = xNext;
            }
        }

        // Fallback: bisection with scanning for sign changes
        double left = -1000;
        double right = 1000;
        double step = 1;

        // Find interval with sign change
        while (left <= right) {
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            if (fLeft == 0) return left;
            if (fRight == 0) return right;
            if (fLeft * fRight < 0) {
                // Bisection in [left, right]
                while (right - left > 1e-12) {
                    double mid = (left + right) / 2;
                    double fMid = poly(xs, mid);
                    if (Math.abs(fMid) < tolerance) return mid;
                    if (fLeft * fMid < 0) {
                        right = mid;
                    } else {
                        left = mid;
                        fLeft = fMid;
                    }
                }
                return (left + right) / 2;
            }

            left -= step * 10;
            right += step * 10;
            step *= 2;

            if (Math.abs(left) > 1e6) break; // Give up
        }

        // Last resort: return midpoint of search range
        return 0;
    }

    private double polyDerivative(List<Double> xs, double x) {
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += xs.get(i) * i * Math.pow(x, i - 1);
        }
        return result;
    }
}

