class Solution {
    /**
    Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13.
    >>> fizzBuzz(50)
    0
    >>> fizzBuzz(78)
    2
    >>> fizzBuzz(79)
    3
     */
    public int fizzBuzz(int n) {
        int count = 0;

        // Check all integers from 0 to n-1
        for (int i = 0; i < n; i++) {
            // Check if divisible by 11 or 13
            if (i % 11 == 0 || i % 13 == 0) {
                // Count occurrences of digit 7 in i
                count += countSevens(i);
            }
        }

        return count;
    }

    private int countSevens(int num) {
        // Handle negative numbers (though our loop starts at 0)
        if (num < 0) {
            num = -num;
        }

        // Special case for 0
        if (num == 0) {
            return 0;
        }

        int count = 0;
        while (num > 0) {
            if (num % 10 == 7) {
                count++;
            }
            num /= 10;
        }
        return count;
    }
}

