import java.util.*;
import java.lang.*;

class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // All other even numbers are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        // Only need to check up to sqrt(n) because if n = a*b and a <= b,
        // then a*a <= a*b = n, so a <= sqrt(n)
        int sqrtN = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Create a lambda for evaluating polynomial
        java.util.function.DoubleFunction<Double> polyFunc = (double x) -> poly(xs, x);

        double f = polyFunc.apply(0.0);

        // Try to find interval with sign change
        double left = -1.0;
        double right = 1.0;
        double fLeft = polyFunc.apply(left);
        double fRight = polyFunc.apply(right);

        // Expand interval until we find sign change
        int maxExpansions = 50;
        int count = 0;
        while (fLeft * fRight > 0 && count < maxExpansions) {
            left *= 2;
            right *= 2;
            fLeft = polyFunc.apply(left);
            fRight = polyFunc.apply(right);
            count++;
        }

        // If still no sign change, use bisection anyway with large interval
        if (count >= maxExpansions) {
            left = -1000.0;
            right = 1000.0;
            fLeft = polyFunc.apply(left);
            fRight = polyFunc.apply(right);
        }

        // Bisection method
        double tolerance = 1e-9;
        double mid = 0;

        // Ensure f(left) and f(right) have opposite signs
        if (fLeft * fRight > 0) {
            // Fallback: try Newton-like approach or return midpoint of initial range
            // For robustness, just return the midpoint
            return (left + right) / 2.0;
        }

        for (int i = 0; i < 100; i++) { // Max iterations
            mid = (left + right) / 2.0;
            double fMid = polyFunc.apply(mid);

            if (Math.abs(fMid) < tolerance) {
                break;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return mid;
    }
}

