class Solution {
    public List<String> separateParenGroups(String paren_string) {
        List<String> result = new ArrayList<>();
        StringBuilder currentGroup = new StringBuilder();
        int balance = 0;

        for (char c : paren_string.toCharArray()) {
            // Skip spaces
            if (c == ' ') {
                continue;
            }

            // Add current character to current group
            currentGroup.append(c);

            // Update balance based on parenthesis type
            if (c == '(') {
                balance++;
            } else if (c == ')') {
                balance--;
                // When balance reaches 0, we've completed a balanced group
                if (balance == 0) {
                    result.add(currentGroup.toString());
                    currentGroup = new StringBuilder(); // Reset for next group
                }
            }
        }

        return result;
    }
}

