     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return 0; // or throw exception, but based on examples, assume n >= 2
        }

        // Start checking from 2 upward to find the smallest divisor
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                // i is the smallest divisor, so n/i is the largest proper divisor
                return n / i;
            }
        }

        // If no divisor found, n is prime, so largest proper divisor is 1
        return 1;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Return list of prime factors of given integer in the order from smallest to largest.
    Each of the factors should be listed number of times corresponding to how many times it appeares in factorization.
    Input number should be equal to the product of all factors
    >>> factorize(8)
    [2, 2, 2]
    >>> factorize(25)
    [5, 5]
    >>> factorize(70)
    [2, 5, 7]
     */
    public List<Integer> factorize(int n) {
        List<Integer> factors = new ArrayList<>();

        if (n <= 1) {
            return factors;
        }

        // Check for factor 2
        while (n % 2 == 0) {
            factors.add(2);
            n /= 2;
        }

        // Check for odd factors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }

        // If n is still greater than 1, then it's a prime factor
        if (n > 1) {
            factors.add(n);
        }

        return factors;
    }
}

