class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: empty or single coefficient
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Ensure even number of coefficients as per requirement
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("Polynomial must have even number of coefficients");
        }

        // Check if leading coefficient is zero - find largest non-zero
        int n = xs.size();
        double leadingCoeff = 0.0;
        for (int i = n - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) {
                leadingCoeff = xs.get(i);
                break;
            }
        }

        if (Math.abs(leadingCoeff) < 1e-12) {
            throw new IllegalArgumentException("Largest non-zero coefficient must be non-zero");
        }

        // For linear case (2 coefficients): ax + b = 0 => x = -b/a
        if (n == 2) {
            double a = xs.get(1); // coefficient of x
            double b = xs.get(0); // constant term
            if (Math.abs(a) < 1e-12) {
                // If no x term, then either no solution or infinite solutions
                return 0.0;
            }
            return -b / a;
        }

        // Bisection method for higher degree polynomials
        // Since odd degree polynomial, we know there's at least one root
        // Search in range [-1000, 1000] initially, expand if needed
        double left = -1000.0;
        double right = 1000.0;

        // Find an interval where function changes sign
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 10;
            right *= 10;
            // Prevent infinite loop for pathological cases
            if (Math.abs(left) > 1e8) {
                // Fallback: try Newton-Raphson with initial guess 0
                return newtonRaphson(xs, 0.0);
            }
        }

        // Bisection method
        double tolerance = 1e-9;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance) {
                return mid;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Return midpoint if didn't converge perfectly
        return (left + right) / 2.0;
    }

    // Helper method: Newton-Raphson
    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        double tolerance = 1e-9;
        int maxIterations = 100;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative numerically
            double h = 1e-8;
            double fpx = (poly(xs, x + h) - fx) / h;

            if (Math.abs(fpx) < 1e-12) {
                // Derivative too small, fall back to bisection idea
                return x;
            }

            x = x - fx / fpx;

            // Prevent overflow
            if (Double.isInfinite(x) || Double.isNaN(x)) {
                return x0; // fallback to initial guess
            }
        }

        return x;
    }
}

