class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 1; // F(1)
        long b = 1; // F(2)

        // Check F(1) = 1 (not prime), F(2) = 1 (not prime)
        // Start from F(3) = 2

        // Handle special case for first few Fibonacci numbers
        if (n == 1) return 2;
        if (n == 2) return 3;
        if (n == 3) return 5;

        // Generate Fibonacci numbers starting from 2, 3, 5...
        long fib = 2; // First candidate (F(3))
        long prev = 1; // F(2)
        long prev2 = 1; // F(1)

        count = 0;

        while (true) {
            if (isPrime(fib)) {
                count++;
                if (count == n) {
                    return (int) fib;
                }
            }

            // Generate next Fibonacci number
            long next = prev + prev2;
            prev2 = prev;
            prev = fib;
            fib = next;
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0) return false;

        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

