class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        if (n <= 1) {
            return 0; // or handle as needed, but 1 has no proper divisors
        }

        // Start from n/2 and go downwards - the first divisor found is the largest
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // fallback (shouldn't be reached for n > 1)
    }
}

