        int count = 0;
        int a = 0;  // F(0)
        int b = 1;  // F(1)

        // Handle special case: F(1) = 1 is not prime, F(2) = 1 is not prime
        // Start checking from F(3) = 2

        while (true) {
            int next = a + b;
            a = b;
            b = next;

            // Skip 1 (not prime)
            if (next == 1) {
                continue;
            }

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

