class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrtN = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Newton-Raphson method with multiple starting points
        // Try several starting points in case some lead to division by zero or divergence
        double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

        for (double x0 : startingPoints) {
            double x = x0;
            for (int i = 0; i < 100; i++) { // max iterations
                double fx = poly(xs, x);

                // If we're close enough to zero, return
                if (Math.abs(fx) < 1e-9) {
                    return x;
                }

                // Compute derivative: f'(x) = sum_{k=1}^{n-1} k * xs.get(k) * x^(k-1)
                double fpx = 0.0;
                for (int k = 1; k < xs.size(); k++) {
                    fpx += k * xs.get(k) * Math.pow(x, k - 1);
                }

                // If derivative is zero, skip this starting point
                if (Math.abs(fpx) < 1e-12) {
                    break;
                }

                double xNext = x - fx / fpx;

                // Check for divergence or NaN
                if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                    break;
                }

                x = xNext;
            }
        }

        // Fallback: try bisection method on a range
        // Since it's an odd-degree polynomial, it must cross zero somewhere
        double left = -1000.0;
        double right = 1000.0;

        // Find interval where sign changes
        while (left < right) {
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            if (fLeft * fRight <= 0) {
                // Bisection method
                for (int i = 0; i < 100; i++) {
                    double mid = (left + right) / 2;
                    double fMid = poly(xs, mid);

                    if (Math.abs(fMid) < 1e-9) {
                        return mid;
                    }

                    if (fLeft * fMid <= 0) {
                        right = mid;
                        fRight = fMid;
                    } else {
                        left = mid;
                        fLeft = fMid;
                    }
                }
                return (left + right) / 2;
            }

            left *= 2;
            right *= 2;

            // Safety check to avoid infinite loop
            if (Math.abs(left) > 1e6) {
                break;
            }
        }

        // Last resort: return 0.0
        return 0.0;
    }
}

