            return result;
        }

        String[] notes = string.split(" ");

        for (String note : notes) {
            if (note.equals("o")) {
                result.add(4);
            } else if (note.equals("o|")) {
                result.add(2);
            } else if (note.equals(".|")) {
                result.add(1);
            }
            // Note: The problem doesn't specify handling invalid notes,
            // so we assume valid input based on the examples
        }

        return result;
    }
}

