class Solution {
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Binary search / bisection method to find root
        // Since polynomial has odd degree (even number of coefficients), it must have at least one real root

        // Helper lambda for evaluating polynomial
        java.util.function.DoubleUnaryOperator polyFunc = (double x) -> poly(xs, x);

        // Find an interval [a, b] where f(a) * f(b) < 0 (sign change)
        double a = -1000.0;
        double b = 1000.0;
        double fa = polyFunc.applyAsDouble(a);
        double fb = polyFunc.applyAsDouble(b);

        // Expand interval until we find sign change
        int iterations = 0;
        while (fa * fb > 0 && iterations < 100) {
            a *= 2;
            b *= 2;
            fa = polyFunc.applyAsDouble(a);
            fb = polyFunc.applyAsDouble(b);
            iterations++;
        }

        // Bisection method
        double epsilon = 1e-9;
        for (int i = 0; i < 100; i++) { // sufficient iterations for precision
            double mid = (a + b) / 2.0;
            double fmid = polyFunc.applyAsDouble(mid);

            if (Math.abs(fmid) < epsilon) {
                return mid;
            }

            if (fa * fmid <= 0) {
                b = mid;
                fb = fmid;
            } else {
                a = mid;
                fa = fmid;
            }
        }

        return (a + b) / 2.0;
    }
}

