        // Check adjacent pairs only (they will have minimum distance)
        for (int i = 0; i < sorted.size() - 1; i++) {
            if (Math.abs(sorted.get(i + 1) - sorted.get(i)) < threshold) {
                return true;
            }
        }

        return false;
    }
}

