class Solution {
    public List<Double> rescaleToUnit(List<Double> numbers) {
        if (numbers == null || numbers.isEmpty()) {
            return new ArrayList<>();
        }

        // Find min and max
        double min = numbers.get(0);
        double max = numbers.get(0);

        for (Double num : numbers) {
            if (num != null) {
                min = Math.min(min, num);
                max = Math.max(max, num);
            }
        }

        // Handle the case where all numbers are the same
        if (min == max) {
            // Return list of zeros (or could be all 0.5, but 0 is standard for min-max)
            List<Double> result = new ArrayList<>(Collections.nCopies(numbers.size(), 0.0));
            return result;
        }

        // Apply the rescaling formula: (x - min) / (max - min)
        List<Double> result = new ArrayList<>(numbers.size());
        for (Double num : numbers) {
            result.add((num - min) / (max - min));
        }

        return result;
    }
}

