class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Define a reasonable search range and tolerance
        double left = -1000.0;
        double right = 1000.0;
        double tolerance = 1e-9;

        // Expand the search range if needed until we find a sign change
        while (poly(xs, left) > 0 && poly(xs, right) > 0) {
            left *= 2;
            right *= 2;
        }
        while (poly(xs, left) < 0 && poly(xs, right) < 0) {
            left *= 2;
            right *= 2;
        }

        // Binary search (bisection method)
        for (int i = 0; i < 100; i++) { // 100 iterations should be enough for double precision
            double mid = (left + right) / 2.0;
            double value = poly(xs, mid);

            if (Math.abs(value) < tolerance) {
                return mid;
            }

            if (poly(xs, left) * value < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2.0;
    }
}

