class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Find the largest non-zero coefficient to determine end behavior
        double leadingCoeff = 0.0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-15) {
                leadingCoeff = xs.get(i);
                break;
            }
        }

        // For odd degree polynomial, find interval where sign changes
        double a = -1000.0;
        double b = 1000.0;

        // Adjust bounds based on leading coefficient to ensure sign change
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Expand interval if needed until we find sign change
        int attempts = 0;
        while (fa * fb > 0 && attempts < 30) {
            a *= 2;
            b *= 2;
            fa = poly(xs, a);
            fb = poly(xs, b);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations for double precision
            double mid = (a + b) / 2;
            double fmid = poly(xs, mid);

            if (Math.abs(fmid) < 1e-12) {
                return mid;
            }

            if (fa * fmid <= 0) {
                b = mid;
                fb = fmid;
            } else {
                a = mid;
                fa = fmid;
            }
        }

        return (a + b) / 2;
    }
}

