class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Handle edge cases
        if (string == null || substring == null) {
            return 0;
        }

        if (substring.length() == 0) {
            return 0; // Empty substring - no matches
        }

        if (string.length() < substring.length()) {
            return 0; // String too short to contain substring
        }

        int count = 0;
        int index = 0;

        // Search for substring starting from each possible position
        while (index <= string.length() - substring.length()) {
            int foundIndex = string.indexOf(substring, index);
            if (foundIndex == -1) {
                break;
            }
            count++;
            // Move to next position to allow overlapping matches
            index = foundIndex + 1;
        }

        return count;
    }
}

