class Solution {
    public int largestDivisor(int n) {
        if (n <= 1) {
            throw new IllegalArgumentException("n must be greater than 1");
        }

        // Check for smallest divisor from 2 to sqrt(n)
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                // i is the smallest divisor, so n/i is the largest proper divisor
                return n / i;
            }
        }

        // If no divisor found, n is prime, so largest proper divisor is 1
        return 1;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Return list of prime factors of given integer in the order from smallest to largest.
    Each of the factors should be listed number of times corresponding to how many times it appeares in factorization.
    Input number should be equal to the product of all factors
    >>> factorize(8)
    [2, 2, 2]
    >>> factorize(25)
    [5, 5]
    >>> factorize(70)
    [2, 5, 7]
     */
    public List<Integer> factorize(int n) {
        List<Integer> factors = new ArrayList<>();

        // Handle edge cases
        if (n <= 1) {
            return factors;
        }

        // Work with absolute value since prime factors are positive
        int num = Math.abs(n);

        // Check for factor 2
        while (num % 2 == 0) {
            factors.add(2);
            num /= 2;
        }

        // Check for odd factors starting from 3
        for (int i = 3; i * i <= num; i += 2) {
            while (num % i == 0) {
                factors.add(i);
                num /= i;
            }
        }

        // If num is still greater than 1, then it's a prime factor
        if (num > 1) {
            factors.add(num);
        }

        return factors;
    }
}

