class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrtN = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For degree 1: ax + b = 0 -> x = -b/a (but our format is [constant, coeff_of_x])
        // Actually: xs[0] + xs[1]*x = 0 -> x = -xs[0]/xs[1]
        if (xs.size() == 2) {
            return -xs.get(0) / xs.get(1);
        }

        // Newton's method
        double x = 1.0; // initial guess
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative
            double fPrimeX = polyDerivative(xs, x);

            // Avoid division by zero
            if (Math.abs(fPrimeX) < 1e-15) {
                // Try a different starting point or small perturbation
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fPrimeX;

            // Check for convergence
            if (Math.abs(xNext - x) < tolerance) {
                return xNext;
            }

            x = xNext;
        }

        // If Newton's method fails, try bisection with a reasonable range
        // Try to find an interval where function changes sign
        double left = -100.0, right = 100.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand range until we find sign change
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 20) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        if (fLeft * fRight <= 0) {
            // Bisection method
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);

                if (Math.abs(fMid) < tolerance || (right - left) < tolerance) {
                    return mid;
                }

                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
            return (left + right) / 2;
        }

        // Fallback - return the last Newton estimate
        return x;
    }

    // Helper method to compute derivative
    private double polyDerivative(List<Double> xs, double x) {
        if (xs.size() <= 1) {
            return 0;
        }

        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

