class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge case: n <= 1 has no proper divisors
        if (n <= 1) {
            return -1; // or throw exception, but problem implies n >= 2
        }

        // Start from n/2 and go down to find the largest proper divisor
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // This should never be reached for n >= 2, since 1 always divides n
        return 1;
    }
}

