class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Validate: even number of coefficients (odd degree polynomial)
        if (xs.size() % 2 == 0) {
            throw new IllegalArgumentException("Polynomial must have even number of coefficients");
        }

        // Check if the polynomial is actually constant (degree 0)
        if (xs.size() == 1) {
            // Constant polynomial: either no solution or all x are solutions
            // But according to problem, we only handle cases with guaranteed solution
            throw new IllegalArgumentException("Constant polynomial cannot have unique solution");
        }

        // Use bisection method - find interval [a, b] where f(a)*f(b) < 0
        // For odd-degree polynomial, as x -> ±∞, f(x) -> ±∞ or ∓∞ depending on leading coefficient

        double a = -1000.0;
        double b = 1000.0;

        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // If signs are same, expand interval
        int attempts = 0;
        while (fa * fb > 0 && attempts < 30) {
            a *= 10;
            b *= 10;
            fa = poly(xs, a);
            fb = poly(xs, b);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations for precision
            double mid = (a + b) / 2.0;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < 1e-9) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2.0;
    }
}

