        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For polynomials with even number of coefficients (odd degree)
        // There's guaranteed to be at least one real root

        // Use Newton-Raphson method to find a root
        double x = 1.0; // initial guess
        double tolerance = 1e-10;

        for (int i = 0; i < 1000; i++) {
            double fx = poly(xs, x);

            // If we're close enough to zero, return
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative: f'(x) = sum(k * xs[k] * x^(k-1)) for k=1 to n
            double fpx = 0.0;
            for (int k = 1; k < xs.size(); k++) {
                fpx += k * xs.get(k) * Math.pow(x, k - 1);
            }

            // Avoid division by zero
            if (Math.abs(fpx) < tolerance) {
                // If derivative is zero, try a different approach - perturb x
                x += 0.1;
                continue;
            }

            // Newton-Raphson step
            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < tolerance) {
                return xNext;
            }

            x = xNext;
        }

        // Fallback: return best approximation
        return x;
    }
}

