        String[] notes = string.trim().split("\\s+");

        for (String note : notes) {
            switch (note) {
                case "o":
                    result.add(4);
                    break;
                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // Ignore invalid notes or could throw exception
                    break;
            }
        }

        return result;
    }
}

