        String[] words = numbers.trim().split("\\s+");

        // Sort words by their numeric values
        Arrays.sort(words, (a, b) -> wordToNumber.get(a).compareTo(wordToNumber.get(b)));

        // Join sorted words with spaces
        return String.join(" ", words);
    }
}

