            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        int n = xs.size() - 1; // degree
        if (n == 1) {
            // ax + b = 0 => x = -b/a, but note: xs[0] = constant, xs[1] = coeff of x
            // So xs[0] + xs[1]*x = 0 => x = -xs[0]/xs[1]
            return -xs.get(0) / xs.get(1);
        }

        // Try small integers first (based on examples)
        for (int x = -10; x <= 10; x++) {
            double val = poly(xs, (double) x);
            if (Math.abs(val) < 1e-9) {
                return (double) x;
            }
        }

        // If no integer root found, use bisection on [-1000, 1000]
        double left = -1000.0;
        double right = 1000.0;
        // Ensure we have opposite signs — expand if needed
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand interval until we straddle zero (odd degree guarantees eventually)
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 10) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // Now bisection
        for (int i = 0; i < 100; i++) { // 100 iterations → precision ~1e-30
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);
            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }
            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

