class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Ensure we have even number of coefficients
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Remove trailing zeros to get the actual degree
        List<Double> trimmed = new ArrayList<>(xs);
        while (trimmed.size() > 1 && Math.abs(trimmed.get(trimmed.size() - 1)) < 1e-15) {
            trimmed.remove(trimmed.size() - 1);
        }

        // After trimming, degree should be odd (since original size was even)
        int degree = trimmed.size() - 1;
        if (degree % 2 == 0) {
            throw new IllegalArgumentException("After trimming, degree must be odd (guaranteed by problem statement)");
        }

        // Get the leading coefficient (should be non-zero after trimming)
        double leadingCoeff = trimmed.get(trimmed.size() - 1);

        // If it's a linear polynomial (degree 1), solve directly
        if (degree == 1) {
            double constantTerm = trimmed.get(0);
            double slope = trimmed.get(1);
            return -constantTerm / slope;
        }

        // Define the polynomial function
        java.util.function.DoubleUnaryOperator polyFunc = x -> {
            double result = 0;
            double xPower = 1;
            for (double coeff : trimmed) {
                result += coeff * xPower;
                xPower *= x;
            }
            return result;
        };

        // Find bounds where function changes sign
        double left = -1.0;
        double right = 1.0;
        double fLeft = polyFunc.applyAsDouble(left);
        double fRight = polyFunc.applyAsDouble(right);

        // Expand bounds until we find sign change
        int iterations = 0;
        while (fLeft * fRight > 0 && iterations < 100) {
            left *= 2;
            right *= 2;
            fLeft = polyFunc.applyAsDouble(left);
            fRight = polyFunc.applyAsDouble(right);
            iterations++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives good precision
            double mid = (left + right) / 2;
            double fMid = polyFunc.applyAsDouble(mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint of final interval
        return (left + right) / 2;
    }
}

