class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        // Only need to check up to √n because if n = a * b and a <= b, then a * a <= n, so a <= √n
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Horner's method for better numerical stability and efficiency
        double result = 0.0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Remove trailing zeros (leading coefficients for higher degrees)
        List<Double> coeffs = new ArrayList<>(xs);
        while (coeffs.size() > 1 && coeffs.get(coeffs.size() - 1) == 0.0) {
            coeffs.remove(coeffs.size() - 1);
        }

        // Ensure we have even number of coefficients as per requirement
        // If not even, add a zero coefficient to make it even (but this shouldn't happen per spec)
        if (coeffs.size() % 2 == 0) {
            // Keep as is
        } else {
            coeffs.add(0.0);
        }

        // Get leading coefficient (highest degree term)
        double leadingCoeff = coeffs.get(coeffs.size() - 1);
        double constantTerm = coeffs.get(0);

        // Handle special cases
        if (leadingCoeff == 0.0) {
            // Edge case: all coefficients zero -> any x is a solution
            return 0.0;
        }

        // Try rational roots using Rational Root Theorem
        // Possible roots are ±factors(constantTerm) / factors(leadingCoeff)
        List<Double> candidates = new ArrayList<>();

        // Get integer factors for simple cases (assuming coefficients are small integers)
        long constInt = Math.round(constantTerm);
        long leadInt = Math.round(leadingCoeff);

        if (constInt == 0) {
            // If constant term is 0, then x=0 is a root
            return 0.0;
        }

        // Find factors of constant term
        for (long i = 1; i * i <= Math.abs(constInt); i++) {
            if (constInt % i == 0) {
                candidates.add((double) i);
                candidates.add((double) -i);
                if (i * i != Math.abs(constInt)) {
                    candidates.add((double) (constInt / i));
                    candidates.add((double) -(constInt / i));
                }
            }
        }

        // Add fractions if leading coefficient ≠ 1
        if (leadInt != 1 && leadInt != -1 && leadInt != 0) {
            List<Double> originalCandidates = new ArrayList<>(candidates);
            for (double cand : originalCandidates) {
                for (long j = 1; j * j <= Math.abs(leadInt); j++) {
                    if (leadInt % j == 0) {
                        candidates.add(cand / j);
                        candidates.add(cand / -j);
                        if (j * j != Math.abs(leadInt)) {
                            candidates.add(cand / (leadInt / j));
                            candidates.add(cand / -(leadInt / j));
                        }
                    }
                }
            }
        }

        // Remove duplicates and try candidates
        Set<Double> uniqueCandidates = new HashSet<>(candidates);
        for (double candidate : uniqueCandidates) {
            if (Math.abs(poly(xs, candidate)) < 1e-9) {
                return candidate;
            }
        }

        // If no rational root found, use bisection method for odd-degree polynomials
        // Since we have even number of coefficients, degree is odd, so there must be a real root

        // Find interval where sign changes
        double left = -1000.0;
        double right = 1000.0;

        // Expand interval until we find sign change
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 10;
            right *= 10;
            if (right > 1e9) {
                break; // Safety limit
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2.0;
            double value = poly(xs, mid);

            if (Math.abs(value) < 1e-9) {
                return mid;
            }

            if (poly(xs, left) * value < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Return midpoint as fallback
        return (left + right) / 2.0;
    }
}

