class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int fib1 = 1;
        int fib2 = 1;

        // Start checking from the 3rd Fibonacci number (which is 2)
        while (true) {
            int nextFib = fib1 + fib2;

            if (isPrime(nextFib)) {
                count++;
                if (count == n) {
                    return nextFib;
                }
            }

            fib1 = fib2;
            fib2 = nextFib;
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

