class Solution {
    /**
     * Check if in given list of numbers, are any two numbers closer to each other than given threshold.
     * <p>
     * The method sorts the list first and then checks adjacent pairs for proximity,
     * which ensures O(n log n) time complexity due to sorting.
     *
     * @param numbers the list of numbers to check (not modified)
     * @param threshold the minimum distance threshold; if any pair of numbers has distance
     *                  strictly less than this value, the method returns true
     * @return true if there exist two numbers in the list whose absolute difference is
     *         strictly less than the threshold, false otherwise
     * @throws IllegalArgumentException if {@code threshold} is negative
     * @throws NullPointerException if {@code numbers} is null
     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        // Validate inputs
        if (numbers == null) {
            throw new NullPointerException("numbers cannot be null");
        }
        if (threshold < 0) {
            throw new IllegalArgumentException("threshold must be non-negative");
        }

        // Handle edge cases
        if (numbers.size() < 2) {
            return false;
        }

        // Create a copy to avoid modifying the original list
        List<Double> sortedNumbers = new ArrayList<>(numbers);
        Collections.sort(sortedNumbers);

        // Check adjacent pairs only - if any pair is closer than threshold, return true
        for (int i = 0; i < sortedNumbers.size() - 1; i++) {
            double diff = Math.abs(sortedNumbers.get(i + 1) - sortedNumbers.get(i));
            if (diff < threshold) {
                return true;
            }
        }

        return false;
    }
}

import java.util.*;
