class Solution {
    /**
     * Separates a string containing multiple groups of nested parentheses into
     * individual balanced groups.
     * 
     * @param paren_string a string containing multiple groups of parentheses, possibly with spaces
     * @return a list of strings, each representing a balanced group of parentheses
     * @throws IllegalArgumentException if the input contains unbalanced parentheses
     */
    public List<String> separateParenGroups(String paren_string) {
        List<String> result = new ArrayList<>();

        // Handle null or empty input
        if (paren_string == null) {
            return result;
        }

        // Remove all spaces from the input
        String cleanString = paren_string.replace(" ", "");

        int balance = 0;
        int start = 0;

        for (int i = 0; i < cleanString.length(); i++) {
            char c = cleanString.charAt(i);

            if (c == '(') {
                // Increment balance when we see an opening parenthesis
                balance++;
            } else if (c == ')') {
                // Decrement balance when we see a closing parenthesis
                balance--;

                // When balance reaches 0, we've found a complete balanced group
                if (balance == 0) {
                    result.add(cleanString.substring(start, i + 1));
                    start = i + 1; // Start next group from next character
                }
            }
        }

        // Check for unbalanced parentheses
        if (balance != 0) {
            throw new IllegalArgumentException("Unbalanced parentheses in input");
        }

        return result;
    }
}

