     * E.g. (()()) has maximum two levels of nesting while ((())) has three.
     *
     * >>> parseNestedParens("(()()) ((())) () ((())()())")
     * [2, 3, 1, 3]
     *
     * @param paren_string a string containing groups of parentheses separated by spaces
     * @return a list of integers representing the maximum nesting depth for each group
     * @throws IllegalArgumentException if the input contains invalid characters or unmatched parentheses
     */
    public List<Integer> parseNestedParens(String paren_string) {
        List<Integer> result = new ArrayList<>();

        if (paren_string == null || paren_string.trim().isEmpty()) {
            return result;
        }

        // Split by whitespace to get individual groups
        String[] groups = paren_string.trim().split("\\s+");

        for (String group : groups) {
            int maxDepth = 0;
            int currentDepth = 0;

            for (int i = 0; i < group.length(); i++) {
                char c = group.charAt(i);

                if (c == '(') {
                    currentDepth++;
                    maxDepth = Math.max(maxDepth, currentDepth);
                } else if (c == ')') {
                    currentDepth--;
                    // Check for invalid sequence (more closing than opening)
                    if (currentDepth < 0) {
                        throw new IllegalArgumentException("Invalid parentheses sequence: " + group);
                    }
                } else {
                    // Invalid character
                    throw new IllegalArgumentException("Invalid character '" + c + "' in group: " + group);
                }
            }

            // Check for unmatched opening parentheses
            if (currentDepth != 0) {
                throw new IllegalArgumentException("Unmatched parentheses in group: " + group);
            }

            result.add(maxDepth);
        }

        return result;
    }
}

