class Solution {
    /**
     * Returns a list containing the sum and product of all integers in the given list.
     * <p>
     * For an empty list, the sum is 0 and the product is 1.
     * <p>
     * Examples:
     * <ul>
     *   <li>{@code sumProduct(List.of())} returns {@code [0, 1]}</li>
     *   <li>{@code sumProduct(Arrays.asList(1, 2, 3, 4))} returns {@code [10, 24]}</li>
     * </ul>
     *
     * @param numbers the list of integers to process; may be empty or null
     * @return a list of two integers: [sum, product]
     * @throws NullPointerException if {@code numbers} is null
     * 
     * @implNote This method iterates through the list once, computing both sum and product in a single pass.
     */
    public List<Integer> sumProduct(List<Integer> numbers) {
        if (numbers == null) {
            throw new NullPointerException("Input list cannot be null");
        }

        int sum = 0;
        int product = 1;

        for (Integer num : numbers) {
            if (num != null) {
                sum += num;
                product *= num;
            } else {
                // Handle null elements - could throw exception or skip
                // Based on typical expectations, we'll treat null as 0 for sum and 1 for product,
                // but since multiplication by 0 would affect product, better to throw exception
                throw new IllegalArgumentException("List contains null elements");
            }
        }

        return Arrays.asList(sum, product);
    }
}

