class Solution {
    /**
     * Computes the rolling maximum of a sequence of integers.
     * For each element in the input list, returns the maximum value
     * encountered from the beginning of the sequence up to and including
     * the current element.
     *
     * @param numbers the list of integers to process; must not be null
     * @return a list where the i-th element is the maximum of the first i+1 elements
     *         from the input list; never returns null
     * @throws NullPointerException if the input list is null
     *
     * Example:
     * <pre>
     *   rollingMax(Arrays.asList(1, 2, 3, 2, 3, 4, 2)) returns [1, 2, 3, 3, 3, 4, 4]
     * </pre>
     */
    public List<Integer> rollingMax(List<Integer> numbers) {
        if (numbers == null) {
            throw new NullPointerException("Input list cannot be null");
        }

        List<Integer> result = new ArrayList<>(numbers.size());
        if (numbers.isEmpty()) {
            return result;
        }

        int currentMax = numbers.get(0);
        result.add(currentMax);

        for (int i = 1; i < numbers.size(); i++) {
            int num = numbers.get(i);
            if (num > currentMax) {
                currentMax = num;
            }
            result.add(currentMax);
        }

        return result;
    }
}

