class Solution {
    /**
     * Test if given string is a palindrome.
     *
     * @param string the string to test
     * @return true if the string is a palindrome, false otherwise
     */
    public boolean isPalindrome(String string) {
        int i = 0;
        int j = string.length() - 1;
        while (i < j) {
            if (string.charAt(i) != string.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    /**
     * Find the shortest palindrome that begins with the supplied string.
     * <p>
     * Algorithm idea: Find the longest postfix of the supplied string that is a palindrome,
     * then append to the end of the string the reverse of the prefix that comes before
     * the palindromic suffix.
     *
     * @param string the input string
     * @return the shortest palindrome that begins with the input string
     * @throws NullPointerException if the input string is null
     */
    public String makePalindrome(String string) {
        if (string == null) {
            throw new NullPointerException("Input string cannot be null");
        }

        // Handle empty string case
        if (string.isEmpty()) {
            return "";
        }

        // Find the longest palindromic suffix
        for (int i = 0; i < string.length(); i++) {
            // Check if substring from i to end is a palindrome
            if (isPalindrome(string.substring(i))) {
                // Found longest palindromic suffix starting at index i
                String prefix = string.substring(0, i);
                String reversedPrefix = new StringBuilder(prefix).reverse().toString();
                return string + reversedPrefix;
            }
        }

        // Fallback (should never reach here since at minimum the last char is a palindrome)
        return string;
    }
}

