class Solution {
    /**
     * Performs bitwise XOR operation on two binary strings.
     * 
     * @param a first binary string consisting of '0's and '1's
     * @param b second binary string consisting of '0's and '1's
     * @return a binary string representing the XOR of the two inputs
     * @throws IllegalArgumentException if the input strings have different lengths
     * 
     * <p>Precondition: both input strings must have the same length and contain only '0' or '1' characters.
     * Postcondition: returns a string of the same length where each character is the XOR of corresponding characters in the inputs.
     * 
     * <p>Example:
     * <pre>{@code
     * stringXor("010", "110") returns "100"
     * }</pre>
     */
    public String stringXor(String a, String b) {
        // Validate inputs
        if (a == null || b == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        if (a.length() != b.length()) {
            throw new IllegalArgumentException("Input strings must have the same length");
        }

        if (a.isEmpty()) {
            return "";
        }

        // Check that strings contain only '0' and '1'
        for (int i = 0; i < a.length(); i++) {
            char c1 = a.charAt(i);
            char c2 = b.charAt(i);
            if ((c1 != '0' && c1 != '1') || (c2 != '0' && c2 != '1')) {
                throw new IllegalArgumentException("Input strings must contain only '0' and '1' characters");
            }
        }

        StringBuilder result = new StringBuilder(a.length());

        for (int i = 0; i < a.length(); i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            // XOR operation: same bits give 0, different bits give 1
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

