     * Returns an empty {@link Optional} if the input list is null or empty.
     *
     * @param strings the list of strings to search through (may be null or empty)
     * @return an {@link Optional} containing the longest string, or empty if the input is null/empty
     * @implSpec This method iterates through the list once, maintaining the longest string seen so far.
     *           When a string of equal or greater length is found, it replaces the current longest string.
     * @throws NullPointerException if the input list is null
     */
    public Optional<String> longest(List<String> strings) {
        if (strings == null || strings.isEmpty()) {
            return Optional.empty();
        }

        String longest = null;
        for (String s : strings) {
            if (s == null) {
                continue;
            }
            if (longest == null || s.length() > longest.length()) {
                longest = s;
            }
        }

        return Optional.ofNullable(longest);
    }
}

