class Solution {
    /**
     * Return the greatest common divisor of two integers a and b.
     * Uses the Euclidean algorithm to compute the GCD efficiently.
     * 
     * @param a first integer (can be negative, zero, or positive)
     * @param b second integer (can be negative, zero, or positive)
     * @return the greatest common divisor of a and b (always non-negative)
     * @throws IllegalArgumentException if both a and b are zero
     * 
     * @apiNote The GCD of 0 and 0 is undefined, so this method throws an exception
     *          in that case. For all other inputs, the result is non-negative.
     * 
     * <pre>
     * Examples:
     *   greatestCommonDivisor(3, 5)  = 1
     *   greatestCommonDivisor(25, 15) = 5
     *   greatestCommonDivisor(-12, 8) = 4
     *   greatestCommonDivisor(0, 10)  = 10
     * </pre>
     */
    public int greatestCommonDivisor(int a, int b) {
        // Handle edge case where both inputs are zero
        if (a == 0 && b == 0) {
            throw new IllegalArgumentException("GCD is undefined for (0, 0)");
        }

        // Use absolute values to handle negative numbers
        // The GCD is always non-negative
        int x = Math.abs(a);
        int y = Math.abs(b);

        // Euclidean algorithm
        while (y != 0) {
            int temp = y;
            y = x % y;
            x = temp;
        }

        return x;
    }
}

