class Solution {
    /**
     * Sorts a space-delimited string of number words from 'zero' to 'nine' in ascending numerical order.
     * 
     * @param numbers a space-delimited string containing only valid number words: 
     *                "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", or "nine"
     * @return a new space-delimited string with the number words sorted from smallest to largest
     * @throws IllegalArgumentException if the input contains invalid number words
     * @throws NullPointerException if the input string is null
     */
    public String sortNumbers(String numbers) {
        // Handle null input
        if (numbers == null) {
            throw new NullPointerException("Input string cannot be null");
        }

        // Handle empty string case
        if (numbers.trim().isEmpty()) {
            return "";
        }

        // Split the input string into individual number words
        String[] numberWords = numbers.split(" +");

        // Define mapping from word to numeric value
        Map<String, Integer> wordToNumber = new HashMap<>();
        wordToNumber.put("zero", 0);
        wordToNumber.put("one", 1);
        wordToNumber.put("two", 2);
        wordToNumber.put("three", 3);
        wordToNumber.put("four", 4);
        wordToNumber.put("five", 5);
        wordToNumber.put("six", 6);
        wordToNumber.put("seven", 7);
        wordToNumber.put("eight", 8);
        wordToNumber.put("nine", 9);

        // Validate each word and collect results
        List<String> result = new ArrayList<>();
        for (String word : numberWords) {
            String lowerWord = word.toLowerCase();
            if (!wordToNumber.containsKey(lowerWord)) {
                throw new IllegalArgumentException("Invalid number word: '" + word + "'");
            }
            result.add(word); // Keep original casing in output
        }

        // Sort based on numeric value using custom comparator
        result.sort(Comparator.comparing(word -> wordToNumber.get(word.toLowerCase())));

        // Join the sorted words back into a space-delimited string
        return String.join(" ", result);
    }
}

