class Solution {
    /**
     * Rescales a list of numbers to the unit interval [0, 1] using min-max normalization.
     * The smallest value in the input list becomes 0.0 and the largest becomes 1.0.
     * All other values are scaled linearly between these bounds.
     * 
     * @param numbers a list of Double values with at least two elements
     * @return a new list containing the rescaled values
     * @throws IllegalArgumentException if the input list has fewer than two elements
     * @throws NullPointerException if the input list is null or contains null elements
     */
    public List<Double> rescaleToUnit(List<Double> numbers) {
        if (numbers == null) {
            throw new NullPointerException("Input list cannot be null");
        }

        if (numbers.size() < 2) {
            throw new IllegalArgumentException("Input list must have at least two elements");
        }

        // Find min and max values
        double min = Double.POSITIVE_INFINITY;
        double max = Double.NEGATIVE_INFINITY;

        for (Double num : numbers) {
            if (num == null) {
                throw new NullPointerException("List elements cannot be null");
            }
            min = Math.min(min, num);
            max = Math.max(max, num);
        }

        // Handle case where all values are the same (avoid division by zero)
        if (min == max) {
            // If all values are equal, return list of zeros (or could return all 0.5s, but zeros make sense)
            List<Double> result = new ArrayList<>(numbers.size());
            for (int i = 0; i < numbers.size(); i++) {
                result.add(0.0);
            }
            return result;
        }

        double range = max - min;
        List<Double> result = new ArrayList<>(numbers.size());

        for (Double num : numbers) {
            double scaled = (num - min) / range;
            result.add(scaled);
        }

        return result;
    }
}

