class Solution {
    /**
     * For a given number n, find the largest number that divides n evenly, smaller than n.
     * 
     * @param n the input number (must be greater than 1)
     * @return the largest proper divisor of n
     * @throws IllegalArgumentException if n <= 1
     * 
     * >>> largestDivisor(15)
     * 5
     */
    public int largestDivisor(int n) {
        if (n <= 1) {
            throw new IllegalArgumentException("n must be greater than 1");
        }

        // The largest proper divisor of n is at most n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // This should never be reached for n > 1, since 1 always divides n
        return 1;
    }
}

