class Solution {
    /**
     * Return list of prime factors of given integer in the order from smallest to largest.
     * Each of the factors should be listed number of times corresponding to how many times it appears in factorization.
     * The input number should be equal to the product of all factors.
     * 
     * @param n the integer to factorize (must be >= 2)
     * @return list of prime factors in ascending order
     * @throws IllegalArgumentException if n < 2
     * 
     * Examples:
     * <pre>
     * factorize(8)  returns [2, 2, 2]
     * factorize(25) returns [5, 5]
     * factorize(70) returns [2, 5, 7]
     * </pre>
     */
    public List<Integer> factorize(int n) {
        if (n < 2) {
            throw new IllegalArgumentException("Input must be >= 2");
        }

        List<Integer> factors = new ArrayList<>();

        // Handle factor of 2
        while (n % 2 == 0) {
            factors.add(2);
            n /= 2;
        }

        // Check odd factors starting from 3
        for (int i = 3; i * i <= n; i += 2) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }

        // If n is still greater than 1, then it's a prime factor
        if (n > 1) {
            factors.add(n);
        }

        return factors;
    }
}

