    /**
     * From a list of integers, remove all elements that occur more than once.
     * Keep order of elements left the same as in the input.
     * 
     * @param numbers the input list of integers (may contain duplicates)
     * @return a new list containing only elements that appear exactly once in the input,
     *         preserving the original order
     * @throws NullPointerException if the input list is null
     * 
     * >>> removeDuplicates(Arrays.asList(1, 2, 3, 2, 4))
     * [1, 3, 4]
     */
    public List<Integer> removeDuplicates(List<Integer> numbers) {
        if (numbers == null) {
            throw new NullPointerException("Input list cannot be null");
        }

        // First pass: count occurrences of each number
        Map<Integer, Integer> counts = new HashMap<>();
        for (Integer num : numbers) {
            counts.put(num, counts.getOrDefault(num, 0) + 1);
        }

        // Second pass: collect only those numbers that appear exactly once
        List<Integer> result = new ArrayList<>();
        for (Integer num : numbers) {
            if (counts.get(num) == 1) {
                result.add(num);
            }
        }

        return result;
    }
}

