class Solution {
    /**
     * Flips the case of each alphabetic character in the given string.
     * Lowercase characters are converted to uppercase, and uppercase characters
     * are converted to lowercase. Non-alphabetic characters remain unchanged.
     *
     * @param string the input string to process (may be null)
     * @return a new string with the case of all alphabetic characters flipped,
     *         or the same string if no changes were made
     * @throws NullPointerException if the input string is null
     *
     * @implSpec This method iterates through each character in the string,
     *           checks if it is alphabetic, and flips its case if so.
     */
    public String flipCase(String string) {
        if (string == null) {
            throw new NullPointerException("Input string cannot be null");
        }

        StringBuilder result = new StringBuilder(string.length());

        for (char c : string.toCharArray()) {
            if (Character.isLowerCase(c)) {
                result.append(Character.toUpperCase(c));
            } else if (Character.isUpperCase(c)) {
                result.append(Character.toLowerCase(c));
            } else {
                result.append(c);
            }
        }

        return result.toString();
    }
}

