class Solution {
    /**
     * Returns true if the given integer is a prime number, and false otherwise.
     * <p>
     * A prime number is a natural number greater than 1 that has no positive divisors other than 1 and itself.
     * 
     * @param n the integer to test for primality
     * @return true if n is prime, false otherwise
     * @implSpec This method uses trial division up to the square root of n to check for divisibility.
     *           Numbers less than 2 are not prime. For numbers ≥ 2, the method checks divisibility
     *           by 2 and then checks odd numbers from 3 up to √n.
     * @apiNote This method is efficient for reasonably sized integers but may be slow for very large numbers.
     *          For cryptographic applications with very large numbers, consider using probabilistic primality tests.
     * 
     * <pre>{@code
     * >>> isPrime(6)
     * false
     * >>> isPrime(101)
     * true
     * >>> isPrime(11)
     * true
     * >>> isPrime(13441)
     * true
     * >>> isPrime(61)
     * true
     * >>> isPrime(4)
     * false
     * >>> isPrime(1)
     * false
     * }</pre>
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to √n
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

