class Solution {
    /**
     * Evaluates polynomial with coefficients xs at point x.
     * @param xs coefficients list where xs[i] is coefficient of x^i
     * @param x the point at which to evaluate the polynomial
     * @return the value of the polynomial at x
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
     * Finds a zero of the polynomial defined by coefficients xs.
     * Requires xs to have an even number of coefficients (odd degree polynomial),
     * and guarantees at least one real root exists.
     * 
     * Uses Newton-Raphson method starting from initial guess x=0.
     * Returns only one zero, even if multiple zeros exist.
     * 
     * @param xs coefficients list where xs[i] is coefficient of x^i
     * @return a value x such that poly(xs, x) ≈ 0
     * @throws IllegalArgumentException if xs has odd number of elements or is empty
     */
    public double findZero(List<Double> xs) {
        if (xs == null || xs.isEmpty() || xs.size() % 2 == 0 && xs.size() <= 1) {
            throw new IllegalArgumentException("Polynomial must have even number of coefficients (>1)");
        }

        // Newton-Raphson method
        double x = 0.0; // initial guess
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative
            double fpx = polyDerivative(xs, x);

            // Avoid division by zero
            if (Math.abs(fpx) < tolerance) {
                // Try a different starting point
                x += 0.5;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < tolerance) {
                return xNext;
            }

            x = xNext;
        }

        // Fallback: return last approximation
        return x;
    }

    /**
     * Evaluates the derivative of the polynomial with coefficients xs at point x.
     * @param xs coefficients list where xs[i] is coefficient of x^i
     * @param x the point at which to evaluate the derivative
     * @return the value of the derivative at x
     */
    private double polyDerivative(List<Double> xs, double x) {
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

