class Solution {
    /**
     * Returns a new list where elements at indices divisible by 3 are sorted in ascending order,
     * while elements at other indices remain unchanged.
     *
     * <p>The resulting list has the same length and structure as the input list, except that
     * the elements at indices 0, 3, 6, ... (i.e., indices divisible by 3) are replaced with
     * those same elements sorted in natural order.
     *
     * @param l the input list of integers; must not be null
     * @return a new list with elements at indices divisible by 3 sorted in ascending order
     * @throws NullPointerException if the input list is null
     * @throws IllegalArgumentException if the input list contains null elements
     * @implSpec The method creates a copy of the input list, extracts elements at indices
     *           divisible by 3, sorts them, and places them back in the same positions.
     */
    public List<Integer> sortThird(List<Integer> l) {
        if (l == null) {
            throw new NullPointerException("Input list must not be null");
        }

        // Create a copy of the original list
        List<Integer> result = new ArrayList<>(l);

        // Collect elements at indices divisible by 3
        List<Integer> thirdElements = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 3) {
            Integer value = l.get(i);
            if (value == null) {
                throw new IllegalArgumentException("List elements must not be null");
            }
            thirdElements.add(value);
        }

        // Sort the collected elements
        Collections.sort(thirdElements);

        // Place sorted elements back at indices divisible by 3
        int sortedIndex = 0;
        for (int i = 0; i < result.size(); i += 3) {
            result.set(i, thirdElements.get(sortedIndex++));
        }

        return result;
    }
}

