class Solution {
    /**
     * Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13.
     *
     * @param n the upper bound (exclusive) for checking integers
     * @return the count of digit 7 occurrences in qualifying numbers
     * @see #containsDigitSeven(int)
     */
    public int fizzBuzz(int n) {
        int count = 0;

        // Check all numbers from 1 to n-1
        for (int i = 1; i < n; i++) {
            // Check if divisible by 11 or 13
            if (i % 11 == 0 || i % 13 == 0) {
                count += countDigitSeven(i);
            }
        }

        return count;
    }

    /**
     * Count occurrences of digit 7 in the decimal representation of a number.
     *
     * @param num the number to check
     * @return the number of times digit 7 appears in num
     */
    private int countDigitSeven(int num) {
        int count = 0;
        int n = Math.abs(num);

        while (n > 0) {
            if (n % 10 == 7) {
                count++;
            }
            n /= 10;
        }

        return count;
    }
}

