class Solution {
    /**
     * Encodes a string by cycling groups of three characters.
     * For each group of exactly three characters, moves the first character to the end.
     * Groups with fewer than three characters remain unchanged.
     *
     * @param s the string to encode
     * @return the encoded string
     */
    public String encodeCyclic(String s) {
        // split string to groups. Each of length 3.
        List<String> groups = new ArrayList<>();
        for (int i = 0; i < s.length(); i += 3) {
            groups.add(s.substring(i, Math.min(i + 3, s.length())));
        }
        // cycle elements in each group. Unless group has fewer elements than 3.
        for (int i = 0; i < groups.size(); i++) {
            if (groups.get(i).length() == 3) {
                groups.set(i, groups.get(i).substring(1) + groups.get(i).charAt(0));
            }
        }
        return String.join("", groups);
    }

    /**
     * Decodes a string that was encoded with the encodeCyclic function.
     * Reverses the cyclic shift by moving the last character of each 3-character group to the front.
     * Groups with fewer than three characters remain unchanged.
     *
     * @param s the encoded string
     * @return the decoded string
     */
    public String decodeCyclic(String s) {
        // split string to groups. Each of length 3.
        List<String> groups = new ArrayList<>();
        for (int i = 0; i < s.length(); i += 3) {
            groups.add(s.substring(i, Math.min(i + 3, s.length())));
        }
        // reverse cycle: move last character to front for groups of length 3
        for (int i = 0; i < groups.size(); i++) {
            if (groups.get(i).length() == 3) {
                groups.set(i, groups.get(i).charAt(2) + groups.get(i).substring(0, 2));
            }
        }
        return String.join("", groups);
    }
}

