class Solution {
    /**
     * Returns the n-th number that is both a Fibonacci number and prime.
     * 
     * @param n the position (1-indexed) of the prime Fibonacci number to find
     * @return the n-th prime Fibonacci number
     * @throws IllegalArgumentException if n is less than 1
     * 
     * <p>The sequence of prime Fibonacci numbers begins: 2, 3, 5, 13, 89, 233, ...
     * 
     * <p><b>Precondition:</b> n >= 1
     * <p><b>Postcondition:</b> Returns the n-th smallest prime number that is also a Fibonacci number.
     */
    public int primeFib(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0, b = 1; // Fibonacci sequence starts with 0, 1

        while (true) {
            long next = a + b;
            a = b;
            b = next;

            if (isPrime(a)) {
                count++;
                if (count == n) {
                    return (int) a;
                }
            }
        }
    }

    /**
     * Checks if a number is prime.
     * 
     * @param num the number to check
     * @return true if the number is prime, false otherwise
     */
    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

