class Solution {
    /**
     * Separates a string containing multiple groups of nested parentheses into individual balanced groups.
     * 
     * @param paren_string a string containing multiple groups of nested parentheses, possibly with spaces
     * @return a list of strings where each string is a balanced group of parentheses
     * @throws IllegalArgumentException if the parentheses are unbalanced
     */
    public List<String> separateParenGroups(String paren_string) {
        List<String> groups = new ArrayList<>();

        // Remove all spaces from the input string
        String cleaned = paren_string.replace(" ", "");

        int balance = 0;
        StringBuilder currentGroup = new StringBuilder();

        for (char c : cleaned.toCharArray()) {
            if (c == '(') {
                balance++;
                currentGroup.append(c);
            } else if (c == ')') {
                balance--;
                currentGroup.append(c);

                // When balance reaches 0, we've completed a balanced group
                if (balance == 0) {
                    groups.add(currentGroup.toString());
                    currentGroup.setLength(0); // Reset for next group
                }
            }
        }

        // Check for unbalanced parentheses
        if (balance != 0) {
            throw new IllegalArgumentException("Unbalanced parentheses in input");
        }

        return groups;
    }
}

