class Solution {
    /**
     * Calculates the Mean Absolute Deviation (MAD) of a list of numbers.
     * <p>
     * MAD is defined as the average of the absolute deviations from the mean:
     * MAD = (1/n) * Σ|xi - x̄|, where x̄ is the mean of the dataset.
     *
     * @param numbers list of numeric values; must not be null or empty
     * @return the mean absolute deviation of the values in the list
     * @throws IllegalArgumentException if the input list is null or empty
     */
    public double meanAbsoluteDeviation(List<Double> numbers) {
        if (numbers == null || numbers.isEmpty()) {
            throw new IllegalArgumentException("Input list must not be null or empty");
        }

        // Calculate the mean
        double sum = 0.0;
        for (Double num : numbers) {
            if (num == null) {
                throw new IllegalArgumentException("List contains null values");
            }
            sum += num;
        }
        double mean = sum / numbers.size();

        // Calculate the mean absolute deviation
        double totalAbsoluteDeviation = 0.0;
        for (Double num : numbers) {
            totalAbsoluteDeviation += Math.abs(num - mean);
        }

        return totalAbsoluteDeviation / numbers.size();
    }
}

