class Solution {
    /**
     * Parses a string containing groups of nested parentheses and returns the
     * maximum nesting depth for each group.
     *
     * <p>The input string consists of one or more groups of parentheses,
     * separated by single spaces. Each group is analyzed independently to
     * determine its maximum nesting depth.
     *
     * @param paren_string a string containing space-separated groups of parentheses
     * @return a list of integers representing the maximum nesting depth of each group
     * @throws IllegalArgumentException if the input contains invalid characters or unbalanced parentheses
     *
     * @example
     * parseNestedParens("(()()) ((())) () ((())()())") returns [2, 3, 1, 3]
     */
    public List<Integer> parseNestedParens(String paren_string) {
        List<Integer> result = new ArrayList<>();

        if (paren_string == null || paren_string.trim().isEmpty()) {
            return result;
        }

        String[] groups = paren_string.split(" ");

        for (String group : groups) {
            int maxDepth = 0;
            int currentDepth = 0;

            for (int i = 0; i < group.length(); i++) {
                char c = group.charAt(i);

                if (c == '(') {
                    currentDepth++;
                    maxDepth = Math.max(maxDepth, currentDepth);
                } else if (c == ')') {
                    currentDepth--;
                } else {
                    throw new IllegalArgumentException("Invalid character '" + c + "' in group: " + group);
                }
            }

            // Validate that parentheses are balanced
            if (currentDepth != 0) {
                throw new IllegalArgumentException("Unbalanced parentheses in group: " + group);
            }

            result.add(maxDepth);
        }

        return result;
    }
}

