class Solution {
    /**
     * Test if given string is a palindrome.
     *
     * @param string the string to test
     * @return true if the string is a palindrome, false otherwise
     */
    public boolean isPalindrome(String string) {
        int i = 0;
        int j = string.length() - 1;
        while (i < j) {
            if (string.charAt(i) != string.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    /**
     * Find the shortest palindrome that begins with a supplied string.
     * <p>
     * Algorithm idea is simple:
     * - Find the longest suffix of supplied string that is a palindrome.
     * - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
     *
     * @param string the input string
     * @return the shortest palindrome that begins with the supplied string
     * @throws NullPointerException if the input string is null
     */
    public String makePalindrome(String string) {
        if (string == null) {
            throw new NullPointerException("Input string cannot be null");
        }

        // Find the longest suffix that is a palindrome
        for (int i = 0; i < string.length(); i++) {
            if (isPalindrome(string.substring(i))) {
                // Append reverse of the prefix (string[0..i-1]) to the end
                String prefix = string.substring(0, i);
                String reversedPrefix = new StringBuilder(prefix).reverse().toString();
                return string + reversedPrefix;
            }
        }

        // This should never be reached since a single character is always a palindrome
        return string;
    }
}

