class Solution {
    /**
     * Returns the greatest common divisor of two integers.
     *
     * @param a first integer
     * @param b second integer
     * @return the greatest common divisor of a and b
     * @throws IllegalArgumentException if both a and b are zero
     */
    public int greatestCommonDivisor(int a, int b) {
        // Handle edge case where both numbers are zero
        if (a == 0 && b == 0) {
            throw new IllegalArgumentException("Both arguments cannot be zero");
        }

        // Use absolute values to handle negative numbers
        a = Math.abs(a);
        b = Math.abs(b);

        // Euclidean algorithm
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }

        return a;
    }
}

