class Solution {
    /**
     * Returns the number of occurrences of the specified substring in the given string,
     * counting overlapping occurrences.
     *
     * @param string the string to search in
     * @param substring the substring to search for
     * @return the number of times the substring appears in the string, including overlaps
     * @throws IllegalArgumentException if substring is null
     */
    public int howManyTimes(String string, String substring) {
        // Handle edge cases
        if (string == null || substring == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        // Empty substring case: by convention, count as 0 (though could be argued differently)
        if (substring.isEmpty()) {
            return 0;
        }

        // Empty string case: no matches possible
        if (string.isEmpty()) {
            return 0;
        }

        int count = 0;
        int length = string.length();
        int subLength = substring.length();

        // Check each possible starting position
        for (int i = 0; i <= length - subLength; i++) {
            if (string.substring(i, i + subLength).equals(substring)) {
                count++;
            }
        }

        return count;
    }
}

