class Solution {
    /**
     * Sorts a space-delimited string of number words from "zero" to "nine" in ascending numerical order.
     *
     * @param numbers space-delimited string of number words from 'zero' to 'nine'
     * @return string with numbers sorted from smallest to largest, space-delimited
     * @throws IllegalArgumentException if any word is not a valid number word
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        // Map number words to their numeric values
        Map<String, Integer> wordToNumber = new HashMap<>();
        wordToNumber.put("zero", 0);
        wordToNumber.put("one", 1);
        wordToNumber.put("two", 2);
        wordToNumber.put("three", 3);
        wordToNumber.put("four", 4);
        wordToNumber.put("five", 5);
        wordToNumber.put("six", 6);
        wordToNumber.put("seven", 7);
        wordToNumber.put("eight", 8);
        wordToNumber.put("nine", 9);

        // Split input string into individual words
        String[] words = numbers.split("\\s+");
        List<Integer> numbersList = new ArrayList<>();

        // Convert words to numbers
        for (String word : words) {
            if (!wordToNumber.containsKey(word)) {
                throw new IllegalArgumentException("Invalid number word: '" + word + "'");
            }
            numbersList.add(wordToNumber.get(word));
        }

        // Sort the numbers
        Collections.sort(numbersList);

        // Build reverse map for conversion back to words
        Map<Integer, String> numberToWord = new HashMap<>();
        numberToWord.put(0, "zero");
        numberToWord.put(1, "one");
        numberToWord.put(2, "two");
        numberToWord.put(3, "three");
        numberToWord.put(4, "four");
        numberToWord.put(5, "five");
        numberToWord.put(6, "six");
        numberToWord.put(7, "seven");
        numberToWord.put(8, "eight");
        numberToWord.put(9, "nine");

        // Convert sorted numbers back to words
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < numbersList.size(); i++) {
            if (i > 0) {
                result.append(" ");
            }
            result.append(numberToWord.get(numbersList.get(i)));
        }

        return result.toString();
    }
}

