class Solution {
    /**
     * Rescales a list of numbers to the unit interval [0, 1].
     * The minimum value in the input list becomes 0.0, and the maximum becomes 1.0.
     * All other values are scaled linearly between these extremes.
     *
     * <p>If all values in the input list are equal, the method returns a list of zeros.
     *
     * @param numbers list of numeric values to rescale; must contain at least two elements
     * @return a new list containing the rescaled values in the range [0.0, 1.0]
     * @throws IllegalArgumentException if the input list is null or has fewer than two elements
     */
    public List<Double> rescaleToUnit(List<Double> numbers) {
        if (numbers == null) {
            throw new IllegalArgumentException("Input list cannot be null");
        }

        if (numbers.size() < 2) {
            throw new IllegalArgumentException("Input list must contain at least two elements");
        }

        // Find minimum and maximum values
        double min = Double.MAX_VALUE;
        double max = Double.MIN_VALUE;

        for (Double value : numbers) {
            if (value == null) {
                throw new IllegalArgumentException("List cannot contain null values");
            }
            if (value < min) {
                min = value;
            }
            if (value > max) {
                max = value;
            }
        }

        // Create result list
        List<Double> result = new ArrayList<>(numbers.size());

        // Handle case where all values are the same (avoid division by zero)
        if (max == min) {
            // All values are identical, return list of zeros
            for (int i = 0; i < numbers.size(); i++) {
                result.add(0.0);
            }
            return result;
        }

        // Apply min-max normalization
        double range = max - min;
        for (Double value : numbers) {
            result.add((value - min) / range);
        }

        return result;
    }
}

