class Solution {
    /**
     * Returns the largest divisor of {@code n} that is smaller than {@code n}.
     *
     * @param n the number to find the largest proper divisor for; must be greater than 1
     * @return the largest integer that divides {@code n} evenly and is less than {@code n}
     * @throws IllegalArgumentException if {@code n <= 1}
     */
    public int largestDivisor(int n) {
        if (n <= 1) {
            throw new IllegalArgumentException("n must be greater than 1");
        }

        // The largest proper divisor cannot be larger than n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // This line should never be reached for n > 1, since 1 always divides n
        return 1;
    }
}

