class Solution {
    /**
     * Returns the list of prime factors of the given integer in ascending order.
     * Each prime factor appears in the list as many times as it divides the number.
     * 
     * <p>The product of all returned factors equals the input number.
     * 
     * @param n the integer to factorize; must be greater than 1
     * @return list of prime factors in ascending order
     * @throws IllegalArgumentException if n is less than or equal to 1
     * 
     * @implSpec
     * The implementation uses trial division, checking divisibility by integers
     * starting from 2 up to sqrt(n), then adding any remaining prime factor.
     * 
     * @apiNote
     * For example, factorize(8) returns [2, 2, 2] because 8 = 2 × 2 × 2.
     */
    public List<Integer> factorize(int n) {
        if (n <= 1) {
            throw new IllegalArgumentException("Input must be greater than 1");
        }

        List<Integer> factors = new ArrayList<>();

        // Check for factor 2 separately to optimize for odd numbers afterward
        while (n % 2 == 0) {
            factors.add(2);
            n /= 2;
        }

        // Check odd factors starting from 3
        for (int i = 3; i * i <= n; i += 2) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }

        // If n is still greater than 1, it's a prime factor
        if (n > 1) {
            factors.add(n);
        }

        return factors;
    }
}

