class Solution {
    /**
     * From a list of integers, remove all elements that occur more than once.
     * Keep order of elements left the same as in the input.
     *
     * <p>For example, {@code removeDuplicates(Arrays.asList(1, 2, 3, 2, 4))} returns {@code [1, 3, 4]}.
     *
     * @param numbers the list of integers to process; may be null or contain null elements
     * @return a new list containing only elements that appear exactly once in the input, in their original order
     * @throws NullPointerException if the input list is null
     */
    public List<Integer> removeDuplicates(List<Integer> numbers) {
        if (numbers == null) {
            throw new NullPointerException("Input list cannot be null");
        }

        // Count occurrences of each element
        Map<Integer, Long> counts = numbers.stream()
                .filter(Objects::nonNull)
                .collect(Collectors.groupingBy(num -> num, Collectors.counting()));

        // Filter to keep only elements that appear exactly once
        List<Integer> result = new ArrayList<>();
        for (Integer num : numbers) {
            if (num != null && counts.getOrDefault(num, 0L) == 1L) {
                result.add(num);
            }
        }

        return result;
    }
}

