class Solution {
    /**
     * Evaluates polynomial with coefficients xs at point x.
     * return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     *
     * @param xs coefficients of the polynomial; xs[i] is the coefficient of x^i
     * @param x the point at which to evaluate the polynomial
     * @return the value of the polynomial at point x
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
     * Finds a zero of the polynomial defined by coefficients xs.
     * Only works for polynomials with an even number of coefficients (odd degree),
     * which guarantees at least one real root.
     *
     * @param xs coefficients of the polynomial; xs[i] is the coefficient of x^i,
     *           must have even size (odd degree polynomial)
     * @return a value x such that poly(xs, x) ≈ 0
     * @throws IllegalArgumentException if xs has odd size (no real root guaranteed)
     */
    public double findZero(List<Double> xs) {
        // Check that xs has even number of coefficients (odd degree)
        if (xs.size() % 2 == 0) {
            throw new IllegalArgumentException("Polynomial must have even number of coefficients (odd degree)");
        }

        // Handle edge case of constant polynomial (degree 0)
        if (xs.size() == 1) {
            return 0.0; // or throw exception - constant polynomial has no root unless it's zero
        }

        // Find a reasonable search interval using the leading coefficient
        double leadingCoeff = xs.get(xs.size() - 1);

        // Start with a reasonable interval
        double left = -1000.0;
        double right = 1000.0;

        // Expand interval until we bracket a root
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 10;
            right *= 10;
            // Safety check to prevent infinite loop
            if (Math.abs(left) > 1e10) {
                throw new RuntimeException("Could not find bracketing interval");
            }
        }

        // Binary search (bisection method) for root
        double mid = 0;
        int iterations = 100; // Sufficient precision for double
        for (int i = 0; i < iterations; i++) {
            mid = (left + right) / 2.0;
            double valueAtMid = poly(xs, mid);

            if (Math.abs(valueAtMid) < 1e-9) {
                break;
            }

            if (poly(xs, left) * valueAtMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return mid;
    }
}

