class Solution {
    /**
     * Returns a new list where elements at indices divisible by three are sorted,
     * while elements at other indices remain unchanged.
     *
     * <p>The elements at indices i where i % 3 == 0 are extracted, sorted in ascending order,
     * and placed back at those same indices. All other elements are left in their original positions.
     *
     * @param l the input list of integers; may be empty or null
     * @return a new list with elements at indices divisible by three sorted
     * @throws NullPointerException if the input list l is null
     */
    public List<Integer> sortThird(List<Integer> l) {
        if (l == null) {
            throw new NullPointerException("Input list cannot be null");
        }

        // Create a copy of the input list to avoid modifying the original
        List<Integer> result = new ArrayList<>(l);

        // Collect elements at indices divisible by 3
        List<Integer> divisibleByThree = new ArrayList<>();
        for (int i = 0; i < l.size(); i++) {
            if (i % 3 == 0) {
                divisibleByThree.add(l.get(i));
            }
        }

        // Sort these elements
        Collections.sort(divisibleByThree);

        // Place sorted elements back at their positions
        int sortedIndex = 0;
        for (int i = 0; i < result.size(); i++) {
            if (i % 3 == 0) {
                result.set(i, divisibleByThree.get(sortedIndex++));
            }
        }

        return result;
    }
}

