class Solution {
    /**
     * Returns the number of times the digit 7 appears in integers less than n 
     * which are divisible by 11 or 13.
     *
     * @param n the upper bound (exclusive); must be non-negative
     * @return the count of digit 7 occurrences in qualifying numbers
     */
    public int fizzBuzz(int n) {
        int count = 0;

        // Check all numbers from 1 to n-1
        for (int i = 1; i < n; i++) {
            // Check if divisible by 11 or 13
            if (i % 11 == 0 || i % 13 == 0) {
                // Count occurrences of digit 7 in this number
                int num = i;
                while (num > 0) {
                    if (num % 10 == 7) {
                        count++;
                    }
                    num /= 10;
                }
            }
        }

        return count;
    }
}

