class Solution {
    /**
     * Returns the encoded string by cycling groups of three characters.
     *
     * <p>Each group of three consecutive characters is transformed by moving
     * the first character to the end. For example, "abc" becomes "bca".
     * Groups with fewer than three characters remain unchanged.
     *
     * @param s the string to encode
     * @return the encoded string
     */
    public String encodeCyclic(String s) {
        // split string to groups. Each of length 3.
        List<String> groups = new ArrayList<>();
        for (int i = 0; i < s.length(); i += 3) {
            groups.add(s.substring(i, Math.min(i + 3, s.length())));
        }
        // cycle elements in each group. Unless group has fewer elements than 3.
        for (int i = 0; i < groups.size(); i++) {
            if (groups.get(i).length() == 3) {
                groups.set(i, groups.get(i).substring(1) + groups.get(i).charAt(0));
            }
        }
        return String.join("", groups);
    }

    /**
     * Returns the decoded string from an encoded string produced by encodeCyclic.
     *
     * <p>Each group of three characters is transformed by moving the last character
     * to the front. For example, "bca" becomes "abc". Groups with fewer than three
     * characters remain unchanged.
     *
     * @param s the encoded string
     * @return the original string before encoding
     */
    public String decodeCyclic(String s) {
        // split string to groups. Each of length 3.
        List<String> groups = new ArrayList<>();
        for (int i = 0; i < s.length(); i += 3) {
            groups.add(s.substring(i, Math.min(i + 3, s.length())));
        }
        // reverse the cycle in each group. Unless group has fewer elements than 3.
        for (int i = 0; i < groups.size(); i++) {
            if (groups.get(i).length() == 3) {
                groups.set(i, groups.get(i).charAt(groups.get(i).length() - 1) + groups.get(i).substring(0, groups.get(i).length() - 1));
            }
        }
        return String.join("", groups);
    }
}

