class Solution {
    /**
     * Returns the n-th number that is both a Fibonacci number and prime.
     *
     * @param n the position of the Fibonacci prime to return (1-indexed)
     * @return the n-th Fibonacci prime number
     * @throws IllegalArgumentException if n is less than 1
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 0; // F(0)
        int b = 1; // F(1)

        // Handle special case: check F(0) = 0 (not prime), F(1) = 1 (not prime)
        // Start from F(2) = 1

        // We'll generate Fibonacci numbers and check for primality
        if (n == 1) {
            return 2; // First Fibonacci prime is 2 (F(3))
        }

        // Generate Fibonacci sequence starting from F(3) = 2
        int fib = 2; // F(3)
        int index = 3;

        // We already know the first Fibonacci prime is 2
        count = 1;

        while (count < n) {
            if (isPrime(fib)) {
                count++;
                if (count == n) {
                    return fib;
                }
            }

            // Generate next Fibonacci number
            int next = a + b;
            a = b;
            b = next;
            fib = next;
            index++;
        }

        return fib;
    }

    /**
     * Checks if a number is prime.
     *
     * @param num the number to check
     * @return true if the number is prime, false otherwise
     */
    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        int sqrt = (int) Math.sqrt(num);
        for (int i = 3; i <= sqrt; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

