class Solution {
    /**
     * For a given list of input numbers, calculate Mean Absolute Deviation
     * around the mean of this dataset.
     * <p>
     * Mean Absolute Deviation is the average absolute difference between each
     * element and a centerpoint (mean in this case):
     * <blockquote>
     * MAD = average | x - x_mean |
     * </blockquote>
     *
     * @param numbers the list of numbers to analyze (must not be null or empty)
     * @return the mean absolute deviation of the numbers
     * @throws IllegalArgumentException if the input list is null or empty
     * @implSpec
     * This implementation computes the arithmetic mean first, then calculates
     * the average of the absolute deviations from that mean.
     */
    public double meanAbsoluteDeviation(List<Double> numbers) {
        // Validate input
        if (numbers == null || numbers.isEmpty()) {
            throw new IllegalArgumentException("Input list must not be null or empty");
        }

        // Step 1: Calculate the mean
        double sum = 0.0;
        for (Double num : numbers) {
            if (num == null) {
                throw new IllegalArgumentException("List must not contain null values");
            }
            sum += num;
        }
        double mean = sum / numbers.size();

        // Step 2: Calculate the mean of absolute deviations
        double totalAbsoluteDeviation = 0.0;
        for (Double num : numbers) {
            totalAbsoluteDeviation += Math.abs(num - mean);
        }

        return totalAbsoluteDeviation / numbers.size();
    }
}

