class Solution {
    /**
     * Returns the longest string from the given list.
     * In case of multiple strings of the same maximum length, returns the first one.
     * Returns {@link Optional#empty()} if the input list is empty.
     *
     * @param strings the list of strings to search
     * @return an {@link Optional} containing the longest string, or {@link Optional#empty()} if the list is empty
     * @implSpec
     *   This implementation iterates through the list once, keeping track of the longest string seen so far.
     *   If the list is empty, it returns {@link Optional#empty()}.
     *   When multiple strings have the same maximum length, the first one encountered is returned.
     * @apiNote
     *   This method performs a linear scan of the input list.
     */
    public Optional<String> longest(List<String> strings) {
        if (strings == null || strings.isEmpty()) {
            return Optional.empty();
        }

        String longest = strings.get(0);
        for (int i = 1; i < strings.size(); i++) {
            String current = strings.get(i);
            if (current.length() > longest.length()) {
                longest = current;
            }
        }

        return Optional.of(longest);
    }
}

