    public List<Integer> parseMusic(String string) {
        List<Integer> result = new ArrayList<>();

        // Handle empty or null input
        if (string == null || string.trim().isEmpty()) {
            return result;
        }

        // Split by whitespace to get individual notes
        String[] notes = string.trim().split("\\s+");

        for (String note : notes) {
            switch (note) {
                case "o":
                    result.add(4);  // whole note
                    break;
                case "o|":
                    result.add(2);  // half note
                    break;
                case ".|":
                    result.add(1);  // quarter note
                    break;
                default:
                    // According to the problem statement, we only expect the three note types,
                    // but if an unknown note appears, we could either skip it or throw an exception.
                    // Given the problem context, we'll skip unknown notes.
                    break;
            }
        }

        return result;
    }
