class Solution {
    /**
     * Find how many times a given substring can be found in the original string. Count overlapping cases.
     *
     * @implSpec
     * This implementation iterates through each possible starting position in the string
     * and checks if the substring matches from that position, counting all occurrences
     * including overlapping ones.
     *
     * @param string the string to search in
     * @param substring the substring to search for
     * @return the number of times the substring appears in the string, including overlapping cases
     * @see String#indexOf(String, int)
     */
    public int howManyTimes(String string, String substring) {
        // Handle edge cases
        if (string == null || substring == null) {
            return 0;
        }

        // If substring is empty, return 0 (no meaningful matches)
        if (substring.isEmpty()) {
            return 0;
        }

        // If substring is longer than string, no matches possible
        if (substring.length() > string.length()) {
            return 0;
        }

        int count = 0;
        // Check each possible starting position
        for (int i = 0; i <= string.length() - substring.length(); i++) {
            if (string.substring(i, i + substring.length()).equals(substring)) {
                count++;
            }
        }

        return count;
    }
}

