class Solution {
    /**
     * For a given number n, find the largest number that divides n evenly, smaller than n.
     * 
     * @implSpec
     * This implementation finds the largest proper divisor by computing 
     * {@code n / p} where {@literal p} is the smallest prime factor of {@code n}.
     * If {@code n} is prime, the result is 1.
     * 
     * @param n the number to find the largest proper divisor for (must be > 1)
     * @return the largest divisor of n that is less than n
     * @throws IllegalArgumentException if n <= 1
     * 
     * >>> largestDivisor(15)
     * 5
     */
    public int largestDivisor(int n) {
        if (n <= 1) {
            throw new IllegalArgumentException("n must be greater than 1");
        }

        // If n is even, the largest proper divisor is n/2
        if (n % 2 == 0) {
            return n / 2;
        }

        // For odd n, find the smallest prime factor
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                // Found smallest factor i, so largest proper divisor is n/i
                return n / i;
            }
        }

        // If no factors found, n is prime, so largest proper divisor is 1
        return 1;
    }
}

