class Solution {
    /**
     * Returns list of prime factors of given integer in the order from smallest to largest.
     * Each of the factors should be listed number of times corresponding to how many times it appears in factorization.
     * Input number should be equal to the product of all factors.
     * 
     * @param n the integer to factorize (must be >= 2)
     * @return list of prime factors in ascending order
     * @implSpec
     * This implementation uses trial division: first extracting all factors of 2,
     * then checking odd divisors from 3 up to sqrt(n). If any remainder remains
     * after division by all primes up to sqrt(n), that remainder is itself prime.
     * 
     * @apiNote
     * For n &lt; 2, returns an empty list.
     */
    public List<Integer> factorize(int n) {
        List<Integer> factors = new ArrayList<>();

        // Handle edge cases
        if (n <= 1) {
            return factors;
        }

        // Extract all factors of 2
        while (n % 2 == 0) {
            factors.add(2);
            n /= 2;
        }

        // Check odd factors starting from 3
        for (int i = 3; i * i <= n; i += 2) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }

        // If n is still greater than 1, then it is a prime factor
        if (n > 1) {
            factors.add(n);
        }

        return factors;
    }
}

