class Solution {
    /**
     * Evaluates polynomial with coefficients xs at point x.
     * return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     *
     * @implSpec
     * This implementation uses Horner's method for numerical stability.
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
     * xs are coefficients of a polynomial.
     * findZero finds x such that poly(x) = 0.
     * findZero returns only one zero point, even if there are many.
     * Moreover, findZero only takes list xs having even number of coefficients
     * and largest non-zero coefficient as it guarantees
     * a solution.
     *
     * @implSpec
     * This implementation uses Newton-Raphson method with multiple starting points
     * and fallback to bisection if needed. It is guaranteed to find a root when
     * xs has even length and the leading coefficient is positive, as the polynomial
     * tends to +infinity at both ends and must cross zero if it attains negative values.
     *
     * >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
     * -0.5
     * >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
     * 1.0
     */
    public double findZero(List<Double> xs) {
        // Use Horner's method for efficient evaluation and derivative calculation
        double[] coeffs = xs.stream().mapToDouble(Double::doubleValue).toArray();

        // Try multiple starting points for Newton-Raphson
        double[] startingPoints = {-1000, -100, -10, -1, 0, 1, 10, 100, 1000};

        for (double x0 : startingPoints) {
            double root = newtonRaphson(coeffs, x0);
            if (Math.abs(poly(xs, root)) < 1e-9) {
                return root;
            }
        }

        // Fallback: bisection on large interval if Newton-Raphson fails
        // Since polynomial tends to +inf at both ends, find interval where f changes sign
        double left = -1000.0;
        double right = 1000.0;

        double fl = poly(xs, left);
        double fr = poly(xs, right);

        // Find a point where f is negative (must exist due to problem guarantee)
        while (fl > 0 && fr > 0) {
            left *= 2;
            right *= 2;
            fl = poly(xs, left);
            fr = poly(xs, right);

            if (left < -1e10 || right > 1e10) {
                break; // Avoid infinite loop
            }
        }

        // Now find where function changes sign
        if (fl <= 0) {
            // Search right from left until sign change
            double x = left;
            double step = 1;
            while (poly(xs, x) <= 0 && x < right) {
                x += step;
                step *= 1.5;
            }
            return bisect(xs, left, x);
        } else {
            // Search left from right until sign change
            double x = right;
            double step = -1;
            while (poly(xs, x) <= 0 && x > left) {
                x += step;
                step *= 1.5;
            }
            return bisect(xs, x, right);
        }
    }

    private double newtonRaphson(double[] coeffs, double x0) {
        double x = x0;
        for (int i = 0; i < 100; i++) { // Max iterations
            double fx = evaluatePoly(coeffs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }
            double fpx = evaluateDerivative(coeffs, x);
            if (Math.abs(fpx) < 1e-12) {
                // Derivative too small, try perturbation
                x += 0.01;
                continue;
            }
            double xNext = x - fx / fpx;
            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                return x; // Give up and return current approximation
            }
            x = xNext;
        }
        return x; // Return last approximation
    }

    private double evaluatePoly(double[] coeffs, double x) {
        double result = 0;
        for (int i = coeffs.length - 1; i >= 0; i--) {
            result = result * x + coeffs[i];
        }
        return result;
    }

    private double evaluateDerivative(double[] coeffs, double x) {
        double result = 0;
        for (int i = coeffs.length - 1; i >= 1; i--) {
            result = result * x + i * coeffs[i];
        }
        return result;
    }

    private double bisect(List<Double> xs, double a, double b) {
        double fa = poly(xs, a);
        if (Math.abs(fa) < 1e-12) return a;

        double fb = poly(xs, b);
        if (Math.abs(fb) < 1e-12) return b;

        // Ensure fa and fb have opposite signs
        if (fa * fb > 0) {
            // Try to find a better interval
            return a; // Fallback
        }

        for (int i = 0; i < 100; i++) {
            double mid = (a + b) / 2;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < 1e-12 || (b - a) < 1e-12) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }
        return (a + b) / 2;
    }
}

