class Solution {
    /**
     * Checks if there are any two numbers in the list whose absolute difference is less than the given threshold.
     *
     * @param numbers the list of numbers to check
     * @param threshold the threshold for closeness (must be non-negative)
     * @return true if any two numbers are closer than the threshold, false otherwise
     * @throws IllegalArgumentException if threshold is negative
     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        if (threshold < 0) {
            throw new IllegalArgumentException("Threshold must be non-negative");
        }

        if (numbers == null || numbers.size() < 2) {
            return false;
        }

        // Create a copy to avoid modifying the original list
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        // Check adjacent pairs only (since sorted, minimum difference for each element is with neighbor)
        for (int i = 0; i < sorted.size() - 1; i++) {
            if (Math.abs(sorted.get(i + 1) - sorted.get(i)) < threshold) {
                return true;
            }
        }

        return false;
    }
}

