class Solution {
    /**
     * Separates a string containing multiple groups of nested parentheses into individual balanced groups.
     * Spaces in the input string are ignored. Each returned string represents a maximal balanced
     * parentheses group that is not nested within another group.
     *
     * @param paren_string the input string containing parentheses groups
     * @return a list of strings, each representing a separate balanced parentheses group
     */
    public List<String> separateParenGroups(String paren_string) {
        List<String> result = new ArrayList<>();
        StringBuilder currentGroup = new StringBuilder();
        int balance = 0;

        // Process each character, ignoring spaces
        for (char c : paren_string.toCharArray()) {
            if (c == ' ') {
                continue;
            }

            if (c == '(') {
                currentGroup.append(c);
                balance++;
            } else if (c == ')') {
                currentGroup.append(c);
                balance--;

                // When balance reaches 0, we've completed a group
                if (balance == 0) {
                    result.add(currentGroup.toString());
                    currentGroup = new StringBuilder();
                }
            }
        }

        return result;
    }
}

