class Solution {
    /**
     * Returns the mean absolute deviation of the given numbers around their mean.
     *
     * <p>The mean absolute deviation (MAD) is calculated as the average of the
     * absolute differences between each value and the mean of the dataset.
     *
     * @param numbers the list of numbers to calculate MAD for
     * @return the mean absolute deviation of the numbers
     * @throws IllegalArgumentException if the input list is empty
     * @throws NullPointerException if the input list is null
     */
    public double meanAbsoluteDeviation(List<Double> numbers) {
        // Validate input
        if (numbers == null) {
            throw new NullPointerException("Input list cannot be null");
        }
        if (numbers.isEmpty()) {
            throw new IllegalArgumentException("Input list cannot be empty");
        }

        // Calculate the mean
        double sum = 0.0;
        for (Double num : numbers) {
            sum += num;
        }
        double mean = sum / numbers.size();

        // Calculate the sum of absolute deviations from the mean
        double absSum = 0.0;
        for (Double num : numbers) {
            absSum += Math.abs(num - mean);
        }

        // Return the mean absolute deviation
        return absSum / numbers.size();
    }
}

