class Solution {
    /**
     * Returns a list containing the maximum nesting depth of parentheses for each space-separated group in the input string.
     * 
     * @param paren_string a string containing one or more groups of parentheses separated by spaces
     * @return a list of integers representing the maximum nesting depth for each group
     * @see #parseNestedParens(String)
     */
    public List<Integer> parseNestedParens(String paren_string) {
        List<Integer> result = new ArrayList<>();

        // Handle null or empty input
        if (paren_string == null || paren_string.trim().isEmpty()) {
            return result;
        }

        // Split the input string by spaces to get individual groups
        String[] groups = paren_string.split(" ");

        for (String group : groups) {
            int maxDepth = 0;
            int currentDepth = 0;

            // Traverse each character in the group
            for (int i = 0; i < group.length(); i++) {
                char c = group.charAt(i);

                if (c == '(') {
                    currentDepth++;
                    // Update maximum depth if current depth is greater
                    maxDepth = Math.max(maxDepth, currentDepth);
                } else if (c == ')') {
                    currentDepth--;
                }
            }

            result.add(maxDepth);
        }

        return result;
    }
}

