class Solution {
    /**
     * Test if given string is a palindrome.
     *
     * @param string the string to test
     * @return {@code true} if the string is a palindrome, {@code false} otherwise
     */
    public boolean isPalindrome(String string) {
        int i = 0;
        int j = string.length() - 1;
        while (i < j) {
            if (string.charAt(i) != string.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    /**
     * Find the shortest palindrome that begins with a supplied string.
     * <p>
     * Algorithm idea is simple:
     * <ul>
     *   <li>Find the longest postfix of supplied string that is a palindrome.</li>
     *   <li>Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.</li>
     * </ul>
     *
     * @param string the input string
     * @return the shortest palindrome that begins with the supplied string
     * @implSpec
     * <ul>
     *   <li>{@code makePalindrome("")} returns {@code ""}</li>
     *   <li>{@code makePalindrome("cat")} returns {@code "catac"}</li>
     *   <li>{@code makePalindrome("cata")} returns {@code "catac"}</li>
     * </ul>
     */
    public String makePalindrome(String string) {
        // Handle null case (though not specified in requirements, good practice)
        if (string == null) {
            return null;
        }

        // If string is empty or already a palindrome, return as-is
        if (string.isEmpty() || isPalindrome(string)) {
            return string;
        }

        // Find the longest palindromic suffix
        for (int i = 0; i < string.length(); i++) {
            if (isPalindrome(string.substring(i))) {
                // Found longest palindromic suffix starting at index i
                // Append reverse of prefix (string[0..i-1]) to end
                String prefix = string.substring(0, i);
                return string + new StringBuilder(prefix).reverse().toString();
            }
        }

        // Fallback (should never reach here since single char is always palindrome)
        return string;
    }
}

