class Solution {
    /**
     * Returns the bitwise XOR of two binary strings.
     *
     * @param a the first binary string consisting of '0's and '1's
     * @param b the second binary string consisting of '0's and '1's
     * @return the binary string representing the XOR of the two inputs
     * @throws IllegalArgumentException if the input strings have different lengths
     *     or contain characters other than '0' and '1'
     * @see #stringXor(String, String)
     */
    public String stringXor(String a, String b) {
        // Validate input lengths
        if (a.length() != b.length()) {
            throw new IllegalArgumentException("Input strings must have the same length");
        }

        // Validate that both strings contain only '0' and '1'
        for (int i = 0; i < a.length(); i++) {
            char charA = a.charAt(i);
            char charB = b.charAt(i);

            if ((charA != '0' && charA != '1') || (charB != '0' && charB != '1')) {
                throw new IllegalArgumentException("Input strings must contain only '0' and '1' characters");
            }
        }

        StringBuilder result = new StringBuilder();

        // Perform XOR operation character by character
        for (int i = 0; i < a.length(); i++) {
            char charA = a.charAt(i);
            char charB = b.charAt(i);

            if (charA == charB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

