class Solution {
    /**
     * Returns the greatest common divisor of two integers.
     * <p>
     * The greatest common divisor (GCD) of two integers is the largest positive integer
     * that divides both numbers without a remainder.
     *
     * @param a the first integer
     * @param b the second integer
     * @return the greatest common divisor of {@code a} and {@code b}
     * @throws IllegalArgumentException if both {@code a} and {@code b} are zero
     * @see #gcd(int, int) (for consistency with standard library naming)
     */
    public int greatestCommonDivisor(int a, int b) {
        // Handle edge case where both inputs are zero (GCD undefined)
        if (a == 0 && b == 0) {
            throw new IllegalArgumentException("GCD is undefined for both arguments being zero");
        }

        // Use Euclidean algorithm for efficient computation
        // Normalize negative values since GCD(a, b) = GCD(|a|, |b|)
        a = Math.abs(a);
        b = Math.abs(b);

        // Euclidean algorithm: GCD(a, b) = GCD(b, a mod b) until b == 0
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }

        return a;
    }
}

