     *
     * @param string a string containing musical notes in ASCII format separated by spaces,
     *               where "o" = whole note (4 beats), "o|" = half note (2 beats),
     *               and ".|" = quarter note (1 beat)
     * @return a list of integers representing the beat duration of each note in order
     */
    public List<Integer> parseMusic(String string) {
        List<Integer> result = new ArrayList<>();

        if (string == null || string.isEmpty()) {
            return result;
        }

        String[] notes = string.split(" ");

        for (String note : notes) {
            switch (note) {
                case "o":
                    result.add(4);
                    break;
                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // Optionally handle invalid notes - could throw exception or skip
                    // For this implementation, we'll skip unknown notes
                    break;
            }
        }

        return result;
    }
}

