class Solution {
    /**
     * Returns the number of occurrences of a substring within a string, counting overlapping matches.
     *
     * @param string the string to search in
     * @param substring the substring to search for
     * @return the count of occurrences, including overlapping ones
     */
    public int howManyTimes(String string, String substring) {
        // Handle edge cases
        if (substring == null || substring.isEmpty() || string == null || string.length() < substring.length()) {
            return 0;
        }

        int count = 0;
        // Check each possible starting position in the string
        for (int i = 0; i <= string.length() - substring.length(); i++) {
            if (string.substring(i, i + substring.length()).equals(substring)) {
                count++;
            }
        }
        return count;
    }
}

