class Solution {
    /**
     * Returns the two elements from the input list that are closest to each other,
     * ordered from smallest to largest.
     *
     * @param numbers a list of at least two Double values
     * @return a list containing the two closest numbers, in ascending order
     * @throws IllegalArgumentException if the input list has fewer than two elements
     */
    public List<Double> findClosestElements(List<Double> numbers) {
        if (numbers == null || numbers.size() < 2) {
            throw new IllegalArgumentException("List must contain at least two elements");
        }

        // Create a copy and sort it
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        double minDiff = Math.abs(sorted.get(1) - sorted.get(0));
        int minIndex = 0;

        // Find the pair with minimum difference among adjacent elements
        for (int i = 1; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < minDiff) {
                minDiff = diff;
                minIndex = i;
            }
        }

        // Return the closest pair in ascending order
        List<Double> result = new ArrayList<>();
        result.add(sorted.get(minIndex));
        result.add(sorted.get(minIndex + 1));

        return result;
    }
}

