class Solution {
    /**
     * Returns a new list where the input numbers are linearly rescaled
     * so that the minimum value becomes 0.0 and the maximum value becomes 1.0.
     * If all values are equal, returns a list of zeros.
     *
     * @param numbers the list of numbers to rescale (must contain at least two elements)
     * @return a new list with rescaled values in the range [0.0, 1.0]
     * @throws IllegalArgumentException if the input list is null or has fewer than two elements
     * @throws ArithmeticException if the input list is empty
     */
    public List<Double> rescaleToUnit(List<Double> numbers) {
        if (numbers == null) {
            throw new IllegalArgumentException("Input list cannot be null");
        }

        if (numbers.size() < 2) {
            throw new IllegalArgumentException("Input list must contain at least two elements");
        }

        // Find minimum and maximum values
        double min = Double.MAX_VALUE;
        double max = Double.MIN_VALUE;

        for (Double num : numbers) {
            if (num == null) {
                throw new IllegalArgumentException("List cannot contain null values");
            }
            if (num < min) {
                min = num;
            }
            if (num > max) {
                max = num;
            }
        }

        // Create result list
        List<Double> result = new ArrayList<>(numbers.size());

        // Handle case where all values are equal (min == max)
        if (min == max) {
            for (int i = 0; i < numbers.size(); i++) {
                result.add(0.0);
            }
            return result;
        }

        // Apply linear transformation: (value - min) / (max - min)
        double range = max - min;
        for (Double num : numbers) {
            result.add((num - min) / range);
        }

        return result;
    }
}

