class Solution {
    /**
     * For a given number n, find the largest number that divides n evenly, smaller than n.
     *
     * @param n the number to find the largest proper divisor for (must be greater than 1)
     * @return the largest divisor of n that is smaller than n
     * @throws IllegalArgumentException if n is less than or equal to 1
     */
    public int largestDivisor(int n) {
        if (n <= 1) {
            throw new IllegalArgumentException("n must be greater than 1");
        }

        // Start from n/2 and go downwards to find the largest divisor
        // The largest proper divisor cannot be larger than n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // This line should never be reached for n > 1, as 1 always divides n
        return 1;
    }
}

