class Solution {
    /**
     * Returns the prime factors of the given integer in ascending order.
     * Each prime factor appears in the list as many times as it divides the input number.
     * For example, {@code factorize(8)} returns {@code [2, 2, 2]} since 8 = 2³.
     *
     * @param n the integer to factorize (must be positive)
     * @return a list of prime factors in ascending order
     * @throws IllegalArgumentException if n is less than or equal to 1
     */
    public List<Integer> factorize(int n) {
        if (n <= 1) {
            throw new IllegalArgumentException("Input must be greater than 1");
        }

        List<Integer> factors = new ArrayList<>();

        // Check for factor 2 separately to optimize for even numbers
        while (n % 2 == 0) {
            factors.add(2);
            n /= 2;
        }

        // Check odd factors starting from 3
        for (int i = 3; i * i <= n; i += 2) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }

        // If n is still greater than 1, then it's a prime factor
        if (n > 1) {
            factors.add(n);
        }

        return factors;
    }
}

