class Solution {
    /**
     * From a list of integers, remove all elements that occur more than once.
     * Keep order of elements left the same as in the input.
     *
     * @param numbers the input list of integers
     * @return a new list containing only elements that appear exactly once in the input, in their original order
     * @example
     * <pre>
     * {@code
     * removeDuplicates(Arrays.asList(1, 2, 3, 2, 4)) returns [1, 3, 4]
     * }
     * </pre>
     */
    public List<Integer> removeDuplicates(List<Integer> numbers) {
        if (numbers == null || numbers.isEmpty()) {
            return new ArrayList<>();
        }

        // Count frequency of each element
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        for (Integer num : numbers) {
            frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
        }

        // Filter to keep only elements that appear exactly once
        List<Integer> result = new ArrayList<>();
        for (Integer num : numbers) {
            if (frequencyMap.get(num) == 1) {
                result.add(num);
            }
        }

        return result;
    }
}

