class Solution {
    /**
     * Evaluates polynomial with coefficients xs at point x.
     * @param xs the coefficients [a0, a1, ..., an] representing a0 + a1*x + ... + an*x^n
     * @param x the point at which to evaluate
     * @return the value of the polynomial at point x
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        double xPower = 1;
        for (double coeff : xs) {
            result += coeff * xPower;
            xPower *= x;
        }
        return result;
    }

    /**
     * Finds a zero of the polynomial with coefficients xs.
     * Only accepts lists with even number of coefficients (guaranteeing at least one real root).
     * Uses bisection method to find a root.
     *
     * @param xs the coefficients [a0, a1, ..., an] where n is odd (even number of coefficients)
     * @return a value x such that poly(xs, x) = 0
     */
    public double findZero(List<Double> xs) {
        // Determine the degree and leading coefficient
        int n = xs.size() - 1; // degree
        double leadingCoeff = xs.get(n);

        // Find a bracket [a, b] where f(a) * f(b) < 0
        double a = -1.0;
        double b = 1.0;

        // Expand the range until we find a sign change
        while (poly(xs, a) * poly(xs, b) > 0) {
            a *= 2;
            b *= 2;
            // Safety check to prevent infinite loop
            if (Math.abs(a) > 1e9) {
                break;
            }
        }

        // Bisection method
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Ensure fa and fb have opposite signs
        if (fa > 0 && fb > 0) {
            // Try to find another bracket on the left side
            double c = a * 2;
            while (poly(xs, c) > 0 && Math.abs(c) < 1e10) {
                a = c;
                c *= 2;
            }
            fa = poly(xs, a);
            fb = poly(xs, b);
        } else if (fa < 0 && fb < 0) {
            // Try to find another bracket on the right side
            double c = b * 2;
            while (poly(xs, c) < 0 && Math.abs(c) < 1e10) {
                b = c;
                c *= 2;
            }
            fa = poly(xs, a);
            fb = poly(xs, b);
        }

        // Now apply bisection
        for (int i = 0; i < 100; i++) { // 100 iterations for high precision
            double mid = (a + b) / 2;
            double fmid = poly(xs, mid);

            if (Math.abs(fmid) < 1e-12) {
                return mid;
            }

            if (fa * fmid <= 0) {
                b = mid;
                fb = fmid;
            } else {
                a = mid;
                fa = fmid;
            }
        }

        return (a + b) / 2;
    }
}

