class Solution {
    /**
     * Returns the n-th number that is both a Fibonacci number and prime.
     *
     * @param n the position (1-indexed) of the Fibonacci prime to return
     * @return the n-th Fibonacci prime number
     * @throws IllegalArgumentException if n is less than 1
     */
    public int primeFib(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special case: F(1)=1 is not prime, F(2)=1 is not prime
        // Start checking from F(3)=2 onwards

        while (count < n) {
            long next = a + b;
            a = b;
            b = next;

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return (int) next;
                }
            }
        }

        // Should never reach here if n is reasonable
        throw new IllegalStateException("Failed to find the " + n + "-th Fibonacci prime");
    }

    /**
     * Checks if a number is prime.
     *
     * @param num the number to check
     * @return true if the number is prime, false otherwise
     */
    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

