class Solution {
    /**
     * Determines whether any two numbers in the given list are closer to each other
     * than the specified threshold.
     *
     * @param numbers the list of numbers to check
     * @param threshold the minimum distance threshold (exclusive)
     * @return {@code true} if there exist two numbers whose absolute difference
     *         is less than {@code threshold}, {@code false} otherwise
     * @throws NullPointerException if {@code numbers} is {@code null}
     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        // Handle edge cases
        if (numbers == null) {
            throw new NullPointerException("numbers cannot be null");
        }
        if (numbers.size() < 2) {
            return false;
        }

        // Create a copy and sort to efficiently check adjacent pairs
        List<Double> sortedNumbers = new ArrayList<>(numbers);
        Collections.sort(sortedNumbers);

        // Check adjacent pairs only - if any pair is closer than threshold, return true
        for (int i = 0; i < sortedNumbers.size() - 1; i++) {
            double diff = Math.abs(sortedNumbers.get(i + 1) - sortedNumbers.get(i));
            if (diff < threshold) {
                return true;
            }
        }

        return false;
    }
}

