class Solution {
    /**
     * Separates a string containing multiple groups of nested parentheses into individual balanced groups.
     * <p>
     * Each group is balanced (each opening parenthesis has a matching closing parenthesis)
     * and not nested within another group. Spaces in the input string are ignored.
     *
     * @param paren_string the input string containing parentheses groups
     * @return a list of strings, each representing a balanced parentheses group
     * @throws IllegalArgumentException if the input contains unbalanced parentheses
     */
    public List<String> separateParenGroups(String paren_string) {
        List<String> result = new ArrayList<>();

        if (paren_string == null || paren_string.isEmpty()) {
            return result;
        }

        StringBuilder currentGroup = new StringBuilder();
        int depth = 0;

        for (char c : paren_string.toCharArray()) {
            if (c == ' ') {
                continue; // Ignore spaces
            }

            if (c == '(') {
                // Start or continue a group
                currentGroup.append(c);
                depth++;
            } else if (c == ')') {
                // End a group
                currentGroup.append(c);
                depth--;

                // If we've returned to depth 0, we've completed a balanced group
                if (depth == 0) {
                    result.add(currentGroup.toString());
                    currentGroup.setLength(0); // Reset for next group
                }
            }
        }

        // Check for unbalanced parentheses (depth > 0 means unclosed parentheses)
        if (depth != 0) {
            throw new IllegalArgumentException("Unbalanced parentheses in input string");
        }

        return result;
    }
}

