class Solution {
    /**
     * Calculates the Mean Absolute Deviation (MAD) for a list of numbers.
     * MAD is the average absolute difference between each element and the mean
     * of the dataset.
     *
     * @param numbers the list of Double values to analyze
     * @return the mean absolute deviation around the mean, or 0.0 for empty lists
     * @throws IllegalArgumentException if numbers is null
     * @apiNote Returns 0.0 for empty lists as there's no data to compute deviation
     * @implSpec Computes: MAD = (1/n) * Σ|xi - x̄| where x̄ is the sample mean
     * @see #meanAbsoluteDeviation(Collection)
     */
    public double meanAbsoluteDeviation(List<Double> numbers) {
        if (numbers == null) {
            throw new IllegalArgumentException("Input list cannot be null");
        }

        // Handle empty list case
        if (numbers.isEmpty()) {
            return 0.0;
        }

        // Calculate the mean
        double sum = 0.0;
        for (Double num : numbers) {
            if (num == null) {
                throw new IllegalArgumentException("List cannot contain null values");
            }
            sum += num;
        }
        double mean = sum / numbers.size();

        // Calculate mean absolute deviation
        double totalAbsoluteDeviation = 0.0;
        for (Double num : numbers) {
            totalAbsoluteDeviation += Math.abs(num - mean);
        }

        return totalAbsoluteDeviation / numbers.size();
    }
}

