class Solution {
    /**
     * Tests if given string is a palindrome.
     *
     * @param string the string to test
     * @return true if the string is a palindrome, false otherwise
     */
    public boolean isPalindrome(String string) {
        int i = 0;
        int j = string.length() - 1;
        while (i < j) {
            if (string.charAt(i) != string.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    /**
     * Finds the shortest palindrome that begins with the supplied string.
     * <p>
     * Algorithm idea: Find the longest suffix of the supplied string that is a palindrome,
     * then append to the end of the string the reverse of the prefix that comes before
     * this palindromic suffix.
     *
     * @param string the input string
     * @return the shortest palindrome that begins with the input string
     * @see #isPalindrome(String)
     */
    public String makePalindrome(String string) {
        if (string == null || string.isEmpty()) {
            return string;
        }

        // Find the longest palindromic suffix
        for (int i = 0; i < string.length(); i++) {
            // Check if substring from i to end is a palindrome
            if (isPalindrome(string.substring(i))) {
                // Append reverse of prefix (substring from 0 to i)
                String prefix = string.substring(0, i);
                String reversePrefix = new StringBuilder(prefix).reverse().toString();
                return string + reversePrefix;
            }
        }

        // Fallback (should not be reached since single char is always palindrome)
        return string;
    }
}

