class Solution {
    /**
     * Performs bitwise XOR operation on two binary strings.
     * Both input strings must consist only of characters '0' and '1'.
     * The strings should be of equal length.
     *
     * @param a first binary string
     * @param b second binary string
     * @return a binary string representing the XOR of the two input strings
     * @throws IllegalArgumentException if the input strings have different lengths
     * @throws IllegalArgumentException if either string contains characters other than '0' and '1'
     * 
     * >>> stringXor("010", "110")
     * "100"
     */
    public String stringXor(String a, String b) {
        // Validate inputs
        if (a.length() != b.length()) {
            throw new IllegalArgumentException("Input strings must have equal length");
        }

        // Validate that strings contain only '0' and '1'
        for (int i = 0; i < a.length(); i++) {
            char c1 = a.charAt(i);
            char c2 = b.charAt(i);
            if ((c1 != '0' && c1 != '1') || (c2 != '0' && c2 != '1')) {
                throw new IllegalArgumentException("Input strings must contain only '0' and '1' characters");
            }
        }

        StringBuilder result = new StringBuilder(a.length());

        for (int i = 0; i < a.length(); i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            // XOR logic: same bits give 0, different bits give 1
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

