     * @param a first integer
     * @param b second integer
     * @return the greatest common divisor of a and b (always non-negative)
     * @throws IllegalArgumentException if both a and b are zero (GCD undefined)
     */
    public int greatestCommonDivisor(int a, int b) {
        // Handle negative numbers by taking absolute values
        a = Math.abs(a);
        b = Math.abs(b);

        // Handle edge case where both numbers are zero
        if (a == 0 && b == 0) {
            throw new IllegalArgumentException("GCD is undefined for both inputs being zero");
        }

        // Euclidean algorithm
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }

        return a;
    }
}

