class Solution {
    /**
     * Counts how many times a given substring appears in the original string,
     * including overlapping occurrences.
     *
     * @param string the string to search in
     * @param substring the substring to search for
     * @return the number of occurrences of the substring in the string
     * @see #howManyTimes(String, String)
     */
    public int howManyTimes(String string, String substring) {
        // Handle edge cases
        if (string == null || substring == null) {
            return 0;
        }
        if (substring.isEmpty()) {
            return 0;
        }
        if (string.isEmpty() || string.length() < substring.length()) {
            return 0;
        }

        int count = 0;
        for (int i = 0; i <= string.length() - substring.length(); i++) {
            if (string.substring(i, i + substring.length()).equals(substring)) {
                count++;
            }
        }
        return count;
    }
}

