class Solution {
    /**
     * Input is a space-delimited string of numberals from 'zero' to 'nine'.
     * Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
     * Return the string with numbers sorted from smallest to largest
     * <p>
     * Examples:
     * <ul>
     *   <li>{@code sortNumbers("three one five")} returns {@code "one three five"}</li>
     *   <li>{@code sortNumbers("nine zero one")} returns {@code "zero one nine"}</li>
     * </ul>
     *
     * @param numbers the input space-delimited string of number words
     * @return a string with the number words sorted numerically from smallest to largest
     * @throws IllegalArgumentException if the input contains invalid number words
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        // Map number words to their numeric values
        Map<String, Integer> wordToNumber = new HashMap<>();
        wordToNumber.put("zero", 0);
        wordToNumber.put("one", 1);
        wordToNumber.put("two", 2);
        wordToNumber.put("three", 3);
        wordToNumber.put("four", 4);
        wordToNumber.put("five", 5);
        wordToNumber.put("six", 6);
        wordToNumber.put("seven", 7);
        wordToNumber.put("eight", 8);
        wordToNumber.put("nine", 9);

        // Split the input string into individual words
        String[] words = numbers.split(" ");

        // Validate each word and collect numeric values with original words for mapping
        List<String> validWords = new ArrayList<>();
        for (String word : words) {
            if (!wordToNumber.containsKey(word)) {
                throw new IllegalArgumentException("Invalid number word: '" + word + "'");
            }
            validWords.add(word);
        }

        // Sort the words based on their numeric values
        Collections.sort(validWords, (a, b) -> 
            wordToNumber.get(a) - wordToNumber.get(b));

        // Join the sorted words with spaces
        return String.join(" ", validWords);
    }
}

