class Solution {
    /**
     * For a given number n, find the largest number that divides n evenly, smaller than n.
     * 
     * @param n the number to find the largest proper divisor for (must be > 1)
     * @return the largest proper divisor of n, or 0 if n <= 1
     * 
     * >>> largestDivisor(15)
     * 5
     * >>> largestDivisor(16)
     * 8
     * >>> largestDivisor(7)
     * 1
     */
    public int largestDivisor(int n) {
        if (n <= 1) {
            return 0;
        }

        // The largest proper divisor cannot be larger than n/2
        // Start from n/2 and go down to find the first divisor
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // This should never be reached for n > 1, but included for safety
    }
}

