class Solution {
    /**
     * Removes all elements that occur more than once from the given list.
     * Keeps only elements that appear exactly once, preserving their original order.
     *
     * @param numbers the list of integers to process
     * @return a new list containing only elements that appear exactly once in the input,
     *         in the same order as they appeared in the original list
     * @throws NullPointerException if the input list is null
     * 
     * Example usage:
     * <pre>
     *   Solution solution = new Solution();
     *   List<Integer> result = solution.removeDuplicates(Arrays.asList(1, 2, 3, 2, 4));
     *   // result is [1, 3, 4]
     * </pre>
     */
    public List<Integer> removeDuplicates(List<Integer> numbers) {
        if (numbers == null) {
            throw new NullPointerException("Input list cannot be null");
        }

        // Count occurrences of each element
        Map<Integer, Long> frequencyMap = numbers.stream()
                .collect(Collectors.groupingBy(
                    n -> n, 
                    Collectors.counting()
                ));

        // Filter to keep only elements that appear exactly once
        List<Integer> result = new ArrayList<>();
        for (Integer num : numbers) {
            if (frequencyMap.get(num) == 1) {
                result.add(num);
            }
        }

        return result;
    }
}

