     * <p>
     * A prime number is a natural number greater than 1 that has no positive
     * divisors other than 1 and itself.
     *
     * @param n the number to check for primality
     * @return true if n is prime, false otherwise
     * @see #isPrime(long)
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
            // Handle edge cases
            if (xs == null || xs.isEmpty()) {
                return 0.0;
            }

            // If constant polynomial (degree 0), no zeros unless constant is 0
            if (xs.size() == 1) {
                return 0.0; // or throw exception, but problem says even number of coefficients
            }

            // Degree 1: ax + b = 0 => x = -b/a
            if (xs.size() == 2) {
                double a = xs.get(1); // coefficient of x
                double b = xs.get(0); // constant term
                if (Math.abs(a) < 1e-12) {
                    return 0.0; // degenerate case
                }
                return -b / a;
            }

            // For higher degrees, use Newton-Raphson with multiple starting points
            // Since problem guarantees a solution exists

            // First, check for obvious integer roots using Rational Root Theorem
            // Try small integers around 0
            for (int guess = -10; guess <= 10; guess++) {
                if (Math.abs(poly(xs, guess)) < 1e-9) {
                    return guess;
                }
            }

            // Newton-Raphson with multiple starting points
            double[] startingPoints = {-10, -5, -1, 0, 1, 5, 10};
            double bestRoot = Double.NaN;
            double bestValue = Double.MAX_VALUE;

            for (double start : startingPoints) {
                double root = newtonRaphson(xs, start);
                double value = Math.abs(poly(xs, root));
                if (value < bestValue) {
                    bestValue = value;
                    bestRoot = root;
                }
            }

            return bestRoot;
        }

        private double newtonRaphson(List<Double> xs, double start) {
            double x = start;
            for (int i = 0; i < 100; i++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < 1e-12) {
                    return x;
                }

                // Compute derivative
                double fpx = 0;
                for (int j = 1; j < xs.size(); j++) {
                    fpx += j * xs.get(j) * Math.pow(x, j - 1);
                }

                if (Math.abs(fpx) < 1e-12) {
                    // Derivative too small, try slight perturbation
                    x += 0.1;
                    continue;
                }

                double xNext = x - fx / fpx;
                if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                    break;
                }
                x = xNext;
            }
            return x;
        }
}

