class Solution {
    /**
     * Returns a new list where elements at indices divisible by three are sorted,
     * while elements at other indices remain unchanged.
     *
     * <p>The indices considered are 0-based, so indices 0, 3, 6, 9, ... are sorted.
     * The sorting is done in ascending order.
     *
     * @param l the input list of integers
     * @return a new list with elements at indices divisible by three sorted
     */
    public List<Integer> sortThird(List<Integer> l) {
        // Create a copy of the input list to avoid modifying the original
        List<Integer> result = new ArrayList<>(l);

        // Collect elements at indices divisible by 3
        List<Integer> thirdElements = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 3) {
            thirdElements.add(l.get(i));
        }

        // Sort these elements
        Collections.sort(thirdElements);

        // Put sorted elements back at their positions
        int sortedIndex = 0;
        for (int i = 0; i < result.size(); i += 3) {
            result.set(i, thirdElements.get(sortedIndex++));
        }

        return result;
    }
}

