class Solution {
    /**
     * Returns a new list where elements at even indices are sorted in ascending order,
     * while elements at odd indices remain in their original positions.
     *
     * @param l the input list of integers
     * @return a new list with even-indexed elements sorted and odd-indexed elements unchanged
     * @throws NullPointerException if the input list is null
     * 
     * <p>Examples:
     * <ul>
     *   <li>{@code sortEven(Arrays.asList(1, 2, 3))} returns {@code [1, 2, 3]}</li>
     *   <li>{@code sortEven(Arrays.asList(5, 6, 3, 4))} returns {@code [3, 6, 5, 4]}</li>
     * </ul>
     */
    public List<Integer> sortEven(List<Integer> l) {
        if (l == null) {
            throw new NullPointerException("Input list cannot be null");
        }

        // Create a copy of the input list
        List<Integer> result = new ArrayList<>(l);

        // Extract elements at even indices
        List<Integer> evenElements = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 2) {
            evenElements.add(l.get(i));
        }

        // Sort the even-indexed elements
        Collections.sort(evenElements);

        // Place sorted elements back at even indices
        int evenIndex = 0;
        for (int i = 0; i < result.size(); i += 2) {
            result.set(i, evenElements.get(evenIndex++));
        }

        return result;
    }
}

