class Solution {
    /**
     * Returns the n-th number that is both a Fibonacci number and prime.
     * 
     * @param n the position (1-indexed) of the prime Fibonacci number to return
     * @return the n-th prime Fibonacci number
     * @throws IllegalArgumentException if n is less than 1
     * 
     * >>> primeFib(1)
     * 2
     * >>> primeFib(2)
     * 3
     * >>> primeFib(3)
     * 5
     * >>> primeFib(4)
     * 13
     * >>> primeFib(5)
     * 89
     */
    public int primeFib(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 0; // F(0)
        int b = 1; // F(1)

        // Handle special case: 2 is the first prime Fibonacci
        if (n == 1) {
            return 2;
        }

        // Generate Fibonacci numbers until we find the nth prime one
        while (true) {
            int next = a + b;
            a = b;
            b = next;

            // Skip 0 and 1, they're not prime
            if (next > 1 && isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }
        }
    }

    /**
     * Checks if a number is prime.
     * 
     * @param num the number to check
     * @return true if the number is prime, false otherwise
     */
    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0 || num % 3 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

