class Solution {
    /**
     * Detects if the account balance falls below zero at any point during the operations.
     * The account starts with a zero balance, and each integer in the operations list
     * represents a deposit (positive) or withdrawal (negative).
     *
     * @param operations list of deposit and withdrawal amounts
     * @return true if the balance goes below zero at any point, false otherwise
     *
     * Example usage:
     *   belowZero(Arrays.asList(1, 2, 3)) returns false
     *   belowZero(Arrays.asList(1, 2, -4, 5)) returns true
     */
    public boolean belowZero(List<Integer> operations) {
        int balance = 0;
        for (int operation : operations) {
            balance += operation;
            if (balance < 0) {
                return true;
            }
        }
        return false;
    }
}

