class Solution {
    /**
     * Insert a number 'delimiter' between every two consecutive elements of input list `numbers'.
     * 
     * @param numbers the input list of integers
     * @param delimiter the value to insert between consecutive elements
     * @return a new list with the delimiter inserted between every pair of consecutive elements
     * @implSpec If the input list is empty, returns an empty list. If the input list has one element,
     *           returns a new list containing just that element. For lists with two or more elements,
     *           inserts the delimiter between each adjacent pair.
     * @apiNote This method does not modify the input list.
     * @see List
     */
    public List<Integer> intersperse(List<Integer> numbers, int delimiter) {
        // Handle null input (though typically we'd expect non-null per contract)
        if (numbers == null) {
            return new ArrayList<>();
        }

        // Create result list with appropriate initial capacity
        int size = numbers.size();
        if (size == 0) {
            return new ArrayList<>();
        }

        List<Integer> result = new ArrayList<>(size * 2 - 1);

        // Add first element
        result.add(numbers.get(0));

        // Add remaining elements with delimiter before each
        for (int i = 1; i < size; i++) {
            result.add(delimiter);
            result.add(numbers.get(i));
        }

        return result;
    }
}

