class Solution {
    /**
     * Filter an input list of strings only for ones that contain given substring.
     * 
     * @param strings the list of strings to filter (may be null or empty)
     * @param substring the substring to search for (may be null or empty)
     * @return a new list containing only strings that contain the substring
     *         Returns empty list if input list is null or empty.
     *         Returns all strings if substring is empty (since every string contains empty substring).
     * 
     * >>> filterBySubstring(List.of(), "a")
     * []
     * >>> filterBySubstring(Arrays.asList("abc", "bacd", "cde", "array"), "a")
     * ["abc", "bacd", "array"]
     */
    public List<String> filterBySubstring(List<String> strings, String substring) {
        // Handle null input list
        if (strings == null) {
            return new ArrayList<>();
        }

        // Handle null substring - treat as empty string (matches everything)
        if (substring == null) {
            substring = "";
        }

        List<String> result = new ArrayList<>();

        for (String str : strings) {
            // Skip null strings in the list (or could throw exception - decision based on typical behavior)
            if (str == null) {
                continue;
            }

            // Check if current string contains the substring
            if (str.contains(substring)) {
                result.add(str);
            }
        }

        return result;
    }
}

