class Solution {
    /**
     * For a given list of integers, return a list consisting of the sum and product of all the integers in the list.
     * Empty sum should be equal to 0 and empty product should be equal to 1.
     * 
     * @param numbers the list of integers to process
     * @return a list containing [sum, product] of all integers
     * 
     * Examples:
     * <pre>{@code
     * sumProduct(List.of())           // returns [0, 1]
     * sumProduct(Arrays.asList(1,2,3,4))  // returns [10, 24]
     * }</pre>
     */
    public List<Integer> sumProduct(List<Integer> numbers) {
        int sum = 0;
        int product = 1;

        for (Integer num : numbers) {
            sum += num;
            product *= num;
        }

        return Arrays.asList(sum, product);
    }
}

