class Solution {
    /**
     * Return the greatest common divisor of two integers a and b.
     * Uses the Euclidean algorithm.
     * 
     * @param a first integer (can be negative, zero, or positive)
     * @param b second integer (can be negative, zero, or positive)
     * @return the greatest common divisor of a and b (always non-negative)
     * @throws IllegalArgumentException if both a and b are zero
     * 
     * >>> greatestCommonDivisor(3, 5)
     * 1
     * >>> greatestCommonDivisor(25, 15)
     * 5
     */
    public int greatestCommonDivisor(int a, int b) {
        // Handle edge case where both numbers are zero
        if (a == 0 && b == 0) {
            throw new IllegalArgumentException("GCD is undefined for (0, 0)");
        }

        // Use absolute values to handle negative inputs
        // GCD is always non-negative by convention
        int x = Math.abs(a);
        int y = Math.abs(b);

        // Euclidean algorithm: GCD(x, y) = GCD(y, x mod y)
        while (y != 0) {
            int temp = y;
            y = x % y;
            x = temp;
        }

        return x;
    }
}

