class Solution {
    /**
     * Given list of numbers (of at least two elements), apply a linear transform to that list,
     * such that the smallest number will become 0 and the largest will become 1.
     *
     * @param numbers list of Double values to rescale (must contain at least 2 elements)
     * @return a new list where values are rescaled to [0, 1] interval
     * @throws IllegalArgumentException if the input list has fewer than 2 elements or is null
     * @throws NullPointerException if the list contains null elements
     */
    public List<Double> rescaleToUnit(List<Double> numbers) {
        // Validate input
        if (numbers == null || numbers.size() < 2) {
            throw new IllegalArgumentException("Input list must contain at least 2 elements");
        }

        // Find min and max values
        double min = Double.POSITIVE_INFINITY;
        double max = Double.NEGATIVE_INFINITY;

        for (Double num : numbers) {
            if (num == null) {
                throw new NullPointerException("List contains null elements");
            }
            if (num < min) {
                min = num;
            }
            if (num > max) {
                max = num;
            }
        }

        // Handle edge case where all values are the same
        double range = max - min;
        if (range == 0) {
            // If all values are identical, return list of zeros (or could return all 0.5)
            // Following the spirit of the problem, all values become 0.0 when min == max
            List<Double> result = new ArrayList<>(numbers.size());
            for (int i = 0; i < numbers.size(); i++) {
                result.add(0.0);
            }
            return result;
        }

        // Apply linear transformation: (value - min) / (max - min)
        List<Double> result = new ArrayList<>(numbers.size());
        for (Double num : numbers) {
            result.add((num - min) / range);
        }

        return result;
    }
}

