class Solution {
    public double findZero(List<Double> xs) {
        // Newton-Raphson method
        double x = 0.0; // initial guess
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);
            // compute derivative
            double fpx = 0.0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(fpx) < 1e-15) {
                // derivative too small, try perturbation
                x += 0.1;
                continue;
            }

            double xNew = x - fx / fpx;

            if (Math.abs(xNew - x) < tolerance) {
                return xNew;
            }

            x = xNew;
        }

        // fallback: return current x if didn't converge
        return x;
    }
}

