class Solution {
    /**
     * primeFib returns n-th number that is a Fibonacci number and it's also prime.
     * >>> primeFib(1)
     * 2
     * >>> primeFib(2)
     * 3
     * >>> primeFib(3)
     * 5
     * >>> primeFib(4)
     * 13
     * >>> primeFib(5)
     * 89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 0; // First Fibonacci number
        int b = 1; // Second Fibonacci number

        // Handle special case: if n == 1, we need to find first prime Fibonacci
        while (true) {
            // Generate next Fibonacci number
            int next = a + b;
            a = b;
            b = next;

            // Check if this Fibonacci number is prime and greater than 1
            if (next > 1 && isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }
        }
    }

    /**
     * Checks if a number is prime.
     */
    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

