class Solution {
    public double findZero(List<Double> xs) {
            // Newton-Raphson method
            double x = 0.0; // initial guess
            double tolerance = 1e-10;
            int maxIterations = 1000;

            for (int i = 0; i < maxIterations; i++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < tolerance) {
                    return x;
                }

                // Compute derivative using finite differences or analytically
                double h = 1e-8;
                double fpx = (poly(xs, x + h) - poly(xs, x - h)) / (2 * h);

                if (Math.abs(fpx) < 1e-15) {
                    // Derivative too small, try perturbing x
                    x += 0.1;
                    continue;
                }

                double xNext = x - fx / fpx;

                // Check for convergence
                if (Math.abs(xNext - x) < tolerance) {
                    return xNext;
                }

                x = xNext;
            }

            // Fallback: if Newton fails, try bisection
            // Find interval where sign changes
            double left = -1000.0;
            double right = 1000.0;

            // Expand interval until we find sign change
            while (poly(xs, left) * poly(xs, right) > 0) {
                left *= 2;
                right *= 2;
                // Safety check to avoid infinite loop
                if (Math.abs(left) > 1e6) {
                    break;
                }
            }

            // Bisection method
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fmid = poly(xs, mid);

                if (Math.abs(fmid) < tolerance) {
                    return mid;
                }

                if (poly(xs, left) * fmid < 0) {
                    right = mid;
                } else {
                    left = mid;
                }
            }

            return (left + right) / 2;
        }
}

