class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Start with first two Fibonacci numbers
        int prev = 0;
        int curr = 1;

        int count = 0;

        // Handle special case: 2 is the first Fibonacci prime
        while (count < n) {
            // Generate next Fibonacci number
            int next = prev + curr;
            prev = curr;
            curr = next;

            // Check if current Fibonacci number is prime and > 1
            if (curr > 1 && isPrime(curr)) {
                count++;
                if (count == n) {
                    return curr;
                }
            }
        }

        // Should never reach here for valid input
        throw new RuntimeException("Failed to find nth Fibonacci prime");
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

