class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Use bisection method
        // First, check if constant term is already zero
        if (Math.abs(xs.get(0)) < 1e-12) {
            return 0.0;
        }

        // Determine degree (n-1 for n coefficients)
        int n = xs.size();

        // Find leading coefficient (largest non-zero)
        double leadingCoeff = 0.0;
        for (int i = n - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) {
                leadingCoeff = xs.get(i);
                break;
            }
        }

        // For odd degree polynomials, we know there's at least one real root
        // We need to find an interval [a, b] where f(a) * f(b) < 0

        double left = -1000.0;
        double right = 1000.0;

        // Try to find bounds where function changes sign
        // Start with reasonable bounds and expand if needed
        double fl = poly(xs, left);
        double fr = poly(xs, right);

        // Expand bounds if necessary
        int expandCount = 0;
        while (fl * fr > 0 && expandCount < 50) {
            left *= 2;
            right *= 2;
            fl = poly(xs, left);
            fr = poly(xs, right);
            expandCount++;
        }

        // If we still don't have opposite signs, try specific values based on problem guarantee
        if (fl * fr > 0) {
            // Fallback: just return a simple value like 0 or try more aggressive expansion
            left = -10000.0;
            right = 10000.0;
            fl = poly(xs, left);
            fr = poly(xs, right);
        }

        // Now apply bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations should give good precision
            double mid = (left + right) / 2.0;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < 1e-12) {
                return mid;
            }

            if (fl * fm < 0) {
                right = mid;
                fr = fm;
            } else {
                left = mid;
                fl = fm;
            }
        }

        return (left + right) / 2.0;
    }
}

