class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 0; // F(0)
        int b = 1; // F(1)

        // Handle special case: F(0) = 0, F(1) = 1, F(2) = 1 are not prime
        // Start checking from F(3) = 2 onwards

        // We need to check Fibonacci numbers starting from F(3) = 2
        // But let's generate them systematically

        if (n == 1) return 2; // First Fibonacci prime is 2 (F(3))

        // Generate Fibonacci numbers and check for primality
        for (int i = 3; ; i++) {
            int fib = a + b;

            // Check if this Fibonacci number is prime and greater than 1
            if (fib > 1 && isPrime(fib)) {
                count++;
                if (count == n) {
                    return fib;
                }
            }

            // Update Fibonacci sequence
            a = b;
            b = fib;
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

