    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        // Using the idiom from ITEM 57: minimize scope with for loop
        for (int i = 3, sqrtN = (int) Math.sqrt(n); i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method
        double x = 0.0; // initial guess

        // Try different initial guesses if needed
        for (int attempt = 0; attempt < 3; attempt++) {
            if (attempt == 1) x = 1.0;
            else if (attempt == 2) x = -1.0;

            double prevX = x;
            for (int i = 0; i < 100; i++) {
                double fx = poly(xs, x);

                // Check if we found a root
                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                // Compute derivative
                double fPrimeX = 0.0;
                for (int j = 1; j < xs.size(); j++) {
                    fPrimeX += j * xs.get(j) * Math.pow(x, j - 1);
                }

                // Handle case where derivative is zero
                if (Math.abs(fPrimeX) < 1e-15) {
                    break; // try next initial guess
                }

                double newX = x - fx / fPrimeX;

                // Check for convergence or oscillation
                if (Math.abs(newX - prevX) < 1e-12 || 
                    Double.isNaN(newX) || Double.isInfinite(newX)) {
                    break;
                }

                prevX = x;
                x = newX;
            }
        }

        // Fallback: try bisection method if Newton-Raphson fails
        // Since we know there's a root (odd degree polynomial), search in a range
        double left = -1000.0;
        double right = 1000.0;

        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }

            double fLeft = poly(xs, left);
            if (fLeft * fMid <= 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Final fallback - return midpoint
        return (left + right) / 2;
    }
}

