        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method to find a root
        double x = 1.0; // initial guess

        // Newton-Raphson iterations
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);

            // If we're close enough to zero, return
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative at x
            double fpx = polyDerivative(xs, x);

            // If derivative is zero, can't continue Newton's method
            if (Math.abs(fpx) < 1e-10) {
                // Try perturbing x slightly
                x += 0.1;
                continue;
            }

            double xNew = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNew - x) < 1e-10) {
                return xNew;
            }

            x = xNew;
        }

        // Return best approximation after max iterations
        return x;
    }

    // Helper method to evaluate derivative of polynomial
    private double polyDerivative(List<Double> xs, double x) {
        if (xs.size() <= 1) {
            return 0.0;
        }

        double result = 0.0;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

