class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Start from n/2 since no divisor (other than n itself) can be larger than n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }
        // This should never be reached for n > 1, as 1 always divides n
        // For n = 1, there is no proper divisor, but the problem likely assumes n > 1
        return 1;
    }
}

