class Solution {
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // All other even numbers are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For very low degrees, we can solve directly
        if (xs.size() == 2) {
            // ax + b = 0 => x = -b/a
            double a = xs.get(1);
            double b = xs.get(0);
            return -b / a;
        }

        // For higher degrees, use Newton-Raphson
        double x = 0.0; // initial guess

        // Try multiple starting points to increase chances of finding a root
        double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0, 0.5, -0.5};

        for (double startX : startingPoints) {
            double currentX = startX;
            for (int i = 0; i < 100; i++) { // max iterations
                double fx = poly(xs, currentX);

                // Check if close enough to zero
                if (Math.abs(fx) < 1e-9) {
                    return currentX;
                }

                // Compute derivative
                double fPrimeX = polyDerivative(xs, currentX);

                // Avoid division by zero
                if (Math.abs(fPrimeX) < 1e-12) {
                    break; // try next starting point
                }

                double nextX = currentX - fx / fPrimeX;

                // Check for convergence
                if (Math.abs(nextX - currentX) < 1e-9) {
                    if (Math.abs(poly(xs, nextX)) < 1e-6) {
                        return nextX;
                    }
                    break; // might be stuck, try next starting point
                }

                currentX = nextX;
            }
        }

        // Fallback: bisection method on a large interval
        double left = -1000.0;
        double right = 1000.0;

        // Find interval where sign changes
        while (left > -10000 && right < 10000) {
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            if (fLeft * fRight <= 0) {
                // Bisection
                for (int i = 0; i < 100; i++) {
                    double mid = (left + right) / 2;
                    double fMid = poly(xs, mid);

                    if (Math.abs(fMid) < 1e-9 || (right - left) < 1e-9) {
                        return mid;
                    }

                    if (fLeft * fMid <= 0) {
                        right = mid;
                        fRight = fMid;
                    } else {
                        left = mid;
                        fLeft = fMid;
                    }
                }
                return (left + right) / 2;
            }

            left *= 2;
            right *= 2;
        }

        // Last resort: return midpoint
        return 0.0;
    }

    // Helper method to compute derivative of polynomial
    private double polyDerivative(List<Double> xs, double x) {
        double result = 0;
        // derivative of a_i * x^i is i * a_i * x^(i-1)
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

