import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // For linear case: xs[0] + xs[1]*x = 0 => x = -xs[0]/xs[1]
        if (xs.size() == 2) {
            double a0 = xs.get(0);
            double a1 = xs.get(1);
            if (Math.abs(a1) > 1e-15) {
                return -a0 / a1;
            }
        }

        // For higher degree polynomials, use numerical method
        // We'll use Newton-Raphson method with numerical differentiation

        // Start with initial guess
        double x = 0.0;
        double tolerance = 1e-10;
        int maxIterations = 1000;

        // Try different starting points if needed
        for (int attempt = 0; attempt < 10; attempt++) {
            x = attempt - 5.0; // Try starting points from -5 to 4

            for (int i = 0; i < maxIterations; i++) {
                double fx = poly(xs, x);

                // Check if we're close enough to zero
                if (Math.abs(fx) < tolerance) {
                    return x;
                }

                // Numerical derivative
                double h = 1e-8;
                double fpx = (poly(xs, x + h) - fx) / h;

                // Avoid division by zero or very small derivative
                if (Math.abs(fpx) < 1e-15) {
                    break; // Skip this starting point
                }

                double xNew = x - fx / fpx;

                // Check for convergence
                if (Math.abs(xNew - x) < tolerance) {
                    return xNew;
                }

                // Check for divergence or overflow
                if (Double.isNaN(xNew) || Double.isInfinite(xNew)) {
                    break;
                }

                x = xNew;
            }
        }

        // Fallback: try bisection method in a reasonable range
        double left = -1000.0;
        double right = 1000.0;

        // Find interval where sign changes
        while (left < right) {
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            if (fLeft * fRight <= 0) {
                // Bisection method
                for (int i = 0; i < 100; i++) {
                    double mid = (left + right) / 2;
                    double fMid = poly(xs, mid);

                    if (Math.abs(fMid) < 1e-10) {
                        return mid;
                    }

                    if (fLeft * fMid <= 0) {
                        right = mid;
                    } else {
                        left = mid;
                        fLeft = fMid;
                    }
                }
                return (left + right) / 2;
            }

            // Expand the search range
            left *= 2;
            right *= 2;

            // Prevent infinite expansion
            if (Math.abs(left) > 1e6) {
                break;
            }
        }

        // If still no result, return the best approximation we can find
        return x;
    }
}

