class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 1;  // First Fibonacci number F1
        long b = 1;  // Second Fibonacci number F2

        // Handle special case: 1 is not prime, so skip initial 1s
        // Start checking from the third Fibonacci number (which is 2)

        // Check if 2 is prime (it is)
        if (n == 1) {
            return 2;
        }

        // Generate Fibonacci numbers starting from 2
        long c = 2;  // F3 = 2
        int fibIndex = 3;

        // Check 2 as first potential Fibonacci prime
        if (isPrime(c)) {
            count++;
            if (count == n) {
                return (int) c;
            }
        }

        // Continue generating Fibonacci numbers
        while (true) {
            a = b;
            b = c;
            c = a + b;
            fibIndex++;

            if (isPrime(c)) {
                count++;
                if (count == n) {
                    return (int) c;
                }
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        long sqrt = (long) Math.sqrt(num);
        for (long i = 3; i <= sqrt; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

