    public List<Integer> parseMusic(String string) {
        List<Integer> result = new ArrayList<>();

        if (string == null || string.trim().isEmpty()) {
            return result;
        }

        String[] notes = string.trim().split("\\s+");

        for (String note : notes) {
            switch (note) {
                case "o":
                    result.add(4);
                    break;
                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // According to the problem, we only expect these three formats
                    // If there's an unknown format, we could throw an exception or skip
                    // Since the problem doesn't specify error handling, we'll assume valid input
                    break;
            }
        }

        return result;
    }
}

