class Solution {
    public int howManyTimes(String string, String substring) {
        // Handle edge cases
        if (string == null || substring == null) {
            return 0;
        }

        int count = 0;
        int stringLength = string.length();
        int substringLength = substring.length();

        // If substring is empty or longer than string, no matches possible
        if (substringLength == 0 || substringLength > stringLength) {
            return 0;
        }

        // Check each possible starting position
        for (int i = 0; i <= stringLength - substringLength; i++) {
            if (string.substring(i, i + substringLength).equals(substring)) {
                count++;
            }
        }

        return count;
    }
}

