class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 1; // F(1) = 1
        long b = 1; // F(2) = 1

        // Check if 2 is needed (it's the first Fibonacci prime)
        // We'll generate starting from F(3) = 2

        // Handle the special case for 2
        if (n == 1) {
            return 2;
        }

        // Start generating from F(3) = 2
        long fib = 2; // F(3)
        a = 1; // F(2)
        b = 2; // F(3)

        // Check if 2 is the first prime Fibonacci
        if (isPrime((int)fib)) {
            count++;
            if (count == n) {
                return (int)fib;
            }
        }

        // Generate remaining Fibonacci numbers
        while (true) {
            fib = a + b;
            a = b;
            b = fib;

            if (isPrime((int)fib)) {
                count++;
                if (count == n) {
                    return (int)fib;
                }
            }

            // Safety check - though Fibonacci primes grow quickly and shouldn't overflow int for reasonable n
            if (fib > Integer.MAX_VALUE) {
                break;
            }
        }

        throw new RuntimeException("Failed to find " + n + "-th prime Fibonacci");
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

