class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For polynomials of odd degree, there's always at least one real root
        // Use bisection method on a sufficiently large interval

        // First, check if it's linear (degree 1)
        if (xs.size() == 2) {
            // f(x) = xs[0] + xs[1]*x = 0 => x = -xs[0]/xs[1]
            return -xs.get(0) / xs.get(1);
        }

        // For higher odd degrees, use bisection method
        // We need to find an interval [a, b] where f(a)*f(b) < 0

        // Try expanding interval until we find sign change
        double a = -1.0;
        double b = 1.0;
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Expand interval until we find sign change
        int maxExpansions = 30;
        int expansionCount = 0;
        while (fa * fb >= 0 && expansionCount < maxExpansions) {
            a *= 2;
            b *= 2;
            fa = poly(xs, a);
            fb = poly(xs, b);
            expansionCount++;
        }

        // If still no sign change, use larger bounds
        if (fa * fb >= 0) {
            a = -1e6;
            b = 1e6;
            fa = poly(xs, a);
            fb = poly(xs, b);
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations for high precision
            double mid = (a + b) / 2;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < 1e-12) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        // Return midpoint if we didn't find exact root
        return (a + b) / 2;
    }
}

