class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return 0; // No proper divisors for n <= 1
        }

        // Find the smallest divisor > 1
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                // i is the smallest prime factor, so n/i is the largest proper divisor
                return n / i;
            }
        }

        // If we reach here, n is prime, so the largest proper divisor is 1
        return 1;
    }
}

