class Solution {
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle simple linear case explicitly for efficiency
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            return -a / b;
        }

        // Newton's method implementation
        double x = 0.0; // initial guess

        // Try multiple starting points to increase chances of convergence
        double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0, 0.5, -0.5};

        for (double startX : startingPoints) {
            x = startX;
            for (int iteration = 0; iteration < 100; iteration++) {
                double fx = poly(xs, x);

                // Check if we're close enough to a root
                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                // Compute derivative using analytical formula
                double fpx = 0.0;
                for (int i = 1; i < xs.size(); i++) {
                    fpx += i * xs.get(i) * Math.pow(x, i - 1);
                }

                // Avoid division by zero
                if (Math.abs(fpx) < 1e-15) {
                    break; // try next starting point
                }

                double newX = x - fx / fpx;

                // Check for divergence or NaN
                if (Double.isNaN(newX) || Double.isInfinite(newX) || 
                    (iteration > 0 && Math.abs(newX - x) > 1e6)) {
                    break; // try next starting point
                }

                x = newX;
            }
        }

        // Fallback: return the best approximation found
        double bestX = 0.0;
        double bestError = Double.MAX_VALUE;
        for (double startX : startingPoints) {
            double x = startX;
            for (int iteration = 0; iteration < 100; iteration++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < bestError) {
                    bestError = Math.abs(fx);
                    bestX = x;
                }

                double fpx = 0.0;
                for (int i = 1; i < xs.size(); i++) {
                    fpx += i * xs.get(i) * Math.pow(x, i - 1);
                }

                if (Math.abs(fpx) < 1e-15) break;

                double newX = x - fx / fpx;
                if (Double.isNaN(newX) || Double.isInfinite(newX)) break;
                x = newX;
            }
        }

        return bestX;
    }
}

