class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true; // 2 and 3 are prime
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check for divisors from 5 up to sqrt(n)
        // Use 6k ± 1 optimization: all primes > 3 are of form 6k±1
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle special case of linear polynomial (degree 1)
        if (xs.size() == 2) {
            // f(x) = xs[0] + xs[1]*x = 0 => x = -xs[0]/xs[1]
            return -xs.get(0) / xs.get(1);
        }

        // For higher degree polynomials, use Newton-Raphson method
        double x = 1.0; // Initial guess
        double epsilon = 1e-10;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // Check if we're close enough to a root
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative numerically: f'(x) ≈ (f(x+h) - f(x-h)) / (2h)
            double h = 1e-7;
            double fpx = (poly(xs, x + h) - poly(xs, x - h)) / (2 * h);

            // Avoid division by zero or very small derivative
            if (Math.abs(fpx) < epsilon) {
                // Try a different starting point if derivative is too small
                x += 0.1;
                continue;
            }

            double xNew = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNew - x) < epsilon) {
                return xNew;
            }

            x = xNew;
        }

        // If we exit the loop without converging, return the best estimate
        return x;
    }
}

