class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // All other even numbers are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        // Only need to check up to sqrt(n) because if n = a*b and a <= b, then a <= sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle linear case directly (2 coefficients)
        if (xs.size() == 2) {
            double a0 = xs.get(0);
            double a1 = xs.get(1);
            if (a1 != 0) {
                return -a0 / a1;
            }
        }

        // For higher degree polynomials, use Newton-Raphson
        double x = 0.0; // initial guess

        // Try multiple starting points if needed
        for (int attempt = 0; attempt < 3; attempt++) {
            double currentX = x + (attempt == 0 ? 0 : (attempt == 1 ? 1.0 : -1.0));

            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, currentX);

                // Check if we found a root
                if (Math.abs(fx) < 1e-10) {
                    return currentX;
                }

                // Compute derivative
                double fpx = 0.0;
                for (int i = 1; i < xs.size(); i++) {
                    fpx += i * xs.get(i) * Math.pow(currentX, i - 1);
                }

                // Avoid division by zero
                if (Math.abs(fpx) < 1e-10) {
                    break; // try different starting point
                }

                double nextX = currentX - fx / fpx;

                // Check for convergence
                if (Math.abs(nextX - currentX) < 1e-12) {
                    if (Math.abs(poly(xs, nextX)) < 1e-8) {
                        return nextX;
                    }
                    break;
                }

                currentX = nextX;
            }
        }

        // Fallback: try bisection method
        // Find interval where function changes sign
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand search range if needed
        int expandAttempts = 0;
        while (fLeft * fRight > 0 && expandAttempts < 20) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            expandAttempts++;
        }

        // Bisection method
        if (fLeft * fRight <= 0) {
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);

                if (Math.abs(fMid) < 1e-10) {
                    return mid;
                }

                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
            return (left + right) / 2;
        }

        // Last resort: return Newton's method result even if not perfect
        return x;
    }
}

