class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Handle edge cases
        if (substring == null || substring.isEmpty() || string == null) {
            return 0;
        }

        int count = 0;
        int searchStart = 0;

        while (searchStart <= string.length() - substring.length()) {
            int index = string.indexOf(substring, searchStart);
            if (index == -1) {
                break;
            }
            count++;
            // Move search position by 1 to allow overlapping matches
            searchStart = index + 1;
        }

        return count;
    }
}

