class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Get the degree and leading coefficient
        int n = xs.size() - 1; // degree of polynomial
        double leadingCoeff = xs.get(n);

        // Helper function to evaluate polynomial
        java.util.function.DoubleUnaryOperator polyFunc = (double x) -> {
            double result = 0;
            double xPower = 1;
            for (int i = 0; i <= n; i++) {
                result += xs.get(i) * xPower;
                xPower *= x;
            }
            return result;
        };

        // For odd-degree polynomials (even number of coefficients means odd degree),
        // there's always at least one real root
        // We'll use bisection method with initial bounds

        // Find bounds where f(a) and f(b) have opposite signs
        double a = -1000.0;
        double b = 1000.0;
        double fa = polyFunc.applyAsDouble(a);
        double fb = polyFunc.applyAsDouble(b);

        // If we're lucky and already at root
        if (Math.abs(fa) < 1e-9) return a;
        if (Math.abs(fb) < 1e-9) return b;

        // Expand search range if needed until we have opposite signs
        int attempts = 0;
        while (fa * fb > 0 && attempts < 20) {
            a *= 2;
            b *= 2;
            fa = polyFunc.applyAsDouble(a);
            fb = polyFunc.applyAsDouble(b);
            attempts++;
        }

        // Now apply bisection method
        for (int i = 0; i < 100; i++) { // sufficient iterations for precision
            double mid = (a + b) / 2;
            double fm = polyFunc.applyAsDouble(mid);

            if (Math.abs(fm) < 1e-9) {
                return mid;
            }

            if (fa * fm < 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2;
    }
}

