class Solution {
    /**
    Return maximum element in the list.
    >>> maxElement(Arrays.asList(1, 2, 3))
    3
    >>> maxElement(Arrays.asList(5, 3, -5, 2, -3, 3, 9, 0, 123, 1, -10))
    123
     */
    public int maxElement(List<Integer> l) {
        if (l == null || l.isEmpty()) {
            throw new IllegalArgumentException("List cannot be null or empty");
        }

        Integer max = l.get(0);
        for (int i = 1; i < l.size(); i++) {
            Integer current = l.get(i);
            // Use compareTo to avoid identity comparison issues with boxed integers
            if (current.compareTo(max) > 0) {
                max = current;
            }
        }
        return max;
    }
}

