class Solution {
    /**
    This function takes a list l and returns a list l' such that
    l' is identical to l in the indicies that are not divisible by three, while its values at the indicies that are divisible by three are equal
    to the values of the corresponding indicies of l, but sorted.
    >>> sortThird(Arrays.asList(1, 2, 3))
    [1, 2, 3]
    >>> sortThird(Arrays.asList(5, 6, 3, 4, 8, 9, 2))
    [2, 6, 3, 4, 8, 9, 5]
     */
    public List<Integer> sortThird(List<Integer> l) {
        // Create a copy of the original list
        List<Integer> result = new ArrayList<>(l);

        // Extract elements at indices divisible by 3
        List<Integer> thirdElements = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 3) {
            thirdElements.add(l.get(i));
        }

        // Sort these elements
        Collections.sort(thirdElements);

        // Put sorted elements back into their positions
        int sortedIndex = 0;
        for (int i = 0; i < result.size(); i += 3) {
            result.set(i, thirdElements.get(sortedIndex++));
        }

        return result;
    }
}

