class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) return -1;

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special case for first few Fibonacci numbers
        // We'll start from F(3) = 2 onwards since 0, 1 are not prime

        while (true) {
            long next = a + b;
            a = b;
            b = next;

            // Skip 1 (which appears twice in Fibonacci sequence)
            if (next == 1) continue;

            // Check if next is prime
            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return (int) next;
                }
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0) return false;

        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

