class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs.isEmpty()) return 0.0;

        // Find the degree of polynomial (highest non-zero coefficient index)
        int degree = -1;
        for (int i = xs.size() - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) {
                degree = i;
                break;
            }
        }

        // Linear case: ax + b = 0 => x = -b/a
        if (degree == 1) {
            double a = xs.get(1);
            double b = xs.get(0);
            if (Math.abs(a) > 1e-12) {
                return -b / a;
            }
        }

        // For higher degrees, use bisection method
        // Since we know a root exists, we need to find an interval [a,b] with sign change

        // Start with a reasonable search range
        double left = -1000.0;
        double right = 1000.0;

        // Expand range until we find sign change
        for (int expand = 0; expand < 20; expand++) {
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            if (fLeft * fRight <= 0) {
                // Sign change found or one of them is zero
                break;
            }

            // Expand the search range
            left *= 2;
            right *= 2;
        }

        // Now apply bisection method
        for (int iteration = 0; iteration < 100; iteration++) {
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            // Check if we found exact root (within tolerance)
            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            double fLeft = poly(xs, left);

            if (fLeft * fMid <= 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Return midpoint as best approximation
        return (left + right) / 2.0;
    }
}

