class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Handle special cases: F(3)=2, F(4)=3 are the first Fibonacci primes
        // Note: F(0)=0, F(1)=1, F(2)=1 are not prime

        long a = 0; // F(0)
        long b = 1; // F(1)
        int count = 0;

        // Check F(0) and F(1) - neither are prime
        // Start generating from F(2)

        while (true) {
            long next = a + b;
            a = b;
            b = next;

            // Check if 'next' is prime and Fibonacci number (it is by construction)
            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return (int) next;
                }
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        long sqrt = (long) Math.sqrt(num);
        for (long i = 3; i <= sqrt; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

