class Solution {
    public String makePalindrome(String string) {
        if (string == null || string.isEmpty()) {
            return string;
        }

        int n = string.length();

        // Find the longest palindromic suffix
        // We iterate from index 0 to n-1, and check if substring from i to end is palindrome
        // The first (smallest i) such that substring(i, n) is palindrome gives us the longest suffix
        for (int i = 0; i < n; i++) {
            if (isPalindrome(string.substring(i))) {
                // Found longest palindromic suffix starting at index i
                String prefix = string.substring(0, i);
                return string + new StringBuilder(prefix).reverse().toString();
            }
        }

        // Fallback (should never reach here since at least last char is palindrome)
        return string;
    }
}

