        String[] notes = string.trim().split("\\s+");

        for (String note : notes) {
            if ("o".equals(note)) {
                result.add(4);
            } else if ("o|".equals(note)) {
                result.add(2);
            } else if (".|".equals(note)) {
                result.add(1);
            }
            // Note: In production code, we might want to handle invalid inputs
            // For now, we assume the input is always valid as per the problem statement
        }

        return result;
    }
}

