class Solution {
    public double findZero(List<Double> xs) {
        // For linear: ax + b = 0 => x = -b/a
        if (xs.size() == 2) {
            return -xs.get(0) / xs.get(1);
        }

        // Bisection method for odd-degree polynomials
        double left = -10000.0;
        double right = 10000.0;

        // Ensure we have a sign change
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand interval if needed (though for odd degree, this should eventually work)
        while (fLeft * fRight > 0) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            // Safety break
            if (Math.abs(left) > 1e9) {
                // Fallback: return midpoint
                return (left + right) / 2;
            }
        }

        // Bisection loop
        for (int i = 0; i < 100; i++) { // enough iterations for double precision
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

