class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Use Horner's method for better numerical stability and performance
        double result = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For linear case: ax + b = 0 => x = -b/a
        if (xs.size() == 2) {
            double a = xs.get(1);
            double b = xs.get(0);
            if (Math.abs(a) > 1e-12) {
                return -b / a;
            }
        }

        // Derivative coefficients
        List<Double> deriv = new ArrayList<>();
        for (int i = 1; i < xs.size(); i++) {
            deriv.add(xs.get(i) * i);
        }

        // Newton-Raphson with multiple starting points
        double[] guesses = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};
        for (double x0 : guesses) {
            double x = x0;
            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < 1e-9) {
                    return x;
                }

                double fpx = poly(deriv, x);
                if (Math.abs(fpx) < 1e-12) {
                    break; // derivative too small, try next guess
                }

                x = x - fx / fpx;

                // Check if we've gone too far
                if (Double.isNaN(x) || Double.isInfinite(x)) {
                    break;
                }
            }
        }

        // If Newton-Raphson failed, try bisection
        // Find an interval [a, b] where f(a) * f(b) < 0
        double a = -1000.0;
        double b = 1000.0;
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Expand interval if needed
        int expansions = 0;
        while (fa * fb > 0 && expansions < 30) {
            a *= 2;
            b *= 2;
            fa = poly(xs, a);
            fb = poly(xs, b);
            expansions++;
        }

        if (fa * fb <= 0) {
            // Bisection method
            for (int i = 0; i < 100; i++) {
                double mid = (a + b) / 2;
                double fm = poly(xs, mid);

                if (Math.abs(fm) < 1e-9 || (b - a) < 1e-9) {
                    return mid;
                }

                if (fa * fm <= 0) {
                    b = mid;
                    fb = fm;
                } else {
                    a = mid;
                    fa = fm;
                }
            }
            return (a + b) / 2;
        }

        // Fallback: return midpoint of large interval
        return 0.0;
    }
}

