class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Newton-Raphson method with fallback to bisection
        double x = 1.0; // Initial guess

        for (int iteration = 0; iteration < 100; iteration++) {
            double fx = poly(xs, x);

            // Check if we're close enough to a root
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute numerical derivative
            double h = 1e-8;
            double fxDeriv = (poly(xs, x + h) - poly(xs, x - h)) / (2 * h);

            // Avoid division by zero or near-zero derivative
            if (Math.abs(fxDeriv) < 1e-12) {
                // Try a different initial guess if derivative is too small
                x = (iteration % 2 == 0) ? x + 1.0 : x - 1.0;
                continue;
            }

            double xNew = x - fx / fxDeriv;

            // Check if Newton step is reasonable (not going to infinity)
            if (Double.isInfinite(xNew) || Double.isNaN(xNew)) {
                x = (iteration % 2 == 0) ? x + 1.0 : x - 1.0;
                continue;
            }

            // If the new value is too far, use bisection-like approach
            if (Math.abs(xNew - x) > 1e6) {
                x = x + (fx > 0 ? -1.0 : 1.0);
            } else {
                x = xNew;
            }
        }

        // Final attempt to return a reasonable approximation
        return x;
    }
}

