class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Handle null cases (though problem states inputs are valid)
        if (a == null || b == null) {
            return "";
        }

        // Assume inputs have same length as per typical XOR requirements
        int length = Math.min(a.length(), b.length());
        StringBuilder result = new StringBuilder(length);

        for (int i = 0; i < length; i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            // XOR logic: if bits are different, result is '1', otherwise '0'
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

