class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method to find a root
        double x = 0.0; // initial guess
        double tolerance = 1e-9;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // If close enough to zero, return
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative numerically or analytically
            // Better to compute derivative analytically
            double fpx = polyDerivative(xs, x);

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-12) {
                // Try small perturbation
                x += 0.1;
                continue;
            }

            double xNew = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNew - x) < tolerance) {
                return xNew;
            }

            x = xNew;
        }

        // If didn't converge, return best estimate
        return x;
    }

    // Helper method to compute polynomial derivative
    private double polyDerivative(List<Double> coeffs, double x) {
        double result = 0;
        for (int i = 1; i < coeffs.size(); i++) {
            result += coeffs.get(i) * i * Math.pow(x, i - 1);
        }
        return result;
    }
}

