            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 1;
        int b = 1;

        // Start checking from Fibonacci numbers
        while (true) {
            // Generate next Fibonacci number
            int next = a + b;
            a = b;
            b = next;

            // Skip 1 (not prime), check if prime
            if (next > 1 && isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }
        }
    }

    private boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        if (num <= 3) {
            return true;
        }
        if (num % 2 == 0 || num % 3 == 0) {
            return false;
        }

        // Check divisors up to sqrt(num)
        for (int i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

