    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Use Newton-Raphson method
        // Start with initial guess
        double x = 1.0;
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative using numerical differentiation
            double h = 1e-8;
            double fpx = (poly(xs, x + h) - poly(xs, x - h)) / (2 * h);

            // Avoid division by zero
            if (Math.abs(fpx) < tolerance) {
                // Try a different starting point
                x = x + 1.0;
                continue;
            }

            double newX = x - fx / fpx;

            // Check for convergence
            if (Math.abs(newX - x) < tolerance) {
                return newX;
            }

            x = newX;
        }

        // If we didn't converge, return current best guess
        return x;
    }
}

