class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        // Use Map interface instead of HashMap implementation
        Map<String, Integer> numMap = new HashMap<>();
        numMap.put("zero", 0);
        numMap.put("one", 1);
        numMap.put("two", 2);
        numMap.put("three", 3);
        numMap.put("four", 4);
        numMap.put("five", 5);
        numMap.put("six", 6);
        numMap.put("seven", 7);
        numMap.put("eight", 8);
        numMap.put("nine", 9);

        // Handle empty or null input
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        // Split into words and collect into list
        String[] words = numbers.trim().split("\\s+");
        List<String> wordList = new ArrayList<>(Arrays.asList(words));

        // Sort based on numeric value using the map
        Collections.sort(wordList, (a, b) -> numMap.get(a) - numMap.get(b));

        // Join back into string
        return String.join(" ", wordList);
    }
}

