class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method
        double x = 0.0; // start at 0

        // Try multiple starting points if needed
        for (int start = 0; start < 10; start++) {
            double current = start - 5.0; // try from -5 to 4

            for (int i = 0; i < 100; i++) { // max iterations
                double fx = poly(xs, current);

                // Check if we found a root
                if (Math.abs(fx) < 1e-9) {
                    return current;
                }

                // Compute derivative: f'(x) = sum(i * xs[i] * x^(i-1))
                double fpx = 0.0;
                for (int j = 1; j < xs.size(); j++) {
                    fpx += j * xs.get(j) * Math.pow(current, j - 1);
                }

                // Avoid division by zero
                if (Math.abs(fpx) < 1e-9) {
                    break;
                }

                double next = current - fx / fpx;

                // Check for convergence
                if (Math.abs(next - current) < 1e-9) {
                    double finalFx = poly(xs, next);
                    if (Math.abs(finalFx) < 1e-9) {
                        return next;
                    }
                    break;
                }

                current = next;
            }
        }

        // Fallback: binary search for sign change
        double left = -1000.0;
        double right = 1000.0;

        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fmid = poly(xs, mid);

            if (Math.abs(fmid) < 1e-9) {
                return mid;
            }

            double fleft = poly(xs, left);
            if (fleft * fmid <= 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2;
    }
}

