import java.util.*;
import java.lang.*;

class Solution {
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // All other even numbers are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        // We only need to check up to sqrt(n) because if n = a*b and a <= b,
        // then a <= sqrt(n), so we'd find the smaller factor first
        int sqrtN = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For linear case: ax + b = 0 => x = -b/a
        if (xs.size() == 2) {
            double a = xs.get(1);
            double b = xs.get(0);
            if (Math.abs(a) > 1e-15) {
                return -b / a;
            }
        }

        // Newton-Raphson method with multiple starting points
        double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0, 0.5, -0.5};
        double bestResult = Double.NaN;
        double bestResidual = Double.MAX_VALUE;

        for (double start : startingPoints) {
            double root = newtonRaphson(xs, start);
            if (!Double.isNaN(root)) {
                double residual = Math.abs(poly(xs, root));
                if (residual < bestResidual) {
                    bestResidual = residual;
                    bestResult = root;
                }
            }
        }

        // If Newton-Raphson failed, try bisection
        if (Double.isNaN(bestResult) || bestResidual > 1e-9) {
            bestResult = bisection(xs);
        }

        return bestResult;
    }

    private double newtonRaphson(List<Double> coeffs, double x0) {
        double x = x0;
        for (int i = 0; i < 100; i++) { // max iterations
            double fx = poly(coeffs, x);
            if (Math.abs(fx) < 1e-15) {
                return x;
            }

            // Compute derivative
            double fpx = derivative(coeffs, x);

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-15) {
                return Double.NaN;
            }

            double xNext = x - fx / fpx;

            // Check for convergence or overflow
            if (Double.isInfinite(xNext) || Double.isNaN(xNext)) {
                return Double.NaN;
            }

            if (Math.abs(xNext - x) < 1e-12) {
                return xNext;
            }

            x = xNext;
        }
        return x;
    }

    private double derivative(List<Double> coeffs, double x) {
        double result = 0;
        for (int i = 1; i < coeffs.size(); i++) {
            result += i * coeffs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }

    private double bisection(List<Double> coeffs) {
        // Find an interval [a, b] where f(a) * f(b) < 0
        double a = -100.0;
        double b = 100.0;

        // Expand interval until we find sign change
        for (int expand = 0; expand < 10; expand++) {
            double fa = poly(coeffs, a);
            double fb = poly(coeffs, b);

            if (fa * fb <= 0) {
                // Bisection method
                for (int i = 0; i < 100; i++) {
                    double mid = (a + b) / 2;
                    double fm = poly(coeffs, mid);

                    if (Math.abs(fm) < 1e-12 || (b - a) / 2 < 1e-12) {
                        return mid;
                    }

                    if (fa * fm <= 0) {
                        b = mid;
                        fb = fm;
                    } else {
                        a = mid;
                        fa = fm;
                    }
                }
                return (a + b) / 2;
            }

            a *= 2;
            b *= 2;
        }

        // Fallback: return midpoint of search range
        return (a + b) / 2;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    This function takes a list l and returns a list l' such that
    l' is identical to l in the indicies that are not divisible by three, while its values at the indicies that are divisible by three are equal
    to the values of the corresponding indicies of l, but sorted.
    >>> sortThird(Arrays.asList(1, 2, 3))
    [1, 2, 3]
    >>> sortThird(Arrays.asList(5, 6, 3, 4, 8, 9, 2))
    [2, 6, 3, 4, 8, 9, 5]
     */
    public List<Integer> sortThird(List<Integer> l) {
        // Create a new list to return
        List<Integer> result = new ArrayList<>(l);

        // Collect elements at indices divisible by 3 (0, 3, 6, ...)
        List<Integer> thirdElements = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 3) {
            thirdElements.add(l.get(i));
        }

        // Sort these elements
        Collections.sort(thirdElements);

        // Put the sorted elements back into their positions
        int sortedIndex = 0;
        for (int i = 0; i < result.size(); i += 3) {
            result.set(i, thirdElements.get(sortedIndex++));
        }

        return result;
    }
}

