    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }
        // Check odd divisors from 3 to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Find the highest degree non-zero coefficient to determine leading term
        int n = xs.size() - 1; // degree of polynomial
        double leadingCoeff = 0;
        for (int i = n; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) {
                leadingCoeff = xs.get(i);
                break;
            }
        }

        // For odd degree polynomials, as x->∞, p(x)->sign(leadingCoeff)*∞
        // as x->-∞, p(x)->-sign(leadingCoeff)*∞ (since degree is odd)
        // So there must be a root somewhere

        // Try bisection with expanding interval
        double left = -100.0;
        double right = 100.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand interval until we bracket a root
        int expansionCount = 0;
        while (fLeft * fRight > 0 && expansionCount < 30) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            expansionCount++;
        }

        // If still no sign change, just return midpoint as fallback
        if (fLeft * fRight > 0) {
            return (left + right) / 2;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations should be enough for double precision
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

