class Solution {
    public String makePalindrome(String string) {
        // Handle empty string
        if (string.isEmpty()) {
            return "";
        }

        // Find the longest palindromic suffix
        for (int i = 0; i < string.length(); i++) {
            // Check if substring from i to end is a palindrome
            if (isPalindrome(string.substring(i))) {
                // If yes, append reverse of prefix (substring from 0 to i)
                String prefix = string.substring(0, i);
                return string + new StringBuilder(prefix).reverse().toString();
            }
        }

        // Fallback (should never reach here since single char is always palindrome)
        return string;
    }
}

