class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        // Map number words to their integer values
        Map<String, Integer> wordToNum = new HashMap<>();
        wordToNum.put("zero", 0);
        wordToNum.put("one", 1);
        wordToNum.put("two", 2);
        wordToNum.put("three", 3);
        wordToNum.put("four", 4);
        wordToNum.put("five", 5);
        wordToNum.put("six", 6);
        wordToNum.put("seven", 7);
        wordToNum.put("eight", 8);
        wordToNum.put("nine", 9);

        // Map integer values back to words
        Map<Integer, String> numToWord = new HashMap<>();
        numToWord.put(0, "zero");
        numToWord.put(1, "one");
        numToWord.put(2, "two");
        numToWord.put(3, "three");
        numToWord.put(4, "four");
        numToWord.put(5, "five");
        numToWord.put(6, "six");
        numToWord.put(7, "seven");
        numToWord.put(8, "eight");
        numToWord.put(9, "nine");

        // Split the input string and process each word
        String[] words = numbers.split(" ");
        List<Integer> numericValues = new ArrayList<>();

        for (String word : words) {
            if (!word.isEmpty()) {
                numericValues.add(wordToNum.get(word));
            }
        }

        // Sort numerically
        Collections.sort(numericValues);

        // Convert back to words
        List<String> sortedWords = new ArrayList<>();
        for (Integer num : numericValues) {
            sortedWords.add(numToWord.get(num));
        }

        // Join with spaces
        return String.join(" ", sortedWords);
    }
}

