class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Newton-Raphson method
        double x = 1.0; // initial guess
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // Check if close enough to zero
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative
            double fpx = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fpx += i * xs.get(i) * Math.pow(x, i - 1);
            }

            // Avoid division by zero or very small derivative
            if (Math.abs(fpx) < 1e-15) {
                // Try a different starting point or use bisection fallback
                // For simplicity, perturb x slightly
                x += 0.1;
                continue;
            }

            double xNew = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNew - x) < tolerance) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNew)) < 1e-8) {
                    return xNew;
                }
            }

            x = xNew;
        }

        // Fallback: if Newton-Raphson didn't converge, try bisection between -1000 and 1000
        // Since odd-degree polynomials go to ±infinity, there must be sign change somewhere
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Ensure sign change (if not, expand search range)
        while (fLeft * fRight > 0) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            // Safety check to avoid infinite loop
            if (Math.abs(left) > 1e10) {
                break;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance || (right - left) < tolerance) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Final return as fallback
        return (left + right) / 2;
    }
}

