class Solution {
    public double findZero(List<Double> xs) {
        // Handle degenerate case: constant polynomial (shouldn't happen per constraints)
        if (xs.size() <= 1) {
            return 0.0;
        }

        // Use Newton-Raphson method to find a root
        double x = 1.0; // initial guess
        final int MAX_ITERATIONS = 100;
        final double EPSILON = 1e-10;

        for (int i = 0; i < MAX_ITERATIONS; i++) {
            double fx = poly(xs, x);

            // Check if we've found a root
            if (Math.abs(fx) < EPSILON) {
                return x;
            }

            // Compute derivative using Horner's method for efficiency and accuracy
            // For polynomial a0 + a1*x + a2*x^2 + ... + an*x^n,
            // derivative is a1 + 2*a2*x + 3*a3*x^2 + ... + n*an*x^(n-1)
            double fpx = 0.0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            // Avoid division by zero
            if (Math.abs(fpx) < EPSILON) {
                // Try a different initial guess if derivative is too small
                x += 0.1;
                continue;
            }

            double nextX = x - fx / fpx;

            // Check for convergence
            if (Math.abs(nextX - x) < EPSILON) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, nextX)) < EPSILON) {
                    return nextX;
                }
            }

            x = nextX;
        }

        // Fallback: return best approximation
        return x;
    }
}

