class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Generate Fibonacci numbers and check for primality
        int a = 0; // F(0)
        int b = 1; // F(1)
        int count = 0;

        // Handle special case: F(1) = 1 is not prime, so start checking from F(2) onwards
        while (true) {
            int next = a + b;
            a = b;
            b = next;

            // Check if current Fibonacci number (b) is prime
            if (isPrime(b)) {
                count++;
                if (count == n) {
                    return b;
                }
            }
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

