class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return -1; // No proper divisors for n <= 1
        }

        // Start checking from n/2 downwards, as the largest proper divisor 
        // cannot be larger than n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // This line is technically unreachable for n > 1, but included for safety
    }
}

