        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        double xPower = 1; // Start with x^0 = 1
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * xPower;
            xPower *= x; // Use multiplication instead of Math.pow for efficiency
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method
        double x = 0.0; // Initial guess
        double epsilon = 1e-10;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // Check if we're close enough to a root
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative at x
            double fPrimeX = polyDerivative(xs, x);

            // Avoid division by zero
            if (Math.abs(fPrimeX) < epsilon) {
                // Try a small perturbation if derivative is near zero
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fPrimeX;

            // Check for convergence
            if (Math.abs(xNext - x) < epsilon) {
                return xNext;
            }

            x = xNext;
        }

        // Fallback: return last estimate if didn't converge
        return x;
    }

    // Helper method to evaluate derivative of polynomial
    private double polyDerivative(List<Double> xs, double x) {
        // Derivative of a_0 + a_1*x + a_2*x^2 + ... + a_n*x^n
        // is a_1 + 2*a_2*x + 3*a_3*x^2 + ... + n*a_n*x^(n-1)
        double result = 0;
        double xPower = 1; // Start with x^0 = 1 for the constant term in derivative

        // Skip the first coefficient (a_0) since its derivative is 0
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * xPower;
            xPower *= x;
        }

        return result;
    }
}

