class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return 0; // or -1, depending on requirements, but 1 has no proper divisors
        }

        // Check for smallest divisor from 2 to sqrt(n)
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                // Found smallest divisor i, so n/i is the largest proper divisor
                return n / i;
            }
        }

        // If we reach here, n is prime, so the largest proper divisor is 1
        return 1;
    }
}

