class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Use Horner's method for better numerical stability and efficiency
        double result = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method
        double x = 1.0; // initial guess

        // Maximum iterations to avoid infinite loops
        int maxIterations = 100;
        double tolerance = 1e-10;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);

            // If we're close enough to zero, return
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative using finite differences if needed,
            // or compute derivative coefficients analytically
            double fpx = polyDerivative(xs, x);

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-15) {
                // Try a different initial guess or perturb
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < tolerance) {
                // Verify this is actually a root
                if (Math.abs(poly(xs, xNext)) < tolerance) {
                    return xNext;
                }
            }

            x = xNext;
        }

        // Fallback: return best approximation found
        return x;
    }

    // Helper method to evaluate derivative of polynomial
    private double polyDerivative(List<Double> coeffs, double x) {
        if (coeffs.size() <= 1) {
            return 0;
        }

        // Derivative coefficients: for a_n*x^n + ... + a_1*x + a_0,
        // derivative is n*a_n*x^(n-1) + ... + 1*a_1
        List<Double> derivCoeffs = new ArrayList<>();
        for (int i = 1; i < coeffs.size(); i++) {
            derivCoeffs.add(coeffs.get(i) * i);
        }

        return poly(derivCoeffs, x);
    }
}

