class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Handle special case: we need to find n prime Fibonacci numbers
        int count = 0;
        int a = 1, b = 1; // First two Fibonacci numbers

        // Check the first Fibonacci number (1)
        if (isPrime(a)) {
            count++;
            if (count == n) {
                return a;
            }
        }

        // Generate subsequent Fibonacci numbers
        while (true) {
            int c = a + b;
            a = b;
            b = c;

            if (isPrime(c)) {
                count++;
                if (count == n) {
                    return c;
                }
            }
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

