class Solution {
    /**
     * Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
     * For each of the groups, output the deepest level of nesting of parentheses.
     * E.g. (()()) has maximum two levels of nesting while ((())) has three.
     *
     * >>> parseNestedParens("(()()) ((())) () ((())()())")
     * [2, 3, 1, 3]
     */
    public List<Integer> parseNestedParens(String parenString) {
        List<Integer> depths = new ArrayList<>();

        // Split by spaces to get individual parenthesis groups
        String[] groups = parenString.split(" ");

        for (String group : groups) {
            int maxDepth = 0;
            int currentDepth = 0;

            // Scan each character in the group
            for (int i = 0; i < group.length(); i++) {
                char c = group.charAt(i);

                if (c == '(') {
                    currentDepth++;
                    maxDepth = Math.max(maxDepth, currentDepth);
                } else if (c == ')') {
                    currentDepth--;
                }
            }

            depths.add(maxDepth);
        }

        return depths;
    }
}

