     * ["abc", "bacd", "array"]
     */
    public List<String> filterBySubstring(List<String> strings, String substring) {
        // Handle edge cases
        if (strings == null) {
            return new ArrayList<>();
        }

        // If substring is null, return empty list (as null.contains() would throw NPE)
        if (substring == null) {
            return new ArrayList<>();
        }

        // Create result list
        List<String> result = new ArrayList<>();

        // If substring is empty, include all strings (every string contains empty string)
        if (substring.isEmpty()) {
            result.addAll(strings);
            return result;
        }

        // Filter strings that contain the substring
        for (String str : strings) {
            if (str != null && str.contains(substring)) {
                result.add(str);
            }
        }

        return result;
    }
}

