class Solution {
    public double findZero(List<Double> xs) {
        // Ensure even number of coefficients (as per problem requirement)
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Bisection method with interval expansion
        double low = -1000.0;
        double high = 1000.0;

        // Check if we need to expand interval to find sign change
        double fLow = poly(xs, low);
        double fHigh = poly(xs, high);

        // If same sign, expand interval until we get opposite signs
        int expansions = 0;
        while (fLow * fHigh > 0 && expansions < 30) {
            low *= 2;
            high *= 2;
            fLow = poly(xs, low);
            fHigh = poly(xs, high);
            expansions++;
        }

        // Now apply bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~1e-30 precision
            double mid = (low + high) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLow * fMid <= 0) {
                high = mid;
                fHigh = fMid;
            } else {
                low = mid;
                fLow = fMid;
            }
        }

        return (low + high) / 2;
    }
}

