class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 0; // F(0)
        int b = 1; // F(1)

        // Handle the first few Fibonacci numbers explicitly since the loop starts from F(2)
        // Check F(0) = 0 - not prime
        // Check F(1) = 1 - not prime
        // Check F(2) = 1 - not prime
        // Check F(3) = 2 - prime
        // Check F(4) = 3 - prime
        // Check F(5) = 5 - prime
        // Check F(6) = 8 - not prime
        // Check F(7) = 13 - prime
        // etc.

        // Start generating from F(2) onwards, but check earlier ones too
        if (n == 1) {
            return 2; // First prime Fibonacci is 2 (F(3))
        }

        // We'll generate Fibonacci numbers starting from index 2
        int index = 2;

        while (true) {
            int next = a + b;
            a = b;
            b = next;
            index++;

            // Check if current Fibonacci number is prime
            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

