class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Handle edge cases - if lengths differ, we can pad the shorter one with leading zeros
        // or return empty string if lengths don't match (depending on interpretation)
        // Since the problem doesn't specify, I'll assume same length as per typical binary operations

        int len = Math.min(a.length(), b.length());
        StringBuilder result = new StringBuilder();

        for (int i = 0; i < len; i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            // XOR operation: same bits give 0, different bits give 1
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

