class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs.isEmpty()) {
            return 0.0;
        }

        // Find the highest non-zero coefficient index to determine degree
        int degree = xs.size() - 1;
        while (degree >= 0 && Math.abs(xs.get(degree)) < 1e-12) {
            degree--;
        }

        // If all coefficients are zero, any x is a solution
        if (degree < 0) {
            return 0.0;
        }

        // For odd degree polynomials, we know there's at least one real root
        // Use bisection method with interval expansion

        double left = -1.0;
        double right = 1.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand interval until we find a sign change
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 30) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // If still no sign change, try negative left
        if (fLeft * fRight > 0) {
            // Try symmetric around 0 with larger bounds
            left = -1000.0;
            right = 1000.0;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // sufficient iterations for double precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

