class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Handle special cases - first few prime Fibonacci numbers
        if (n == 1) return 2;
        if (n == 2) return 3;
        if (n == 3) return 5;
        if (n == 4) return 13;
        if (n == 5) return 89;

        int count = 5; // We've already handled up to the 5th prime Fibonacci

        // Start generating from F(10) = 55 onwards to find more prime Fibonacci numbers
        long prev2 = 21; // F(8)
        long prev1 = 34; // F(9)
        long current = 55; // F(10)

        while (true) {
            current = prev1 + prev2;

            if (isPrime(current)) {
                count++;
                if (count == n) {
                    return (int) current;
                }
            }

            prev2 = prev1;
            prev1 = current;
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;

        // Check for divisibility by numbers of form 6k ± 1
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

