import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Binary search / bisection method
        // First, define the polynomial function
        final List<Double> coeffs = xs;

        // Find an interval where the function changes sign
        // For odd-degree polynomials, as x->+inf, f(x)->sign(lc)*inf, as x->-inf, f(x)->-sign(lc)*inf
        // where lc is leading coefficient (last non-zero coefficient)

        // Find leading coefficient (last non-zero coefficient)
        double leadingCoeff = 0;
        for (int i = coeffs.size() - 1; i >= 0; i--) {
            if (Math.abs(coeffs.get(i)) > 1e-12) {
                leadingCoeff = coeffs.get(i);
                break;
            }
        }

        // Determine direction: if leading coeff > 0, then f(+inf) = +inf, f(-inf) = -inf
        // if leading coeff < 0, then f(+inf) = -inf, f(-inf) = +inf

        // Start with a reasonable interval and expand until we find sign change
        double left = -100.0;
        double right = 100.0;

        double fLeft = poly(coeffs, left);
        double fRight = poly(coeffs, right);

        // Expand interval until we get sign change
        int expansionCount = 0;
        while (fLeft * fRight > 0 && expansionCount < 30) {
            left *= 2;
            right *= 2;
            fLeft = poly(coeffs, left);
            fRight = poly(coeffs, right);
            expansionCount++;
        }

        // Now apply bisection method
        double mid = 0;
        for (int i = 0; i < 100; i++) { // 100 iterations for precision
            mid = (left + right) / 2;
            double fMid = poly(coeffs, mid);

            if (Math.abs(fMid) < 1e-12) {
                break;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return mid;
    }
}

