    [2.0, 2.0]
     */
    public List<Double> findClosestElements(List<Double> numbers) {
        // Create a copy and sort it
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        double minDiff = Double.MAX_VALUE;
        int minIndex = 0;

        // Check adjacent pairs in sorted list
        for (int i = 0; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < minDiff) {
                minDiff = diff;
                minIndex = i;
            }
        }

        // Return the pair in order (smaller, larger)
        double first = sorted.get(minIndex);
        double second = sorted.get(minIndex + 1);

        List<Double> result = new ArrayList<>();
        result.add(Math.min(first, second));
        result.add(Math.max(first, second));

        return result;
    }
}

