class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Use Horner's method for efficiency
        double result = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle linear case explicitly: a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (b != 0) {
                return -a / b;
            }
        }

        // For higher degrees, use Newton-Raphson method
        // Start with initial guess 0
        double x = 0.0;
        double epsilon = 1e-10;

        for (int iter = 0; iter < 100; iter++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Calculate derivative using finite differences or analytically
            // For simplicity, use numerical derivative
            double h = 1e-7;
            double fpx = (poly(xs, x + h) - poly(xs, x - h)) / (2 * h);

            if (Math.abs(fpx) < epsilon) {
                // Derivative too small, try perturbation
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check if we're converging
            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                // Fallback to bisection if Newton fails
                return bisection(xs, -1000.0, 1000.0, epsilon);
            }

            if (Math.abs(xNext - x) < epsilon) {
                return xNext;
            }

            x = xNext;
        }

        // Final fallback: bisection
        return bisection(xs, -1000.0, 1000.0, 1e-8);
    }

    // Bisection method as fallback
    private double bisection(List<Double> xs, double a, double b, double epsilon) {
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Ensure we have a sign change
        if (fa * fb > 0) {
            // Try different intervals
            for (int i = 0; i < 20; i++) {
                double start = -Math.pow(2, i);
                double end = Math.pow(2, i);
                double fStart = poly(xs, start);
                double fEnd = poly(xs, end);
                if (fStart * fEnd <= 0) {
                    a = start;
                    b = end;
                    fa = fStart;
                    fb = fEnd;
                    break;
                }
            }
        }

        while (Math.abs(b - a) > epsilon) {
            double mid = (a + b) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < epsilon) {
                return mid;
            }

            if (fa * fMid < 0) {
                b = mid;
                fb = fMid;
            } else {
                a = mid;
                fa = fMid;
            }
        }

        return (a + b) / 2;
    }
}

