        // Sort the list to make comparison efficient - adjacent elements are most likely to be close
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        // Check only adjacent pairs in the sorted list
        for (int i = 0; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < threshold) {
                return true;
            }
        }

        return false;
    }
}

