class Solution {
    public double findZero(List<Double> xs) {
        // Create a function to evaluate polynomial
        java.util.function.DoubleUnaryOperator f = x -> poly(xs, x);

        // For odd-degree polynomial, we know limits as x->±∞
        // Leading term dominates: if leading coefficient > 0, f(x)->+∞ as x->+∞, f(x)->-∞ as x->-∞
        // if leading coefficient < 0, f(x)->-∞ as x->+∞, f(x)->+∞ as x->-∞

        int n = xs.size() - 1; // degree of polynomial
        double leadCoeff = xs.get(n);

        // Find initial bounds where f(a) and f(b) have opposite signs
        double a = -1000.0;
        double b = 1000.0;

        // Expand bounds until we find opposite signs
        while (f.applyAsDouble(a) * f.applyAsDouble(b) > 0) {
            a *= 10;
            b *= 10;
            if (Math.abs(a) > 1e8) {
                // Fallback: try different strategy if expansion fails
                a = -10.0;
                b = 10.0;
                break;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations for high precision
            double mid = (a + b) / 2.0;
            double fMid = f.applyAsDouble(mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (f.applyAsDouble(a) * fMid < 0) {
                b = mid;
            } else {
                a = mid;
            }
        }

        return (a + b) / 2.0;
    }
}

