class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special case: F(0)=0, F(1)=1, F(2)=1, F(3)=2, ...
        // We need to check each Fibonacci number starting from the beginning

        // Check F(0) = 0
        if (isPrime(a)) {
            count++;
            if (count == n) return (int)a;
        }

        // Check F(1) = 1
        if (isPrime(b)) {
            count++;
            if (count == n) return (int)b;
        }

        // Generate remaining Fibonacci numbers
        while (true) {
            long c = a + b;
            a = b;
            b = c;

            if (c > Integer.MAX_VALUE) {
                // This shouldn't happen for reasonable n based on examples, but just in case
                throw new ArithmeticException("Fibonacci number exceeds Integer.MAX_VALUE");
            }

            if (isPrime((int)c)) {
                count++;
                if (count == n) {
                    return (int)c;
                }
            }
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

