class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Precondition: n must be greater than 1 to have a proper divisor
        if (n <= 1) {
            throw new IllegalArgumentException("n must be greater than 1");
        }

        // The largest proper divisor cannot be larger than n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // This should never happen for n > 1, but just in case
        throw new IllegalStateException("No divisor found for " + n);
    }
}

