class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Validate input: must have even number of coefficients
        if (xs == null || xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Handle linear case directly: a + bx = 0 -> x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) < 1e-15) {
                throw new IllegalArgumentException("Linear coefficient must be non-zero");
            }
            return -a / b;
        }

        // For higher degrees, use Newton-Raphson method
        double x = 0.0; // initial guess

        // Try multiple starting points to increase chances of convergence
        double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

        for (double start : startingPoints) {
            x = start;
            for (int iteration = 0; iteration < 100; iteration++) {
                double fx = poly(xs, x);

                // Check if we've found a root
                if (Math.abs(fx) < 1e-12) {
                    return x;
                }

                // Calculate derivative: f'(x)
                double fPrimeX = 0;
                for (int i = 1; i < xs.size(); i++) {
                    fPrimeX += i * xs.get(i) * Math.pow(x, i - 1);
                }

                // Avoid division by zero
                if (Math.abs(fPrimeX) < 1e-12) {
                    break; // try next starting point
                }

                double newX = x - fx / fPrimeX;

                // Check for convergence
                if (Math.abs(newX - x) < 1e-12) {
                    return x;
                }

                // Check if we're diverging (value too large)
                if (Math.abs(newX) > 1e10) {
                    break; // try next starting point
                }

                x = newX;
            }
        }

        // Fallback: if Newton-Raphson failed, try bisection on a reasonable range
        // Since we know there's guaranteed to be a root, search in [-100, 100]
        double left = -100.0;
        double right = 100.0;
        double mid = (left + right) / 2;

        for (int i = 0; i < 100; i++) {
            mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            double fLeft = poly(xs, left);
            if (fLeft * fMid <= 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return mid;
    }
}

