class Solution {
    /**
    Test if given string is a palindrome
     */
    public boolean isPalindrome(String string) {
        int i = 0;
        int j = string.length() - 1;
        while (i < j) {
            if (string.charAt(i) != string.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    /**
    Find the shortest palindrome that begins with a supplied string.
    Algorithm idea is simple:
    - Find the longest postfix of supplied string that is a palindrome.
    - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
    >>> makePalindrome("")
    ""
    >>> makePalindrome("cat")
    "catac"
    >>> makePalindrome("cata")
    "catac"
     */
    public String makePalindrome(String string) {
        if (string == null || string.isEmpty()) {
            return string;
        }

        // Find the longest palindromic suffix
        for (int i = 0; i < string.length(); i++) {
            // Check if substring from i to end is a palindrome
            if (isPalindrome(string.substring(i))) {
                // Found longest palindromic suffix starting at index i
                // Get the prefix before this suffix (from 0 to i-1)
                String prefix = string.substring(0, i);
                // Reverse the prefix and append to original string
                String reversedPrefix = new StringBuilder(prefix).reverse().toString();
                return string + reversedPrefix;
            }
        }

        // Fallback (shouldn't reach here since single char is always palindrome)
        return string;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Ensure both strings have the same length by padding with leading zeros
        int lenA = a.length();
        int lenB = b.length();
        int maxLen = Math.max(lenA, lenB);

        // Pad both strings to the same length
        StringBuilder paddedA = new StringBuilder();
        StringBuilder paddedB = new StringBuilder();

        // Pad string a with leading zeros
        for (int i = 0; i < maxLen - lenA; i++) {
            paddedA.append('0');
        }
        paddedA.append(a);

        // Pad string b with leading zeros
        for (int i = 0; i < maxLen - lenB; i++) {
            paddedB.append('0');
        }
        paddedB.append(b);

        // Perform XOR operation character by character
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < maxLen; i++) {
            char bitA = paddedA.charAt(i);
            char bitB = paddedB.charAt(i);

            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

