class Solution {
    /**
    Return list of prime factors of given integer in the order from smallest to largest.
    Each of the factors should be listed number of times corresponding to how many times it appeares in factorization.
    Input number should be equal to the product of all factors
    >>> factorize(8)
    [2, 2, 2]
    >>> factorize(25)
    [5, 5]
    >>> factorize(70)
    [2, 5, 7]
     */
    public List<Integer> factorize(int n) {
        if (n <= 1) {
            throw new IllegalArgumentException("Input must be greater than 1 for prime factorization");
        }

        List<Integer> factors = new ArrayList<>();
        int num = n;

        // Check for factor 2 separately to optimize for odd numbers later
        while (num % 2 == 0) {
            factors.add(2);
            num /= 2;
        }

        // Now check odd factors starting from 3
        for (int i = 3; i * i <= num; i += 2) {
            while (num % i == 0) {
                factors.add(i);
                num /= i;
            }
        }

        // If num is still greater than 1, then it's a prime factor
        if (num > 1) {
            factors.add(num);
        }

        return factors;
    }
}

