class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        if (xs == null || xs.isEmpty()) {
            throw new IllegalArgumentException("Coefficient list cannot be null or empty");
        }

        // Check that list has even number of coefficients
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("Coefficient list must have even number of coefficients");
        }

        // Find the highest degree term (largest non-zero coefficient from the end)
        int degree = xs.size() - 1;
        double leadingCoeff = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-15) {  // Non-zero check with tolerance
                leadingCoeff = xs.get(i);
                degree = i;
                break;
            }
        }

        // If all coefficients are zero, every x is a solution, return 0
        if (Math.abs(leadingCoeff) < 1e-15) {
            return 0.0;
        }

        // For odd-degree polynomials, there's always at least one real root
        // We'll use Newton's method with multiple starting points to find a root

        // Try different starting points
        double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0, 100.0, -100.0};

        for (double start : startingPoints) {
            double root = newtonMethod(xs, start);
            if (Math.abs(poly(xs, root)) < 1e-9) {
                return root;
            }
        }

        // Fallback: try bisection method on a large interval
        double left = -1000.0, right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If signs are different, bisection should work
        if (fLeft * fRight <= 0) {
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);
                if (Math.abs(fMid) < 1e-9) {
                    return mid;
                }
                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
            return (left + right) / 2;
        }

        // If all else fails, return a reasonable default
        return 0.0;
    }

    private double newtonMethod(List<Double> xs, double startX) {
        double x = startX;
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative: f'(x) = sum_{k=1}^{n} k * coeff[k] * x^(k-1)
            double fPrimeX = 0;
            for (int k = 1; k < xs.size(); k++) {
                fPrimeX += k * xs.get(k) * Math.pow(x, k - 1);
            }

            // Avoid division by zero
            if (Math.abs(fPrimeX) < 1e-12) {
                // Try a small perturbation
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fPrimeX;

            // Check if we're diverging
            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                return startX; // Give up and return starting point
            }

            x = xNext;
        }
        return x;
    }
}

