        double max = Collections.max(numbers);

        // Handle the case where all numbers are the same
        if (max == min) {
            // All values become 0.0 (or could be 0.5, but 0.0 is standard for min-max scaling)
            return new ArrayList<>(Collections.nCopies(numbers.size(), 0.0));
        }

        double range = max - min;
        List<Double> result = new ArrayList<>(numbers.size());

        for (double num : numbers) {
            result.add((num - min) / range);
        }

        return result;
    }
}

