class Solution {
    public double findZero(List<Double> xs) {
        // Bisection method
        double low = -1000.0;
        double high = 1000.0;
        double tolerance = 1e-9;

        // Evaluate at endpoints
        double fLow = poly(xs, low);
        double fHigh = poly(xs, high);

        // If no sign change, expand interval
        while (fLow * fHigh > 0) {
            low *= 10;
            high *= 10;
            fLow = poly(xs, low);
            fHigh = poly(xs, high);
            // Safety check to prevent infinite loop
            if (Math.abs(low) > 1e7) {
                break;
            }
        }

        // Bisection loop
        for (int i = 0; i < 100; i++) {  // max iterations
            double mid = (low + high) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance) {
                return mid;
            }

            if (fLow * fMid <= 0) {
                high = mid;
                fHigh = fMid;
            } else {
                low = mid;
                fLow = fMid;
            }
        }

        return (low + high) / 2;
    }
}

