class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long fib1 = 0; // F(0)
        long fib2 = 1; // F(1)

        // Check the first few Fibonacci numbers manually since F(0)=0, F(1)=1, F(2)=1 are not prime
        while (true) {
            long nextFib = fib1 + fib2;
            fib1 = fib2;
            fib2 = nextFib;

            if (isPrime(fib2)) {
                count++;
                if (count == n) {
                    return (int) fib2;
                }
            }

            // Safety check to prevent overflow issues - though for typical inputs this won't be hit
            if (fib2 > Integer.MAX_VALUE) {
                throw new ArithmeticException("Result exceeds Integer.MAX_VALUE");
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

