        for (String note : notes) {
            switch (note) {
                case "o":
                    result.add(4);
                    break;
                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // For robustness, could throw IllegalArgumentException or skip
                    // Based on problem statement, we assume valid input, so no need for error handling
                    break;
            }
        }
        return result;
    }
}

