class Solution {
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge case: constant polynomial
        if (xs.size() == 1) {
            // If constant is zero, any x works; otherwise no solution
            return 0.0;
        }

        // Since we're guaranteed a solution exists and the polynomial has odd degree
        // (even number of coefficients means degree = n-1 is odd), we know there's at least one real root

        // Try Newton-Raphson with multiple starting points
        // First, try some simple rational guesses based on Rational Root Theorem heuristics
        // For the example, we can try small integers first

        // Try integer candidates: -10, -9, ..., -1, 0, 1, ..., 10
        for (double guess = -10; guess <= 10; guess++) {
            double result = newtonRaphson(xs, guess);
            if (Math.abs(poly(xs, result)) < 1e-9) {
                return result;
            }
        }

        // If that fails, use bisection with expanding search
        double left = -100.0;
        double right = 100.0;

        // Expand search range until we find a sign change
        while (left > -1e6 && right < 1e6) {
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            if (fLeft == 0) return left;
            if (fRight == 0) return right;

            if (fLeft * fRight < 0) {
                // Sign change found, use bisection
                return bisection(xs, left, right);
            }

            left *= 2;
            right *= 2;
        }

        // Fallback: return midpoint if nothing else works
        return 0.0;
    }

    private double newtonRaphson(List<Double> xs, double initialGuess) {
        double x = initialGuess;
        for (int i = 0; i < 100; i++) { // max iterations
            double fx = poly(xs, x);

            // Check if we're close enough
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative: f'(x) = sum_{k=1}^{n} k * a_k * x^{k-1}
            double dfx = 0;
            for (int k = 1; k < xs.size(); k++) {
                dfx += k * xs.get(k) * Math.pow(x, k - 1);
            }

            // Avoid division by zero
            if (Math.abs(dfx) < 1e-12) {
                // Try a small perturbation
                x += 0.001;
                continue;
            }

            double xNext = x - fx / dfx;

            // Check for convergence
            if (Math.abs(xNext - x) < 1e-12) {
                return xNext;
            }

            x = xNext;
        }
        return x; // Return last approximation
    }

    private double bisection(List<Double> xs, double left, double right) {
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Ensure we have a sign change
        if (fLeft * fRight >= 0) {
            return left; // Should not happen given our logic
        }

        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

