class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 1, b = 1;

        // Check first two Fibonacci numbers (1, 1) - neither is prime
        while (true) {
            long next = a + b;
            a = b;
            b = next;

            // Check if current Fibonacci number (b) is prime
            if (isPrime(b)) {
                count++;
                if (count == n) {
                    return (int) b;
                }
            }

            // Safety check to prevent overflow issues for very large n
            if (b > Integer.MAX_VALUE) {
                break;
            }
        }

        throw new IllegalStateException("Failed to find the " + n + "-th prime Fibonacci number");
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        long sqrt = (long) Math.sqrt(num);
        for (long i = 3; i <= sqrt; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

