class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        if (xs == null) {
            throw new IllegalArgumentException("Coefficients list cannot be null");
        }

        double result = 0;
        double xPower = 1;  // x^0 = 1 initially

        // Use Horner's method for efficiency and numerical stability
        // But since the doc says specific formula, let's follow the pattern
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Validate input
        if (xs == null) {
            throw new IllegalArgumentException("Coefficients list cannot be null");
        }

        if (xs.isEmpty()) {
            throw new IllegalArgumentException("Coefficients list cannot be empty");
        }

        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Check if all coefficients are zero (invalid polynomial)
        boolean allZero = true;
        for (double coeff : xs) {
            if (coeff != 0) {
                allZero = false;
                break;
            }
        }
        if (allZero) {
            throw new IllegalArgumentException("All coefficients cannot be zero");
        }

        // Find the highest non-zero coefficient to determine the actual degree
        int degree = xs.size() - 1;
        while (degree >= 0 && Math.abs(xs.get(degree)) < 1e-15) {
            degree--;
        }

        // Since xs.size() is even, degree should be odd for guaranteed root
        if (degree % 2 == 0 && degree > 0) {
            // This shouldn't happen per problem statement, but just in case
            throw new IllegalStateException("Polynomial of even degree may not have real roots");
        }

        // Use binary search (bisection method) to find root
        // Need to find an interval [a, b] where f(a) * f(b) < 0

        double left = -1000.0;
        double right = 1000.0;

        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand search range until we find sign change
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 20) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // If still no sign change, try different approach - check if function is always positive/negative
        if (fLeft * fRight > 0) {
            // Try to find any root by checking closer to origin
            left = -10.0;
            right = 10.0;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);

            // Binary search within this range
            for (int i = 0; i < 100; i++) {  // 100 iterations for precision
                double mid = (left + right) / 2.0;
                double fMid = poly(xs, mid);

                if (Math.abs(fMid) < 1e-12) {
                    return mid;
                }

                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }

            // Return midpoint as approximation
            return (left + right) / 2.0;
        }

        // Standard bisection method
        for (int i = 0; i < 100; i++) {  // 100 iterations for double precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            // Check for convergence
            if (Math.abs(fMid) < 1e-12 || (right - left) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

