     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        // Validate inputs according to standard exception conventions
        if (numbers == null) {
            throw new NullPointerException("List of numbers cannot be null");
        }
        if (threshold < 0) {
            throw new IllegalArgumentException("Threshold must be non-negative, got: " + threshold);
        }

        // If less than 2 elements, no pair exists
        if (numbers.size() < 2) {
            return false;
        }

        // Create a copy to avoid modifying the original list
        List<Double> sortedNumbers = new ArrayList<>(numbers);
        Collections.sort(sortedNumbers);

        // Check adjacent pairs for close proximity
        for (int i = 0; i < sortedNumbers.size() - 1; i++) {
            double diff = Math.abs(sortedNumbers.get(i + 1) - sortedNumbers.get(i));
            if (diff < threshold) {
                return true;
            }
        }

        return false;
    }
}

