        }

        // Split by spaces
        String[] groups = paren_string.split(" ");

        for (String group : groups) {
            int maxDepth = 0;
            int currentDepth = 0;

            for (char c : group.toCharArray()) {
                if (c == '(') {
                    currentDepth++;
                    maxDepth = Math.max(maxDepth, currentDepth);
                } else if (c == ')') {
                    currentDepth--;
                    // Validate that we don't have invalid parentheses (more closing than opening)
                    if (currentDepth < 0) {
                        // According to Item 72, IllegalArgumentException is appropriate here
                        // since the input string has invalid parentheses structure
                        throw new IllegalArgumentException("Invalid parentheses: unmatched closing parenthesis in group: " + group);
                    }
                }
            }

            // Validate that all parentheses are closed
            if (currentDepth != 0) {
                throw new IllegalArgumentException("Invalid parentheses: unmatched opening parenthesis in group: " + group);
            }

            result.add(maxDepth);
        }

        return result;
    }
}

