class Solution {
    public String makePalindrome(String string) {
        if (string == null) {
            throw new IllegalArgumentException("Input string cannot be null");
        }

        // Handle empty string case
        if (string.isEmpty()) {
            return "";
        }

        // Find the longest palindromic suffix
        for (int i = 0; i < string.length(); i++) {
            // Check if substring from index i to end is a palindrome
            if (isPalindrome(string.substring(i))) {
                // Found the longest palindromic suffix starting at index i
                String prefix = string.substring(0, i);
                String reversedPrefix = new StringBuilder(prefix).reverse().toString();
                return string + reversedPrefix;
            }
        }

        // This should never be reached since at least the last character is a palindrome
        return string;
    }
}

