class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Check for invalid input - numbers <= 1 have no proper divisors
        if (n <= 1) {
            throw new IllegalArgumentException("Input must be greater than 1");
        }

        // Start from n/2 and go downwards to find the largest proper divisor
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // This should never be reached since 1 always divides any n > 1
        throw new IllegalStateException("No proper divisor found for n = " + n);
    }
}

