class Solution {
    public double findZero(List<Double> xs) {
        // Validate input
        if (xs == null) {
            throw new NullPointerException("coefficients list cannot be null");
        }
        if (xs.isEmpty()) {
            throw new IllegalArgumentException("coefficients list cannot be empty");
        }
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("coefficients list must have even number of elements");
        }

        // Find the highest non-zero coefficient index
        int degree = xs.size() - 1;
        while (degree >= 0 && Math.abs(xs.get(degree)) < 1e-15) {
            degree--;
        }
        if (degree < 0) {
            throw new IllegalArgumentException("polynomial cannot be identically zero");
        }

        // For linear case (degree 1), solve directly
        if (degree == 1) {
            return -xs.get(0) / xs.get(1);
        }

        // Newton-Raphson method with multiple starting points
        double x = 0.0;
        double tolerance = 1e-12;
        int maxIterations = 1000;

        // Try multiple starting points
        double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

        for (double startX : startingPoints) {
            x = startX;
            for (int i = 0; i < maxIterations; i++) {
                double fx = poly(xs, x);

                // Check if we found a root
                if (Math.abs(fx) < tolerance) {
                    return x;
                }

                // Calculate derivative
                double fpx = polyDerivative(xs, x);

                // Avoid division by zero
                if (Math.abs(fpx) < 1e-15) {
                    break;
                }

                double newX = x - fx / fpx;

                // Check for convergence or overflow
                if (Double.isNaN(newX) || Double.isInfinite(newX) || 
                    Math.abs(newX - x) < tolerance) {
                    if (Math.abs(poly(xs, newX)) < tolerance) {
                        return newX;
                    }
                    break;
                }

                x = newX;
            }

            // Check if current x is a solution
            if (Math.abs(poly(xs, x)) < tolerance) {
                return x;
            }
        }

        // Bisection fallback for guaranteed root (since problem states solution exists)
        // Find interval [a, b] where sign changes
        double a = -100.0;
        double b = 100.0;
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Expand search interval if needed
        int expandCount = 0;
        while (fa * fb > 0 && expandCount < 10) {
            a *= 10;
            b *= 10;
            fa = poly(xs, a);
            fb = poly(xs, b);
            expandCount++;
        }

        // If still same sign, try to find sign change with smaller steps
        if (fa * fb > 0) {
            for (double testA = -100; testA <= 100; testA += 1) {
                for (double testB = testA + 1; testB <= 100; testB += 1) {
                    double fTestA = poly(xs, testA);
                    double fTestB = poly(xs, testB);
                    if (fTestA * fTestB <= 0) {
                        a = testA;
                        b = testB;
                        fa = fTestA;
                        fb = fTestB;
                        break;
                    }
                }
                if (fa * fb <= 0) break;
            }
        }

        // Bisection method
        if (fa * fb <= 0) {
            for (int i = 0; i < 100; i++) {
                double mid = (a + b) / 2;
                double fmid = poly(xs, mid);

                if (Math.abs(fmid) < tolerance || (b - a) / 2 < tolerance) {
                    return mid;
                }

                if (fa * fmid <= 0) {
                    b = mid;
                    fb = fmid;
                } else {
                    a = mid;
                    fa = fmid;
                }
            }
            return (a + b) / 2;
        }

        // Last resort: return the best approximation found
        double bestX = 0.0;
        double bestResidual = Math.abs(poly(xs, 0.0));

        for (double testX = -10; testX <= 10; testX += 0.5) {
            double residual = Math.abs(poly(xs, testX));
            if (residual < bestResidual) {
                bestResidual = residual;
                bestX = testX;
            }
        }

        return bestX;
    }

    // Helper method to compute derivative
    private double polyDerivative(List<Double> xs, double x) {
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

