class Solution {
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge case: constant polynomial (degree 0) - but problem states even number of coefficients
        // and for linear case (2 coefficients), we can solve directly

        // Check if we have a linear polynomial (2 coefficients)
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (b != 0) {
                return -a / b;
            }
        }

        // For higher degree polynomials, use bisection method
        // Since polynomial has odd degree (even number of coefficients), it must have a real root

        double left = -1000.0;
        double right = 1000.0;

        // Expand the search interval until we find a sign change
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If no sign change, expand interval
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 30) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // If still no sign change, try different approach - use Newton's method with initial guess 0
        if (fLeft * fRight > 0) {
            // Fallback: Newton's method starting from 0
            return newtonMethod(xs, 0.0);
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // enough iterations for double precision
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }

    private double newtonMethod(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 50; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }
            // Compute derivative
            double dfx = 0;
            for (int j = 1; j < xs.size(); j++) {
                dfx += xs.get(j) * j * Math.pow(x, j - 1);
            }
            if (Math.abs(dfx) < 1e-12) {
                // Derivative too small, perturb x slightly
                x += 0.1;
                continue;
            }
            double xNew = x - fx / dfx;
            if (Double.isNaN(xNew) || Double.isInfinite(xNew)) {
                x += 0.1;
                continue;
            }
            if (Math.abs(xNew - x) < 1e-12) {
                return xNew;
            }
            x = xNew;
        }
        return x;
    }
}

