class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("Input must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special case: Fibonacci sequence starts with 0, 1, 1, 2, 3, ...
        // We need to check each Fibonacci number

        // Check F(0) = 0 - not prime
        // Check F(1) = 1 - not prime
        // Check F(2) = 1 - not prime
        // Check F(3) = 2 - prime

        // Start generating from F(2) onwards, but we need to check all
        if (n == 1) {
            return 2;
        }

        // We'll generate Fibonacci numbers and check for primality
        long fib = 0;
        int index = 0;

        while (true) {
            fib = fibonacci(index);

            if (fib > 1 && isPrime(fib)) {
                count++;
                if (count == n) {
                    return (int) fib;
                }
            }

            index++;

            // Safety check to prevent infinite loops for large inputs
            if (index > 1000 && count < n) {
                throw new RuntimeException("Could not find " + n + "-th Fibonacci prime");
            }
        }
    }

    private long fibonacci(int n) {
        if (n <= 0) return 0;
        if (n == 1) return 1;

        long a = 0, b = 1;
        for (int i = 2; i <= n; i++) {
            long temp = a + b;
            a = b;
            b = temp;
        }
        return b;
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;

        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

