        // Handle edge cases: numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Use Newton's method with several starting points to find a root
        // Try multiple initial guesses to increase chances of finding a root
        double[] initialGuesses = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

        for (double x0 : initialGuesses) {
            double result = newtonMethod(xs, x0);
            if (Math.abs(poly(xs, result)) < 1e-9) {
                return result;
            }
        }

        // Fallback: try bisection method over a large range
        // Since odd-degree polynomial must cross zero somewhere
        double left = -1000.0;
        double right = 1000.0;

        // Make sure we have opposite signs at endpoints
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If same sign, expand the range
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 20) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint as last resort
        return (left + right) / 2;
    }

    private double newtonMethod(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 50; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative
            double fPrime = 0;
            for (int j = 1; j < xs.size(); j++) {
                fPrime += j * xs.get(j) * Math.pow(x, j - 1);
            }

            // Avoid division by zero
            if (Math.abs(fPrime) < 1e-12) {
                // Slight perturbation
                x += 0.001;
                continue;
            }

            double xNew = x - fx / fPrime;

            // Check for divergence
            if (Double.isNaN(xNew) || Double.isInfinite(xNew) || Math.abs(xNew - x) > 1e6) {
                return x0; // Give up and return original guess
            }

            x = xNew;
        }
        return x;
    }
}

