class Solution {
    /**
     * Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
     * separate those groups into separate strings and return the list of those.
     * Separate groups are balanced (each open brace is properly closed) and not nested within each other
     * Ignore any spaces in the input string.
     * 
     * @param paren_string the input string containing parenthesis groups
     * @return list of balanced parenthesis groups
     * @throws IllegalArgumentException if input contains unbalanced parentheses
     */
    public List<String> separateParenGroups(String paren_string) {
        if (paren_string == null) {
            return new ArrayList<>();
        }

        List<String> result = new ArrayList<>();
        StringBuilder currentGroup = new StringBuilder();
        int openCount = 0;

        for (char c : paren_string.toCharArray()) {
            if (c == ' ') {
                continue;
            }

            if (c == '(') {
                openCount++;
                currentGroup.append(c);
            } else if (c == ')') {
                if (openCount > 0) {
                    openCount--;
                    currentGroup.append(c);
                    // When openCount reaches 0, we have a complete balanced group
                    if (openCount == 0) {
                        result.add(currentGroup.toString());
                        currentGroup.setLength(0);
                    }
                } else {
                    // Unbalanced parentheses - extra closing bracket
                    throw new IllegalArgumentException("Unbalanced parentheses in input");
                }
            } else {
                // Ignore any non-parenthesis characters
                continue;
            }
        }

        // Check for unbalanced parentheses - extra opening brackets
        if (openCount != 0) {
            throw new IllegalArgumentException("Unbalanced parentheses in input");
        }

        return result;
    }
}

