class Solution {
    /**
     * Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
     * For each of the group, output the deepest level of nesting of parentheses.
     * E.g. (()()) has maximum two levels of nesting while ((())) has three.
     *
     * @param paren_string string containing groups of parentheses separated by spaces
     * @return list of integers representing the maximum nesting depth for each group
     * @throws NullPointerException if paren_string is null
     * @throws IllegalArgumentException if paren_string contains invalid characters (not parentheses or spaces)
     */
    public List<Integer> parseNestedParens(String paren_string) {
        // Validate input
        if (paren_string == null) {
            throw new NullPointerException("Input string cannot be null");
        }

        List<Integer> result = new ArrayList<>();

        // Handle empty string case
        if (paren_string.trim().isEmpty()) {
            return result;
        }

        // Split by spaces to get individual groups
        String[] groups = paren_string.split("\\s+");

        for (String group : groups) {
            int maxDepth = 0;
            int currentDepth = 0;

            for (int i = 0; i < group.length(); i++) {
                char c = group.charAt(i);

                // Validate character
                if (c != '(' && c != ')') {
                    throw new IllegalArgumentException(
                        "Invalid character '" + c + "' found in group '" + group + "'. Only parentheses allowed."
                    );
                }

                if (c == '(') {
                    currentDepth++;
                    maxDepth = Math.max(maxDepth, currentDepth);
                } else if (c == ')') {
                    currentDepth--;
                }
            }

            result.add(maxDepth);
        }

        return result;
    }
}

