class Solution {
    /**
    For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sumProduct(List.of())
    [0, 1]
    >>> sumProduct(Arrays.asList(1, 2, 3, 4))
    [10, 24]

    @param numbers the list of integers to process (must not be null)
    @return a list containing two elements: [sum, product]
    @throws NullPointerException if the input list is null
    */
    public List<Integer> sumProduct(List<Integer> numbers) {
        if (numbers == null) {
            throw new NullPointerException("Input list must not be null");
        }

        int sum = 0;
        int product = 1;

        for (Integer num : numbers) {
            if (num == null) {
                throw new NullPointerException("List elements must not be null");
            }
            sum += num;
            // Check for potential overflow before multiplication
            if (product != 0 && num != 0 && 
                (product > Integer.MAX_VALUE / num || product < Integer.MIN_VALUE / num)) {
                throw new ArithmeticException("Integer overflow in product calculation");
            }
            product *= num;
        }

        return Arrays.asList(sum, product);
    }
}

