class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"

    @param a first binary string
    @param b second binary string
    @return the binary XOR result as a string
    @throws IllegalArgumentException if either string contains characters other than '0' or '1'
    @throws IllegalArgumentException if the input strings have different lengths
    @throws NullPointerException if either input string is null
    */
    public String stringXor(String a, String b) {
        // Validate inputs are not null
        if (a == null || b == null) {
            throw new NullPointerException("Input strings cannot be null");
        }

        // Validate strings have same length
        if (a.length() != b.length()) {
            throw new IllegalArgumentException("Input strings must have the same length");
        }

        // Validate that both strings contain only '0' and '1'
        for (int i = 0; i < a.length(); i++) {
            char ca = a.charAt(i);
            char cb = b.charAt(i);

            if ((ca != '0' && ca != '1') || (cb != '0' && cb != '1')) {
                throw new IllegalArgumentException("Input strings must contain only '0' and '1' characters");
            }
        }

        StringBuilder result = new StringBuilder(a.length());

        // Perform XOR operation character by character
        for (int i = 0; i < a.length(); i++) {
            char ca = a.charAt(i);
            char cb = b.charAt(i);

            // XOR: same bits give 0, different bits give 1
            if (ca == cb) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

