class Solution {
    /**
    Out of list of strings, return the longest one. Return the first one in case of multiple
    strings of the same length. Return None in case the input list is empty.
    >>> longest(List.of())
    Optional.empty
    >>> longest(Arrays.asList("a", "b", "c"))
    Optional[a]
    >>> longest(Arrays.asList("a", "bb", "ccc"))
    Optional[ccc]
     *
     * @param strings the list of strings to search
     * @return an Optional containing the longest string, or empty if the list is empty
     * @throws NullPointerException if the input list is null, or if any element in the list is null
     */
    public Optional<String> longest(List<String> strings) {
        if (strings == null) {
            throw new NullPointerException("Input list cannot be null");
        }

        if (strings.isEmpty()) {
            return Optional.empty();
        }

        String longest = strings.get(0);
        if (longest == null) {
            throw new NullPointerException("List contains null element");
        }

        for (int i = 1; i < strings.size(); i++) {
            String current = strings.get(i);
            if (current == null) {
                throw new NullPointerException("List contains null element");
            }

            if (current.length() > longest.length()) {
                longest = current;
            }
        }

        return Optional.of(longest);
    }
}

