class Solution {
    /**
    Return a greatest common divisor of two integers a and b
    >>> greatestCommonDivisor(3, 5)
    1
    >>> greatestCommonDivisor(25, 15)
    5
     * @param a first integer
     * @param b second integer
     * @return the greatest common divisor of a and b
     * @throws IllegalArgumentException if both a and b are zero
     */
    public int greatestCommonDivisor(int a, int b) {
        // Handle negative numbers by taking absolute values
        a = Math.abs(a);
        b = Math.abs(b);

        // GCD is undefined when both numbers are 0
        if (a == 0 && b == 0) {
            throw new IllegalArgumentException("GCD is undefined for both arguments being zero");
        }

        // Euclidean algorithm
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }

        return a;
    }
}

