class Solution {
    private static final Map<String, Integer> NUMBER_MAP = new HashMap<>();

    static {
        NUMBER_MAP.put("zero", 0);
        NUMBER_MAP.put("one", 1);
        NUMBER_MAP.put("two", 2);
        NUMBER_MAP.put("three", 3);
        NUMBER_MAP.put("four", 4);
        NUMBER_MAP.put("five", 5);
        NUMBER_MAP.put("six", 6);
        NUMBER_MAP.put("seven", 7);
        NUMBER_MAP.put("eight", 8);
        NUMBER_MAP.put("nine", 9);
    }

    /**
     * Input is a space-delimited string of numberals from 'zero' to 'nine'.
     * Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
     * Return the string with numbers sorted from smallest to largest.
     *
     * @param numbers space-delimited string of number words
     * @return sorted string of number words
     * @throws IllegalArgumentException if input contains invalid number words or is malformed
     */
    public String sortNumbers(String numbers) {
        // Handle null input
        if (numbers == null) {
            throw new IllegalArgumentException("Input cannot be null");
        }

        // Trim and check for empty string
        String trimmed = numbers.trim();
        if (trimmed.isEmpty()) {
            return "";
        }

        // Split by spaces and collect tokens
        String[] tokens = trimmed.split("\\s+");
        List<String> validWords = new ArrayList<>();

        for (String token : tokens) {
            if (!NUMBER_MAP.containsKey(token)) {
                throw new IllegalArgumentException("Invalid number word: '" + token + "'");
            }
            validWords.add(token);
        }

        // Sort by numeric value using the map
        validWords.sort((a, b) -> NUMBER_MAP.get(a) - NUMBER_MAP.get(b));

        // Join back into space-separated string
        return String.join(" ", validWords);
    }
}

