class Solution {
    /**
     * Given list of numbers (of at least two elements), apply a linear transform to that list,
     * such that the smallest number will become 0 and the largest will become 1.
     *
     * @param numbers the list of numbers to rescale
     * @return a new list with rescaled values in the range [0, 1]
     * @throws NullPointerException if the input list is null
     * @throws IllegalArgumentException if the list has fewer than two elements
     * @throws ArithmeticException if all numbers in the list are equal (max equals min)
     */
    public List<Double> rescaleToUnit(List<Double> numbers) {
        // Check for null input
        if (numbers == null) {
            throw new NullPointerException("Input list cannot be null");
        }

        // Check if list has at least two elements
        if (numbers.size() < 2) {
            throw new IllegalArgumentException("List must contain at least two elements");
        }

        // Find min and max values
        double min = Double.MAX_VALUE;
        double max = Double.MIN_VALUE;

        for (Double num : numbers) {
            if (num == null) {
                throw new NullPointerException("List contains null elements");
            }
            min = Math.min(min, num);
            max = Math.max(max, num);
        }

        // Check if all values are the same (would cause division by zero)
        if (max == min) {
            throw new ArithmeticException("Cannot rescale: all values are equal (max equals min)");
        }

        // Create result list with the same size
        List<Double> result = new ArrayList<>(numbers.size());

        // Apply the rescaling formula: (value - min) / (max - min)
        double range = max - min;
        for (Double num : numbers) {
            result.add((num - min) / range);
        }

        return result;
    }
}

