class Solution {
    /**
     * For a given number n, find the largest number that divides n evenly, smaller than n.
     * 
     * @param n the number to find the largest proper divisor for
     * @return the largest divisor of n that is smaller than n
     * @throws IllegalArgumentException if n is less than or equal to 1, as no such divisor exists
     */
    public int largestDivisor(int n) {
        if (n <= 1) {
            throw new IllegalArgumentException("Input must be greater than 1");
        }

        // Start checking from n/2 downwards - the largest possible proper divisor is n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // This should never be reached since 1 always divides any n > 1
        return 1;
    }
}

