    * >>> removeDuplicates(Array.asList(1, 2, 3, 2, 4))
    * [1, 3, 4]
    * 
    * @param numbers the input list of integers (may be null or empty)
    * @return a new list containing only elements that appear exactly once in the input, in original order
    * @throws NullPointerException if the input list is null
    */
    public List<Integer> removeDuplicates(List<Integer> numbers) {
        Objects.requireNonNull(numbers, "Input list cannot be null");

        // Count occurrences of each number
        Map<Integer, Long> counts = numbers.stream()
            .collect(Collectors.groupingBy(n -> n, Collectors.counting()));

        // Filter to keep only elements that appear exactly once, preserving order
        return numbers.stream()
            .filter(n -> counts.get(n) == 1)
            .collect(Collectors.toList());
    }
}

