class Solution {
    public double findZero(List<Double> xs) {
            // Validate input: must have even number of coefficients
            if (xs == null || xs.size() % 2 != 0) {
                throw new IllegalArgumentException("List must have even number of coefficients");
            }

            // Newton-Raphson method
            double x = 1.0; // initial guess

            // Perform up to 100 iterations
            for (int i = 0; i < 100; i++) {
                double fx = poly(xs, x);

                // If we're close enough to zero, return
                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                // Compute derivative: f'(x)
                double fpx = 0;
                for (int j = 1; j < xs.size(); j++) {
                    fpx += j * xs.get(j) * Math.pow(x, j - 1);
                }

                // Avoid division by zero
                if (Math.abs(fpx) < 1e-15) {
                    // Perturb x slightly and try again
                    x += 0.1;
                    continue;
                }

                // Newton step
                x = x - fx / fpx;

                // Check for divergence (in case of numerical issues)
                if (Double.isNaN(x) || Double.isInfinite(x)) {
                    // Try bisection fallback with a reasonable range
                    double left = -10.0;
                    double right = 10.0;
                    while (right - left > 1e-10) {
                        double mid = (left + right) / 2;
                        double fmid = poly(xs, mid);
                        if (Math.abs(fmid) < 1e-10) {
                            return mid;
                        }
                        double fleft = poly(xs, left);
                        if (fleft * fmid < 0) {
                            right = mid;
                        } else {
                            left = mid;
                        }
                    }
                    return (left + right) / 2;
                }
            }

            // Fallback: return the last approximation
            return x;
        }
}

