    3
     */
    public int fizzBuzz(int n) {
        if (n <= 0) {
            return 0;
        }

        int count = 0;

        for (int i = 1; i < n; i++) {
            if (i % 11 == 0 || i % 13 == 0) {
                // Count occurrences of '7' in the number
                String numStr = String.valueOf(i);
                for (int j = 0; j < numStr.length(); j++) {
                    if (numStr.charAt(j) == '7') {
                        count++;
                    }
                }
            }
        }

        return count;
    }
}

