            throw new NullPointerException("Input list cannot be null");
        }

        // Create a copy of the original list
        List<Integer> result = new ArrayList<>(l);

        // Collect values at even indices
        List<Integer> evenValues = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 2) {
            evenValues.add(l.get(i));
        }

        // Sort the collected even-indexed values
        Collections.sort(evenValues);

        // Place sorted values back at even indices
        int evenIndex = 0;
        for (int i = 0; i < result.size(); i += 2) {
            result.set(i, evenValues.get(evenIndex++));
        }

        return result;
    }
}

