class Solution {
    /**
     * primeFib returns n-th number that is a Fibonacci number and it's also prime.
     * 
     * >>> primeFib(1)
     * 2
     * >>> primeFib(2)
     * 3
     * >>> primeFib(3)
     * 5
     * >>> primeFib(4)
     * 13
     * >>> primeFib(5)
     * 89
     *
     * @param n the position of the Fibonacci prime to return (must be positive)
     * @return the n-th number that is both a Fibonacci number and a prime number
     * @throws IllegalArgumentException if n is less than or equal to 0
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Handle special case for small n
        if (n == 1) return 2;
        if (n == 2) return 3;

        int count = 2; // We already have 2 and 3

        // Start generating Fibonacci numbers from F(4) = 3, but we need to continue
        long a = 2; // F(3)
        long b = 3; // F(4)

        while (count < n) {
            long c = a + b;
            a = b;
            b = c;

            if (isPrime((int)c)) {
                count++;
                if (count == n) {
                    return (int)c;
                }
            }
        }

        // Should not reach here for valid inputs based on examples
        throw new ArithmeticException("Failed to find the " + n + "-th Fibonacci prime");
    }

    /**
     * Checks if a number is prime.
     * 
     * @param num the number to check
     * @return true if the number is prime, false otherwise
     */
    private boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        if (num <= 3) {
            return true;
        }
        if (num % 2 == 0 || num % 3 == 0) {
            return false;
        }

        for (int i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

