    >>> hasCloseElements(Arrays.asList(1.0, 2.0, 3.0), 0.5)
    false
    >>> hasCloseElements(Arrays.asList(1.0, 2.8, 3.0, 4.0, 5.0, 2.0), 0.3)
    true

    @param numbers the list of numbers to check
    @param threshold the minimum distance threshold
    @return true if any two numbers are closer than threshold, false otherwise
    @throws NullPointerException if the input list is null, or if any element in the list is null
     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        // Check for null list
        if (numbers == null) {
            throw new NullPointerException("Input list cannot be null");
        }

        // Handle edge cases: empty list or single element
        if (numbers.size() <= 1) {
            return false;
        }

        // Create a sorted copy to avoid modifying the original list
        List<Double> sortedNumbers = new ArrayList<>(numbers);
        Collections.sort(sortedNumbers);

        // Check adjacent pairs
        for (int i = 0; i < sortedNumbers.size() - 1; i++) {
            // This will throw NullPointerException if any element is null
            double diff = Math.abs(sortedNumbers.get(i) - sortedNumbers.get(i + 1));
            if (diff < threshold) {
                return true;
            }
        }

        return false;
    }
}

