class Solution {
    /**
     * Given a positive floating point number, it can be decomposed into
     * an integer part (largest integer smaller than given number) and decimals
     * (leftover part always smaller than 1).
     *
     * Return the decimal part of the number.
     *
     * @param number a positive floating point number
     * @return the decimal (fractional) part of the number, which is always in the range [0, 1)
     * @throws IllegalArgumentException if number is negative
     * @throws ArithmeticException if number is NaN or infinite
     */
    public double truncateNumber(double number) {
        // Check for invalid inputs as per ITEM 74 - document exceptions
        if (Double.isNaN(number)) {
            throw new IllegalArgumentException("Input cannot be NaN");
        }
        if (Double.isInfinite(number)) {
            throw new IllegalArgumentException("Input cannot be infinite");
        }
        if (number < 0) {
            throw new IllegalArgumentException("Input must be non-negative");
        }

        // Get the integer part (floor for positive numbers)
        double integerPart = Math.floor(number);

        // Return the decimal part
        return number - integerPart;
    }
}

