class Solution {
    /**
     * Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
     * For each of the groups, output the deepest level of nesting of parentheses.
     * E.g. (()()) has maximum two levels of nesting while ((())) has three.
     *
     * @param paren_string string containing space-separated groups of parentheses
     * @return list of integers representing the maximum nesting depth for each group
     * @throws IllegalArgumentException if the input string contains invalid characters
     * @throws NullPointerException if the input string is null
     */
    public List<Integer> parseNestedParens(String paren_string) {
        if (paren_string == null) {
            throw new NullPointerException("Input string cannot be null");
        }

        List<Integer> result = new ArrayList<>();

        // Split by whitespace to get individual groups
        String[] groups = paren_string.trim().split("\\s+");

        for (String group : groups) {
            int maxDepth = 0;
            int currentDepth = 0;

            for (int i = 0; i < group.length(); i++) {
                char c = group.charAt(i);

                if (c == '(') {
                    currentDepth++;
                    maxDepth = Math.max(maxDepth, currentDepth);
                } else if (c == ')') {
                    currentDepth--;
                    // Optional: validate that depth never goes negative
                    if (currentDepth < 0) {
                        throw new IllegalArgumentException("Invalid parentheses: unbalanced closing parenthesis in group: " + group);
                    }
                } else {
                    throw new IllegalArgumentException("Invalid character '" + c + "' found in group: " + group);
                }
            }

            // Optional: validate that final depth is zero (balanced)
            if (currentDepth != 0) {
                throw new IllegalArgumentException("Unbalanced parentheses in group: " + group);
            }

            result.add(maxDepth);
        }

        return result;
    }
}

