class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"

    @param a the first binary string
    @param b the second binary string
    @return the binary string representing the XOR of a and b
    @throws IllegalArgumentException if the input strings have different lengths
    @throws NullPointerException if either a or b is null
    */
    public String stringXor(String a, String b) {
        // Check for null inputs
        if (a == null || b == null) {
            throw new NullPointerException("Input strings cannot be null");
        }

        // Check if lengths are equal
        if (a.length() != b.length()) {
            throw new IllegalArgumentException("Input strings must have the same length");
        }

        StringBuilder result = new StringBuilder(a.length());

        // Perform XOR character by character
        for (int i = 0; i < a.length(); i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            // Validate that characters are only '0' or '1'
            if ((bitA != '0' && bitA != '1') || (bitB != '0' && bitB != '1')) {
                throw new IllegalArgumentException("Input strings must contain only '0' and '1' characters");
            }

            // XOR operation: same bits give 0, different bits give 1
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

