            if (token.equals("o")) {
                result.add(4);
            } else if (token.equals("o|")) {
                result.add(2);
            } else if (token.equals(".|")) {
                result.add(1);
            }
            // Note: Invalid tokens are ignored per the problem context
        }

        return result;
    }
}

import java.util.*;
