class Solution {
    /**
     * Input is a space-delimited string of numberals from 'zero' to 'nine'.
     * Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
     * Return the string with numbers sorted from smallest to largest.
     * 
     * @param numbers a space-delimited string of number words
     * @return a space-delimited string of the same number words sorted numerically
     * @throws IllegalArgumentException if any word is not a valid number from 'zero' to 'nine'
     * @throws NullPointerException if the input string is null
     */
    public String sortNumbers(String numbers) {
        // Documented NullPointerException: if numbers is null
        if (numbers == null) {
            throw new NullPointerException("Input string cannot be null");
        }

        // Handle empty string case
        if (numbers.trim().isEmpty()) {
            return "";
        }

        // Split the input string by spaces
        String[] words = numbers.trim().split("\\s+");

        // Create a mapping from word to numeric value
        Map<String, Integer> wordToNumber = new HashMap<>();
        wordToNumber.put("zero", 0);
        wordToNumber.put("one", 1);
        wordToNumber.put("two", 2);
        wordToNumber.put("three", 3);
        wordToNumber.put("four", 4);
        wordToNumber.put("five", 5);
        wordToNumber.put("six", 6);
        wordToNumber.put("seven", 7);
        wordToNumber.put("eight", 8);
        wordToNumber.put("nine", 9);

        // Validate all words and collect them for sorting
        List<String> validWords = new ArrayList<>();
        for (String word : words) {
            if (!wordToNumber.containsKey(word)) {
                // Documented IllegalArgumentException for invalid input
                throw new IllegalArgumentException("Invalid number word: '" + word + "'. Valid words are: zero, one, two, three, four, five, six, seven, eight, nine.");
            }
            validWords.add(word);
        }

        // Sort the words based on their numeric values
        Collections.sort(validWords, (a, b) -> {
            return wordToNumber.get(a) - wordToNumber.get(b);
        });

        // Join the sorted words back into a space-delimited string
        return String.join(" ", validWords);
    }
}

