class Solution {
    /**
     * Given list of numbers (of at least two elements), apply a linear transform to that list,
     * such that the smallest number will become 0 and the largest will become 1.
     *
     * @param numbers the list of numbers to rescale
     * @return a new list with rescaled values between 0.0 and 1.0
     * @throws IllegalArgumentException if the input list has fewer than 2 elements
     * @throws NullPointerException if the input list is null
     * @throws NoSuchElementException if the input list is empty
     */
    public List<Double> rescaleToUnit(List<Double> numbers) {
        // Check for null input
        if (numbers == null) {
            throw new NullPointerException("Input list cannot be null");
        }

        // Check if list has at least 2 elements
        if (numbers.size() < 2) {
            throw new IllegalArgumentException("List must contain at least two elements");
        }

        // Find minimum and maximum values
        double min = Double.MAX_VALUE;
        double max = Double.MIN_VALUE;

        for (Double num : numbers) {
            // Check for null elements in the list
            if (num == null) {
                throw new NullPointerException("List contains null element");
            }

            if (num < min) {
                min = num;
            }
            if (num > max) {
                max = num;
            }
        }

        // Handle case where all elements are the same (min == max)
        // In this case, all values should map to 0.0 (or 1.0, but 0.0 is more consistent)
        if (min == max) {
            List<Double> result = new ArrayList<>();
            for (int i = 0; i < numbers.size(); i++) {
                result.add(0.0);
            }
            return result;
        }

        // Apply linear transformation: (x - min) / (max - min)
        List<Double> result = new ArrayList<>(numbers.size());
        double range = max - min;

        for (Double num : numbers) {
            result.add((num - min) / range);
        }

        return result;
    }
}

