class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
    */
    public int largestDivisor(int n) {
        // Handle edge case: n must be greater than 1 to have a proper divisor
        if (n <= 1) {
            return -1; // or throw IllegalArgumentException
        }

        // Start from n/2 and go down, since the largest proper divisor is at most n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // For n > 1, we should always find at least 1 as a divisor
        return 1;
    }
}

