    @param n the number to check for primality
    @return true if n is prime, false otherwise
    @throws IllegalArgumentException if n is less than 2 (though this implementation returns false instead)
    */
    public boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

