import java.lang.*;

class Solution {
    /**
     * Evaluates polynomial with coefficients xs at point x.
     * return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     *
     * @param xs coefficients of the polynomial
     * @param x point at which to evaluate
     * @return polynomial value at x
     * @throws IllegalArgumentException if xs is null or empty
     * @throws NullPointerException if xs is null or contains null elements
     */
    public double poly(List<Double> xs, double x) {
        if (xs == null) {
            throw new NullPointerException("Coefficients list cannot be null");
        }
        if (xs.isEmpty()) {
            throw new IllegalArgumentException("Coefficients list cannot be empty");
        }

        double result = 0;
        double xPower = 1.0;
        for (int i = 0; i < xs.size(); i++) {
            Double coef = xs.get(i);
            if (coef == null) {
                throw new NullPointerException("Coefficient at index " + i + " cannot be null");
            }
            result += coef * xPower;
            xPower *= x;
        }
        return result;
    }

    /**
     * xs are coefficients of a polynomial.
     * findZero finds x such that poly(x) = 0.
     * findZero returns only one zero point, even if there are many.
     * Moreover, findZero only takes list xs having even number of coefficients
     * and largest non zero coefficient as it guarantees a solution.
     * 
     * >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
     * -0.5
     * >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
     * 1.0
     *
     * @param xs coefficients of the polynomial (must have even size)
     * @return a root of the polynomial
     * @throws IllegalArgumentException if xs has odd number of coefficients or is empty/null
     * @throws NullPointerException if xs is null or contains null elements
     * @throws IllegalStateException if no root can be found (should not happen per problem guarantee)
     */
    public double findZero(List<Double> xs) {
        if (xs == null) {
            throw new NullPointerException("Coefficients list cannot be null");
        }
        if (xs.size() % 2 != 0 || xs.isEmpty()) {
            throw new IllegalArgumentException("Coefficients list must have even number of coefficients");
        }

        // Check for null elements
        for (int i = 0; i < xs.size(); i++) {
            if (xs.get(i) == null) {
                throw new NullPointerException("Coefficient at index " + i + " cannot be null");
            }
        }

        int n = xs.size();

        // Handle linear case (degree 1)
        if (n == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (b == 0) {
                throw new IllegalStateException("Linear coefficient cannot be zero for linear equation");
            }
            return -a / b;
        }

        // For higher degree polynomials, use Newton-Raphson method
        double x = 0.0; // initial guess

        // Try multiple starting points if needed
        double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 0.5, -0.5, 10.0, -10.0};

        for (double startX : startingPoints) {
            x = startX;
            for (int iteration = 0; iteration < 100; iteration++) {
                // Calculate f(x) and f'(x)
                double fx = poly(xs, x);

                // If close enough to zero, return
                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                // Calculate derivative using numerical differentiation or analytical
                double derivative = polyDerivative(xs, x);

                // Skip if derivative is too small to avoid division by zero
                if (Math.abs(derivative) < 1e-15) {
                    continue;
                }

                double newX = x - fx / derivative;

                // Check for convergence
                if (Math.abs(newX - x) < 1e-12) {
                    return x;
                }

                x = newX;
            }
        }

        // Fallback: try bisection on an interval if Newton fails
        // Since problem guarantees a solution exists, try broader search
        for (double left = -100.0; left <= 100.0; left += 1.0) {
            double right = left + 1.0;
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            if (fLeft * fRight <= 0) {
                // Bisection method
                for (int i = 0; i < 50; i++) {
                    double mid = (left + right) / 2.0;
                    double fMid = poly(xs, mid);

                    if (Math.abs(fMid) < 1e-10) {
                        return mid;
                    }

                    if (fLeft * fMid <= 0) {
                        right = mid;
                    } else {
                        left = mid;
                        fLeft = fMid;
                    }
                }
                return (left + right) / 2.0;
            }
        }

        // Last resort: return the best approximation found
        x = 0.0;
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-8) {
                return x;
            }
            double derivative = polyDerivative(xs, x);
            if (Math.abs(derivative) < 1e-15) {
                break;
            }
            x -= fx / derivative;
        }

        return x;
    }

    /**
     * Evaluates the derivative of the polynomial at point x.
     * 
     * @param xs coefficients of the polynomial
     * @param x point at which to evaluate derivative
     * @return derivative value at x
     * @throws NullPointerException if xs is null or contains null elements
     */
    private double polyDerivative(List<Double> xs, double x) {
        if (xs.size() <= 1) {
            return 0.0;
        }

        double result = 0;
        double xPower = 1.0;
        for (int i = 1; i < xs.size(); i++) {
            Double coef = xs.get(i);
            if (coef == null) {
                throw new NullPointerException("Coefficient at index " + i + " cannot be null");
            }
            result += i * coef * xPower;
            xPower *= x;
        }
        return result;
    }
}

