class Solution {
    /**
     * This function takes a list l and returns a list l' such that
     * l' is identical to l in the indices that are not divisible by three, while its values at the indices that are divisible by three are equal
     * to the values of the corresponding indices of l, but sorted.
     * 
     * @param l the input list of integers
     * @return a new list where elements at indices divisible by 3 are sorted, others remain unchanged
     * @throws IllegalArgumentException if l is null
     * @throws NullPointerException if l contains null elements
     */
    public List<Integer> sortThird(List<Integer> l) {
        if (l == null) {
            throw new IllegalArgumentException("Input list cannot be null");
        }

        // Create a copy of the input list
        List<Integer> result = new ArrayList<>(l);

        // Collect indices that are divisible by 3 (0, 3, 6, ...)
        List<Integer> divisibleIndices = new ArrayList<>();
        for (int i = 0; i < result.size(); i += 3) {
            divisibleIndices.add(i);
        }

        // Extract values at those indices
        List<Integer> valuesToSort = new ArrayList<>();
        for (int index : divisibleIndices) {
            Integer value = result.get(index);
            if (value == null) {
                throw new NullPointerException("List contains null element at index " + index);
            }
            valuesToSort.add(value);
        }

        // Sort the extracted values
        Collections.sort(valuesToSort);

        // Put the sorted values back at the divisible-by-3 indices
        Iterator<Integer> valueIterator = valuesToSort.iterator();
        for (int index : divisibleIndices) {
            result.set(index, valueIterator.next());
        }

        return result;
    }
}

