class Solution {
    /**
     * Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13.
     * <p>
     * This method throws no exceptions under normal operation.
     *
     * @param n the upper bound (exclusive) for checking numbers
     * @return the count of digit 7 appearances in qualifying numbers
     * @throws IllegalArgumentException if n is negative
     * @throws NullPointerException if n is null (impossible since n is primitive int)
     */
    public int fizzBuzz(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }

        int count = 0;
        for (int i = 1; i < n; i++) {
            if (i % 11 == 0 || i % 13 == 0) {
                String numStr = String.valueOf(i);
                for (int j = 0; j < numStr.length(); j++) {
                    if (numStr.charAt(j) == '7') {
                        count++;
                    }
                }
            }
        }
        return count;
