class Solution {
    /**
     * primeFib returns n-th number that is a Fibonacci number and it's also prime.
     * 
     * @param n the position of the Fibonacci prime to find (must be positive)
     * @return the n-th Fibonacci prime number
     * @throws IllegalArgumentException if n is less than 1
     * @throws ArithmeticException if the computation overflows integer range
     */
    public int primeFib(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("n must be positive, got: " + n);
        }

        int count = 0;
        int a = 0; // F(0)
        int b = 1; // F(1)

        // Handle special case: check 2 separately since it's the only even prime Fibonacci
        if (n == 1) return 2;

        // Start generating Fibonacci numbers from F(3) = 2
        while (true) {
            int next = a + b;

            // Check for overflow
            if (next < 0) {
                throw new ArithmeticException("Integer overflow during Fibonacci calculation");
            }

            // Check if current Fibonacci number is prime and count it
            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }

            a = b;
            b = next;
        }
    }

    /**
     * Checks if a number is prime.
     * 
     * @param num the number to check
     * @return true if the number is prime, false otherwise
     */
    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

