class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Validate inputs
        if (a == null || b == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        if (a.length() != b.length()) {
            throw new IllegalArgumentException("Input strings must have equal length: a.length()=" + a.length() + ", b.length()=" + b.length());
        }

        if (a.isEmpty()) {
            return "";
        }

        StringBuilder result = new StringBuilder(a.length());
        for (int i = 0; i < a.length(); i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            // Validate that characters are only '0' or '1'
            if ((bitA != '0' && bitA != '1') || (bitB != '0' && bitB != '1')) {
                throw new IllegalArgumentException("Input strings must contain only '0' and '1' characters: a='" + a + "', b='" + b + "'");
            }

            // Perform XOR: same bits -> '0', different bits -> '1'
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

