class Solution {
    /**
    Out of list of strings, return the longest one. Return the first one in case of multiple
    strings of the same length. Return None in case the input list is empty.
    >>> longest(List.of())
    Optional.empty
    >>> longest(Arrays.asList("a", "b", "c"))
    Optional[a]
    >>> longest(Arrays.asList("a", "bb", "ccc"))
    Optional[ccc]
     */
    public Optional<String> longest(List<String> strings) {
        // Validate input - handle null list explicitly
        if (strings == null) {
            throw new IllegalArgumentException("Input list cannot be null");
        }

        // Handle empty list case - return Optional.empty()
        if (strings.isEmpty()) {
            return Optional.empty();
        }

        String longest = null;
        int maxLength = -1;

        // Iterate through the list to find the longest string
        for (int i = 0; i < strings.size(); i++) {
            String current = strings.get(i);

            // Validate that individual elements are not null
            if (current == null) {
                throw new IllegalArgumentException(
                    "List contains null element at index " + i + 
                    ", valid indices: [0, " + (strings.size() - 1) + 
                    "], list size: " + strings.size()
                );
            }

            int currentLength = current.length();

            // Use > instead of >= to keep the first occurrence in case of ties
            if (currentLength > maxLength) {
                maxLength = currentLength;
                longest = current;
            }
        }

        return Optional.ofNullable(longest);
    }
}

