class Solution {
    /**
    Return a greatest common divisor of two integers a and b
    >>> greatestCommonDivisor(3, 5)
    1
    >>> greatestCommonDivisor(25, 15)
    5
     */
    public int greatestCommonDivisor(int a, int b) {
        // Handle negative numbers by taking absolute values
        // GCD is always non-negative
        a = Math.abs(a);
        b = Math.abs(b);

        // Handle special case where both are zero
        // According to mathematical definition, gcd(0,0) is undefined,
        // but many implementations return 0 for this case
        if (a == 0 && b == 0) {
            return 0;
        }

        // Euclidean algorithm
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }

        return a;
    }
}

