class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Validate inputs - provide detailed error messages for debugging
        if (string == null) {
            throw new IllegalArgumentException("Input string cannot be null. string=null");
        }
        if (substring == null) {
            throw new IllegalArgumentException("Substring cannot be null. substring=null");
        }

        // Edge case: empty substring - return 0 to avoid infinite counting
        if (substring.isEmpty()) {
            return 0;
        }

        // Edge case: substring longer than string
        if (substring.length() > string.length()) {
            return 0;
        }

        int count = 0;
        int substringLength = substring.length();

        // Check each possible starting position
        for (int i = 0; i <= string.length() - substringLength; i++) {
            // Check if substring matches at position i
            boolean match = true;
            for (int j = 0; j < substringLength; j++) {
                if (string.charAt(i + j) != substring.charAt(j)) {
                    match = false;
                    break;
                }
            }

            if (match) {
                count++;
            }
        }

        return count;
    }
}

