    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        // Handle null or empty input
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        String[] tokens = numbers.split(" ");
        List<String> validWords = new ArrayList<>();

        for (String token : tokens) {
            String trimmedToken = token.trim();
            if (trimmedToken.isEmpty()) {
                continue;
            }

            Integer numValue = WORD_TO_NUM.get(trimmedToken);
            if (numValue == null) {
                throw new IllegalArgumentException(
                    "Invalid number word: '" + trimmedToken + "'. " +
                    "Expected one of: zero, one, two, three, four, five, six, seven, eight, nine."
                );
            }
            validWords.add(trimmedToken);
        }

        // Sort by numeric value using the map
        Collections.sort(validWords, (a, b) -> 
            WORD_TO_NUM.get(a) - WORD_TO_NUM.get(b)
        );

        return String.join(" ", validWords);
    }
}

import java.util.*;
