import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            throw new IllegalArgumentException("Coefficient list cannot be null or empty");
        }

        // Find the actual degree by removing trailing zeros (from highest degree)
        int n = xs.size() - 1;
        while (n > 0 && Math.abs(xs.get(n)) < 1e-15) {
            n--;
        }

        // If the polynomial is constant (degree 0), no root unless it's zero
        if (n == 0) {
            if (Math.abs(xs.get(0)) < 1e-15) {
                return 0.0; // every x is a root, return 0
            } else {
                throw new IllegalArgumentException("Constant polynomial with no roots");
            }
        }

        // For odd degree polynomials, there's always at least one real root
        // Use bisection method after finding appropriate bounds

        // Evaluate polynomial at a point
        java.util.function.DoubleUnaryOperator f = t -> {
            double result = 0;
            double x = 1;
            for (int i = 0; i <= n; i++) {
                result += xs.get(i) * x;
                x *= t;
            }
            return result;
        };

        // Find bounds where f(low) * f(high) < 0
        double low = -1.0;
        double high = 1.0;
        double fl = f.applyAsDouble(low);
        double fh = f.applyAsDouble(high);

        // Expand bounds until we find opposite signs
        int attempts = 0;
        while (fl * fh > 0 && attempts < 30) {
            low *= 2;
            high *= 2;
            fl = f.applyAsDouble(low);
            fh = f.applyAsDouble(high);
            attempts++;
        }

        // If still same sign, try different approach
        if (fl * fh > 0) {
            // Fallback: use Newton-Raphson starting from 0
            double x = 0.0;
            for (int i = 0; i < 100; i++) {
                double fx = f.applyAsDouble(x);
                if (Math.abs(fx) < 1e-12) {
                    return x;
                }
                // Numerical derivative
                double h = 1e-8;
                double fpx = (f.applyAsDouble(x + h) - fx) / h;
                if (Math.abs(fpx) < 1e-12) {
                    x += 1.0; // perturb if derivative is zero
                    continue;
                }
                x = x - fx / fpx;
                if (Double.isNaN(x) || Double.isInfinite(x)) {
                    x = (Math.random() - 0.5) * 10; // random restart
                }
            }
            return x; // Return last approximation
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // sufficient iterations for double precision
            double mid = (low + high) / 2;
            double fm = f.applyAsDouble(mid);

            if (Math.abs(fm) < 1e-12) {
                return mid;
            }

            if (fl * fm <= 0) {
                high = mid;
                fh = fm;
            } else {
                low = mid;
                fl = fm;
            }
        }

        return (low + high) / 2;
    }
}

