class Solution {
    /**
    This function takes a list l and returns a list l' such that
    l' is identical to l in the odd indicies, while its values at the even indicies are equal
    to the values of the even indicies of l, but sorted.
    >>> sortEven(Arrays.asList(1, 2, 3))
    [1, 2, 3]
    >>> sortEven(Arrays.asList(5, 6, 3, 4))
    [3, 6, 5, 4]
     */
    public List<Integer> sortEven(List<Integer> l) {
        // Validate input - capture failure information in exception message
        if (l == null) {
            throw new IllegalArgumentException("Input list cannot be null");
        }

        int n = l.size();
        List<Integer> result = new ArrayList<>(n);

        // Extract even-indexed elements (indices 0, 2, 4, ...)
        List<Integer> evenElements = new ArrayList<>();
        for (int i = 0; i < n; i += 2) {
            evenElements.add(l.get(i));
        }

        // Sort the even-indexed elements
        Collections.sort(evenElements);

        // Build result: place sorted even elements at even indices, keep odd indices unchanged
        int evenIndex = 0;
        for (int i = 0; i < n; i++) {
            if (i % 2 == 0) {
                // Even index: use next sorted element
                if (evenIndex >= evenElements.size()) {
                    throw new IllegalStateException(
                        "Internal error: even index " + evenIndex + 
                        " exceeds available even elements size " + evenElements.size() + 
                        ", list size=" + n
                    );
                }
                result.add(evenElements.get(evenIndex++));
            } else {
                // Odd index: keep original value
                result.add(l.get(i));
            }
        }

        return result;
    }
}

