class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Validate inputs are not null
        if (a == null || b == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        // Validate inputs contain only '0' and '1'
        if (!a.matches("[01]+") || !b.matches("[01]+")) {
            throw new IllegalArgumentException("Input strings must contain only '0' and '1' characters");
        }

        // Pad the shorter string with leading zeros to match lengths
        int maxLen = Math.max(a.length(), b.length());
        StringBuilder aPad = new StringBuilder(a);
        StringBuilder bPad = new StringBuilder(b);

        while (aPad.length() < maxLen) {
            aPad.insert(0, '0');
        }
        while (bPad.length() < maxLen) {
            bPad.insert(0, '0');
        }

        StringBuilder result = new StringBuilder(maxLen);

        // Perform XOR bit by bit
        for (int i = 0; i < maxLen; i++) {
            char bitA = aPad.charAt(i);
            char bitB = bPad.charAt(i);

            // XOR: if bits are same, result is '0'; if different, result is '1'
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

