class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle invalid input - n must be greater than 1 to have a proper divisor
        if (n <= 1) {
            throw new IllegalArgumentException(
                String.format("Cannot find proper divisor for n=%d; n must be > 1", n));
        }

        // The largest proper divisor cannot exceed n/2
        // Check from n/2 down to 1
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // This should never be reached since 1 always divides n and n > 1
        // But include failure-capture info just in case
        throw new IllegalStateException(
            String.format("No proper divisor found for n=%d; this should not happen", n));
    }
}

