class Solution {
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Validate input
        if (xs == null || xs.isEmpty()) {
            throw new IllegalArgumentException("Polynomial coefficients cannot be null or empty");
        }

        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException(
                String.format("Polynomial must have even number of coefficients, got %d", xs.size()));
        }

        // Find the highest non-zero coefficient to determine the degree
        int degree = -1;
        for (int i = xs.size() - 1; i >= 0; i--) {
            if (!xs.get(i).equals(0.0)) {
                degree = i;
                break;
            }
        }

        if (degree == -1) {
            throw new IllegalArgumentException("All coefficients are zero, no polynomial defined");
        }

        // Check if the leading coefficient is indeed the largest non-zero coefficient
        double leadingCoeff = xs.get(degree);
        double maxAbsCoeff = 0;
        for (double coeff : xs) {
            if (Math.abs(coeff) > maxAbsCoeff) {
                maxAbsCoeff = Math.abs(coeff);
            }
        }

        // According to problem statement, largest non-zero coefficient should be the leading one
        // But we'll just check if leading coefficient is non-zero (already ensured by finding degree)

        // Newton-Raphson with multiple starting points
        double[] startingPoints = {0.0, 1.0, -1.0, 10.0, -10.0, 0.5, -0.5, 2.0, -2.0};
        double root = Double.NaN;

        for (double start : startingPoints) {
            try {
                root = newtonRaphson(xs, start, 100, 1e-12);
                if (!Double.isNaN(root) && Math.abs(poly(xs, root)) < 1e-8) {
                    return root;
                }
            } catch (Exception e) {
                // Continue to next starting point
            }
        }

        // Fallback: Bisection method on a wide range
        double left = -1000.0;
        double right = 1000.0;

        // Find interval where sign changes
        while (left < right) {
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            if (fLeft * fRight <= 0) {
                // Sign change detected, use bisection
                root = bisection(xs, left, right, 1000, 1e-12);
                if (!Double.isNaN(root) && Math.abs(poly(xs, root)) < 1e-8) {
                    return root;
                }
                break;
            }

            // Expand search range
            left *= 2;
            right *= 2;

            // Prevent infinite loop
            if (Math.abs(left) > 1e10) {
                break;
            }
        }

        // If still no root found, throw exception with failure-capture info
        throw new RuntimeException(
            String.format("Failed to find root for polynomial with coefficients %s", xs.toString())
        );
    }

    private double newtonRaphson(List<Double> coeffs, double x0, int maxIterations, double tolerance) {
        double x = x0;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(coeffs, x);

            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Calculate derivative
            double fPrime = polyDerivative(coeffs, x);

            if (Math.abs(fPrime) < 1e-15) {
                // Derivative too small, try perturbation
                fPrime = 1e-15;
            }

            double xNext = x - fx / fPrime;

            // Check for convergence
            if (Math.abs(xNext - x) < tolerance) {
                // Verify it's actually a root
                if (Math.abs(poly(coeffs, xNext)) < tolerance) {
                    return xNext;
                }
            }

            x = xNext;
        }

        return Double.NaN;
    }

    private double polyDerivative(List<Double> coeffs, double x) {
        if (coeffs.size() <= 1) {
            return 0;
        }

        double result = 0;
        for (int i = 1; i < coeffs.size(); i++) {
            result += i * coeffs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }

    private double bisection(List<Double> coeffs, double left, double right, int maxIterations, double tolerance) {
        double fLeft = poly(coeffs, left);
        double fRight = poly(coeffs, right);

        // Check if we have a sign change
        if (fLeft * fRight > 0) {
            return Double.NaN;
        }

        for (int i = 0; i < maxIterations; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(coeffs, mid);

            if (Math.abs(fMid) < tolerance || (right - left) / 2 < tolerance) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

