    >>> hasCloseElements(Arrays.asList(1.0, 2.0, 3.0), 0.5)
    false
    >>> hasCloseElements(Arrays.asList(1.0, 2.8, 3.0, 4.0, 5.0, 2.0), 0.3)
    true
     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        // Validate parameters before performing any operations (Item 49)
        if (numbers == null) {
            throw new IllegalArgumentException("List of numbers cannot be null");
        }

        // Negative threshold doesn't make sense for "closer than"
        if (threshold < 0) {
            throw new IllegalArgumentException("Threshold must be non-negative");
        }

        // Handle edge cases
        if (numbers.size() < 2) {
            return false;
        }

        // Create a copy and sort it to check adjacent pairs only
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        // Check each adjacent pair
        for (int i = 0; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < threshold) {
                return true;
            }
        }

        return false;
    }
}

