class Solution {
    public double findZero(List<Double> xs) {
        // Validate: even number of coefficients
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Find the leading coefficient (highest degree, last non-zero)
        int n = xs.size() - 1;
        double leadingCoeff = 0.0;
        for (int i = n; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-15) {
                leadingCoeff = xs.get(i);
                break;
            }
        }
        if (Math.abs(leadingCoeff) < 1e-15) {
            throw new IllegalArgumentException("No non-zero coefficients found");
        }

        // Bisection method
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand interval until we have sign change
        int expansionAttempts = 0;
        while (fLeft * fRight > 0 && expansionAttempts < 20) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            expansionAttempts++;
        }

        // If still no sign change, fallback to Newton or just return midpoint
        if (fLeft * fRight > 0) {
            // Try derivative-based guess or just return 0
            return 0.0;
        }

        // Bisection loop
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12 || (right - left) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

