class Solution {
    /**
    Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parseNestedParens("(()()) ((())) () ((())()())")
    [2, 3, 1, 3]
     */
    public List<Integer> parseNestedParens(String paren_string) {
        // Handle null or empty input
        if (paren_string == null || paren_string.trim().isEmpty()) {
            return new ArrayList<>();
        }

        // Split by spaces to get individual groups
        String[] groups = paren_string.trim().split("\\s+");

        // Use a temporary list to achieve failure atomicity
        List<Integer> result = new ArrayList<>(groups.length);

        try {
            for (String group : groups) {
                int maxDepth = 0;
                int currentDepth = 0;

                for (char c : group.toCharArray()) {
                    if (c == '(') {
                        currentDepth++;
                        maxDepth = Math.max(maxDepth, currentDepth);
                    } else if (c == ')') {
                        currentDepth--;
                    }
                    // Invalid characters would cause issues, but per problem spec we assume valid input
                }

                result.add(maxDepth);
            }

            return result;
        } catch (Exception e) {
            // If something goes wrong, return an empty list to maintain failure atomicity
            // The original string wasn't modified, and no partial results are returned
            throw new RuntimeException("Failed to parse parentheses: " + e.getMessage(), e);
        }
    }
}

