class Solution {
    /**
    Out of list of strings, return the longest one. Return the first one in case of multiple
    strings of the same length. Return None in case the input list is empty.
    >>> longest(List.of())
    Optional.empty
    >>> longest(Arrays.asList("a", "b", "c"))
    Optional[a]
    >>> longest(Arrays.asList("a", "bb", "ccc"))
    Optional[ccc]
     */
    public Optional<String> longest(List<String> strings) {
        // Handle null input - could throw NullPointerException, but better to be defensive
        if (strings == null) {
            return Optional.empty();
        }

        // Handle empty list
        if (strings.isEmpty()) {
            return Optional.empty();
        }

        String longest = null;
        int maxLen = -1;

        for (String s : strings) {
            // Handle null elements in the list - skip them or treat as length 0?
            // Since the problem says "list of strings", we'll assume non-null strings
            // but be defensive anyway
            if (s == null) {
                continue; // skip null elements
            }

            int len = s.length();
            if (len > maxLen) {
                maxLen = len;
                longest = s;
            }
            // Note: if len == maxLen, we keep the current 'longest' (first occurrence)
        }

        // If all elements were null, longest could still be null
        if (longest == null) {
            return Optional.empty();
        }

        return Optional.of(longest);
    }
}

