        String[] tokens = numbers.trim().split("\\s+");

        // Validate and convert to integers using a temporary list
        List<Integer> tempNumbers = new ArrayList<>();
        for (String token : tokens) {
            Integer num = wordToNumber.get(token);
            if (num == null) {
                throw new IllegalArgumentException("Invalid number word: " + token);
            }
            tempNumbers.add(num);
        }

        // Sort the numbers
        Collections.sort(tempNumbers);

        // Convert back to words using a reverse mapping (created on the fly)
        String[] validWords = {"zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"};

        // Build result string using a temporary StringBuilder for failure atomicity
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < tempNumbers.size(); i++) {
            if (i > 0) {
                result.append(" ");
            }
            result.append(validWords[tempNumbers.get(i)]);
        }

        return result.toString();
    }
}

