class Solution {
    public List<Double> findClosestElements(List<Double> numbers) {
        // Create a temporary copy to ensure failure atomicity
        List<Double> sortedNumbers = new ArrayList<>(numbers);
        Collections.sort(sortedNumbers);

        double minDiff = Double.POSITIVE_INFINITY;
        int minIndex = 0;

        // Check adjacent pairs only - the closest pair must be adjacent in sorted order
        for (int i = 0; i < sortedNumbers.size() - 1; i++) {
            double diff = Math.abs(sortedNumbers.get(i + 1) - sortedNumbers.get(i));
            if (diff < minDiff) {
                minDiff = diff;
                minIndex = i;
            }
        }

        // Return in order (smaller, larger) - since sorted, sortedNumbers.get(minIndex) <= sortedNumbers.get(minIndex + 1)
        return Arrays.asList(
            sortedNumbers.get(minIndex),
            sortedNumbers.get(minIndex + 1)
        );
    }
}

