    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method to find a root
        // Start with initial guess and iterate
        double x = 0.0; // initial guess

        // Try multiple starting points to increase chances of finding a root
        double[] initialGuesses = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

        for (double guess : initialGuesses) {
            double currentX = guess;
            for (int iteration = 0; iteration < 100; iteration++) {
                double fx = poly(xs, currentX);

                // If we're close enough to zero, return
                if (Math.abs(fx) < 1e-9) {
                    return currentX;
                }

                // Compute derivative using numerical differentiation
                double h = 1e-8;
                double fPrime = (poly(xs, currentX + h) - poly(xs, currentX - h)) / (2 * h);

                // Avoid division by zero or very small derivative
                if (Math.abs(fPrime) < 1e-12) {
                    break; // try next initial guess
                }

                double nextX = currentX - fx / fPrime;

                // Check if we're converging or diverging
                if (Double.isNaN(nextX) || Double.isInfinite(nextX)) {
                    break; // try next initial guess
                }

                // Check for convergence
                if (Math.abs(nextX - currentX) < 1e-9) {
                    // Verify this is actually a root
                    if (Math.abs(poly(xs, nextX)) < 1e-6) {
                        return nextX;
                    }
                    break; // try next initial guess
                }

                currentX = nextX;
            }
        }

        // Fallback: try bisection method on a wide range
        // Since polynomial has odd degree, it must go from -inf to +inf or vice versa
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Make sure we have a sign change
        if (fLeft * fRight > 0) {
            // Expand range until we find sign change
            for (int i = 0; i < 20 && fLeft * fRight > 0; i++) {
                left *= 2;
                right *= 2;
                fLeft = poly(xs, left);
                fRight = poly(xs, right);
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint as best approximation
        return (left + right) / 2;
    }
}

