class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Generate Fibonacci numbers and check if they're prime
        int count = 0;
        long a = 1; // F(1)
        long b = 1; // F(2)

        // Handle special case: F(3) = 2
        if (n == 1) {
            return 2;
        }

        // Start from F(3) = 2
        long current = 2;
        int fibIndex = 3;

        while (true) {
            // Check if current Fibonacci number is prime
            if (isPrime(current)) {
                count++;
                if (count == n) {
                    return (int) current;
                }
            }

            // Generate next Fibonacci number
            long next = a + b;
            a = b;
            b = next;
            current = next;
            fibIndex++;
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

