class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        // Handle null or empty input
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        // Create mapping from word to digit
        Map<String, Integer> wordToDigit = new HashMap<>();
        wordToDigit.put("zero", 0);
        wordToDigit.put("one", 1);
        wordToDigit.put("two", 2);
        wordToDigit.put("three", 3);
        wordToDigit.put("four", 4);
        wordToDigit.put("five", 5);
        wordToDigit.put("six", 6);
        wordToDigit.put("seven", 7);
        wordToDigit.put("eight", 8);
        wordToDigit.put("nine", 9);

        // Create reverse mapping from digit to word
        Map<Integer, String> digitToWord = new HashMap<>();
        for (Map.Entry<String, Integer> entry : wordToDigit.entrySet()) {
            digitToWord.put(entry.getValue(), entry.getKey());
        }

        // Split input string and process each token
        String[] tokens = numbers.trim().split("\\s+");
        List<Integer> digitList = new ArrayList<>();

        for (String token : tokens) {
            try {
                Integer digit = wordToDigit.get(token.toLowerCase());
                if (digit == null) {
                    // Handle invalid input - could throw exception or skip
                    // Following the principle of handling exceptions properly,
                    // we'll include a meaningful error handling approach
                    throw new IllegalArgumentException("Invalid number word: '" + token + "'");
                }
                digitList.add(digit);
            } catch (IllegalArgumentException e) {
                // Re-throw with more context, or handle gracefully
                // For this problem, let's assume valid input as per spec
                throw e;
            }
        }

        // Sort the digits
        Collections.sort(digitList);

        // Convert back to words
        List<String> resultWords = new ArrayList<>();
        for (Integer digit : digitList) {
            resultWords.add(digitToWord.get(digit));
        }

        return String.join(" ", resultWords);
    }
}

