class Solution {
    public double findZero(List<Double> xs) {
        // For polynomials with odd degree (even number of coefficients), 
        // there's always at least one real root

        // First, find a large enough interval where sign changes
        double left = -1000.0;
        double right = 1000.0;

        // Expand the search range if needed
        while (poly(xs, left) > 0 && poly(xs, right) > 0) {
            left *= 10;
            right *= 10;
        }
        while (poly(xs, left) < 0 && poly(xs, right) < 0) {
            left *= 10;
            right *= 10;
        }

        // Bisection method
        double mid = 0;
        int maxIterations = 100;
        double tolerance = 1e-9;

        for (int i = 0; i < maxIterations; i++) {
            mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance) {
                break;
            }

            double fLeft = poly(xs, left);
            if (fLeft * fMid > 0) {
                left = mid;
            } else {
                right = mid;
            }
        }

        return mid;
    }
}

