     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return 0; // No proper divisors for 0 or 1
        }

        // Start from n/2 and go downwards
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // This line is theoretically unreachable for n > 1, but included for safety
    }
}

