class Solution {
    public double findZero(List<Double> xs) {
        // Create a function to evaluate polynomial
        // Since poly() already exists, we'll use it

        // Start with initial interval and expand until sign change
        double left = -1.0;
        double right = 1.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand interval until sign change (or max attempts)
        int maxExpansions = 100;
        int expansionCount = 0;
        while (fLeft * fRight > 0 && expansionCount < maxExpansions) {
            left *= 2.0;
            right *= 2.0;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            expansionCount++;
        }

        // If still no sign change, fallback to Newton or just return mid
        // But problem says solution guaranteed, so assume sign change found
        if (fLeft * fRight > 0) {
            // Last resort: return midpoint (shouldn't happen per problem statement)
            return 0.0;
        }

        // Bisection method
        double mid;
        double fMid;
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~1e-30 precision
            mid = (left + right) / 2.0;
            fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

