import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: constant polynomial (shouldn't happen per problem statement, but safety)
        if (xs.size() <= 1) {
            return 0.0;
        }

        // Define the polynomial evaluation function locally
        java.util.function.DoubleUnaryOperator polyFunc = x -> poly(xs, x);

        // Try to find an interval [a, b] where f(a) * f(b) < 0 (sign change)
        double a = -1.0;
        double b = 1.0;
        double fa = polyFunc.applyAsDouble(a);
        double fb = polyFunc.applyAsDouble(b);

        // Expand interval until we find sign change
        int iterations = 0;
        while (fa * fb > 0 && iterations < 100) {
            a *= 2;
            b *= 2;
            fa = polyFunc.applyAsDouble(a);
            fb = polyFunc.applyAsDouble(b);
            iterations++;
        }

        // If still no sign change, return midpoint (fallback)
        if (fa * fb > 0) {
            return 0.0;
        }

        // Bisection method to find root
        for (int i = 0; i < 100; i++) { // 100 iterations for precision
            double mid = (a + b) / 2;
            double fm = polyFunc.applyAsDouble(mid);

            if (Math.abs(fm) < 1e-12) {
                return mid;
            }

            if (fa * fm < 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2;
    }
}

