class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 0; // First Fibonacci number F(0)
        int b = 1; // Second Fibonacci number F(1)

        // Check F(0) = 0 - not prime
        // Check F(1) = 1 - not prime
        // Check F(2) = 1 - not prime
        // Start from F(3) = 2

        // We need to handle the early Fibonacci numbers specially since F(0)=0, F(1)=1, F(2)=1
        // Then F(3)=2, F(4)=3, F(5)=5, F(6)=8, etc.

        if (n == 1) return 2;
        if (n == 2) return 3;
        if (n == 3) return 5;
        if (n == 4) return 13;
        if (n == 5) return 89;

        // For larger n, generate Fibonacci numbers and check for primality
        // Start generating from F(3) onwards
        int prev = 2; // F(3) = 2
        int curr = 3; // F(4) = 3
        count = 2; // We already counted 2 and 3

        while (true) {
            // Generate next Fibonacci number
            int next = prev + curr;
            prev = curr;
            curr = next;

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

