    >>> makePalindrome("")
    ""
    >>> makePalindrome("cat")
    "catac"
    >>> makePalindrome("cata")
    "catac"
     */
    public String makePalindrome(String string) {
        if (string == null || string.isEmpty()) {
            return string;
        }

        // Find the longest palindromic suffix
        for (int i = 0; i < string.length(); i++) {
            if (isPalindrome(string.substring(i))) {
                // The suffix starting at i is palindromic
                // We need to append reverse of prefix [0, i)
                String prefix = string.substring(0, i);
                String reversePrefix = new StringBuilder(prefix).reverse().toString();
                return string + reversePrefix;
            }
        }

        // Fallback (should never reach here since single char is always palindrome)
        return string;
    }
}

