import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Create a function to evaluate the polynomial
        java.util.function.DoubleUnaryOperator f = x -> poly(xs, x);

        // Find an interval [a, b] where f(a) and f(b) have opposite signs
        double a = -10.0;
        double b = 10.0;
        double fa = f.applyAsDouble(a);
        double fb = f.applyAsDouble(b);

        // Expand interval until we find sign change
        int expansionCount = 0;
        while (fa * fb > 0 && expansionCount < 30) {
            a *= 2;
            b *= 2;
            fa = f.applyAsDouble(a);
            fb = f.applyAsDouble(b);
            expansionCount++;
        }

        // If still no sign change, try different starting points
        if (fa * fb > 0) {
            // Fallback: try with larger range
            a = -1000.0;
            b = 1000.0;
            fa = f.applyAsDouble(a);
            fb = f.applyAsDouble(b);
            expansionCount = 0;
            while (fa * fb > 0 && expansionCount < 30) {
                a *= 2;
                b *= 2;
                fa = f.applyAsDouble(a);
                fb = f.applyAsDouble(b);
                expansionCount++;
            }
        }

        // Bisection method
        double tolerance = 1e-9;
        int maxIterations = 100;

        for (int i = 0; i < maxIterations; i++) {
            double mid = (a + b) / 2;
            double fm = f.applyAsDouble(mid);

            if (Math.abs(fm) < tolerance || (b - a) / 2 < tolerance) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2; // Return midpoint if didn't converge exactly
    }
}

