                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Use bisection method to find a root
        // First, find bounds where the function changes sign

        // Check if polynomial is constant (shouldn't happen per constraints, but handle safely)
        if (xs.size() <= 1) {
            return 0.0;
        }

        // Define the polynomial evaluation function locally
        java.util.function.DoubleUnaryOperator polyFunc = x -> {
            double result = 0;
            double xPower = 1;
            for (double coeff : xs) {
                result += coeff * xPower;
                xPower *= x;
            }
            return result;
        };

        // Find bounds with opposite signs
        double low = -1.0;
        double high = 1.0;
        double fLow = polyFunc.applyAsDouble(low);
        double fHigh = polyFunc.applyAsDouble(high);

        // Expand bounds until we find opposite signs
        int iterations = 0;
        while (fLow * fHigh >= 0 && iterations < 100) {
            low *= 2;
            high *= 2;
            fLow = polyFunc.applyAsDouble(low);
            fHigh = polyFunc.applyAsDouble(high);
            iterations++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~1e-30 precision
            double mid = (low + high) / 2.0;
            double fMid = polyFunc.applyAsDouble(mid);

            if (Math.abs(fMid) < 1e-15) {
                return mid;
            }

            if (fLow * fMid <= 0) {
                high = mid;
                fHigh = fMid;
            } else {
                low = mid;
                fLow = fMid;
            }
        }

        return (low + high) / 2.0;
    }
}

