class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Handle small cases directly based on known sequence
        if (n == 1) return 2;
        if (n == 2) return 3;
        if (n == 3) return 5;
        if (n == 4) return 13;
        if (n == 5) return 89;

        int count = 5; // We've already handled up to n=5

        // Start generating from F(12) = 144 onwards
        long a = 89; // F(11) = 89
        long b = 144; // F(12) = 144

        while (true) {
            long c = a + b;
            a = b;
            b = c;

            if (isPrime(c)) {
                count++;
                if (count == n) {
                    return (int) c;
                }
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0) return false;
        if (num % 3 == 0) return (num == 3);

        // Check for divisibility by numbers of form 6k ± 1
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

