class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true; // 2 and 3 are prime
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check for factors from 5 up to sqrt(n), skipping even numbers
        // We use the 6k ± 1 optimization: all primes > 3 are of form 6k±1
        int i = 5;
        while (i * i <= n) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
            i += 6;
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Newton-Raphson method
        // Start with initial guess
        double x = 1.0;

        // Derivative of polynomial: for coefficients [a0, a1, a2, ..., an],
        // derivative is [a1, 2*a2, 3*a3, ..., n*an]
        List<Double> derivatives = new ArrayList<>();
        for (int i = 1; i < xs.size(); i++) {
            derivatives.add(xs.get(i) * i);
        }

        int maxIterations = 1000;
        double tolerance = 1e-10;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);

            // Check if we've found a root
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Calculate derivative at x
            double fpx = poly(derivatives, x);

            // Avoid division by zero
            if (Math.abs(fpx) < tolerance) {
                // Try a different starting point if derivative is too small
                x += 0.5;
                continue;
            }

            // Newton-Raphson update: x_{n+1} = x_n - f(x_n) / f'(x_n)
            x = x - fx / fpx;
        }

        // If we didn't converge, return the best estimate
        return x;
    }
}

