class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Convert to array for faster access
        double[] coeffs = new double[xs.size()];
        for (int i = 0; i < xs.size(); i++) {
            coeffs[i] = xs.get(i);
        }

        // Find the degree (highest non-zero coefficient index)
        int degree = coeffs.length - 1;
        while (degree >= 0 && Math.abs(coeffs[degree]) < 1e-15) {
            degree--;
        }

        // Since we have even number of coefficients, degree should be odd
        // We know a root exists due to the problem guarantee

        // For bisection, we need to find an interval [a, b] where f(a)*f(b) < 0
        // For odd-degree polynomial, as x->+inf, f(x)->sign(leading)*inf
        // and as x->-inf, f(x)->-sign(leading)*inf

        double leadingCoeff = coeffs[degree];

        // Find initial bounds
        double left = -1.0;
        double right = 1.0;

        // Expand until we get opposite signs
        while (true) {
            double fLeft = evaluatePolynomial(coeffs, left);
            double fRight = evaluatePolynomial(coeffs, right);

            if (fLeft * fRight <= 0) {
                break;
            }

            // Expand the interval
            left *= 10;
            right *= 10;

            // Safety limit to prevent infinite loop
            if (Math.abs(left) > 1e9) {
                // Fallback: just return 0 if we can't find bounds
                return 0.0;
            }
        }

        // Apply bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations should give good precision
            double mid = (left + right) / 2.0;
            double fMid = evaluatePolynomial(coeffs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            double fLeft = evaluatePolynomial(coeffs, left);
            if (fLeft * fMid <= 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2.0;
    }

    // Helper method to evaluate polynomial
    private double evaluatePolynomial(double[] coeffs, double x) {
        double result = 0;
        for (int i = coeffs.length - 1; i >= 0; i--) {
            result = result * x + coeffs[i];
        }
        return result;
    }
}

