class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Define precision
        final double EPSILON = 1e-10;

        // Evaluate at some starting points to find interval with sign change
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If we're lucky and hit zero directly
        if (Math.abs(fLeft) < EPSILON) return left;
        if (Math.abs(fRight) < EPSILON) return right;

        // Expand search range until we find sign change (polynomial behavior)
        // Since leading coefficient ensures solution exists, we can expand until sign change
        while (fLeft * fRight > 0) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);

            // Safety check to avoid infinite loop
            if (Math.abs(left) > 1e15) {
                // Fallback: use Newton's method from 0
                return newtonMethod(xs, 0.0);
            }
        }

        // Bisection method
        while (right - left > EPSILON) {
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < EPSILON) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }

    // Alternative: Newton-Raphson method as fallback
    private double newtonMethod(List<Double> xs, double x0) {
        final double EPSILON = 1e-10;
        double x = x0;

        for (int i = 0; i < 1000; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < EPSILON) {
                return x;
            }

            // Compute derivative numerically
            double h = 1e-8;
            double fPrime = (poly(xs, x + h) - poly(xs, x - h)) / (2 * h);

            if (Math.abs(fPrime) < 1e-15) {
                // Derivative too small, perturb x
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fPrime;

            // Check for divergence
            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                x += 0.1;
            } else {
                x = xNext;
            }
        }

        return x;
    }
}

