class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special case: F(0)=0 and F(1)=1 are not prime
        // Start from F(2)=1, but we know F(3)=2 is the first prime Fibonacci

        while (count < n) {
            long next = a + b;
            a = b;
            b = next;

            // Check if 'a' (the current Fibonacci number) is prime
            if (isPrime(a)) {
                count++;
                if (count == n) {
                    return (int) a;
                }
            }
        }

        // Should never reach here for valid inputs
        return -1;
    }

    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0 || num % 3 == 0) {
            return false;
        }

        // Check divisors up to sqrt(num)
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

