        }

        String[] notes = string.trim().split("\\s+");

        for (String note : notes) {
            switch (note) {
                case "o":
                    result.add(4);
                    break;
                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // According to problem statement, only these three formats should appear
                    // But if needed, could handle error case here
                    break;
            }
        }

        return result;
    }
}

