class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Create polynomial function
        java.util.function.DoubleUnaryOperator poly = (double x) -> poly(xs, x);

        // For odd degree polynomials, we know limits at ±∞ are opposite signs
        // Start with a reasonable range and expand if needed
        double left = -1000.0;
        double right = 1000.0;

        double fLeft = poly.applyAsDouble(left);
        double fRight = poly.applyAsDouble(right);

        // If same sign, expand the interval
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 20) {
            left *= 10;
            right *= 10;
            fLeft = poly.applyAsDouble(left);
            fRight = poly.applyAsDouble(right);
            attempts++;
        }

        // Bisection method
        double mid;
        double fMid;
        int iterations = 100;

        // Ensure we have opposite signs
        if (fLeft * fRight > 0) {
            // Fallback: try Newton-Raphson with starting point 0
            mid = 0.0;
            for (int i = 0; i < iterations; i++) {
                double fVal = poly.applyAsDouble(mid);
                // Numerical derivative
                double h = 1e-8;
                double fPrime = (poly.applyAsDouble(mid + h) - fVal) / h;
                if (Math.abs(fPrime) < 1e-12) {
                    mid += 0.1; // perturb if derivative too small
                    continue;
                }
                double next = mid - fVal / fPrime;
                if (Double.isNaN(next) || Double.isInfinite(next)) {
                    mid += 0.1;
                    continue;
                }
                mid = next;
            }
            return mid;
        }

        // Bisection
        for (int i = 0; i < iterations; i++) {
            mid = (left + right) / 2.0;
            fMid = poly.applyAsDouble(mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

