    public List<Integer> unique(List<Integer> l) {
        if (l == null) {
            return new ArrayList<>();
        }

        // Use a TreeSet to automatically remove duplicates and sort
        // Since we need ascending order and TreeSet is sorted by natural ordering
        Set<Integer> set = new TreeSet<>(l);

        // Convert back to a List
        return new ArrayList<>(set);
    }
}

