class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) return -1;

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special cases for small Fibonacci numbers
        if (a == 2 || isPrime((int)a)) { // 0 is not prime
            // skip 0
        }

        // Check Fibonacci numbers starting from 2 (which is F(3))
        if (isPrime(2)) {
            count++;
            if (count == n) return 2;
        }

        if (isPrime(3)) {
            count++;
            if (count == n) return 3;
        }

        // Start generating from F(4) = 3, F(5) = 5, etc.
        // But we already checked 2 and 3, so start with 5
        long fib = 5;
        long prev1 = 3;
        long prev2 = 2;

        while (true) {
            if (isPrime((int)fib)) {
                count++;
                if (count == n) {
                    return (int)fib;
                }
            }

            // Generate next Fibonacci number
            long next = fib + prev1;
            prev2 = prev1;
            prev1 = fib;
            fib = next;

            // Safety check to prevent overflow
            if (fib > Integer.MAX_VALUE) {
                break;
            }
        }

        return -1;
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

