class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // For odd-degree polynomials, as x -> ±∞, p(x) -> ±∞ or ∓∞ depending on leading coefficient sign
        // So we can find large enough a, b such that poly(a) < 0 and poly(b) > 0 (or vice versa)

        double a = -1000.0;
        double b = 1000.0;
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Ensure we have opposite signs
        // If not, expand the interval
        int iterations = 0;
        while (fa * fb > 0 && iterations < 20) {
            a *= 10;
            b *= 10;
            fa = poly(xs, a);
            fb = poly(xs, b);
            iterations++;
        }

        // Now apply bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~1e-30 precision
            double mid = (a + b) / 2.0;
            double fmid = poly(xs, mid);

            if (Math.abs(fmid) < 1e-12) {
                return mid;
            }

            if (fa * fmid < 0) {
                b = mid;
                fb = fmid;
            } else {
                a = mid;
                fa = fmid;
            }
        }

        return (a + b) / 2.0;
    }
}

