     */
    public Optional<String> longest(List<String> strings) {
        if (strings == null || strings.isEmpty()) {
            return Optional.empty();
        }

        String result = null;
        int maxLength = -1;

        for (String s : strings) {
            // Skip null strings if any
            if (s == null) {
                continue;
            }

            int length = s.length();
            if (length > maxLength) {
                maxLength = length;
                result = s;
            }
            // Note: We don't update for equal length, so first occurrence is preserved
        }

        return Optional.ofNullable(result);
    }
}

