            switch (token) {
                case "o":
                    result.add(4);
                    break;
                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // According to the problem, input should only contain valid tokens,
                    // but we could add error handling if needed
                    break;
            }
        }

        return result;
    }
}

