    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        double xPower = 1;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * xPower;
            xPower *= x;
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method
        double x = 1.0; // initial guess

        // Avoid division by zero in derivative - if all coefficients zero, return 0
        if (xs.stream().allMatch(c -> c == 0)) {
            return 0.0;
        }

        for (int iteration = 0; iteration < 100; iteration++) {
            double fx = poly(xs, x);

            // Check if we're close enough to a root
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative: f'(x) = sum_{i=1}^{n} i * xs[i] * x^(i-1)
            double fpx = 0.0;
            double xPower = 1.0;
            for (int i = 1; i < xs.size(); i++) {
                fpx += i * xs.get(i) * xPower;
                xPower *= x;
            }

            // Handle case where derivative is zero (avoid division by zero)
            if (Math.abs(fpx) < 1e-15) {
                // Try a different starting point or perturb current x
                x += 0.1;
                continue;
            }

            double newX = x - fx / fpx;

            // Check for convergence
            if (Math.abs(newX - x) < 1e-10) {
                // Final check
                if (Math.abs(poly(xs, newX)) < 1e-10) {
                    return newX;
                }
            }

            x = newX;
        }

        // Return best approximation after max iterations
        return x;
    }
}

