class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Use Horner's method for better numerical stability and efficiency
        double result = 0.0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle special case: linear polynomial (2 coefficients)
        if (xs.size() == 2) {
            // ax + b = 0 => x = -b/a
            double a = xs.get(1);
            double b = xs.get(0);
            return -b / a;
        }

        // For higher degree polynomials, use Newton-Raphson method
        double x = 1.0; // initial guess
        double epsilon = 1e-10;

        for (int i = 0; i < 100; i++) { // max iterations
            double fx = poly(xs, x);
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative using Horner's method
            double fpx = polyDerivative(xs, x);
            if (Math.abs(fpx) < epsilon) {
                // Derivative too small, try small perturbation
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < epsilon) {
                if (Math.abs(poly(xs, xNext)) < epsilon) {
                    return xNext;
                }
            }

            x = xNext;

            // If x becomes NaN or too large, reset with different initial guess
            if (Double.isNaN(x) || Double.isInfinite(x) || Math.abs(x) > 1e6) {
                x = (i % 3 == 0) ? -1.0 : (i % 3 == 1) ? 0.0 : 2.0;
            }
        }

        // Fallback: return the best approximation found
        return x;
    }

    // Helper method to evaluate derivative of polynomial
    private double polyDerivative(List<Double> xs, double x) {
        if (xs.size() <= 1) {
            return 0.0;
        }

        // Derivative coefficients: for xs[0] + xs[1]*x + xs[2]*x^2 + ..., 
        // derivative is xs[1] + 2*xs[2]*x + 3*xs[3]*x^2 + ...
        double result = 0.0;
        for (int i = 1; i < xs.size(); i++) {
            result = result * x + (i * xs.get(i));
        }
        return result;
    }
}

