class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case
        if (xs.isEmpty()) {
            return 0.0;
        }

        // Find the highest-degree non-zero coefficient (leading term)
        int degree = xs.size() - 1;
        while (degree >= 0 && Math.abs(xs.get(degree)) < 1e-12) {
            degree--;
        }

        // Shouldn't happen per problem statement, but safety check
        if (degree < 0) {
            return 0.0;
        }

        // Since we have even number of coefficients, degree is odd (xs.size() - 1 is odd when xs.size() is even)
        // Odd-degree polynomials always have at least one real root

        // Use Newton-Raphson method with fallback to bisection
        double x = 1.0; // initial guess
        double tolerance = 1e-9;
        int maxIterations = 1000;

        // Try Newton-Raphson
        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative numerically
            double h = 1e-8;
            double fpx = (poly(xs, x + h) - fx) / h;

            if (Math.abs(fpx) < 1e-12) {
                // Derivative too small, try different initial guess or switch to bisection
                break;
            }

            double xNext = x - fx / fpx;

            // Check for divergence
            if (Double.isNaN(xNext) || Double.isInfinite(xNext) || Math.abs(xNext - x) > 1e6) {
                break;
            }

            x = xNext;
        }

        // If Newton-Raphson failed, use bisection with expanding search
        double left = -1000.0;
        double right = 1000.0;

        // Expand search range until we find sign change
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        int expandAttempts = 20;
        double expansionFactor = 10.0;

        for (int attempt = 0; attempt < expandAttempts && (fLeft * fRight > 0); attempt++) {
            left *= expansionFactor;
            right *= expansionFactor;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // sufficient iterations for double precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance || (right - left) < tolerance) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Fallback: return midpoint of final interval
        return (left + right) / 2.0;
    }
}

