class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrtN = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For Newton's method, start with initial guess
        double x = 1.0;
        int maxIterations = 100;
        double tolerance = 1e-10;

        // Try Newton's method
        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative
            double fpx = polyDerivative(xs, x);
            if (Math.abs(fpx) < 1e-15) {
                // Derivative too small, try different starting point
                x = x + 1.0;
                continue;
            }

            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < tolerance) {
                if (Math.abs(poly(xs, xNext)) < tolerance) {
                    return xNext;
                }
            }

            x = xNext;

            // If x goes to infinity, break and try bisection-like approach
            if (Double.isInfinite(x) || Double.isNaN(x)) {
                x = 0.0;
                break;
            }
        }

        // Fallback: try scanning for sign changes
        // Start from small values and expand
        for (double start = -10.0; start <= 10.0; start += 0.5) {
            double left = start;
            double right = start + 0.5;
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            if (fLeft == 0.0) return left;
            if (fRight == 0.0) return right;
            if (fLeft * fRight < 0) {
                // Sign change detected, use bisection
                for (int i = 0; i < 50; i++) {
                    double mid = (left + right) / 2;
                    double fMid = poly(xs, mid);
                    if (Math.abs(fMid) < 1e-10) {
                        return mid;
                    }
                    if (fLeft * fMid < 0) {
                        right = mid;
                    } else {
                        left = mid;
                        fLeft = fMid;
                    }
                }
                return (left + right) / 2;
            }
        }

        // Last resort: return the last Newton iteration value
        return x;
    }

    private double polyDerivative(List<Double> xs, double x) {
        // Derivative: if f(x) = a0 + a1*x + a2*x^2 + ... + an*x^n
        // then f'(x) = a1 + 2*a2*x + 3*a3*x^2 + ... + n*an*x^(n-1)
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

