class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Handle edge cases - if lengths differ, we need to decide behavior
        // Based on typical binary XOR operations, we assume equal length strings
        // or pad with leading zeros. However, the problem doesn't specify,
        // so we'll process up to the minimum length and handle the rest.

        StringBuilder result = new StringBuilder();
        int len = Math.min(a.length(), b.length());

        // Process the common length part
        for (int i = 0; i < len; i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            // XOR: same bits give 0, different bits give 1
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

