import java.lang.*;

class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true;
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check odd divisors from 5 to sqrt(n), skipping even numbers
        // Use 6k ± 1 optimization: all primes > 3 are of form 6k ± 1
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Newton-Raphson method with safeguard
        double x = 1.0; // initial guess

        for (int iter = 0; iter < 100; iter++) {
            double fx = polyValue(xs, x);

            // If we're close enough to zero, return
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative
            double fpx = polyDerivativeValue(xs, x);

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-10) {
                // Try a different approach: perturb x slightly
                x += 0.1;
                continue;
            }

            // Newton step
            double xNext = x - fx / fpx;

            // Check for divergence
            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                // Fallback to bisection with reasonable bounds
                return bisection(xs, -1000.0, 1000.0);
            }

            // Check convergence
            if (Math.abs(xNext - x) < 1e-10) {
                return xNext;
            }

            x = xNext;
        }

        // Return best approximation after max iterations
        return x;
    }

    // Helper method to evaluate polynomial at x
    private double polyValue(List<Double> coeffs, double x) {
        double result = 0.0;
        double xPower = 1.0;
        for (double c : coeffs) {
            result += c * xPower;
            xPower *= x;
        }
        return result;
    }

    // Helper method to evaluate derivative at x
    private double polyDerivativeValue(List<Double> coeffs, double x) {
        if (coeffs.size() <= 1) {
            return 0.0;
        }

        double result = 0.0;
        double xPower = 1.0;
        for (int i = 1; i < coeffs.size(); i++) {
            result += i * coeffs.get(i) * xPower;
            xPower *= x;
        }
        return result;
    }

    // Bisection method as fallback
    private double bisection(List<Double> coeffs, double left, double right) {
        double fLeft = polyValue(coeffs, left);
        double fRight = polyValue(coeffs, right);

        // Ensure we have opposite signs
        if (fLeft * fRight > 0) {
            // Try wider bounds
            for (int attempt = 0; attempt < 5; attempt++) {
                left *= 2;
                right *= 2;
                fLeft = polyValue(coeffs, left);
                fRight = polyValue(coeffs, right);
                if (fLeft * fRight <= 0) break;
            }
            if (fLeft * fRight > 0) {
                return left; // give up, just return left bound
            }
        }

        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2.0;
            double fMid = polyValue(coeffs, mid);

            if (Math.abs(fMid) < 1e-10 || (right - left) < 1e-10) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

