class Solution {
    /**
     * takes as input string encoded with encodeCyclic function. Returns decoded string.
     */
    public String decodeCyclic(String s) {
        // split string to groups. Each of length 3.
        List<String> groups = new ArrayList<>();
        for (int i = 0; i < s.length(); i += 3) {
            groups.add(s.substring(i, Math.min(i + 3, s.length())));
        }

        // reverse the cycling operation: move last char to front for groups of length 3
        for (int i = 0; i < groups.size(); i++) {
            if (groups.get(i).length() == 3) {
                String group = groups.get(i);
                groups.set(i, group.charAt(2) + group.substring(0, 2));
            }
        }

        return String.join("", groups);
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 1, b = 1; // First two Fibonacci numbers

        // We need to check Fibonacci numbers starting from F(3) = 2
        while (true) {
            int next = a + b;
            a = b;
            b = next;

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }

            // Safety check to prevent overflow for very large numbers
            if (next < 0) {
                throw new ArithmeticException("Fibonacci number overflow");
            }
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        int sqrt = (int) Math.sqrt(num);
        for (int i = 3; i <= sqrt; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

