class Solution {
    /**
    Test if given string is a palindrome
     */
    public boolean isPalindrome(String string) {
        int i = 0;
        int j = string.length() - 1;
        while (i < j) {
            if (string.charAt(i) != string.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    /**
    Find the shortest palindrome that begins with a supplied string.
    Algorithm idea is simple:
    - Find the longest postfix of supplied string that is a palindrome.
    - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
    >>> makePalindrome("")
    ""
    >>> makePalindrome("cat")
    "catac"
    >>> makePalindrome("cata")
    "catac"
     */
    public String makePalindrome(String string) {
        if (string == null || string.length() <= 1) {
            return string;
        }

        // Find the longest palindromic suffix
        int n = string.length();
        int longestPalindromicSuffixStart = 0;

        // Start from the beginning of the string and check each possible suffix
        // We want the longest palindromic suffix, so we check from left to right
        // and keep updating when we find a palindromic suffix
        for (int i = 0; i < n; i++) {
            if (isPalindrome(string.substring(i))) {
                longestPalindromicSuffixStart = i;
                break; // First (leftmost) palindrome found is the longest
            }
        }

        // Get the prefix that comes before the palindromic suffix
        String prefix = string.substring(0, longestPalindromicSuffixStart);
        String palindromicSuffix = string.substring(longestPalindromicSuffixStart);

        // Append reverse of prefix to the end
        String reversedPrefix = new StringBuilder(prefix).reverse().toString();
        return string + reversedPrefix;
    }
}

