class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Handle edge cases
        if (string == null || substring == null) {
            return 0;
        }

        // If substring is empty, return 0 as per the first example
        if (substring.isEmpty()) {
            return 0;
        }

        // If string is empty or shorter than substring, no matches possible
        if (string.isEmpty() || string.length() < substring.length()) {
            return 0;
        }

        int count = 0;
        int stringLen = string.length();
        int subLen = substring.length();

        // Check each possible starting position
        for (int i = 0; i <= stringLen - subLen; i++) {
            // Check if substring matches at position i
            boolean match = true;
            for (int j = 0; j < subLen; j++) {
                if (string.charAt(i + j) != substring.charAt(j)) {
                    match = false;
                    break;
                }
            }
            if (match) {
                count++;
            }
        }

        return count;
    }
}

