import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Use Horner's method for efficiency and numerical stability
        double result = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        int n = xs.size();
        if (n == 0) return 0;

        // Handle linear case directly: a + bx = 0 => x = -a/b
        if (n == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) < 1e-12) {
                // No solution or infinite solutions; return 0 as fallback
                return 0;
            }
            return -a / b;
        }

        // Newton-Raphson method
        double x = 1.0; // Initial guess
        for (int i = 0; i < 100; i++) { // Max iterations
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative: f'(x)
            double dfx = 0;
            for (int j = 1; j < n; j++) {
                dfx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            // Avoid division by zero
            if (Math.abs(dfx) < 1e-12) {
                // Perturb x slightly and try again
                x += 0.1;
                continue;
            }

            double xNext = x - fx / dfx;

            // Check for convergence
            if (Math.abs(xNext - x) < 1e-12) {
                break;
            }

            x = xNext;
        }

        return x;
    }
}

