class Solution {
    public double findZero(List<Double> xs) {
        // Use bisection method with adaptive bound searching

        // First, handle edge cases
        if (xs.isEmpty()) {
            return 0.0;
        }

        // Define the polynomial evaluation function
        java.util.function.DoubleUnaryOperator f = x -> poly(xs, x);

        // Find a suitable interval [a, b] where f(a) * f(b) < 0
        double a = -1.0;
        double b = 1.0;
        double fa = f.applyAsDouble(a);
        double fb = f.applyAsDouble(b);

        // Expand interval until we find sign change
        int iterations = 0;
        final int MAX_ITERATIONS = 100;
        while (fa * fb > 0 && iterations < MAX_ITERATIONS) {
            if (Math.abs(fa) < Math.abs(fb)) {
                a *= 2;
                fa = f.applyAsDouble(a);
            } else {
                b *= 2;
                fb = f.applyAsDouble(b);
            }
            iterations++;
        }

        // If still no sign change, try larger bounds
        if (fa * fb > 0) {
            a = -1000.0;
            b = 1000.0;
            fa = f.applyAsDouble(a);
            fb = f.applyAsDouble(b);
        }

        // Bisection method
        final double TOLERANCE = 1e-9;
        int maxSteps = 100;
        for (int i = 0; i < maxSteps; i++) {
            double mid = (a + b) / 2;
            double fm = f.applyAsDouble(mid);

            if (Math.abs(fm) < TOLERANCE || (b - a) / 2 < TOLERANCE) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2;
    }
}

