class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // All other even numbers are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge case: constant polynomial (shouldn't happen per problem constraints)
        if (xs.size() <= 1) {
            return 0.0;
        }

        // Bisection method parameters
        double left = -1000.0;
        double right = 1000.0;
        double tolerance = 1e-9;
        int maxIterations = 1000;

        // Find an interval where the function changes sign
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If we don't have a sign change, try expanding the interval
        int expansionAttempts = 0;
        while (fLeft * fRight > 0 && expansionAttempts < 20) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            expansionAttempts++;
        }

        // Bisection method
        for (int i = 0; i < maxIterations; i++) {
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            // Check if we've found a root (within tolerance)
            if (Math.abs(fMid) < tolerance) {
                return mid;
            }

            // Check if interval is small enough
            if (Math.abs(right - left) < tolerance) {
                return mid;
            }

            // Decide which half to keep
            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return best approximation after max iterations
        return (left + right) / 2.0;
    }
}

