class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Handle small cases directly for efficiency
        if (n == 1) return 2;
        if (n == 2) return 3;
        if (n == 3) return 5;
        if (n == 4) return 13;
        if (n == 5) return 89;

        // Start generating Fibonacci numbers from F(6) = 8 onwards
        long prev2 = 3; // F(4) = 3
        long prev1 = 5; // F(5) = 5
        int count = 3;  // We already counted 2, 3, 5

        while (count < n) {
            long current = prev2 + prev1;

            // Skip even numbers (except 2) - they can't be prime
            if (current > 2 && current % 2 == 0) {
                prev2 = prev1;
                prev1 = current;
                continue;
            }

            if (isPrime(current)) {
                count++;
                if (count == n) {
                    return (int) current;
                }
            }

            prev2 = prev1;
            prev1 = current;
        }

        // This shouldn't be reached if n >= 1
        return -1;
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

