     * This method is <b>not thread-safe</b>. If multiple threads access the result
     * list concurrently, and at least one of the threads modifies the list structurally,
     * it must be synchronized externally. Structural modifications include adding or
     * removing elements, but not merely changing the contents of the strings themselves.
     *
     * @param strings the list of strings to filter (may be null or empty)
     * @param substring the substring to search for (may be null or empty)
     * @return a new list containing only strings that contain the substring
     * @throws NullPointerException if the input list is null
     */
    public List<String> filterBySubstring(List<String> strings, String substring) {
        // Handle null input list
        if (strings == null) {
            throw new NullPointerException("Input list cannot be null");
        }

        // Create result list
        List<String> result = new ArrayList<>();

        // Handle null or empty substring - if substring is null or empty, 
        // we could either return all strings or none. Based on typical behavior,
        // an empty substring should match everything, but let's check the examples.
        // From the examples, we can infer that we're looking for literal substring matches.

        if (substring == null) {
            // If substring is null, no strings can contain it
            return result;
        }

        // Iterate through each string and check if it contains the substring
        for (String str : strings) {
            // Skip null strings to avoid NullPointerException
            if (str != null && str.contains(substring)) {
                result.add(str);
            }
        }

        return result;
    }
}

