     * @param numbers the input list of integers; may be null or empty
     * @return a list where each element at index i is the maximum value among the first i+1 elements
     *         of the input list; returns an empty list if input is empty or null
     */
    public List<Integer> rollingMax(List<Integer> numbers) {
        // Handle null input
        if (numbers == null) {
            return new ArrayList<>();
        }

        // Handle empty input
        if (numbers.isEmpty()) {
            return new ArrayList<>();
        }

        List<Integer> result = new ArrayList<>(numbers.size());
        int currentMax = Integer.MIN_VALUE;

        for (Integer num : numbers) {
            // Update current maximum (handle null values in the list)
            if (num != null && num > currentMax) {
                currentMax = num;
            } else if (currentMax == Integer.MIN_VALUE && num != null) {
                currentMax = num;
            }
            result.add(currentMax);
        }

        return result;
    }
}

