class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For linear case (2 coefficients), solve directly
        if (xs.size() == 2) {
            // f(x) = xs[0] + xs[1]*x = 0 => x = -xs[0]/xs[1]
            return -xs.get(0) / xs.get(1);
        }

        // For higher degrees, use Newton-Raphson method
        double x = 0.0; // starting point
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);

            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Calculate derivative using finite differences or analytical
            // Analytical derivative: for polynomial sum(a_i * x^i), derivative is sum(i * a_i * x^(i-1))
            double fpx = derivative(xs, x);

            if (Math.abs(fpx) < 1e-15) {
                // Derivative too small, try small perturbation
                fpx = derivative(xs, x + 1e-8);
                if (Math.abs(fpx) < 1e-15) {
                    x += 0.1; // move a bit and try again
                    continue;
                }
            }

            double xNew = x - fx / fpx;

            if (Double.isNaN(xNew) || Double.isInfinite(xNew)) {
                x += 0.1;
                continue;
            }

            if (Math.abs(xNew - x) < tolerance) {
                return xNew;
            }

            x = xNew;
        }

        // Fallback: return last computed value
        return x;
    }

    private double derivative(List<Double> coeffs, double x) {
        if (coeffs.size() <= 1) {
            return 0;
        }

        double result = 0;
        for (int i = 1; i < coeffs.size(); i++) {
            result += i * coeffs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

