class Solution {
    /**
     * Check if in given list of numbers, are any two numbers closer to each other than given threshold.
     * <p>
     * This method is thread-safe if the input list is not modified during execution.
     * The method creates a copy of the list internally, so modifications to the original
     * list after the method returns do not affect the result.
     *
     * @param numbers the list of numbers to check
     * @param threshold the minimum distance threshold (exclusive)
     * @return true if any two numbers are closer than threshold, false otherwise
     * @throws NullPointerException if numbers is null
     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        if (numbers == null) {
            throw new NullPointerException("Input list cannot be null");
        }

        // If threshold is negative, no two numbers can be "closer" than a negative distance
        if (threshold < 0) {
            return false;
        }

        // Need at least 2 elements to compare
        if (numbers.size() < 2) {
            return false;
        }

        // Create a copy to avoid modifying the original list
        List<Double> sortedNumbers = new ArrayList<>(numbers);
        Collections.sort(sortedNumbers);

        // Check adjacent pairs only (most efficient for sorted list)
        for (int i = 0; i < sortedNumbers.size() - 1; i++) {
            double diff = Math.abs(sortedNumbers.get(i + 1) - sortedNumbers.get(i));
            if (diff < threshold) {
                return true;
            }
        }

        return false;
    }
}

