class Solution {
    /**
     * Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
     * separate those groups into separate strings and return the list of those.
     * Separate groups are balanced (each open brace is properly closed) and not nested within each other
     * Ignore any spaces in the input string.
     *
     * @param paren_string String containing multiple groups of parentheses separated by spaces
     * @return List of balanced parenthesis groups as separate strings
     * 
     * Example:
     * separateParenGroups("( ) (( )) (( )( ))") returns ["()", "(())", "(()())"]
     */
    public List<String> separateParenGroups(String paren_string) {
        List<String> result = new ArrayList<>();

        // Remove all spaces from the input
        String cleanString = paren_string.replace(" ", "");

        int nestingLevel = 0;
        StringBuilder currentGroup = new StringBuilder();

        for (int i = 0; i < cleanString.length(); i++) {
            char c = cleanString.charAt(i);

            if (c == '(') {
                // Start or continue a group
                currentGroup.append(c);
                nestingLevel++;
            } else if (c == ')') {
                // End current group if nesting level becomes 0 after this
                currentGroup.append(c);
                nestingLevel--;

                // If we've completed a balanced group (nesting level back to 0)
                if (nestingLevel == 0) {
                    result.add(currentGroup.toString());
                    currentGroup.setLength(0); // Reset for next group
                }
            }
        }

        return result;
    }
}

