class Solution {
    /**
     * For a given list of input numbers, calculate Mean Absolute Deviation
     * around the mean of this dataset.
     * <p>
     * Mean Absolute Deviation is the average absolute difference between each
     * element and the mean of the dataset.
     * <p>
     * This method is thread-safe as it does not maintain any shared mutable state.
     *
     * @param numbers the list of numbers to calculate MAD for (must not be null or empty)
     * @return the Mean Absolute Deviation as a double
     * @throws IllegalArgumentException if the input list is null or empty
     *
     * Example:
     * <pre>{@code
     * meanAbsoluteDeviation(Arrays.asList(1.0, 2.0, 3.0, 4.0)) // returns 1.0
     * }</pre>
     */
    public double meanAbsoluteDeviation(List<Double> numbers) {
        // Validate input
        if (numbers == null || numbers.isEmpty()) {
            throw new IllegalArgumentException("Input list cannot be null or empty");
        }

        // Calculate the mean
        double sum = 0.0;
        for (Double num : numbers) {
            if (num == null) {
                throw new IllegalArgumentException("List cannot contain null values");
            }
            sum += num;
        }
        double mean = sum / numbers.size();

        // Calculate the mean absolute deviation
        double madSum = 0.0;
        for (Double num : numbers) {
            madSum += Math.abs(num - mean);
        }

        return madSum / numbers.size();
    }
}

