class Solution {
    /**
     * Returns true if a given number is prime, and false otherwise.
     * <p>
     * This method is <b>thread-safe</b>: it has no shared mutable state and
     * produces consistent results across concurrent invocations.
     *
     * @param n the number to test for primality
     * @return true if n is prime, false otherwise
     * @implSpec
     * The implementation checks divisibility by 2 and then by odd numbers
     * from 3 to sqrt(n), running in O(sqrt(n)) time.
     * @implNote
     * Negative numbers, 0, and 1 are not considered prime.
     * <p>
     * Examples:
     * <ul>
     *   <li>{@code isPrime(6)} returns {@code false}</li>
     *   <li>{@code isPrime(101)} returns {@code true}</li>
     *   <li>{@code isPrime(11)} returns {@code true}</li>
     *   <li>{@code isPrime(13441)} returns {@code true}</li>
     *   <li>{@code isPrime(61)} returns {@code true}</li>
     *   <li>{@code isPrime(4)} returns {@code false}</li>
     *   <li>{@code isPrime(1)} returns {@code false}</li>
     * </ul>
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge case: constant polynomial (degree 0)
        if (xs.size() == 1) {
            return 0.0; // This shouldn't happen per problem constraints, but be safe
        }

        // Find the highest non-zero coefficient (leading term)
        int degree = xs.size() - 1;
        double leadingCoeff = xs.get(degree);
        for (int i = degree; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) {
                leadingCoeff = xs.get(i);
                break;
            }
        }

        // Since we have even number of coefficients, degree is odd, so polynomial has at least one real root
        // Find bounds where polynomial changes sign
        double left = -1.0;
        double right = 1.0;

        // Expand search range until we find sign change
        while (true) {
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            if (fLeft == 0) return left;
            if (fRight == 0) return right;
            if (fLeft * fRight < 0) break; // Sign change found

            // Expand the range
            left *= 2;
            right *= 2;

            // Safety check to prevent infinite loop
            if (Math.abs(left) > 1e9) {
                // Fallback: use Newton's method starting from 0
                return newtonRaphson(xs, 0.0);
            }
        }

        // Bisection method
        for (int iter = 0; iter < 100; iter++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            double fLeft = poly(xs, left);
            if (fLeft * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Return midpoint after iterations
        return (left + right) / 2;
    }

    // Helper method for Newton-Raphson fallback
    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 50; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-9) return x;

            // Compute derivative
            double fpx = 0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(fpx) < 1e-12) {
                // Derivative too small, try a small perturbation
                x += 0.1;
                continue;
            }

            x = x - fx / fpx;

            if (Double.isNaN(x) || Double.isInfinite(x)) {
                x = (x0 + x) / 2; // Backup approach
            }
        }
        return x;
    }
}

