     * @throws NoSuchElementException if the list is empty
     * @throws NullPointerException if the list or any element is null
     * 
     * <p>This method is <b>thread-safe</b> with respect to the method call itself,
     * but does not provide atomicity for compound operations on the list.
     * If the list is structurally modified by other threads during execution,
     * the behavior is undefined. For concurrent access to a shared list,
     * external synchronization is recommended.
     * 
     * <p>Examples:
     * <pre>{@code
     * maxElement(Arrays.asList(1, 2, 3))  // returns 3
     * maxElement(Arrays.asList(5, 3, -5, 2, -3, 3, 9, 0, 123, 1, -10))  // returns 123
     * }</pre>
     */
    public int maxElement(List<Integer> l) {
        if (l == null) {
            throw new NullPointerException("List cannot be null");
        }

        if (l.isEmpty()) {
            throw new NoSuchElementException("List cannot be empty");
        }

        int max = l.get(0);
        for (int i = 1; i < l.size(); i++) {
            Integer value = l.get(i);
            if (value == null) {
                throw new NullPointerException("List elements cannot be null");
            }
            if (value > max) {
                max = value;
            }
        }
        return max;
    }
}

