class Solution {
    /**
     * Return the number of times the digit 7 appears in integers less than n 
     * which are divisible by 11 or 13.
     * 
     * Examples:
     * >>> fizzBuzz(50)
     * 0
     * >>> fizzBuzz(78)
     * 2
     * >>> fizzBuzz(79)
     * 3
     * 
     * @param n the upper bound (exclusive)
     * @return the count of digit 7 occurrences in qualifying numbers
     */
    public int fizzBuzz(int n) {
        int count = 0;

        for (int i = 1; i < n; i++) {
            // Check if divisible by 11 or 13
            if (i % 11 == 0 || i % 13 == 0) {
                // Count occurrences of '7' in the number
                int num = i;
                while (num > 0) {
                    if (num % 10 == 7) {
                        count++;
                    }
                    num /= 10;
                }
            }
        }

        return count;
    }
}

