    >>> intersperse(Arrays.asList(1, 2, 3), 4)
    [1, 4, 2, 4, 3]
     */
    public List<Integer> intersperse(List<Integer> numbers, int delimiter) {
        // Handle null input
        if (numbers == null) {
            return new ArrayList<>();
        }

        int n = numbers.size();

        // Handle empty list
        if (n == 0) {
            return new ArrayList<>();
        }

        // Handle single element list
        if (n == 1) {
            return new ArrayList<>(numbers);
        }

        // Create result list with expected capacity
        List<Integer> result = new ArrayList<>(2 * n - 1);

        // Add first element
        result.add(numbers.get(0));

        // Add remaining elements with delimiter between them
        for (int i = 1; i < n; i++) {
            result.add(delimiter);
            result.add(numbers.get(i));
        }

        return result;
    }
}

