    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true;  // 2 and 3 are prime
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check for divisors from 5 up to sqrt(n)
        // Use the 6k ± 1 optimization: all primes > 3 are of form 6k±1
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Tolerance for convergence
        final double EPSILON = 1e-9;
        final int MAX_ITERATIONS = 1000;

        // Define polynomial evaluation helper
        java.util.function.DoubleUnaryOperator polyEval = x -> poly(xs, x);

        // Find interval with sign change by expanding
        double left = -1.0;
        double right = 1.0;
        double fLeft = polyEval.applyAsDouble(left);
        double fRight = polyEval.applyAsDouble(right);

        // Expand until sign change
        int expansions = 0;
        while (fLeft * fRight >= 0 && expansions < 100) {
            left *= 2;
            right *= 2;
            fLeft = polyEval.applyAsDouble(left);
            fRight = polyEval.applyAsDouble(right);
            expansions++;
        }

        // If still no sign change, fallback to Newton or assume 0 (shouldn't happen per problem guarantee)
        if (fLeft * fRight > 0) {
            // Fallback: try Newton's method starting at 0
            double x = 0.0;
            for (int i = 0; i < MAX_ITERATIONS; i++) {
                double fx = polyEval.applyAsDouble(x);
                if (Math.abs(fx) < EPSILON) {
                    return x;
                }
                // Approximate derivative: f'(x) ≈ (f(x+h) - f(x)) / h
                double h = 1e-7;
                double fpx = (polyEval.applyAsDouble(x + h) - fx) / h;
                if (Math.abs(fpx) < 1e-12) {
                    x += 1.0; // avoid division by zero
                    continue;
                }
                x -= fx / fpx;
            }
            return x;
        }

        // Bisection method
        for (int i = 0; i < MAX_ITERATIONS; i++) {
            double mid = (left + right) / 2.0;
            double fMid = polyEval.applyAsDouble(mid);

            if (Math.abs(fMid) < EPSILON || (right - left) < EPSILON) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint as best guess
        return (left + right) / 2.0;
    }
}

