class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Generate Fibonacci numbers and check if they're prime
        int count = 0;
        long a = 1, b = 1; // First two Fibonacci numbers

        // Handle special case for first few Fibonacci numbers
        // F1=1, F2=1 (not prime), F3=2 (prime), F4=3 (prime), F5=5 (prime), etc.

        // Check F3=2
        if (n == 1) return 2;
        count = 1;

        // Start from F4
        long fib = 3;
        int index = 4;

        while (true) {
            if (isPrime(fib)) {
                count++;
                if (count == n) {
                    return (int) fib;
                }
            }

            // Generate next Fibonacci number
            long next = a + b;
            a = b;
            b = fib;
            fib = next;
            index++;

            // Safety check for potential overflow (though problem constraints likely limit n)
            if (fib > Integer.MAX_VALUE) {
                throw new ArithmeticException("Fibonacci number exceeds integer range");
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0) return false;

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

