class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Edge cases
        if (n <= 1) {
            return -1; // No proper divisors for n <= 1
        }

        // If n is even, largest proper divisor is n/2
        if (n % 2 == 0) {
            return n / 2;
        }

        // For odd numbers, find the smallest divisor
        int smallestDivisor = -1;
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                smallestDivisor = i;
                break;
            }
        }

        // If we found a divisor, largest proper divisor is n/smallestDivisor
        if (smallestDivisor != -1) {
            return n / smallestDivisor;
        }

        // If no divisor found (n is prime), largest proper divisor is 1
        return 1;
    }
}

