        return primeFibs.get(n - 1);
    }

    private void generateNextPrimeFib() {
        // Get the last two Fibonacci numbers we need to continue generation
        // We'll start generating from the beginning if we have no sequence info
        int size = primeFibs.size();

        if (size == 0) {
            // First prime Fibonacci is 2
            primeFibs.add(2);
            return;
        }

        // Find the next Fibonacci number after the last prime Fibonacci we found
        // We need to track the Fibonacci sequence separately
        int lastFoundIndex = findLastFibIndex(primeFibs.get(size - 1));
        int a = getFibonacci(lastFoundIndex);
        int b = getFibonacci(lastFoundIndex + 1);

        // Continue generating Fibonacci numbers until we find the next prime one
        while (true) {
            int nextFib = a + b;
            a = b;
            b = nextFib;

            if (isPrime(nextFib)) {
                primeFibs.add(nextFib);
                return;
            }
        }
    }

    // Helper method to find index of a Fibonacci number in the sequence
    private int findLastFibIndex(int fibNum) {
        if (fibNum == 2) return 3; // 2 is the 3rd Fibonacci number (1,1,2)
        if (fibNum == 3) return 4; // 3 is the 4th
        if (fibNum == 5) return 5;
        if (fibNum == 13) return 7;
        if (fibNum == 89) return 11;

        // Generic approach for larger numbers
        int a = 1, b = 1, idx = 2;
        while (b < fibNum) {
            int temp = a + b;
            a = b;
            b = temp;
            idx++;
        }
        return (b == fibNum) ? idx : -1;
    }

    // Get nth Fibonacci number (1-indexed: F1=1, F2=1, F3=2, etc.)
    private int getFibonacci(int n) {
        if (n <= 0) return 0;
        if (n == 1 || n == 2) return 1;

        int a = 1, b = 1;
        for (int i = 3; i <= n; i++) {
            int temp = a + b;
            a = b;
            b = temp;
        }
        return b;
    }

    // Check if a number is prime
    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

