class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Use Horner's method for efficiency and numerical stability
        double result = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle degenerate cases
        if (xs.isEmpty()) return 0;

        // Try simple values first (common roots are often 0, 1, -1)
        for (double test : new double[]{0, 1, -1, 2, -2, 0.5, -0.5}) {
            if (Math.abs(poly(xs, test)) < 1e-10) {
                return test;
            }
        }

        // Newton-Raphson method
        double x = 1.0; // initial guess
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative using finite difference (or analytically)
            // For simplicity, use numerical derivative
            double h = 1e-8;
            double fpx = (poly(xs, x + h) - poly(xs, x - h)) / (2 * h);

            if (Math.abs(fpx) < 1e-12) {
                // Derivative too small, try different initial guess
                x = (Math.random() - 0.5) * 10;
                continue;
            }

            double xNew = x - fx / fpx;

            // Check for convergence or overflow
            if (Double.isNaN(xNew) || Double.isInfinite(xNew)) {
                x = (Math.random() - 0.5) * 10;
                continue;
            }

            if (Math.abs(xNew - x) < 1e-12) {
                return xNew;
            }

            x = xNew;
        }

        // Fallback: return last computed value
        return x;
    }
}

