class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Newton's method: x_{n+1} = x_n - f(x_n) / f'(x_n)

        // Start with a reasonable initial guess
        double x = 0.0;

        // Handle edge case: constant polynomial (shouldn't happen per constraints, but be safe)
        if (xs.size() <= 1) {
            return 0.0;
        }

        // Newton's method iterations
        for (int i = 0; i < 100; i++) { // sufficient iterations for convergence
            double fx = poly(xs, x);

            // Check if we're close enough to a root
            if (Math.abs(fx) < 1e-9) {
                return x;
            }

            // Compute derivative: f'(x) = sum_{j=1}^{n} j * xs[j] * x^{j-1}
            double fpx = 0.0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-12) {
                // If derivative is too small, try a different starting point
                x = (i % 2 == 0) ? x + 1.0 : x - 1.0;
                continue;
            }

            double nextX = x - fx / fpx;

            // Check for divergence or NaN
            if (Double.isNaN(nextX) || Double.isInfinite(nextX)) {
                x = (i % 2 == 0) ? x + 1.0 : x - 1.0;
            } else {
                x = nextX;
            }
        }

        // Fallback: return last computed value (should be close to root)
        return x;
    }
}

