class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int fib1 = 0;  // F(0)
        int fib2 = 1;  // F(1)

        // Handle special case: F(1) = 1 is not prime, F(2) = 1 is not prime
        // Start generating from F(3) = 2 onwards

        // Check F(3) = 2
        if (n == 1) return 2;

        int currentFib = 2;  // F(3)
        count = 1;

        // If we already found the nth one
        if (count == n) return currentFib;

        // Generate Fibonacci numbers starting from F(4) = 3
        int prevFib = 3;  // F(4)

        while (true) {
            // Check if current Fibonacci number is prime
            if (isPrime(prevFib)) {
                count++;
                if (count == n) {
                    return prevFib;
                }
            }

            // Generate next Fibonacci number
            int nextFib = currentFib + prevFib;
            currentFib = prevFib;
            prevFib = nextFib;
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

