class Solution {
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Use Horner's method for better numerical stability and efficiency
        double result = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For odd-degree polynomials (even number of coefficients), we know at least one real root exists
        int n = xs.size();

        // Handle edge cases
        if (n == 2) {
            // Linear case: a + bx = 0 => x = -a/b
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) > 1e-12) {
                return -a / b;
            }
        }

        // Newton-Raphson method with multiple starting points
        double x = 0.0;
        double tolerance = 1e-10;
        int maxIterations = 1000;

        // Try multiple starting points
        double[] startingPoints = {0.0, 1.0, -1.0, 10.0, -10.0, 100.0, -100.0, 0.5, -0.5};

        for (double start : startingPoints) {
            double currentX = start;
            for (int iter = 0; iter < maxIterations; iter++) {
                double fx = poly(xs, currentX);
                if (Math.abs(fx) < tolerance) {
                    return currentX;
                }

                // Compute derivative numerically
                double h = 1e-8;
                double fpx = (poly(xs, currentX + h) - fx) / h;

                if (Math.abs(fpx) < 1e-12) {
                    // Derivative too small, try next starting point
                    break;
                }

                double nextX = currentX - fx / fpx;

                // Check for divergence
                if (Double.isNaN(nextX) || Double.isInfinite(nextX) || 
                    Math.abs(nextX - currentX) > 1e6) {
                    break;
                }

                currentX = nextX;
            }
        }

        // Fallback: bisection method over a large interval
        // Since it's odd degree, lim(x->+inf) = ±inf and lim(x->-inf) = ∓inf, so we can find signs
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If signs are different, bisection will work
        if (fLeft * fRight < 0) {
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);
                if (Math.abs(fMid) < tolerance) {
                    return mid;
                }
                if (fLeft * fMid < 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
            return (left + right) / 2;
        }

        // Last resort: return midpoint of search range
        return 0.0;
    }
}

