class Solution {
    /**
    Return sorted unique elements in a list
    >>> unique(Arrays.asList(5, 3, 5, 2, 3, 3, 9, 0, 123))
    [0, 2, 3, 5, 9, 123]
     */
    public List<Integer> unique(List<Integer> l) {
        // Handle null input
        if (l == null) {
            return new ArrayList<>();
        }

        // Use a TreeSet to automatically remove duplicates and sort
        // TreeSet provides O(n log n) time complexity and removes duplicates
        Set<Integer> set = new TreeSet<>(l);

        // Convert back to a List
        return new ArrayList<>(set);
    }
}

