class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Validate input: must have even number of coefficients
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Check if leading coefficient (largest non-zero) is non-zero
        int n = xs.size() - 1;
        while (n >= 0 && xs.get(n) == 0) {
            n--;
        }
        if (n < 0 || xs.get(n) == 0) {
            throw new IllegalArgumentException("All coefficients are zero");
        }

        // Use Newton-Raphson method to find a root
        // Start with initial guess
        double x = 1.0;
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);

            // Check if we've found a root
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative: f'(x)
            double fPrimeX = 0;
            for (int j = 1; j < xs.size(); j++) {
                fPrimeX += j * xs.get(j) * Math.pow(x, j - 1);
            }

            // Avoid division by zero
            if (Math.abs(fPrimeX) < tolerance) {
                // Slightly perturb x if derivative is too small
                x += 0.01;
                continue;
            }

            // Newton-Raphson update: x_new = x - f(x)/f'(x)
            x = x - fx / fPrimeX;

            // Check for convergence
            if (Math.abs(fx / fPrimeX) < tolerance) {
                return x;
            }
        }

        // If we didn't converge, return the best estimate
        return x;
    }
}

