class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Validate inputs - though problem states they contain only 0s and 1s
        if (a == null || b == null || a.length() != b.length()) {
            throw new IllegalArgumentException("Input strings must be non-null and of equal length");
        }

        StringBuilder result = new StringBuilder();

        for (int i = 0; i < a.length(); i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            // XOR: same bits give 0, different bits give 1
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

