class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Binary search for root
        double low = -1000.0;
        double high = 1000.0;

        // Ensure we have opposite signs at bounds
        // For odd-degree polynomial, as x->+inf, sign depends on leading coefficient
        // as x->-inf, sign is opposite (since degree is odd)
        double leftVal = poly(xs, low);
        double rightVal = poly(xs, high);

        // If same sign, expand the search range
        int iterations = 0;
        while (leftVal * rightVal > 0 && iterations < 30) {
            low *= 10;
            high *= 10;
            leftVal = poly(xs, low);
            rightVal = poly(xs, high);
            iterations++;
        }

        // Binary search
        for (int i = 0; i < 100; i++) { // 100 iterations for precision
            double mid = (low + high) / 2.0;
            double midVal = poly(xs, mid);

            if (Math.abs(midVal) < 1e-9) {
                return mid;
            }

            if (leftVal * midVal <= 0) {
                high = mid;
                rightVal = midVal;
            } else {
                low = mid;
                leftVal = midVal;
            }
        }

        return (low + high) / 2.0;
    }
}

