class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) return -1;

        int count = 0;
        int a = 0; // F(0)
        int b = 1; // F(1)

        // Check F(0) = 0 - not prime
        // Check F(1) = 1 - not prime
        // Start from F(2) = 1, but we know F(2) = 1 is not prime

        // Generate Fibonacci numbers starting from F(2)
        while (count < n) {
            int next = a + b;
            a = b;
            b = next;

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return next;
                }
            }
        }

        return -1; // Should not reach here with valid input
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }

        return true;
    }
}

