class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Ensure both strings have the same length by padding the shorter one with leading zeros
        int maxLen = Math.max(a.length(), b.length());

        // Pad both strings to the same length with leading zeros
        StringBuilder aPadded = new StringBuilder();
        for (int i = 0; i < maxLen - a.length(); i++) {
            aPadded.append('0');
        }
        aPadded.append(a);

        StringBuilder bPadded = new StringBuilder();
        for (int i = 0; i < maxLen - b.length(); i++) {
            bPadded.append('0');
        }
        bPadded.append(b);

        StringBuilder result = new StringBuilder();

        // Perform XOR bit by bit
        for (int i = 0; i < maxLen; i++) {
            char bitA = aPadded.charAt(i);
            char bitB = bPadded.charAt(i);

            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

