class Solution {
    public double findZero(List<Double> xs) {
            // Use bisection method
            // First, evaluate the polynomial at some points to find an interval with sign change

            // Get the degree (highest power) - since xs has even number of coefficients,
            // the degree is xs.size() - 1, which is odd
            int degree = xs.size() - 1;

            // Try to find an interval [a, b] where f(a) * f(b) < 0
            double a = -1000.0;
            double b = 1000.0;

            double fa = poly(xs, a);
            double fb = poly(xs, b);

            // If we're lucky and one endpoint is already a root
            if (Math.abs(fa) < 1e-9) return a;
            if (Math.abs(fb) < 1e-9) return b;

            // Expand search range if needed (in case both values have same sign due to limited range)
            int attempts = 0;
            while (fa * fb > 0 && attempts < 30) {
                a *= 10;
                b *= 10;
                fa = poly(xs, a);
                fb = poly(xs, b);
                attempts++;
            }

            // Bisection method
            for (int i = 0; i < 100; i++) { // 100 iterations for high precision
                double mid = (a + b) / 2.0;
                double fm = poly(xs, mid);

                if (Math.abs(fm) < 1e-9) {
                    return mid;
                }

                if (fa * fm <= 0) {
                    b = mid;
                    fb = fm;
                } else {
                    a = mid;
                    fa = fm;
                }
            }

            return (a + b) / 2.0;
        }
}

