class Solution {
    public double findZero(List<Double> xs) {
        // For linear case: ax + b = 0 => x = -b/a
        if (xs.size() == 2) {
            double a = xs.get(1);
            double b = xs.get(0);
            return -b / a;
        }

        // Bisection method with interval expansion
        double low = -100.0;
        double high = 100.0;
        double fLow = poly(xs, low);
        double fHigh = poly(xs, high);

        // Expand interval until we get sign change
        int iterations = 0;
        while (fLow * fHigh > 0 && iterations < 100) {
            low *= 2;
            high *= 2;
            fLow = poly(xs, low);
            fHigh = poly(xs, high);
            iterations++;
        }

        // Now bisection
        double mid;
        for (int i = 0; i < 100; i++) { // enough iterations for double precision
            mid = (low + high) / 2.0;
            double fMid = poly(xs, mid);
            if (Math.abs(fMid) < 1e-9 || (high - low) < 1e-9) {
                return mid;
            }
            if (fLow * fMid < 0) {
                high = mid;
                fHigh = fMid;
            } else {
                low = mid;
                fLow = fMid;
            }
        }
        return (low + high) / 2.0;
    }
}

