class Solution {
    /**
    For a given list of input numbers, calculate Mean Absolute Deviation
    around the mean of this dataset.
    Mean Absolute Deviation is the average absolute difference between each
    element and a centerpoint (mean in this case):
    MAD = average | x - x_mean |
    >>> meanAbsoluteDeviation(Arrays.asList(1.0, 2.0, 3.0, 4.0))
    1.0
     */
    public double meanAbsoluteDeviation(List<Double> numbers) {
        if (numbers == null || numbers.isEmpty()) {
            return 0.0;
        }

        // Calculate the mean
        double sum = 0.0;
        for (Double num : numbers) {
            sum += num;
        }
        double mean = sum / numbers.size();

        // Calculate the sum of absolute deviations from the mean
        double totalDeviation = 0.0;
        for (Double num : numbers) {
            totalDeviation += Math.abs(num - mean);
        }

        // Return the average of absolute deviations
        return totalDeviation / numbers.size();
    }
}

