    [0.0, 0.25, 0.5, 0.75, 1.0]
     */
    public List<Double> rescaleToUnit(List<Double> numbers) {
        if (numbers == null || numbers.isEmpty()) {
            return new ArrayList<>();
        }

        // Find min and max values
        double min = Double.MAX_VALUE;
        double max = Double.MIN_VALUE;

        for (Double num : numbers) {
            if (num != null) {
                min = Math.min(min, num);
                max = Math.max(max, num);
            }
        }

        // Calculate the range
        double range = max - min;

        // Create result list
        List<Double> result = new ArrayList<>();

        // Handle edge case where all values are the same (range = 0)
        if (range == 0) {
            // If all values are identical, map them all to 0.0 (or could be 0.5, but 0.0 is standard)
            for (int i = 0; i < numbers.size(); i++) {
                result.add(0.0);
            }
        } else {
            // Apply the rescaling formula: (value - min) / (max - min)
            for (Double num : numbers) {
                if (num != null) {
                    result.add((num - min) / range);
                } else {
                    result.add(null); // Preserve nulls if present
                }
            }
        }

        return result;
    }
}

