class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: constant polynomial (degree 0)
        if (xs.size() == 1) {
            return 0.0; // or throw exception, but problem says even number of coefficients
        }

        // Find the degree (highest non-zero coefficient)
        int degree = xs.size() - 1;

        // For bisection method, we need an interval [a, b] where f(a) * f(b) < 0

        // Try to find appropriate bounds
        double a = -100.0;
        double b = 100.0;

        // Expand bounds until we find opposite signs
        while (poly(xs, a) * poly(xs, b) > 0) {
            a *= 2;
            b *= 2;
            // Safety limit to prevent infinite loop
            if (Math.abs(a) > 1e6) {
                break;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives good precision
            double mid = (a + b) / 2;
            double fmid = poly(xs, mid);

            if (Math.abs(fmid) < 1e-12) {
                return mid;
            }

            double fa = poly(xs, a);
            if (fa * fmid < 0) {
                b = mid;
            } else {
                a = mid;
            }
        }

        return (a + b) / 2;
    }
}

