class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Handle null cases
        if (a == null || b == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        // Ensure both strings have the same length by padding the shorter one with leading zeros
        int maxLen = Math.max(a.length(), b.length());
        StringBuilder aBuilder = new StringBuilder(a);
        StringBuilder bBuilder = new StringBuilder(b);

        while (aBuilder.length() < maxLen) {
            aBuilder.insert(0, '0');
        }
        while (bBuilder.length() < maxLen) {
            bBuilder.insert(0, '0');
        }

        a = aBuilder.toString();
        b = bBuilder.toString();

        StringBuilder result = new StringBuilder();

        for (int i = 0; i < a.length(); i++) {
            char bitA = a.charAt(i);
            char bitB = b.charAt(i);

            // XOR: same bits give 0, different bits give 1
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

