class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method with multiple starting points
        // Since polynomial has odd degree (even number of coefficients), there's at least one real root

        // Try multiple starting points and return first successful root
        double[] starters = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0, 100.0, -100.0};

        for (double start : starters) {
            double root = newtonRaphson(xs, start);
            if (!Double.isNaN(root) && !Double.isInfinite(root)) {
                // Verify it's actually a root (within tolerance)
                double value = poly(xs, root);
                if (Math.abs(value) < 1e-6) {
                    return root;
                }
            }
        }

        // Fallback: binary search / bisection approach
        // Since odd degree polynomial goes from -inf to +inf or vice versa
        double left = -1000.0;
        double right = 1000.0;

        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Make sure we have opposite signs
        while (fLeft > 0 && fRight > 0) {
            left *= 2;
            fLeft = poly(xs, left);
            if (left < -1e6) break;
        }
        while (fLeft < 0 && fRight < 0) {
            right *= 2;
            fRight = poly(xs, right);
            if (right > 1e6) break;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);
            if (Math.abs(fMid) < 1e-10 || (right - left) < 1e-10) {
                return mid;
            }
            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }

    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 50; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative
            double fPrime = 0;
            for (int j = 1; j < xs.size(); j++) {
                fPrime += xs.get(j) * j * Math.pow(x, j - 1);
            }

            if (Math.abs(fPrime) < 1e-10) {
                return Double.NaN; // Derivative too small
            }

            double xNew = x - fx / fPrime;
            if (Double.isInfinite(xNew) || Double.isNaN(xNew)) {
                return Double.NaN;
            }
            x = xNew;
        }
        return x;
    }
}

