class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Find the highest degree non-zero coefficient
        int n = xs.size() - 1;
        double leadingCoeff = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) {
                leadingCoeff = xs.get(i);
                n = i;
                break;
            }
        }

        // Cauchy's bound: all roots satisfy |x| <= 1 + max(|a_i|/|a_n|)
        double maxRatio = 0;
        for (int i = 0; i < xs.size(); i++) {
            double ratio = Math.abs(xs.get(i)) / Math.abs(leadingCoeff);
            if (ratio > maxRatio) {
                maxRatio = ratio;
            }
        }
        double bound = 1 + maxRatio;

        // Try Newton-Raphson from multiple starting points
        for (double startX = -bound; startX <= bound; startX += bound / 5.0) {
            double x = startX;
            for (int iter = 0; iter < 50; iter++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < 1e-9) {
                    return x;
                }

                // Compute derivative
                double fpx = 0;
                for (int i = 1; i < xs.size(); i++) {
                    fpx += i * xs.get(i) * Math.pow(x, i - 1);
                }

                // Avoid division by zero or very small derivative
                if (Math.abs(fpx) < 1e-12) {
                    break;
                }

                double newX = x - fx / fpx;

                // Check if we stayed within bounds
                if (Math.abs(newX) > bound * 2) {
                    break;
                }

                x = newX;
            }
        }

        // Fallback: try bisection between -bound and bound
        double left = -bound;
        double right = bound;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If signs are different, bisection will work
        if (fLeft * fRight <= 0) {
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);
                if (Math.abs(fMid) < 1e-9) {
                    return mid;
                }
                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
        }

        // Last resort: return midpoint of interval
        return (left + right) / 2;
    }
}

