    [4, 2, 1, 2, 2, 1, 1, 1, 1, 4, 4]
     */
    public List<Integer> parseMusic(String string) {
        List<Integer> result = new ArrayList<>();

        if (string == null || string.trim().isEmpty()) {
            return result;
        }

        String[] notes = string.split(" ");

        for (String note : notes) {
            if (note.equals("o")) {
                result.add(4);
            } else if (note.equals("o|")) {
                result.add(2);
            } else if (note.equals(".|")) {
                result.add(1);
            }
        }

        return result;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Handle edge cases
        if (substring == null || substring.isEmpty() || string == null || string.isEmpty()) {
            return 0;
        }

        int count = 0;
        int index = 0;

        while (index <= string.length() - substring.length()) {
            // Find the next occurrence starting from current index
            int foundIndex = string.indexOf(substring, index);

            if (foundIndex == -1) {
                break;
            }

            count++;
            // Move to next position to allow overlapping matches
            index = foundIndex + 1;
        }

        return count;
    }
}

