     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: linear polynomial (degree 1)
        if (xs.size() == 2) {
            // ax + b = 0 => x = -b/a
            double a = xs.get(1);
            double b = xs.get(0);
            if (a == 0) {
                // If leading coefficient is 0, try next one or return 0
                if (xs.size() > 2 && xs.get(2) != 0) {
                    a = xs.get(2);
                    b = xs.get(1);
                    return -b / a;
                }
                return 0.0;
            }
            return -b / a;
        }

        // Newton-Raphson method for finding roots
        double x = 0.0; // initial guess

        // Try multiple starting points if needed
        for (int attempt = 0; attempt < 5; attempt++) {
            double currentX = x + attempt * 0.5;

            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, currentX);

                // Check if we found a root
                if (Math.abs(fx) < 1e-10) {
                    return currentX;
                }

                // Calculate derivative
                double fpx = polyDerivative(xs, currentX);

                // Avoid division by zero
                if (Math.abs(fpx) < 1e-10) {
                    // Try perturbing slightly
                    currentX += 0.1;
                    continue;
                }

                double newX = currentX - fx / fpx;

                // Check for convergence
                if (Math.abs(newX - currentX) < 1e-10) {
                    if (Math.abs(poly(xs, newX)) < 1e-8) {
                        return newX;
                    }
                }

                // Limit search range to avoid overflow
                if (Double.isInfinite(newX) || Double.isNaN(newX)) {
                    currentX = currentX + 0.1;
                } else {
                    currentX = newX;
                }
            }
        }

        // Fallback: try bisection between -1000 and 1000
        double left = -1000.0;
        double right = 1000.0;

        // Find interval where sign changes
        while (left < right) {
            double mid = (left + right) / 2;
            double fmid = poly(xs, mid);

            if (Math.abs(fmid) < 1e-10) {
                return mid;
            }

            double fLeft = poly(xs, left);

            if (fLeft * fmid < 0) {
                right = mid;
            } else {
                left = mid;
            }

            // Limit iterations
            if (right - left < 1e-8) {
                break;
            }
        }

        return (left + right) / 2;
    }

    // Helper method to compute derivative polynomial value
    private double polyDerivative(List<Double> coeffs, double x) {
        double result = 0;
        for (int i = 1; i < coeffs.size(); i++) {
            result += i * coeffs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

