                case ".|":
                    result.add(1);
                    break;
                default:
                    // According to the problem, we can assume valid input
                    // But for robustness, we could add error handling
                    throw new IllegalArgumentException("Invalid note: " + note);
            }
        }

        return result;
    }
}

