        if (numbers == null) {
            return new ArrayList<>();
        }

        // Create result list with appropriate capacity
        List<Integer> result = new ArrayList<>(numbers.size() > 0 ? 
                                             numbers.size() * 2 - 1 : 0);

        // Handle empty list
        if (numbers.isEmpty()) {
            return result;
        }

        // Iterate through all but the last element, adding each followed by delimiter
        for (int i = 0; i < numbers.size() - 1; i++) {
            result.add(numbers.get(i));
            result.add(delimiter);
        }

        // Add the last element
        result.add(numbers.get(numbers.size() - 1));

        return result;
    }
}

