class Solution {
    /**
    Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sortNumbers("three one five")
    "one three five"
     */
    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return numbers;
        }

        // Create mapping from word to numeric value
        Map<String, Integer> wordToNum = new HashMap<>();
        wordToNum.put("zero", 0);
        wordToNum.put("one", 1);
        wordToNum.put("two", 2);
        wordToNum.put("three", 3);
        wordToNum.put("four", 4);
        wordToNum.put("five", 5);
        wordToNum.put("six", 6);
        wordToNum.put("seven", 7);
        wordToNum.put("eight", 8);
        wordToNum.put("nine", 9);

        // Split input string into individual number words
        String[] words = numbers.trim().split("\\s+");

        // Convert words to integers, sort them, then convert back to words
        List<Integer> nums = new ArrayList<>();
        for (String word : words) {
            nums.add(wordToNum.get(word));
        }

        Collections.sort(nums);

        // Build result string by converting numbers back to words
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < nums.size(); i++) {
            if (i > 0) {
                result.append(" ");
            }
            result.append(getWordFromNumber(nums.get(i)));
        }

        return result.toString();
    }

    // Helper method to convert number to word
    private String getWordFromNumber(int num) {
        switch (num) {
            case 0: return "zero";
            case 1: return "one";
            case 2: return "two";
            case 3: return "three";
            case 4: return "four";
            case 5: return "five";
            case 6: return "six";
            case 7: return "seven";
            case 8: return "eight";
            case 9: return "nine";
            default: throw new IllegalArgumentException("Invalid number: " + num);
        }
    }
}

