import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For linear case: ax + b = 0 -> x = -b/a
        if (xs.size() == 2) {
            double a = xs.get(1);
            double b = xs.get(0);
            if (Math.abs(a) > 1e-12) {
                return -b / a;
            }
        }

        // Use Newton-Raphson method with multiple starting points
        double[] startingPoints = {-1000, -100, -10, -1, 0, 1, 10, 100, 1000};

        for (double startX : startingPoints) {
            double x = startX;
            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < 1e-9) {
                    return x;
                }

                // Compute derivative numerically
                double h = 1e-8;
                double fPrime = (poly(xs, x + h) - fx) / h;

                if (Math.abs(fPrime) < 1e-12) {
                    break; // Derivative too small, skip this starting point
                }

                double newX = x - fx / fPrime;

                // Check for divergence
                if (Double.isNaN(newX) || Double.isInfinite(newX) || 
                    Math.abs(newX - x) > 1e10) {
                    break;
                }

                x = newX;
            }
        }

        // If Newton-Raphson fails, try bisection between -1000 and 1000
        double left = -1000;
        double right = 1000;

        // Find an interval where function changes sign
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Try to find bracket
        while (fLeft * fRight > 0 && (right - left) < 2000) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        if (fLeft * fRight <= 0) {
            // Bisection method
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);
                if (Math.abs(fMid) < 1e-9 || (right - left) < 1e-9) {
                    return mid;
                }
                if (fLeft * fMid <= 0) {
                    right = mid;
                    fRight = fMid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
        }

        // Fallback: return midpoint of search range
        return 0.0;
    }
}

