class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method with multiple starting points
        // Try several initial guesses
        double[] initialGuesses = {-1000, -100, -10, -1, 0, 1, 10, 100, 1000};

        for (double guess : initialGuesses) {
            double result = newtonRaphson(xs, guess);
            // Check if result is actually a root
            if (Math.abs(poly(xs, result)) < 1e-9) {
                return result;
            }
        }

        // Fallback: try bisection between -1000 and 1000
        double left = -1000, right = 1000;
        double mid = (left + right) / 2;
        int iterations = 100;

        for (int i = 0; i < iterations; i++) {
            mid = (left + right) / 2;
            double fMid = poly(xs, mid);
            double fLeft = poly(xs, left);

            if (Math.abs(fMid) < 1e-12) {
                break;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return mid;
    }

    private double newtonRaphson(List<Double> coeffs, double x0) {
        double x = x0;
        for (int i = 0; i < 100; i++) {
            double fx = poly(coeffs, x);

            // Derivative
            double fpx = polyDeriv(coeffs, x);

            if (Math.abs(fpx) < 1e-12) {
                // Derivative too small, try to adjust
                x += 0.1;
                continue;
            }

            double xNext = x - fx / fpx;

            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                return x0; // fallback
            }

            if (Math.abs(xNext - x) < 1e-12) {
                break;
            }

            x = xNext;
        }
        return x;
    }

    private double polyDeriv(List<Double> coeffs, double x) {
        double result = 0;
        for (int i = 1; i < coeffs.size(); i++) {
            result += i * coeffs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

