class Solution {
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Convert list to array for faster access
        double[] coeffs = new double[xs.size()];
        for (int i = 0; i < xs.size(); i++) {
            coeffs[i] = xs.get(i);
        }

        // Define polynomial evaluation function inline
        java.util.function.DoubleUnaryOperator polyEval = (double x) -> {
            double result = 0;
            double xPower = 1;
            for (int i = 0; i < coeffs.length; i++) {
                result += coeffs[i] * xPower;
                xPower *= x;
            }
            return result;
        };

        double f = polyEval.applyAsDouble(0.0);
        if (Math.abs(f) < 1e-12) {
            return 0.0;
        }

        // Try to find an interval [a, b] where f(a)*f(b) < 0
        double left = -1.0;
        double right = 1.0;
        double fLeft = polyEval.applyAsDouble(left);
        double fRight = polyEval.applyAsDouble(right);

        // Expand interval until we find sign change
        int maxExpansions = 100;
        int expansionCount = 0;
        while (fLeft * fRight > 0 && expansionCount < maxExpansions) {
            left *= 2;
            right *= 2;
            fLeft = polyEval.applyAsDouble(left);
            fRight = polyEval.applyAsDouble(right);
            expansionCount++;
        }

        // If still no sign change, try searching in different directions
        if (fLeft * fRight > 0) {
            // Fallback: use Newton's method starting from 0
            double x = 0.0;
            for (int iter = 0; iter < 100; iter++) {
                // Compute f(x)
                double fx = 0;
                double xPow = 1;
                for (int i = 0; i < coeffs.length; i++) {
                    fx += coeffs[i] * xPow;
                    xPow *= x;
                }

                // Compute f'(x)
                double fpx = 0;
                double xPowDeriv = 1;
                for (int i = 1; i < coeffs.length; i++) {
                    fpx += i * coeffs[i] * xPowDeriv;
                    xPowDeriv *= x;
                }

                if (Math.abs(fpx) < 1e-15) {
                    // Derivative too small, try small perturbation
                    x += 0.1;
                    continue;
                }

                double newX = x - fx / fpx;
                if (Math.abs(newX - x) < 1e-12) {
                    break;
                }
                x = newX;
            }
            return x;
        }

        // Bisection method
        final double EPSILON = 1e-12;
        while (right - left > EPSILON) {
            double mid = (left + right) / 2;
            double fMid = polyEval.applyAsDouble(mid);

            if (Math.abs(fMid) < EPSILON) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

