class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Handle special cases - the first few Fibonacci primes are small
        if (n == 1) return 2;
        if (n == 2) return 3;
        if (n == 3) return 5;
        if (n == 4) return 13;
        if (n == 5) return 89;

        // We'll generate Fibonacci numbers and check if they're prime
        int count = 5; // We already know the first 5

        long a = 21; // F(8) = 21 (we've already checked up to F(11)=89)
        long b = 34; // F(9) = 34
        long c = 55; // F(10) = 55

        // Start from F(11) = 89 which we already know is prime
        // So we need to start checking from F(12) = 144
        long fibPrev = 55;
        long fibCurrent = 89;

        while (true) {
            // Generate next Fibonacci number
            long fibNext = fibPrev + fibCurrent;
            fibPrev = fibCurrent;
            fibCurrent = fibNext;

            // Check if it's prime
            if (isPrime(fibCurrent)) {
                count++;
                if (count == n) {
                    return (int) fibCurrent;
                }
            }

            // Safety check to prevent overflow (though problem likely expects reasonable inputs)
            if (fibCurrent > Integer.MAX_VALUE) {
                throw new ArithmeticException("Result exceeds Integer.MAX_VALUE");
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;

        // Check for factors up to sqrt(num)
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

