class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // For odd-degree polynomials (even number of coefficients means odd degree),
        // there's always at least one real root.
        // We'll use bisection method after finding appropriate bounds.

        double lower = -1000.0;
        double upper = 1000.0;
        double fLower = poly(xs, lower);
        double fUpper = poly(xs, upper);

        // Ensure we have opposite signs - if not, expand range
        int attempts = 0;
        while (fLower * fUpper > 0 && attempts < 20) {
            lower *= 10;
            upper *= 10;
            fLower = poly(xs, lower);
            fUpper = poly(xs, upper);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives very precise result
            double mid = (lower + upper) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }

            if (fLower * fMid <= 0) {
                upper = mid;
                fUpper = fMid;
            } else {
                lower = mid;
                fLower = fMid;
            }
        }

        return (lower + upper) / 2.0;
    }
}

