class Solution {
    public int largestDivisor(int n) {
        // Start from n/2 and go down to 1
        // The largest proper divisor of n cannot exceed n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }
        // This should never be reached for n > 1, but return 1 as fallback
        return 1;
    }
}

