import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Define a reasonable search range
        double left = -1000.0;
        double right = 1000.0;

        // Evaluate polynomial at endpoints
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Ensure we have opposite signs (if not, expand search range)
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 10) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations should give good precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint if we didn't converge exactly
        return (left + right) / 2.0;
    }
}

