class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return -1; // or throw exception, but problem implies n > 1
        }

        // Check for smallest divisor starting from 2
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                // i is the smallest divisor > 1
                // So n/i is the largest divisor < n
                return n / i;
            }
        }

        // If we reach here, n is prime, so largest proper divisor is 1
        return 1;
    }
}

