class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        int n = xs.size();

        // Handle linear case directly: a + bx = 0 => x = -a/b
        if (n == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (b != 0) {
                return -a / b;
            }
            // If b == 0, handle as special case (but problem says guaranteed solution exists)
            return -a / 1e-10; // fallback
        }

        // For higher degree polynomials, use Newton-Raphson method
        // Start with a reasonable initial guess
        double x = 1.0;
        double tolerance = 1e-10;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Calculate derivative
            double fpx = polyDerivative(xs, x);

            // If derivative is too small, avoid division by zero
            if (Math.abs(fpx) < 1e-15) {
                // Try a different starting point
                x = (iter % 2 == 0) ? x + 1 : x - 1;
                continue;
            }

            double xNew = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNew - x) < tolerance) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNew)) < tolerance) {
                    return xNew;
                }
            }

            x = xNew;
        }

        // If Newton-Raphson fails, try bisection method
        // Find an interval [a, b] where f(a)*f(b) < 0
        double a = -100.0;
        double b = 100.0;
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Expand interval until we find sign change
        while (fa * fb > 0 && (Math.abs(a) < 1e6)) {
            a *= 2;
            b *= 2;
            fa = poly(xs, a);
            fb = poly(xs, b);
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (a + b) / 2;
            double fmid = poly(xs, mid);

            if (Math.abs(fmid) < tolerance || (b - a) / 2 < tolerance) {
                return mid;
            }

            if (fa * fmid <= 0) {
                b = mid;
                fb = fmid;
            } else {
                a = mid;
                fa = fmid;
            }
        }

        // Fallback: return midpoint of final interval
        return (a + b) / 2;
    }

    // Helper method to evaluate polynomial derivative
    private double polyDerivative(List<Double> xs, double x) {
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += i * xs.get(i) * Math.pow(x, i - 1);
        }
        return result;
    }
}

