class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Edge case: empty substring - by convention, empty string appears at every position
        // but typically we return 0 for empty substring as there's no meaningful match
        if (substring.isEmpty()) {
            return 0;
        }

        // Edge case: substring longer than string
        if (substring.length() > string.length()) {
            return 0;
        }

        int count = 0;
        // Check at each possible starting position
        for (int i = 0; i <= string.length() - substring.length(); i++) {
            if (string.startsWith(substring, i)) {
                count++;
            }
        }

        return count;
    }
}

