class Solution {
    public double findZero(List<Double> xs) {
        // Newton-Raphson method
        // Start with initial guess
        double x = 1.0;

        // Perform Newton's method iterations
        for (int i = 0; i < 100; i++) {
            double fx = poly(xs, x);

            // If close enough to zero, return
            if (Math.abs(fx) < 1e-9) {
                return x;
            }

            // Compute derivative
            double fpx = polyDerivative(xs, x);

            // Avoid division by zero
            if (Math.abs(fpx) < 1e-12) {
                x += 0.1; // perturb slightly
                continue;
            }

            // Newton step
            double xNext = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNext - x) < 1e-9) {
                return xNext;
            }

            x = xNext;
        }

        // Fallback: return the current approximation
        return x;
    }

    private double polyDerivative(List<Double> xs, double x) {
        if (xs.size() <= 1) {
            return 0.0;
        }

        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += xs.get(i) * i * Math.pow(x, i - 1);
        }
        return result;
    }
}

