class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true; // 2 and 3 are prime
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check for factors of the form 6k ± 1 up to sqrt(n)
        // This skips all even numbers and multiples of 3
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Find the degree of polynomial (highest non-zero power)
        int degree = xs.size() - 1;

        // Get leading coefficient (largest non-zero coefficient)
        double leadingCoeff = 0;
        for (int i = degree; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-15) {
                leadingCoeff = xs.get(i);
                break;
            }
        }

        // For odd degree polynomials, as x -> ±∞, f(x) -> ±∞ or ∓∞ depending on leading coefficient
        // We need to find an interval [a, b] where f(a) * f(b) < 0

        double left = -1.0;
        double right = 1.0;

        // Expand the interval until we find sign change
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 2;
            right *= 2;
            // Safety check to prevent infinite loop
            if (Math.abs(left) > 1e10) {
                // Fallback: try Newton's method starting from 0
                return newtonMethod(xs, 0);
            }
        }

        // Use bisection method to find root
        double mid;
        int iterations = 0;
        int maxIterations = 1000;
        double tolerance = 1e-12;

        while ((right - left) > tolerance && iterations < maxIterations) {
            mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance) {
                return mid;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
            iterations++;
        }

        return (left + right) / 2.0;
    }

    private double newtonMethod(List<Double> xs, double x0) {
        double x = x0;
        double tolerance = 1e-12;
        int maxIterations = 100;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative: f'(x) = sum(i * coeff_i * x^(i-1))
            double fPrime = 0;
            for (int j = 1; j < xs.size(); j++) {
                fPrime += j * xs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(fPrime) < 1e-15) {
                // Derivative too small, switch to bisection
                return x + 0.1 * (i % 2 == 0 ? 1 : -1);
            }

            double xNew = x - fx / fPrime;
            if (Math.abs(xNew - x) < tolerance) {
                return xNew;
            }
            x = xNew;
        }

        return x;
    }
}

