    public List<Integer> sortThird(List<Integer> l) {
        List<Integer> result = new ArrayList<>(l);

        // Collect values at indices divisible by 3
        List<Integer> valuesAtDivisibleByThree = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 3) {
            valuesAtDivisibleByThree.add(l.get(i));
        }

        // Sort these values
        Collections.sort(valuesAtDivisibleByThree);

        // Put sorted values back into result at indices divisible by 3
        int sortedIndex = 0;
        for (int i = 0; i < result.size(); i += 3) {
            result.set(i, valuesAtDivisibleByThree.get(sortedIndex++));
        }

        return result;
    }
}

