class Solution {
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // All other even numbers are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
            // Try multiple starting points for Newton-Raphson
            double[] starts = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

            for (double start : starts) {
                try {
                    double root = newtonRaphson(xs, start);
                    // Verify it's actually a root (within tolerance)
                    if (Math.abs(poly(xs, root)) < 1e-7) {
                        return root;
                    }
                } catch (Exception e) {
                    // Skip this starting point
                }
            }

            // Fallback: try bisection between -100 and 100
            double left = -100.0;
            double right = 100.0;
            double mid;
            for (int i = 0; i < 100; i++) {
                mid = (left + right) / 2.0;
                double fMid = poly(xs, mid);
                double fLeft = poly(xs, left);

                if (Math.abs(fMid) < 1e-7) {
                    return mid;
                }

                if (fLeft * fMid <= 0) {
                    right = mid;
                } else {
                    left = mid;
                }
            }

            return (left + right) / 2.0;
        }

        private double newtonRaphson(List<Double> xs, double startX) {
            double x = startX;
            for (int i = 0; i < 100; i++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                // Compute derivative: f'(x) = sum of i * coeff[i] * x^(i-1)
                double fPrimeX = 0;
                for (int j = 1; j < xs.size(); j++) {
                    fPrimeX += j * xs.get(j) * Math.pow(x, j - 1);
                }

                // If derivative is zero, we can't continue Newton-Raphson
                if (Math.abs(fPrimeX) < 1e-10) {
                    throw new ArithmeticException("Derivative too small");
                }

                double xNext = x - fx / fPrimeX;

                // Check for divergence
                if (Double.isInfinite(xNext) || Double.isNaN(xNext)) {
                    throw new ArithmeticException("Divergence detected");
                }

                x = xNext;
            }
            return x;
        }
}

