class Solution {
    /**
    Filter an input list of strings only for ones that contain given substring
    >>> filterBySubstring(List.of(), "a")
    []
    >>> filterBySubstring(Arrays.asList("abc", "bacd", "cde", "array"), "a")
    ["abc", "bacd", "array"]
     */
    public List<String> filterBySubstring(List<String> strings, String substring) {
        List<String> result = new ArrayList<>();

        // Handle null cases
        if (strings == null) {
            return result;
        }

        // If substring is null, no strings can contain it, so return empty list
        if (substring == null) {
            return result;
        }

        for (String str : strings) {
            // Only add if string is not null and contains the substring
            if (str != null && str.contains(substring)) {
                result.add(str);
            }
        }

        return result;
    }
}

