class Solution {
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrtN = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle linear case directly
        if (xs.size() == 2) {
            // a + bx = 0 => x = -a/b
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) < 1e-12) {
                // constant polynomial, no root or infinite roots
                return 0.0;
            }
            return -a / b;
        }

        // Newton-Raphson with multiple starting points
        double[] startingPoints = {-100.0, -10.0, -1.0, 0.0, 1.0, 10.0, 100.0};
        double bestRoot = Double.MAX_VALUE;
        boolean found = false;

        for (double x0 : startingPoints) {
            double x = x0;
            for (int iter = 0; iter < 50; iter++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < 1e-10) {
                    if (!found || Math.abs(x) < Math.abs(bestRoot)) {
                        bestRoot = x;
                        found = true;
                    }
                    break;
                }

                // Compute derivative
                double fpx = 0;
                for (int i = 1; i < xs.size(); i++) {
                    fpx += i * xs.get(i) * Math.pow(x, i - 1);
                }

                if (Math.abs(fpx) < 1e-12) {
                    // Derivative too small, try next starting point
                    break;
                }

                double xNext = x - fx / fpx;
                if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                    break;
                }
                x = xNext;
            }
        }

        // If still not found, use bisection between -100 and 100
        if (!found) {
            double left = -100.0;
            double right = 100.0;
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = poly(xs, mid);
                double fLeft = poly(xs, left);
                if (fMid == 0 || (right - left) < 1e-9) {
                    bestRoot = mid;
                    found = true;
                    break;
                }
                if (fLeft * fMid <= 0) {
                    right = mid;
                } else {
                    left = mid;
                }
            }
        }

        return found ? bestRoot : 0.0;
    }
}

