                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // According to the problem statement, only these three formats are expected
                    // If unexpected input appears, we could throw exception or skip, but problem implies valid input
                    break;
            }
        }

        return result;
    }
}

