class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return -1; // or throw exception, but problem doesn't specify behavior for n <= 1
        }

        // Start from n/2 and go downwards to find the largest proper divisor
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // This should never be reached since 1 always divides n
    }
}

