import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Try small integer values first
        double[] testValues = {0, 1, -1, 2, -2, 3, -3, 0.5, -0.5};
        for (double x : testValues) {
            if (Math.abs(poly(xs, x)) < 1e-9) {
                return x;
            }
        }

        // For linear case: ax + b = 0 => x = -b/a
        if (xs.size() == 2) {
            double a = xs.get(1);
            double b = xs.get(0);
            if (Math.abs(a) > 1e-12) {
                return -b / a;
            }
        }

        // For higher degrees, use Newton-Raphson starting from multiple initial guesses
        double[] initialGuesses = {0, 1, -1, 2, -2, 10, -10, 0.5, -0.5};

        for (double x0 : initialGuesses) {
            double result = newtonRaphson(xs, x0);
            if (result != Double.NaN && Math.abs(poly(xs, result)) < 1e-7) {
                return result;
            }
        }

        // Fallback: try bisection on a wide range
        for (double left = -100, right = 100; left <= 100; left += 10) {
            double fLeft = poly(xs, left);
            double fRight = poly(xs, left + 10);
            if (fLeft * fRight <= 0) {
                // Root exists in [left, left+10]
                double result = bisection(xs, left, left + 10);
                if (Math.abs(poly(xs, result)) < 1e-7) {
                    return result;
                }
            }
        }

        // Last resort: return 0 (shouldn't happen per problem statement)
        return 0.0;
    }

    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        for (int i = 0; i < 100; i++) { // max iterations
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-12) {
                return x;
            }

            // Compute derivative
            double fPrime = 0;
            for (int j = 1; j < xs.size(); j++) {
                fPrime += j * xs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(fPrime) < 1e-12) {
                return Double.NaN; // Derivative too small
            }

            double xNext = x - fx / fPrime;
            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                return Double.NaN;
            }

            if (Math.abs(xNext - x) < 1e-12) {
                return xNext;
            }

            x = xNext;
        }
        return x;
    }

    private double bisection(List<Double> xs, double a, double b) {
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        if (fa * fb > 0) {
            return (a + b) / 2; // No sign change, just return midpoint
        }

        for (int i = 0; i < 100; i++) {
            double c = (a + b) / 2;
            double fc = poly(xs, c);

            if (Math.abs(fc) < 1e-12 || (b - a) < 1e-12) {
                return c;
            }

            if (fa * fc <= 0) {
                b = c;
                fb = fc;
            } else {
                a = c;
                fa = fc;
            }
        }
        return (a + b) / 2;
    }
}

