class Solution {
    /**
    Input to this function is a string representing musical notes in a special ASCII format.
    Your task is to parse this string and return list of integers corresponding to how many beats does each
    not last.

    Here is a legend:
    "o" - whole note, lasts four beats
    "o|" - half note, lasts two beats
    ".|" - quater note, lasts one beat

    >>> parseMusic("o o| .| o| o| .| .| .| .| o o")
    [4, 2, 1, 2, 2, 1, 1, 1, 1, 4, 4]
     */
    public List<Integer> parseMusic(String string) {
        List<Integer> result = new ArrayList<>();
        if (string == null || string.isEmpty()) {
            return result;
        }

        int i = 0;
        while (i < string.length()) {
            // Skip whitespace
            if (Character.isWhitespace(string.charAt(i))) {
                i++;
                continue;
            }

            // Check for quarter note ".|" (must check before "o|" and "o")
            if (i + 1 < string.length() && string.substring(i, i + 2).equals(".|")) {
                result.add(1);
                i += 2;
            }
            // Check for half note "o|"
            else if (i + 1 < string.length() && string.substring(i, i + 2).equals("o|")) {
                result.add(2);
                i += 2;
            }
            // Check for whole note "o"
            else if (string.charAt(i) == 'o') {
                result.add(4);
                i += 1;
            }
            // Handle any other characters (shouldn't happen per spec, but be safe)
            else {
                i++;
            }
        }

        return result;
    }
}

