class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Newton-Raphson method
        double x = 1.0; // initial guess

        // Try multiple starting points if needed
        for (int start = 0; start < 3; start++) {
            double currentX = start == 0 ? 1.0 : (start == 1 ? -1.0 : 0.0);

            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, currentX);

                // Check if close enough to zero
                if (Math.abs(fx) < 1e-10) {
                    return currentX;
                }

                // Calculate derivative
                double fPrimeX = 0.0;
                for (int i = 1; i < xs.size(); i++) {
                    fPrimeX += i * xs.get(i) * Math.pow(currentX, i - 1);
                }

                // If derivative is zero or too small, try next starting point
                if (Math.abs(fPrimeX) < 1e-10) {
                    break;
                }

                double nextX = currentX - fx / fPrimeX;

                // Check for divergence
                if (Double.isNaN(nextX) || Double.isInfinite(nextX)) {
                    break;
                }

                // Check convergence
                if (Math.abs(nextX - currentX) < 1e-12) {
                    if (Math.abs(poly(xs, nextX)) < 1e-10) {
                        return nextX;
                    }
                    break;
                }

                currentX = nextX;
            }
        }

        // Fallback: bisection method between -1000 and 1000
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Ensure we have opposite signs (since odd degree polynomial must cross zero)
        // If not, expand the interval
        while (fLeft * fRight > 0 && (right - left) < 20000) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

