        List<Integer> result = new ArrayList<>(numbers.size());
        int currentMax = Integer.MIN_VALUE;

        for (Integer num : numbers) {
            if (num != null && num > currentMax) {
                currentMax = num;
            }
            result.add(currentMax);
        }

        return result;
    }
}

