     */
    public boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle linear case directly for efficiency and accuracy
        if (xs.size() == 2) {
            double a = xs.get(1);
            double b = xs.get(0);
            if (Math.abs(a) > 1e-12) {
                return -b / a;
            }
        }

        // Bisection method for higher degrees
        // Define a function to evaluate polynomial
        java.util.function.DoubleUnaryOperator f = (double x) -> poly(xs, x);

        // Find an interval [left, right] where sign changes
        double left = -1000.0;
        double right = 1000.0;

        // Expand interval until we find sign change
        while (f.applyAsDouble(left) * f.applyAsDouble(right) > 0) {
            left *= 10;
            right *= 10;
            // Safety limit to prevent infinite loop
            if (Math.abs(left) > 1e9) {
                // Fallback: try starting from smaller range
                left = -10.0;
                right = 10.0;
                break;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives good precision
            double mid = (left + right) / 2.0;
            double fMid = f.applyAsDouble(mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (f.applyAsDouble(left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Return midpoint of final interval
        return (left + right) / 2.0;
    }
}

