class Solution {
    public List<Double> findClosestElements(List<Double> numbers) {
        if (numbers == null || numbers.size() < 2) {
            throw new IllegalArgumentException("List must contain at least two elements");
        }

        // Create a copy to avoid modifying the original list
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        double minDiff = Double.MAX_VALUE;
        int minIndex = 0;

        // Check consecutive pairs in sorted list
        for (int i = 0; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < minDiff) {
                minDiff = diff;
                minIndex = i;
            }
        }

        // Return in order (smaller, larger)
        double a = sorted.get(minIndex);
        double b = sorted.get(minIndex + 1);

        return Arrays.asList(Math.min(a, b), Math.max(a, b));
    }
}

