class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // For n <= 1, there's no proper divisor smaller than n
        if (n <= 1) {
            return -1; // or handle as appropriate, though problem likely assumes n > 1
        }

        // Start from n/2 and go downwards since the largest proper divisor is at most n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // fallback, though for n > 1, we should always find at least 1
    }
}

