class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Use Horner's method for better numerical stability and efficiency
        double result = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Find the highest degree coefficient (last non-zero)
        int n = xs.size() - 1;
        while (n >= 0 && Math.abs(xs.get(n)) < 1e-12) {
            n--;
        }
        if (n < 0) {
            return 0.0; // zero polynomial
        }

        // Check if degree is odd (even number of coefficients means odd degree)
        // xs.size() is even, so degree = xs.size() - 1 is odd
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("Number of coefficients must be even");
        }

        // Determine search bounds using the fact that leading term dominates
        double leadingCoeff = xs.get(n);
        double bound = 1.0;
        for (int i = 0; i < n; i++) {
            bound += Math.abs(xs.get(i) / leadingCoeff);
        }
        bound = Math.max(bound, 1.0);

        double left = -bound;
        double right = bound;

        // Use bisection method for guaranteed convergence
        for (int iter = 0; iter < 100; iter++) {
            double mid = (left + right) / 2.0;
            double val = poly(xs, mid);

            if (Math.abs(val) < 1e-12) {
                return mid;
            }

            double valLeft = poly(xs, left);
            if (valLeft * val <= 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Fallback: return midpoint if didn't converge perfectly
        return (left + right) / 2.0;
    }
}

