import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Using Horner's method for better numerical stability and performance
        double result = 0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            throw new IllegalArgumentException("Coefficient list cannot be null or empty");
        }

        // Find the highest degree term (last non-zero coefficient)
        int degree = xs.size() - 1;
        while (degree > 0 && Math.abs(xs.get(degree)) < 1e-15) {
            degree--;
        }

        // Must be odd degree (even number of coefficients means odd degree)
        if (degree % 2 == 0) {
            throw new IllegalArgumentException("Polynomial must have odd degree (even number of coefficients)");
        }

        // Use bisection method
        // First, find an interval [a, b] where f(a) * f(b) < 0

        double left = -1.0;
        double right = 1.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand interval until we find sign change
        int maxExpansion = 100;
        for (int i = 0; i < maxExpansion && fLeft * fRight >= 0; i++) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        // If still no sign change (shouldn't happen for odd degree), try specific values
        if (fLeft * fRight >= 0) {
            // Try specific points for odd degree polynomials
            left = -1000.0;
            right = 1000.0;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        // Bisection method with tolerance
        final double tolerance = 1e-12;
        final int maxIterations = 100;

        for (int i = 0; i < maxIterations; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance || (right - left) / 2 < tolerance) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

