class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        int a = 1; // F(1)
        int b = 1; // F(2)

        // Handle special case: check if 1 is considered (but 1 is not prime)
        // So start checking from F(3) = 2

        // First check if n == 1, we need to find the first prime Fibonacci
        if (n == 1) {
            // The first prime Fibonacci is 2
            return 2;
        }

        // Start generating Fibonacci numbers from F(3) = 2
        int fib = 2;
        int index = 3;

        // We already know F(1)=1 and F(2)=1 are not prime, F(3)=2 is the first prime Fibonacci
        count = 1; // We found the first one (2)

        if (n == 1) {
            return 2;
        }

        while (count < n) {
            // Check if current Fibonacci number is prime
            if (isPrime(fib)) {
                count++;
                if (count == n) {
                    return fib;
                }
            }

            // Generate next Fibonacci number
            int next = a + b;
            a = b;
            b = fib;
            fib = next;
        }

        return fib;
    }

    private boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

