class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        int n = xs.size();

        // Handle linear case: a + bx = 0 -> x = -a/b
        if (n == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) < 1e-12) {
                throw new IllegalArgumentException("Invalid polynomial: zero coefficient for x");
            }
            return -a / b;
        }

        // For higher odd-degree polynomials, use bisection method
        // First, make sure the leading coefficient is non-zero (should be, but check anyway)
        double leadingCoeff = xs.get(n - 1);
        if (Math.abs(leadingCoeff) < 1e-12) {
            throw new IllegalArgumentException("Leading coefficient must be non-zero");
        }

        // Define the polynomial function
        java.util.function.DoubleUnaryOperator f = x -> poly(xs, x);

        // Find an interval [a, b] where f(a) * f(b) < 0 (sign change)
        double bound = 1.0;
        double fa, fb;
        int iterations = 0;
        final int maxBoundIterations = 100;

        do {
            fa = f.applyAsDouble(-bound);
            fb = f.applyAsDouble(bound);
            if (fa * fb <= 0) {
                break;
            }
            bound *= 2.0;
            iterations++;
        } while (iterations < maxBoundIterations);

        // If we couldn't find a sign change, try a different approach or throw
        if (iterations == maxBoundIterations) {
            // Fallback: try Newton's method from x=0
            return newtonRaphson(xs, 0.0);
        }

        // Bisection method
        double left = -bound;
        double right = bound;
        double mid;
        final double tolerance = 1e-12;
        final int maxBisectionIterations = 1000;

        for (int i = 0; i < maxBisectionIterations; i++) {
            mid = (left + right) / 2.0;
            double fm = f.applyAsDouble(mid);

            if (Math.abs(fm) < tolerance || (right - left) / 2.0 < tolerance) {
                return mid;
            }

            double fl = f.applyAsDouble(left);
            if (fl * fm <= 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2.0;
    }

    // Helper method for Newton-Raphson
    private double newtonRaphson(List<Double> xs, double x0) {
        double x = x0;
        final double tolerance = 1e-12;
        final int maxIterations = 100;

        for (int i = 0; i < maxIterations; i++) {
            double fx = poly(xs, x);
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative
            double fpx = 0;
            for (int j = 1; j < xs.size(); j++) {
                fpx += j * xs.get(j) * Math.pow(x, j - 1);
            }

            if (Math.abs(fpx) < 1e-15) {
                x += 0.1; // small perturbation if derivative is near zero
                continue;
            }

            double xNext = x - fx / fpx;
            if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                x += 0.1; // fallback
            } else {
                x = xNext;
            }
        }

        return x;
    }
}

