        List<Integer> result = new ArrayList<>(l);

        // Collect values at indices divisible by 3
        List<Integer> valuesToSort = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 3) {
            valuesToSort.add(l.get(i));
        }

        // Sort these values
        Collections.sort(valuesToSort);

        // Put sorted values back at indices divisible by 3
        int sortedIndex = 0;
        for (int i = 0; i < result.size(); i += 3) {
            result.set(i, valuesToSort.get(sortedIndex++));
        }

        return result;
    }
