class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method
        // Start with initial guesses and try different starting points
        double x = 1.0; // initial guess

        for (int attempt = 0; attempt < 50; attempt++) {
            double fx = poly(xs, x);

            // Check if we've found a root
            if (Math.abs(fx) < 1e-10) {
                return x;
            }

            // Compute derivative using finite differences or analytical derivative
            // For better accuracy, compute derivative analytically
            double fPrime = 0.0;
            for (int i = 1; i < xs.size(); i++) {
                fPrime += i * xs.get(i) * Math.pow(x, i - 1);
            }

            // If derivative is too small, avoid division by zero
            if (Math.abs(fPrime) < 1e-15) {
                // Try a different starting point
                x = (attempt % 2 == 0) ? x + 1.0 : x - 1.0;
                continue;
            }

            double xNew = x - fx / fPrime;

            // Check for convergence
            if (Math.abs(xNew - x) < 1e-10) {
                // Final check
                if (Math.abs(poly(xs, xNew)) < 1e-8) {
                    return xNew;
                }
            }

            x = xNew;

            // If x becomes NaN or infinity, restart with different initial guess
            if (Double.isNaN(x) || Double.isInfinite(x)) {
                x = attempt % 2 == 0 ? 10.0 : -10.0;
            }
        }

        // Fallback: try bisection-like approach or return best guess
        // Given the problem constraints, we should have found a root by now
        return x;
    }
}

