     */
    public Optional<String> longest(List<String> strings) {
        // Check parameters for validity - handle null list
        if (strings == null) {
            return Optional.empty();
        }

        // Handle empty list case
        if (strings.isEmpty()) {
            return Optional.empty();
        }

        String longest = null;
        int maxLen = -1;

        // Iterate through the list to find the longest string
        // Since we want the first one in case of ties, we use >= comparison
        for (String s : strings) {
            // Check for null elements as well
            if (s == null) {
                continue;
            }

            int len = s.length();
            if (len > maxLen) {
                maxLen = len;
                longest = s;
            }
        }

        return Optional.ofNullable(longest);
    }
}

