class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        // Use Horner's method for better numerical stability and efficiency
        double result = 0.0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only one zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Validate input: must have even number of coefficients
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("Polynomial must have even number of coefficients");
        }

        // Handle edge case: constant polynomial (degree 0)
        if (xs.size() == 2) {
            // Linear case: a + bx = 0 -> x = -a/b
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) < 1e-12) {
                throw new IllegalArgumentException("Linear coefficient must be non-zero");
            }
            return -a / b;
        }

        // Newton-Raphson method with multiple starting points for robustness
        // Try several initial guesses to find a root
        double[] initialGuesses = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0};

        for (double initialGuess : initialGuesses) {
            try {
                double root = newtonRaphson(xs, initialGuess);
                // Verify the root is actually close to zero
                if (Math.abs(poly(xs, root)) < 1e-6) {
                    return root;
                }
            } catch (Exception e) {
                // Skip this starting point if Newton's method fails
                continue;
            }
        }

        // Fallback: try bisection method on intervals
        // Since we know a solution exists (guaranteed by problem statement),
        // we can search in a reasonable range
        for (double left = -100.0, right = 100.0; left <= right; ) {
            double mid = (left + right) / 2.0;
            double valueMid = poly(xs, mid);

            if (Math.abs(valueMid) < 1e-6) {
                return mid;
            }

            // Try to find sign change
            boolean foundSignChange = false;
            for (double testPoint = -100.0; testPoint <= 100.0; testPoint += 10.0) {
                double valueTest = poly(xs, testPoint);
                if (valueMid * valueTest < 0) {
                    // Sign change between mid and testPoint
                    double bisectRoot = bisection(xs, mid, testPoint);
                    if (Math.abs(poly(xs, bisectRoot)) < 1e-6) {
                        return bisectRoot;
                    }
                    foundSignChange = true;
                    break;
                }
            }

            if (!foundSignChange) {
                // Expand search range
                left *= 2;
                right *= 2;
                if (Math.abs(left) > 1e8) {
                    break; // Give up
                }
            }
        }

        // Last resort: return midpoint of range as fallback
        return 0.0;
    }

    // Helper: Compute derivative of polynomial at x
    private double polyDerivative(List<Double> xs, double x) {
        // If xs = [a0, a1, a2, ..., an], derivative is [a1, 2*a2, 3*a3, ..., n*an]
        double result = 0.0;
        for (int i = 1; i < xs.size(); i++) {
            result = result * x + (i * xs.get(i));
        }
        return result;
    }

    // Newton-Raphson method
    private double newtonRaphson(List<Double> xs, double initialGuess) {
        double x = initialGuess;
        for (int i = 0; i < 100; i++) { // Max iterations
            double fx = poly(xs, x);
            double fpx = polyDerivative(xs, x);

            if (Math.abs(fpx) < 1e-12) {
                // Derivative too small, try to recover
                x += 0.1;
                continue;
            }

            double nextX = x - fx / fpx;

            // Check convergence
            if (Math.abs(nextX - x) < 1e-12) {
                return x;
            }

            x = nextX;

            // Check if we've converged to a root
            if (Math.abs(poly(xs, x)) < 1e-10) {
                return x;
            }
        }
        return x;
    }

    // Bisection method
    private double bisection(List<Double> xs, double a, double b) {
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Ensure sign change exists
        if (fa * fb > 0) {
            // Try reversing or adjusting
            if (Math.abs(fa) < Math.abs(fb)) {
                return a;
            } else {
                return b;
            }
        }

        for (int i = 0; i < 100; i++) {
            double c = (a + b) / 2.0;
            double fc = poly(xs, c);

            if (Math.abs(fc) < 1e-10 || (b - a) < 1e-10) {
                return c;
            }

            if (fa * fc < 0) {
                b = c;
                fb = fc;
            } else {
                a = c;
                fa = fc;
            }
        }
        return (a + b) / 2.0;
    }
}

