class Solution {
    /**
     * Insert a number 'delimiter' between every two consecutive elements of input list `numbers`.
     * 
     * @param numbers the input list of integers
     * @param delimiter the integer to insert between consecutive elements
     * @return a new list with the delimiter inserted between each pair of consecutive elements
     * 
     * Examples:
     * >>> intersperse(List.of(), 4)
     * []
     * >>> intersperse(Arrays.asList(1, 2, 3), 4)
     * [1, 4, 2, 4, 3]
     */
    public List<Integer> intersperse(List<Integer> numbers, int delimiter) {
        // Handle null input - return empty list as per advice to return empty collections
        if (numbers == null) {
            return Collections.emptyList();
        }

        // If list has 0 or 1 elements, no delimiters needed
        if (numbers.size() <= 1) {
            return new ArrayList<>(numbers);
        }

        // Create result list with expected capacity: original size + (size-1) delimiters
        List<Integer> result = new ArrayList<>(numbers.size() * 2 - 1);

        // Add first element
        result.add(numbers.get(0));

        // Add remaining elements with delimiter before each
        for (int i = 1; i < numbers.size(); i++) {
            result.add(delimiter);
            result.add(numbers.get(i));
        }

        return result;
    }
}

