class Solution {
    /**
     * Parses a string containing space-separated groups of parentheses and returns
     * a list with the maximum nesting depth for each group.
     *
     * @param parenString a string containing groups of parentheses separated by spaces
     * @return a List of Integers representing the maximum nesting depth of each group
     */
    public List<Integer> parseNestedParens(String parenString) {
        List<Integer> result = new ArrayList<>();

        if (parenString == null || parenString.trim().isEmpty()) {
            return result;
        }

        String[] groups = parenString.trim().split("\\s+");

        for (String group : groups) {
            int maxDepth = 0;
            int currentDepth = 0;

            for (int i = 0; i < group.length(); i++) {
                char c = group.charAt(i);

                if (c == '(') {
                    currentDepth++;
                    maxDepth = Math.max(maxDepth, currentDepth);
                } else if (c == ')') {
                    currentDepth--;
                }
            }

            result.add(maxDepth);
        }

        return result;
    }
}

