            if (num == null) {
                throw new IllegalArgumentException("List contains null elements");
            }

            // Update current maximum
            if (num > currentMax) {
                currentMax = num;
            }

            // Add current maximum to result
            result.add(currentMax);
        }

        return result;
    }
}

