class Solution {
    /**
     * Input is a space-delimited string of numerals from 'zero' to 'nine'.
     * Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
     * Return the string with numbers sorted from smallest to largest.
     *
     * @param numbers space-delimited string of number words
     * @return space-delimited string with numbers sorted numerically
     */
    public String sortNumbers(String numbers) {
        // Handle null or empty input - return empty string per best practices
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        // Split into individual number words
        String[] numWords = numbers.trim().split("\\s+");

        // Create mapping from word to numeric value
        Map<String, Integer> wordToNumber = new HashMap<>();
        wordToNumber.put("zero", 0);
        wordToNumber.put("one", 1);
        wordToNumber.put("two", 2);
