        Arrays.sort(numWords, (a, b) -> {
            Integer valA = wordToNumber.get(a);
            Integer valB = wordToNumber.get(b);
            return valA.compareTo(valB);
        });

        // Join back into a space-delimited string
        return String.join(" ", numWords);
    }
}

