class Solution {
    /**
     * Rescales a list of numbers so that the minimum becomes 0 and the maximum becomes 1.
     * 
     * @param numbers list of numbers (must contain at least two elements)
     * @return new list with rescaled values as doubles
     * @throws IllegalArgumentException if the input list has fewer than 2 elements
     * @throws NullPointerException if the input list is null or contains null elements
     */
    public List<Double> rescaleToUnit(List<Double> numbers) {
        // Validate input - fail fast with appropriate exception
        if (numbers == null) {
            throw new NullPointerException("Input list cannot be null");
        }
        if (numbers.size() < 2) {
            throw new IllegalArgumentException("List must contain at least two elements");
        }

        // Find min and max values
        double min = Double.MAX_VALUE;
        double max = Double.MIN_VALUE;
        for (Double num : numbers) {
            if (num == null) {
                throw new NullPointerException("List cannot contain null elements");
            }
            min = Math.min(min, num);
            max = Math.max(max, num);
        }

        // Handle edge case where all values are the same (avoid division by zero)
        if (min == max) {
            // If all values are equal, return list of zeros (or could return all 0.5, but zeros make sense for "rescaled to 0-1")
            List<Double> result = new ArrayList<>(numbers.size());
            for (int i = 0; i < numbers.size(); i++) {
                result.add(0.0);
            }
            return result;
        }

        // Apply the linear transformation
        List<Double> result = new ArrayList<>(numbers.size());
        double range = max - min;
        for (Double num : numbers) {
            result.add((num - min) / range);
        }

        return result;
    }
}

