class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge case: empty list or all zeros
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Find the leading coefficient (last non-zero element from the end)
        int n = xs.size() - 1;
        double leadingCoeff = 0.0;
        for (int i = n; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-15) {
                leadingCoeff = xs.get(i);
                break;
            }
        }

        // For odd-degree polynomials, we know there's at least one real root
        // Use bisection method with appropriate bounds

        // Evaluate polynomial at some points to find sign change
        double left = -1000.0;
        double right = 1000.0;

        // Expand bounds if needed to ensure sign change
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 10) {
            left *= 10;
            right *= 10;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // enough iterations for double precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

