class Solution {
    /**
     * Returns the n-th number that is both a Fibonacci number and prime.
     * 
     * @param n the position (1-indexed) of the prime Fibonacci number to return
     * @return the n-th prime Fibonacci number
     * @throws IllegalArgumentException if n is less than 1
     */
    public int primeFib(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("n must be positive, got: " + n);
        }

        int count = 0;
        long a = 0, b = 1; // Fibonacci sequence starting with F(0)=0, F(1)=1

        while (true) {
            long fib = a + b;
            a = b;
            b = fib;

            if (isPrime(fib)) {
                count++;
                if (count == n) {
                    return (int) fib;
                }
            }

            // Safety check for overflow - though for typical inputs this won't happen
            if (fib > Integer.MAX_VALUE) {
                throw new RuntimeException("Result exceeds Integer.MAX_VALUE");
            }
        }
    }

    /**
     * Checks if a number is prime.
     * 
     * @param num the number to check
     * @return true if the number is prime, false otherwise
     */
    private boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2 || num == 3) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

