class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        // Ensure we have even number of coefficients (odd degree polynomial)
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("Polynomial must have even number of coefficients (odd degree)");
        }

        // Check that leading coefficient is non-zero
        double leadingCoeff = xs.get(xs.size() - 1);
        if (Math.abs(leadingCoeff) < 1e-15) {
            throw new IllegalArgumentException("Leading coefficient must be non-zero");
        }

        // Newton-Raphson method
        double x = 0.0; // initial guess
        double epsilon = 1e-12;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // Check if we found a root
            if (Math.abs(fx) < epsilon) {
                return x;
            }

            // Compute derivative numerically (or analytically)
            double derivative = polyDerivative(xs, x);

            // Avoid division by zero
            if (Math.abs(derivative) < 1e-15) {
                // Try a small perturbation
                x += 0.01;
                continue;
            }

            double xNew = x - fx / derivative;

            // Check convergence
            if (Math.abs(xNew - x) < epsilon) {
                // Verify this is actually a root
                if (Math.abs(poly(xs, xNew)) < epsilon) {
                    return xNew;
                }
            }

            x = xNew;

            // Handle overflow or divergence
            if (Double.isInfinite(x) || Double.isNaN(x)) {
                // Fallback: try bisection method with a reasonable interval
                return bisectionMethod(xs, -1000.0, 1000.0);
            }
        }

        // Return best approximation found
        return x;
    }

    // Helper method to evaluate derivative of polynomial
    private double polyDerivative(List<Double> xs, double x) {
        double result = 0;
        for (int i = 1; i < xs.size(); i++) {
            result += xs.get(i) * i * Math.pow(x, i - 1);
        }
        return result;
    }

    // Bisection method fallback for cases where Newton-Raphson fails
    private double bisectionMethod(List<Double> xs, double a, double b) {
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Ensure we have a sign change
        if (fa * fb > 0) {
            // Try different intervals
            for (double interval = 1.0; interval <= 1000; interval *= 2) {
                a = -interval;
                b = interval;
                fa = poly(xs, a);
                fb = poly(xs, b);
                if (fa * fb <= 0) break;
            }
        }

        if (fa * fb > 0) {
            // Last resort: return midpoint
            return 0.0;
        }

        double epsilon = 1e-12;
        while ((b - a) > epsilon) {
            double mid = (a + b) / 2;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < epsilon) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2;
    }
}

