class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special case for Fibonacci sequence starting
        // We'll generate Fibonacci numbers and check for primality

        // Check F(0) = 0 - not prime
        // Check F(1) = 1 - not prime (by definition, primes are > 1)
        // Check F(2) = 1 - not prime
        // Check F(3) = 2 - prime
        // Check F(4) = 3 - prime
        // etc.

        while (true) {
            long nextFib = a + b;
            a = b;
            b = nextFib;

            // Skip 1 (not prime) and handle small numbers
            if (nextFib > 1 && isPrime((int)nextFib)) {
                count++;
                if (count == n) {
                    return (int)nextFib;
                }
            }

            // Safety check to prevent overflow for very large n
            if (nextFib < 0) {
                throw new ArithmeticException("Integer overflow occurred");
            }
        }
    }

    private boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        if (num <= 3) {
            return true;
        }
        if (num % 2 == 0 || num % 3 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(num)
        for (int i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

