class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n <= 1) {
            return false;
        }
        if (n <= 3) {
            return true;  // 2 and 3 are prime
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }

        // Check for factors from 5 up to sqrt(n)
        // Use 6k ± 1 optimization: all primes > 3 are of form 6k±1
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
