class Solution {
    public double findZero(List<Double> xs) {
        // Use Newton-Raphson method to find a root
        // Start with initial guess
        double x = 1.0;

        // Maximum iterations and tolerance
        int maxIterations = 1000;
        double tolerance = 1e-10;

        for (int iter = 0; iter < maxIterations; iter++) {
            double fx = poly(xs, x);

            // If we're close enough to zero, return
            if (Math.abs(fx) < tolerance) {
                return x;
            }

            // Compute derivative numerically
            double h = 1e-8;
            double fpx = (poly(xs, x + h) - poly(xs, x - h)) / (2 * h);

            // Avoid division by zero or very small derivative
            if (Math.abs(fpx) < 1e-15) {
                // Try a different initial guess or small adjustment
                x += 0.1;
                continue;
            }

            // Newton-Raphson update
            double xNew = x - fx / fpx;

            // Check for convergence
            if (Math.abs(xNew - x) < tolerance) {
                // Verify it's actually a root
                if (Math.abs(poly(xs, xNew)) < tolerance) {
                    return xNew;
                }
            }

            x = xNew;

            // Handle overflow or divergence
            if (Double.isNaN(x) || Double.isInfinite(x)) {
                // Fallback to bisection between -1000 and 1000
                return bisectionMethod(xs, -1000.0, 1000.0, tolerance, maxIterations);
            }
        }

        // If Newton-Raphson failed, try bisection as fallback
        return bisectionMethod(xs, -1000.0, 1000.0, tolerance, maxIterations);
    }

    // Helper method for bisection when Newton-Raphson fails
    private double bisectionMethod(List<Double> xs, double a, double b, double tol, int maxIter) {
        double fa = poly(xs, a);
        double fb = poly(xs, b);

        // Ensure we have opposite signs (by IVT, for odd-degree polynomials, this should work)
        // If not, expand search range
        int attempts = 0;
        while (fa * fb > 0 && attempts < 10) {
            a *= 2;
            b *= 2;
            fa = poly(xs, a);
            fb = poly(xs, b);
            attempts++;
        }

        if (fa * fb > 0) {
            // Last resort: try random points
            for (int i = 0; i < 100; i++) {
                double testX = (Math.random() - 0.5) * 1000;
                if (Math.abs(poly(xs, testX)) < 1e-8) {
                    return testX;
                }
            }
            return a; // Give up and return something
        }

        for (int i = 0; i < maxIter; i++) {
            double mid = (a + b) / 2;
            double fm = poly(xs, mid);

            if (Math.abs(fm) < tol || (b - a) / 2 < tol) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2;
    }
}

