class Solution {
    /**
    Input to this function is a string representing musical notes in a special ASCII format.
    Your task is to parse this string and return list of integers corresponding to how many beats does each
    not last.

    Here is a legend:
    "o" - whole note, lasts four beats
    "o|" - half note, lasts two beats
    ".|" - quater note, lasts one beat

    >>> parseMusic("o o| .| o| o| .| .| .| .| o o")
    [4, 2, 1, 2, 2, 1, 1, 1, 1, 4, 4]
     */
    public List<Integer> parseMusic(String string) {
        List<Integer> result = new ArrayList<>();
        if (string == null || string.isEmpty()) {
            return result;
        }

        int i = 0;
        while (i < string.length()) {
            // Skip whitespace
            if (Character.isWhitespace(string.charAt(i))) {
                i++;
                continue;
            }

            // Check for note patterns
            char current = string.charAt(i);

            if (current == 'o') {
                // Could be "o" (whole note) or "o|" (half note)
                if (i + 1 < string.length() && string.charAt(i + 1) == '|') {
                    // "o|" - half note (2 beats)
                    result.add(2);
                    i += 2; // Skip both 'o' and '|'
                } else {
                    // "o" - whole note (4 beats)
                    result.add(4);
                    i += 1;
                }
            } else if (current == '.') {
                // Must be ".|" - quarter note (1 beat)
                if (i + 1 < string.length() && string.charAt(i + 1) == '|') {
                    result.add(1);
                    i += 2; // Skip both '.' and '|'
                } else {
                    // Invalid case, but skip the character to avoid infinite loop
                    i++;
                }
            } else {
                // Skip any other characters
                i++;
            }
        }

        return result;
    }
}

