class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Find the degree (highest power) - number of coefficients - 1
        int degree = xs.size() - 1;

        // For odd degree polynomials (even number of coefficients means odd degree),
        // there's guaranteed to be at least one real root

        // Use bisection method with expanding bounds until we find sign change
        double left = -1.0;
        double right = 1.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand bounds until we have a sign change
        int maxExpansions = 100;
        int expansions = 0;
        while (fLeft * fRight > 0 && expansions < maxExpansions) {
            if (Math.abs(fLeft) < Math.abs(fRight)) {
                left *= 2;
                fLeft = poly(xs, left);
            } else {
                right *= 2;
                fRight = poly(xs, right);
            }
            expansions++;
        }

        // If still no sign change, fallback to Newton-Raphson from 0
        if (fLeft * fRight > 0) {
            // Try Newton-Raphson starting from 0
            double x = 0.0;
            for (int i = 0; i < 100; i++) {
                double fx = poly(xs, x);
                if (Math.abs(fx) < 1e-12) {
                    return x;
                }
                // Compute derivative numerically
                double h = 1e-9;
                double fPrime = (poly(xs, x + h) - poly(xs, x - h)) / (2 * h);
                if (Math.abs(fPrime) < 1e-15) {
                    x += 0.1; // perturb if derivative too small
                    continue;
                }
                x = x - fx / fPrime;
                if (Double.isNaN(x) || Double.isInfinite(x)) {
                    // Fallback to bisection with wider bounds
                    left = -1000.0;
                    right = 1000.0;
                    break;
                }
            }
            if (Math.abs(poly(xs, x)) < 1e-8) {
                return x;
            }
            // Fall back to bisection
            left = -1000.0;
            right = 1000.0;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~30 decimal digits precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

