class Solution {
    /**
    Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> stringXor("010", "110")
    "100"
     */
    public String stringXor(String a, String b) {
        // Handle null cases
        if (a == null || b == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        // Get the maximum length and pad the shorter string with leading zeros
        int lenA = a.length();
        int lenB = b.length();
        int maxLen = Math.max(lenA, lenB);

        // Pad strings with leading zeros to make them equal length
        StringBuilder paddedA = new StringBuilder();
        for (int i = 0; i < maxLen - lenA; i++) {
            paddedA.append('0');
        }
        paddedA.append(a);

        StringBuilder paddedB = new StringBuilder();
        for (int i = 0; i < maxLen - lenB; i++) {
            paddedB.append('0');
        }
        paddedB.append(b);

        // Perform XOR operation
        StringBuilder result = new StringBuilder(maxLen);
        for (int i = 0; i < maxLen; i++) {
            char bitA = paddedA.charAt(i);
            char bitB = paddedB.charAt(i);

            // XOR: same bits give 0, different bits give 1
            if (bitA == bitB) {
                result.append('0');
            } else {
                result.append('1');
            }
        }

        return result.toString();
    }
}

