class Solution {
    public double findZero(List<Double> xs) {
        // Convert to array for easier access
        double[] coeffs = new double[xs.size()];
        for (int i = 0; i < xs.size(); i++) {
            coeffs[i] = xs.get(i);
        }

        // Find the degree (highest non-zero coefficient)
        int degree = coeffs.length - 1;
        while (degree > 0 && Math.abs(coeffs[degree]) < 1e-15) {
            degree--;
        }

        // For odd degree polynomials, we know there's at least one real root
        // Use bisection method with bounds based on Lagrange's bound
        double upperBound = 1.0;
        if (degree > 0) {
            double maxRatio = 0.0;
            for (int i = 0; i < degree; i++) {
                double ratio = Math.abs(coeffs[i] / coeffs[degree]);
                if (ratio > maxRatio) maxRatio = ratio;
            }
            upperBound = 1.0 + maxRatio;
        }

        // Search for interval where function changes sign
        double left = -upperBound;
        double right = upperBound;

        double fLeft = poly(coeffs, left);
        double fRight = poly(coeffs, right);

        // If no sign change, expand search range
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 20) {
            left *= 2;
            right *= 2;
            fLeft = poly(coeffs, left);
            fRight = poly(coeffs, right);
            attempts++;
        }

        // If still no sign change, use midpoint as fallback
        if (fLeft * fRight > 0) {
            return 0.0;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // enough iterations for precision
            double mid = (left + right) / 2.0;
            double fMid = poly(coeffs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }

    // Helper method for array coefficients (reuse poly logic)
    private double poly(double[] coeffs, double x) {
        double result = 0;
        double xPower = 1.0;
        for (double coeff : coeffs) {
            result += coeff * xPower;
            xPower *= x;
        }
        return result;
    }
}

