class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // For n <= 1, there's no proper divisor
        if (n <= 1) {
            return -1; // or handle as needed
        }

        // Start from n/2 and go downwards
        // The largest proper divisor cannot be larger than n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // This line is technically unreachable but included for safety
    }
}

