class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Find the leading coefficient (last non-zero element)
        int n = xs.size() - 1;
        double leadingCoeff = 0.0;
        for (int i = n; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-15) {
                leadingCoeff = xs.get(i);
                n = i; // actual degree
                break;
            }
        }

        // If all coefficients are zero, any x is a solution
        if (Math.abs(leadingCoeff) < 1e-15) {
            return 0.0;
        }

        // Define a search range using Cauchy's bound: |root| <= 1 + max(|a_i/a_n|)
        double maxRatio = 0;
        for (int i = 0; i < n; i++) {
            double ratio = Math.abs(xs.get(i) / leadingCoeff);
            if (ratio > maxRatio) {
                maxRatio = ratio;
            }
        }
        double bound = 1 + maxRatio;

        // Use bisection method on range [-bound, bound] extended for safety
        double left = -2 * bound - 10;
        double right = 2 * bound + 10;

        // Ensure we have opposite signs at endpoints
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // If both same sign, expand range until we get opposite signs
        int attempts = 0;
        while (fLeft * fRight > 0 && attempts < 50) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            attempts++;
        }

        // Bisection method
        double mid = 0;
        for (int i = 0; i < 100; i++) { // enough iterations for double precision
            mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                break;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return mid;
    }
}

