class Solution {
    public int fizzBuzz(int n) {
        int count = 0;

        for (int i = 0; i < n; i++) {
            if (i % 11 == 0 || i % 13 == 0) {
                // Count occurrences of digit 7 in i
                int num = i;
                if (num == 0) {
                    // 0 contains no digit 7
                    continue;
                }
                while (num > 0) {
                    if (num % 10 == 7) {
