class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // For n <= 1, there's no proper divisor smaller than n
        if (n <= 1) {
            return -1; // or handle as appropriate, but problem implies n > 1
        }

        // The largest proper divisor cannot exceed n/2
        // So we check from n/2 down to 1
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // This line should never be reached for n > 1,
        // since 1 always divides n
        return 1;
    }
}

