class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrtN = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
            // For Newton-Raphson, we need both the polynomial and its derivative
            // Start with initial guess
            double x = 0.0;

            // Try multiple starting points to increase chances of convergence
            double[] startingPoints = {0.0, 1.0, -1.0, 2.0, -2.0, 10.0, -10.0, 5.0, -5.0};

            for (double startX : startingPoints) {
                double currentX = startX;
                for (int iter = 0; iter < 100; iter++) {
                    double fx = poly(xs, currentX);

                    // If we're close enough to zero, return
                    if (Math.abs(fx) < 1e-10) {
                        return currentX;
                    }

                    // Compute derivative numerically
                    double h = 1e-7;
                    double fPrime = (poly(xs, currentX + h) - poly(xs, currentX - h)) / (2 * h);

                    // Avoid division by zero
                    if (Math.abs(fPrime) < 1e-10) {
                        break; // Try next starting point
                    }

                    double nextX = currentX - fx / fPrime;

                    // Check for divergence or NaN
                    if (Double.isNaN(nextX) || Double.isInfinite(nextX)) {
                        break;
                    }

                    currentX = nextX;
                }

                // Check if this iteration converged
                if (Math.abs(poly(xs, currentX)) < 1e-8) {
                    return currentX;
                }
            }

            // Fallback: try bisection on a reasonable interval
            // Since odd-degree polynomials go from -inf to +inf (or vice versa)
            double left = -1000.0;
            double right = 1000.0;
            double fLeft = poly(xs, left);
            double fRight = poly(xs, right);

            // If signs are different, bisection will work
            if (fLeft * fRight < 0) {
                for (int i = 0; i < 100; i++) {
                    double mid = (left + right) / 2;
                    double fMid = poly(xs, mid);

                    if (Math.abs(fMid) < 1e-10) {
                        return mid;
                    }

                    if (fLeft * fMid < 0) {
                        right = mid;
                        fRight = fMid;
                    } else {
                        left = mid;
                        fLeft = fMid;
                    }
                }
                return (left + right) / 2;
            }

            // Last resort: return the best we found
            double bestX = 0.0;
            double bestVal = Double.MAX_VALUE;
            for (double testX = -10; testX <= 10; testX += 0.5) {
                double val = Math.abs(poly(xs, testX));
                if (val < bestVal) {
                    bestVal = val;
                    bestX = testX;
                }
            }
            return bestX;
        }
}

