class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return -1; // No proper divisors for 1 or less
        }

        // Start from n/2 and go down, since the largest proper divisor 
        // cannot exceed n/2 (for n > 1)
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // Fallback (shouldn't reach here for n > 1)
    }
}

