class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle degree 1 case directly
        if (xs.size() == 2) {
            return -xs.get(0) / xs.get(1);
        }

        // Newton-Raphson with multiple starting points for robustness
        double x = 1.0;
        for (int attempt = 0; attempt < 3; attempt++) {
            double currentX = x + (attempt == 0 ? 0 : (attempt == 1 ? -1.0 : 10.0));
            double prevX = Double.POSITIVE_INFINITY;
            for (int iter = 0; iter < 100; iter++) {
                double fx = poly(xs, currentX);
                // Compute derivative
                double fpx = 0;
                for (int i = 1; i < xs.size(); i++) {
                    fpx += i * xs.get(i) * Math.pow(currentX, i - 1);
                }

                if (Math.abs(fpx) < 1e-12) {
                    // Derivative too small, try different start
                    break;
                }

                double nextX = currentX - fx / fpx;

                if (Double.isNaN(nextX) || Double.isInfinite(nextX)) {
                    break;
                }

                if (Math.abs(nextX - currentX) < 1e-9) {
                    // Converged
                    if (Math.abs(poly(xs, nextX)) < 1e-8) {
                        return nextX;
                    }
                }

                prevX = currentX;
                currentX = nextX;
            }
        }

        // Fallback: try bisection in range [-1000, 1000]
        double left = -1000.0;
        double right = 1000.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Ensure we have a sign change
        if (fLeft * fRight > 0) {
            // Expand search range
            for (int i = 0; i < 10; i++) {
                left *= 2;
                right *= 2;
                fLeft = poly(xs, left);
                fRight = poly(xs, right);
                if (fLeft * fRight <= 0) {
                    break;
                }
            }
        }

        // Bisection method
        for (int iter = 0; iter < 100; iter++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-9 || (right - left) < 1e-9) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2;
    }
}

