    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is prime
        if (n == 2) {
            return true;
        }

        // Even numbers > 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Create a lambda for evaluating the polynomial
        java.util.function.DoubleUnaryOperator f = x -> poly(xs, x);

        // Find the leading coefficient (last non-zero coefficient)
        int n = xs.size();
        double leadingCoeff = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-15) {
                leadingCoeff = xs.get(i);
                break;
            }
        }

        // Determine search direction based on leading coefficient
        // We'll search for an interval [a, b] where f(a)*f(b) < 0
        double step = 1.0;
        double a = 0.0;
        double fa = f.applyAsDouble(a);

        // Expand outward until we find opposite signs
        double b = step;
        double fb = f.applyAsDouble(b);

        // If same sign, expand in both directions
        while (fa * fb > 0 && step < 1e9) {
            // Try negative side too
            double aneg = -step;
            double faneg = f.applyAsDouble(aneg);

            if (fa * faneg <= 0) {
                b = a;
                fb = fa;
                a = aneg;
                fa = faneg;
                break;
            } else if (fb * faneg <= 0) {
                // fb and faneg have opposite signs
                a = aneg;
                fa = faneg;
                break;
            }

            step *= 2;
            b = step;
            fb = f.applyAsDouble(b);
        }

        // If still no sign change, fallback to bisection on large interval
        if (fa * fb > 0) {
            a = -1e9;
            b = 1e9;
            fa = f.applyAsDouble(a);
            fb = f.applyAsDouble(b);
        }

        // Now apply bisection method
        final double EPSILON = 1e-9;
        while (Math.abs(b - a) > EPSILON * (Math.abs(a) + Math.abs(b) + 1)) {
            double mid = (a + b) / 2.0;
            double fmid = f.applyAsDouble(mid);

            if (Math.abs(fmid) < EPSILON) {
                return mid;
            }

            if (fa * fmid <= 0) {
                b = mid;
                fb = fmid;
            } else {
                a = mid;
                fa = fmid;
            }
        }

        return (a + b) / 2.0;
    }
}

