class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Handle small cases directly for efficiency
        if (n == 1) return 2;
        if (n == 2) return 3;
        if (n == 3) return 5;
        if (n == 4) return 13;
        if (n == 5) return 89;

        // Generate Fibonacci numbers and check for primality
        int count = 5; // We already found the first 5: 2, 3, 5, 13, 89

        long prev2 = 5;  // F(5) = 5
        long prev1 = 13; // F(7) = 13
        long current = 34; // Start from F(9) = 34

        while (true) {
            // Calculate next Fibonacci number
            long next = prev2 + prev1;
            prev2 = prev1;
            prev1 = current;
            current = next;

            // Check if it's prime
            if (isPrime(current)) {
                count++;
                if (count == n) {
                    return (int) current;
                }
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0) return false;
        if (num % 3 == 0) return num == 3;

        // Check divisibility by numbers of form 6k ± 1
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

