    public List<Integer> sortThird(List<Integer> l) {
        // Create a copy of the input list to avoid modifying the original
        List<Integer> result = new ArrayList<>(l);

        // Collect values at indices divisible by 3 (0, 3, 6, ...)
        List<Integer> thirdValues = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 3) {
            thirdValues.add(l.get(i));
        }

        // Sort the collected values
        Collections.sort(thirdValues);

        // Put the sorted values back into their positions
        int sortedIndex = 0;
        for (int i = 0; i < result.size(); i += 3) {
            result.set(i, thirdValues.get(sortedIndex++));
        }

        return result;
    }
}

