        if (string == null || string.trim().isEmpty()) {
            return new ArrayList<>();
        }

        String[] notes = string.trim().split("\\s+");
        List<Integer> result = new ArrayList<>();

        for (String note : notes) {
            switch (note) {
                case "o":
                    result.add(4);
                    break;
                case "o|":
                    result.add(2);
                    break;
                case ".|":
                    result.add(1);
                    break;
                default:
                    // Optional: handle invalid notes or throw exception
                    // For now, we'll skip invalid notes or could add 0
                    // Based on the problem statement, we assume valid input
                    break;
            }
        }

        return result;
    }
}

