class Solution {
    public double findZero(List<Double> xs) {
        // Validate input: even number of coefficients
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Check that the leading coefficient (highest degree) is non-zero
        boolean hasNonZeroLeading = false;
        for (int i = xs.size() - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) {
                hasNonZeroLeading = true;
                break;
            }
        }
        if (!hasNonZeroLeading) {
            throw new IllegalArgumentException("Leading coefficient must be non-zero");
        }

        // Use bisection method to find a root
        double left = -1000.0;
        double right = 1000.0;
        double tolerance = 1e-9;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double mid = (left + right) / 2.0;
            double valueAtMid = poly(xs, mid);

            if (Math.abs(valueAtMid) < tolerance) {
                return mid;
            }

            double valueAtLeft = poly(xs, left);

            // Check if root is in left half or right half
            if (valueAtLeft * valueAtMid <= 0) {
                right = mid;
            } else {
                left = mid;
            }

            // Check interval width
            if (right - left < tolerance) {
                return (left + right) / 2.0;
            }
        }

        // Fallback: return midpoint of final interval
        return (left + right) / 2.0;
    }
}

