class Solution {
    /**
    primeFib returns n-th number that is a Fibonacci number and it's also prime.
    >>> primeFib(1)
    2
    >>> primeFib(2)
    3
    >>> primeFib(3)
    5
    >>> primeFib(4)
    13
    >>> primeFib(5)
    89
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        int count = 0;
        long a = 0; // F(0)
        long b = 1; // F(1)

        // Handle special case: F(0)=0, F(1)=1, F(2)=1, F(3)=2, ...
        // We start from the beginning of Fibonacci sequence

        if (n == 1) return 2;

        // Generate Fibonacci numbers until we find n prime ones
        while (true) {
            long next = a + b;
            a = b;
            b = next;

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return (int) next;
                }
            }

            // Safety check for large numbers - though for n up to reasonable values this won't overflow int
            if (next > Integer.MAX_VALUE) {
                throw new ArithmeticException("Result exceeds Integer.MAX_VALUE");
            }
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0) return false;

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

