class Solution {
    public double findZero(List<Double> xs) {
        // Convert to array for faster access
        double[] coeffs = new double[xs.size()];
        for (int i = 0; i < xs.size(); i++) {
            coeffs[i] = xs.get(i);
        }

        // Find the degree (highest non-zero coefficient index)
        int degree = coeffs.length - 1;
        while (degree > 0 && Math.abs(coeffs[degree]) < 1e-15) {
            degree--;
        }

        // For odd degree polynomials, we know limits at ±∞
        // We need to find an interval [a, b] where f(a)*f(b) < 0

        double a = -1000.0;
        double b = 1000.0;
        double fa = evaluatePoly(coeffs, a);
        double fb = evaluatePoly(coeffs, b);

        // Expand search range until we find opposite signs
        int attempts = 0;
        while (fa * fb >= 0 && attempts < 30) {
            a *= 2;
            b *= 2;
            fa = evaluatePoly(coeffs, a);
            fb = evaluatePoly(coeffs, b);
            attempts++;
        }

        // If still no sign change, use midpoint as fallback (shouldn't happen with guaranteed root)
        if (fa * fb >= 0) {
            return 0.0;
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives ~1e-30 precision
            double mid = (a + b) / 2.0;
            double fm = evaluatePoly(coeffs, mid);

            if (Math.abs(fm) < 1e-12 || (b - a) < 1e-12) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2.0;
    }

    private double evaluatePoly(double[] coeffs, double x) {
        double result = 0;
        double xPower = 1;
        for (int i = 0; i < coeffs.length; i++) {
            result += coeffs[i] * xPower;
            xPower *= x;
        }
        return result;
    }
}

