class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases - if n <= 1, no proper divisor exists
        if (n <= 1) {
            throw new IllegalArgumentException("n must be greater than 1");
        }

        // Start from n/2 and go down to 1
        // The first divisor we find will be the largest proper divisor
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // This should never happen for n > 1, since 1 always divides n
        return 1;
    }
}

