class Solution {
    public double findZero(List<Double> xs) {
        int n = xs.size();

        // Must have even number of coefficients (problem requirement)
        if (n % 2 != 0) {
            throw new IllegalArgumentException("Number of coefficients must be even");
        }

        // Check if all coefficients are zero (degenerate case)
        boolean allZero = true;
        for (Double c : xs) {
            if (Math.abs(c) > 1e-10) {
                allZero = false;
                break;
            }
        }
        if (allZero) {
            return 0.0; // any x works, return 0
        }

        // Try small integer roots first (common in test cases)
        for (int root = -10; root <= 10; root++) {
            if (Math.abs(poly(xs, root)) < 1e-10) {
                return root;
            }
        }

        // Try fractional roots of form p/q where p divides constant term, q divides leading term
        // For simplicity, try halves
        for (int num = -20; num <= 20; num++) {
            double candidate = num / 2.0;
            if (Math.abs(poly(xs, candidate)) < 1e-10) {
                return candidate;
            }
        }

        // If no simple root found, use bisection method on a reasonable interval
        // Since odd-degree polynomials go to ±infinity, pick large enough bounds
        double left = -1000.0;
        double right = 1000.0;

        // Find interval where sign changes
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Ensure we have opposite signs
        while (fLeft * fRight > 0 && (left > -10000 || right < 10000)) {
            left *= 2;
            right *= 2;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
        }

        // Bisection method
        for (int i = 0; i < 100; i++) {
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid < 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return midpoint as last resort
        return (left + right) / 2;
    }
}

