        // Create result list with appropriate capacity
        List<Integer> result = new ArrayList<>(numbers.size() * 2 - 1);

        // Add first element, then delimiter + remaining elements
        for (int i = 0; i < numbers.size(); i++) {
            result.add(numbers.get(i));
            // Add delimiter after each element except the last one
            if (i < numbers.size() - 1) {
                result.add(delimiter);
            }
        }

        return result;
    }
}

