class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        if (n <= 1) {
            return -1; // or throw IllegalArgumentException, as no proper divisors exist
        }

        // Start from n/2 and go downwards - the first divisor we find is the largest
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // This should never be reached for n > 1, but included for completeness
    }
}

