class Solution {
    public double findZero(List<Double> xs) {
        // Use bisection method
        // First, evaluate at some points to find sign change
        double left = -1000.0;
        double right = 1000.0;

        // Expand bounds if needed until we find sign change
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 2;
            right *= 2;
            // Safety limit to avoid infinite loop
            if (Math.abs(left) > 1e10) {
                break;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations for precision
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-10) {
                return mid;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return (left + right) / 2;
    }
}

