class Solution {
    /**
    Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    separate those group into separate strings and return the list of those.
    Separate groups are balanced (each open brace is properly closed) and not nested within each other
    Ignore any spaces in the input string.
    >>> separateParenGroups("( ) (( )) (( )( ))")
    ["()", "(())", "(()())"]
     */
    public List<String> separateParenGroups(String paren_string) {
        List<String> result = new ArrayList<>();

        // Remove all spaces
        String cleaned = paren_string.replace(" ", "");

        int start = 0;  // start index of current group
        int depth = 0;  // current nesting depth

        for (int i = 0; i < cleaned.length(); i++) {
            char c = cleaned.charAt(i);

            if (c == '(') {
                depth++;
                // If this is the first '(' of a new group, mark start
                if (depth == 1) {
                    start = i;
                }
            } else if (c == ')') {
                depth--;
                // When depth becomes 0, we've completed a balanced group
                if (depth == 0) {
                    result.add(cleaned.substring(start, i + 1));
                }
            }
        }

        return result;
    }
}

