class Solution {
    /**
     * Out of list of strings, return the longest one. Return the first one in case of multiple
     * strings of the same length. Return Optional.empty() in case the input list is empty.
     * 
     * >>> longest(List.of())
     * Optional.empty
     * >>> longest(Arrays.asList("a", "b", "c"))
     * Optional[a]
     * >>> longest(Arrays.asList("a", "bb", "ccc"))
     * Optional[ccc]
     */
    public Optional<String> longest(List<String> strings) {
        if (strings == null || strings.isEmpty()) {
            return Optional.empty();
        }

        String longest = strings.get(0);
        for (int i = 1; i < strings.size(); i++) {
            String current = strings.get(i);
            // If current string is longer than the longest so far, update
            if (current != null && (longest == null || current.length() > longest.length())) {
                longest = current;
            } else if (current != null && longest == null) {
                // If longest is null but current is not, set current as longest
                longest = current;
            }
            // Note: if both are null or current.length() <= longest.length(), keep longest
        }

        return Optional.ofNullable(longest);
    }
}

