class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return -1; // or throw exception, as 1 has no proper divisors
        }

        // For any n > 1, the largest proper divisor is n divided by its smallest prime factor
        // We can find the smallest prime factor by checking from 2 upward
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                // i is the smallest prime factor, so n/i is the largest proper divisor
                return n / i;
            }
        }

        // If no divisor found, n is prime, so the largest proper divisor is 1
        return 1;
    }
}

