import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Trim trailing zeros (leading coefficients for higher powers)
        int n = xs.size();
        int lastNonZero = -1;
        for (int i = n - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) {
                lastNonZero = i;
                break;
            }
        }
        if (lastNonZero < 0) {
            // All coefficients zero - any x is a root
            return 0.0;
        }

        // Create a list with only significant coefficients
        List<Double> coeffs = xs.subList(0, lastNonZero + 1);

        // The degree is lastNonZero (since xs[0] is constant, xs[lastNonZero] is x^lastNonZero)
        // We need odd degree for guaranteed real root
        int degree = lastNonZero;

        // Bisection method on interval [-bound, bound]
        double left = -1000.0;
        double right = 1000.0;
        double tolerance = 1e-9;
        int maxIterations = 1000;

        for (int iter = 0; iter < maxIterations; iter++) {
            double mid = (left + right) / 2.0;
            double fMid = poly(coeffs, mid);

            if (Math.abs(fMid) < tolerance) {
                return mid;
            }

            double fLeft = poly(coeffs, left);
            if (fLeft * fMid <= 0) {
                right = mid;
            } else {
                left = mid;
            }

            // Check interval width
            if (right - left < tolerance) {
                return (left + right) / 2.0;
            }
        }

        // Fallback: return midpoint of final interval
        return (left + right) / 2.0;
    }
}

