    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases: numbers <= 1 are not prime
        if (n <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (n == 2) {
            return true;
        }

        // All other even numbers are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrtN = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrtN; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Handle linear case directly: a + bx = 0 => x = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            if (Math.abs(b) < 1e-12) {
                throw new IllegalArgumentException("No unique solution: coefficient of x is zero");
            }
            return -a / b;
        }

        // For higher degrees, use Newton-Raphson
        List<Double> coeffs = new ArrayList<>(xs);
        int n = coeffs.size() - 1; // degree of polynomial

        // Compute derivative coefficients
        List<Double> derivCoeffs = new ArrayList<>();
        for (int i = 1; i < coeffs.size(); i++) {
            derivCoeffs.add(coeffs.get(i) * i);
        }

        // Newton-Raphson with multiple starting points
        double[] starts = {0.0, 1.0, -1.0, 2.0, -2.0, 0.5, -0.5, 3.0, -3.0};

        for (double start : starts) {
            double x = start;
            for (int iter = 0; iter < 50; iter++) {
                double fx = poly(coeffs, x);
                if (Math.abs(fx) < 1e-10) {
                    return x;
                }

                double fpx = poly(derivCoeffs, x);
                if (Math.abs(fpx) < 1e-12) {
                    break; // derivative too small, skip this start
                }

                double xNext = x - fx / fpx;

                // Check for NaN or overflow
                if (Double.isNaN(xNext) || Double.isInfinite(xNext)) {
                    break;
                }

                // If function value not decreasing significantly, break
                double fxNext = poly(coeffs, xNext);
                if (Math.abs(fxNext) >= Math.abs(fx) && iter > 0) {
                    break;
                }

                x = xNext;
            }
        }

        // Fallback: try bisection between -100 and 100
        double left = -100.0;
        double right = 100.0;
        double fLeft = poly(coeffs, left);
        double fRight = poly(coeffs, right);

        // Find interval where sign changes
        while (fLeft * fRight > 0 && (right - left) > 1) {
            left *= 2;
            right *= 2;
            fLeft = poly(coeffs, left);
            fRight = poly(coeffs, right);
            if (Math.abs(left) > 1e6) {
                break;
            }
        }

        // Bisection if sign change found
        if (fLeft * fRight <= 0) {
            for (int i = 0; i < 100; i++) {
                double mid = (left + right) / 2;
                double fMid = poly(coeffs, mid);
                if (Math.abs(fMid) < 1e-10) {
                    return mid;
                }
                if (fLeft * fMid <= 0) {
                    right = mid;
                } else {
                    left = mid;
                    fLeft = fMid;
                }
            }
        }

        // Last resort: return midpoint of search range
        return (left + right) / 2;
    }
}

