                depth++;
            } else if (c == ')') {
                depth--;
                if (depth == 0) {
                    // End of a complete group
                    result.add(cleaned.substring(start, i + 1));
                }
            }
            // Ignore any other characters (though problem says only parentheses and spaces)
        }

        return result;
    }
}

