    [1, 4, 2, 4, 3]
     */
    public List<Integer> intersperse(List<Integer> numbers, int delimiter) {
        // Handle null input (defensive programming)
        if (numbers == null) {
            throw new IllegalArgumentException("Input list cannot be null");
        }

        // Create a result list with appropriate capacity
        // Size will be: original size + (original size - 1) if size > 0
        int expectedSize = numbers.isEmpty() ? 0 : numbers.size() * 2 - 1;
        List<Integer> result = new ArrayList<>(expectedSize);

        // Iterate through the original list
        for (int i = 0; i < numbers.size(); i++) {
            // Add the current element
            result.add(numbers.get(i));

            // If this is not the last element, add the delimiter
            if (i < numbers.size() - 1) {
                result.add(delimiter);
            }
        }

        return result;
    }
}

