class Solution {
    /**
    Find how many times a given substring can be found in the original string. Count overlaping cases.
    >>> howManyTimes("", "a")
    0
    >>> howManyTimes("aaa", "a")
    3
    >>> howManyTimes("aaaa", "aa")
    3
     */
    public int howManyTimes(String string, String substring) {
        // Handle edge cases
        if (substring == null || substring.isEmpty()) {
            return 0;
        }
        if (string == null || string.length() < substring.length()) {
            return 0;
        }

        int count = 0;
        int index = 0;

        // Use indexOf with start index to find all occurrences including overlaps
        while ((index = string.indexOf(substring, index)) != -1) {
            count++;
            index++; // Move only one position forward to allow overlapping matches
        }

        return count;
    }
}

