class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Numbers less than 2 are not prime
        if (n < 2) {
            return false;
        }

        // 2 is the only even prime number
        if (n == 2) {
            return true;
        }

        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 up to sqrt(n)
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    public double findZero(List<Double> xs) {
        // Bisection method with interval expansion
        double left = -1.0;
        double right = 1.0;
        double fLeft = poly(xs, left);
        double fRight = poly(xs, right);

        // Expand interval until sign change (guaranteed for odd-degree polynomials)
        while (fLeft * fRight >= 0) {
            left *= 2.0;
            right *= 2.0;
            fLeft = poly(xs, left);
            fRight = poly(xs, right);
            // Safety bound to avoid infinite loop (should not happen per problem guarantee)
            if (Math.abs(left) > 1e9) {
                // fallback: return mid of current interval
                return (left + right) / 2.0;
            }
        }

        // Bisection
        for (int i = 0; i < 100; i++) { // enough iterations for double precision
            double mid = (left + right) / 2.0;
            double fMid = poly(xs, mid);
            if (Math.abs(fMid) < 1e-12 || Math.abs(right - left) < 1e-12) {
                return mid;
            }
            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        return (left + right) / 2.0;
    }
}

