class Solution {
    /**
    Return maximum element in the list.
    >>> maxElement(Arrays.asList(1, 2, 3))
    3
    >>> maxElement(Arrays.asList(5, 3, -5, 2, -3, 3, 9, 0, 123, 1, -10))
    123
     */
    public int maxElement(List<Integer> l) {
        if (l == null || l.isEmpty()) {
            throw new IllegalArgumentException("List must not be null or empty");
        }

        Integer max = l.get(0);
        for (Integer num : l) {
            // Skip null values if any (defensive programming)
            if (num == null) {
                continue;
            }
            if (max == null || num > max) {
                max = num;
            }
        }

        // If all elements were null, we'd have max as null
        if (max == null) {
            throw new IllegalArgumentException("List contains no non-null elements");
        }

        return max;
    }
}

