        // Split input string into words
        String[] words = numbers.trim().split("\\s+");

        // Sort based on numeric value using custom comparator
        Arrays.sort(words, (a, b) -> {
            return wordToDigit.get(a).compareTo(wordToDigit.get(b));
        });

        // Join sorted words back into string
        return String.join(" ", words);
    }
}

