class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Edge cases: for n <= 1, there's no proper divisor
        if (n <= 1) {
            return -1; // or throw exception, but problem implies n >= 2
        }

        // The largest proper divisor cannot be larger than n/2
        // Start from n/2 and go downwards to find the first divisor
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        return 1; // This will only happen for n=2, where 1 is the answer
    }
}

