class Solution {
    public double findZero(List<Double> xs) {
        // For linear case: [a, b] -> root = -a/b
        if (xs.size() == 2) {
            double a = xs.get(0);
            double b = xs.get(1);
            return -a / b;
        }

        // Use Newton-Raphson method
        double x = 1.0; // initial guess
        for (int i = 0; i < 100; i++) { // max iterations
            double fx = poly(xs, x);
            if (Math.abs(fx) < 1e-9) {
                return x;
            }

            // Compute derivative
            List<Double> deriv = new ArrayList<>();
            for (int j = 1; j < xs.size(); j++) {
                deriv.add(xs.get(j) * j);
            }
            double fpx = poly(deriv, x);

            if (Math.abs(fpx) < 1e-12) {
                // Derivative too small, adjust x slightly
                x += 0.1;
                continue;
            }

            double xNew = x - fx / fpx;
            if (Double.isNaN(xNew) || Double.isInfinite(xNew)) {
                // Fallback: small perturbation
                x += 0.1;
            } else {
                x = xNew;
            }
        }

        // If not converged, return best approximation
        return x;
    }
}

