class Solution {
    /**
    Return true if a given number is prime, and false otherwise.
    >>> isPrime(6)
    false
    >>> isPrime(101)
    true
    >>> isPrime(11)
    true
    >>> isPrime(13441)
    true
    >>> isPrime(61)
    true
    >>> isPrime(4)
    false
    >>> isPrime(1)
    false
     */
    public boolean isPrime(int n) {
        // Handle edge cases
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        // Even numbers greater than 2 are not prime
        if (n % 2 == 0) {
            return false;
        }

        // Check odd divisors from 3 to sqrt(n)
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
     */
    public double poly(List<Double> xs, double x) {
        double result = 0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
    xs are coefficients of a polynomial.
    findZero find x such that poly(x) = 0.
    findZero returns only only zero point, even if there are many.
    Moreover, findZero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> findZero(Arrays.asList(1, 2)) // f(x) = 1 + 2x
    -0.5
    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
        int n = xs.size();
        // Even number of coefficients means odd degree (n-1)
        if (n == 2) {
            // Linear case: a + bx = 0 => x = -a/b
            double a = xs.get(0);
            double b = xs.get(1);
            return -a / b;
        }

        // For higher degree polynomials, use bisection method
        // Since odd degree polynomials go to ±∞ at ±∞, we can find bounds

        double left = -1000.0;
        double right = 1000.0;

        // Expand search range until we find sign change
        while (poly(xs, left) * poly(xs, right) > 0) {
            left *= 2;
            right *= 2;
            // Prevent infinite loop if something goes wrong
            if (Math.abs(left) > 1e10) {
                break;
            }
        }

        // Bisection method
        for (int i = 0; i < 100; i++) { // 100 iterations gives good precision
            double mid = (left + right) / 2;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-9) {
                return mid;
            }

            if (poly(xs, left) * fMid < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        // Return midpoint of final interval
        return (left + right) / 2;
    }
}

