class Solution {
    /**
    Check if in given list of numbers, are any two numbers closer to each other than given threshold.
    >>> hasCloseElements(Arrays.asList(1.0, 2.0, 3.0), 0.5)
    false
    >>> hasCloseElements(Arrays.asList(1.0, 2.8, 3.0, 4.0, 5.0, 2.0), 0.3)
    true
     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        if (numbers == null || numbers.size() < 2) {
            return false;
        }

        // Create a copy to avoid modifying the original list
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        // Check adjacent pairs only - if any pair is closer than threshold, return true
        for (int i = 0; i < sorted.size() - 1; i++) {
            double diff = Math.abs(sorted.get(i + 1) - sorted.get(i));
            if (diff < threshold) {
                return true;
            }
        }

        return false;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
     * Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
     * separate those group into separate strings and return the list of those.
     * Separate groups are balanced (each open brace is properly closed) and not nested within each other
     * Ignore any spaces in the input string.
     * >>> separateParenGroups("( ) (( )) (( )( ))")
     * ["()", "(())", "(()())"]
     */
    public List<String> separateParenGroups(String paren_string) {
        List<String> result = new ArrayList<>();

        // Remove all spaces
        String cleaned = paren_string.replace(" ", "");

        int depth = 0;
        StringBuilder currentGroup = new StringBuilder();

        for (char c : cleaned.toCharArray()) {
            if (c == '(') {
                // Start a new group or continue current one
                if (depth == 0) {
                    currentGroup = new StringBuilder();
                }
                currentGroup.append(c);
                depth++;
            } else if (c == ')') {
                currentGroup.append(c);
                depth--;

                // When depth returns to 0, we've completed a balanced group
                if (depth == 0) {
                    result.add(currentGroup.toString());
                }
            }
        }

        return result;
    }
}

