    public double findZero(List<Double> xs) {
        if (xs == null || xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Find the largest non-zero coefficient (from highest degree term)
        int degree = -1;
        double leadingCoeff = 0.0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-15) { // non-zero tolerance
                degree = i;
                leadingCoeff = xs.get(i);
                break;
            }
        }

        if (degree == -1) {
            throw new IllegalArgumentException("All coefficients are zero - no unique polynomial");
        }

        // For odd-degree polynomials, we know there's at least one real root
        // Use bisection method with appropriate bounds

        // Determine search bounds based on leading coefficient
        // For large |x|, the polynomial behaves like leadingCoeff * x^degree
        // We want to find a and b such that p(a) * p(b) < 0

        double bound = 1.0;
        // Increase bound until we get sign change
        while (true) {
            double pNeg = poly(xs, -bound);
            double pPos = poly(xs, bound);

            if (pNeg * pPos <= 0) {
                // Sign change detected or one is zero
                break;
            }

            bound *= 2.0;

            // Safety limit to prevent infinite loop
            if (bound > 1e9) {
                throw new RuntimeException("Could not find bracketing interval");
            }
        }

        // Bisection method
        double left = -bound;
        double right = bound;
        double mid = 0;

        for (int i = 0; i < 100; i++) { // sufficient iterations for double precision
            mid = (left + right) / 2.0;
            double value = poly(xs, mid);

            if (Math.abs(value) < 1e-12) {
                break;
            }

            double leftValue = poly(xs, left);
            if (leftValue * value < 0) {
                right = mid;
            } else {
                left = mid;
            }
        }

        return mid;
    }
}

