        numMap.put("five", 5);
        numMap.put("six", 6);
        numMap.put("seven", 7);
        numMap.put("eight", 8);
        numMap.put("nine", 9);

        // Split input string into words
        String[] words = numbers.split(" ");

        // Sort words based on their numeric values
        Arrays.sort(words, (a, b) -> numMap.get(a).compareTo(numMap.get(b)));

        // Join back into a space-delimited string
        return String.join(" ", words);
    }
}

