class Solution {
    /**
     * For a given number n, find the largest number that divides n evenly, smaller than n
     * >>> largestDivisor(15)
     * 5
     */
    public int largestDivisor(int n) {
        // Handle edge cases
        if (n <= 1) {
            return 0; // No proper divisors for 1 or non-positive numbers
        }

        // If n is even, the largest proper divisor is n/2
        if (n % 2 == 0) {
            return n / 2;
        }

        // For odd n, find the smallest divisor starting from 3
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return n / i; // n/i is the largest proper divisor
            }
        }

        // If no divisor found, n is prime, so largest proper divisor is 1
        return 1;
    }
}

