class Solution {
    public double findZero(List<Double> xs) {
        // Remove trailing zeros to get actual degree
        List<Double> coeffs = new ArrayList<>();
        int n = xs.size();
        // Find last non-zero coefficient
        int lastNonZero = -1;
        for (int i = n - 1; i >= 0; i--) {
            if (Math.abs(xs.get(i)) > 1e-12) {
                lastNonZero = i;
                break;
            }
        }
        // If all coefficients are zero, polynomial is zero everywhere
        // but problem guarantees solution exists, so assume not all zero
        if (lastNonZero == -1) {
            return 0.0; // degenerate case
        }

        // Copy up to last non-zero coefficient
        for (int i = 0; i <= lastNonZero; i++) {
            coeffs.add(xs.get(i));
        }

        // Now coeffs represents: c0 + c1*x + ... + c_d*x^d where d = lastNonZero
        int degree = lastNonZero;

        // For odd degree polynomials, we know there's at least one real root
        // Use bisection method

        // Define the polynomial function as lambda
        java.util.function.DoubleUnaryOperator polyFunc = x -> {
            double result = 0;
            double xPower = 1;
            for (double coeff : coeffs) {
                result += coeff * xPower;
                xPower *= x;
            }
            return result;
        };

        // Find an interval [a, b] where f(a) * f(b) < 0
        double a = -10.0;
        double b = 10.0;
        double fa = polyFunc.applyAsDouble(a);
        double fb = polyFunc.applyAsDouble(b);

        // Expand interval until we find sign change
        int attempts = 0;
        while (fa * fb > 0 && attempts < 30) {
            a *= 10;
            b *= 10;
            fa = polyFunc.applyAsDouble(a);
            fb = polyFunc.applyAsDouble(b);
            attempts++;
        }

        // If still same sign, return mid-point as fallback (shouldn't happen for odd degree)
        if (fa * fb > 0) {
            return 0.0;
        }

        // Bisection method
        double tolerance = 1e-9;
        int maxIterations = 100;
        for (int i = 0; i < maxIterations; i++) {
            double mid = (a + b) / 2;
            double fm = polyFunc.applyAsDouble(mid);

            if (Math.abs(fm) < tolerance || (b - a) / 2 < tolerance) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2;
    }
}

