class Solution {
    public double findZero(List<Double> xs) {
        // Handle edge cases
        if (xs == null || xs.isEmpty()) {
            return 0.0;
        }

        // Ensure even number of coefficients as per requirement
        if (xs.size() % 2 != 0) {
            throw new IllegalArgumentException("List must have even number of coefficients");
        }

        // Bisection parameters
        double low = -10000.0;
        double high = 10000.0;
        double tolerance = 1e-9;
        int maxIterations = 1000;

        // Expand interval until we find sign change (guaranteed for odd-degree polynomial)
        double fLow = poly(xs, low);
        double fHigh = poly(xs, high);

        // Try expanding interval if same sign
        int expandAttempts = 0;
        while (fLow * fHigh > 0 && expandAttempts < 20) {
            low *= 10;
            high *= 10;
            fLow = poly(xs, low);
            fHigh = poly(xs, high);
            expandAttempts++;
        }

        // Bisection method
        for (int i = 0; i < maxIterations; i++) {
            double mid = (low + high) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < tolerance || (high - low) / 2.0 < tolerance) {
                return mid;
            }

            if (fLow * fMid <= 0) {
                high = mid;
                fHigh = fMid;
            } else {
                low = mid;
                fLow = fMid;
            }
        }

        // Fallback: return midpoint of final interval
        return (low + high) / 2.0;
    }
}

