}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largestDivisor(15)
    5
     */
    public int largestDivisor(int n) {
        // Handle edge case - though problem likely assumes n > 1
        if (n <= 1) {
            return 1; // or throw exception, but 1 is reasonable fallback
        }

        // Check for smallest divisor from 2 to sqrt(n)
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                // i is the smallest divisor > 1, so n/i is the largest proper divisor
                return n / i;
            }
        }

        // If no divisor found, n is prime, so largest proper divisor is 1
        return 1;
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Return list of prime factors of given integer in the order from smallest to largest.
    Each of the factors should be listed number of times corresponding to how many times it appeares in factorization.
    Input number should be equal to the product of all factors
    >>> factorize(8)
    [2, 2, 2]
    >>> factorize(25)
    [5, 5]
    >>> factorize(70)
    [2, 5, 7]
     */
    public List<Integer> factorize(int n) {
        List<Integer> factors = new ArrayList<>();

        // Handle edge case: n <= 1 has no prime factors
        if (n <= 1) {
            return factors;
        }

        // Check for factor 2 first (even numbers)
        while (n % 2 == 0) {
            factors.add(2);
            n /= 2;
        }

        // Check for odd factors starting from 3
        // Only need to check up to sqrt(n) because if n has a factor > sqrt(n),
        // it must have a corresponding factor < sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }

        // If n is still greater than 1, then it's a prime factor itself
        if (n > 1) {
            factors.add(n);
        }

        return factors;
    }
}

import java.util.*;
import java.lang.*;
import java.util.stream.Collectors;

class Solution {
    /**
    From a list of integers, remove all elements that occur more than once.
    Keep order of elements left the same as in the input.
    >>> removeDuplicates(Array.asList(1, 2, 3, 2, 4))
    [1, 3, 4]
     */
    public List<Integer> removeDuplicates(List<Integer> numbers) {
        if (numbers == null || numbers.isEmpty()) {
            return new ArrayList<>();
        }

        // Count frequency of each element
        Map<Integer, Long> frequency = numbers.stream()
                .collect(Collectors.groupingBy(
                    n -> n,
                    Collectors.counting()
                ));

        // Filter to keep only elements that appear exactly once, preserving order
        return numbers.stream()
                .filter(n -> frequency.get(n) == 1)
                .collect(Collectors.toList());
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flipCase("Hello")
    "hELLO"
     */
    public String flipCase(String string) {
        if (string == null) {
            return null;
        }

        StringBuilder result = new StringBuilder(string.length());

        for (int i = 0; i < string.length(); i++) {
            char c = string.charAt(i);
            if (Character.isLowerCase(c)) {
                result.append(Character.toUpperCase(c));
            } else if (Character.isUpperCase(c)) {
                result.append(Character.toLowerCase(c));
            } else {
                result.append(c);
            }
        }

        return result.toString();
    }
}

